# Task IDs (from bl60x_fw_api.h)
# =============================================================================
const
  TASK_NONE* = 0xFF'u8
  TASK_MM*   = 0'u8
  TASK_SCAN* = 1'u8
  TASK_SCANU* = 2'u8
