  TASK_SM*   = 4'u8
  TASK_APM*  = 5'u8
  TASK_BAM*  = 6'u8
  TASK_RXU*  = 7'u8
  TASK_CFG*  = 8'u8
  TASK_LAST_EMB* = TASK_CFG
  TASK_API*  = 9'u8
  TASK_MAX*  = 10'u8

template KE_FIRST_MSG(task: uint16): uint16 = (task shl 10)

