  let dsIe2 = mac_ie_find(ieStart, ieLen, IE_ID_DS_PARAM)
  if dsIe2 != nil:
    let dd = cast[ptr UncheckedArray[uint8]](dsIe2)
    let freq = phy_channel_to_freq(fb[6], dd[2])
    entry.chanPtr = me_freq_to_chan_ptr(fb[6], freq)
    let r = cast[int8](fb[24])
    if entry.rssi < r: entry.rssi = r
  else:
    let r = cast[int8](fb[24])
    if entry.rssi < r:
      entry.chanPtr = me_freq_to_chan_ptr(fb[6], cast[ptr uint16](cast[uint](frame)+4)[])
      entry.rssi = r

  # SSID filter loop
  let numSsids = spb[308]
  var ssidOk = (numSsids == 0)
  if numSsids > 0:
    var idx = 0
    var base = cast[uint](scanParam) + 253
    while idx < numSsids.int:
      let fL = cast[ptr uint8](base-1)[]
      if fL != 0:
        if fL == ssidBuf[0] and c_memcmp(cast[pointer](base), addr ssidBuf[1], fL.csize_t) == 0:
          ssidOk = true; break
      else:
