      let smP = cast[ptr pointer](addr sm_env[0])[]
      let smB = cast[ptr UncheckedArray[uint8]](smP)
      let smF = cast[ptr uint32](cast[uint](smP)+48)[]
      let vSR = cast[uint](vif) + 348
      let vRO = cast[pointer](cast[uint](vif)+436)

      cast[ptr uint16](cast[uint](vif)+420)[] = entry.band
      discard c_memcpy(cast[pointer](cast[uint](vif)+380), addr entry.bssid[0], 6)
      discard c_memcpy(cast[pointer](cast[uint](vif)+386), addr ssidBuf[0], 34)
      cast[ptr uint16](cast[uint](vif)+434)[] = entry.capInfo
      cast[ptr uint16](cast[uint](vif)+432)[] = entry.beaconPeriod
      cast[ptr pointer](cast[uint](vif)+424)[] = entry.chanPtr
      cast[ptr uint32](cast[uint](vif)+484)[] = 0
      cast[ptr int8](cast[uint](vif)+473)[] = entry.noiseFloor1
      cast[ptr int8](cast[uint](vif)+474)[] = entry.noiseFloor2

