        let hcIe = mac_ie_find(ieStart, ieLen, IE_ID_HT_CAP)
        if hcIe != nil:
          let hc = cast[ptr UncheckedArray[uint8]](hcIe)
          cast[ptr uint16](cast[uint](vif)+348)[] = hc[2].uint16 or (hc[3].uint16 shl 8)
          cast[ptr uint8](cast[uint](vif)+350)[] = hc[4]
          for mi in 0'u8 ..< 16: cast[ptr uint8](cast[uint](vif)+351+mi.uint)[] = hc[5+mi]
          cast[ptr uint16](cast[uint](vif)+368)[] = hc[21].uint16 or (hc[22].uint16 shl 8)
          cast[ptr uint32](cast[uint](vif)+372)[] = (hc[23].uint16 or (hc[24].uint16 shl 8)).uint32
          cast[ptr uint8](cast[uint](vif)+376)[] = hc[27]
          cast[ptr uint32](cast[uint](vif)+484)[] = cast[ptr uint32](cast[uint](vif)+484)[] or 2

