            let pf = cast[ptr UncheckedArray[pointer]](wpa_cbs)[12]
            if pf != nil:
              discard cast[proc(a:pointer,b:uint8,c:pointer):pointer{.cdecl.}](pf)(lW, wd[1]+2, addr lS[0])
        cast[ptr uint8](cast[uint](vif)+497)[] = sT
