        if (smF and 0x600) != 0:
          if (lf and 0x400) != 0: aT = 1024
          elif (lf and 0x100) != 0: aT = 256
        else:
          if (lf and 0x100) != 0: aT = 256
          elif (lf and 2) == 0: aT = 0
        if aT != 0:
          cast[ptr uint8](cast[uint](vif)+498)[] = lS[4]
          cast[ptr uint8](cast[uint](vif)+499)[] = lS[8]
          cast[ptr uint8](cast[uint](vif)+500)[] = lS[12]
          cast[ptr uint32](cast[uint](vif)+504)[] = aT
          if (lS[16] and 0x80) != 0:
            cast[ptr uint8](cast[uint](vif)+508)[] = 1
            if (lS[16] and 0x40) != 0 or aT == 1024:
