              cast[ptr uint8](cast[uint](vif)+500)[] = 6
          if aT == 1024: cast[ptr uint8](cast[uint](vif)+497)[] = 4
          let stF = cast[ptr uint8](cast[uint](vif)+497)[]
          if stF >= 2 and stF <= 4:
