              let copyLen = if secLenRaw > 128'u: 128'u else: secLenRaw
              let slot = if vB[87].int < MAX_VIFS: vB[87].int else: 0
              discard c_memcpy(addr assocSecIeStore[slot][0], srcSecIe, copyLen.csize_t)
              cast[ptr pointer](cast[uint](vif) + 492)[] = addr assocSecIeStore[slot][0]
              cast[ptr uint8](cast[uint](vif) + 496)[] = copyLen.uint8
