            nb[0] = vB[87]
            discard c_memcpy(addr nb[2], cast[pointer](cast[uint](vif)+80), 6)
            discard c_memcpy(addr nb[8], cast[pointer](cast[uint](vif)+380), 6)
            nb[52] = stF
            cast[ptr uint16](addr nb[54])[] = aT.uint16
            cast[ptr uint16](addr nb[56])[] = cast[ptr uint16](cast[uint](vif)+498)[]
