      var wb {.noinit.}: array[140, uint8]
      discard c_memset(addr wb[0], 0, 28)
      cast[ptr pointer](addr wb[0])[] = result
      cast[ptr pointer](addr wb[8])[] = cast[pointer](addr ssidBuf[1])
      wb[12] = ssidBuf[0]
      cast[ptr uint16](addr wb[6])[] = entry.capInfo
      cast[ptr pointer](addr wb[24])[] = wIe
