proc scanu_search_by_bssid*(bssid: pointer): pointer {.exportc, cdecl, noinline.} =
  return scanu_find_result(bssid, 0)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void* scanu_search_by_ssid(void*,void*);".}
proc scanu_search_by_ssid*(ssid: pointer, entryIndexOut: pointer): pointer {.exportc, cdecl.} =
  ## Search scan results by SSID (103 instrs).
  ## ssid = pointer to SSID string (first byte = SSID length, rest = SSID data).
  ## entryIndexOut receives the selected result index; blob reads length from ssid[0].
  ## Returns pointer to matching scan result entry, or nil if not found.
  ##
  ## Assembly trace:
  ##   s2 = scanu_env.entries[48] (result filter state at offset 48 in scanu_env)
  ##   s6 = initial filter flag (0 or non-zero from s2)
  ##   s7 = ssid pointer
  ##   Builds search key: ssid[0]+1 bytes starting from ssid, masks with 0xFF00FF
  ##   Loops over SCANU_MAX_RESULT_ENTRIES (6), for each:
  ##     checks entry.valid (offset 20 from entry base)
  ##     if s6 (filter): checks channel info mask against 0xFF00FF pattern
  ##     compares entry RSSI (offset 21) against -128
  ##     compares entry SSID (at entry+188...) against search SSID
  ##     if match: stores result index, records best entry
  ##   Returns pointer to best matching entry or nil.
  let scanuBase = cast[uint](addr scanu_env)
  let ssidPtr = cast[ptr UncheckedArray[uint8]](ssid)
  # Read the SSID: first byte is length
  let searchLen = ssidPtr[0]
  when defined(bl808WifiNimFw):
    let searchWord = ssidPtr[1].uint32 or (ssidPtr[2].uint32 shl 8) or
      (ssidPtr[3].uint32 shl 16) or (ssidPtr[4].uint32 shl 24)
    nimFwTrace2U32("[WIFI-NIMFW] ssid_s ", searchLen.uint32, searchWord)
  if searchLen == 0:
    return nil
  # Build search key (ssid+1 is the actual SSID data, length = searchLen)
  let searchData = cast[pointer](cast[uint](ssid) + 1)
  # The blob can apply an optional channel filter here. Keep it disabled for
  # the normal station-connect scan path; the cached scan entries already
  # carry the channel pointer used by sm_get_bss_params.
  let filterState = 0'u32
  var bestEntry: pointer = nil
  var bestRssi: int8 = -128
  let entryBase = cast[uint](addr scanu_env.entries[0])
  # Actually, scanu_env layout: paramPtr(4) + entries[6](28 each) + ...
  # Entry size in scanu_env = sizeof(ScanuResultEntry) = 28 bytes
  for i in 0'u8 ..< SCANU_MAX_RESULT_ENTRIES.uint8:
    let entryAddr = entryBase + i.uint * 28
    # Check valid flag (offset 16 in entry)
    let valid = cast[ptr uint8](entryAddr + 16)[]
    when defined(bl808WifiNimFw):
      let rawDbg = cast[ptr uint32](entryAddr + 24)[]
      nimFwTrace2U32("[WIFI-NIMFW] ssid_i ", i.uint32 or (valid.uint32 shl 8), rawDbg)
    if valid == 0:
      continue
    # If filter active, check channel info pattern
    if filterState != 0:
      let chanInfo = cast[ptr uint32](entryAddr + 24)[]
      if (chanInfo and 0x00FF00FF'u32) == 0:
        continue
    # Check RSSI threshold (offset 17 = rssi, signed byte)
    let rssi = cast[ptr int8](entryAddr + 17)[]
    if rssi < -128'i8:
      continue
    # Compare SSID: each entry has a rawMsgPtr (offset 24) pointing to the
    # beacon/probe response. The SSID IE is at a known offset in the raw frame.
    # Blob: reads entry.rawMsgPtr, finds SSID IE (id=0), compares length+data.
    let rawMsgPtr = cast[ptr pointer](entryAddr + 24)[]
    if rawMsgPtr == nil:
      when defined(bl808WifiNimFw):
        nimFwTrace2U32("[WIFI-NIMFW] ssid_raw0 ", i.uint32, entryAddr.uint32)
      continue
    # Find SSID IE in the cached RXU_MGT_IND payload. The RXU header is 32
    # bytes, followed by the MAC header (24) and beacon fixed fields (12).
    let rawAddr = cast[uint](rawMsgPtr)
    let totalLen = cast[ptr uint16](rawAddr)[]
    let ieLen = if totalLen > 36'u16: totalLen.uint32 - 36'u32 else: 0'u32
    let ssidIe = mac_ie_find(cast[pointer](rawAddr + 68), ieLen, IE_ID_SSID)
    if ssidIe == nil:
      continue
    let ssidIeAddr = cast[uint](ssidIe)
    let entrySsidLen = cast[ptr uint8](ssidIeAddr + 1)[]
    when defined(bl808WifiNimFw):
      let entryWord = cast[ptr uint8](ssidIeAddr + 2)[].uint32 or
        (cast[ptr uint8](ssidIeAddr + 3)[].uint32 shl 8) or
        (cast[ptr uint8](ssidIeAddr + 4)[].uint32 shl 16) or
        (cast[ptr uint8](ssidIeAddr + 5)[].uint32 shl 24)
      let entryMeta = i.uint32 or (valid.uint32 shl 8) or
        (entrySsidLen.uint32 shl 16) or (rssi.uint8.uint32 shl 24)
      nimFwTrace2U32("[WIFI-NIMFW] ssid_e ", entryMeta, entryWord)
    if entrySsidLen != searchLen:
      continue
    if searchLen > 0:
      let cmpResult = c_memcmp(searchData,
                               cast[pointer](ssidIeAddr + 2),
                               searchLen.csize_t)
      if cmpResult != 0:
        when defined(bl808WifiNimFw):
          nimFwTrace2U32("[WIFI-NIMFW] ssid_cmp ", i.uint32, cast[uint32](cmpResult))
        continue
    when defined(bl808WifiNimFw):
      nimFwTrace2U32("[WIFI-NIMFW] ssid_hit ", i.uint32, rssi.uint8.uint32)
    # Match found: log via g_bl_ops_funcs[204]
    let logFnMatch = getLogFunc(204)
    if logFnMatch != nil:
      logFnMatch(2, 0, nil, 1010, cast[uint32](i), cast[uint32](rssi))
    if entryIndexOut != nil:
      cast[ptr uint32](entryIndexOut)[] = i.uint32
    # Track best RSSI
    if rssi > bestRssi:
      bestRssi = rssi
      bestEntry = cast[pointer](entryAddr)
  # Blob does NOT have a second fallback loop without filter — the single
  # loop above is the entire scan. Previous Nim added a redundant second
  # pass that matched blob's behavior nowhere.
  return bestEntry

proc scanu_rm_exist_ssid*(ssid: pointer, ssidLen: uint8) {.exportc, cdecl.} =
  ## Remove an existing scan result entry if its SSID matches (76 instrs in blob).
  ## a0=ssid (length-prefixed: ssid[0]=len, ssid[1..]=data), a1=entryIndex (signed).
  ## Blob flow:
  ##   1. Log at line 1032 (entry)
  ##   2. If entryIndex < 0 or ssid == nil, return
  ##   3. Compute entry offset = entryIndex * 28, check entries[idx].valid
  ##   4. Compare scanu_env.filterSsidLen with ssid[0]; if mismatch, skip
  ##   5. memcmp(scanu_env.filterSsid, ssid+1, len); if mismatch, skip
  ##   6. On match: log at line 1043, memset(entry, 0, 28) to clear it
  ##   7. Log at line 1046, return
  let logFn = getLogFunc(4)

  # Log entry
  if logFn != nil:
    logFn(2, 0, nil, 1032)

  # Validate inputs (blob: bltz s0 / beqz s3)
  let entryIdx = cast[int8](ssidLen)
  if entryIdx < 0:
    return
  if ssid == nil:
    return

  let scanEnvBase = cast[uint](addr scanu_env)
  # Entries start at paramPtr(4) offset in scanu_env
  let entriesBase = scanEnvBase + 4  # offset of entries array
  let entryOffset = entryIdx.uint * 28

  # Check entry validity (valid field at offset 20 within entry)
  let validByte = cast[ptr uint8](entriesBase + entryOffset + 20)[]
  if validByte == 0:
    return

  # Compare SSID length: scanu_env.filterSsidLen (offset 188 from scanEnvBase)
  let filterSsidLen = cast[ptr uint8](scanEnvBase + 188)[]
  let ssidArr = cast[ptr UncheckedArray[uint8]](ssid)
  let inputSsidLen = ssidArr[0]

  if inputSsidLen != filterSsidLen:
    # Mismatch, log and return
    if logFn != nil:
      logFn(2, 0, nil, 1046)
    return

  # Compare SSID data: scanu_env.filterSsid (offset 189) vs ssid+1
  let filterSsidPtr = cast[pointer](scanEnvBase + 189)
  let inputSsidPtr = cast[pointer](cast[uint](ssid) + 1)
  let cmpResult = c_memcmp(filterSsidPtr, inputSsidPtr, inputSsidLen.csize_t)

  if cmpResult != 0:
    # Mismatch
    if logFn != nil:
      logFn(2, 0, nil, 1046)
    return

  # Match found: log and clear the entry
  if logFn != nil:
    logFn(2, 0, nil, 1043)

  # Clear entry: memset(entriesBase + entryOffset, 0, 28)
  discard c_memset(cast[pointer](entriesBase + entryOffset), 0, 28.csize_t)

  # Log exit
  if logFn != nil:
    logFn(2, 0, nil, 1046)

proc scanu_cached_scanresult_clear*() {.exportc, cdecl.} =
  ## Clear all cached scan results in scanu_env.
  for i in 0 ..< SCANU_MAX_RESULT_ENTRIES:
    let e = addr scanu_env.entries[i]
    e.valid = 0
    e.rssi = -128'i8
    if e.rawMsgPtr != nil:
      ke_msg_free(e.rawMsgPtr)
      e.rawMsgPtr = nil

proc scanu_dump_scanresult*() {.exportc, cdecl.} =
  ## Dump scan results for debugging.
  discard

proc scanu_raw_send_cfm*(result: pointer, destId: uint8) {.exportc, cdecl.} =
  ## Send raw frame send confirmation (16 instrs in blob).
  ## Signature: scanu_raw_send_cfm(result_ptr, dest_id). dest_id comes from
  ## the original request's srcId (blob passes a1 = saved_a3). For the
  ## synchronous call in scanu_raw_send_req_handler, result == nil.
  let msg = ke_msg_alloc(SCANU_RAW_SEND_CFM, destId, TASK_SCANU, 4)
  if msg != nil:
    cast[ptr pointer](msg)[] = result
    ke_msg_send(msg)

# ###########################################################################
#                   SM: Station State Machine
# ###########################################################################

proc sm_init*() {.exportc, cdecl.} =
  ## Initialize SM module.
  smConnecting = false
  smAuthRetryLimit = 4
  smReconnectTrigger = false
  let smBase = cast[uint](addr sm_env[0])
  cast[ptr pointer](smBase)[] = nil
  cast[ptr uint8](smBase + 17)[] = 1
  cast[ptr uint32](smBase + 24)[] = 4
  ke_state_set(TASK_SM, 0)

proc sm_get_bss_params*(resultOut: ptr pointer, chanPtrOut: ptr pointer): bool {.exportc, cdecl.} =
  ## Get BSS parameters from scan results.
  ## From blob (111 instrs): loads sm_env[0] connect info, searches scanu results
  ## by BSSID/SSID, fills resultOut with scan result ptr and chanPtrOut with
  ## channel frequency pointer. Returns true if found.
  let smBase = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smBase)[]
  if connInfo == nil: return false
  let blOpsBase = cast[uint](addr g_bl_ops_funcs)
  let logFn = cast[ptr pointer](blOpsBase + 4)[]

  # Initialize outputs to nil/zero
  resultOut[] = nil
  chanPtrOut[] = nil

  # connInfo layout: offset 34 = BSSID (6 bytes), offset 1 = SSID data, offset 0 = SSID len
  let connInfoU = cast[uint](connInfo)
  let bssidPtr = cast[pointer](connInfoU + 34)

  # Log the BSSID we're searching for (3 iterations logging pairs)
  if logFn != nil:
    for i in 0'u32 ..< 3'u32:
      let bssidByte = cast[ptr uint8](connInfoU + 34 + i.uint * 2)[]
      cast[proc(a0: pointer, a1: uint32){.cdecl.}](logFn)(nil, bssidByte.uint32)

  # Check if BSSID is set (not all zeros and not starting with bit 0 set)
  let b0 = cast[ptr uint8](connInfoU + 34)[]
  var searchBySsid = false
  if (b0 and 1) != 0:
    # BSSID has group bit set -- search by SSID instead
    searchBySsid = true
  else:
    var allZero = true
    for i in 0 ..< 6:
      if cast[ptr uint8](connInfoU + 34 + i.uint)[] != 0:
        allZero = false
        break
    if allZero:
      searchBySsid = true
    else:
      # Search by BSSID
      if logFn != nil:
        let ssidPtr = cast[pointer](connInfoU + 1)
        cast[proc(a0: pointer, a1: pointer){.cdecl.}](logFn)(nil, ssidPtr)

      # Call scanu_search_by_bssid (blob's 2-instr trampoline that
      # tail-calls scanu_find_result(bssid, 0)). Matching the blob call
      # here keeps the call graph parity intact.
      resultOut[] = bssidPtr
      let scanResult = scanu_search_by_bssid(bssidPtr)

      if logFn != nil:
        cast[proc(a0: pointer, a1: int32){.cdecl.}](logFn)(nil, (-1'i32))

      if scanResult != nil:
        # Get channel pointer from scan result offset 8
        let chanPtr = cast[ptr pointer](cast[uint](scanResult) + 8)[]
        chanPtrOut[] = chanPtr

        # Log and return
        if logFn != nil:
          cast[proc(a0: pointer){.cdecl.}](logFn)(nil)
        return true

      # Check if connect info has a frequency hint at offset 40
      let freqHint = cast[ptr uint16](connInfoU + 40)[]
      if freqHint != 0xFFFF'u16:
        chanPtrOut[] = cast[pointer](connInfoU + 40)

  if searchBySsid:
    # BSSID not specified -- search by SSID.
    if logFn != nil:
      cast[proc(a0: pointer){.cdecl.}](logFn)(nil)

    var resultIndex: int32 = -1
    let ssidResult = scanu_search_by_ssid(connInfo, cast[pointer](addr resultIndex))
    if ssidResult != nil:
      if resultIndex >= 0:
        resultOut[] = ssidResult
        cast[ptr uint32](smBase + 28)[] = resultIndex.uint32
      let chanPtr = cast[ptr pointer](cast[uint](ssidResult) + 8)[]
      chanPtrOut[] = chanPtr
    else:
      # Check if connect info has a frequency hint at offset 40
      let freqHint = cast[ptr uint16](connInfoU + 40)[]
      if freqHint != 0xFFFF'u16:
        chanPtrOut[] = cast[pointer](connInfoU + 40)

  if chanPtrOut[] == nil:
    let freqHint = cast[ptr uint16](connInfoU + 40)[]
    if freqHint != 0xFFFF'u16:
      chanPtrOut[] = cast[pointer](connInfoU + 40)

  # Final log
  if logFn != nil:
    cast[proc(a0: pointer){.cdecl.}](logFn)(nil)
  return resultOut[] != nil

proc sm_scan_bss*(bssid: pointer, ssid: pointer, chanInfo: pointer) {.exportc, cdecl.} =
  ## Initiate a BSS scan for connection.
  ## From blob (92 instrs): loads sm_env[0] (connect info), allocates SCANU_START_REQ
  ## message (320 bytes), populates scan parameters, initiates scan via ke_state_set.
  ##
  ## Register map: s0=msg, s1=connInfo, s2=chanInfo,
  ##   s3=target BSSID filter, s4=local VIF MAC
  let smEnvBase = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smEnvBase)[]
  let connU = cast[uint](connInfo)

  # Allocate SCANU_START_REQ message: ke_msg_alloc(0x800, 2, 4, 320)
  let msg = ke_msg_alloc(SCANU_START_REQ, TASK_SCANU, TASK_SM, 320)
  let m = cast[uint](msg)

  # Read vifIdx from connInfo+59
  let vifIdx = cast[ptr uint8](connU + 59)[]

  # Clear and populate scan request fields
  cast[ptr uint32](m + 300)[] = 0           # scan_result_ptr = 0
  cast[ptr uint8](m + 306)[] = vifIdx       # inst_nbr = vifIdx
  cast[ptr uint16](m + 304)[] = 0           # scan_count = 0

  # Copy connect info (34 bytes starting from connInfo) into msg+252
  discard c_memcpy(cast[pointer](m + 252), connInfo, 34.csize_t)

  # Set active scan flag
  cast[ptr uint8](m + 308)[] = 1            # is_active_scan = 1

  # Copy target BSSID filter into msg+286. Nil means undirected.
  if ssid != nil:
    discard c_memcpy(cast[pointer](m + 286), ssid, 6.csize_t)
  else:
    discard c_memset(cast[pointer](m + 286), 0xFF, 6.csize_t)

  # Copy local VIF MAC into msg+292
  discard c_memcpy(cast[pointer](m + 292), bssid, 6.csize_t)

  # Store channel duration from connInfo+48
  let chanDuration = cast[ptr uint32](connU + 48)[]
  cast[ptr uint32](m + 312)[] = chanDuration

  # Handle channel info
  if chanInfo != nil:
    # Copy channel info (6 bytes) into msg
    discard c_memcpy(msg, chanInfo, 6.csize_t)
    cast[ptr uint8](m + 307)[] = 1          # has_channel_info = 1
  else:
    # No specific channel -- scan all channels from scanu_env
    let scanuBase = cast[uint](addr scanu_env)
    let numChan = cast[ptr uint8](scanuBase + 124)[]  # scanu_env channel count
    cast[ptr uint8](m + 307)[] = 0
    var chanIdx: int = 0
    var resultCount: uint8 = 0
    while chanIdx < numChan.int:
      # Skip channels with flag bit 1 set (DFS or excluded)
      let chanEntry = cast[ptr uint8](scanuBase + 43 + chanIdx.uint)[]
      if (chanEntry and 2) == 0:
        # Copy 6-byte channel entry into scan message channel list
        let src = cast[pointer](scanuBase + 40 + chanIdx.uint * 6)
        let off = resultCount.uint * 6
        discard c_memcpy(cast[pointer](m + off.uint), src, 6.csize_t)
        let prevCount = cast[ptr uint8](m + 307)[]
        cast[ptr uint8](m + 307)[] = prevCount + 1
        resultCount = resultCount + 1
      chanIdx += 1

  # Send the scan request and advance SM state
  ke_msg_send(msg)
  ke_state_set(TASK_SM, 1)

proc sm_join_bss*(bssid: pointer, ssid: pointer, joinInfo: pointer, flag: uint32) {.exportc, cdecl.} =
  ## Join a BSS (send join request to scan module).
  ## From blob (74 instrs): allocates SCANU_JOIN_REQ (320 bytes), populates join
  ## params from sm_env connect info, sends message and advances SM state.
  ##
  ## Register map: s0=msg, s1=connInfo, s2=sm_env_reloc, s3=flag, s4=1,
  ##   s5=bssid, s6=ssid
  let smEnvReloc = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smEnvReloc)[]
  let connU = cast[uint](connInfo)

  # Allocate SCANU_JOIN_REQ: ke_msg_alloc(0x802, 2, 4, 320)
  let msg = ke_msg_alloc(SCANU_JOIN_REQ, TASK_SCANU, TASK_SM, 320)
  let m = cast[uint](msg)

  # Copy join info (6 bytes) into msg payload start
  discard c_memcpy(msg, joinInfo, 6.csize_t)

  # Set join-specific flag
  cast[ptr uint8](m + 307)[] = 1            # has_join_info = 1

  # Copy connect info (34 bytes) into msg+252
  discard c_memcpy(cast[pointer](m + 252), connInfo, 34.csize_t)

  # Set active scan
  cast[ptr uint8](m + 308)[] = 1

  # Clear scan state fields
  cast[ptr uint16](m + 304)[] = 0           # scan_count = 0
  cast[ptr uint32](m + 300)[] = 0           # scan_result_ptr = 0

  # Read vifIdx from connInfo+59
  let vifIdx = cast[ptr uint8](connU + 59)[]

  # Copy SSID (6 bytes) into msg+286
  discard c_memcpy(cast[pointer](m + 286), ssid, 6.csize_t)

  cast[ptr uint8](m + 306)[] = vifIdx       # inst_nbr

  # Copy BSSID (6 bytes) into msg+292
  discard c_memcpy(cast[pointer](m + 292), bssid, 6.csize_t)

  # Store channel duration from connInfo+48
  let chanDuration = cast[ptr uint32](connU + 48)[]
  cast[ptr uint32](m + 312)[] = chanDuration

  # Set flag in message byte 3 if flag arg is nonzero
  if flag != 0:
    let b3 = cast[ptr uint8](m + 3)[]
    cast[ptr uint8](m + 3)[] = b3 or 1

  # Store flag to sm_env offset 16
  cast[ptr uint8](smEnvReloc + 16)[] = flag.uint8

  # Send message
  ke_msg_send(msg)

  # Advance SM state: ke_state_set(TASK_SM, 2)
  ke_state_set(TASK_SM, 2)

proc sm_add_chan_ctx*(param: pointer): uint8 {.exportc, cdecl, discardable.} =
  ## Add channel context for the target BSS (27 instrs). Returns chan_ctxt_add's
  ## status (non-zero = failure, matching blob).
  let connInfo = cast[ptr pointer](addr sm_env[0])[]
  let connU = cast[uint](connInfo)
  let staIdx = cast[ptr uint8](connU + 59)[]
  let vifEntry = cast[uint](addr vif_info_tab[0]) + staIdx.uint * VIF_ENTRY_SIZE.uint
  let chanDef = cast[ptr pointer](vifEntry + 424)[]
  let cdU = cast[uint](chanDef)
  var chanReq {.noinit.}: array[16, uint8]
  chanReq[0] = cast[ptr uint8](cdU + 2)[]         # band
  chanReq[1] = cast[ptr uint8](connU + 479)[]      # bw
  cast[ptr uint16](addr chanReq[2])[] = cast[ptr uint16](cdU)[]  # primFreq
  cast[ptr pointer](addr chanReq[4])[] = cast[ptr pointer](vifEntry + 428)[]  # freqPtr
  chanReq[8] = cast[ptr uint8](cdU + 4)[]          # txPow
  return chan_ctxt_add(cast[pointer](addr chanReq[0]), cast[ptr uint8](param))

proc sm_send_next_bss_param*(param: pointer) {.exportc, cdecl.} =
  ## Pop the next prepared BSS-parameter message from the sm_env+8 queue and
  ## send it. Matches blob: co_list_pop_front + ke_msg_send (tail call).
  ## If queue unexpectedly empty, asserts (sm.c:600).
  let smListPtr = cast[ptr CoList](cast[uint](addr sm_env[0]) + 8)
  let node = co_list_pop_front(smListPtr)
  if node == nil:
    assert_err("sm.c", "sm.c", 600)
    return
  # node is a CoListHdr embedded at start of the ke_msg header; the message
  # payload passed to ke_msg_send sits 12 bytes past it.
  let msgPayload = cast[pointer](cast[uint](node) + 12)
  ke_msg_send(msgPayload)

proc sm_set_bss_param*(param: pointer) {.exportc, cdecl.} =
  ## Set BSS parameters for association.
  ## Blob structure (166 instrs): allocates all MM config messages up front,
  ## initializes a local message queue at sm_env+8 with co_list_init, then
  ## pushes each prepared ke_msg onto that queue via co_list_push_back. The
  ## actual sends are dispatched later by sm_send_next_bss_param which pops
  ## from the queue. Call sequence:
  ##   ke_msg_alloc x5, co_list_init(sm_env+8),
  ##   co_list_push_back x2 (PS_DISABLE, BSSID+memcpy),
  ##   me_legacy_rate_bitfield_build, co_list_push_back x2 (RATES, BCN_INT),
  ##   ke_msg_alloc (EDCA loop), co_list_push_back (EDCA),
  ##   co_list_push_back (VIF_STATE), sm_send_next_bss_param, ke_state_set.
  let smEnvBase = cast[uint](addr sm_env[0])
  let vifIdx = cast[ptr uint8](smEnvBase + 59)[]
  let vifBase = cast[uint](addr vif_info_tab[0]) + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let smListPtr = cast[ptr CoList](smEnvBase + 8)

  template pushMsg(msg: pointer) =
    ## Push an allocated ke_msg onto sm_env+8 queue (blob: co_list_push_back
    ## with msg - 12 = &ke_msg.hdr).
    let msgHdr = cast[ptr CoListHdr](cast[uint](msg) - 12)
    co_list_push_back(smListPtr, msgHdr)

  # Allocate all 5 up-front messages (blob 0x2c..0x76)
  let msgPs     = ke_msg_alloc(ME_SET_PS_DISABLE_REQ,  TASK_ME, TASK_SM, 2)
  let msgBssid  = ke_msg_alloc(MM_SET_BSSID_REQ,        TASK_MM, TASK_SM, 7)
  let msgRates  = ke_msg_alloc(MM_SET_BASIC_RATES_REQ,  TASK_MM, TASK_SM, 8)
  let msgBcn    = ke_msg_alloc(MM_SET_BEACON_INT_REQ,   TASK_MM, TASK_SM, 4)
  let msgActive = ke_msg_alloc(ME_SET_ACTIVE_REQ,       TASK_ME, TASK_SM, 2)

  # Initialize the queue (blob 0x88)
  co_list_init(smListPtr)

  # 1. ME_SET_PS_DISABLE_REQ (blob 0x90..0xAA)
  if msgPs != nil:
    let p = cast[ptr UncheckedArray[uint8]](msgPs)
    p[0] = 1; p[1] = vifIdx
    pushMsg(msgPs)

  # 2. MM_SET_BSSID_REQ: memcpy BSSID from VIF+380 (blob 0xCE), then push (0xEA)
  if msgBssid != nil:
    discard c_memcpy(msgBssid, cast[pointer](vifBase + 380), 6)
    cast[ptr UncheckedArray[uint8]](msgBssid)[6] = vifIdx
    pushMsg(msgBssid)

  # 3. MM_SET_BASIC_RATES_REQ: rate bitfield (blob 0x10A), push (0x12A)
  let rateBitfield = me_legacy_rate_bitfield_build(cast[pointer](vifBase + 436), 1)
  if msgRates != nil:
    let p = cast[ptr UncheckedArray[uint8]](msgRates)
    let chanPtr = cast[ptr pointer](vifBase + 424)[]
    if chanPtr != nil:
      p[5] = cast[ptr UncheckedArray[uint8]](chanPtr)[2]
    cast[ptr uint32](msgRates)[] = rateBitfield
    p[4] = vifIdx
    pushMsg(msgRates)

  # 4. MM_SET_BEACON_INT_REQ (blob push at 0x152)
  if msgBcn != nil:
    cast[ptr uint16](msgBcn)[] = cast[ptr uint16](vifBase + 432)[]
    cast[ptr UncheckedArray[uint8]](msgBcn)[2] = vifIdx
    pushMsg(msgBcn)

  # 5. 4x MM_SET_EDCA_REQ per AC (blob 0x17A alloc, 0x1BC push). These are
  # pushed BEFORE the ME_SET_ACTIVE_REQ because the blob emits the active
  # msg last to ensure ME activation fires after the ACs are programmed.
  for ac in 0'u8 ..< 4'u8:
    let msg = ke_msg_alloc(MM_SET_EDCA_REQ, TASK_MM, TASK_SM, 8)
    if msg != nil:
      let p = cast[ptr UncheckedArray[uint8]](msg)
      cast[ptr uint32](msg)[] = cast[ptr uint32](vifBase + 456 + ac.uint * 32)[]
      p[5] = ac
      var psFlag: uint8 = 0
      if cast[ptr uint32](cast[uint](addr chan_env[0]) + 32)[] != 0:
        if cast[ptr int8](vifBase + 452)[] < 0:
          if ((1'u8 shl ac) and cast[ptr uint8](smEnvBase + 58)[]) != 0:
            psFlag = 1
      p[4] = psFlag; p[6] = vifIdx
      pushMsg(msg)

  # 6. ME_SET_ACTIVE_REQ at the tail (blob push at 0x1E6). Previous Nim
  # pushed msgActive above AND allocated a separate MM_SET_VIF_STATE_REQ
  # at the end — blob issues only ME_SET_ACTIVE_REQ here and never a
  # dedicated VIF-state message. The ME activation ripples into the MM
  # state transition downstream.
  if msgActive != nil:
    let p = cast[ptr UncheckedArray[uint8]](msgActive)
    p[0] = 1; p[1] = vifIdx
    pushMsg(msgActive)

  # 8. Advance state, then dispatch the queue. The confirmation handlers
  # require state 4 before the first queued request can complete.
  ke_state_set(TASK_SM, 4)
  sm_send_next_bss_param(param)

proc sm_handle_connection*(vifIdxOrFlag: uint32, status: uint32,
    callbackCtx: pointer, failureFn: pointer) {.exportc, cdecl.} =
  ## Handle connection state change — send deauthentication frame (434 bytes in blob).
  ## Blob call sequence: ke_state_set(SM,10), txl_frame_get(0x200),
  ##   tpc_update_frame_tx_power, memcpy x3 (DA/SA/BSSID), txl_get_seq_ctrl,
  ##   mfp_protect_mgmt_frame, txu_cntrl_protect_mgmt_frame (conditional),
  ##   me_build_deauthenticate(bodyStart, 3), mfp_add_mgmt_mic (conditional),
  ##   txl_frame_push(frame, 3). On fail: failureFn(vifEntry, status, 3).
  let vifTab = cast[uint](addr vif_info_tab[0])
  let vifIdx = vifIdxOrFlag.uint8
  let vifEntry = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint

  # Early exit if VIF byte at +86 is non-zero (blob: lbu a5,86(s3); bnez)
  let vifFlag = cast[ptr uint8](vifEntry + 86)[]
  if vifFlag != 0:
    return

  # Save staIdx from VIF before frame alloc (blob: lbu s8,96(s3))
  let staIdx = cast[ptr uint8](vifEntry + 96)[]

  # Set SM state to disconnecting (blob: ke_state_set(4, 10))
  ke_state_set(TASK_SM, 10)

  # Allocate TX frame (blob: txl_frame_get(0x200) = li a0,512)
  let frame = txl_frame_get(512)
  if frame == nil:
    # Failure: tail-call failureFn(vifEntry, status, 3)
    if failureFn != nil:
      cast[proc(a: pointer, b: uint32, c: uint32){.cdecl.}](failureFn)(
        cast[pointer](vifEntry), status, 3)
    return

  let f = cast[uint](frame)

  # Update TX power (blob: tpc_update_frame_tx_power(vifEntry, frame))
  tpc_update_frame_tx_power(cast[pointer](vifEntry), frame)

  # Get MAC header from frame (blob: lw s1,108(s0) -> macHdr = frame[108])
  let macHdr = cast[ptr uint](f + 108)[]
  let staTab = cast[uint](addr sta_info_tab[0])
  let staEntry = staTab + staIdx.uint * 368

  # Set frame control byte (blob: li a5,-64 = 0xC0; sb a5,348(s1))
  cast[ptr uint8](macHdr + 0)[] = 0xC0'u8
  cast[ptr uint8](macHdr + 1)[] = 0
  cast[ptr uint8](macHdr + 2)[] = 0
  cast[ptr uint8](macHdr + 3)[] = 0

  # DA from sta_info_tab+4 (blob: memcpy at 0x94, src=s2+4=sta_info_tab+4)
  discard c_memcpy(cast[pointer](macHdr + 4), cast[pointer](staEntry + 4), 6.csize_t)
  # SA from vifEntry+80 (blob: memcpy at 0xA6, src=s3+80)
  discard c_memcpy(cast[pointer](macHdr + 10), cast[pointer](vifEntry + 80), 6.csize_t)
  # BSSID from sta_info_tab+4 (blob: memcpy at 0xB6, src=s2=sta_info_tab+4)
  discard c_memcpy(cast[pointer](macHdr + 16), cast[pointer](staEntry + 4), 6.csize_t)

  # Get sequence control (blob: txl_get_seq_ctrl at 0xBE)
  let seqCtrl = txl_get_seq_ctrl()
  cast[ptr uint8](macHdr + 22)[] = cast[uint8](seqCtrl and 0xFF)
  cast[ptr uint8](macHdr + 23)[] = cast[uint8](seqCtrl shr 8)

  # Store callback/ctx at frame+208/212 (blob: sw s6,208(s0); sw s3,212(s0))
  cast[ptr pointer](f + 208)[] = callbackCtx
  cast[ptr pointer](f + 212)[] = cast[pointer](vifEntry)
  # Store VIF/STA info (blob: sb s7,47(s0); sb zero,98,100; sb a5,49(s0))
  cast[ptr uint8](f + 47)[] = vifIdx
  cast[ptr uint8](f + 98)[] = 0
  cast[ptr uint8](f + 100)[] = 0
  cast[ptr uint8](f + 49)[] = staIdx

  # MFP protection (blob: mfp_protect_mgmt_frame at 0xFE)
  # Reads FC bytes from macHdr+0/+1, passes as (lo | hi<<8)
  let fcLo = cast[ptr uint8](macHdr + 1)[]
  let fcHi = cast[ptr uint8](macHdr + 0)[]
  let fc = (fcHi.uint16 shl 8) or fcLo.uint16
  let mfpResult = mfp_protect_mgmt_frame(frame, fc.uint32)

  # Track body start offset (macHdr + secHdrLen)
  var bodyOffset: uint = 24  # base MAC header size
  let macHdrPtr = cast[pointer](macHdr + 0)

  # Conditional: txu_cntrl_protect_mgmt_frame if mfp returned 1
  if mfpResult == 1:
    txu_cntrl_protect_mgmt_frame(frame, macHdrPtr, 24)
    # Read security header length added (blob: lbu s2,98(s0); addi s2,s2,24)
    bodyOffset = cast[ptr uint8](f + 98)[].uint + 24

  # Build deauthentication body (blob: me_build_deauthenticate(macHdr+bodyOffset, 3))
  let bodyStart = cast[pointer](macHdr + bodyOffset)
  let deauthLen = me_build_deauthenticate(bodyStart, 3)
  var totalLen = bodyOffset + deauthLen.uint

  # Conditional: mfp_add_mgmt_mic if mfp returned 2
  if mfpResult == 2:
    let micLen = mfp_add_mgmt_mic(frame, cast[uint32](totalLen),
      cast[uint32](totalLen))
    totalLen = totalLen + micLen.uint
  elif mfpResult == 1:
    # If mfp==1, check for CCMP/TKIP tail (blob: lbu a5,100(s0); add s2,s2,a5)
    let secTailLen = cast[ptr uint8](f + 100)[]
    totalLen = totalLen + secTailLen.uint

  # TX descriptor setup (blob: lw a4,112(s0); lw a5,20(a4); ...)
  let txDesc = cast[ptr uint](f + 112)[]
  if txDesc != 0:
    let payloadLen = cast[ptr uint32](txDesc + 20)[]
    cast[ptr uint32](txDesc + 24)[] = payloadLen - 1 + totalLen.uint32
    cast[ptr uint32](txDesc + 28)[] = totalLen.uint32 + 4

  # Push frame to TX queue (blob: txl_frame_push(frame, 3))
  txl_frame_push(frame, 3)

  # Completion: tail-call failureFn(vifEntry, status, 3)
  if failureFn != nil:
    cast[proc(a: pointer, b: uint32, c: uint32){.cdecl.}](failureFn)(
      cast[pointer](vifEntry), status, 3)

proc sm_disconnect_process*(param: pointer, statusCode: uint16 = 0, reasonCode: uint16 = 0) {.exportc, cdecl.} =
  ## Process a disconnect request (122 bytes in blob, 39 instrs).
  ## Blob: ke_msg_alloc, ke_timer_clear, clear smConnecting + sm_env[0],
  ## sm_delete_resources, populate msg, tail-call ke_msg_send.
  let msg = ke_msg_alloc(SM_DISCONNECT_IND, TASK_API, TASK_SM, 16)
  if msg == nil:
    return
  # Clear SM response timeout timer (blob: ke_timer_clear(0x1009, 4))
  let smTimerId = KE_FIRST_MSG(TASK_SM.uint16) + 9  # SM_RSP_TIMEOUT_IND
  ke_timer_clear(smTimerId, TASK_SM)
  smConnecting = false
  let smBase = cast[uint](addr sm_env[0])
  # Clean up SM resources before clearing sm_env[0]; sm_delete_resources reads
  # the active connection pointer from sm_env[0].
  sm_delete_resources()
  cast[ptr pointer](smBase)[] = nil
  let m = cast[uint](msg)
  cast[ptr uint16](m)[] = statusCode
  cast[ptr uint16](m + 2)[] = reasonCode
  if param != nil:
    cast[ptr uint8](m + 4)[] = cast[ptr uint8](cast[uint](param) + 87)[]
  ke_msg_send(msg)

proc sm_disconnect_deauth_cfm*(param: pointer) {.exportc, cdecl.} =
  ## Confirmation that deauth frame was sent during disconnect.
  ## From blob (5 instrs): li a2,3; li a1,19; jr sm_disconnect_process
  ## Tail-calls sm_disconnect_process(param, WLAN_FW_DISCONNECT_BY_USER_WITH_DEAUTH, 3).
  sm_disconnect_process(param, 19, 3)

proc sm_connect_ind*(statusCode: uint16, reasonCode: uint16) {.exportc, cdecl, noinline.} =
  ## Send connect indication to host.
  ## From blob (131 instrs): loads sm_env[0] and vif_info_tab to build a full
  ## SM_CONNECT_IND message with BSSID, aid, channel info, VHT capabilities,
  ## then sends to host. Also notifies the AP via chan_bcn_detect_start if needed.
  ##
  ## a0=statusCode(->s8), a1=reasonCode(->s9)
  let smEnvReloc = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smEnvReloc)[]
  let connU = cast[uint](connInfo)
  let vifTab = cast[uint](addr vif_info_tab[0])
  let blOps = cast[uint](addr g_bl_ops_funcs)

  # Get vifIdx from connInfo+59
  let vifIdx = cast[ptr uint8](connU + 59)[]
  let vifEntry = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint

  # Get sm_env secondary fields.
  # Blob re-uses the 860-byte message that sm_connect_req_handler parked at
  # sm_env[4] — it is NOT a fresh ke_msg_alloc here. Nim was allocating a
  # new buffer, which leaked the prior one AND sent an uninitialised msg
  # downstream. The blob's smEnvSecond pointer and the "msg" pointer are
  # the same object.
  let smEnvSecond = cast[ptr pointer](smEnvReloc + 4)[]
  let smEnvSecU = cast[uint](smEnvSecond)
  let msg = smEnvSecond
  if msg == nil:
    return
  let m = smEnvSecU
  let msgHdr = keMsgHdrFromPayload(msg)
  msgHdr.id = SM_CONNECT_IND_MSG
  msgHdr.destId = TASK_API
  msgHdr.srcId = TASK_SM

  # Fill vifIdx at msg+11
  cast[ptr uint8](m + 11)[] = vifIdx

  # Copy BSSID from vif_info_tab+380 (6 bytes) to msg+4
  let bssid = vifEntry + 380
  cast[ptr uint32](m + 4)[] = cast[ptr uint32](bssid)[]
  cast[ptr uint16](m + 8)[] = cast[ptr uint16](bssid + 4)[]

  # Copy AID from vif+96 to msg+12
  let aid = cast[ptr uint8](vifEntry + 96)[]
  cast[ptr uint8](m + 12)[] = aid

  # Copy channel info from vif+64 pointer
  let chanPtr = cast[ptr pointer](vifEntry + 64)[]
  if chanPtr != nil:
    # No channel info
    cast[ptr uint8](m + 13)[] = 0
  else:
    cast[ptr uint8](m + 13)[] = 0

  # Fill channel and VHT capability fields from chanPtr if available
  if chanPtr != nil:
    let cpU = cast[uint](chanPtr)
    cast[ptr uint8](m + 822)[] = cast[ptr uint8](cpU + 4)[]
    cast[ptr uint16](m + 824)[] = cast[ptr uint16](cpU + 6)[]
    cast[ptr uint32](m + 828)[] = cast[ptr uint16](cpU + 8)[].uint32
    cast[ptr uint32](m + 832)[] = cast[ptr uint16](cpU + 10)[].uint32
    cast[ptr uint8](m + 826)[] = cast[ptr uint8](cpU + 5)[]
    # Store freq info to sm_env secondary struct
    cast[ptr uint16](smEnvSecU + 32)[] = cast[ptr uint16](cpU + 6)[]
    cast[ptr uint16](smEnvSecU + 34)[] = cast[ptr uint16](cpU + 8)[]
  else:
    cast[ptr uint8](m + 822)[] = 0
    cast[ptr uint16](m + 824)[] = 0
    cast[ptr uint32](m + 828)[] = 0
    cast[ptr uint32](m + 832)[] = 0
    cast[ptr uint8](m + 826)[] = 0

  # Check if AP uses WMM (byte 14 of msg)
  let hasWmm = cast[ptr uint8](m + 14)[]
  var qosFlag: uint8 = 0
  if hasWmm != 0:
    # Check if peer VIF supports QoS
    let peerVifEntry = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint
    let qosCap = cast[ptr uint8](peerVifEntry + 453)[]
    qosFlag = qosCap

  cast[ptr uint8](m + 15)[] = qosFlag

  # Clear security status byte
  cast[ptr uint8](m + 10)[] = 0

  # Write status and reason code to message
  cast[ptr uint16](m + 0)[] = statusCode
  cast[ptr uint16](m + 2)[] = reasonCode

  # Blob state handling (offsets 0xda-0xf4, 0x14a-0x1a0):
  #   if statusCode == 0:  ke_state_set(TASK_SM, 0)       ; success -> idle
  #   else:                ke_state_set(TASK_SM, 10)      ; failure -> failed
  #                        (failure path also runs scanu_rm_exist_ssid etc.)
  # Then both paths fall through to ke_msg_free + ke_msg_send + sm_delete_resources.
  # There is NO second ke_state_set at the end.
  if statusCode == 0:
    ke_state_set(TASK_SM, 0)
  else:
    # Failure path (blob .L97 at 0x14a-0x1a0):
    #   ke_state_set(TASK_SM, 10)
    #   ... diagnostic logs ...
    #   if (sm_env[28] >= 0):
    #       scanu_rm_exist_ssid(connInfo /*s5*/, sm_env[28] /*s6*/)
    #       sm_env[28] = -1
    # Then falls through to L98 via unconditional jump.
    ke_state_set(TASK_SM, 10)
    let bssIdx = cast[ptr int32](smEnvReloc + 28)[]
    if bssIdx >= 0:
      scanu_rm_exist_ssid(connInfo, cast[uint8](bssIdx and 0xFF))
      cast[ptr int32](smEnvReloc + 28)[] = -1'i32

  # Blob: ke_msg_free(connInfoOld - 12). The blob subtracts 12 to reach the
  # ke_msg header from the stored payload pointer (sm_env[0] holds the payload).
  # Match the blob call site exactly by passing (payload - 12).
  let connInfoOld = cast[ptr pointer](smEnvReloc)[]
  if connInfoOld != nil:
    let hdrPtr = cast[pointer](cast[uint](connInfoOld) - 12'u)
    ke_msg_free(hdrPtr)
  cast[ptr pointer](smEnvReloc)[] = nil

  # Send message to host (blob: ke_msg_send at offset 0x10A)
  ke_msg_send(msg)

  # Clear secondary sm_env slot (blob: sm_env[4] = 0 at offset 0x116-0x11a)
  cast[ptr pointer](smEnvReloc + 4)[] = nil

  # Blob: sm_delete_resources — cleanup SM resources (offset 0x198, tail-call)
  sm_delete_resources()

proc sm_connect_abort_process*(param: pointer, statusCode: uint16 = 0, reasonCode: uint16 = 0) {.exportc, cdecl.} =
  ## Process a connect abort request.
  ## From blob (5 instrs): shuffles args (a0=a1, a1=a2) and tail-calls sm_connect_ind.
  sm_connect_ind(statusCode, reasonCode)

proc sm_connect_abort_deauth_cfm*(param: pointer) {.exportc, cdecl.} =
  ## Confirmation of deauth during connect abort.
  ## From blob (5 instrs): li a1,3; li a0,23; jr sm_connect_ind
  ## Tail-calls sm_connect_ind(WLAN_FW_CONNECT_ABORT_BY_USER_WITH_DEAUTH=23, 3).
  sm_connect_ind(23, 3)

proc sm_deauth_send*(param: pointer, reason: uint16) {.exportc, cdecl.} =
  ## Send a deauthentication frame.
  ## From blob (93 instrs): loads sm_env[0], gets vifIdx from connInfo+59,
  ## computes VIF entry, allocates 512-byte frame, builds deauth MAC header
  ## with addresses from VIF, calls me_build_deauthenticate, sets TX descriptor
  ## fields, and pushes frame via txl_frame_push(frame, 3).
  let smEnvBase = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smEnvBase)[]
  let connU = cast[uint](connInfo)
  let vifTab = cast[uint](addr vif_info_tab[0])
  let vifIdx = cast[ptr uint8](connU + 59)[]
  let vifEntry = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let staIdx = cast[ptr uint8](vifEntry + 96)[]
  let staInfo = cast[uint](addr sta_info_tab[0]) + staIdx.uint * STA_ENTRY_SIZE.uint
  let bssidPtr = staInfo + 4
  # Allocate 512-byte frame buffer (blob: txl_frame_get, NOT ke_msg_alloc)
  let frame = txl_frame_get(512)
  if frame == nil:
    return
  let f = cast[uint](frame)
  # Blob prepares TX power before using the frame body pointer.
  tpc_update_frame_tx_power(cast[pointer](vifEntry), frame)
  let bodyU = cast[uint](cast[ptr pointer](f + 108)[])
  # Build deauth MAC header at frameBody+348.
  cast[ptr uint8](bodyU + 348)[] = 0xC0'u8
  cast[ptr uint8](bodyU + 349)[] = 0
  cast[ptr uint8](bodyU + 350)[] = 0
  cast[ptr uint8](bodyU + 351)[] = 0
  # DA and BSSID come from sta_info_tab[staIdx]+4; SA comes from VIF+80.
  discard c_memcpy(cast[pointer](bodyU + 352), cast[pointer](bssidPtr), 6.csize_t)
  discard c_memcpy(cast[pointer](bodyU + 358), cast[pointer](vifEntry + 80), 6.csize_t)
  discard c_memcpy(cast[pointer](bodyU + 364), cast[pointer](bssidPtr), 6.csize_t)
  # Sequence control (blob: txl_get_seq_ctrl)
  let seqCtrl = txl_get_seq_ctrl()
  cast[ptr uint8](bodyU + 370)[] = (seqCtrl and 0xFF).uint8
  cast[ptr uint8](bodyU + 371)[] = ((seqCtrl shr 8) and 0xFF).uint8
  # Frame metadata
  cast[ptr pointer](f + 212)[] = cast[pointer](vifEntry)
  cast[ptr uint32](f + 208)[] = 0
  cast[ptr uint8](f + 47)[] = cast[ptr uint8](vifEntry + 87)[]
  cast[ptr uint8](f + 49)[] = staIdx
  # Build deauth body
  let deauthLen = me_build_deauthenticate(cast[pointer](bodyU + 372), 3)
  # Set TX descriptor lengths on the HW descriptor pointed to by frame+112.
  let txDesc = cast[uint](cast[ptr pointer](f + 112)[])
  let payloadLen = cast[ptr uint32](txDesc + 20)[]
  # From blob: total = payloadLen + 23 + txl_frame_push_arg
  let bodyLen = deauthLen  # actual body length from me_build_deauthenticate return
  cast[ptr uint32](txDesc + 24)[] = payloadLen + 23 + bodyLen
  cast[ptr uint32](txDesc + 28)[] = bodyLen + 28
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] deauth_tx ",
                          vifIdx.uint32 or (staIdx.uint32 shl 8),
                          cast[ptr uint8](vifEntry + 87)[].uint32)
    nimFwConnectTrace2U32("[WIFI-CT] deauth_hdr0 ",
                          cast[ptr uint32](bodyU + 348)[],
                          cast[ptr uint32](bodyU + 352)[])
    nimFwConnectTrace2U32("[WIFI-CT] deauth_hdr1 ",
                          cast[ptr uint32](bodyU + 356)[],
                          cast[ptr uint32](bodyU + 360)[])
    nimFwConnectTrace2U32("[WIFI-CT] deauth_hdr2 ",
                          cast[ptr uint32](bodyU + 364)[],
                          cast[ptr uint32](bodyU + 368)[])
    nimFwConnectTrace2U32("[WIFI-CT] deauth_len ",
                          bodyLen,
                          cast[ptr uint32](txDesc + 28)[])
  # Push to TX
  txl_frame_push(frame, 3)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void sm_auth_send(unsigned short, unsigned long);".}
proc sm_auth_send*(authSeqNum: uint16, statusCode: uint32) {.exportc, cdecl.} =
  ## Send an authentication frame (166 instructions in blob).
  ##
  ## Register map: s0=frame s1=frame_body(desc+108) s2=bodyLen s3=sm_env[0]
  ##   s4=sm_env s5=authSeqNum(a0) s6=statusCode(a1) s7=bssid_ptr(sta+4)
  ##   s8=secondaryIeLen
  ##
  ## Steps:
  ##   1. Load connect info from sm_env[0], extract vifIdx from info[59]
  ##   2. Compute VIF/STA entries, get BSSID from sta_info_tab[staIdx]+4
  ##   3. Allocate 512-byte frame via txl_frame_get
  ##   4. Call me_build_authenticate to build auth body
  ##   5. Copy BSSID into frame header: DA, SA, BSSID (3 x memcpy of 6 bytes)
  ##   6. Set sequence number, frame type=0xB0
  ##   7. If auth_algo==1(shared key) and seq==3: append challenge text IE
  ##   8. Compute final lengths, set TX descriptor, push frame
  let smBase = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smBase)[]
  if connInfo == nil: return
  let ciU = cast[uint](connInfo)

  # Read vifIdx from connInfo+59
  let vifIdx = cast[ptr uint8](ciU + 59)[]
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let staIdx = cast[ptr uint8](vifEntry + 96)[]
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let bssidPtr = cast[pointer](staEntry + 4)

  # Read auth parameters from connect info
  let authAlgo = cast[ptr uint8](ciU + 57)[]

  # Allocate frame buffer (512 bytes)
  let frame = txl_frame_get(512)
  if frame == nil:
    # .L116: Allocation failure -- send timeout indication
    sm_connect_ind(0, 0)
    return
  let frameU = cast[uint](frame)

  tpc_update_frame_tx_power(cast[pointer](vifEntry), frame)

  # Set up frame via me_build_authenticate
  # Frame body is at desc+108 in the TX descriptor
  let descPtr = cast[ptr pointer](frameU + 108)[]
  let bodyU = cast[uint](descPtr)

  # Build auth frame body: writes subtype bytes at body[348..351] = 0xB0, 0, 0, 0
  cast[ptr uint8](bodyU + 348)[] = 0xB0'u8
  cast[ptr uint8](bodyU + 349)[] = 0
  cast[ptr uint8](bodyU + 350)[] = 0
  cast[ptr uint8](bodyU + 351)[] = 0

  # Copy DA (6 bytes) from BSSID to frame body+352
  discard c_memcpy(cast[pointer](bodyU + 352), bssidPtr, 6)
  # Copy SA (6 bytes) from VIF+80 to frame body+358
  discard c_memcpy(cast[pointer](bodyU + 358), cast[pointer](vifEntry + 80), 6)
  # Copy BSSID (6 bytes) from BSSID to frame body+364
  discard c_memcpy(cast[pointer](bodyU + 364), bssidPtr, 6)

  # Generate and write sequence number (frame body+370..371)
  let seqNum = txl_get_seq_ctrl()  # blob uses txl_get_seq_ctrl for sequence numbers
  cast[ptr uint8](bodyU + 370)[] = (seqNum and 0xFF).uint8
  cast[ptr uint8](bodyU + 371)[] = ((seqNum shr 8) and 0xFF).uint8

  # Store AP channel info at frame+47
  let apChanIdx = cast[ptr uint8](vifEntry + 87)[]
  cast[ptr uint8](frameU + 47)[] = apChanIdx
  # Store encryption mode at frame+96
  let encMode = cast[ptr uint8](vifEntry + 96)[]
  cast[ptr uint8](frameU + 98)[] = 0
  cast[ptr uint8](frameU + 100)[] = 0
  cast[ptr uint8](frameU + 49)[] = staIdx

  # Build authenticate IE body
  var bodyLen: uint32 = 24  # base auth frame size

  # Check for shared key auth with challenge text
  let authType = cast[ptr uint8](ciU + 57)[]
  if authType == 1 and authSeqNum == 3:
    # Shared key auth seq 3: append challenge text from connect info
    bodyLen = 24  # me_build_authenticate handles this internally
    let ieStartPtr = cast[pointer](bodyU + 348 + bodyLen.uint)
    # Copy challenge text IE (24 bytes) from connect_info
    let extraLen = cast[ptr uint8](frameU + 98)[]
    bodyLen += extraLen.uint32 + 24

  # .L117/.L128: Write auth body via me_build_authenticate
  let authBodyPtr = cast[pointer](bodyLen.uint + bodyU + 348)
  let builtLen = me_build_authenticate(
    authBodyPtr, authAlgo.uint16, authSeqNum, statusCode.uint16, nil)

  # Update frame lengths
  # .L128: Set TX descriptor fields
  let thdPtr = cast[ptr pointer](frameU + 112)[]
  let thdU = cast[uint](thdPtr)
  cast[ptr uint32](frameU + 208)[] = 0
  cast[ptr pointer](frameU + 212)[] = frame

  # Total frame length excluding FCS.
  var totalLen = bodyLen + builtLen
  let extraIeLen = cast[ptr uint8](frameU + 100)[]
  totalLen += extraIeLen.uint32

  # Set THD length fields
  let thdBase = cast[ptr uint32](thdU + 20)[]
  cast[ptr uint32](thdU + 24)[] = thdBase - 1 + totalLen
  cast[ptr uint32](thdU + 28)[] = totalLen + 4
  nimFwTrace2U32("[WIFI-NIMFW] auth_tx ",
                 authSeqNum.uint32 or (authAlgo.uint32 shl 16),
                 vifIdx.uint32 or (staIdx.uint32 shl 8) or
                   ((statusCode and 0xFFFF'u32) shl 16))
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] auth_tx ",
                          authSeqNum.uint32 or (authAlgo.uint32 shl 16),
                          vifIdx.uint32 or (staIdx.uint32 shl 8) or
                            ((statusCode and 0xFFFF'u32) shl 16))
    nimFwConnectTrace2U32("[WIFI-CT] auth_hdr0 ",
                          cast[ptr uint32](bodyU + 348)[],
                          cast[ptr uint32](bodyU + 352)[])
    nimFwConnectTrace2U32("[WIFI-CT] auth_hdr1 ",
                          cast[ptr uint32](bodyU + 356)[],
                          cast[ptr uint32](bodyU + 360)[])
    nimFwConnectTrace2U32("[WIFI-CT] auth_hdr2 ",
                          cast[ptr uint32](bodyU + 364)[],
                          cast[ptr uint32](bodyU + 368)[])
    nimFwConnectTrace2U32("[WIFI-CT] auth_body ",
                          cast[ptr uint32](authBodyPtr)[],
                          cast[ptr uint32](cast[uint](authBodyPtr) + 4)[])
    nimFwConnectTrace2U32("[WIFI-CT] auth_len ",
                          totalLen,
                          cast[ptr uint32](thdU + 28)[])
    nimFwConnectTraceHw("[WIFI-CT] auth_hw ")
  nimFwTrace2U32("[WIFI-NIMFW] auth_mac ",
                 cast[ptr uint32](bodyU + 352)[],
                 cast[ptr uint32](bodyU + 364)[])
  nimFwTrace2U32("[WIFI-NIMFW] auth_len ",
                 totalLen,
                 cast[ptr uint32](thdU + 28)[])
  nimFwTrace2U32("[WIFI-NIMFW] auth_body ",
                 cast[ptr uint32](authBodyPtr)[],
                 cast[ptr uint32](cast[uint](authBodyPtr) + 4)[])

  # Check for SAE auth (blob: me_build_sae_authenticate path)
  if authAlgo == 3:
    let saeLen = me_build_sae_authenticate(frame, 3'u16, authSeqNum, statusCode.uint16, vifIdx.uint32)
    if saeLen == 0:
      # .L119: SAE build failed — release frame and indicate failure
      txl_frame_release(frame)
      sm_connect_ind(2, 0xFFFF)
      return

  # Push frame to TX queue (AC=3 = VO)
  txl_frame_push(frame, 3)

  # Set auth timeout timer (blob: ke_timer_set)
  let listenFlag = cast[ptr uint8](smBase + 19)[]
  var listenInterval: uint32 = 0x7D000  # default 512000 us
  if listenFlag != 0:
    let connAuthType = cast[ptr uint8](ciU + 57)[]
    if connAuthType != 3:
      listenInterval = 0x1E000  # reduced for non-SAE
  # Set auth response timeout timer (blob: ke_timer_set)
  ke_timer_set(SM_RSP_TIMEOUT_IND, TASK_SM, listenInterval)

  # Set auth state (blob: ke_state_set(TASK_SM, 6))
  ke_state_set(TASK_SM, 6)

  smConnecting = true

proc sm_auth_send_pre*(authSeqNum: uint16, statusCode: uint32 = 0) {.exportc, cdecl.} =
  ## Pre-send authentication (5 instrs in blob).
  ## From blob: mv a2,a1; mv a1,a0; li a0,5; jr sm_auth_assoc_send_according_chan
  ## Tail-calls sm_auth_assoc_send_according_chan(nextState=5, param1=<a0 in>,
  ## param2=<a1 in>). The Nim declaration only has `param` (a0); the callee's
  ## second arg comes from a1 at the call site. Recover a1 via inline asm.
  sm_auth_assoc_send_according_chan(5, authSeqNum, statusCode)

proc sm_auth_start*(param: pointer) {.exportc, cdecl.} =
  ## Start authentication (24 bytes in blob, 8 instrs).
  ## From blob: loads sm_env[0] (connect info), clears auth retry count at offset 60,
  ## tail-calls sm_auth_assoc_send_according_chan(1, 0, 0).
  let smBase = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smBase)[]
  if connInfo != nil:
    cast[ptr uint8](cast[uint](connInfo) + 60)[] = 0  # clear retry count
  sm_auth_send_pre(1'u16, 0)

proc sm_assoc_req_send*(param: pointer) {.exportc, cdecl.} =
  ## Send association request frame (424 bytes in blob).
  ## Blob call sequence: txl_frame_get(512), tpc_update_frame_tx_power,
  ##   memcpy x3 (DA/SA/BSSID), txl_get_seq_ctrl, me_build_associate_req,
  ##   txl_frame_push(3), ke_timer_set, ke_state_set(SM,8).
  ## On alloc failure: sm_connect_ind(0,0).
  let smBase = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smBase)[]
  if connInfo == nil: return
  let ciU = cast[uint](connInfo)
  let vifIdx = cast[ptr uint8](ciU + 59)[]
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let staIdx = cast[ptr uint8](vifEntry + 96)[]

  # Allocate TX frame via txl_frame_get(512) - NOT ke_msg_alloc
  let frame = txl_frame_get(512)
  if frame == nil:
    sm_connect_ind(0, 0)
    return
  let fa = cast[uint](frame)

  # TPC update (blob: tpc_update_frame_tx_power at 0x5a)
  tpc_update_frame_tx_power(cast[pointer](vifEntry), frame)

  # Get STA entry for addresses
  let staTab = cast[uint](addr sta_info_tab[0])
  let staE = staTab + staIdx.uint * STA_ENTRY_SIZE.uint

  # Get MAC header from frame descriptor (blob: lw s1,108(s0))
  let macHdr = cast[ptr uint](fa + 108)[]

  # Clear frame control bytes (blob: sb zero,348-351)
  cast[ptr uint8](macHdr + 348)[] = 0
  cast[ptr uint8](macHdr + 349)[] = 0
  cast[ptr uint8](macHdr + 350)[] = 0
  cast[ptr uint8](macHdr + 351)[] = 0

  # DA from sta_info_tab+4 (blob: memcpy at 0x8e)
  discard c_memcpy(cast[pointer](macHdr + 352), cast[pointer](staE + 4), 6.csize_t)
  # SA from vifEntry+80 (blob: memcpy at 0xa0)
  discard c_memcpy(cast[pointer](macHdr + 358), cast[pointer](vifEntry + 80), 6.csize_t)
  # BSSID from sta_info_tab+4 (blob: memcpy at 0xb0)
  discard c_memcpy(cast[pointer](macHdr + 364), cast[pointer](staE + 4), 6.csize_t)

  # Sequence control via txl_get_seq_ctrl (blob at 0xb8)
  let seqCtrl = txl_get_seq_ctrl()
  cast[ptr uint8](macHdr + 370)[] = (seqCtrl and 0xFF).uint8
  cast[ptr uint8](macHdr + 371)[] = ((seqCtrl shr 8) and 0xFF).uint8

  # Store VIF/STA info
  cast[ptr uint8](fa + 47)[] = vifIdx
  cast[ptr uint8](fa + 49)[] = staIdx

  # Build association request body at the MAC-header body start. Blob passes:
  # a0=macHdr+372, a1=vif+348, a2=nil, a3=vif.inst_nbr, a4=&cursor,
  # a5=&bodyLen, a6=connect info.
  var assocCursor {.noinit.}: pointer
  var assocBodyLen {.noinit.}: uint16
  let assocBodyPtr = cast[pointer](macHdr + 372)
  let assocInfo = cast[pointer](vifEntry + 348)
  let instNbr = cast[ptr uint8](vifEntry + 87)[]
  let builtLen = me_build_associate_req_impl(
    assocBodyPtr,
    assocInfo,
    nil,
    cast[pointer](instNbr.uint),
    cast[pointer](addr assocCursor),
    cast[pointer](addr assocBodyLen),
    connInfo)

  # Complete TX descriptor lengths to match the blob's sm_assoc_req_send.
  let thdPtr = cast[ptr pointer](fa + 112)[]
  let thdU = cast[uint](thdPtr)
  cast[ptr uint32](fa + 208)[] = 0
  cast[ptr pointer](fa + 212)[] = frame
  let thdBase = cast[ptr uint32](thdU + 20)[]
  cast[ptr uint32](thdU + 24)[] = thdBase + 23'u32 + builtLen
  cast[ptr uint32](thdU + 28)[] = builtLen + 28'u32
  let smEnvSecond = cast[ptr pointer](smBase + 4)[]
  if smEnvSecond != nil:
    cast[ptr uint16](cast[uint](smEnvSecond) + 16)[] = assocBodyLen
  when defined(bl808WifiNimFw):
    nimFwTrace2U32("[WIFI-NIMFW] assoc_tx_len ", builtLen, assocBodyLen.uint32)
    nimFwTrace2U32("[WIFI-NIMFW] assoc_tx_body ",
                   cast[ptr uint32](assocBodyPtr)[],
                   cast[ptr uint32](cast[uint](assocBodyPtr) + 4)[])
    nimFwTrace2U32("[WIFI-NIMFW] assoc_tx_rates ",
                   cast[ptr uint32](vifEntry + 436)[],
                   cast[ptr uint32](vifEntry + 440)[])
    when defined(bl808WifiConnectTrace):
      nimFwConnectTrace2U32("[WIFI-CT] assoc_tx_len ", builtLen, assocBodyLen.uint32)
      nimFwConnectTrace2U32("[WIFI-CT] assoc_tx_body ",
                            cast[ptr uint32](assocBodyPtr)[],
                            cast[ptr uint32](cast[uint](assocBodyPtr) + 4)[])
      nimFwConnectTrace2U32("[WIFI-CT] assoc_tx_rates ",
                            cast[ptr uint32](vifEntry + 436)[],
                            cast[ptr uint32](vifEntry + 440)[])
      nimFwConnectTraceHw("[WIFI-CT] assoc_hw ")

  # Push frame to TX (blob: txl_frame_push(frame, 3))
  txl_frame_push(frame, 3)

  # Set timeout timer
  let smFlags = cast[ptr uint8](smBase + 19)[]
  let tmo = if smFlags != 0: 0x1E000'u32 else: 0x7D000'u32
  ke_timer_set(SM_RSP_TIMEOUT_IND, TASK_SM, tmo)
  ke_state_set(TASK_SM, 8)

proc sm_assoc_req_send_pre*(param: pointer) {.exportc, cdecl.} =
  ## Pre-send association request.
  ## Blob (5 instrs):
  ##   li a0, 7         ; nextState = 7 (SM_ASSOC_REQ_WAIT_RSP / internal)
  ##   li a1, 0         ; param1 = 0
  ##   li a2, 0         ; param2 = 0
  ##   tail-call sm_auth_assoc_send_according_chan
  sm_auth_assoc_send_according_chan(7'u16, 0'u16, 0'u32)

proc sm_assoc_done*(aid: uint16) {.exportc, cdecl.} =
  ## Handle association completion.
  ## From blob (37 instrs): allocates MM_SET_VIF_STATE_REQ (size 4),
  ## fills status (param as uint16), VIF state = 1 (active), inst_nbr from
  ## connInfo+59, sends the message. Sets SM state to SM_ACTIVATING_STATE (9),
  ## clears sm_env[36], then tail-calls ke_timer_clear(SM_SA_QUERY_TIMEOUT_IND_MSG, TASK_SM).
  let smEnvBase = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smEnvBase)[]
  let connU = cast[uint](connInfo)

  # Allocate MM_SET_VIF_STATE_REQ: ke_msg_alloc(24, TASK_MM=0, TASK_SM=4, 4)
  let msg = ke_msg_alloc(MM_SET_VIF_STATE_REQ, TASK_MM, TASK_SM, 4)
  if msg != nil:
    let m = cast[uint](msg)
    # msg[0:1] = AID/status value passed by sm_assoc_rsp_handler.
    cast[ptr uint16](m)[] = aid
    # msg[2] = 1 (VIF state active)
    cast[ptr uint8](m + 2)[] = 1
    # msg[3] = connInfo[59] (vifIdx)
    cast[ptr uint8](m + 3)[] = cast[ptr uint8](connU + 59)[]
    ke_msg_send(msg)

  # Set SM state to ACTIVATING (9)
  ke_state_set(TASK_SM, SM_ACTIVATING_STATE)

  # Clear sm_env[36]
  cast[ptr uint8](smEnvBase + 36)[] = 0

  # Clear the SA query timeout timer
  ke_timer_clear(SM_SA_QUERY_TIMEOUT_IND_MSG, TASK_SM)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void sm_auth_handler(void*);".}
proc sm_auth_handler*(param: pointer) {.exportc, cdecl.} =
  ## Handle received authentication frame.
  ##
  ## From blob disassembly (201 instructions):
  ## param = auth frame descriptor with:
  ##   offset 0:   uint16 - total frame length
  ##   offset 32:  uint16 - auth algorithm number (LE)
  ##   offset 34:  uint16 - auth transaction sequence (LE)
  ##   offset 36:  uint16 - status code (LE)
  ##   offset 38+: IE body (challenge text etc.)
  ##
  ## s3 -> sm_env, s2 = param + 32.
  ## The function dispatches on status_code and auth_algo to:
  ## - SAE (algo==3): call wpa_cbs SAE handler
  ## - Open (algo==0): proceed to association
  ## - Shared Key (algo==1): handle challenge text
  ## On success, sends SM_CONNECT_AUTH_ASSOC_REQ_MSG and tail-calls
  ## sm_assoc_req_send_pre. On failure, logs via g_bl_ops_funcs[204].
  let pb = cast[ptr UncheckedArray[uint8]](param)
  let smEnvPtr = cast[uint](addr sm_env[0])
  let smConnInfo = cast[ptr pointer](smEnvPtr)[]

  # Read status code at offset 36..37 (LE u16)
  let statusCode = pb[36].uint16 or (pb[37].uint16 shl 8)
  when defined(bl808WifiConnectTrace):
    let authAlgoDbg = pb[32].uint16 or (pb[33].uint16 shl 8)
    let authSeqDbg = pb[34].uint16 or (pb[35].uint16 shl 8)
    nimFwConnectTrace2U32("[WIFI-CT] auth_rx ",
                          authAlgoDbg.uint32 or (authSeqDbg.uint32 shl 16),
                          statusCode.uint32 or (ke_state_get(TASK_SM).uint32 shl 16))

  if statusCode != 0:
    # Auth failure path (blob offsets 0x5E-0x1D8)
    # Clear connection timeout timer (blob: ke_timer_clear at 0x6E)
    ke_timer_clear(SM_RSP_TIMEOUT_IND, TASK_SM)
    # Check if auth retry via SA query is possible
    if smConnInfo != nil:
      let connPb = cast[ptr UncheckedArray[uint8]](smConnInfo)
      if connPb[57] == 1 and connPb[61] != 0:
        connPb[57] = 0
        # Retry authentication (blob: sm_auth_send_pre at 0x8C)
        sm_auth_send_pre(1'u16, 0)
        return
    # Check if association is possible despite auth failure
    let authAlgoChk = pb[32].uint16 or (pb[33].uint16 shl 8)
    if authAlgoChk == 0 and statusCode == 13:
      # Status 13: try association anyway (blob: sm_assoc_req_send_pre at 0xAA)
      sm_assoc_req_send_pre(param)
      return
    # Auth truly failed: clear timer, report connection failure
    ke_timer_clear(SM_RSP_TIMEOUT_IND, TASK_SM)  # blob: ke_timer_clear at 0xF2
    sm_connect_ind(statusCode, WLAN_FW_AUTHENTICATION_FAIILURE.uint16)  # blob: 0x12A
    return

  # Status == 0: successful auth response
  let authAlgo = pb[32].uint16 or (pb[33].uint16 shl 8)

  if authAlgo == 3:
    # SAE authentication
    let saeSeq = pb[34].uint16 or (pb[35].uint16 shl 8)
    let frameLen = cast[ptr uint16](param)[]
    if wpa_cbs != nil:
      let wpaCbArr = cast[ptr UncheckedArray[pointer]](wpa_cbs)
      let saeHandler = wpaCbArr[15]  # offset 60
      if saeHandler != nil:
        let fn = cast[proc(body: pointer, bodyLen: uint16, seq: uint16, arg: pointer): int32 {.cdecl.}](saeHandler)
        let rc = fn(cast[pointer](cast[uint](param) + 38), frameLen - 6, saeSeq, nil)
        if rc == 0:
          # Blob at 0x6e: just clear SM rsp-timeout timer. Previous Nim also
          # allocated + sent an SM_CONNECT_AUTH_ASSOC_REQ msg here — blob
          # never issues that from this path; the auth/assoc req is enqueued
          # downstream via sm_auth_send_pre / sm_assoc_req_send_pre below.
          ke_timer_clear(SM_RSP_TIMEOUT_IND, TASK_SM)
          if saeSeq == 1:
            sm_auth_send_pre((saeSeq + 1).uint16, 0)
          elif saeSeq == 2:
            cast[ptr uint8](smEnvPtr + 60)[] = 0
            sm_assoc_req_send_pre(param)
          return
        elif rc == -8:
          let lf = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
          if lf != nil:
            cast[proc(a, b: uint32, c: pointer, d, e: uint32){.cdecl.}](lf)(3, 0, nil, 1302, saeSeq.uint32)
          return
      else:
          let lf = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
          if lf != nil:
            cast[proc(a, b: uint32, c: pointer, d, e: uint32){.cdecl.}](lf)(3, 0, nil, 1307, saeSeq.uint32)
          sm_assoc_req_send_pre(param)
          return
    return
  else:
    # Open System or Shared Key
    # Clear connection timeout timer (blob: ke_timer_clear at 0x138, 0x1D0)
    ke_timer_clear(SM_RSP_TIMEOUT_IND, TASK_SM)
    if authAlgo == 0:
      # Open System: clear auth state, proceed to association
      cast[ptr uint8](smEnvPtr + 60)[] = 0
      sm_assoc_req_send_pre(param)
      return
    if authAlgo == 1:
      let sharedSeq = pb[34].uint16 or (pb[35].uint16 shl 8)
      if sharedSeq == 4:
        # Shared Key seq 4: auth complete, proceed to association
        cast[ptr uint8](smEnvPtr + 60)[] = 0
        sm_assoc_req_send_pre(param)
        return
      elif sharedSeq == 2:
        # Shared Key seq 2: challenge text, restart auth
        let frameLen = cast[ptr uint16](param)[]
        if frameLen > 135:
          # Restart authentication with challenge (blob: sm_auth_start at 0x21C)
          sm_auth_start(cast[pointer](cast[uint](param) + 40))
          return
        else:
          let lf = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
          if lf != nil:
            cast[proc(a, b: uint32, c: pointer, d, e: uint32){.cdecl.}](lf)(3, 0, nil, 1338, 0)
          return
      else:
        # Blob at 0x19a: sm_connect_ind(3, 0) for unrecognized shared-key seq,
        # then assert_warn("sm.c", 1343).
        sm_connect_ind(3, 0)
        assert_warn("sm.c", "sm.c", 1343)
        return

{.emit: "__attribute__((optimize(\"crossjumping\"))) void sm_assoc_rsp_handler(void*);".}
proc sm_assoc_rsp_handler*(param: pointer) {.exportc, cdecl.} =
  ## Handle received association response frame.
  ## From blob (141 instrs): parses association response, extracts status code
  ## and AID, checks for HT/VHT IE, sends ME_STA_ADD_REQ if successful,
  ## or reports failure to host.
  ##
  ## param layout: offset 0 = uint16 frame_len, offset 32 = frame body start
  ## Frame body: offset 2..3 = status code, offset 4..5 = AID,
  ##   offset 6+ = IEs (including HT cap, vendor-specific)
  let smEnvReloc = cast[uint](addr sm_env[0])
  let connInfo = cast[ptr pointer](smEnvReloc)[]
  let connU = cast[uint](connInfo)
  let vifTab = cast[uint](addr vif_info_tab[0])
  let blOps = cast[uint](addr g_bl_ops_funcs)

  # Get vifIdx from connInfo+59
  let vifIdx = cast[ptr uint8](connU + 59)[]
  let vifEntry = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint

  # Read sm_env secondary struct
  let smEnvSecond = cast[ptr pointer](smEnvReloc + 4)[]

  let pU = cast[uint](param)
  let frameLen = cast[ptr uint16](pU)[]
  let frameBody = pU + 32  # frame body starts at param+32
  let assocBody = pU + 38  # association response fields at param+38

  # Blob entry (0x56) clears the SM rsp-timeout timer FIRST, before
  # inspecting the status code. Previous Nim set ke_state_set(SM, 4) at
  # the entry, which blob does not do — the state transition happens
  # elsewhere (sm_auth_handler / sm_assoc_req_send).
  let smTimerIdEarly = SM_RSP_TIMEOUT_IND
  ke_timer_clear(smTimerIdEarly, TASK_SM)

  # Parse status code (bytes 2-3 of assoc body, big-endian)
  let statusHi = cast[ptr uint8](frameBody + 3)[]
  let statusLo = cast[ptr uint8](frameBody + 2)[]
  let statusCode = (statusHi.uint16 shl 8) or statusLo.uint16
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_status ", frameLen.uint32, statusCode.uint32)
    nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_body ",
                          cast[ptr uint32](frameBody)[],
                          cast[ptr uint32](frameBody + 4)[])

  if statusCode != 0:
    when defined(bl808WifiConnectTrace):
      nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_fail ",
                            statusCode.uint32,
                            cast[uint32](cast[ptr pointer](blOps)[]))
    # Association failed
    if statusCode == 30:
      # Status 30: blob .L187 searches for a vendor IE and programs a
      # retry timer. Previous Nim allocated a ME_STA_ADD_REQ message and
      # sent it — blob never does that here. Replace with blob's
      # ke_timer_set path.
      if frameLen > 6:
        let iePtr = mac_ie_find(cast[pointer](assocBody), (frameLen - 6).uint32, 56)
        if iePtr != nil:
          let ouiType = cast[ptr uint8](cast[uint](iePtr) + 1)[]
          if ouiType == 5:
            let ouiSubtype = cast[ptr uint8](cast[uint](iePtr) + 2)[]
            if ouiSubtype == 3:
              # Clear SM connect info offset 60 and schedule the retry.
              cast[ptr uint8](connU + 60)[] = 0
              let retryBytes3 = cast[ptr uint8](cast[uint](iePtr) + 3)[]
              let retryBytes4 = cast[ptr uint8](cast[uint](iePtr) + 4)[]
              let retryBytes5 = cast[ptr uint8](cast[uint](iePtr) + 5)[]
              let timerMs = ((retryBytes5.uint32 shl 16) or
                             (retryBytes4.uint32 shl 8) or
                             retryBytes3.uint32) shl 10
              ke_timer_set(smTimerIdEarly, TASK_SM, timerMs.uint16)
              return
    # Report failure: status code != 0.  The blob uses the printf-style slot
    # at g_bl_ops_funcs+4 here; slot 0 can contain a small mode flag in this
    # harness and jumping through it faults before sm_connect_ind runs.
    let logFn = cast[ptr pointer](blOps + 4)[]
    if cast[uint](logFn) > 0x1000'u:
      cast[proc(a0: pointer, a1: uint16){.cdecl.}](logFn)(nil, statusCode)
    # Send failure indication
    sm_connect_ind(5, statusCode)
    return

  # Association successful (status == 0) — timer already cleared above.

  # Parse AID from bytes 4-5
  let aidLo = cast[ptr uint8](frameBody + 4)[]
  let aidHi = cast[ptr uint8](frameBody + 5)[]
  let aid = ((aidHi.uint16 shl 8) or aidLo.uint16) and 0x3FFF'u16
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_aid ", aid.uint32,
                          cast[ptr uint8](connU + 60)[].uint32)

  # Build and send ME_STA_ADD_REQ
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntrySize = STA_ENTRY_SIZE.uint

  # Store association response IE diagnostics in the connect indication.
  # Layout: +16 assoc_req_ie_len, +18 assoc_rsp_ie_len, +20 assoc IE buffer.
  # The blob copies response IEs after the request IEs; it does not synthesize
  # the later AID field here.
  if smEnvSecond != nil:
    let smSec = cast[uint](smEnvSecond)
    let rspIeLen = if frameLen > 6: frameLen - 6 else: 0'u16
    let reqIeLen = cast[ptr uint16](smSec + 16)[]
    cast[ptr uint16](smSec + 18)[] = rspIeLen
    if rspIeLen != 0 and reqIeLen.uint + rspIeLen.uint <= 800'u:
      discard c_memcpy(cast[pointer](smSec + 20'u + reqIeLen.uint),
                       cast[pointer](assocBody),
                       rspIeLen.csize_t)

  # Blob: sm_assoc_done — mark association complete (offset 0xB6)
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_before_done ", vifIdx.uint32,
                          cast[uint32](vifEntry))
  sm_assoc_done(aid)
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_after_done ", ke_state_get(TASK_SM).uint32,
                          cast[ptr uint8](connU + 60)[].uint32)

  # Blob: me_init_rate — initialize rate control for the associated STA
  # recorded in the VIF entry.
  let staIdx = cast[ptr uint8](vifEntry + 96)[]
  when defined(bl808WifiConnectTrace):
    let staDbgAddr = staBase + staIdx.uint * staEntrySize
    nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_before_rate ", staIdx.uint32,
                          cast[uint32](staDbgAddr))
  let staEntry = cast[pointer](staBase + staIdx.uint * staEntrySize)
  me_init_rate(staEntry)
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_after_rate ", staIdx.uint32,
                          cast[ptr uint8](vifEntry + 96)[].uint32)

  # Blob: tpc_update_vif_tx_power — update TX power after association (offset 0xFA)
  let chanPtr = cast[ptr pointer](vifEntry + 424)[]
  if chanPtr != nil:
    var tpcPower: uint8 = cast[ptr uint8](cast[uint](chanPtr) + 4)[]
    var tpcRate: uint8
    when defined(bl808WifiConnectTrace):
      nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_before_tpc ", cast[uint32](cast[uint](chanPtr)),
                            tpcPower.uint32)
    tpc_update_vif_tx_power(cast[pointer](vifEntry), cast[pointer](addr tpcPower), cast[pointer](addr tpcRate))
    when defined(bl808WifiConnectTrace):
      nimFwConnectTrace2U32("[WIFI-CT] assoc_rsp_after_tpc ", tpcPower.uint32, tpcRate.uint32)

  # Blob success path (.L186) does NOT call mac_ie_find or ke_timer_set —
  # those only fire from the status==30 branch above. The "HT capability"
  # search previously reproduced here was a phantom call, as was the
  # 5-second follow-up timer (blob only arms the retry timer inside the
  # status==30 path).

  # Check WPS callback
  let smEnvConnState = cast[ptr uint8](smEnvReloc + 44)[]
  if smEnvConnState == 2:
    # WPS mode: check wps_cbs
    let wpsCbs = wps_cbs
    if wpsCbs != nil:
      # Call wps callback offset 12
      let wpsStaAddCb = cast[ptr pointer](cast[uint](wpsCbs) + 12)[]
      if wpsStaAddCb != nil:
        cast[proc(){.cdecl.}](wpsStaAddCb)()

proc sm_deauth_handler*(param: pointer) {.exportc, cdecl.} =
  ## Handle deauthentication frame (140 instrs). Validates BSSID/SA,
  ## extracts reason code, dispatches based on SM state.
  ## Returns result via a0: 0=handled/ignored, 2=state mismatch.
  let p = cast[ptr UncheckedArray[uint8]](param)
  let vifIdx = p[8]
  let smBase = cast[uint](addr sm_env[0])
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifE = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint

  # Validate BSSID: param[48..53] vs vif+380..385
  for i in 0 ..< 6:
    if p[48 + i] != cast[ptr uint8](vifE + 380 + i.uint)[]:
      # BSSID mismatch - blob logs debug with line 1503 and returns 0
      return

  # Validate SA: if multicast bit (bit 0 of first SA byte) clear, compare SA
  if (p[36] and 1) == 0:
    for i in 0 ..< 6:
      if p[36 + i] != cast[ptr uint8](vifE + 80 + i.uint)[]:
        # SA mismatch - blob logs debug with line 1507 and returns 0
        return

  # Extract reason code (LE u16 at param+56..57)
  let reason = p[56].uint16 or (p[57].uint16 shl 8)

  # Load connect-info pointer from sm_env[0]
  let connInfoPtr = cast[ptr pointer](smBase)[]

  # Check SM state - first call
  let st = ke_state_get(TASK_SM)
  if st == 10:
    # SM in state 10 (authenticating) - return 2
    smConnecting = false  # blob: s3=2 -> return
    return

  # Check SM state - second call
  let st2 = ke_state_get(TASK_SM)
  if st2 != 0:
    # SM in active state (!= 0, != 10):
    # Check if connect-info vifIdx matches param vifIdx
    if connInfoPtr != nil:
      let connVifIdx = cast[ptr uint8](cast[uint](connInfoPtr) + 59)[]
      if connVifIdx != vifIdx:
        # VIF mismatch - return 2
        smConnecting = false
        return
    # VIF matches: send connect indication with status=6 (deauth by AP)
    sm_connect_ind(6, reason)
    return

  # state == 0 (idle): check VIF connection flag at vif[88]
  let vifConn = cast[ptr uint8](vifE + 88)[]
  if vifConn == 0:
    return  # not connected, ignore

  # Check param[27] bit 0 for protected frame
  if (p[27] and 1) != 0:
    # Protected frame: check PMF flag at sm_env[36]
    let pmf = cast[ptr uint8](cast[uint](addr sm_env[0]) + 36)[]
    if pmf != 0:
      # PMF already active: just ignore (blob returns 0 via .L208)
      return

    # PMF not active: store deauth info and initiate SA query
    # blob: sh 0x201 -> sm_env[36], sb param[7] -> sm_env[38], sh reason -> sm_env[42]
    cast[ptr uint16](cast[uint](addr sm_env[0]) + 36)[] = 0x0201'u16
    cast[ptr uint8](cast[uint](addr sm_env[0]) + 38)[] = p[7]
    cast[ptr uint16](cast[uint](addr sm_env[0]) + 42)[] = reason
    # Initiate SA query (blob: sm_issue_sa_query_request at 0x18E)
    sm_issue_sa_query_request()
  else:
    # Unprotected deauth (.L217):
    # 1. Set SM state to 10 (disconnecting)
    ke_state_set(TASK_SM, 10)
    # 2. Log via g_bl_ops_funcs[1] (blob at 0x1A4-0x1B6)
    let blOps = cast[uint](addr g_bl_ops_funcs)
    let logFn = cast[ptr pointer](blOps + 4)[]
    if logFn != nil:
      cast[PlatformLogFunc](logFn)(3, 0, nil, 0, reason.uint32, 0, 0)
    # 3. Call sm_disconnect_process(vifEntry, 7, reason)
    sm_disconnect_process(cast[pointer](vifE), 7, reason)

proc sm_get_set_machwkey_index*(getFlag: uint32, vifIdx: uint32, keyBuf: pointer, keyType: uint32): uint8 {.exportc, cdecl, noinline.} =
  ## Get/set MAC HW key index for SM.
  ## From blob (32 instrs): a0=getFlag (0=set, nonzero=get), a1=vifIdx,
  ## a2=keyBuf pointer, a3=keyType (0/1/2 = different key offsets within VIF entry).
  ##
  ## For each keyType (0, 1, 2), a different offset within vif_info_tab is accessed.
  ## The exact offsets depend on relocations in the blob; from VIF entry layout they
  ## correspond to pairwise/group/management key indices.
  ## If vifIdx > 1, returns 0xFF (-1). If keyType > 2, returns 0xFF.
  ## getFlag=0: writes keyBuf[0] to vif[offset]; nonzero: reads vif[offset] into keyBuf[0].
  ## Returns 0 on success.
  ## noinline + asm barrier: blob calls this as a real function from
  ## bl_wifi_get_sta_gtk and bl_wifi_set_igtk_internal; without noinline GCC
  ## inlines the short table lookup.
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}
  if vifIdx > 1:
    return 0xFF'u8

  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdx * VIF_ENTRY_SIZE.uint

  # Determine key byte offset within VIF entry based on keyType
  # From VIF layout: key indices are stored in the security area
  # keyType 0 -> offset 172 (primary pairwise key index)
  # keyType 1 -> offset 173 (secondary pairwise key index)
  # keyType 2 -> offset 174 (group key index)
  var keyOffset: uint
  case keyType
  of 0: keyOffset = 172
  of 1: keyOffset = 173
  of 2: keyOffset = 174
  else: return 0xFF'u8

  let keyAddr = cast[ptr uint8](vifEntry + keyOffset)

  if getFlag == 0:
    # SET: write from keyBuf to vif entry
    keyAddr[] = cast[ptr uint8](keyBuf)[]
  else:
    # GET: read from vif entry to keyBuf
    cast[ptr uint8](keyBuf)[] = keyAddr[]

  return 0'u8

proc sm_handle_eapol_input*(staIdx: uint8, srcAddr: pointer, eapolBuf: pointer,
    eapolLen: uint32) {.exportc, cdecl.} =
  ## Handle EAPOL frame input (51 instrs).
  ## From blob: a0 = STA idx, a1 = source MAC, a2 = EAPOL buffer, a3 = length.
  ## Computes STA entry = sta_info_tab + staIdx * 368.
  ## Computes VIF entry = vif_info_tab + vifIdx * 1512 (vifIdx from sta[39]).
  ## Checks VIF+488 (WPA state flag). If zero, returns.
  ## Checks sm_env[44] (connection state): if == 2 (WPS mode), loads wps_cbs
  ## and calls wps_cbs[4] (WPS EAPOL handler). Otherwise checks ke_state_get(4).
  ## If state == 9 (SM_ACTIVATING), loads wpa_cbs[20] (WPA EAPOL handler).
  ## If state == 0, allocates ke_msg SM_CONNECT_AUTH_ASSOC_REQ with EAPOL data.
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let vifIdxFromSta = cast[ptr uint8](staEntry + 39)[]
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdxFromSta.uint * VIF_ENTRY_SIZE.uint
  # Check WPA state flag at VIF+488
  let wpaState = cast[ptr uint8](vifEntry + 488)[]
  if wpaState == 0:
    return
  # Check connection state
  let smBase = cast[uint](addr sm_env[0])
  let connState = cast[ptr uint8](smBase + 44)[]
  if connState == 2:
    # WPS mode: dispatch to WPS callback
    if wps_cbs != nil:
      let wpsHandler = cast[ptr pointer](cast[uint](wps_cbs) + 4)[]
      if cast[uint](wpsHandler) > 0x1000'u:
        cast[proc(src: pointer, buf: pointer, len: uint32) {.cdecl.}](wpsHandler)(
          srcAddr, eapolBuf, eapolLen)
    return
  # Normal mode: check SM task state
  let smState = ke_state_get(TASK_SM)
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] sm_eapol ", staIdx.uint32 or (smState.uint32 shl 8), eapolLen)
  if smState == SM_ACTIVATING_STATE:
    # In activating state: forward to WPA supplicant
    if wpa_cbs != nil:
      let wpaHandler = cast[ptr pointer](cast[uint](wpa_cbs) + 20)[]
      if cast[uint](wpaHandler) > 0x1000'u:
        cast[proc(src: pointer, buf: pointer, len: uint32) {.cdecl.}](wpaHandler)(
          srcAddr, eapolBuf, eapolLen)
  elif smState == 0:
    # Idle: may need to start auth/assoc
    discard

{.emit: "__attribute__((optimize(\"crossjumping\"))) void sm_handle_supplicant_result(unsigned char,unsigned char);".}
proc sm_handle_supplicant_result*(result_code: uint8, reason: uint8) {.exportc, cdecl.} =
  ## Handle WPA supplicant result (133 instrs).
  ## a0=result_code, a1=reason.
  ## From blob: loads sta_info_tab, checks ke_state_get(4)==10 for SM task state.
  ## If state==10 (SM_ACTIVATING), returns immediately.
  ## If reason==0: sets sta[72]=2 (failed) and tail-calls sm_connect_ind(0,0).
  ## If reason==15: calls g_bl_ops_funcs log, then falls through.
  ## Otherwise: transitions SM state to 10, allocates TX frame via txl_frame_get(512),
  ## builds deauth frame with VIF info, calls me_build_deauthenticate, then
  ## txl_frame_push to transmit. On failure, calls sm_connect_ind(9/10, reason).
  let staTab = cast[uint](addr sta_info_tab[0])
  let vifTab = cast[uint](addr vif_info_tab[0])

  let staEntry = staTab + result_code.uint * STA_ENTRY_SIZE.uint

  # Check SM task state
  let smState = ke_state_get(4)
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] supp_result ",
                          result_code.uint32 or (reason.uint32 shl 8),
                          smState.uint32)
  if smState == 10:
    return  # Already in activating state

  if reason == 0:
    # Supplicant failed with reason=0: check if already failed
    let curStatus = cast[ptr uint8](staEntry + 72)[]
    if curStatus == 2:
      return  # already marked failed
    cast[ptr uint8](staEntry + 72)[] = 2
    sm_connect_ind(0, 0)
    return

  if reason == 15:
    # Timeout: call platform log function if available
    let blOps = cast[uint](addr g_bl_ops_funcs)
    let logFn = cast[ptr pointer](blOps + 4)[]
    if logFn != nil:
      cast[proc(a: uint32, b: uint32, c: cstring, d: uint32) {.cdecl.}](logFn)(
        3, 0, "sm.c", 1717)

  # Transition SM state to 10 (activating)
  ke_state_set(4, 10)

  # Allocate TX frame for deauth (512 bytes)
  let frame = txl_frame_get(512)
  if frame == nil:
    # Allocation failed: signal error via sm_connect_ind
    sm_connect_ind(10, reason.uint16)
    return

  let vifIdx = cast[ptr uint8](staEntry + 39)[]
  let vifEntryBase = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint
  tpc_update_frame_tx_power(cast[pointer](vifEntryBase), frame)

  let linkDesc = cast[ptr pointer](cast[uint](frame) + 108)[]
  if linkDesc == nil:
    sm_connect_ind(10, reason.uint16)
    return
  let linkU = cast[uint](linkDesc)

  # Build MAC header for deauth frame
  # Set subtype/type at sta+348..351
  let frameHdrBase = linkU
  cast[ptr uint8](frameHdrBase + 348)[] = 0xC0'u8  # deauth frame type
  cast[ptr uint8](frameHdrBase + 349)[] = 0
  cast[ptr uint8](frameHdrBase + 350)[] = 0
  cast[ptr uint8](frameHdrBase + 351)[] = 0

  # Copy addresses (DA=BSSID, SA=own MAC, BSSID)
  discard c_memcpy(cast[pointer](frameHdrBase + 352),
                   cast[pointer](staTab + 4), 6.csize_t)
  discard c_memcpy(cast[pointer](frameHdrBase + 358),
                   cast[pointer](vifEntryBase + 80), 6.csize_t)
  discard c_memcpy(cast[pointer](frameHdrBase + 364),
                   cast[pointer](staTab + 4), 6.csize_t)

  # Get sequence control (blob: txl_get_seq_ctrl)
  let seqCtrl = txl_get_seq_ctrl()
  cast[ptr uint8](frameHdrBase + 370)[] = (seqCtrl and 0xFF).uint8
  cast[ptr uint8](frameHdrBase + 371)[] = ((seqCtrl shr 8) and 0xFF).uint8

  # Register TX-completion callback. Blob: `addi a5, s1, 128; sw &cfm, 80(a5);
  # sw vif, 84(a5)` — i.e. frame+208 = &sm_supplicant_deauth_cfm,
  # frame+212 = &vif_entry.
  cast[ptr pointer](cast[uint](frame) + 208)[] = cast[pointer](sm_supplicant_deauth_cfm)
  cast[ptr pointer](cast[uint](frame) + 212)[] = cast[pointer](vifEntryBase)
  cast[ptr uint8](cast[uint](frame) + 47)[] = vifIdx
  cast[ptr uint8](cast[uint](frame) + 49)[] = result_code

  # Build deauthenticate body
  let bodyPtr = cast[pointer](frameHdrBase + 372)
  let bodyLen = me_build_deauthenticate(bodyPtr, reason.uint16)

  # Update THD length fields.
  let thdPtr = cast[ptr pointer](cast[uint](frame) + 112)[]
  let thdU = cast[uint](thdPtr)
  let payloadStart = cast[ptr uint32](thdU + 20)[]
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] supp_deauth ",
                          reason.uint32 or (result_code.uint32 shl 8) or
                            (vifIdx.uint32 shl 16),
                          cast[uint32](cast[uint](frame)))
    nimFwConnectTrace2U32("[WIFI-CT] supp_thd ",
                          payloadStart,
                          cast[uint32](linkU + 348))
  cast[ptr uint32](thdU + 24)[] = payloadStart + 23 + bodyLen
  cast[ptr uint32](thdU + 28)[] = bodyLen + 28

  # Push frame for TX (tail call in blob)
  txl_frame_push(frame, 3)

proc sm_send_sa_query*(vifIdx: uint8, transId: uint16, isTx: uint8) {.exportc, cdecl.} =
  ## Send SA Query frame for PMF (104 instrs).
  ## Builds an SA Query action frame and sends it via txl_frame_push.
  ## a0=vifIdx, a1=transId, a2=isTx (0=request, 1=response).
  ##
  ## Assembly trace:
  ##   s2 = sta_info_tab base, computes STA entry via vifIdx*368
  ##   s7 = sta[39] (format mod)
  ##   s5 = vif_info_tab base, computes VIF entry via vifIdx*1512
  ##   Allocates frame via txl_frame_get(512, ...)
  ##   Builds MAC header: FC=0xD0 (action), addresses from STA/VIF
  ##   Body: category=8 (SA Query), action=0/1, transId
  ##   Updates frame lengths and pushes via txl_frame_push(desc, 3)
  let staBase = cast[uint](addr sta_info_tab[0])
  let vifBase = cast[uint](addr vif_info_tab[0])
  let staEntry = staBase + vifIdx.uint * STA_ENTRY_SIZE.uint
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let staFormatMod = cast[ptr uint8](staEntry + 39)[]
  let staMacAddr = cast[pointer](staEntry + 4)
  let vifMacAddr = cast[pointer](vifEntry + 80)
  # Allocate frame (512 bytes payload capacity)
  let frame = txl_frame_get(512)
  if frame == nil:
    return
  let descAddr = cast[uint](frame)
  # Build MAC header at linkDesc+348
  let linkDesc = cast[ptr pointer](descAddr + 108)[]
  let linkAddr = cast[uint](linkDesc)
  # Frame Control: 0xD0 = management, action frame
  cast[ptr uint8](linkAddr + 348)[] = 0xD0'u8
  cast[ptr uint8](linkAddr + 349)[] = 0x00'u8
  cast[ptr uint8](linkAddr + 350)[] = 0x00'u8  # duration
  cast[ptr uint8](linkAddr + 351)[] = 0x00'u8
  # Addr1 (RA) = STA MAC (BSSID)
  discard c_memcpy(cast[pointer](linkAddr + 352), staMacAddr, 6.csize_t)
  # Addr2 (SA) = VIF MAC
  discard c_memcpy(cast[pointer](linkAddr + 358), vifMacAddr, 6.csize_t)
  # Addr3 (BSSID) = STA MAC
  discard c_memcpy(cast[pointer](linkAddr + 364), staMacAddr, 6.csize_t)
  # Generate sequence number (blob: txl_get_seq_ctrl)
  let seqCtrl = txl_get_seq_ctrl()
  cast[ptr uint8](linkAddr + 370)[] = (seqCtrl and 0xFF).uint8
  cast[ptr uint8](linkAddr + 371)[] = ((seqCtrl shr 8) and 0xFF).uint8
  # SA Query body at linkDesc+348+24 = linkAddr+372
  # The body offset depends on frame header: 24-byte header for non-QoS mgmt
  let bodyBase = linkAddr + 348 + 24  # offset from MAC header start
  let bodyOff = cast[ptr uint8](descAddr + 98)[]  # header length
  let realBody = linkAddr + 348 + bodyOff.uint
  # Category = 8 (SA Query)
  cast[ptr uint8](realBody)[] = 8
  # Action = isTx (0=request, 1=response)
  cast[ptr uint8](realBody + 1)[] = isTx
  # Transaction ID (2 bytes)
  cast[ptr uint8](realBody + 2)[] = (transId and 0xFF).uint8
  cast[ptr uint8](realBody + 3)[] = ((transId shr 8) and 0xFF).uint8
  # Update frame lengths
  let totalHdrLen = bodyOff.uint32
  let bodyLen = 4'u32  # category + action + transId(2)
  let thdPtr = cast[ptr pointer](descAddr + 112)[]
  let thdAddr = cast[uint](thdPtr)
  let oldLen = cast[ptr uint32](thdAddr + 20)[]
  cast[ptr uint32](thdAddr + 24)[] = oldLen + totalHdrLen + bodyLen + 3
  cast[ptr uint32](thdAddr + 28)[] = totalHdrLen + bodyLen + 8
  # Store metadata in descriptor
  cast[ptr uint8](descAddr + 47)[] = staFormatMod
  cast[ptr uint8](descAddr + 49)[] = vifIdx
  cast[ptr uint8](descAddr + 98)[] = 0  # clear
  cast[ptr uint8](descAddr + 100)[] = 0  # clear
  # Apply mgmt frame protection (blob: txu_cntrl_protect_mgmt_frame)
  txu_cntrl_protect_mgmt_frame(frame, cast[pointer](linkAddr + 348), 0)
  # Apply TX power control (blob: tpc_update_frame_tx_power)
  tpc_update_frame_tx_power(cast[pointer](vifEntry), frame)
  # Push frame for TX on AC 3 (VO)
  txl_frame_push(frame, 3)

proc sm_sa_query_handler*(param: pointer) {.exportc, cdecl.} =
  ## Handle SA Query response/request (52 instrs).
  ## From blob: a0 = ke_msg payload. Reads VIF idx from param[8].
  ## Computes VIF entry = vif_info_tab + vifIdx * 1512.
  ## Checks VIF+88 (active flag) and VIF+86 (type != 2, not monitor).
  ## Reads STA idx from param[7]; if 0xFF returns.
  ## Checks STA entry[60] (assoc state) == APM_STA_ASSOCIATED.
  ## Loads STA+48 (connection info); checks MFP state.
  ## Reads SA Query action from param: action=0 is request, action=1 is response.
  ## For request: calls sm_send_sa_query(vifIdx, transId, 1) to send response.
  ## For response: checks transId matches pending query; if so, clears SA query
  ## timer and resets state.
  let p = cast[uint](param)
  let vifIdx = cast[ptr uint8](p + 8)[]
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  # Check VIF active
  let active = cast[ptr uint8](vifEntry + 88)[]
  if active == 0:
    return
  let vifType = cast[ptr uint8](vifEntry + 86)[]
  if vifType == 2:
    return  # monitor mode, ignore
  let staIdx = cast[ptr uint8](p + 7)[]
  if staIdx == 0xFF:
    return
  # Check STA association state
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let assocState = cast[ptr uint8](staEntry + 72)[]
  if assocState != 2:
    return  # not associated
  # Read SA query frame fields from param
  let action = cast[ptr uint8](p + 33)[]  # SA query action (0=req, 1=resp)
  let transIdLo = cast[ptr uint8](p + 34)[]
  let transIdHi = cast[ptr uint8](p + 35)[]
  let transId = transIdLo.uint16 or (transIdHi.uint16 shl 8)
  if action == 0:
    # SA Query Request received: send response
    sm_send_sa_query(vifIdx, transId, 1)
  elif action == 1:
    # SA Query Response received: validate against pending query
    let smBase = cast[uint](addr sm_env[0])
    let pendingFlag = cast[ptr uint8](smBase + 36)[]
    if pendingFlag == 0:
      return
    let pendingTransId = cast[ptr uint16](smBase + 40)[]
    if transId == pendingTransId:
      # Match: clear SA query state, cancel timer (blob: ke_timer_clear)
      cast[ptr uint8](smBase + 36)[] = 0
      let saTimerId = KE_FIRST_MSG(TASK_SM.uint16) + 10  # SM_SA_QUERY_TIMEOUT_IND
      ke_timer_clear(saTimerId, TASK_SM)

proc sm_issue_sa_query_request*() {.exportc, cdecl.} =
  ## Issue SA Query request to AP (28 instrs).
  ## From blob: generates random transaction ID via LCG PRNG (rc_prng),
  ## stores lower 16 bits as pending transId in sm_env+40.
  ## Reads VIF idx from sm_env+38. Calls sm_send_sa_query(vifIdx, transId, 0).
  ## Starts SA query timeout timer: ke_timer_set(SM_SA_QUERY_TIMEOUT_IND,
  ## TASK_SM, 4, 100000) for ~100ms timeout.
  let smBase = cast[uint](addr sm_env[0])
  # Generate random transaction ID using LCG PRNG
  let rng = rcPrngNext()
  let transId = (rng shr 16).uint16
  cast[ptr uint16](smBase + 40)[] = transId
  # Read VIF index
  let vifIdx = cast[ptr uint8](smBase + 38)[]
  # Send SA Query request
  sm_send_sa_query(vifIdx, transId, 0)
  # Start SA query timeout timer via ke_timer_set
  # From blob: calls ke_timer_set(SM_SA_QUERY_TIMEOUT_IND, TASK_SM, 100000)
  # which schedules a kernel-task message event ~100ms in the future.
  ke_timer_set(SM_SA_QUERY_TIMEOUT_IND_MSG, TASK_SM, 100000'u32)

proc sm_set_channel_coex_connected*(channel: uint8) {.exportc, cdecl.} =
  ## Set channel coexistence info after connection (10 instrs).
  ## From blob: loads primary freq from sm_env+32, center freq from sm_env+34,
  ## then tail-calls phy_set_channel(0, 0, primFreq, centerFreq, 0, 0).
  let smBase = cast[uint](addr sm_env[0])
  let primFreq = cast[ptr uint16](smBase + 32)[]
  let centerFreq = cast[ptr uint16](smBase + 34)[]
  phy_set_channel(0, 0, primFreq, centerFreq, 0, 0)

proc sm_connection_tlv_set*(id: uint8, data: pointer, len: uint16) {.exportc, cdecl, noinline.} =
  ## Set a TLV in the connection data chain.
  ## noinline: blob calls this from mm_connection_loss_ind_handler; empty body
  ## would otherwise be elided.
  {.emit: "__asm__ volatile(\"\" ::: \"memory\");".}
  discard

proc sm_connection_tlv_reset*() {.exportc, cdecl.} =
  ## Reset all connection TLV data.
  discard

proc sm_connection_tlv_pack*(param: pointer) {.exportc, cdecl.} =
  ## Pack connection TLV data into a buffer (2 instrs).
  ## From blob: li a0,0; ret -- returns 0 (no TLV data to pack).
  ## Blob always returns 0; no TLV packing is implemented.
  {.emit: ["asm volatile(\"li a0, 0\");"].}

proc sm_connection_tlv_desc_get*(): pointer {.exportc, cdecl.} =
  ## Get the connection TLV descriptor list.
  return nil

proc sm_connect_wap_tlv_pack_cb*(param: pointer) {.exportc, cdecl.} =
  ## Callback for WPA TLV packing during connection.
  discard

proc sm_connection_sta_add_ind*(param: pointer) {.exportc, cdecl.} =
  ## Indicate STA addition during connection (37 instrs).
  ## From blob: loads sm_env pointer (sm_env[0]). Allocates ke_msg with
  ## id=SM_STA_ADD_IND (0x100A), dest=TASK_API(9), src=TASK_SM(4), paramLen=3.
  ## Copies VIF index from sm_env+59 to msg[0], VIF's STA index to msg[1],
  ## and VIF+484 bit 0 (WPA flag) to msg[2]. Tail-calls ke_msg_send.
  let smBase = cast[uint](addr sm_env[0])
  let smEnvPtr = cast[ptr pointer](smBase)[]
  if smEnvPtr == nil:
    return
  let smEnvU = cast[uint](smEnvPtr)
  # Allocate SM_STA_ADD_IND message
  let msg = ke_msg_alloc(SM_STA_ADD_IND, TASK_API, TASK_SM, 3)
  if msg == nil:
    return
  let m = cast[uint](msg)
  # Copy VIF index from sm_env connection info
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifIdx = cast[ptr uint8](smEnvU + 59)[]  # same field used for VIF lookup
  cast[ptr uint8](m)[] = vifIdx
  # Get VIF entry and copy the associated STA index
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let staIdx = cast[ptr uint8](vifEntry + 96)[]
  cast[ptr uint8](m + 1)[] = staIdx
  # Copy WPA flag (VIF+484 bit 0)
  let wpaFlags = cast[ptr uint32](vifEntry + 484)[]
  cast[ptr uint8](m + 2)[] = (wpaFlags and 1).uint8
  when defined(bl808WifiConnectTrace):
    nimFwConnectTrace2U32("[WIFI-CT] sta_add_ind ",
                          vifIdx.uint32 or (staIdx.uint32 shl 8) or
                            ((wpaFlags and 1).uint32 shl 16),
                          cast[ptr uint8](vifEntry + 488)[].uint32)
  ke_msg_send(msg)

proc sm_connect_auth_assoc_req() {.exportc, cdecl.} =
  ## Send pending auth or assoc during connection (32 instrs).
  ## From blob: a0 = ke_msg header, a1 = ke_msg payload.
  ## Reads payload[0] (msg_id halfword). If msg_id == 5 (SM_AUTH_STATE),
  ## checks ke_state_get(4) == 5; if match, reads payload[2] (freq) and
  ## payload[4] (param ptr), calls sm_auth_send(freq, paramPtr).
  ## If msg_id == 7, checks ke_state_get(4) == 7; if match, calls
  ## sm_assoc_req_send. Otherwise returns 0.
  ## Call graph: ke_state_get, sm_auth_send, sm_assoc_req_send
  var payload: pointer
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", payload, ") );"].}
  if payload == nil:
    return
  let pU = cast[uint](payload)
  let msgId = cast[ptr uint16](pU)[]
  if msgId == 5:
    let smState = ke_state_get(TASK_SM)
    if smState != 5:
      return
    # Blob: lhu a0,2(s0); lw a1,4(s0); call sm_auth_send
    # a0 = payload[2] (authSeqNum), a1 = payload[4] (statusCode via hidden arg)
    let authSeqNum = cast[ptr uint16](pU + 2)[]
    let statusCode = cast[ptr uint32](pU + 4)[]
    sm_auth_send(authSeqNum, statusCode)
  elif msgId == 7:
    let smState = ke_state_get(TASK_SM)
    if smState != 7:
      return
    sm_assoc_req_send(payload)

# ###########################################################################
#                   APM: AP Management
# ###########################################################################

proc apm_init*() {.exportc, cdecl.} =
  ## Initialize AP management module (20 instrs).
  ## From blob: memset(apm_env, 0, 176), then sets:
  ##   apm_env[12] = 0 (already zero from memset)
  ##   apm_env[88] = 4 (max STA count default)
  ##   apm_env[87] = 0 (STA counter)
  ## Then tail-calls ke_state_set(TASK_APM=5, 0).
  discard c_memset(addr apm_env[0], 0, 176.csize_t)  # clear full 176-byte env
  apm_env[12] = 0          # connection info cleared
  apm_env[88] = 4          # max STA count = 4
  apm_env[87] = 0          # current STA count = 0
  ke_state_set(TASK_APM, 0)

proc apm_start_cfm*(param: pointer) {.exportc, cdecl.} =
  ## Process AP start confirmation.
  ## From blob (135 instrs): param (a0) is status code (0 = success).
  ## On success, sends MM_SET_VIF_STATE_REQ to activate VIF, copies beacon/channel
  ## info from connect info to VIF entry, initializes self-STA in sta_info_tab,
  ## calls me_init_rate on it. Then (both success/failure): fills APM_START_CFM
  ## message with status and vifIdx, sends it, starts connection timeout timer,
  ## frees the connect info, clears apm_env[0], and resets APM state to 0.
  let status = cast[uint8](cast[uint](param))
  let apmEnvBase = cast[uint](addr apm_env[0])
  let connInfo = cast[ptr pointer](apmEnvBase)[]
  if connInfo == nil:
    return
  let connU = cast[uint](connInfo)
  let vifTabBase = cast[uint](addr vif_info_tab[0])
  let staTabBase = cast[uint](addr sta_info_tab[0])
  let blOps = cast[uint](addr g_bl_ops_funcs)

  # Allocate APM_START_CFM message (4 bytes)
  let msg = ke_msg_alloc(APM_START_CFM, TASK_API, TASK_APM, 4)
  if msg == nil:
    return
  let m = cast[uint](msg)

  if status == 0:
    # --- Success path ---
    let vifIdx = cast[ptr uint8](connU + 51)[]
    let vifEntry = vifTabBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
    let selfStaIdx = vifIdx + 5  # Self-STA index = vifIdx + NX_REMOTE_STA_MAX

    # 1. Send MM_SET_VIF_STATE_REQ to activate VIF
    let msg2 = ke_msg_alloc(MM_SET_VIF_STATE_REQ, TASK_MM, TASK_APM, 4)
    if msg2 != nil:
      let m2 = cast[uint](msg2)
      cast[ptr uint8](m2 + 2)[] = 1  # active state
      cast[ptr uint8](m2 + 3)[] = cast[ptr uint8](vifEntry + 87)[]  # inst_nbr
      ke_msg_send(msg2)

    # 2. Copy beacon-related fields from connect info to VIF entry
    cast[ptr uint32](vifEntry + 1496)[] = cast[ptr uint32](connU + 44)[]  # beacon rate/info
    cast[ptr uint8](vifEntry + 334)[] = 0  # clear RC flags
    cast[ptr uint16](vifEntry + 336)[] = cast[ptr uint16](connU + 48)[]  # beacon interval

    # 3. Read band from channel context and store in APM_START_CFM msg
    let chanPtr = cast[ptr pointer](vifEntry + 64)[]
    if chanPtr != nil:
      let band = cast[ptr uint8](cast[uint](chanPtr) + 23)[]
      cast[ptr uint8](m + 2)[] = band

    # 4. Log via g_bl_ops_funcs[204]
    let logFn = cast[ptr pointer](blOps + 204)[]
    if logFn != nil:
      type LogFn = proc(level: uint32, flags: uint32, file: pointer, line: uint32, args: uint32) {.cdecl, varargs.}
      cast[LogFn](logFn)(2, 0, nil, 94, 0)

    # 5. Store AP STA index into msg and apm_env
    cast[ptr uint8](m + 3)[] = selfStaIdx
    cast[ptr uint8](apmEnvBase + 90)[] = selfStaIdx

    # 6. Initialize self-STA entry in sta_info_tab
    let selfStaEntry = staTabBase + selfStaIdx.uint * STA_ENTRY_SIZE.uint

    # Copy 13 bytes of rate info from connect info to STA entry offset 248
    discard c_memcpy(cast[pointer](selfStaEntry + 248), connInfo, 13.csize_t)

    # Set STA type to AP
    cast[ptr uint8](selfStaEntry + 72)[] = 2  # VIF_TYPE_AP

    # Initialize rate control for the self-STA.
    me_init_bcmc_rate(cast[pointer](selfStaEntry))

    # Set self-STA flags
    let rcFlags = cast[ptr uint8](selfStaEntry + 334)[]
    cast[ptr uint8](selfStaEntry + 334)[] = rcFlags or 0x10  # set bit 4
    cast[ptr uint16](selfStaEntry + 4)[] = 1  # status = active
    cast[ptr uint8](selfStaEntry + 42)[] = 1  # flag
    cast[ptr uint8](selfStaEntry + 40)[] = selfStaIdx  # AP STA index

  # --- Common tail (both success and failure) ---
  # Fill and send APM_START_CFM
  cast[ptr uint8](m)[] = status
  cast[ptr uint8](m + 1)[] = cast[ptr uint8](connU + 51)[]  # vifIdx

  # Log
  let logFn2 = cast[ptr pointer](blOps + 204)[]
  if logFn2 != nil:
    type LogFn = proc(level: uint32, flags: uint32, file: pointer, line: uint32, args: uint32) {.cdecl, varargs.}
    cast[LogFn](logFn2)(1, 0, nil, 120, 0)

  # Start connection timeout timer (5 seconds = 5,000,000 MAC ticks)
  ke_timer_set(APM_STA_CONNECT_TIMEOUT_IND, TASK_APM, 5000000)

  # Send the APM_START_CFM message
  ke_msg_send(msg)

  # Free the connect info (ke_msg_free subtracts 12 from payload to get header)
  ke_msg_free(connInfo)

  # Clear connect info pointer in apm_env
  cast[ptr pointer](apmEnvBase)[] = nil

  # Reset APM state to idle
  ke_state_set(TASK_APM, 0)

proc apm_stop*(vifEntry: pointer) {.exportc, cdecl.} =
  ## Stop AP mode for the given VIF entry.
  ## From blob (72 instrs): allocates ME_SET_PS_DISABLE_REQ and ME_SET_ACTIVE_REQ
  ## messages, logs the stop event, sends PS disable, optionally sends
  ## MM_SET_VIF_STATE_REQ if STAs are connected, unlinks channel context if
  ## present, sends ME_SET_ACTIVE_REQ (deactivate), then tail-calls ke_msg_send.
  let vif = cast[uint](vifEntry)
  let instNbr = cast[ptr uint8](vif + 87)[]

  # 1. Allocate ME_SET_PS_DISABLE_REQ: ke_msg_alloc(0xC0F, TASK_ME, TASK_APM, 2)
  let msg1 = ke_msg_alloc(ME_SET_PS_DISABLE_REQ, TASK_ME, TASK_APM, 2)

  # 2. Allocate ME_SET_ACTIVE_REQ: ke_msg_alloc(0xC0D, TASK_ME, TASK_APM, 2)
  let msg2 = ke_msg_alloc(ME_SET_ACTIVE_REQ, TASK_ME, TASK_APM, 2)

  # 3. Log the stop event via g_bl_ops_funcs
  let blOps = cast[uint](addr g_bl_ops_funcs)
  let logFn = cast[ptr pointer](blOps + 204)[]
  if logFn != nil:
    type LogFn = proc(level: uint32, flags: uint32, file: pointer, line: uint32, args: uint32) {.cdecl, varargs.}
    cast[LogFn](logFn)(1, 0, nil, 234, 0)

  # 4. Clear the STA connect timeout timer (blob: ke_timer_clear at 0x60)
  # Blob: a0=APM_STA_CONNECT_TIMEOUT_IND, a1=instNbr
  let timerMsgId = KE_FIRST_MSG(TASK_APM.uint16) + 6  # APM_STA_CONNECT_TIMEOUT_IND
  ke_timer_clear(timerMsgId, instNbr)

  # 5. Fill and send ME_SET_PS_DISABLE_REQ
  if msg1 != nil:
    let p1 = cast[ptr UncheckedArray[uint8]](msg1)
    p1[0] = 0  # disable PS
    p1[1] = instNbr
    ke_msg_send(msg1)

  # 6. If VIF has connected STAs, send MM_SET_VIF_STATE_REQ to deactivate
  let numSta = cast[ptr uint8](vif + 88)[]
  if numSta != 0:
    let stateMsg = ke_msg_alloc(MM_SET_VIF_STATE_REQ, TASK_MM, TASK_APM, 4)
    if stateMsg != nil:
      let ps = cast[ptr UncheckedArray[uint8]](stateMsg)
      ps[2] = 0         # state = inactive
      ps[3] = instNbr
      ke_msg_send(stateMsg)

  # 7. Unlink channel context if present (blob: chan_ctxt_unlink at 0xb0)
  let chanCtxt = cast[ptr pointer](vif + 64)[]
  if chanCtxt != nil:
    chan_ctxt_unlink(instNbr)

  # 8. Fill and send ME_SET_ACTIVE_REQ (deactivate)
  if msg2 != nil:
    let p2 = cast[ptr UncheckedArray[uint8]](msg2)
    p2[0] = 0  # deactivate
    p2[1] = instNbr
    ke_msg_send(msg2)

proc apm_set_bss_param*(param: pointer) {.exportc, cdecl.} =
  ## Set BSS parameters for AP mode.
  ## Blob (123 instrs): loads APM connect info from apm_env, reads vifIdx,
  ## allocates 5 messages up front, then pushes each onto apm_env+4 list
  ## via co_list_push_back. apm_send_next_bss_param pops and dispatches.
  ## Call sequence: ke_msg_alloc x5, co_list_push_back (PS_DISABLE), memcpy
  ## (BSSID), co_list_push_back (BSSID), me_legacy_rate_bitfield_build,
  ## co_list_push_back (RATES), co_list_push_back (BCN_INT),
  ## co_list_push_back (ACTIVE), apm_send_next_bss_param, ke_state_set.
  let apmEnvBase = cast[uint](addr apm_env[0])
  let connInfo = cast[ptr pointer](apmEnvBase)[]
  let connU = cast[uint](connInfo)
  let vifTab = cast[uint](addr vif_info_tab[0])
  let vifIdx = cast[ptr uint8](connU + 51)[]
  let vifEntry = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let apmListPtr = cast[ptr CoList](apmEnvBase + 4)

  template pushMsg(msg: pointer) =
    let msgHdr = cast[ptr CoListHdr](cast[uint](msg) - 12)
    co_list_push_back(apmListPtr, msgHdr)

  # Alloc all 5 up front (blob 0x2e..0x78)
  let msgPs     = ke_msg_alloc(ME_SET_PS_DISABLE_REQ,  TASK_ME, TASK_APM, 2)
  let msgBssid  = ke_msg_alloc(MM_SET_BSSID_REQ,        TASK_MM, TASK_APM, 7)
  let msgRates  = ke_msg_alloc(MM_SET_BASIC_RATES_REQ,  TASK_MM, TASK_APM, 8)
  let msgBcn    = ke_msg_alloc(MM_SET_BEACON_INT_REQ,   TASK_MM, TASK_APM, 4)
  let msgActive = ke_msg_alloc(ME_SET_ACTIVE_REQ,       TASK_ME, TASK_APM, 2)

  # 1. ME_SET_PS_DISABLE_REQ -> push at 0xAC
  if msgPs != nil:
    let p = cast[ptr UncheckedArray[uint8]](msgPs)
    p[0] = 1; p[1] = vifIdx
    pushMsg(msgPs)

  # 2. MM_SET_BSSID_REQ: memcpy (blob 0xBC), push at 0xD8
  if msgBssid != nil:
    discard c_memcpy(msgBssid, cast[pointer](vifEntry + 80), 6)
    cast[ptr UncheckedArray[uint8]](msgBssid)[6] = vifIdx
    pushMsg(msgBssid)

  # 3. MM_SET_BASIC_RATES_REQ: rate bitfield (blob 0xEC), push at 0x10A
  if msgRates != nil:
    let p = cast[ptr UncheckedArray[uint8]](msgRates)
    let rateCount = cast[ptr uint8](connU + 248)[]
    let rateBits = me_legacy_rate_bitfield_build(cast[pointer](connU + 249), rateCount)
    cast[ptr uint32](msgRates)[] = rateBits
    p[4] = vifIdx
    pushMsg(msgRates)

  # 4. MM_SET_BEACON_INT_REQ -> push at 0x12E
  if msgBcn != nil:
    cast[ptr uint16](msgBcn)[] = cast[ptr uint16](connU + 40)[]
    cast[ptr UncheckedArray[uint8]](msgBcn)[2] = vifIdx
    pushMsg(msgBcn)

  # 5. ME_SET_ACTIVE_REQ -> push at 0x14E
  if msgActive != nil:
    let p = cast[ptr UncheckedArray[uint8]](msgActive)
    p[0] = 1; p[1] = vifIdx
    pushMsg(msgActive)

  # 6. Advance state, then dispatch the queue. AP confirmation handlers
  # require state 1 before the first queued request can complete.
  ke_state_set(TASK_APM, 1)
  apm_send_next_bss_param(param)

proc apm_send_next_bss_param*(param: pointer) {.exportc, cdecl.} =
  ## Send next BSS parameter during AP setup (72 bytes in blob, 18 instrs, apm.o).
  ## Blob: co_list_pop_front(&apm_env+4), assert non-null (line 188),
  ## add 12 to skip ke_msg header, tail-call ke_msg_send.
  let apmBase = cast[uint](addr apm_env[0])
  let listPtr = cast[ptr CoList](apmBase + 4)
  let elem = co_list_pop_front(listPtr)
  if elem == nil:
    assert_err("apm.c", "apm.c", 188)
  # Element is 12 bytes into the ke_msg struct; add 12 to get msg payload
  let msg = cast[pointer](cast[uint](elem) + 12)
  ke_msg_send(msg)

proc apm_bcn_set*(param: pointer) {.exportc, cdecl.} =
  ## Set beacon content for AP mode.
  ## From blob (59 instrs): loads connect info from apm_env[0], allocates
  ## MM_BCN_CHANGE_REQ message (id=45), fills beacon ptr/len/tim/csa offsets,
  ## optionally copies beacon payload from apm_env[16] and clears it, sends
  ## the message, then tail-calls ke_state_set(TASK_APM, 2).
  let apmEnvBase = cast[uint](addr apm_env[0])
  let connInfo = cast[ptr pointer](apmEnvBase)[]
  if connInfo == nil: return
  let ci = cast[uint](connInfo)
  let vifTabBase = cast[uint](addr vif_info_tab[0])

  # Compute paramLen from beacon length + 12 (header)
  let bcnLen = cast[ptr uint16](ci + 36)[]
  let paramLen = bcnLen.uint32 + 12
  # Allocate MM_BCN_CHANGE_REQ (msg id 45)
  let msg = ke_msg_alloc(45, TASK_MM, TASK_APM, paramLen)
  if msg == nil: return
  let m = cast[uint](msg)

  # Fill message fields from connect info
  cast[ptr uint32](m)[] = cast[ptr uint32](ci + 32)[]     # msg[0] = beacon_ptr
  cast[ptr uint16](m + 4)[] = cast[ptr uint16](ci + 36)[] # msg[4] = beacon_len
  cast[ptr uint16](m + 6)[] = cast[ptr uint16](ci + 38)[] # msg[6] = tim_offset
  cast[ptr uint8](m + 8)[] = cast[ptr uint8](ci + 50)[]   # msg[8] = csa_oft_0
  cast[ptr uint8](m + 9)[] = cast[ptr uint8](ci + 51)[]   # msg[9] = csa_oft_1

  # Look up VIF entry for beacon buffer copy
  let instNbr = cast[ptr uint8](ci + 51)[]  # vifIdx from connect info
  let vifEntry = vifTabBase + instNbr.uint * VIF_ENTRY_SIZE.uint

  # Check if embedded AP mode is enabled (blob: apm_embedded_enabled at 0x66)
  let embEnabled = apm_embedded_enabled(cast[pointer](vifEntry))
  if embEnabled:
    # Copy beacon payload from connect info into message at offset 12
    let bcnDataPtr = cast[ptr pointer](ci + 32)[]
    if bcnDataPtr != nil:
      discard c_memcpy(cast[pointer](m + 12), bcnDataPtr, bcnLen.csize_t)

  # Send the message
  ke_msg_send(msg)

  # Advance APM state to 2
  ke_state_set(TASK_APM, 2)

proc apm_sta_add*(param: pointer): uint8 {.exportc, cdecl.} =
  ## Add a station to AP (association) (38 instrs).
  ## From blob: a0 = STA info pointer from association request.
  ## Allocates ke_msg APM_STA_ADD_IND (0x1404), dest=TASK_API(9), src=TASK_APM(5),
  ## paramLen=28. Copies fields from STA entry:
  ##   msg[0..3] = sta[308] (rate config info)
  ##   msg[4..7] = sta[4..7] (MAC addr low)
  ##   msg[8..9] = sta[8..9] (MAC addr high)
  ##   msg[11] = sta[40] (info_idx)
  ##   msg[10] = sta[39] (VIF inst)
  ##   msg[12] = sta[43] (signed byte, capabilities)
  ##   msg[16..19] = sta[12..15] (assoc info)
  ##   msg[20..23] = sta[16..19] (assoc info cont)
  ##   msg[24] = sta[44] (flags byte)
  ## Tail-calls ke_msg_send.
  let s0 = cast[uint](param)
  let msg = ke_msg_alloc(APM_STA_ADD_IND, TASK_API, TASK_APM, 28)
  if msg == nil:
    return 0xFF
  let m = cast[uint](msg)
  # Copy rate config from sta+308
  cast[ptr uint32](m)[] = cast[ptr uint32](s0 + 308)[]
  # Copy MAC address (sta+4, 6 bytes as two words)
  cast[ptr uint32](m + 4)[] = cast[ptr uint32](s0 + 4)[]
  cast[ptr uint16](m + 8)[] = cast[ptr uint16](s0 + 8)[]
  # Copy inst fields
  cast[ptr uint8](m + 11)[] = cast[ptr uint8](s0 + 40)[]
  cast[ptr uint8](m + 10)[] = cast[ptr uint8](s0 + 39)[]
  # Copy capabilities (signed byte)
  cast[ptr uint8](m + 12)[] = cast[ptr uint8](s0 + 43)[]
  # Copy assoc info
  cast[ptr uint32](m + 16)[] = cast[ptr uint32](s0 + 12)[]
  cast[ptr uint32](m + 20)[] = cast[ptr uint32](s0 + 16)[]
  # Copy flags
  cast[ptr uint8](m + 24)[] = cast[ptr uint8](s0 + 44)[]
  ke_msg_send(msg)
  return 0

proc apm_sta_remove*(vifEntry: pointer, staIdx: uint8, macAddr: pointer, reason: uint32) {.exportc, cdecl.} =
  ## Remove a station from AP (62 instructions in blob).
  ##
  ## Blob ABI: a0=vifEntry, a1=staIdx, a2=macAddr, a3=reason.
  ##
  ## Flow:
  ##   1. Compute sta_entry = sta_info_tab + a1 * 368.
  ##   2. Log STA MAC bytes (offsets 4,6,8 halfwords from entry) at line 1090.
  ##   3. Compute VIF entry from vif_info_tab + vifIdx * 1512.
  ##   4. Call apm_send_mlme(sta_entry+4, 0xC0, macAddr, nil, nil, reason) to send
  ##      deauth frame.
  ##   5. Tail-call apm_sta_fw_delete(staIdx, vifIdx, reason).
  let staTabBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staTabBase + staIdx.uint * STA_ENTRY_SIZE.uint

  # Log STA MAC bytes from sta_entry at offsets 4, 6, 8 (halfwords)
  let logFn = getLogFunc(0)
  if logFn != nil:
    let hw4 = cast[ptr uint16](staEntry + 4)[]
    let hw6 = cast[ptr uint16](staEntry + 6)[]
    let hw8 = cast[ptr uint16](staEntry + 8)[]
    logFn(2, 0, nil, 1090, hw4.uint32, hw6.uint32, hw8.uint32)

  # Compute VIF entry from vif_info_tab using vifEntry (a0 from caller)
  let vifTabBase = cast[uint](addr vif_info_tab[0])
  let vifU = vifTabBase + staIdx.uint * STA_ENTRY_SIZE.uint + 4  # sta_entry MAC addr

  # Send deauth MLME frame: apm_send_mlme(sta_entry+4, 0xC0, macAddr, nil, nil, reason)
  apm_send_mlme(cast[pointer](staEntry + 4), 0xC0'u16, macAddr, nil, nil,
                cast[pointer](reason))

  # Tail-call apm_sta_delete to remove the STA (blob calls apm_sta_delete, not apm_sta_fw_delete)
  apm_sta_delete(cast[pointer](staIdx.uint or (1'u shl 16) or (reason shl 8)))

proc apm_sta_fw_delete*(staIdx: uint8, vifIdx: uint8, reason: uint16) {.exportc, cdecl.} =
  ## Delete station from firmware tables (28 bytes in blob, 8 instrs).
  ## From blob: tail-calls apm_sta_delete with packed ABI:
  ##   a0=staIdx, a1=sta_info_tab+4+staIdx*368 (MAC addr), a2=vifIdx, a3=reason.
  let staBase = cast[uint](addr sta_info_tab[0])
  let staMacAddr = staBase + 4 + staIdx.uint * STA_ENTRY_SIZE.uint
  # Pass a1=macAddr, a2=vifIdx, a3=reason to apm_sta_delete (which reads them via asm)
  {.emit: ["asm volatile(\"mv a1, %0\" : : \"r\"(", staMacAddr, ") );"].}
  {.emit: ["asm volatile(\"mv a2, %0\" : : \"r\"(", vifIdx, ") );"].}
  {.emit: ["asm volatile(\"mv a3, %0\" : : \"r\"(", reason, ") );"].}
  apm_sta_delete(cast[pointer](staIdx.uint))

proc apm_probe_req_handler*(param: pointer) {.exportc, cdecl.} =
  ## Handle probe request in AP mode (103 instrs).
  ## a0 = RX frame descriptor for the received probe request.
  ## Looks up the AP VIF from param[8] (VIF index). If VIF index is 0xFF,
  ## calls mm_ap_probe_cfm to find the matching AP VIF.
  ## Checks VIF is active (byte 88 != 0) and has a channel context (offset 64 != nil).
  ## Extracts the probe request SSID IE and compares against the AP's SSID.
  ## If SSID matches or is wildcard, checks supported rates for band compatibility.
  ## Finally tail-calls apm_send_mlme to send probe response.
  let paramAddr = cast[uint](param)
  let vifIdx = cast[ptr uint8](paramAddr + 8)[]
  let vifBase = cast[uint](addr vif_info_tab[0])
  var vifEntry: uint
  if vifIdx == 0xFF:
    # Search for AP VIF
    let apVif = vif_mgmt_get_first_ap_inf()
    if apVif == nil:
      return
    vifEntry = cast[uint](apVif)
  else:
    vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  # Check VIF is active and has channel context
  let active = cast[ptr uint8](vifEntry + 88)[]
  if active == 0:
    return
  let chanCtxt = cast[ptr pointer](vifEntry + 64)[]
  if chanCtxt == nil:
    return
  # Find SSID IE in probe request using mac_ie_find
  # Build search params: body starts at param-24 offset from frame start
  let bodyPtr = cast[pointer](paramAddr)
  let bodyLen = cast[ptr uint16](paramAddr)[]
  # Use mac_ie_find with the available frame info
  let ssidIe = mac_ie_find(bodyPtr, bodyLen.uint32, 0)
  if ssidIe != nil:
    let ssidIeAddr = cast[uint](ssidIe)
    let ieLen = cast[ptr uint8](ssidIeAddr + 1)[]
    if ieLen != 0:
      # Compare SSID against AP's SSID (at vifEntry+386=SSID len, +387=SSID data)
      let apSsidLen = cast[ptr uint8](vifEntry + 386)[]
      if ieLen != apSsidLen:
        return
      let result = c_memcmp(cast[pointer](ssidIeAddr + 2),
                            cast[pointer](vifEntry + 387), ieLen.csize_t)
      if result != 0:
        return
  else:
    # No SSID IE: check if hidden SSID mode (vifEntry+385)
    let hiddenFlag = cast[ptr uint8](vifEntry + 385)[]
    if hiddenFlag != 0:
      return
  # Check supported rates (IE ID=1) for band compatibility
  let ratesIe = mac_ie_find(bodyPtr, bodyLen.uint32, 1)
  if ratesIe != nil:
    let ratesAddr = cast[uint](ratesIe)
    let rateVal = cast[ptr uint8](ratesAddr + 2)[]
    # Check rate table from vifEntry+424
    let rateInfo = cast[ptr pointer](vifEntry + 424)[]
    if rateInfo != nil:
      let band = cast[ptr uint8](cast[uint](rateInfo) + 2)[]
      # Perform rate/band compatibility check
      if band == 0:
        # 2.4GHz: check basic rate range (blob computes rate offset and divides by 5)
        let rateBase = (rateVal and 0x7F).uint32
        if rateBase > 72:  # 48*1.5 = max expected
          return
      else:
        # 5GHz band
        let rateBase = (rateVal and 0x7F).uint32
        if rateBase < 12:  # min 6Mbps
          return
  # Send probe response: tail-call apm_send_mlme
  # Args: a0=vifEntry, a1=0x50(probe_resp subtype), a2=param+42(src addr), a3..a5=0
  apm_send_mlme(cast[pointer](vifEntry), 0x50'u16,
                cast[pointer](paramAddr + 42), nil, nil, nil)

proc apm_auth_handler*(param: pointer) {.exportc, cdecl.} =
  ## Handle authentication frame in AP mode (59 instructions in blob).
  ## a0 = RX frame descriptor (param).
  ## Flow:
  ##   1. Read vifIdx from param[8]; if 0xFF, return.
  ##   2. Compute VIF entry: vif_info_tab + vifIdx * 1512.
  ##   3. Get STA MAC from param+42.
  ##   4. Look up station by MAC; if not found, try to add one.
  ##   5. Check how many STAs are associated. If > 1, update VIF[338] (STA count)
  ##      and ensure channel context via vif[64].
  ##   6. Tail-call apm_send_mlme(vifEntry, 0xB0, macAddr, nil, nil, nil) to send
  ##      auth response (frame type 0xB0 = authentication = 176).
  let pBase = cast[uint](param)
  let vifIdx = cast[ptr uint8](pBase + 8)[]
  if vifIdx == 0xFF:
    return

  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let staMac = cast[pointer](pBase + 42)

  # Look up STA by MAC address via HW search
  let staIdx = hal_machw_search_addr(staMac, 0)

  if staIdx != 0xFF:
    # Station exists: delete it before re-adding
    apm_sta_delete(staMac)

  # Get channel context count
  let ctxtCnt = chan_ctxt_cnt()
  if ctxtCnt > 1:
    # Store 1 to vifEntry+338, trigger channel context
    let chanCtxt = cast[ptr pointer](vifEntry + 64)[]
    cast[ptr uint8](vifEntry + 338)[] = 1
    chan_ctxt_trigger(chanCtxt)

  # Send authentication response frame: tail-call apm_send_mlme
  apm_send_mlme(cast[pointer](vifEntry), 0xB0, staMac, nil, nil, nil)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void apm_assoc_req_handler(void*,unsigned long);".}
proc apm_assoc_req_handler*(param: pointer, reassoc: uint32 = 0) {.exportc, cdecl.} =
  ## Handle AP-mode association request (470 instructions in blob).
  ## Parses Assoc/Reassoc Request, validates rates/security, builds
  ## APM_STA_ADD_IND message, manages apm_env STA slots, and sends
  ## association response via apm_send_mlme with TX confirm callback.
  ## Second parameter reassoc: 0=assoc, 1=reassoc (passed by dispatcher).
  let pBase = cast[uint](param)
  let vifIdx = cast[ptr uint8](pBase + 8)[]
  if vifIdx == 0xFF: return

  let staMac = cast[pointer](pBase + 42)
  let apmBase = cast[uint](addr apm_env[0])
  let logFn204 = getLogFunc(204)

  # Debug log: MAC address at line 501 (blob: jalr t1 at 0x7C)
  if logFn204 != nil:
    let m = cast[ptr UncheckedArray[uint8]](staMac)
    logFn204(2, 0, cast[pointer](cstring"apm.c"), 501,
      m[0].uint32, m[1].uint32, m[2].uint32,
      m[3].uint32, m[4].uint32, m[5].uint32)

  # Search apm_env for existing entry with matching MAC (blob: loop at 0x8A-0x94)
  # 5 entries, stride 16 bytes; active flag at +104, MAC at +92
  for i in 0'u ..< 5'u:
    let entryOff = apmBase + i * 16
    if cast[ptr uint8](entryOff + 104)[] != 0:
      if c_memcmp(cast[pointer](entryOff + 92), staMac, 6) == 0:
        # Duplicate STA found: log at line 852 via g_bl_ops_funcs[4] and return
        let warnFn = getLogFunc(4)
        if warnFn != nil:
          warnFn(cast[uint32](cast[uint](cstring"apm duplicate")),
            cast[uint32](cast[uint](cstring"apm.c")), cast[pointer](852), 0)
        return

  # Alloc APM_STA_ADD_IND (88 bytes)
  let msg = ke_msg_alloc(APM_STA_ADD_IND, TASK_API, TASK_APM, 88)
  if msg == nil: return
  let mb = cast[uint](msg)
  discard c_memset(msg, 0, 88)
  discard c_memcpy(msg, staMac, 6)
  cast[ptr uint8](mb + 73)[] = vifIdx
  cast[ptr uint32](mb + 76)[] = cast[ptr uint32](pBase + 16)[]
  cast[ptr uint32](mb + 80)[] = cast[ptr uint32](pBase + 20)[]
  cast[ptr uint8](mb + 84)[] = cast[ptr uint8](pBase + 24)[]
  cast[ptr uint8](mb + 85)[] = cast[ptr uint8](pBase + 28)[]

  # Debug logs for msg fields (blob: 5 calls at lines 864-868 via g_bl_ops_funcs[204])
  if logFn204 != nil:
    logFn204(2, 0, cast[pointer](cstring"apm.c"), 864)
    logFn204(2, 0, cast[pointer](cstring"apm.c"), 865, cast[ptr uint32](mb + 76)[])
    logFn204(2, 0, cast[pointer](cstring"apm.c"), 866, cast[ptr uint32](mb + 80)[])
    logFn204(2, 0, cast[pointer](cstring"apm.c"), 867, cast[ptr uint8](mb + 84)[].uint32)
    logFn204(2, 0, cast[pointer](cstring"apm.c"), 868, cast[ptr uint8](mb + 85)[].uint32)

  # Determine assoc vs reassoc from parameter; compute IE body
  let rawLen0 = cast[ptr uint8](pBase + 58)[]
  let rawLen1 = cast[ptr uint8](pBase + 59)[]
  let totalIeLen = rawLen0.uint16 or (rawLen1.uint16 shl 8)
  var iePtr: pointer; var ieLen: uint32
  if reassoc != 0:
    iePtr = cast[pointer](pBase + 66)
    ieLen = if totalIeLen > 34: totalIeLen.uint32 - 34 else: 0'u32
  else:
    iePtr = cast[pointer](pBase + 60)
    ieLen = if totalIeLen > 28: totalIeLen.uint32 - 28 else: 0'u32

  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifOff = vifIdx.uint * VIF_ENTRY_SIZE
  let vif = vifBase + vifOff
  let vifMaxRate = cast[ptr uint16](vif + 518)[]

  var status: uint8 = 0

  # Parse SSID (id=0) and validate against AP config (blob: mac_ie_find + memcmp at 0x218/0x278)
  let ssidIe = mac_ie_find(iePtr, ieLen, 0)
  if ssidIe != nil:
    let ssidLen = cast[ptr uint8](cast[uint](ssidIe) + 1)[]
    let vifSsidLen = cast[ptr uint8](vif + 520)[]
    if ssidLen != vifSsidLen or
       c_memcmp(cast[pointer](cast[uint](ssidIe) + 2),
                cast[pointer](vif + 521), ssidLen.csize_t) != 0:
      status = 12  # SSID mismatch

  # Parse Supported Rates (id=1) and check against VIF max
  let ratesIe = mac_ie_find(iePtr, ieLen, 1)
  if ratesIe != nil:
    let rLen = cast[ptr uint8](cast[uint](ratesIe) + 1)[]
    if rLen.uint16 > vifMaxRate: status = 18

  # Build rate accumulator
  var rateBuf {.noinit.}: array[49, uint8]
  rateBuf[0] = 0
  if ratesIe != nil:
    let rLen = cast[ptr uint8](cast[uint](ratesIe) + 1)[]
    var ri: uint8 = 0
    while ri < rLen:
      rateBuf[0] += 1
      rateBuf[rateBuf[0]] = cast[ptr uint8](cast[uint](ratesIe) + 2 + ri.uint)[]
      ri += 1

  # Parse Extended Rates (id=50)
  let extIe = mac_ie_find(iePtr, ieLen, 50)
  if extIe != nil:
    let eLen = cast[ptr uint8](cast[uint](extIe) + 1)[]
    var ei: uint8 = 0
    while ei < eLen:
      rateBuf[0] += 1
      rateBuf[rateBuf[0]] = cast[ptr uint8](cast[uint](extIe) + 2 + ei.uint)[]
      ei += 1
  cast[ptr uint8](mb + 6)[] = rateBuf[0]

  # Check rates against VIF supported set at vif+436
  let vifRateCount = cast[ptr uint8](vif + 436)[]
  var rI: uint8 = 0
  while rI < vifRateCount:
    let vr = cast[ptr uint8](vif + 437 + rI.uint)[]
    var fnd = false
    for j in 1'u8 .. rateBuf[0]:
      if (rateBuf[j] and 0x7F) == (vr and 0x7F):
        fnd = true; break
    if not fnd and (cast[int8](vr) < 0):
      status = 18; break
    if fnd:
      let cnt = cast[ptr uint8](mb + 6)[]
      cast[ptr uint8](mb + 7 + cnt.uint)[] = vr
      cast[ptr uint8](mb + 6)[] = cnt + 1
    rI += 1

  # Parse HT Capabilities (id=45)
  let htIe = mac_ie_find(iePtr, ieLen, 45)
  if htIe != nil:
    let htLen = cast[ptr uint8](cast[uint](htIe) + 1)[]
    if htLen >= 26:
      let hc0 = cast[ptr uint8](cast[uint](htIe) + 2)[]
      let hc1 = cast[ptr uint8](cast[uint](htIe) + 3)[]
      cast[ptr uint16](mb + 20)[] = hc0.uint16 or (hc1.uint16 shl 8)
      let he0 = cast[ptr uint8](cast[uint](htIe) + 21)[]
      let he1 = cast[ptr uint8](cast[uint](htIe) + 22)[]
      cast[ptr uint16](mb + 40)[] = he0.uint16 or (he1.uint16 shl 8)
      let tf0 = cast[ptr uint8](cast[uint](htIe) + 23)[]
      let tf1 = cast[ptr uint8](cast[uint](htIe) + 24)[]
      cast[ptr uint32](mb + 44)[] = tf0.uint32 or (tf1.uint32 shl 8)
      cast[ptr uint8](mb + 48)[] = cast[ptr uint8](cast[uint](htIe) + 27)[]
      cast[ptr uint32](mb + 64)[] = cast[ptr uint32](mb + 64)[] or 2

  # NOTE: Blob does NOT search for QoS (id=4) or VHT (id=191) in apm_assoc_req_handler.
  # Those IEs are handled by the host driver after receiving APM_STA_ADD_IND.

  # Build rate bitfield from parsed rates (blob: call me_legacy_rate_bitfield_build)
  let rateBitfield = me_legacy_rate_bitfield_build(cast[pointer](addr rateBuf[0]), rateBuf[0])
  cast[ptr uint32](mb + 56)[] = rateBitfield

  # Check RSN/security: blob only validates the IE exists (via
  # mac_ie_find/mac_vsie_find) but does NOT memcmp the IE body against
  # the VIF template. Removing the spurious memcmp to match blob's
  # 3-site memcmp count.
  let vifSec = cast[ptr uint32](vif + 172)[]
  if vifSec != 0:
    let rsnIe = mac_ie_find(iePtr, ieLen, 48)
    if rsnIe == nil:
      let wpaOui = cast[pointer](addr WPA_OUI[0])
      let wpaIe = mac_vsie_find(iePtr, ieLen, wpaOui, 4)
      if wpaIe == nil:
        status = 40
  else:
    cast[ptr uint16](mb + 68)[] = 0

  # Check STA limit against apm_env counters (blob: lbu at 87(s4), 88(s4) where s4=apm_env)
  let curSta = apm_env[87]
  let maxSta = apm_env[88]
  if curSta >= maxSta: status = 17

  # apm_env STA slot management (blob: 0x3BC-0x5A6)
  # Only entered when status == 0 (STA limit not exceeded, rates/security OK)
  var aidIdx: int = -1
  if status == 0:
    # Translate rate for message (blob: me_rate_translate)
    let translatedRate = me_rate_translate(rateBitfield)
    cast[ptr uint32](mb + 60)[] = translatedRate

    # Debug log: MAC address at line 525 (blob: jalr t1 at 0x400)
    if logFn204 != nil:
      let m = cast[ptr UncheckedArray[uint8]](staMac)
      logFn204(2, 0, cast[pointer](cstring"apm.c"), 525,
        m[0].uint32, m[1].uint32, m[2].uint32,
        m[3].uint32, m[4].uint32, m[5].uint32)

    # Search apm_env for existing STA entry (blob: loop at 0x406-0x530)
    for i in 0 ..< 5:
      let entryOff = apmBase + i.uint * 16
      if cast[ptr uint8](entryOff + 104)[] == 0:
        continue
      if c_memcmp(cast[pointer](entryOff + 92), staMac, 6) == 0:
        # Found existing entry: log at line 536 and mark connected
        if logFn204 != nil:
          logFn204(2, 0, cast[pointer](cstring"apm.c"), 536, i.uint32)
        let slotBase = apmBase + (i.uint + 5) * 16
        cast[ptr uint8](slotBase + 24)[] = 1  # mark connected
        aidIdx = i
        break

    if aidIdx < 0:
      # No existing entry: find a free slot (blob: loop .L201 at 0x536)
      for i in 0 ..< 5:
        let entryOff = apmBase + i.uint * 16
        if cast[ptr uint8](entryOff + 104)[] == 0:
          # Free slot found: memcpy MAC, set flags, store msg ptr, incr count
          let slotBase = apmBase + (i.uint + 5) * 16
          discard c_memcpy(cast[pointer](slotBase + 12), staMac, 6)  # blob: memcpy at 0x568
          cast[ptr uint8](slotBase + 24)[] = 1  # mark connected
          cast[ptr uint32](slotBase + 20)[] = cast[uint32](mb)  # store msg pointer
          apm_env[87] = apm_env[87] + 1  # increment STA count
          # Debug log: slot index at line 560 (blob: jalr a6 at 0x5A4)
          if logFn204 != nil:
            logFn204(2, 0, cast[pointer](cstring"apm.c"), 560, i.uint32)
          aidIdx = i
          break

    if aidIdx < 0:
      # All STA slots full
      status = 17

  # Store AID in message (blob: sh at 0x45A, AID = index + 1)
  if aidIdx >= 0:
    cast[ptr uint16](mb + 68)[] = (aidIdx + 1).uint16

  # Debug log: final status at line 1023 (blob: jalr a6 at 0x47A)
  if logFn204 != nil:
    logFn204(2, 0, cast[pointer](cstring"apm.c"), 1023, status.uint32)

  if status != 0:
    cast[ptr uint8](mb + 72)[] = status

  # Send association/reassociation response via apm_send_mlme (blob: call at 0x23E)
  # Blob always sends regardless of status; passes apm_tx_cfm_handler as callback
  # and msg as callbackArg. The TX confirm handler sends or frees the msg.
  let vifPtr = cast[pointer](vif)
  let frameType: uint16 = if reassoc != 0: 0x30'u16 else: 0x10'u16
  apm_send_mlme(vifPtr, frameType, staMac,
    cast[pointer](apm_tx_cfm_handler), msg, nil)

proc apm_deauth_handler*(param: pointer) {.exportc, cdecl.} =
  ## Handle deauthentication frame in AP mode (similar structure to disassoc, ~50 instrs).
  ## Nearly identical to apm_disassoc_handler but uses type=2 (deauth).
  ##
  ## a0 = RX frame descriptor (param).
  ## Flow:
  ##   1. Read vifIdx from param[8]; if 0xFF, return.
  ##   2. Read staIdx from param[7]; if 0xFF, return.
  ##   3. Extract reason code from param[56..57] (LE16).
  ##   4. Log at line 1054 with reason code.
  ##   5. Get STA MAC from param+42.
  ##   6. Tail-call apm_sta_delete(staIdx, macAddr, 2, reason) to remove STA.
  let pBase = cast[uint](param)
  let vifIdx = cast[ptr uint8](pBase + 8)[]
  if vifIdx == 0xFF:
    return
  let staIdx = cast[ptr uint8](pBase + 7)[]
  if staIdx == 0xFF:
    return

  # Extract reason code from param[56..57] (LE16)
  let reasonLo = cast[ptr uint8](pBase + 56)[].uint16
  let reasonHi = cast[ptr uint8](pBase + 57)[].uint16
  let reason = (reasonHi shl 8) or reasonLo

  # Log
  let logFn = getLogFunc(4)
  if logFn != nil:
    logFn(2, 0, nil, 1054, reason.uint32)

  let staMac = cast[pointer](pBase + 42)

  # Remove station: blob tail-calls apm_sta_delete(packed args)
  # Blob ABI: a0=staIdx|reason<<8|type<<16, passes as single packed pointer arg
  apm_sta_delete(cast[pointer](staIdx.uint or (2'u shl 16) or (reason.uint shl 8)))

proc apm_disassoc_handler*(param: pointer) {.exportc, cdecl.} =
  ## Handle disassociation frame in AP mode (58 instructions in blob).
  ## Very similar to apm_deauth_handler but uses frame type 0xC0 (disassoc)
  ## and passes type=3 to the station delete function.
  ##
  ## a0 = RX frame descriptor (param).
  ## Flow:
  ##   1. Read vifIdx from param[8]; if 0xFF, return.
  ##   2. Read staIdx from param[7]; if 0xFF, return.
  ##   3. Extract reason code from param[56..57] (LE16).
  ##   4. Log at line 1074 with reason code.
  ##   5. Compute VIF entry from vifIdx (vif_info_tab + vifIdx * 1512).
  ##   6. Get STA MAC from param+42.
  ##   7. Call apm_send_mlme(vifEntry, 0xC0, macAddr, nil, nil, nil) to send
  ##      disassociation response.
  ##   8. Tail-call apm_sta_delete(staIdx, macAddr, 3, reason) to remove STA.
  let pBase = cast[uint](param)
  let vifIdx = cast[ptr uint8](pBase + 8)[]
  if vifIdx == 0xFF:
    return
  let staIdx = cast[ptr uint8](pBase + 7)[]
  if staIdx == 0xFF:
    return

  # Extract reason code from param[56..57] (LE16)
  let reasonLo = cast[ptr uint8](pBase + 56)[].uint16
  let reasonHi = cast[ptr uint8](pBase + 57)[].uint16
  let reason = (reasonHi shl 8) or reasonLo

  # Log
  let logFn = getLogFunc(4)
  if logFn != nil:
    logFn(2, 0, nil, 1074, reason.uint32)

  # Compute VIF entry
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = cast[pointer](vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint)
  let staMac = cast[pointer](pBase + 42)

  # Send disassociation response
  apm_send_mlme(vifEntry, 0xC0, staMac, nil, nil, nil)

  # Remove station: blob tail-calls apm_sta_delete(packed args)
  apm_sta_delete(cast[pointer](staIdx.uint or (3'u shl 16) or (reason.uint shl 8)))

proc apm_beacon_handler*(param: pointer) {.exportc, cdecl, noinline.} =
  ## Handle beacon reception in AP mode.
  ## noinline + asm barrier: blob calls this as a real function from
  ## rxu_mgt_ind_handler/rxu_mgt_ind_handler_apm; without the barrier GCC
  ## elides the call because the body is a no-op.
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}

proc apm_embedded_enabled*(vifEntry: pointer): bool {.exportc, cdecl, noinline.} =
  ## Check if embedded AP mode is enabled for given VIF entry.
  ## From blob (12 instrs): if vifEntry is NULL, return hostapd_enabled & 1.
  ## Otherwise, check if vifType (offset 86) == 2 (AP mode); if so return
  ## hostapd_enabled & 1, else return 0.
  ## noinline + asm barrier: callers use `discard apm_embedded_enabled(...)`
  ## or call with nil in some branches; without the barrier GCC elides the
  ## call because the return value is unused and the body is side-effect-free.
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}
  if vifEntry == nil:
    return (hostapd_enabled and 1) != 0
  let vifType = cast[ptr uint8](cast[uint](vifEntry) + 86)[]
  if vifType == 2:
    return (hostapd_enabled and 1) != 0
  return false

proc apm_get_hostapd_ctx*(): pointer {.exportc, cdecl, noinline.} =
  ## Get hostapd context pointer from apm_env[172] (blob layout; not a
  ## separate global). Previous Nim read a separate Nim-only `hostapd_ctx`
  ## global that is never written by the firmware, so always returned nil.
  ## Blob: `auipc+lw of apm_env+0xac; ret`.
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}
  return cast[ptr pointer](cast[uint](addr apm_env[0]) + 0xAC)[]

proc apm_handle_eapol_input*(staIdx: uint8, rxBuf: pointer, rxLen: uint32) {.exportc, cdecl.} =
  ## Handle EAPOL input in AP mode.
  ## From blob (17 instrs): checks hostapd_ctx; if NULL, returns immediately.
  ## Otherwise, computes STA entry from staIdx, then VIF entry from STA instNbr
  ## vif_info_tab + instNbr * VIF_ENTRY_SIZE. Loads the hostapd_ops callback
  ## table, extracts the EAPOL RX handler at offset 44 of the ops struct, and
  ## calls it with (apm_env[172], vif->hostapd_priv, rxBuf, rxLen).
  let hostapdCtx = cast[ptr pointer](cast[uint](addr apm_env[0]) + 0xAC)[]
  if hostapdCtx == nil:
    return
  let staBase = cast[uint](addr sta_info_tab[0])
  let staU = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let instNbr = cast[ptr uint8](staU + 39)[]
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + instNbr.uint * VIF_ENTRY_SIZE.uint
  # Load hostapd ops table pointer from vif_mgmt_env offset 12
  let opsPtr = cast[ptr pointer](cast[uint](addr vif_mgmt_env[0]) + 12)[]
  if opsPtr == nil: return
  # Get EAPOL RX handler at offset 44 in ops table
  let eapolHandler = cast[ptr pointer](cast[uint](opsPtr) + 44)[]
  if eapolHandler == nil: return
  # Load VIF's hostapd private data from vif+364
  let vifPriv = cast[ptr pointer](vifEntry + 364)[]
  # Call the handler: eapolHandler(hostapd_ctx, vifPriv, rxBuf, rxLen)
  type EapolHandlerFn = proc(ctx: pointer, priv: pointer, buf: pointer, length: uint32) {.cdecl.}
  cast[EapolHandlerFn](eapolHandler)(hostapdCtx, vifPriv, rxBuf, rxLen)

proc apm_handle_auth_done*(param: pointer) {.exportc, cdecl.} =
  ## Handle auth done callback in AP mode.
  ## From blob (7 instrs): param is actually a staIdx (uint8 in a0).
  ## Computes sta_info_tab[staIdx] (stride 368), stores 2 at sta[72] (auth done flag).
  let staIdx = cast[uint](param)
  let staTab = cast[uint](addr sta_info_tab[0])
  let staEntry = staTab + staIdx * STA_ENTRY_SIZE.uint
  cast[ptr uint8](staEntry + 72)[] = 2  # auth done state

proc apm_send_mlme*(vifEntry: pointer, frameType: uint16, destAddr: pointer,
    callback: pointer, callbackArg: pointer, extraParam: pointer) {.exportc, cdecl.} =
  ## Send MLME frame in AP mode (auth response, assoc response, deauth, probe rsp).
  ## From blob (160 instrs): allocates 512-byte frame buffer, builds MAC header
  ## with DA=destAddr, SA=BSSID=vifEntry+80 (AP's own MAC), dispatches on frameType:
  ##   0xB0 (auth):    me_build_authenticate(body, 0, 2, 0, nil)
  ##   0xC0 (deauth):  me_build_deauthenticate(body, reason=extraParam)
  ##   0x50 (probe):   me_build_probe_rsp(body, inst_nbr) + extra IEs
  ##   0x10/0x30 (assoc/reassoc rsp): me_build_associate_rsp(body, inst_nbr, extraParam, callbackArg)
  ## Then sets TX descriptor fields and tail-calls txl_frame_push(frame, 3).
  ## On alloc failure, calls assert_rec then callback(callbackArg, 0x40000000) if set.
  let vifU = cast[uint](vifEntry)

  # Allocate 512-byte frame buffer (blob: txl_frame_get, NOT ke_msg_alloc)
  let frame = txl_frame_get(512)
  if frame == nil:
    if callback != nil:
      type CbFn = proc(arg: pointer, flags: uint32) {.cdecl.}
      cast[CbFn](callback)(callbackArg, 0x40000000'u32)
    return

  let f = cast[uint](frame)

  # Get THD/link descriptor pointer at frame[108]
  let thd = cast[ptr pointer](f + 108)[]
  let thdU = cast[uint](thd)

  # Build MAC header at thd+348
  cast[ptr uint8](thdU + 348)[] = (frameType and 0xFF).uint8
  cast[ptr uint8](thdU + 349)[] = ((frameType shr 8) and 0xFF).uint8
  cast[ptr uint8](thdU + 350)[] = 0  # duration low
  cast[ptr uint8](thdU + 351)[] = 0  # duration high

  # DA = destAddr (6 bytes at thd+352)
  discard c_memcpy(cast[pointer](thdU + 352), destAddr, 6.csize_t)

  # SA = VIF MAC at vifEntry+80 (6 bytes at thd+358)
  let vifMac = cast[pointer](vifU + 80)
  discard c_memcpy(cast[pointer](thdU + 358), vifMac, 6.csize_t)

  # BSSID = VIF MAC (same as SA for AP mode, 6 bytes at thd+364)
  discard c_memcpy(cast[pointer](thdU + 364), vifMac, 6.csize_t)

  # Sequence number: vendor uses the global TX control sequence counter.
  let seqPtr = cast[ptr uint16](cast[uint](addr txl_cntrl_env[0]) + 84)
  var seqNum = seqPtr[]
  seqNum = (seqNum + 1) and 0x0FFF'u16
  seqPtr[] = seqNum
  let seqField = seqNum shl 4
  cast[ptr uint8](thdU + 370)[] = (seqField and 0xFF).uint8
  cast[ptr uint8](thdU + 371)[] = ((seqField shr 8) and 0xFF).uint8

  # Dispatch on frame type to build frame body at thd+372
  let bodyBuf = cast[pointer](thdU + 372)
  let instNbr = cast[ptr uint8](vifU + 87)[]
  var totalLen: uint32 = 24  # default: MAC header only

  if frameType == 0xB0:
    # Auth response: me_build_authenticate(body, algo=0, seq=2, status=0, challenge=nil)
    let bodyLen = me_build_authenticate(bodyBuf, 0, 2, 0, nil)
    totalLen = bodyLen + 24

  elif frameType == 0xC0:
    # Deauth: me_build_deauthenticate(body, reason)
    let reason = cast[uint16](cast[uint](extraParam))
    let bodyLen = me_build_deauthenticate(bodyBuf, reason)
    totalLen = bodyLen + 24

  elif frameType == 0x50:
    # Probe response: me_build_probe_rsp(body, inst_nbr)
    let bodyLen = me_build_probe_rsp(bodyBuf, instNbr, nil)
    totalLen = bodyLen + 24

    # Add customer IEs (blob: me_add_ie_customer at 0x110)
    let custIeLen = me_add_ie_customer(cast[pointer](thdU + 372 + bodyLen.uint))
    totalLen += custIeLen
    # Blob does NOT append extra probe response IEs here — customer IEs
    # are the full append path.

  elif (frameType and (not 0x20'u16)) == 0x10:
    # Assoc response (0x10) or reassoc response (0x30)
    # me_build_associate_rsp(body, inst_nbr, extraParam, callbackArg)
    type BuildAssocRspFn = proc(buf: pointer, vifIdx: uint8, status: pointer,
        extra: pointer): uint32 {.cdecl.}
    let bodyLen = cast[BuildAssocRspFn](me_build_associate_rsp)(
        bodyBuf, instNbr, extraParam, callbackArg)
    totalLen = bodyLen + 24

  # Set TX descriptor fields at frame+112
  let txDesc = cast[ptr pointer](f + 112)[]
  let txDescU = cast[uint](txDesc)
  let baseLen = cast[ptr uint32](txDescU + 20)[]
  cast[ptr uint32](txDescU + 24)[] = baseLen - 1 + totalLen
  cast[ptr uint32](txDescU + 28)[] = totalLen + 4  # include FCS

  # Frame metadata
  cast[ptr uint8](f + 98)[] = 0
  cast[ptr uint8](f + 100)[] = 0
  cast[ptr uint8](f + 47)[] = instNbr
  cast[ptr uint8](f + 49)[] = 0xFF  # no rate override
  cast[ptr uint32](f + 208)[] = cast[uint32](cast[uint](callback))
  cast[ptr uint32](f + 212)[] = cast[uint32](cast[uint](callbackArg))

  # Push frame to TX queue (AC=3, management)
  txl_frame_push(frame, 3)

proc aidListDelete(macAddr: pointer) {.exportc: "aid_list_delete", cdecl, noinline.} =
  ## Compiler-generated helper (blob: _aid_list_delete.isra.0; Nim exports the
  ## parent symbol `aid_list_delete` for 1:1 symbol parity).
  ## Iterates 5 AID entries in apm_env, compares 6-byte MAC addresses.
  ## On match: clears the MAC, calls WPA disconnect callback, decrements STA count.
  ## noinline: blob calls this from both apm_sta_delete and apm_tx_cfm_handler.
  {.emit: "__asm__ volatile(\"\" ::: \"memory\");".}
  let blOps = cast[uint](addr g_bl_ops_funcs)
  let logFn = cast[ptr pointer](blOps + 204)[]
  let apmBase = cast[uint](addr apm_env[0])
  # Log the MAC address (line 471)
  if logFn != nil:
    let m = cast[ptr UncheckedArray[uint8]](macAddr)
    cast[PlatformLogFunc](logFn)(2, 0, nil, 471,
      m[0].uint32, m[1].uint32, m[2].uint32, m[3].uint32, m[4].uint32, m[5].uint32)
  # Search 5 entries (stride 16 bytes from apm_env base)
  for i in 0'u32 ..< 5'u32:
    let entryOff = apmBase + i.uint * 16
    let connFlag = cast[ptr uint8](entryOff + 104)[]
    if connFlag == 0:
      continue
    # Compare 6-byte MAC at entry offset 92
    let entryMac = cast[pointer](entryOff + 92)
    if c_memcmp(entryMac, macAddr, 6) != 0:
      continue
    # Match found: clear the MAC
    discard c_memset(entryMac, 0, 6)
    # Call WPA disconnect callback: wpa_cbs[10] (byte offset 40)
    if wpa_cbs != nil:
      let wpaCbArr = cast[ptr UncheckedArray[pointer]](wpa_cbs)
      let disconnCb = wpaCbArr[10]
      if disconnCb != nil:
        # Load param from apm_env + (i+5)*16 + 20
        let staHandle = cast[ptr pointer](apmBase + (i + 5) * 16 + 20)[]
        cast[proc(p: pointer) {.cdecl.}](disconnCb)(staHandle)
    # Clear connected byte at apm_env + (i+5)*16 + 24
    cast[ptr uint8](apmBase + (i + 5) * 16 + 24)[] = 0
    # Decrement STA count
    let cnt = apm_env[87]
    apm_env[87] = cnt - 1
    # Log deletion (line 487)
    if logFn != nil:
      cast[PlatformLogFunc](logFn)(2, 0, nil, 487, i.uint32)
    return
  # No match found: log (line 491)
  if logFn != nil:
    cast[PlatformLogFunc](logFn)(2, 0, nil, 491)

proc apm_tx_cfm_handler*(param: pointer) {.exportc, cdecl.} =
  ## Handle TX confirmation in AP mode (31 instrs).
  ## From blob: a0=txDesc, a1=txStatus. Checks bit 23 (0x00800000) of txStatus:
  ##   If set (retry/failure) and pendingCount != 0: tail-call ke_msg_send(txDesc).
  ##   If set and pendingCount == 0: tail-call ke_msg_free(txDesc - 12).
  ##   If not set (success) and pendingCount != 0: call _aid_list_delete(txDesc).
  ##   Then call g_bl_ops_funcs[1] TX confirm callback with string and counts.
  var txStatus: uint32
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", txStatus, ") );"].}
  let td = cast[uint](param)
  let pendingCount = cast[ptr uint16](td + 68)[]
  if (txStatus and 0x00800000'u32) != 0:
    # TX retry/failure path
    if pendingCount != 0:
      ke_msg_send(param)
    else:
      ke_msg_free(cast[pointer](td - 12))
  else:
    # TX success path
    if pendingCount != 0:
      aidListDelete(param)
    # Call TX confirm callback via g_bl_ops_funcs[1] (byte offset 4)
    let pendingCount2 = cast[ptr uint16](td + 68)[]  # reload after aidListDelete
    let txCfmCb = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 4)[]
    if txCfmCb != nil:
      cast[proc(a: pointer, b: uint32, c: uint32) {.cdecl.}](txCfmCb)(
        param, txStatus, pendingCount2.uint32)

proc apm_tx_int_ps_check*(txDesc: pointer): bool {.exportc, cdecl.} =
  ## Check if station requires PS postpone (AP-side TX path).
  ## From blob (54 instrs): reads txDesc fields, loads STA and VIF entries,
  ## checks if VIF is in AP mode (type==2), STA is in PS state, and frame
  ## is not a bufferable management frame (subtype <= 6). If all conditions
  ## met and STA TIM bit is clear, sets the PS-poll flag in the STA's
  ## postpone bitmap and returns false (don't transmit). Returns true (OK to TX)
  ## in all other cases.
  let td = cast[uint](txDesc)
  let staDlPolicy = cast[ptr uint8](td + 47)[]  # STA delivery policy

  # Check active channel contexts (blob: chan_ctxt_cnt, not ke_state_get)
  let ctxtCount = chan_ctxt_cnt()
  if ctxtCount <= 1:
    return true  # APM not active, allow TX

  # Check STA entry: offset 4 = next ptr, offset 32 = rate info
  let staPeerPtr = cast[ptr pointer](td + 4)[]
  if staPeerPtr == nil:
    return true
  let staPeerU = cast[uint](staPeerPtr)
  let staRateInfo = cast[ptr uint16](staPeerU + 32)[]
  if staRateInfo != 0:
    return true

  # Load STA's TX descriptor at offset 108
  let staDescPtr = cast[ptr pointer](td + 108)[]
  if staDescPtr == nil:
    return true
  let descU = cast[uint](staDescPtr)

  # Check frame type (TID descriptor offsets 348-349)
  let ftype0 = cast[ptr uint8](descU + 348)[]
  let ftype1 = cast[ptr uint8](descU + 349)[]
  let frameType = ftype0.uint16 or (ftype1.uint16 shl 8)
  if frameType == 0xC4:
    return true  # Control frame, allow TX

  # Look up VIF entry
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifType = cast[ptr uint8](vifBase + 86)[]
  if vifType != 2:
    return true  # Not AP mode

  # Check STA subtype
  let staSubtype = cast[ptr uint8](td + 49)[]
  if staSubtype > 6:
    return true

  # Look up STA entry from sta_info_tab
  let staBase = cast[uint](addr sta_info_tab[0])
  let staInstNbr = cast[ptr uint8](td + 39)[]

  # Check PS state at STA entry offset 41
  let staEntry = staBase + staInstNbr.uint * STA_ENTRY_SIZE.uint
  let psState = cast[ptr uint8](staEntry + 41)[]
  if psState != 1:
    return true

  # Check STA's postpone state bits at offset 48
  let postponeBits = cast[ptr uint16](td + 50)[]
  if (postponeBits and 3) != 0:
    return true

  # Set PS-poll flag in STA's postpone bitmap
  let curBits = cast[ptr uint16](td + 50)[]
  cast[ptr uint16](td + 50)[] = curBits or 0x1000
  return false

proc apm_tx_int_ps_postpone*(txDesc: pointer, staEntry: pointer) {.exportc, cdecl.} =
  ## Postpone TX for PS station (47 instrs).
  ## From blob: a0=txDesc (VIF entry), a1=staEntry. Checks txDesc+50 (halfword)
  ## bit 12 (0x1000) set. If not, returns. Reads STA delivery mask from a1+314,
  ## computes AND with txDesc[46] (AC/TID). If match, checks staEntry+73 bits.
  ## Sets bit 3 (0x08) or bit 1 (0x02) in staEntry+73 depending on delivery type.
  ## If bit was already set, returns. Otherwise stores updated flags.
  ## If all delivery bits match (mask==0xF), allocates ke_msg for TIM update.
  let td = cast[uint](txDesc)  # blob passes txDesc as a0
  let sta = cast[uint](staEntry)  # blob passes staEntry as a1
  # Check postpone flag at txDesc+50
  let postponeFlags = cast[ptr uint16](td + 50)[]
  if (postponeFlags and 0x1000) == 0:
    return
  # Read delivery mask and TID
  let delivMask = cast[ptr uint8](sta + 314)[]
  let tid = cast[ptr uint8](td + 46)[]
  let tidMatch = tid and delivMask
  let psFlags = cast[ptr uint8](sta + 73)[]
  if tidMatch != 0:
    # UAPSD delivery
    if (psFlags and 0x08) != 0:
      return  # already set
    cast[ptr uint8](sta + 73)[] = psFlags or 0x08
  else:
    # Legacy PS delivery
    if (psFlags and 0x02) != 0:
      return  # already set
    cast[ptr uint8](sta + 73)[] = psFlags or 0x02
  # Check if all delivery bits now active -> send TIM update
  let updatedFlags = cast[ptr uint8](sta + 73)[]
  let allMask = delivMask and cast[ptr uint8](td + 46)[]
  if allMask == 0x0F or updatedFlags == 0x0F:
    let msg = ke_msg_alloc(47, TASK_MM, TASK_APM, 4)  # MM_TIM_UPDATE pseudo-msg
    if msg != nil:
      let m = cast[uint](msg)
      cast[ptr uint16](m)[] = cast[ptr uint16](sta + 36)[]  # AID
      cast[ptr uint8](m + 3)[] = cast[ptr uint8](sta + 39)[]  # inst nbr
      cast[ptr uint8](m + 2)[] = 1  # set TIM bit
      ke_msg_send(msg)

proc apm_tx_int_ps_get_postpone*(vifEntry: pointer, staEntry: pointer, postponeFlag: ptr uint32): pointer {.exportc, cdecl.} =
  ## Get postponed TX frame for PS station.
  ## From blob (124 instrs): VIF AP mode check, walks STA postponed list
  ## (sta+356), matches TID against delivery mask, removes and returns frame.
  let vif = cast[uint](vifEntry)
  let sta = cast[uint](staEntry)
  let vifType = cast[ptr uint8](vif + 86)[]
  if vifType != 2:
    postponeFlag[] = 0; return nil
  let psStatus = cast[ptr uint32](sta + 48)[]
  if psStatus == 0:
    postponeFlag[] = 0; return nil
  var psMask, checkMask: uint8
  if (psStatus and 1) != 0:
    psMask = 1; checkMask = 2
  else:
    psMask = 4; checkMask = 8
  let staFlags = cast[ptr uint8](sta + 73)[]
  if (staFlags and checkMask) == 0:
    postponeFlag[] = 1; return nil
  let delivMask = cast[ptr uint8](sta + 314)[]
  var cur = cast[ptr pointer](sta + 356)[]
  var prev: pointer = nil
  let psCheckSeqz = cast[uint32](if (psStatus - 2) == 0: 1 else: 0)
  while true:
    if cur == nil:
      assert_warn("apm.c", "apm.c", 377)
      postponeFlag[] = 1; return nil
    let curU = cast[uint](cur)
    let frameTid = cast[ptr uint8](curU + 46)[]
    let tidMatch = frameTid and delivMask
    let tidSeqz = cast[uint32](if tidMatch == 0: 1 else: 0)
    if tidSeqz != psCheckSeqz:
      co_list_remove(cast[ptr CoList](sta + 356), cast[ptr CoListHdr](prev), cast[ptr CoListHdr](cur))
      cast[ptr uint8](curU + 46)[] = cast[uint8]((psStatus and 3) + 3)
      var nextScan = if prev != nil: cast[ptr pointer](cast[uint](prev))[] else: cast[ptr pointer](sta + 356)[]
      var hasMore = false
      var scan = nextScan
      while scan != nil:
        let sU = cast[uint](scan)
        let sTid = cast[ptr uint8](sU + 46)[]
        let sSeqz = cast[uint32](if (sTid and delivMask) == 0: 1 else: 0)
        let sChk = cast[uint32](if (cast[ptr uint32](sta + 48)[] - 2) == 0: 1 else: 0)
        if sSeqz != sChk:
          hasMore = true; break
        scan = cast[ptr pointer](sU)[]
      if not hasMore:
        var nf = staFlags and (not checkMask)
        cast[ptr uint8](sta + 73)[] = nf
        if (nf and psMask) == 0:
          let tm = ke_msg_alloc(MM_TIM_UPDATE_REQ, TASK_MM, TASK_APM, 4)
          if tm != nil:
            let tmU = cast[uint](tm)
            cast[ptr uint16](tmU)[] = cast[ptr uint16](sta + 36)[]
            cast[ptr uint8](tmU + 2)[] = 0
            cast[ptr uint8](tmU + 3)[] = cast[ptr uint8](sta + 39)[]
            ke_msg_send(tm)
      return cur
    prev = cur
    cur = cast[ptr pointer](curU)[]

proc apm_tx_int_ps_clear*(staIdx: uint8) {.exportc, cdecl.} =
  ## Clear PS postpone buffer for station (41 instrs).
  ## From blob: a0=vifEntry. Checks vifEntry+86 (type) == 2 (AP mode).
  ## If not AP, returns. Computes STA entry = sta_info_tab + staIdx*368
  ## (where staIdx comes from vifEntry context). Checks staEntry+73 (PS flags)
  ## bits [1,3] (0x0A). If zero, returns. Clears bits (AND 0xF5), stores.
  ## If result is zero, allocates ke_msg for TIM update (clear bit).
  ## msg[0..1] = sta+36 (AID), msg[2] = 0 (clear), msg[3] = sta+39 (inst).
  ## Tail-calls ke_msg_send.
  let vifEntry = cast[uint](cast[pointer](staIdx))  # blob passes vifEntry as a0
  let vifType = cast[ptr uint8](vifEntry + 86)[]
  if vifType != 2:
    return  # Not AP mode
  # Compute STA entry from staIdx stored in context
  let staBase = cast[uint](addr sta_info_tab[0])
  # staIdx is actually passed differently; in the blob, the STA is computed
  # from the vifEntry. Use the first linked STA.
  var staIdx2: uint8
  {.emit: ["asm volatile(\"\" : : );"].}  # prevent optimization
  # Read PS flags from sta entry
  let psFlags = cast[ptr uint8](vifEntry + 73)[]
  if (psFlags and 0x0A) == 0:
    return
  # Clear PS bits
  let newFlags = psFlags and 0xF5'u8
  cast[ptr uint8](vifEntry + 73)[] = newFlags
  # Send any postponed frames (blob: sta_mgmt_send_postponed_frame at 0x24)
  let vifPtr = cast[pointer](vifEntry)
  let staPtr = cast[pointer](vifEntry)  # STA entry overlaps in blob's context
  discard sta_mgmt_send_postponed_frame(vifPtr, staPtr, 0)
  if newFlags != 0:
    return
  # All PS cleared: send TIM update to clear TIM bit
  let msg = ke_msg_alloc(47, TASK_MM, TASK_APM, 4)
  if msg != nil:
    let m = cast[uint](msg)
    cast[ptr uint16](m)[] = cast[ptr uint16](vifEntry + 36)[]  # AID
    cast[ptr uint8](m + 2)[] = 0  # clear TIM
    cast[ptr uint8](m + 3)[] = cast[ptr uint8](vifEntry + 39)[]  # inst nbr
    ke_msg_send(msg)

# ###########################################################################
#                   ME: Management Entity
# ###########################################################################

proc me_init*() {.exportc, cdecl.} =
  ## Initialize management entity. Blob:
  ##   memset(me_env, 0, 136)
  ##   ke_state_set(TASK_ME=3, 0)
  ##   scanu_init(); apm_init(); sm_init(); bam_init()
  discard c_memset(addr me_env[0], 0, 136.csize_t)
  ke_state_set(TASK_ME, 0)
  nimFwTrace("[WIFI-NIMFW] scanu_init begin")
  scanu_init()
  nimFwTrace("[WIFI-NIMFW] scanu_init done")
  nimFwTrace("[WIFI-NIMFW] apm_init begin")
  apm_init()
  nimFwTrace("[WIFI-NIMFW] apm_init done")
  nimFwTrace("[WIFI-NIMFW] sm_init begin")
  sm_init()
  nimFwTrace("[WIFI-NIMFW] sm_init done")
  nimFwTrace("[WIFI-NIMFW] bam_init begin")
  bam_init()
  nimFwTrace("[WIFI-NIMFW] bam_init done")

proc me_init_rate*(staEntry: pointer) {.exportc, cdecl.} =
  ## Initialize rate control for a station.
  ## Blob ABI passes a sta_info_tag pointer through to rc_init, then reuses the
  ## same pointer for me_update_buffer_control.
  rc_init(staEntry)
  discard me_update_buffer_control(staEntry)

proc me_init_bcmc_rate*(staEntry: pointer) {.exportc, cdecl.} =
  ## Initialize broadcast/multicast rate for a station entry.
  ## From blob (35 instrs): a0 is a sta_info_tag pointer.
  ## Loads rate count from sta+248, asserts non-zero.
  ## Loops over rates at sta+249, finds max rate (masking bit 7).
  ## Calls me_rate_translate(maxRate), then rc_init_bcmc_rate(sta, rateIdx).
  ## Clears sta+334 (RC flags byte).
  let sta = staEntry
  let staU = cast[uint](sta)
  let rateCount = cast[ptr uint8](staU + 248)[]
  if rateCount == 0:
    assert_err("me.c", "me.c", 510)
  # Loop scanning rates at sta+249, find max rate (masking bit 7)
  var maxRate: uint32 = 0
  var i: uint32 = 0
  let rateCountU = rateCount.uint32
  while i < rateCountU:
    let rate = cast[ptr uint8](staU + 249 + i)[]
    let unmasked = rate.uint32 and 0x7F'u32
    if unmasked > maxRate:
      maxRate = rate.uint32 and 0x7F'u32
    inc i
  # Convert max rate to rate index, then set bcmc rate
  # Blob: mv a1,a0 (rateIdx); mv a0,s0 (sta); call rc_init_bcmc_rate
  let rateIdx = me_rate_translate(maxRate)  # blob: me_rate_translate (not me_legacy_ridx_min)
  rc_init_bcmc_rate(sta, rateIdx)
  cast[ptr uint8](staU + 334)[] = 0

proc me_add_chan_ctx*(vifIdx: uint8, chanInfo: pointer, primFreq: uint16,
    centerFreq1: uint16, extra: uint8): bool {.exportc, cdecl.} =
  ## Add channel context for ME (58 bytes in blob, 18 instrs).
  ## Blob ABI: a0=vifIdx, a1=chanInfoPtr, a2=primFreq, a3=centerFreq1, a4=extra.
  ## Builds local chan_def struct on stack from chanInfo fields, calls chan_ctxt_add.
  let ciAddr = cast[uint](chanInfo)
  var chanDef {.noinit.}: array[16, uint8]
  chanDef[0] = cast[ptr uint8](ciAddr + 2)[]  # chan_type
  chanDef[1] = extra
  cast[ptr uint16](addr chanDef[2])[] = cast[ptr uint16](ciAddr)[]  # freq from chanInfo
  cast[ptr uint16](addr chanDef[4])[] = primFreq
  cast[ptr uint16](addr chanDef[6])[] = centerFreq1
  chanDef[8] = cast[ptr uint8](ciAddr + 4)[]  # extra byte
  let rc = chan_ctxt_add(cast[pointer](addr chanDef[0]), cast[ptr uint8](vifIdx))
  return rc == 0

proc me_beacon_check*(vifIdx: uint8, frameDesc: pointer, iesBase: pointer) {.exportc, cdecl.} =
  ## Check beacon content for HT/VHT capability changes.
  ## From blob (124 instrs): computes VIF entry from vifIdx, scans IEs in the
  ## beacon frame for HT operation IE and channel info changes. Updates VIF
  ## bandwidth flags and calls sta_mgmt_register if needed.
  ##
  ## a0=vifIdx(->s5), a1=frameDesc (adjusted -36), a2=iesBase (adjusted +36 -> s6)
  let vifTab = cast[uint](addr vif_info_tab[0])
  let staTab = cast[uint](addr sta_info_tab[0])
  let vifEntry = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint

  # Adjust iesBase: blob does a2 += 36
  let iesBuf = cast[pointer](cast[uint](iesBase) + 36)
  # Adjust frameDesc: blob does a1 -= 36
  let frameDescAdj = cast[pointer](cast[uint](frameDesc) - 36)

  # Get current channel context info from VIF
  let chanPtr = cast[ptr pointer](vifEntry + 424)[]
  let chanBand = if chanPtr != nil: cast[ptr uint8](cast[uint](chanPtr) + 2)[] else: 0'u8

  # Save current HT operation params
  let prevSecChan = cast[ptr uint8](vifEntry + 479)[]
  let prevChanWidth = cast[ptr uint8](vifEntry + 480)[]

  # Clear HT operation flags
  cast[ptr uint16](vifEntry + 476)[] = 0

  # Search for HT operation IE (ID=42, length=42) in beacon IEs
  let htOpIe = mac_ie_find(iesBuf, 42, 42)  # IE_ID_HT_OPERATION = 42
  if htOpIe != nil:
    let ieData = cast[uint](htOpIe)
    let htFlags = cast[ptr uint8](ieData + 2)[]
    var bwFlags = cast[ptr uint16](vifEntry + 476)[]
    bwFlags = bwFlags and 0xFFF8'u16  # clear lower 3 bits

    # Check secondary channel offset (bit 0)
    if (htFlags and 1) != 0:
      bwFlags = bwFlags or 1

    cast[ptr uint16](vifEntry + 476)[] = bwFlags

    # Check STA channel width (bit 1)
    if (htFlags and 2) != 0:
      # Replicate STA channel width flag to VIF entry for the specific vifIdx
      let vifEntryDst = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint
      var dstFlags = cast[ptr uint16](vifEntryDst + 476)[]
      dstFlags = dstFlags or 2
      cast[ptr uint16](vifEntryDst + 476)[] = dstFlags

    # Check RIFS mode (bit 2)
    if (htFlags and 4) != 0:
      let vifEntryDst2 = vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint
      var dstFlags2 = cast[ptr uint16](vifEntryDst2 + 476)[]
      dstFlags2 = dstFlags2 or 4
      cast[ptr uint16](vifEntryDst2 + 476)[] = dstFlags2

  # Call me_extract_power_constraint with (iesBase, ?, staEntry)
  # Blob relocation at 0xb4: me_extract_power_constraint(a0=iesBase, ?, a2=staEntry)
  let staInfoOff = vifIdx.uint * STA_ENTRY_SIZE.uint + 348
  let staInfoBase = staTab + staInfoOff
  me_extract_power_constraint(cast[pointer](iesBuf), 0, cast[pointer](staInfoBase))

  # Check if channel width changed (vif[480])
  let newChanWidth = cast[ptr uint8](vifEntry + 480)[]
  if newChanWidth != prevChanWidth:
    # Channel width changed: compute delta and call tpc_update_vif_tx_power
    # Blob: delta = chanCtx[4] - newChanWidth, stored on stack, passed to tpc_update_vif_tx_power
    if chanPtr != nil:
      let chanBw = cast[ptr uint8](cast[uint](chanPtr) + 4)[]
      var bwDelta: uint8 = chanBw - newChanWidth
      var outParam: uint8
      # tpc_update_vif_tx_power blob ABI: (a0=vifEntry, a1=&delta, a2=&outParam)
      let tpcFn = cast[proc(vif: pointer, delta: pointer, outP: pointer) {.cdecl.}](tpc_update_vif_tx_power)
      tpcFn(cast[pointer](vifEntry), cast[pointer](addr bwDelta), cast[pointer](addr outParam))

  # Check if secondary channel offset increased (vif[479])
  let newSecChan = cast[ptr uint8](vifEntry + 479)[]
  if prevSecChan < newSecChan:
    # prevSecChan < newSecChan: send MM_CHAN_CTXT_UNLINK_CFM (msg ID 41)
    let surveyMsg = ke_msg_alloc(MM_CHAN_CTXT_UNLINK_CFM, TASK_MM, TASK_ME, 12)
    if surveyMsg != nil:
      let sU = cast[uint](surveyMsg)
      let chanCtxt = cast[ptr pointer](vifEntry + 64)[]
      if chanCtxt != nil:
        cast[ptr uint8](sU)[] = cast[ptr uint8](cast[uint](chanCtxt) + 23)[]
      cast[ptr uint8](sU + 2)[] = chanBand
      cast[ptr uint8](sU + 3)[] = cast[ptr uint8](vifEntry + 479)[]
      let chanFreq = if chanPtr != nil: cast[ptr uint16](cast[uint](chanPtr))[] else: 0'u16
      cast[ptr uint16](sU + 4)[] = chanFreq
      cast[ptr uint16](sU + 6)[] = cast[ptr uint16](vifEntry + 428)[]
      cast[ptr uint16](sU + 8)[] = cast[ptr uint16](vifEntry + 430)[]
      let chanCtxt2 = cast[ptr pointer](vifEntry + 64)[]
      if chanCtxt2 != nil:
        cast[ptr uint8](sU + 10)[] = cast[uint8](cast[ptr int8](cast[uint](chanCtxt2) + 12)[])
      ke_msg_send(surveyMsg)

proc me_bw_check*(param: pointer) {.exportc, cdecl.} =
  ## Check bandwidth capabilities.
  ## From blob (7 instrs): param is a sta_info_tag pointer.
  ## Loads rate info pointer from sta+76, reads BW capability half-word,
  ## clears sta+130 and sta+82, stores BW at sta+80.
  let sta = cast[uint](param)
  let rateInfoPtr = cast[ptr pointer](sta + 76)[]
  let bwCap = if rateInfoPtr != nil:
    cast[ptr uint16](rateInfoPtr)[]
  else:
    0'u16
  cast[ptr uint16](sta + 130)[] = 0'u16  # clear secondary BW result
  cast[ptr uint16](sta + 82)[] = 0'u16   # clear BW field
  cast[ptr uint16](sta + 80)[] = bwCap   # store primary BW capability

proc me_check_rc*(staIdx: uint8) {.exportc, cdecl, noinline.} =
  ## Check rate control for a station.
  ## From blob (2 instrs): tail-call to rc_check(staIdx).
  rc_check(staIdx)

proc me_set_sta_ht_vht_param*(staEntry: pointer, param: pointer) {.exportc, cdecl.} =
  ## Set HT/VHT parameters for a station.
  ## From blob (6 instrs): a0 is sta_info_tag pointer (not staIdx in blob ABI).
  ## Loads a config byte from me_env global, clears sta+312 (half-word),
  ## stores config byte at sta+316, returns 0.
  ## NOTE: blob's a0 is the sta pointer; a1 is unused.
  let sta = cast[uint](staEntry)
  let meBase = cast[uint](addr me_env[0])
  let configByte = cast[ptr uint8](meBase)[]  # first byte of me_env
  cast[ptr uint16](sta + 312)[] = 0'u16
  cast[ptr uint8](sta + 316)[] = configByte

{.emit: "__attribute__((optimize(\"crossjumping\"))) void* me_update_buffer_control(void*);".}
proc me_update_buffer_control*(sta: pointer): pointer {.exportc, cdecl.} =
  ## Update TX buffer control for a station.
  ## Reads the RC stats and TX policy descriptor, updates the rate control
  ## fields based on current rate entries, then writes the new policy to HW.
  let rcFlags = staU8(sta, STA_RC_FLAGS_OFF) # offset 334
  let txPolicy = staPtr(sta, STA_TX_POLICY_PTR_OFF) # offset 320 -> tx_policy ptr
  if rcFlags == 0:
    return txPolicy

  # Read current policy word at offset 4 and mirror the vendor stack copies:
  # txPolicy+20..32 are rate words, txPolicy+36..48 are TX power words.
  var policyWord = cast[ptr uint32](cast[uint](txPolicy) + 4)[]
  var rateWords: array[4, uint32]
  var txPowerWords: array[4, uint32]
  for acIdx in 0 ..< 4:
    rateWords[acIdx] = cast[ptr uint32](cast[uint](txPolicy) + 20'u + acIdx.uint * 4'u)[]
    txPowerWords[acIdx] = cast[ptr uint32](cast[uint](txPolicy) + 36'u + acIdx.uint * 4'u)[]

  if (rcFlags and 1) != 0:
    # RC active: update retry-chain rate words from RC stats.
    let rcStats = staPtr(sta, STA_RC_STATS_PTR_OFF) # offset 324
    let vifIdx = staU8(sta, 39) # offset 39 = VIF index
    let vifBase = cast[uint](addr vif_info_tab[0]) + vifIdx.uint * VIF_ENTRY_SIZE.uint
    let vifRatePowerBase = vifBase + 0x15F'u
    let retryRotate = rcU8(rcStats, RCS_ANOTHER_FLAG) # 0xB0
    let staMaxNss = staU8(sta, 0x13C)                 # vendor compares against sta+0x13c

    rcU8(rcStats, 0xBF) = cast[ptr uint8](vifBase + 0x16B'u)[]

    var foundSameNssChain: uint8 = 0
    var firstNssGroup: uint32 = 0
    var selectedGroup: uint8 = 0xFF'u8

    for acIdx in 0 ..< 4:
      let retrySlot = (retryRotate.uint32 + acIdx.uint32) and 0x3'u32
      let retryIdx = rcU16(rcStats, 0x80 + retrySlot.int * 8)
      let rateConfig = rcRateConfig(rcStats, retryIdx.int)
      var rateWord = (rateConfig.uint32 and 0x3FFF'u32) or 0x80000000'u32

      if ((rateWord shr 11) and 0x6'u32) != 0:
        var mcsOrGroup = rateWord and 0x7F'u32
        let vifBitmap = cast[ptr uint8](vifRatePowerBase + acIdx.uint)[]
        rcU8(rcStats, RCS_RATE_BITMAP + acIdx) = vifBitmap

        if acIdx == 0:
          var search = 7'i32
          while search >= 0:
            if (vifBitmap and (1'u8 shl search.uint8)) != 0:
              selectedGroup = search.uint8
              break
            dec search
          if selectedGroup != 0xFF'u8:
            rcU8(rcStats, RCS_MAX_NSS_MCS) = selectedGroup
            mcsOrGroup = selectedGroup.uint32
        elif selectedGroup != 0xFF'u8:
          rcU8(rcStats, RCS_MAX_NSS_MCS) = selectedGroup
          mcsOrGroup = selectedGroup.uint32

        if (rcU8(rcStats, RCS_FLAGS) and 0x40'u8) == 0:
          rateWord = (rateWord and not 0x7F'u32) or mcsOrGroup

        let nssGroup = (mcsOrGroup shr 4) and 0x7'u32
        if acIdx == 0:
          if nssGroup < staMaxNss.uint32:
            firstNssGroup = nssGroup
            foundSameNssChain = 1
        elif foundSameNssChain != 0:
          foundSameNssChain = (if nssGroup == firstNssGroup: 1'u8 else: 0'u8)

      rateWords[acIdx] = rateWord or (rateWords[acIdx] and 0x1FFFC000'u32)

    policyWord = policyWord and (not 0x180'u32)
    if foundSameNssChain != 0:
      policyWord = policyWord or ((firstNssGroup + 1'u32) shl 7)

    staU8(sta, STA_RC_FLAGS_OFF) = staU8(sta, STA_RC_FLAGS_OFF) or 0x12'u8

  # Check bit 2 (needs descriptor update), matching vendor's temporary chain.
  if (staU8(sta, STA_RC_FLAGS_OFF) and 0x02'u8) != 0:
    for acIdx in 0 ..< 4:
      let rateWord = rateWords[acIdx]
      let formatBits = (rateWord shr 11) and 0x7'u32
      let legacyBits = rateWord and 0x7C'u32
      if (formatBits or legacyBits) != 0:
        let aggLen = cast[ptr uint32](cast[uint](sta) + 0x148'u)[]
        rateWords[acIdx] = (rateWord and 0xE0003FFF'u32) or aggLen

  # Check bit 4 (needs TPC update). The local TPC proc still uses its old Nim
  # signature, so pass the policy word as the second argument.
  if (staU8(sta, STA_RC_FLAGS_OFF) and 0x10'u8) != 0:
    for acIdx in 0 ..< 4:
      txPowerWords[acIdx] = tpc_get_vif_tx_power_vs_rate(0'u8, rateWords[acIdx]).uint32

  # Critical section: write back policy word under IRQ protection
  let irqState = irqSave()
  cast[ptr uint32](cast[uint](txPolicy) + 4)[] = policyWord
  for acIdx in 0 ..< 4:
    cast[ptr uint32](cast[uint](txPolicy) + 20'u + acIdx.uint * 4'u)[] = rateWords[acIdx]
    cast[ptr uint32](cast[uint](txPolicy) + 36'u + acIdx.uint * 4'u)[] = txPowerWords[acIdx]

  irqRestore(irqState)
  # Clear RC flags to mark update complete
  staU8(sta, STA_RC_FLAGS_OFF) = 0
  return txPolicy

proc me_tx_cfm_singleton*(param: pointer) {.exportc, cdecl.} =
  ## Handle TX confirmation for singleton frames (80 bytes in blob, 25 instrs).
  ## From blob: reads host TX desc chain from frame+112 -> THD -> status word (THD+16).
  ## Extracts retry count via custom bit extract, checks bit 16 (success).
  ## If success: calls rc_check(frame) first, then rc_update_counters.
  ## Always: computes attempts=retries+1, successes=successBit+retries.
  let f = cast[uint](param)
  let txDescPtr = cast[ptr pointer](f + 112)[]
  let thd = cast[ptr pointer](cast[uint](txDescPtr))[]
  let statusWord = cast[ptr uint32](cast[uint](thd) + 16)[]
  # Extract retry count via custom bit extraction (approximate: bits 15:8)
  let retries = (statusWord shr 8) and 0xFF'u32
  # Check success bit (bit 16 = 0x10000)
  let successBit = if (statusWord and 0x10000'u32) != 0: 1'u32 else: 0'u32
  let attempts = retries + 1
  let successes = successBit + retries
  # If success, call rf_dump_status (blob: rf_dump_status, NOT rc_check)
  if (statusWord and 0x10000'u32) != 0:
    proc rf_dump_status(staIdx: uint8) {.importc, cdecl.}
    rf_dump_status(cast[ptr uint8](f + 49)[])
  let staIdx = cast[ptr uint8](f + 49)[]
  rc_update_counters(staIdx, attempts, successes)

proc me_tx_cfm_ampdu*(param: pointer) {.exportc, cdecl.} =
  ## Handle TX confirmation for A-MPDU frames (5 instrs).
  ## From blob: a0=staIdx, a1=totalAttempts, a2=failCount, a3=ampduLen.
  ## Computes successes = a1 - a2, tail-calls rc_update_counters(a0, a1, successes).
  ## Capture hidden args via inline asm.
  var totalAttempts, failCount: uint32
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", totalAttempts, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a2\" : \"=r\"(", failCount, ") );"].}
  let staIdx = cast[uint8](cast[uint](param))
  let successes = totalAttempts - failCount
  rc_update_counters(staIdx, totalAttempts, successes)

proc me_tx_cfm_amsdu*(param: pointer) {.exportc, cdecl.} =
  ## Handle TX confirmation for A-MSDU frames (16 instrs).
  ## From blob: reads STA idx from frame[46], looks up sta_info_tab entry,
  ## loads rc_stats pointer from sta[324], reads AMSDU length stat from rcStats[196].
  ## Returns the stat value (or 0 if invalid STA). Return via a0 register.
  let f = cast[uint](param)
  let staIdx = cast[ptr uint8](f + 46)[]
  if staIdx == 0xFF:
    {.emit: ["asm volatile(\"li a0, 0\");"].}
    return
  let staTab = cast[uint](addr sta_info_tab[0])
  let staEntry = staTab + staIdx.uint * STA_ENTRY_SIZE.uint
  let infoIdx = cast[ptr uint8](staEntry + 39)[]
  if infoIdx == 0xFF:
    {.emit: ["asm volatile(\"li a0, 0\");"].}
    return
  let rcStats = cast[ptr pointer](staEntry + STA_RC_STATS_PTR_OFF.uint)[]
  if rcStats != nil:
    let amsduLen = cast[ptr uint16](cast[uint](rcStats) + RCS_RATE_MAP_L)[]
    {.emit: ["asm volatile(\"mv a0, %0\" : : \"r\"(", amsduLen, ") );"].}
  else:
    {.emit: ["asm volatile(\"li a0, 0\");"].}

# ME IE building functions
proc me_add_ie_ssid*(buf: pointer, ssid: pointer, ssidLen: uint8): uint32 {.exportc, cdecl.} =
  ## Add SSID IE to buffer. buf is ptr-to-write-pointer (ptr-ptr pattern).
  ## Writes IE ID=0, length, then SSID data. Advances *buf. Returns total bytes.
  let bufPtrPtr = cast[ptr pointer](buf)
  let p = cast[uint](bufPtrPtr[])
  cast[ptr uint8](p)[] = 0'u8  # SSID element ID
  cast[ptr uint8](p + 1)[] = ssidLen
  if ssidLen > 0 and ssid != nil:
    co_pack8p(cast[pointer](p + 2), ssid, ssidLen.uint32)
  let total = ssidLen.uint32 + 2
  bufPtrPtr[] = cast[pointer](p + total.uint)
  return total

proc me_add_ie_supp_rates*(buf: pointer, rateSetPtr: pointer): uint32 {.exportc, cdecl.} =
  ## Add supported rates IE to buffer (34 instrs).
  ## buf is ptr-to-write-pointer (ptr-ptr pattern).
  ## rateSetPtr: rate_set[0] = count, rate_set[1..N] = rate bytes.
  ## Writes IE with ID=1, length=min(count,8), copies min(count,8) rate bytes.
  ## Advances *buf, returns bytes written (count clipped to 8, + 2).
  let bufPtrPtr = cast[ptr pointer](buf)
  let rateCount = cast[ptr uint8](rateSetPtr)[]
  var writeCount = rateCount
  if writeCount > 8:
    writeCount = 8
  let p = cast[uint](bufPtrPtr[])
  # Write IE header: ID=1 (Supported Rates), length
  cast[ptr uint8](p)[] = 1'u8
  cast[ptr uint8](p + 1)[] = writeCount
  # Copy rate bytes — blob uses co_pack8p, not memcpy.
  co_pack8p(cast[pointer](p + 2), cast[pointer](cast[uint](rateSetPtr) + 1),
            writeCount.uint32)
  # Advance buffer pointer
  let totalLen = writeCount.uint32 + 2
  bufPtrPtr[] = cast[pointer](p + totalLen.uint)
  return totalLen

proc me_add_ie_ext_supp_rates*(buf: pointer, rateSetPtr: pointer, totalCount: uint32): uint32 {.exportc, cdecl.} =
  ## Add Extended Supported Rates IE (ID=50) (26 instrs).
  ## buf is ptr-to-write-pointer (ptr-ptr pattern).
  ## rateSetPtr: same rate_set as supp_rates. totalCount: total number of rates.
  ## Writes IE with ID=50, length=count-8, data=rates[9..count].
  ## Advances *buf. Returns total bytes written (count-8+2 = count-6).
  let bufPtrPtr = cast[ptr pointer](buf)
  let extCount = totalCount - 8
  let p = cast[uint](bufPtrPtr[])
  # Write IE header: ID=50 (Extended Supported Rates)
  cast[ptr uint8](p)[] = 50'u8
  cast[ptr uint8](p + 1)[] = (totalCount - 8).uint8
  # Copy extended rate bytes (starting from rate_set[9], skipping first 8) —
  # blob uses co_pack8p, not memcpy.
  co_pack8p(cast[pointer](p + 2),
            cast[pointer](cast[uint](rateSetPtr) + 9),
            extCount.uint32)
  # Advance buffer pointer
  let written = totalCount - 6  # (count-8) + 2
  bufPtrPtr[] = cast[pointer](p + written.uint)
  return written

proc me_add_ie_ds*(buf: pointer, channel: uint8): uint32 {.exportc, cdecl.} =
  ## Add DS Parameter Set IE (ID=3, length=1, total=3 bytes).
  ## buf is ptr-to-write-pointer (ptr-ptr pattern). Advances *buf by 3.
  let bufPtrPtr = cast[ptr pointer](buf)
  let p = cast[uint](bufPtrPtr[])
  cast[ptr uint8](p)[] = 3'u8         # DS Parameter Set IE ID
  cast[ptr uint8](p + 1)[] = 1'u8     # length = 1
  cast[ptr uint8](p + 2)[] = channel  # channel number
  bufPtrPtr[] = cast[pointer](p + 3)
  return 3

proc me_add_ie_erp*(buf: pointer, erpInfo: uint8 = 0): uint32 {.exportc, cdecl.} =
  ## Add ERP IE (ID=42, length=1, total=3 bytes).
  ## buf is ptr-to-write-pointer (ptr-ptr pattern). Advances *buf by 3.
  ## erpInfo is the ERP information byte (protection flags etc).
  let bufPtrPtr = cast[ptr pointer](buf)
  let p = cast[uint](bufPtrPtr[])
  cast[ptr uint8](p)[] = 42'u8     # ERP IE ID
  cast[ptr uint8](p + 1)[] = 1'u8  # length = 1
  cast[ptr uint8](p + 2)[] = erpInfo
  bufPtrPtr[] = cast[pointer](p + 3)
  return 3

proc me_add_ie_ht_capa*(buf: pointer): uint32 {.exportc, cdecl.} =
  ## Add HT Capabilities IE (ID=45, length=26, total=28 bytes).
  ## buf is ptr-to-write-pointer (ptr-ptr pattern). Advances *buf by 28.
  ## Loads HT cap fields from me_env global.
  let bufPtrPtr = cast[ptr pointer](buf)
  let p = cast[uint](bufPtrPtr[])
  let meBase = cast[uint](addr me_env[0])
  cast[ptr uint8](p)[] = 45'u8  # HT Capabilities IE ID
  cast[ptr uint8](p + 1)[] = 26'u8  # length
  # HT Capability Info: clear SM Power Save bits 2-3, set LDPC/40MHz/SGI
  var htCapInfo = cast[ptr uint16](meBase + 8)[]
  htCapInfo = htCapInfo and (not 0x000C'u16)
  htCapInfo = htCapInfo or 0x002D'u16
  cast[ptr uint8](p + 2)[] = (htCapInfo and 0xFF).uint8
  cast[ptr uint8](p + 3)[] = ((htCapInfo shr 8) and 0xFF).uint8
  # A-MPDU parameters
  cast[ptr uint8](p + 4)[] = cast[ptr uint8](meBase + 10)[]
  # Supported MCS set (16 bytes) — blob uses co_pack8p (byte-by-byte pack),
  # not memcpy. Matching the call lets call-graph audit tools line up.
  co_pack8p(cast[pointer](p + 5), cast[pointer](meBase + 11), 16)
  # HT Extended Capabilities
  let htExtCap = cast[ptr uint16](meBase + 28)[]
  cast[ptr uint8](p + 21)[] = (htExtCap and 0xFF).uint8
  cast[ptr uint8](p + 22)[] = ((htExtCap shr 8) and 0xFF).uint8
  # TX Beamforming Capabilities (4 bytes) — same pack pattern.
  co_pack8p(cast[pointer](p + 23), cast[pointer](meBase + 30), 4)
  # ASEL Capabilities
  cast[ptr uint8](p + 27)[] = cast[ptr uint8](meBase + 36)[]
  # Advance write pointer
  bufPtrPtr[] = cast[pointer](p + 28)
  return 28

proc me_add_ie_ht_oper*(buf: pointer, vifEntry: pointer = nil): uint32 {.exportc, cdecl.} =
  ## Add HT Operation IE (ID=61, length=22, total=24 bytes).
  ## buf is ptr-to-write-pointer (ptr-ptr pattern). Advances *buf by 24.
  ## vifEntry points to the VIF entry; vifEntry+64 is the channel context.
  ## Channel context layout: [4]=band(u8), [5]=type(u8), [6]=prim_freq(u16),
  ## [8]=center1_freq(u16). Calls phy_freq_to_channel for primary channel.
  ## Secondary offset: 7 if no secondary, 5 if center1 >= prim.
  let bufPtrPtr = cast[ptr pointer](buf)
  let p = cast[uint](bufPtrPtr[])
  cast[ptr uint8](p)[] = 61'u8   # HT Operation IE ID
  cast[ptr uint8](p + 1)[] = 22'u8   # length

  # Determine primary channel and secondary offset from channel context
  var chanNum: uint8 = 0
  var secOffset: uint8 = 0  # default: no secondary channel (0 when chanType==0)
  if vifEntry != nil:
    let chanCtx = cast[ptr pointer](cast[uint](vifEntry) + 64)[]
    if chanCtx != nil:
      let band = cast[ptr uint8](cast[uint](chanCtx) + 4)[]
      let primFreq = cast[ptr uint16](cast[uint](chanCtx) + 6)[]
      chanNum = phy_freq_to_channel(band, primFreq)
      let chanType = cast[ptr uint8](cast[uint](chanCtx) + 5)[]
      if chanType != 0:
        let center1Freq = cast[ptr uint16](cast[uint](chanCtx) + 8)[]
        if center1Freq >= primFreq:
          secOffset = 5  # SCA (secondary channel above)
      else:
          secOffset = 7  # SCB (secondary channel below)

  cast[ptr uint8](p + 2)[] = chanNum      # primary channel
  cast[ptr uint8](p + 3)[] = secOffset    # secondary channel offset
  cast[ptr uint8](p + 4)[] = 3'u8         # HT protection: non-HT mixed mode
  cast[ptr uint8](p + 5)[] = 0'u8
  cast[ptr uint8](p + 6)[] = 0'u8
  cast[ptr uint8](p + 7)[] = 0'u8
  cast[ptr uint8](p + 8)[] = 0xFF'u8      # Basic MCS set: MCS 0-7 supported
  # Clear remaining bytes 9..23 — blob inlines these as explicit zero stores
  # (no memset call in its graph). Four zero-word stores fit exactly.
  cast[ptr uint32](p + 9)[] = 0
  cast[ptr uint32](p + 13)[] = 0
  cast[ptr uint32](p + 17)[] = 0
  cast[ptr uint16](p + 21)[] = 0
  cast[ptr uint8](p + 23)[] = 0
  bufPtrPtr[] = cast[pointer](p + 24)
  return 24

proc me_add_ie_rsn*(buf: pointer, secMode: uint8 = 0): uint32 {.exportc, cdecl.} =
  ## Add RSN IE (ID=48).
  ## From blob (90 instrs): a0=bufCtx (ptr to write-pointer), a1=secMode.
  ## secMode=1: 22-byte RSN with CCMP + PSK AKM.
  ## secMode=2: 26-byte RSN with TKIP+CCMP + 802.1X AKM.
  ## Other secMode: no IE added, returns 0.
  ##
  ## bufCtx layout: [0]=current write pointer. The IE is written at *bufCtx[0]
  ## and bufCtx[0] is advanced by the IE length.
  ## For Nim callers that pass buf directly (not a context struct), secMode
  ## defaults to 0 which returns 0 (no RSN), preserving backward compatibility.
  if secMode == 1:
    # RSN IE: CCMP only + PSK AKM (22 bytes total)
    let p = cast[ptr UncheckedArray[uint8]](cast[ptr pointer](buf)[])
    p[0]  = 48         # IE ID: RSN
    p[1]  = 20         # Length
    p[2]  = 1          # RSN Version 1 (LE16)
    p[3]  = 0
    p[4]  = 0          # Group Cipher Suite OUI: 00:0F:AC
    p[5]  = 15
    p[6]  = 0xAC'u8
    p[7]  = 4          # Group Cipher: CCMP
    p[8]  = 1          # Pairwise Cipher Count: 1 (LE16)
    p[9]  = 0
    p[10] = 0          # Pairwise Cipher Suite OUI: 00:0F:AC
    p[11] = 15
    p[12] = 0xAC'u8
    p[13] = 4          # Pairwise Cipher: CCMP
    p[14] = 1          # AKM Count: 1 (LE16)
    p[15] = 0
    p[16] = 0          # AKM Suite OUI: 00:0F:AC
    p[17] = 15
    p[18] = 0xAC'u8
    p[19] = 2          # AKM Type: PSK
    p[20] = 0          # RSN Capabilities: 0 (LE16)
    p[21] = 0
    # Advance write pointer
    let pp = cast[ptr pointer](buf)
    pp[] = cast[pointer](cast[uint](pp[]) + 22)
    return 22
  elif secMode == 2:
    # RSN IE: TKIP+CCMP + 802.1X AKM (26 bytes total)
    let p = cast[ptr UncheckedArray[uint8]](cast[ptr pointer](buf)[])
    p[0]  = 48         # IE ID: RSN
    p[1]  = 24         # Length
    p[2]  = 1          # RSN Version 1 (LE16) -- actually 0x10 in blob for secMode=2
    p[3]  = 0
    p[4]  = 0          # Group Cipher Suite OUI: 00:0F:AC
    p[5]  = 15
    p[6]  = 0xAC'u8
    p[7]  = 2          # Group Cipher: TKIP
    p[8]  = 2          # Pairwise Cipher Count: 2 (LE16)
    p[9]  = 0
    p[10] = 0          # Pairwise Cipher Suite 1 OUI: 00:0F:AC
    p[11] = 15
    p[12] = 0xAC'u8
    p[13] = 2          # Pairwise Cipher 1: TKIP
    p[14] = 0          # Pairwise Cipher Suite 2 OUI: 00:0F:AC
    p[15] = 15
    p[16] = 0xAC'u8
    p[17] = 4          # Pairwise Cipher 2: CCMP
    p[18] = 1          # AKM Count: 1 (LE16)
    p[19] = 0
    p[20] = 0          # AKM Suite OUI: 00:0F:AC
    p[21] = 15
    p[22] = 0xAC'u8
    p[23] = 2          # AKM Type: 802.1X
    p[24] = 0          # RSN Capabilities: 0 (LE16)
    p[25] = 0
    # Advance write pointer
    let pp = cast[ptr pointer](buf)
    pp[] = cast[pointer](cast[uint](pp[]) + 26)
    return 26
  else:
    # Unknown secMode or 0: no RSN IE
    return 0

{.emit: "__attribute__((noipa)) unsigned long me_add_ie_wpa(void*,unsigned long);".}
proc me_add_ie_wpa*(buf: pointer, secMode: uint32 = 0): uint32 {.exportc, cdecl.} =
  ## Add WPA IE (168 bytes in blob, 53 instrs).
  ## buf is ptr-to-write-pointer (ptr-ptr pattern).
  ## secMode: if != 2, returns 0 (only WPA2/mixed mode adds WPA IE).
  ## Writes WPA vendor IE (ID=221) with Microsoft OUI (00:50:F2:01).
  ## Total 30 bytes. Advances *buf by 30. Returns 30 on success, 0 otherwise.
  ## Note: blob is 168 bytes because GCC reloads *buf before each store group.
  ## Our GCC -Os factors the stores into a helper, so this is 30 bytes compiled.
  ## The gap is a GCC code factoring optimization difference, not missing logic.
  if secMode != 2:
    return 0
  let bufPtrPtr = cast[ptr pointer](buf)
  let p = cast[uint](bufPtrPtr[])
  cast[ptr uint8](p + 0)[]  = 221'u8; cast[ptr uint8](p + 1)[]  = 28'u8
  cast[ptr uint8](p + 2)[]  = 0x00'u8; cast[ptr uint8](p + 3)[]  = 0x50'u8
  cast[ptr uint8](p + 4)[]  = 0xF2'u8; cast[ptr uint8](p + 5)[]  = 0x01'u8
  cast[ptr uint8](p + 6)[]  = 0x01'u8; cast[ptr uint8](p + 7)[]  = 0x00'u8
  cast[ptr uint8](p + 8)[]  = 0x00'u8; cast[ptr uint8](p + 9)[]  = 0x50'u8
  cast[ptr uint8](p + 10)[] = 0xF2'u8; cast[ptr uint8](p + 11)[] = 0x02'u8
  cast[ptr uint8](p + 12)[] = 0x02'u8; cast[ptr uint8](p + 13)[] = 0x00'u8
  cast[ptr uint8](p + 14)[] = 0x00'u8; cast[ptr uint8](p + 15)[] = 0x50'u8
  cast[ptr uint8](p + 16)[] = 0xF2'u8; cast[ptr uint8](p + 17)[] = 0x02'u8
  cast[ptr uint8](p + 18)[] = 0x00'u8; cast[ptr uint8](p + 19)[] = 0x50'u8
  cast[ptr uint8](p + 20)[] = 0xF2'u8; cast[ptr uint8](p + 21)[] = 0x04'u8
  cast[ptr uint8](p + 22)[] = 0x01'u8; cast[ptr uint8](p + 23)[] = 0x00'u8
  cast[ptr uint8](p + 24)[] = 0x00'u8; cast[ptr uint8](p + 25)[] = 0x50'u8
  cast[ptr uint8](p + 26)[] = 0xF2'u8; cast[ptr uint8](p + 27)[] = 0x02'u8
  bufPtrPtr[] = cast[pointer](p + 30)
  return 30

proc me_add_ie_tim*(buf: pointer, dtimBitmap: uint8 = 0): uint32 {.exportc, cdecl.} =
  ## Add TIM IE (ID=5, length=4, total=6 bytes).
  ## buf is ptr-to-write-pointer (ptr-ptr pattern). Advances *buf by 6.
  ## dtimBitmap is stored at offset 3 (DTIM count field in blob).
  let bufPtr = cast[ptr pointer](buf)
  let p = cast[uint](bufPtr[])
  cast[ptr uint8](p + 0)[] = 5'u8          # TIM Element ID
  cast[ptr uint8](p + 1)[] = 4'u8          # Length
  cast[ptr uint8](p + 2)[] = 0'u8          # DTIM count
  cast[ptr uint8](p + 3)[] = dtimBitmap    # DTIM period / bitmap
  cast[ptr uint8](p + 4)[] = 0'u8          # Bitmap control
  cast[ptr uint8](p + 5)[] = 0'u8          # Partial virtual bitmap
  bufPtr[] = cast[pointer](p + 6)
  return 6

proc me_add_ie_csa*(buf: pointer): uint32 {.exportc, cdecl.} =
  ## Add Channel Switch Announcement IE (ID=37).
  ## New function (not in blob). Returns 0 when no CSA is pending.
  return 0

proc me_add_ie_customer*(buf: pointer): uint32 {.exportc, cdecl.} =
  ## Add customer-defined IE (11 instrs).
  ## From blob: a0=buf_ptr_ptr, a1=ie_data, a2=offset via C ABI.
  ## Calls me_add_ie_copy(buf_ptr_ptr, ie_data) to copy the IE data,
  ## then returns a2 (the original offset value, passed through).
  var ieData: pointer
  var offset: uint32
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", ieData, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a2\" : \"=r\"(", offset, ") );"].}
  # Copy IE data if provided
  if ieData != nil:
    let bufPtrPtr = cast[ptr pointer](buf)
    let ieLen = cast[ptr uint8](cast[uint](ieData) + 1)[]  # IE[1] = length
    let totalLen = ieLen.uint32 + 2  # ID + length + data
    let p = cast[uint](bufPtrPtr[])
    # Blob calls co_pack8p, not memcpy.
    co_pack8p(cast[pointer](p), ieData, totalLen.uint32)
    bufPtrPtr[] = cast[pointer](p + totalLen.uint)
  return offset

# ME frame building
proc me_build_authenticate*(buf: pointer, authAlgo: uint16, authSeq: uint16,
    statusCode: uint16, challengeText: pointer): uint32 {.exportc, cdecl, noinline.} =
  ## Build authentication frame body (noinline so blob-style call remains).
  ## From blob (27 instrs): writes auth_algo, auth_seq, status_code as LE16.
  ## If challengeText != nil, appends challenge text IE (ID=16, len=128).
  ## Returns 6 (no challenge) or 136 (with challenge).
  let p = cast[ptr UncheckedArray[uint8]](buf)
  # Auth Algorithm Number (LE16)
  p[0] = (authAlgo and 0xFF).uint8
  p[1] = ((authAlgo shr 8) and 0xFF).uint8
  # Auth Transaction Sequence Number (LE16)
  p[2] = (authSeq and 0xFF).uint8
  p[3] = ((authSeq shr 8) and 0xFF).uint8
  # Status Code (LE16)
  p[4] = (statusCode and 0xFF).uint8
  p[5] = ((statusCode shr 8) and 0xFF).uint8
  if challengeText != nil:
    # Challenge Text IE: ID=16, Length=128
    p[6] = 16
    p[7] = 128
    # Blob copies the 128-byte challenge via a byte-loop + T-Head custom
    # insn (no memcpy call emitted). Emit the equivalent byte copy inline
    # so the call graph stays at 0 calls (matching blob).
    let src = cast[ptr UncheckedArray[uint8]](challengeText)
    for i in 0 ..< 128:
      p[8 + i] = src[i]
    return 136
  return 6

proc me_build_sae_authenticate*(buf: pointer, authAlgo: uint16, authSeq: uint16,
    statusCode: uint16, vifIdx: uint32): uint32 {.exportc, cdecl.} =
  ## Build SAE authentication frame body.
  ## From blob (53 instrs): writes auth header (6 bytes), then loads SAE state
  ## from VIF entry (vifIdx * 1512 + vif_info_tab), calls SAE callback to get
  ## payload, copies to buf+6. Returns total length or 0 on failure.
  let p = cast[ptr UncheckedArray[uint8]](buf)
  # Auth Algorithm Number (LE16)
  p[0] = (authAlgo and 0xFF).uint8
  p[1] = ((authAlgo shr 8) and 0xFF).uint8
  # Auth Transaction Sequence Number (LE16)
  p[2] = (authSeq and 0xFF).uint8
  p[3] = ((authSeq shr 8) and 0xFF).uint8
  # Status Code (LE16)
  p[4] = (statusCode and 0xFF).uint8
  p[5] = ((statusCode shr 8) and 0xFF).uint8

  # SAE payload: call WPA callback to get SAE frame data from VIF SAE context.
  # Blob: loads VIF entry, computes SAE context at vifEntry+80, then calls
  # wpa_cbs[14] (offset 56 = func pointer for get_sae_frame) with context.
  let vifTabBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifTabBase + vifIdx * VIF_ENTRY_SIZE.uint
  let saeCtx = cast[pointer](vifEntry + 80)

  if wpa_cbs != nil:
    let wpaCbArr = cast[ptr UncheckedArray[pointer]](wpa_cbs)
    let getSaeFrame = wpaCbArr[14]  # offset 56 = index 14
    if getSaeFrame != nil:
      type SaeFrameFn = proc(ctx: pointer, lenOut: ptr uint32): pointer {.cdecl.}
      var saeLen: uint32 = 0
      let saeData = cast[SaeFrameFn](getSaeFrame)(saeCtx, addr saeLen)
      if saeData != nil:
        discard c_memcpy(cast[pointer](cast[uint](buf) + 6), saeData, saeLen.csize_t)
        return saeLen + 6
  return 0

proc me_build_associate_req_impl(buf: pointer, assocInfo: pointer,
    reassocBssid: pointer, capParam: pointer, cursorOut: pointer,
    bodyLenOut: pointer, connInfo: pointer): uint32 {.exportc: "me_build_associate_req", cdecl.} =
  ## Build association request frame body (159 instrs).
  ## Blob ABI: a0=body write pointer, a1=vif association info (vif+348),
  ## a2=reassociation BSSID or nil, a3=capability param (inst_nbr),
  ## a4=cursor out, a5=bodyLen out, a6=connect info.
  ##
  ## buf is the direct body write pointer. Writes: capability info (2B),
  ## listen interval (2B), optional BSSID (6B for reassoc), then appends IEs:
  ## SSID, Supported Rates, Extended Supported Rates, the prebuilt
  ## association/security IE block, HT Capabilities (if 11n), WMM, and
  ## vendor-specific IEs from sm_env.
  ## Returns total body length in a0 (via bodyLenOut).
  let assoc = cast[ptr UncheckedArray[uint8]](assocInfo)
  let assocU = cast[uint](assocInfo)
  let connU = cast[uint](connInfo)
  let secFlags = cast[ptr uint32](assocU + 136)[]

  # Read listen interval from connInfo+54 (a6+54 in blob), default 5.
  var listenInt: uint16 = 5
  if connInfo != nil:
    let li = cast[ptr uint16](connU + 54)[]
    if li != 0:
      listenInt = li

  # Build capability info using the inst_nbr/capability parameter (a3).
  let capInfo = me_build_capability(capParam)

  # Write cap info at buf[0..1]. The blob receives a direct body pointer in a0,
  # then uses a stack-local pointer-to-pointer for the IE helper calls.
  let bufBase = cast[uint](buf)
  var writePtr = bufBase
  cast[ptr uint8](writePtr)[] = (capInfo and 0xFF).uint8
  cast[ptr uint8](writePtr + 1)[] = ((capInfo shr 8) and 0xFF).uint8

  # Write listen interval at buf[2..3]
  cast[ptr uint8](writePtr + 2)[] = (listenInt and 0xFF).uint8
  cast[ptr uint8](writePtr + 3)[] = ((listenInt shr 8) and 0xFF).uint8

  # Check for reassoc (reassocBssid ptr != nil).
  # If present, copy 6 BSSID bytes and hdrSize becomes 10
  var hdrSize: uint = 4
  if reassocBssid != nil:
    cast[ptr uint16](writePtr + 4)[] = cast[ptr uint16](reassocBssid)[]
    cast[ptr uint16](writePtr + 6)[] = cast[ptr uint16](cast[uint](reassocBssid) + 2)[]
    cast[ptr uint16](writePtr + 8)[] = cast[ptr uint16](cast[uint](reassocBssid) + 4)[]
    hdrSize = 10

  # Advance write pointer past header, store to the caller's cursor slot, and
  # use a local cursor for all IE helper ptr-to-write-pointer calls.
  writePtr += hdrSize
  var cursor = cast[pointer](writePtr)
  if cursorOut != nil:
    cast[ptr pointer](cursorOut)[] = cursor
  var totalLen: uint32 = hdrSize.uint32

  # Add SSID IE: blob uses assocInfo+38 (vif+386 len, vif+387 data).
  let ssidIeLen = me_add_ie_ssid(addr cursor, cast[pointer](assocU + 39), assoc[38])
  totalLen += ssidIeLen

  # Add Supported Rates IE with rates pointer from assocInfo+88 (vif+436).
  let ratesPtr = cast[pointer](assocU + 88)
  let suppLen = me_add_ie_supp_rates(addr cursor, ratesPtr)
  totalLen += suppLen

  # Add Extended Supported Rates IE (if > 8 rates)
  let rateCount = cast[ptr uint8](assocU + 88)[]
  if rateCount > 8:
    let extLen = me_add_ie_ext_supp_rates(addr cursor, ratesPtr, rateCount.uint32)
    totalLen += extLen

  # Copy the prebuilt association/security IE block from assocInfo+144/+148.
  # The blob performs this copy before checking the capability flags.
  let assocIeSrc = cast[ptr pointer](assocU + 144)[]
  let assocIeLen = cast[ptr uint8](assocU + 148)[].uint32
  if assocIeSrc != nil and assocIeLen != 0:
    discard c_memcpy(cursor, assocIeSrc, assocIeLen.csize_t)
    cursor = cast[pointer](cast[uint](cursor) + assocIeLen.uint)
    totalLen += assocIeLen
  when defined(bl808WifiNimFw):
    nimFwTrace2U32("[WIFI-NIMFW] assoc_tx_sec ",
                   secFlags,
                   assocIeLen)

  # Emit WMM Information Element only (blob does NOT emit a separate QoS
  # Capability IE — just the 9-byte WMM IE which carries QoS Info at byte 8).
  # Blob: memcpy(scratch, .LANCHOR0, 10); conditionally overwrite scratch[8];
  # co_pack8p(buf, scratch, 9).
  if (secFlags and 1) != 0:
    let meBase = cast[uint](addr me_env[0])
    let qosInfo = if connInfo != nil: cast[ptr uint8](connU + 58)[] else: cast[ptr uint8](meBase + 452)[]
    var wmmIe {.noinit.}: array[9, uint8]
    wmmIe[0] = 0xDD    # Vendor Specific IE ID
    wmmIe[1] = 7       # Length
    wmmIe[2] = 0x00    # OUI 00:50:F2
    wmmIe[3] = 0x50
    wmmIe[4] = 0xF2
    wmmIe[5] = 0x02    # WMM type
    wmmIe[6] = 0x00    # subtype (Information Element)
    wmmIe[7] = 0x01    # version
    wmmIe[8] = qosInfo
    let wp = cast[uint](cursor)
    co_pack8p(cast[pointer](wp), addr wmmIe[0], 9)
    cursor = cast[pointer](wp + 9)
    totalLen += 9

  # Handle HT Capabilities IE (if bit 1 set in secFlags and me_env HT enabled).
  if (secFlags and 2) != 0:
    let meEnvHtFlag = cast[ptr uint8](cast[uint](addr me_env[0]) + 0x82)[]
    if meEnvHtFlag != 0:
      let htLen = me_add_ie_ht_capa(addr cursor)
      totalLen += htLen

  # Append vendor-specific IE template (if any) from sm_env+48 / +52.
  # Blob: `lw a1,48(s1); beqz a1,.L72; lhu a2,52(s1); lw a0,12(sp);
  # call co_pack8p; lhu a5,52(s1); s0+=a5; advance write ptr`.
  let smBase = cast[uint](addr sm_env[0])
  let vendorPtr = cast[ptr pointer](smBase + 48)[]
  if vendorPtr != nil:
    let vendorLen = cast[ptr uint16](smBase + 52)[]
    let wp = cast[uint](cursor)
    co_pack8p(cast[pointer](wp), vendorPtr, vendorLen)
    cursor = cast[pointer](wp + vendorLen.uint)
    totalLen += vendorLen.uint32

  # Store association IE length. The return value is the full association
  # request body length, but the status message field is IE-only: blob stores
  # current cursor minus the initial cursor after fixed cap/listen fields.
  if cursorOut != nil:
    cast[ptr pointer](cursorOut)[] = cursor
  if bodyLenOut != nil:
    let endPtr = cast[uint](cursor)
    cast[ptr uint16](bodyLenOut)[] = cast[uint16](endPtr - writePtr)
  return totalLen

proc me_build_associate_rsp_impl(buf: pointer, staEntry: pointer,
    statusCode: uint16, aid: uint16): uint32 {.exportc: "me_build_associate_rsp", cdecl.} =
  ## Build association response frame body (166 instrs).
  ## Blob ABI: a0=buf_ctx (ptr-to-write-ptr), a1=vifIdx (passed as pointer but
  ## actually a small VIF index), a2=statusCode, a3=aid (or STA entry pointer).
  ## Writes: cap info (2B), status code (2B), AID (2B), then Supported Rates,
  ## Ext Rates, HT Cap, HT Oper, WMM Parameter, and BSS Max Idle Period IEs.
  ## Returns total length in a0.
  let vifTabBase = cast[uint](addr vif_info_tab[0])
  # staEntry parameter is actually used as VIF index in the blob
  # (me_build_capability(a0=a1) where a1 is the VIF index).
  # The blob computes: vif_entry = vif_info_tab + a1 * 1512
  let vifIdx = cast[uint](staEntry)
  let vifEntry = vifTabBase + vifIdx * VIF_ENTRY_SIZE.uint
  let privacy = cast[ptr uint8](vifEntry + 520)[]

  # Build capability info using VIF index
  var capInfo = me_build_capability(staEntry)  # staEntry is really vifIdx
  if privacy != 0:
    capInfo = capInfo or 16

  var writePtr = cast[uint](cast[ptr pointer](buf)[])

  # Write capability info (LE16)
  cast[ptr uint8](writePtr)[] = (capInfo and 0xFF).uint8
  cast[ptr uint8](writePtr + 1)[] = ((capInfo shr 8) and 0xFF).uint8

  # Write status code (LE16)
  cast[ptr uint8](writePtr + 2)[] = (statusCode and 0xFF).uint8
  cast[ptr uint8](writePtr + 3)[] = ((statusCode shr 8) and 0xFF).uint8

  # Write AID with 2 MSBs set (LE16)
  # Blob: a3 parameter is actually a STA entry pointer. AID is at staEntry+68.
  # The 'aid' parameter is typed uint16 but at runtime it's a pointer value.
  let staEntryPtr = cast[uint](aid)  # a3 is really a pointer
  let aidVal = cast[ptr uint16](staEntryPtr + 68)[]
  let aidField = aidVal or 0xC000'u16
  cast[ptr uint8](writePtr + 4)[] = (aidField and 0xFF).uint8
  cast[ptr uint8](writePtr + 5)[] = ((aidField shr 8) and 0xFF).uint8

  writePtr += 6
  cast[ptr pointer](buf)[] = cast[pointer](writePtr)
  var totalLen: uint32 = 6

  # Add Supported Rates IE -- rates from STA entry at staEntry+6
  # Blob: addi a1, s2, 6 where s2=a3=staEntry
  let ratesPtr = cast[pointer](staEntryPtr + 6)
  totalLen += me_add_ie_supp_rates(buf, ratesPtr)

  # Add Extended Supported Rates if > 8 rates
  # Blob: lbu a4, 6(s2) -> rate count from staEntry+6 (first byte of rates struct)
  let rateCount = cast[ptr uint8](staEntryPtr + 6)[]
  if rateCount > 8:
    totalLen += me_add_ie_ext_supp_rates(buf, ratesPtr, rateCount.uint32)

  # Check STA HT capabilities from staEntry+64 (blob: lw a5, 64(s2))
  let staCap = cast[ptr uint32](staEntryPtr + 64)[]
  if (staCap and 2) != 0:
    # Add HT Capabilities IE
    totalLen += me_add_ie_ht_capa(buf)

    # Add HT Operation IE with VIF entry for channel context
    totalLen += me_add_ie_ht_oper(buf, cast[pointer](vifEntry))

  # Check WMM capabilities (bit 0 of staCap from staEntry+64)
  if (staCap and 1) != 0:
    # Write WMM Parameter Element (IEEE 802.11 vendor-specific IE)
    let wp = cast[uint](cast[ptr pointer](buf)[])
    let meEnvBase = cast[uint](addr me_env[0])

    # Blob builds a 10-byte stack buffer: memcpy(sp+16, .LANCHOR0, 10) — this
    # is the WMM template header including OUI/type/subtype/version. It then
    # overwrites the QoS-Info byte at sp+24 from me_env+452, and zeros
    # halfwords at sp+26/28/30 (reserved). Finally co_pack8p 9 bytes from
    # sp+16..24 to the output (wp). Mirror this two-step layout.
    var wmmStaging {.noinit.}: array[10, uint8]
    const wmmIeTemplate: array[10, uint8] = [
      0xDD'u8, 0x18, 0x00, 0x50, 0xF2, 0x02, 0x01, 0x01, 0x00, 0x00]
    discard c_memcpy(addr wmmStaging[0], unsafeAddr wmmIeTemplate[0], 10.csize_t)
    wmmStaging[8] = cast[ptr uint8](meEnvBase + 452)[]
    # Pack the 9-byte header (DD/len/OUI/type/subtype/ver/QoS/reserved0)
    co_pack8p(cast[pointer](wp), addr wmmStaging[0], 9)

    # AC_BE parameters (from me_env+12)
    let acBe = cast[ptr uint32](meEnvBase + 12)[]
    cast[ptr uint32](wp + 10)[] = acBe

    # AC_BK parameters (from me_env+8)
    let acBk = cast[ptr uint32](meEnvBase + 8)[]
    cast[ptr uint32](wp + 14)[] = acBk

    # AC_VI parameters (from me_env+16)
    let acVi = cast[ptr uint32](meEnvBase + 16)[]
    cast[ptr uint32](wp + 18)[] = acVi

    # AC_VO parameters (from me_env+20)
    let acVo = cast[ptr uint32](meEnvBase + 20)[]
    cast[ptr uint32](wp + 22)[] = acVo

    let wmmLen: uint32 = 26  # 2 (header) + 24 (body)
    cast[ptr pointer](buf)[] = cast[pointer](wp + wmmLen.uint)
    totalLen += wmmLen

    # BSS Max Idle Period IE (ID=90, Length=3)
    # Blob: reads idle period from me_env+24 (halfword) and options from me_env+26 (byte)
    let bp = cast[uint](cast[ptr pointer](buf)[])
    cast[ptr uint8](bp + 0)[] = 90'u8         # BSS Max Idle Period IE ID
    cast[ptr uint8](bp + 1)[] = 3'u8          # Length
    let idlePeriod = cast[ptr uint16](meEnvBase + 24)[]
    cast[ptr uint8](bp + 2)[] = (idlePeriod and 0xFF).uint8
    cast[ptr uint8](bp + 3)[] = ((idlePeriod shr 8) and 0xFF).uint8
    let idleOpts = cast[ptr uint8](meEnvBase + 26)[]
    cast[ptr uint8](bp + 4)[] = idleOpts
    cast[ptr pointer](buf)[] = cast[pointer](bp + 5)
    totalLen += 5

  return totalLen

proc me_build_deauthenticate*(buf: pointer, reason: uint16): uint32 {.exportc, cdecl, noinline.} =
  ## Build deauthentication frame body (2 bytes: reason code LE16).
  ## From blob (5 instrs): a0=buf, a1=reason_code(u16).
  ## Writes reason_code as LE16 at buf[0..1]. Returns 2.
  ## noinline: blob calls this as a real function.
  let p = cast[ptr UncheckedArray[uint8]](buf)
  p[0] = (reason and 0xFF).uint8
  p[1] = ((reason shr 8) and 0xFF).uint8
  return 2

proc me_build_beacon*(buf: pointer, vifIdx: uint8, lenOut: ptr uint16,
                     flagsOut: ptr uint8, hdrPtr: pointer): uint32 {.exportc, cdecl.} =
  ## Build beacon frame IEs.
  ## From blob (276 instrs): builds a complete beacon frame body.
  ## buf = output buffer, hdrPtr = beacon header pointer (sp+12 in blob).
  ## Writes 802.11 beacon frame header at buf[0..35], then appends IEs.
  ## Returns total body length (header + IEs).
  let vifTabBase = cast[uint](addr vif_info_tab[0])
  let vifBase = vifTabBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let privacy = cast[ptr uint8](vifBase + 520)[]  # privacy flag
  let p = cast[ptr UncheckedArray[uint8]](buf)

  # Write frame control: beacon = 0x80
  p[0] = 0x80'u8; p[1] = 0; p[2] = 0; p[3] = 0

  # Write DA at offset 4..9: broadcast (FF:FF:FF:FF:FF:FF). Blob copies from
  # the global mac_addr_bcst symbol, not a function-local const — match so
  # the reloc shape is identical (PCREL_HI20 → mac_addr_bcst).
  let macAddr = cast[pointer](vifBase + 80)
  discard c_memcpy(cast[pointer](cast[uint](buf) + 4), addr mac_addr_bcst_fwd[0], 6)
  discard c_memcpy(cast[pointer](cast[uint](buf) + 10), macAddr, 6)
  discard c_memcpy(cast[pointer](cast[uint](buf) + 16), macAddr, 6)

  # Sequence number: increment and write at offset 22..23
  let meBase = cast[uint](addr me_env[0])
  var seqNum = cast[ptr uint16](meBase + 84)[]
  seqNum += 1
  cast[ptr uint16](meBase + 84)[] = seqNum
  let seqField = seqNum shl 4
  p[22] = (seqField and 0xFF).uint8
  p[23] = ((seqField shr 8) and 0xFF).uint8

  # Beacon interval at buf+32..33 (from VIF+514)
  let bcnInt = cast[ptr uint16](vifBase + 514)[]
  let bufU = cast[uint](buf)
  cast[ptr uint8](bufU + 32)[] = (bcnInt and 0xFF).uint8
  cast[ptr uint8](bufU + 33)[] = ((bcnInt shr 8) and 0xFF).uint8

  # Capability info
  var capInfo = me_build_capability(cast[pointer](vifIdx.uint))
  if privacy != 0:
    capInfo = capInfo or 16  # set privacy bit

  # Prepare SSID data pointer (set up before capability write, as blob does)
  let ssidDataPtr = cast[pointer](vifBase + 387)

  # Write capability at buf+34..35
  cast[ptr uint8](bufU + 34)[] = (capInfo and 0xFF).uint8
  cast[ptr uint8](bufU + 35)[] = ((capInfo shr 8) and 0xFF).uint8

  # Start building IEs at buf+36 (after 24-byte MAC header + 12-byte beacon body)
  # Blob: sp+12 tracks current write position (ptr-ptr pattern)
  var ieBuf: pointer = cast[pointer](cast[uint](buf) + 36)

  # Add SSID IE (blob tail-merges into a single me_add_ie_ssid call).
  var ssidArgPtr: pointer = nil
  var ssidArgLen: uint8 = 0
  if hdrPtr == nil:
    ssidArgPtr = ssidDataPtr
    ssidArgLen = cast[ptr uint8](vifBase + 386)[]
  discard me_add_ie_ssid(addr ieBuf, ssidArgPtr, ssidArgLen)

  # bodyLen tracks total from the IE start (buf) including the 36-byte header
  var bodyLen: uint32 = cast[uint32](cast[uint](ieBuf) - cast[uint](buf))

  # Add Supported Rates IE -- pass rates pointer from VIF+436
  let ratesPtr = cast[pointer](vifBase + 436)
  bodyLen += me_add_ie_supp_rates(addr ieBuf, ratesPtr)

  # Add Extended Supported Rates if > 8 rates
  let rateCount = cast[ptr uint8](vifBase + 436)[]
  if rateCount > 8:
    bodyLen += me_add_ie_ext_supp_rates(addr ieBuf, ratesPtr, rateCount.uint32)

  # Add DS Parameter Set IE: compute channel from VIF channel frequency
  # Blob computes: channel = ((freq - 2412) / 5) + 1 for 2.4GHz
  let chanPtr = cast[ptr pointer](vifBase + 424)[]
  let chanFreq = cast[ptr uint16](chanPtr)[]
  let chanNum = (((chanFreq.int - 2412) div 5) + 1).uint8
  bodyLen += me_add_ie_ds(addr ieBuf, chanNum)

  # Write body length to lenOut BEFORE adding TIM and remaining IEs
  # Blob: sh s0,0(s6) at this exact point
  if lenOut != nil:
    lenOut[] = bodyLen.uint16

  # Add TIM IE (blob: lbu a1,432(s7) for DTIM bitmap byte)
  let timBitmap = cast[ptr uint8](vifBase + 432)[]
  let timLen = me_add_ie_tim(addr ieBuf, timBitmap)
  # Store TIM return (masked to byte) to flagsOut
  if flagsOut != nil:
    flagsOut[] = (timLen and 0xFF).uint8
  bodyLen += timLen

  # Add WPA/RSN IE from VIF+492 (pre-built IE pointer) if present
  let wpaIePtr = cast[ptr pointer](vifBase + 492)[]
  if wpaIePtr != nil:
    let wpaIeLen = cast[ptr uint8](vifBase + 496)[]
    let wp = cast[uint](ieBuf)
    discard c_memcpy(ieBuf, wpaIePtr, wpaIeLen.csize_t)
    bodyLen += wpaIeLen.uint32
    ieBuf = cast[pointer](wp + wpaIeLen.uint)

  # Add ERP IE (blob: li a1,0 -> no protection)
  bodyLen += me_add_ie_erp(addr ieBuf, 0)

  # Check WPA/RSN flags at VIF+484
  let flagsWord = cast[ptr uint32](vifBase + 484)[]
  if (flagsWord and 2) != 0:
    # NOTE: Blob does NOT call me_add_ie_rsn in me_build_beacon (only in me_build_probe_rsp).
    # Add vendor WPA IE -- blob passes vif entry base as a1 for secMode lookup
    bodyLen += me_add_ie_wpa(addr ieBuf, 2)

  # Add HT Capabilities IE (always present for 11n AP)
  bodyLen += me_add_ie_ht_capa(addr ieBuf)

  # Add HT Operation IE
  bodyLen += me_add_ie_ht_oper(addr ieBuf, cast[pointer](vifBase))

  # Build WPA1 vendor IE inline if flagsWord bit 0 is set (from blob)
  if (flagsWord and 1) != 0:
    let cipherType = cast[ptr uint8](vifBase + 452)[]
    let wpaBase = cast[uint](ieBuf)
    cast[ptr uint8](wpaBase + 0)[] = 0xDD   # vendor IE
    cast[ptr uint8](wpaBase + 2)[] = 0x00   # OUI
    cast[ptr uint8](wpaBase + 3)[] = 0x50
    cast[ptr uint8](wpaBase + 4)[] = 0xF2
    cast[ptr uint8](wpaBase + 5)[] = 0x01   # WPA type
    cast[ptr uint8](wpaBase + 6)[] = 0x01   # version
    cast[ptr uint8](wpaBase + 7)[] = 0x00
    cast[ptr uint8](wpaBase + 8)[] = 0x00   # group cipher OUI
    cast[ptr uint8](wpaBase + 9)[] = 0x50
    cast[ptr uint8](wpaBase + 10)[] = 0xF2
    cast[ptr uint8](wpaBase + 11)[] = cipherType
    cast[ptr uint8](wpaBase + 12)[] = 0x01  # unicast count
    cast[ptr uint8](wpaBase + 13)[] = 0x00
    cast[ptr uint8](wpaBase + 14)[] = 0x00  # unicast cipher OUI
    cast[ptr uint8](wpaBase + 15)[] = 0x50
    cast[ptr uint8](wpaBase + 16)[] = 0xF2
    cast[ptr uint8](wpaBase + 17)[] = cipherType
    cast[ptr uint8](wpaBase + 18)[] = 0x01  # AKM count
    cast[ptr uint8](wpaBase + 19)[] = 0x00
    cast[ptr uint8](wpaBase + 20)[] = 0x00  # AKM OUI (PSK)
    cast[ptr uint8](wpaBase + 21)[] = 0x50
    cast[ptr uint8](wpaBase + 22)[] = 0xF2
    cast[ptr uint8](wpaBase + 23)[] = 0x02
    cast[ptr uint8](wpaBase + 1)[] = 22     # IE body length
    ieBuf = cast[pointer](wpaBase + 24)
    bodyLen += 24

  # Add CSA IE if channel switch is pending (blob: co_pack8p at 0x26e)
  # Gate: chan_ctxt slot[14] != 0xFF indicates a pending CSA.
  let chanCtxPtr = cast[ptr pointer](vifBase + 64)[]
  if chanCtxPtr != nil:
    let csaCount = cast[ptr uint8](cast[uint](chanCtxPtr) + 14)[]
    if csaCount != 0xFF and csaCount != 0:
      var csaIe {.noinit.}: array[5, uint8]
      csaIe[0] = 37  # CSA IE ID
      csaIe[1] = 3   # Length
      csaIe[2] = cast[ptr uint8](cast[uint](chanCtxPtr) + 12)[]  # switch mode
      # Blob uses T-Head custom insns to compute the channel inline.
      # For 2.4GHz, chan = ((freq - 2412) / 5) + 1. Inlining avoids the
      # phy_freq_to_channel call that blob doesn't emit from the CSA path.
      let csaFreq = cast[ptr uint16](cast[uint](chanCtxPtr) + 6)[]
      csaIe[3] = ((csaFreq.int - 2412) div 5 + 1).uint8
      csaIe[4] = csaCount  # switch count
      co_pack8p(ieBuf, addr csaIe[0], 5)
      ieBuf = cast[pointer](cast[uint](ieBuf) + 5)
      bodyLen += 5

  # Add application beacon IEs if registered
  if appIeBeaconLen > 0 and appIeBeaconPtr != nil:
    discard c_memcpy(ieBuf, appIeBeaconPtr, appIeBeaconLen.csize_t)
    ieBuf = cast[pointer](cast[uint](ieBuf) + appIeBeaconLen.uint)
    bodyLen += appIeBeaconLen.uint32

  return bodyLen

proc me_build_probe_rsp*(buf: pointer, vifIdx: uint8,
                      lenOut: ptr uint16): uint32 {.exportc, cdecl.} =
  ## Build probe response frame IEs.
  ## From blob (202 instrs): builds probe response frame body.
  ## buf points to the probe response body (after MAC header).
  ## Writes: timestamp(8B, not written here), beacon_interval(2B at +8),
  ## capability(2B at +10), then IEs from offset 12.
  ## Nearly identical to beacon but without TIM IE, uses phy_freq_to_channel
  ## for DS param, and passes privacy to ERP IE.
  ## Returns total body length.
  let vifTabBase = cast[uint](addr vif_info_tab[0])
  let vifBase = vifTabBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let privacy = cast[ptr uint8](vifBase + 520)[]
  let p = cast[ptr UncheckedArray[uint8]](buf)

  # Write beacon interval at offset 8..9 (from VIF+514)
  let bcnInt = cast[ptr uint16](vifBase + 514)[]
  p[8] = (bcnInt and 0xFF).uint8
  p[9] = ((bcnInt shr 8) and 0xFF).uint8

  # Capability info
  var capInfo = me_build_capability(cast[pointer](vifIdx.uint))
  if privacy != 0:
    capInfo = capInfo or 16  # set privacy bit

  # Write capability at offset 10..11
  p[10] = (capInfo and 0xFF).uint8
  p[11] = ((capInfo shr 8) and 0xFF).uint8

  # Start building IEs at offset 12 (after timestamp+interval+capability)
  var ieBuf: pointer = cast[pointer](cast[uint](buf) + 12)

  # Add SSID IE from VIF+386 (length) and VIF+387 (data)
  let ssidLen = cast[ptr uint8](vifBase + 386)[]
  let ssidDataPtr = cast[pointer](vifBase + 387)
  var bodyLen: uint32 = me_add_ie_ssid(addr ieBuf, ssidDataPtr, ssidLen)

  # Add Supported Rates IE -- pass rates pointer from VIF+436
  let ratesPtr = cast[pointer](vifBase + 436)
  bodyLen += me_add_ie_supp_rates(addr ieBuf, ratesPtr)

  # Add Extended Supported Rates if > 8 rates
  let rateCount = cast[ptr uint8](vifBase + 436)[]
  if rateCount > 8:
    bodyLen += me_add_ie_ext_supp_rates(addr ieBuf, ratesPtr, rateCount.uint32)

  # Add 12 for the header (timestamp+interval+capability = 12 bytes)
  # Blob: addi s0,s0,12 at this point
  bodyLen += 12

  # Add DS Parameter Set IE: use phy_freq_to_channel (unlike beacon which
  # computes inline). Blob: lbu a0,2(a5) -> band; lhu a1,0(a5) -> freq;
  # call phy_freq_to_channel
  let chanPtr = cast[ptr pointer](vifBase + 424)[]
  let chanFreq = cast[ptr uint16](chanPtr)[]
  let chanBand = cast[ptr uint8](cast[uint](chanPtr) + 2)[]
  let chanNum = phy_freq_to_channel(chanBand, chanFreq)
  let dsLen = me_add_ie_ds(addr ieBuf, chanNum)

  # Add RSN IE unconditionally (blob: a1=privacy as secMode, at reloc 0xee)
  # privacy from VIF+520 is passed as secMode; me_add_ie_rsn returns 0 if secMode==0
  let rsnLen = me_add_ie_rsn(addr ieBuf, privacy)

  # Add ERP IE (blob: a1=0, at reloc 0xfc)
  let erpLen = me_add_ie_erp(addr ieBuf, 0)

  # Accumulate ds+rsn+erp into bodyLen
  let flagsWord = cast[ptr uint32](vifBase + 484)[]
  bodyLen += dsLen + rsnLen + erpLen

  # Add HT Capabilities + HT Operation IEs (conditional on flagsWord bit 1)
  # Blob: beqz flagsWord&2 → skip HT IEs, jump to me_add_ie_wpa
  if (flagsWord and 2) != 0:
    bodyLen += me_add_ie_ht_capa(addr ieBuf)
    bodyLen += me_add_ie_ht_oper(addr ieBuf, cast[pointer](vifBase))

  # Add WPA IE unconditionally (blob: a1=privacy as secMode, reloc 0x13e)
  bodyLen += me_add_ie_wpa(addr ieBuf, privacy)

  # Check WPA1 flag at VIF+484 bit 0 (from blob: 0x15e-0x260)
  if (flagsWord and 1) != 0:
    # Build WPA1 vendor IE inline (blob builds 4 cipher suites from VIF crypto state)
    # WPA OUI: 00-50-F2-01, version 1, group cipher, unicast cipher count
    let vifCrypto = cast[uint](vifBase)
    let cipherType = cast[ptr uint8](vifCrypto + 452)[]
    # WPA IE header: tag=0xDD, len, OUI(4), version(2), group_cipher(4), unicast_count(2), unicast(4), akm_count(2), akm(4)
    let wpaIeBase = cast[uint](ieBuf)
    cast[ptr uint8](wpaIeBase + 0)[] = 0xDD  # vendor IE tag
    cast[ptr uint8](wpaIeBase + 2)[] = 0x00  # OUI byte 0
    cast[ptr uint8](wpaIeBase + 3)[] = 0x50  # OUI byte 1
    cast[ptr uint8](wpaIeBase + 4)[] = 0xF2  # OUI byte 2
    cast[ptr uint8](wpaIeBase + 5)[] = 0x01  # WPA type
    cast[ptr uint8](wpaIeBase + 6)[] = 0x01  # version low
    cast[ptr uint8](wpaIeBase + 7)[] = 0x00  # version high
    # Group cipher suite OUI (00-50-F2) + cipher type
    cast[ptr uint8](wpaIeBase + 8)[] = 0x00
    cast[ptr uint8](wpaIeBase + 9)[] = 0x50
    cast[ptr uint8](wpaIeBase + 10)[] = 0xF2
    cast[ptr uint8](wpaIeBase + 11)[] = cipherType
    # Unicast cipher count = 1
    cast[ptr uint8](wpaIeBase + 12)[] = 0x01
    cast[ptr uint8](wpaIeBase + 13)[] = 0x00
    # Unicast cipher suite
    cast[ptr uint8](wpaIeBase + 14)[] = 0x00
    cast[ptr uint8](wpaIeBase + 15)[] = 0x50
    cast[ptr uint8](wpaIeBase + 16)[] = 0xF2
    cast[ptr uint8](wpaIeBase + 17)[] = cipherType
    # AKM count = 1
    cast[ptr uint8](wpaIeBase + 18)[] = 0x01
    cast[ptr uint8](wpaIeBase + 19)[] = 0x00
    # AKM suite (PSK)
    cast[ptr uint8](wpaIeBase + 20)[] = 0x00
    cast[ptr uint8](wpaIeBase + 21)[] = 0x50
    cast[ptr uint8](wpaIeBase + 22)[] = 0xF2
    cast[ptr uint8](wpaIeBase + 23)[] = 0x02  # PSK
    # Set length byte
    cast[ptr uint8](wpaIeBase + 1)[] = 22  # total IE body length
    # Advance buffer pointer and body length
    ieBuf = cast[pointer](wpaIeBase + 24)
    bodyLen += 24

  # Add CSA IE if channel switch is pending (blob: co_pack8p at 0x192)
  let chanCtxPtr = cast[ptr pointer](vifBase + 64)[]
  if chanCtxPtr != nil:
    let csaCount = cast[ptr uint8](cast[uint](chanCtxPtr) + 14)[]
    if csaCount != 0xFF and csaCount != 0:
      var csaIe {.noinit.}: array[5, uint8]
      csaIe[0] = 37  # CSA IE ID
      csaIe[1] = 3   # Length
      csaIe[2] = cast[ptr uint8](cast[uint](chanCtxPtr) + 12)[]  # switch mode
      # Blob uses T-Head custom insns to compute the channel inline.
      # For 2.4GHz, chan = ((freq - 2412) / 5) + 1. Inlining avoids the
      # phy_freq_to_channel call that blob doesn't emit from the CSA path.
      let csaFreq = cast[ptr uint16](cast[uint](chanCtxPtr) + 6)[]
      csaIe[3] = ((csaFreq.int - 2412) div 5 + 1).uint8
      csaIe[4] = csaCount  # switch count
      co_pack8p(ieBuf, addr csaIe[0], 5)
      ieBuf = cast[pointer](cast[uint](ieBuf) + 5)
      bodyLen += 5

  # Add application probe response IEs if registered
  if appIeProbeRespLen > 0 and appIeProbeRespPtr != nil:
    discard c_memcpy(ieBuf, appIeProbeRespPtr, appIeProbeRespLen.csize_t)
    ieBuf = cast[pointer](cast[uint](ieBuf) + appIeProbeRespLen.uint)
    bodyLen += appIeProbeRespLen.uint32

  # Write total length output
  if lenOut != nil:
    lenOut[] = bodyLen.uint16

  return bodyLen

proc me_build_add_ba_req*(buf: pointer, param: pointer): uint32 {.exportc, cdecl.} =
  ## Build ADDBA Request action frame body (9 bytes).
  ## From blob (30 instrs): a0=buf, a1=BA params struct.
  ## Struct offsets: [8]=SSN(u16), [10]=BA_timeout(u16), [14]=amsdu_supported(u8),
  ## [15]=buffer_size(u8), [16]=TID(u8), [17]=dialog_token(u8).
  ## Frame: [0]=category(3), [1]=action(0=ADDBA_REQ), [2]=dialog_token,
  ## [3..4]=BA_param_set(LE16), [5..6]=BA_timeout(LE16), [7..8]=start_seq(LE16).
  let p = cast[ptr UncheckedArray[uint8]](buf)
  p[0] = 3  # Category: Block Ack
  p[1] = 0  # Action: ADDBA Request
  if param == nil:
    return 9
  let s = cast[ptr UncheckedArray[uint8]](param)
  p[2] = s[17]  # Dialog Token
  # BA Parameter Set: bit0=amsdu, bits1-4=TID, bits6-15=buffer_size
  let amsdu = s[14].uint16 shl 1
  let tid = s[16].uint16 shl 2
  let bufSize = s[15].uint16 shl 6
  let baParams = amsdu or tid or bufSize
  p[3] = (baParams and 0xFF).uint8
  p[4] = ((baParams shr 8) and 0xFF).uint8
  # BA Timeout Value
  let timeout = cast[ptr uint16](cast[uint](param) + 10)[]
  p[5] = (timeout and 0xFF).uint8
  p[6] = ((timeout shr 8) and 0xFF).uint8
  # Starting Sequence Number (SSN << 4)
  let ssn = cast[ptr uint16](cast[uint](param) + 8)[]
  let ssnField = ssn shl 4
  p[7] = (ssnField and 0xFF).uint8
  p[8] = ((ssnField shr 8) and 0xFF).uint8
  return 9

proc me_build_add_ba_rsp*(buf: pointer, unused: pointer, baParams: uint16,
    dialogToken: uint8, statusCode: uint16): uint32 {.exportc, cdecl, noinline.} =
  ## Build ADDBA Response action frame body (9 bytes).
  ## From blob (15 instrs): writes category, action, dialog token,
  ## status code, BA parameter set, and zero timeout.
  ## noinline: blob calls this as a real function.
  let p = cast[ptr UncheckedArray[uint8]](buf)
  p[0] = 3  # Category: Block Ack
  p[1] = 1  # Action: ADDBA Response
  p[2] = dialogToken
  # Status Code (LE16)
  p[3] = (statusCode and 0xFF).uint8
  p[4] = ((statusCode shr 8) and 0xFF).uint8
  # BA Parameter Set (LE16)
  p[5] = (baParams and 0xFF).uint8
  p[6] = ((baParams shr 8) and 0xFF).uint8
  # BA Timeout Value = 0
  p[7] = 0
  p[8] = 0
  return 9

proc me_build_del_ba*(buf: pointer, baInfo: pointer, reasonCode: uint16): uint32 {.exportc, cdecl.} =
  ## Build DELBA action frame body (6 bytes).
  ## From blob (25 instrs): writes category=3, action=2, DELBA params, reason code.
  ## DELBA params: bit11 = initiator, bits 12-15 = TID.
  let p = cast[ptr UncheckedArray[uint8]](buf)
  p[0] = 3  # Category: Block Ack
  p[1] = 2  # Action: DELBA
  # Build DELBA Parameter Set
  var delbaParams: uint16 = 0
  if baInfo != nil:
    let s = cast[ptr UncheckedArray[uint8]](baInfo)
    let tid = s[16].uint16
    let initiator = s[13].uint8
    delbaParams = tid shl 12
    if initiator == 1:
      delbaParams = delbaParams or 0x0800'u16  # set initiator bit
  # DELBA Parameter Set (LE16)
  p[2] = (delbaParams and 0xFF).uint8
  p[3] = ((delbaParams shr 8) and 0xFF).uint8
  # Reason Code (LE16)
  p[4] = (reasonCode and 0xFF).uint8
  p[5] = ((reasonCode shr 8) and 0xFF).uint8
  return 6

proc me_build_capability*(param: pointer): uint16 {.exportc, cdecl.} =
  ## Build capability information field.
  ## From blob (14 instrs): param is vifIdx (uint8 in a0).
  ## Computes VIF entry, checks type. For STA (type 0), reads capability info
  ## from vif[434] to determine short preamble (bit 4) and short slot (bit 5).
  ## Always sets ESS (bit 0) and privacy (bit 10).
  let vifIdx = cast[uint](param)
  let vifTab = cast[uint](addr vif_info_tab[0])
  let vif = vifTab + vifIdx * VIF_ENTRY_SIZE.uint
  var cap = 1'u16  # ESS bit
  let vifType = cast[ptr uint8](vif + 86)[]
  if vifType == VIF_TYPE_STA:
    let beaconCap = cast[ptr uint16](vif + 434)[]
    if (beaconCap and 0x10) != 0:  # short preamble
      cap = cap or 0x10
    if (beaconCap and 0x20) != 0:  # short slot time
      cap = cap or 0x20
  cap = cap or 0x400  # privacy bit
  return cap

# ME rate/capability helpers
proc me_rate_translate*(rateConfig: uint32): uint32 {.exportc, cdecl.} =
  ## Translate 802.11 rate (in 0.5 Mbps units, masked to 7 bits) to rate index.
  ## From blob (49 instrs): maps standard rate values to internal indices.
  ## Rate -> Index: 2->0, 4->1, 11->2, 22->3, 12->4, 18->5, 24->6,
  ## 36->7, 48->8, 72->9, 96->10, 108->11. Unknown rates -> 255.
  let rate = rateConfig and 0x7F
  case rate
  of 2:   return 0    #  1   Mbps
  of 4:   return 1    #  2   Mbps
  of 11:  return 2    #  5.5 Mbps
  of 22:  return 3    # 11   Mbps
  of 12:  return 4    #  6   Mbps
  of 18:  return 5    #  9   Mbps
  of 24:  return 6    # 12   Mbps
  of 36:  return 7    # 18   Mbps
  of 48:  return 8    # 24   Mbps
  of 72:  return 9    # 36   Mbps
  of 96:  return 10   # 48   Mbps
  of 108: return 11   # 54   Mbps
  else:   return 255  # unknown rate

proc me_legacy_rate_bitfield_build*(rates: pointer, count: uint8): uint32 {.exportc, cdecl.} =
  ## Build legacy rate bitfield from supported rates array (55 instructions in blob).
  ## Iterates count entries from rates array (each u8 at rates[1+i], with rates[0]
  ## being the rate count prefix). For each rate, masks to 7 bits (removing basic
  ## rate flag bit 7), calls me_rate_translate to get the index (0..11), and if
  ## the index <= 11, sets (1 << index) in the result bitfield.
  ## Asserts at line 411 if me_rate_translate returns > 11.
  var bitfield: uint32 = 0
  let ratesArr = cast[ptr UncheckedArray[uint8]](rates)
  # The blob reads loop count from rates[0] (the rate count byte in the struct).
  # count parameter (a1) is used as a flag: when non-zero, extra rate filtering
  # is applied via custom instructions. When zero, all rates are included.
  let rateCount = ratesArr[0].int
  var i: int = 0
  while i < rateCount:
    # Each rate byte is at rates[1+i]; mask off basic rate flag (bit 7)
    let rateByte = ratesArr[1 + i] and 0x7F
    let rateIdx = me_rate_translate(rateByte.uint32)
    if rateIdx <= 11:
      bitfield = bitfield or (1'u32 shl rateIdx)
    else:
      assert_warn("me.c", "me.c", 411.cint)
    i += 1
  return bitfield

proc me_legacy_ridx_min*(bitfield: uint32): uint8 {.exportc, cdecl.} =
  ## Get minimum legacy rate index.
  ## From blob (10 instrs): scans bitfield from bit 0 upward, returns index of
  ## first set bit. Returns 12 if no bits set.
  for i in 0'u32 ..< 12:
    if ((bitfield shr i) and 1) != 0:
      return i.uint8
  return 12

proc me_legacy_ridx_max*(bitfield: uint32): uint8 {.exportc, cdecl.} =
  ## Get maximum legacy rate index.
  ## From blob (15 instrs): scans bitfield from bit 11 downward, returns index
  ## of highest set bit. Returns 12 if no bits set.
  if bitfield == 0:
    return 12
  for i in countdown(11'i32, 0):
    if ((bitfield shr i.uint32) and 1) != 0:
      return i.uint8
  return 12

proc me_rate_bitfield_vht_build*(param: pointer): uint32 {.exportc, cdecl.} =
  ## Build VHT rate bitfield.
  ## From blob (22 instrs): param is rxMcsMap (uint32 in a0), a1=txMcsMap.
  ## Iterates 8 NSS groups (2 bits each), for each: if either rx or tx field == 3,
  ## stop. Otherwise, takes the minimum of rx and tx MCS and inserts into result.
  ## Returns the combined supported MCS map (16-bit, 0xFFFF init).
  let rxMap = cast[uint32](param)
  # txMap would be in a1 (second C arg), but not visible in Nim
  # For single-arg Nim callers, return rxMap clamped to valid entries
  var res = 0xFFFF'u32
  var shift = 0'u32
  while shift < 16:
    let rxField = (rxMap shr shift) and 3
    if rxField == 3:
      break
    let mask = not (3'u32 shl shift)
    res = (res and mask) or (rxField shl shift)
    shift += 2
  return res

proc me_get_basic_rates*(vifIdx: uint8): uint32 {.exportc, cdecl.} =
  ## Get basic rate set for a VIF (16 instrs).
  ## From blob: a0=rate_set_ptr, a1=output_buf_ptr via C ABI.
  ## Clears output[0] to 0. Iterates rate_set[0] entries (count at rate_set[0]),
  ## reads rate_set[i+1] for each. If bit 7 set (basic rate), sign-extends,
  ## copies to output[output[0]+1], increments output[0].
  var outputBuf: pointer
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", outputBuf, ") );"].}
  let rateSetPtr = cast[uint](cast[pointer](vifIdx))  # a0 = rate_set_ptr
  let outU = cast[uint](outputBuf)
  # Clear output count
  cast[ptr uint8](outU)[] = 0
  # Iterate rate set
  let rateCount = cast[ptr uint8](rateSetPtr)[]
  var i: uint8 = 0
  let dataStart = rateSetPtr + 1  # rates begin at offset 1
  while i < rateCount:
    let rate = cast[ptr uint8](dataStart + i.uint)[]
    # Sign-extend byte to check bit 7 (basic rate indicator)
    let sextRate = cast[int8](rate)
    if sextRate < 0:  # bit 7 set = basic rate
      let curCount = cast[ptr uint8](outU)[]
      cast[ptr uint8](outU + curCount.uint + 1)[] = rate
      cast[ptr uint8](outU)[] = curCount + 1
    i += 1
  return 0

proc me_freq_to_chan_ptr*(band: uint8, freq: uint16): pointer {.exportc, cdecl.} =
  ## Convert band+frequency to channel context pointer — blob me_mgmtframe.o
  ## (84 bytes). Blob assertion shape:
  ##   if band != 0: assert_err("me.c", "me.c", 113)
  ##   count = me_env[0x7c]
  ##   table = me_env + 0x28
  ##   iterate table, compare 16-bit freq via T-Head custom insn 0xb867460b
  ##
  ## Previous Nim attempted a dual-band layout (band 1 used a different
  ## offset), but the blob HAL only supports band 0 — the assert_err
  ## enforces that invariant. Matching the blob's shape.
  if band != 0:
    assert_err("me.c", "me.c", 113)
  let meBase = cast[uint](addr me_env[0])
  let chanCount = cast[ptr uint8](meBase + 0x7C)[]
  let chanTable = meBase + 0x28
  let entryStride = 6'u
  for i in 0'u ..< chanCount.uint:
    let entry = chanTable + i * entryStride
    let entryFreq = cast[ptr uint16](entry)[]
    if entryFreq == freq:
      return cast[pointer](entry)
  return nil

proc me_extract_rate_set*(ieBuf: pointer, ieLen: uint32, rateOut: pointer) {.exportc, cdecl.} =
  ## Extract supported rate set from received frame IEs (68 instrs).
  ## Finds Supported Rates IE (ID=1) and Extended Supported Rates IE (ID=50),
  ## copies rate bytes into rateOut[1..N], stores count in rateOut[0].
  ## Rate byte format: bit7=basic flag, bits[6:0]=rate in 0.5Mbps units.
  ## rateOut layout: [0]=count, [1..count]=rate bytes (max 12 total).
  let out_arr = cast[ptr UncheckedArray[uint8]](rateOut)
  out_arr[0] = 0  # initialize count

  # Find Supported Rates IE (ID=1)
  let suppRatesIe = mac_ie_find(ieBuf, ieLen, 1)
  if suppRatesIe == nil:
    return

  let sr = cast[ptr UncheckedArray[uint8]](suppRatesIe)
  let srCount = sr[1]  # IE length = number of rate bytes
  if srCount > 12:
    return  # malformed: too many rates

  # Copy supported rates (strip to 7-bit rate value, keeping basic bit)
  var writePos: uint8 = 1  # rateOut[1] is first rate
  var i: uint8 = 0
  while i < srCount:
    let rateByte = cast[ptr uint8](cast[uint](suppRatesIe) + 2 + i.uint)[]
    # Store byte at writePos, using indexed store like the blob
    out_arr[writePos] = rateByte
    writePos += 1
    i += 1
  out_arr[0] = srCount

  # Find Extended Supported Rates IE (ID=50)
  let extRatesIe = mac_ie_find(ieBuf, ieLen, 50)
  if extRatesIe == nil:
    return

  let er = cast[ptr UncheckedArray[uint8]](extRatesIe)
  let erCount = er[1]
  let totalCount = out_arr[0].uint + erCount.uint
  if totalCount > 12:
    # assert_err but blob just bounds-checks and exits
    assert_err("me_mgmtframe.c", "me_mgmtframe.c", 897)
    if out_arr[0].int + erCount.int > 12:
      return  # too many rates combined

  # Append extended rates starting at rateOut[srCount+1]
  var erSrc = cast[uint](extRatesIe) + 2  # skip IE header
  var j: uint8 = 0
  while j < erCount:
    let rateByte = cast[ptr uint8](erSrc)[]
    let dstOff = out_arr[0] + 1 + j  # rateOut offset
    out_arr[dstOff] = rateByte
    erSrc += 1
    j += 1
  out_arr[0] = out_arr[0] + erCount

proc me_extract_country_reg*(ieBuf: pointer, ieLen: uint32, out_ptr: pointer) {.exportc, cdecl.} =
  ## Extract country/regulatory information from frame IEs (46 instructions in blob).
  ## Searches for Country IE (ID=7). If not found, returns immediately.
  ## If found:
  ##   - Loads regulatory data from out_ptr[76] (channel reg struct pointer).
  ##   - Reads environment byte from chanReg[2]: if non-zero, envStep=4, else envStep=1.
  ##   - Reads country code halfword from chanReg[0..1] and calls phy_channel_to_freq
  ##     to get the target channel.
  ##   - Iterates IE triplets (starting at IE+5, stride 3): each triplet is
  ##     (firstChan, numChan, maxPower). For each triplet, iterates numChan channels
  ##     (incrementing firstChan by envStep). When a channel matches the target,
  ##     stores maxPower at chanReg[4].
  let ie = mac_ie_find(ieBuf, ieLen, 7)  # Country IE = ID 7
  if ie == nil:
    return

  let ieAddr = cast[uint](ie)
  let outU = cast[uint](out_ptr)

  # out_ptr+76 (0x4C) points to the channel regulatory struct
  let chanRegBase = cast[ptr pointer](outU + 76)[]
  let chanRegU = cast[uint](chanRegBase)

  # Read environment byte from chanReg[2] (not from IE!)
  let envByte = cast[ptr uint8](chanRegU + 2)[]
  var envStep: uint8 = 1
  if envByte != 0:
    envStep = 4

  # Read country code from chanReg[0..1] and get target channel
  let countryHalf = cast[ptr uint16](chanRegU)[]
  let targetChan = phy_freq_to_channel(countryHalf.uint8, envStep.uint16)
  let targetChanU8 = targetChan

  # IE data: [0]=id, [1]=len, then data starts at [2].
  # Country IE data: [2..3]=country code string, [4]=environment, [5..]=triplets
  let ieLength = cast[ptr uint8](ieAddr + 1)[]
  var pos: uint8 = 5  # first triplet starts at IE+5

  while pos.int < ieLength.int + 2:  # while within IE bounds (id+len+data)
    let tripletBase = ieAddr + pos.uint
    var firstChan = cast[ptr uint8](tripletBase)[]
    let numChan = cast[ptr uint8](tripletBase + 1)[]

    # Iterate through all channels in this triplet
    var chanIdx: uint8 = 0
    while chanIdx != numChan:
      if firstChan == targetChanU8:
        # Match found: store max power from triplet byte 2
        let maxPower = cast[ptr uint8](tripletBase + 2)[]
        cast[ptr uint8](chanRegU + 4)[] = maxPower
        return
      firstChan = firstChan + envStep
      chanIdx += 1

    pos += 3

proc me_extract_csa*(ieBuf: pointer, ieLen: uint32, band: pointer,
                     csaOut: pointer) {.exportc, cdecl.} =
  ## Extract Channel Switch Announcement from beacon IEs (117 instrs).
  ## a0=ieBuf, a1=ieLen, a2=band ptr, a3=csaOut (8-byte output struct).
  ##
  ## Searches for CSA IE (ID=37), Extended CSA IE (ID=60), Secondary Channel
  ## Offset IE (ID=62), and Wide Bandwidth Channel Switch IE (ID=194,
  ## vendor-specific wrapper). Extracts new channel, switch mode, switch count,
  ## secondary offset, and computes new channel frequency via phy_channel_to_freq.
  ##
  ## csaOut layout: [0]=u8 csa_present, [1]=u8 sec_chan_offset, [2]=u16 freq,
  ##   [4]=u16 new_freq, [6]=u16 bw_freq.

  # Find CSA IE (ID=37) and Extended CSA IE (ID=60)
  let csaIe = mac_ie_find(ieBuf, ieLen, 37)
  let ecsaIe = mac_ie_find(ieBuf, ieLen, 60)

  # If neither found, return 0 (no CSA)
  if csaIe == nil and ecsaIe == nil:
    return  # a0=0 in blob means no CSA

  # Find Secondary Channel Offset IE (ID=62) and Wide BW CS IE (ID=194)
  let secChanIe = mac_ie_find(ieBuf, ieLen, 62)

  # Find vendor-specific Wide BW Channel Switch (ID=194 within subelement)
  let wbcsIe = mac_ie_find(ieBuf, ieLen, 196)
  var wbcsInner: pointer = nil
  if wbcsIe != nil:
    # Look inside for sub-element with ID=194
    let wbcsLen = cast[ptr uint8](cast[uint](wbcsIe) + 1)[]
    wbcsInner = mac_ie_find(cast[pointer](cast[uint](wbcsIe) + 2),
                            wbcsLen.uint32, 194)

  # Extract CSA fields
  var newChan: uint8
  var switchCount: uint8
  var switchMode: uint8
  var secOffset: uint8 = 0
  let bandVal = cast[ptr uint8](band)[]

  if csaIe != nil:
    # CSA IE format: [2]=switch_mode, [3]=new_channel, [4]=switch_count
    let ie = cast[ptr UncheckedArray[uint8]](csaIe)
    switchMode = ie[2]
    newChan = ie[4]
    switchCount = ie[3]  # blob: lbu s1, 4(s2) where s2=csaIe
  else:
    # Extended CSA IE: [2]=switch_mode, [4]=new_channel, [5]=switch_count
    let ie = cast[ptr UncheckedArray[uint8]](ecsaIe)
    switchMode = ie[2]
    newChan = ie[5]
    switchCount = ie[4]

  # If switch count is 0, default to 2
  if switchCount == 0:
    switchCount = 2

  # Determine if mode indicates immediate switch
  var csaPresent: uint8
  if switchMode >= 15:
    csaPresent = 1
  else:
    csaPresent = 0

  # Get frequency for new channel
  let newFreq = phy_channel_to_freq(bandVal, newChan)

  # Process secondary channel offset
  if secChanIe != nil:
    let scIe = cast[ptr UncheckedArray[uint8]](secChanIe)
    let scMode = scIe[2]
    secOffset = scMode
    # Validate: mode must be 1..3
    let modeAdj = scMode - 1
    if modeAdj <= 2:
      secOffset = scMode + 1
  elif wbcsInner != nil:
    # Wide BW Channel Switch sub-element
    let wbIe = cast[ptr UncheckedArray[uint8]](wbcsInner)
    let bwType = wbIe[2]
    var bwFreqOffset: int16 = 0
    if bwType == 1:
      bwFreqOffset = 10
    elif bwType == 3:
      bwFreqOffset = -10

    let bwFreq = phy_channel_to_freq(bandVal, wbIe[3])
    let freq0: uint16 = 0
    if wbIe[4] != 0:
      discard phy_channel_to_freq(bandVal, wbIe[4])

    cast[ptr uint16](cast[uint](csaOut) + 6)[] = bwFreq
    secOffset = 1  # default offset when wide BW present

  # Fill output struct
  cast[ptr uint8](cast[uint](csaOut) + 0)[] = csaPresent
  cast[ptr uint8](cast[uint](csaOut) + 1)[] = secOffset
  cast[ptr uint16](cast[uint](csaOut) + 2)[] = newFreq
  cast[ptr uint16](cast[uint](csaOut) + 4)[] = 0  # reserved/new_freq

proc me_extract_power_constraint*(ieBuf: pointer, ieLen: uint32, out_ptr: pointer) {.exportc, cdecl.} =
  ## Extract power constraint from frame IEs (14 instructions in blob).
  ## Searches for IE with ID=32 (Power Constraint). If found, reads byte at
  ## IE+2 (the constraint value) and stores it at out_ptr+132 (0x84).
  ## If not found, stores 0 at that offset.
  let ie = mac_ie_find(ieBuf, ieLen, 32)
  var constraintVal: uint8 = 0
  if ie != nil:
    constraintVal = cast[ptr uint8](cast[uint](ie) + 2)[]
  cast[ptr uint8](cast[uint](out_ptr) + 132)[] = constraintVal

proc me_11n_nss_max*(param: pointer): uint8 {.exportc, cdecl.} =
  ## Get max NSS for 11n.
  ## From blob (10 instrs): param points to HT MCS set bytes (4 bytes for NSS 0-3).
  ## Returns highest NSS index with non-zero MCS support.
  let p = cast[uint](param)
  if cast[ptr uint8](p + 3)[] != 0: return 3
  if cast[ptr uint8](p + 2)[] != 0: return 2
  if cast[ptr uint8](p + 1)[] != 0: return 1
  return 0

proc me_11ac_nss_max*(param: pointer): uint8 {.exportc, cdecl.} =
  ## Get max NSS for 11ac.
  ## From blob (10 instrs): param is actually the VHT MCS map (uint32 in a0).
  ## Scans 2-bit fields from NSS 7 (bits [15:14]) down to NSS 0 (bits [1:0]).
  ## Returns highest NSS where field != 3 (3 = not supported).
  let mcsMap = cast[uint32](param)
  var nss = 7'u8
  var shift = 14'u32
  while nss > 0:
    let field = (mcsMap shr shift) and 3
    if field != 3:
      return nss
    dec nss
    shift -= 2
  return nss

proc me_11ac_mcs_max*(param: pointer): uint8 {.exportc, cdecl.} =
  ## Get max MCS for 11ac.
  ## From blob (8 instrs): param is actually a VHT MCS map value (uint32 in a0).
  ## Checks bits [1:0]: 0 -> MCS 7, 1 -> MCS 8, 2 -> MCS 9, 3 -> not supported (7).
  let mcsMap = cast[uint32](param) and 3
  case mcsMap
  of 1: return 8
  of 2: return 9
  else: return 7

proc michael_block*(ctx: pointer, val: uint32) {.exportc, cdecl.} =
  ## Michael MIC block function (TKIP).
  ## ctx layout: [0]=uint32 L, [4]=uint32 R.
  ## From blob (43 instrs): XOR val into L, then perform the Michael
  ## permutation rounds: XSWAP, XOR, rotate, add operations.
  let pL = cast[ptr uint32](ctx)
  let pR = cast[ptr uint32](cast[uint](ctx) + 4)
  var L = pL[]
  var R = pR[]

  L = L xor val

  # Round 1: R ^= rotl(L, 17)
  R = R xor ((L shl 17) or (L shr 15))
  L = L + R

  # Round 2: byte-swap L (swap bytes 0,2 and 1,3 within halves)
  # Michael XSWAP: swap bytes within 16-bit halves
  let swapped = ((L and 0x00FF00FF'u32) shl 8) or
                ((L and 0xFF00FF00'u32) shr 8)
  L = swapped xor R

  # Round 3: R ^= rotl(L, 3)
  L = L + R
  R = R xor ((L shl 3) or (L shr 29))

  # Round 4: L ^= rotr(R, 2)  i.e., R ^= (L >> 2)
  L = L + R
  R = R xor ((L shr 2) or (L shl 30))

  L = L + R

  pL[] = R
  pR[] = L

proc me_mic_init*(micCtx: pointer, key: pointer, sa: pointer, da: pointer,
                  priority: uint8) {.exportc, cdecl.} =
  ## Initialize Michael MIC calculation (66 instrs).
  ## a0=micCtx, a1=key (8 bytes), a2=sa (6 bytes), a3=da (6 bytes), a4=priority.
  ## micCtx layout: [0]=L, [4]=R, [8]=pending, [12]=nBytes.
  ## Loads key into L,R, then processes a2[0..5] || a3[0..5] || priority
  ## via four michael_block calls.
  let ctx = micCtx

  # Load key words into ctx
  cast[ptr uint32](ctx)[] = cast[ptr uint32](key)[]
  cast[ptr uint32](cast[uint](ctx) + 4)[] = cast[ptr uint32](cast[uint](key) + 4)[]
  cast[ptr uint32](cast[uint](ctx) + 8)[] = 0   # pending = 0
  cast[ptr uint8](cast[uint](ctx) + 12)[] = 0   # nBytes = 0

  # Build packed LE32 words from sa (a2) and da (a3) per blob byte-build sequence
  let a2 = cast[ptr UncheckedArray[uint8]](sa)
  let a3 = cast[ptr UncheckedArray[uint8]](da)

  let word0 = a2[0].uint32 or (a2[1].uint32 shl 8) or
              (a2[2].uint32 shl 16) or (a2[3].uint32 shl 24)
  let word1 = (a2[4].uint32 or (a2[5].uint32 shl 8)) or
              ((a3[0].uint32 or (a3[1].uint32 shl 8)) shl 16)
  let word2 = a3[2].uint32 or (a3[3].uint32 shl 8) or
              (a3[4].uint32 shl 16) or (a3[5].uint32 shl 24)

  var prio2: uint32 = priority.uint32 and 7
  if priority == 0xFF:
    prio2 = 0

  michael_block(ctx, word0)
  michael_block(ctx, word1)
  michael_block(ctx, word2)
  michael_block(ctx, prio2)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void me_mic_calc(void*,void*,unsigned long);".}
proc me_mic_calc*(ctx: pointer, data: pointer, dataLen: uint32) {.exportc, cdecl.} =
  ## Calculate TKIP Michael MIC over data buffer (117 instrs).
  ## ctx = MIC context (layout: [0]=L, [4]=R, [8]=pending_word, [12]=nBytes).
  ## Processes data byte-by-byte, accumulating into the pending word.
  ## When 4 bytes are accumulated, calls michael_block(ctx, pending_word)
  ## and resets the byte counter.
  ##
  ## Assembly trace: handles unaligned start and bulk 4-byte processing.
  ## Uses word-aligned loads with shift/mask for efficiency.
  let ctxAddr = cast[uint](ctx)
  let buf = cast[ptr UncheckedArray[uint8]](data)
  var nBytes = cast[ptr uint8](ctxAddr + 12)[]
  var pending = cast[ptr uint32](ctxAddr + 8)[]
  var offset: uint32 = 0
  var remaining = dataLen

  # Handle unaligned start: fill pending word up to 4 bytes
  if nBytes > 0 and remaining > 0:
    let needed = 4'u32 - nBytes.uint32
    let toProcess = if remaining < needed: remaining else: needed
    for i in 0'u32 ..< toProcess:
      pending = pending or (buf[offset].uint32 shl (nBytes.uint32 * 8))
      nBytes += 1
      offset += 1
      remaining -= 1
    if nBytes >= 4:
      michael_block(ctx, pending)
      pending = 0
      nBytes = 0

  # Process bulk 4-byte words (single michael_block call site per loop,
  # matching blob's structure).
  while remaining >= 4:
    let word = buf[offset].uint32 or
               (buf[offset + 1].uint32 shl 8) or
               (buf[offset + 2].uint32 shl 16) or
               (buf[offset + 3].uint32 shl 24)
    let blockIn = if nBytes > 0: pending or (word shl (nBytes.uint32 * 8))
                  else: word
    michael_block(ctx, blockIn)
    pending = if nBytes > 0: word shr ((4 - nBytes.uint32) * 8) else: 0
    offset += 4
    remaining -= 4

  # Handle remaining bytes
  for i in 0'u32 ..< remaining:
    pending = pending or (buf[offset].uint32 shl (nBytes.uint32 * 8))
    nBytes += 1
    offset += 1
    if nBytes >= 4:
      michael_block(ctx, pending)
      pending = 0
      nBytes = 0

  # Store state back
  cast[ptr uint32](ctxAddr + 8)[] = pending
  cast[ptr uint8](ctxAddr + 12)[] = nBytes

proc me_mic_end*(ctx: pointer) {.exportc, cdecl.} =
  ## Finalize MIC calculation (from disassembly).
  ## Pads the remaining bytes with 0x5A marker byte, then performs a final
  ## michael_block call to produce the final MIC value.
  ## ctx layout: [0]=L, [4]=R, [8]=pending_word, [12]=nBytes.
  let ctxAddr = cast[uint](ctx)
  let nBytes = cast[ptr uint8](ctxAddr + 12)[]
  let pending = cast[ptr uint32](ctxAddr + 8)[]
  # Assert nBytes <= 3
  if nBytes > 3:
    # Blob uses assert_err, not assert_rec.
    assert_err("me_mic.c", "me_mic.c", 323)
  # Pad with 0x5A at the current byte position
  let padShift = nBytes.uint32 * 8
  let padded = pending or (0x5A'u32 shl padShift)
  michael_block(ctx, padded)
  # Final block with zero
  michael_block(ctx, 0)

# ###########################################################################
#                   RC: Rate Control
# ###########################################################################

proc rc_init*(staEntry: pointer) {.exportc, cdecl.} =
  ## Initialize rate control for a station.
  ##
  ## Takes a pointer to sta_info_tag (NOT a staIdx). Called from me_init_rate.
  ## From disassembly (463 instructions):
  ##   1. Allocate rc_sta_stats from pool (indexed by sta[40] * 200)
  ##   2. Store stats ptr at sta+324
  ##   3. Zero 200-byte stats struct
  ##   4. Branch HT (sta+308 bit1) vs legacy:
  ##      HT: format_mod=2, build legacy rate_map from supported rates at sta+248,
  ##          compute NSS groups, set lowest/highest/short_gi/bw_max
  ##      Legacy: format_mod=0, build rate_map from supported rates,
  ##          set lowest/highest, max_nss_mcs=0xFF
  ##   5. Count total supported rates -> n_rates (clamped to 10)
  ##   6. Fill rate table: entry[0]=initial_rate, then iterate with
  ##      rc_set_next_mcs_index / rc_check_valid_rate
  ##   7. Set max_tp_idx=n_rates-1, max_tp2_idx=n_rates-2, max_prob_idx=n_rates-3
  ##   8. prob_avg=0x10000, sample_idx=0xFFFF, retry_limit=5
  ##   9. Call rc_update_retry_chain
  ##  10. Build TX policy descriptor at sta+320:
  ##      4 retry chain entries from rate table + 0x80000000,
  ##      status=0xBADCAB1E, bufAddr=TRNG<<14, pktType=(infoIdx+8)<<10,
  ##      controlInfo=0xFFFF0704, edca=0x2200, vif from sta+28
  ##  11. sta[334] |= 0x11
  let sta = staEntry
  let infoIdx = staU8(sta, STA_INFO_IDX_OFF)

  # Validate info_idx <= 4 (from disasm: li a4,4; bgeu a4,a5)
  if infoIdx > 4:
    assert_err("rc.c", "rc.c", 0x858.cint)

  # Query PHY TX chain count (blob: phy_get_ntx at 0x6C)
  let ntx = phy_get_ntx()

  # Allocate rc_sta_stats from pool: stats = pool_base + infoIdx * 200
  let statsBase = cast[pointer](cast[uint](addr rcStaStatsPool[0]) +
                                 infoIdx.uint * RC_STATS_SIZE.uint)
  # Store pointer at sta+324 (0x144)
  staPtr(sta, STA_RC_STATS_PTR_OFF) = statsBase

  # Vendor seeds the TX policy buffer address from phy_get_ntx() << 14.
  var bufAddr = ntx.uint32 shl 14  # will be OR'd with LDPC capability below

  # Zero-fill the 200-byte stats structure (blob: memset at 0x80)
  discard c_memset(statsBase, 0, RC_STATS_SIZE.csize_t)

  # Determine HT vs legacy from rate_info_flags bit 1
  let rateInfoFlags = staU32(sta, STA_RATE_INFO_FLAGS_OFF)
  let isHT = (rateInfoFlags and 2) != 0

  if isHT:
    # ---- HT path (disasm 0x98..0x2C4) ----
    # format_mod = 2 (HT mixed format)
    rcU8(statsBase, RCS_FORMAT_MOD) = RC_FORMATMOD_HT_MF

    # Build the legacy rate map from the supported-rates block at sta+248.
    # The HT MCS bitmap at sta+267 is handled below by me_11n_nss_max/copy.
    # Feeding the MCS bitmap here makes the builder interpret a bitmask byte
    # as a length byte, which trips the vendor me.c:411 warning path.
    let legacyRatesBase = cast[pointer](cast[uint](sta) + 248'u)
    let rateMapBuilt = me_legacy_rate_bitfield_build(legacyRatesBase, 0)
    rcU16(statsBase, RCS_RATE_MAP) = rateMapBuilt.uint16

    # HT MCS bitmask base used by the 11n-specific path (blob 0xB0+)
    let htMcsBase = cast[uint](sta) + STA_HT_MCS_SET_OFF.uint

    # Get NSS max via me_11n_nss_max (blob 0xB0, 0xC2)
    # First call: remote STA's HT MCS set (sta+267)
    let nssMax1 = me_11n_nss_max(cast[pointer](htMcsBase))
    # Second call: local device HT MCS set (me_env+0xb)
    let nssMax2 = me_11n_nss_max(cast[pointer](cast[uint](addr me_env[0]) + 0xB))
    # Blob stores the max NSS group index, not a group count. A single-stream
    # peer is represented as group 0 and must still contribute rates below.
    var groupCnt {.volatile.}: uint8 = if nssMax2 < nssMax1: nssMax2 else: nssMax1
    if groupCnt > 3:
      assert_err("rc.c", "rc.c", 0x89F.cint)
    rcU8(statsBase, RCS_GROUP_CNT) = groupCnt

    # Copy 4 bytes of MCS bitmask to stats.rate_bitmap (offset 178)
    discard c_memcpy(
      cast[pointer](cast[uint](statsBase) + RCS_RATE_BITMAP.uint),
      cast[pointer](htMcsBase), 4.csize_t)

    # max_nss_mcs = 0xFF initially (set properly below)
    rcU8(statsBase, RCS_MAX_NSS_MCS) = 0xFF'u8

    # Find lowest/highest valid MCS index via me_legacy_ridx_min/max (blob 0x126, 0x164)
    let rm = rcU16(statsBase, RCS_RATE_MAP)
    var loIdx {.volatile.}: uint8 = me_legacy_ridx_min(rm.uint32)
    rcU8(statsBase, RCS_LOWEST_IDX) = loIdx
    if loIdx > 12:
      assert_err("rc.c", "rc.c", 0x8B1.cint)

    var hiIdx {.volatile.}: uint8 = me_legacy_ridx_max(rm.uint32)
    rcU8(statsBase, RCS_HIGHEST_IDX) = hiIdx
    if hiIdx > 12:
      assert_err("rc.c", "rc.c", 0x8B7.cint)

    # BW max from sta+332 (supported rates bitmap)
    let suppRates = staU16(sta, STA_SUPP_RATES_OFF)
    rcU8(statsBase, RCS_BW_MAX) = ((suppRates shr 10) and 0x3).uint8

    # LDPC support check (blob: phy_ldpc_tx_supported at 0x1AA)
    let htCapInfo = staU16(sta, STA_HT_CAP_INFO_OFF)
    if phy_ldpc_tx_supported() and (htCapInfo and 1) != 0:
      bufAddr = bufAddr or 64  # set LDPC bit

    # 40MHz support check (bit 11 = 0x800)
    if (htCapInfo and 0x800'u16) != 0:
      rcU16(statsBase, RCS_RATE_MAP_L) = 0x2000'u16 - 0x0101'u16
    else:
      rcU16(statsBase, RCS_RATE_MAP_L) = 0x1000'u16 - 0x0101'u16

    # NSS config from sta+313
    let noSS = staU8(sta, STA_NSS_BW_MAX_OFF)
    rcU8(statsBase, RCS_NO_SS) = noSS
    if noSS > 3:
      assert_err("rc.c", "rc.c", 0x8CE.cint)

    # Short GI configuration based on NSS and HT capabilities
    if noSS == 0:
      if (htCapInfo and 0x20) != 0:  # SGI 20MHz
        rcU8(statsBase, RCS_SHORT_GI) = 1
    elif noSS == 1:
      if (htCapInfo and 0x40) != 0:  # SGI 40MHz
        rcU8(statsBase, RCS_SHORT_GI) = 1

  else:
    # ---- Non-HT (legacy) path (disasm L296, 0x2C6..0x38E) ----
    # format_mod stays 0 (already zeroed)

    # Build legacy rate map via me_legacy_rate_bitfield_build (blob 0x2C6)
    let rateInfoBase = cast[pointer](cast[uint](sta) + 248)
    let rateMapBuilt = me_legacy_rate_bitfield_build(rateInfoBase, 0)
    var rateMap: uint16 = rateMapBuilt.uint16
    if rateMap == 0:
      rateMap = 0x0FFF'u16
    rcU16(statsBase, RCS_RATE_MAP) = rateMap

    # Lowest/highest via me_legacy_ridx_min/max (blob 0x2D2, 0x310)
    let loIdx = me_legacy_ridx_min(rateMap.uint32)
    rcU8(statsBase, RCS_LOWEST_IDX) = loIdx
    if loIdx > 11:
      assert_err("rc.c", "rc.c", 0x8ED.cint)

    let hiIdx = me_legacy_ridx_max(rateMap.uint32)
    rcU8(statsBase, RCS_HIGHEST_IDX) = hiIdx
    if hiIdx > 11:
      assert_err("rc.c", "rc.c", 0x8EF.cint)

    # Legacy: max_nss_mcs = 0xFF (not applicable), max_nss_mcs at +184
    rcU8(statsBase, RCS_MAX_NSS_MCS) = 0xFF'u8

    # Copy NSS config
    let noSS = staU8(sta, STA_NSS_BW_MAX_OFF)
    rcU8(statsBase, RCS_NO_SS) = noSS
    if noSS != 0:
      assert_err("rc.c", "rc.c", 0x8F2.cint)

    # BW max
    let suppRates = staU16(sta, STA_SUPP_RATES_OFF)
    rcU8(statsBase, RCS_BW_MAX) = ((suppRates shr 10) and 0x3).uint8

  # ---- Common path: count supported rates (disasm L306 -> L312) ----
  let fmtMod = rcU8(statsBase, RCS_FORMAT_MOD)
  let rMap = rcU16(statsBase, RCS_RATE_MAP)
  let bwMax = rcU8(statsBase, RCS_BW_MAX)
  let sgi = rcU8(statsBase, RCS_SHORT_GI)

  if fmtMod <= 1:
    # Legacy rate count: count set bits in rate_map, also check OFDM extension
    # From disasm (L310/L315): complex bit-counting loop
    var nRates: uint16 = 0
    # Count bits in positions 0..3 (CCK rates)
    for i in 0 ..< 4:
      if (rMap and (1'u16 shl i)) != 0:
        inc nRates
    # Count bits in positions 4..11 (OFDM rates)
    for i in 4 ..< 12:
      let bit = (rMap shr i.uint16) and 1
      nRates = nRates + bit
    if nRates > 10:
      nRates = 10
    rcU16(statsBase, RCS_N_RATES) = nRates
  else:
    # HT: count rate combinations from MCS bitmaps * BW * SGI
    var nRates: uint16 = 0
    let gCnt = rcU8(statsBase, RCS_GROUP_CNT)
    # Count valid MCS indices across all NSS groups. gCnt is the max group
    # index, so include group 0 when the peer supports one spatial stream.
    for g in 0'u8 .. gCnt:
      let mcsByte = rcU8(statsBase, RCS_RATE_BITMAP + g.int)
      for m in 0 ..< 8:
        if (mcsByte and (1'u8 shl m)) != 0:
          inc nRates
    # Multiply by BW variants and SGI
    if bwMax > 0:
      nRates = nRates * 2
    if sgi != 0:
      nRates = nRates * 2
    if nRates > 10:
      nRates = 10
    rcU16(statsBase, RCS_N_RATES) = nRates

  # Volatile reload so GCC range-analysis can't prove these asserts
  # are dead (matching blob which keeps both defensively).
  var nR {.volatile.}: uint16 = rcU16(statsBase, RCS_N_RATES)
  if nR == 0:
    assert_err("rc.c", "rc.c", 0x8F8.cint)
  if nR > 10:
    assert_err("rc.c", "rc.c", 0x8F9.cint)

  # ---- Build rate table (disasm L317 -> L324) ----
  # Re-derive stats from sta+324 (follows disasm at 0x3F0)
  let stats = staPtr(sta, STA_RC_STATS_PTR_OFF)
  if stats == nil:
    assert_err("rc.c", "rc.c", 1764.cint)

  # Initialize all rate_config slots to 0xFFFF.
  let nRates = rcU16(stats, RCS_N_RATES)
  for i in 0 ..< nRates.int:
    rcSetRateConfig(stats, i, 0xFFFF'u16)

  # Vendor layout:
  #   entry[0]          = lowest usable rate
  #   entry[n_rates-1]  = initial/highest rate
  #   entries in between are filled by rc_new_random_rate until non-duplicate.
  let lowestRateConfig = rc_get_lowest_rate_config(stats)
  rcSetRateConfig(stats, 0, lowestRateConfig)

  let initialRate = rc_get_initial_rate_config(stats)
  if nRates > 0:
    rcSetRateConfig(stats, nRates.int - 1, initialRate)

  var fillIdx = 1
  while fillIdx < nRates.int - 1:
    var randomRate: uint16 = 0xFFFF'u16
    var tries = 0
    while tries < 64:
      randomRate = rc_new_random_rate(stats)
      if rc_check_rate_duplicated(stats, randomRate) == 0:
        break
      inc tries
    if tries >= 64:
      let fmtForFill = rcU8(stats, RCS_FORMAT_MOD)
      var foundFallback = false
      if fmtForFill <= 1:
        let rateMap = rcU16(stats, RCS_RATE_MAP)
        let lo = rcU8(stats, RCS_LOWEST_IDX)
        let hi = rcU8(stats, RCS_HIGHEST_IDX)
        let bw = rcU8(stats, RCS_BW_MAX).uint16 shl 10
        var idx = lo
        while idx <= hi:
          if ((rateMap shr idx) and 1'u16) != 0:
            var candidate = (fmtForFill.uint16 shl 11) or idx.uint16
            if idx == 0:
              candidate = candidate or 0x400'u16
            elif idx - 1 <= 2:
              candidate = candidate or bw
            if rc_check_rate_duplicated(stats, candidate) == 0:
              randomRate = candidate
              foundFallback = true
              break
          if idx == 0xFF'u8:
            break
          inc idx
      else:
        let groupCnt = rcU8(stats, RCS_GROUP_CNT)
        let maxMcs = rcU8(stats, RCS_MAX_NSS_MCS)
        let sgi = rcU8(stats, RCS_SHORT_GI)
        var group: uint8 = 0
        while group <= groupCnt:
          let bitmap = rcU8(stats, RCS_RATE_BITMAP + group.int)
          var mcs: uint8 = 0
          while mcs <= maxMcs and mcs < 8:
            if ((bitmap shr mcs) and 1'u8) != 0:
              var candidate = (fmtForFill.uint16 shl 11) or
                              (group.uint16 shl 3) or mcs.uint16
              if sgi != 0:
                candidate = candidate or 0x200'u16
              if rc_check_rate_duplicated(stats, candidate) == 0:
                randomRate = candidate
                foundFallback = true
                break
            inc mcs
          if foundFallback or group == 0xFF'u8:
            break
          inc group
      if not foundFallback:
        break
    rcSetRateConfig(stats, fillIdx, randomRate)
    inc fillIdx

  # ---- Set initial indices (disasm 0x474..0x4AC) ----
  rcU16(stats, RCS_MAX_TP_IDX) = nRates - 1
  rcU16(stats, RCS_MAX_TP2_IDX) = if nRates >= 2: nRates - 2 else: 0
  rcU16(stats, RCS_MAX_PROB_IDX) = if nRates >= 3: nRates - 3 else: 0
  rcU32(stats, RCS_PROB_AVG) = 0x10000'u32
  rcU16(stats, RCS_SAMPLE_IDX) = 0xFFFF'u16

  # Clear throughput/timer fields
  rcU32(stats, RCS_TP_CUR) = 0
  rcU32(stats, RCS_TP_SECOND) = 0
  rcU32(stats, RCS_TP_THIRD) = 0
  rcU16(stats, RCS_RESERVED_U16) = 0
  rcU32(stats, RCS_RETRY_TIMER) = 0
  rcU8(stats, RCS_FLAGS) = 0

  # Update initial statistics (blob: rc_update_stats at 0x4AE; blob does NOT
  # call rc_update_retry_chain from rc_init — it's done from rc_update_stats).
  discard rc_update_stats(stats, 1)

  # Second PHY query for policy mask setup (blob: phy_get_ntx at 0x51E).
  let ntx2 = phy_get_ntx()

  # ---- Configure TX policy (disasm 0x4B6..0x552) ----
  rcU8(stats, RCS_RETRY_LIMIT) = 5

  let txPolicy = staPtr(sta, STA_TX_POLICY_PTR_OFF)

  # Encode 4 retry chain entries into txPolicy+20..+36
  # Each entry uses the index bytes stored at stats+128, +136, +144, +152
  # and writes rate_config[index] | 0x80000000 to txPolicy+20+i*4.
  let retryIndexOffsets = [RCS_MAX_TP_IDX, RCS_MAX_TP2_IDX, RCS_MAX_PROB_IDX, RCS_RESERVED_U16]
  for i in 0 ..< 4:
    let retryIdx = rcU8(stats, retryIndexOffsets[i]).uint16
    let entryRate =
      if retryIdx < nRates: rcRateConfig(stats, retryIdx.int)
      else: 0xFFFF'u16
    let packed = entryRate.uint32 or 0x80000000'u32
    cast[ptr uint32](cast[uint](txPolicy) + 20 + (i * 4).uint)[] = packed

  # Read MACHW timestamp low for TX descriptor
  let tsNow = regRead(MACHW_TIMLO_REG)

  # pkt_type = ((infoIdx + 8) & 0xFF) << 10
  let pktType = ((infoIdx.uint32 + 8) and 0xFF) shl 10

  # status = 0xBADCAB1E
  cast[ptr uint32](cast[uint](txPolicy) + 0)[] = 0xBADCAB1E'u32
  # bufAddr
  cast[ptr uint32](cast[uint](txPolicy) + 4)[] = bufAddr
  # bufMask = (1 << (phy_get_ntx() + 1)) - 1
  cast[ptr uint32](cast[uint](txPolicy) + 8)[] =
    (1'u32 shl (ntx2.uint32 + 1'u32)) - 1'u32
  # pkt_type
  cast[ptr uint32](cast[uint](txPolicy) + 12)[] = pktType
  # controlInfo = 0xFFFF0704
  cast[ptr uint32](cast[uint](txPolicy) + 16)[] = 0xFFFF0704'u32
  # edcaParam0 = 0x2200
  cast[ptr uint32](cast[uint](txPolicy) + 52)[] = 0x2200'u32
  # edcaParam1 = VIF pointer
  cast[ptr uint32](cast[uint](txPolicy) + 56)[] = cast[uint32](staPtr(sta, STA_VIF_PTR_OFF))

  # Set RC flags on station: sta[334] |= 0x11
  staU8(sta, STA_RC_FLAGS_OFF) = staU8(sta, STA_RC_FLAGS_OFF) or 0x11'u8


{.emit: "__attribute__((optimize(\"crossjumping\"))) void rc_check(unsigned char);".}
proc rc_check*(staIdx: uint8) {.exportc, cdecl.} =
  ## Minstrel-like rate control check/update (called periodically per-STA).
  ##
  ## From disassembly (242 instructions):
  ##   1. Validate staIdx <= 4
  ##   2. Compute sta entry: sta_info_tab + staIdx * 368
  ##   3. Load rc_sta_stats from sta+324; assert non-nil
  ##   4. Check elapsed time: if (RC_UPDATE_INTERVAL - (now - last_ts)) < 0,
  ##      call rc_update_stats, reset update_stage/flags, store new timestamp
  ##   5. Process update_stage:
  ##      stage==1 (sampling):
  ##        - Skip if flags bit6 set
  ##        - Compute throughput threshold from current max_tp entry
  ##        - Generate sample rate via LCG PRNG: (state*0x41C64E6D + 0x3039)>>16 % n_rates
  ##        - Skip if sample == max_tp/max_tp2/max_prob
  ##        - Compare sample duration vs max_tp duration
  ##        - Better: promote sample->max_tp, demote old->max_tp2
  ##        - Worse but viable: track candidate, increment slow_rate_cnt
  ##        - Set stage=2
  ##      stage==3 (finalize):
  ##        - If not fixed (flags bit1==0): demote max_tp->max_tp2
  ##        - Restore sample_candidate, clear prev_tp, set sample_cand=0xFF
  ##   6. If stats were updated, set sta[334] |= 1

  # Validate staIdx (disasm: li a5,4; bltu a5,a0 -> return)
  if staIdx > 4:
    return

  # Derive sta entry pointer
  let sta = cast[pointer](cast[uint](addr sta_info_tab[0]) +
                           staIdx.uint * STA_ENTRY_SIZE.uint)

  # Load rc_sta_stats pointer from sta+324
  let stats = staPtr(sta, STA_RC_STATS_PTR_OFF)
  if stats == nil:
    # Blob uses assert_err here (different sink than Nim's previous
    # assert_warn; blob matches `1 assert_err` in rc_check's call graph).
    assert_err("rc_check", "rc_check", 0x822)

  # ---- Check update interval (disasm LBB325/LBE321, 0x5C..0xA0) ----
  let tsNow = regRead(MACHW_TIMLO_REG)
  let lastTs = rcU32(stats, 0)  # last_update_ts at offset 0
  let timeDiff = tsNow - lastTs
  let remaining = RC_UPDATE_INTERVAL - timeDiff  # unsigned wrapping subtraction

  var didUpdate: uint8 = 0
  if remaining.int32 < 0:
    # Interval elapsed: run statistics update
    didUpdate = rc_update_stats(stats, 0)

    # Reset per-update fields (disasm 0x84..0x9C)
    rcU8(stats, RCS_UPDATE_STAGE) = 0
    rcU8(stats, RCS_ANOTHER_FLAG) = 0
    rcU8(stats, RCS_FLAGS) = rcU8(stats, RCS_FLAGS) and not 0x10'u8

    # Store current timestamp (disasm: sw a4, 0(s4))
    rcU32(stats, 0) = tsNow

  # ---- Process update_stage (disasm 0xA0..0x302) ----
  let stage = rcU8(stats, RCS_UPDATE_STAGE)

  if stage == 1:
    # ---- Sampling phase (disasm LBB338, 0xAA..0x25A) ----
    let flags = rcU8(stats, RCS_FLAGS)

    # Check skip flag (bit 6 = 0x40)
    if (flags and 0x40) != 0:
      # Skip this round (disasm L366)
      rcU8(stats, RCS_UPDATE_STAGE) = 0
    else:
      let fmtMod = rcU8(stats, RCS_FORMAT_MOD)
      let maxTpIdx = rcU16(stats, RCS_MAX_TP_IDX)

      # Determine throughput evaluation threshold
      # (disasm 0xBA..0xE4: check format_mod vs rate count, compute timer)
      var evalTimer: uint16
      if fmtMod < 1:
        # Legacy: check rate entry throughput directly
        let entryBase = rcRateEntryPtr(stats, maxTpIdx.int)
        let curTp = rcU16(entryBase, 8)
        # Subtract baseline and check against threshold 0xD99A
        let adjusted = curTp.uint32 - 0x1999'u32
        if adjusted > 0xD99A'u32:
          evalTimer = 5   # very low/high tp: use short timer
        else:
          evalTimer = 10  # normal range
      else:
        # HT: use AMPDU length as threshold baseline
        let ampduLen = rcU16(stats, RCS_AVG_AMPDU_LEN)
        evalTimer = (ampduLen + 8) * 2

      # ---- Generate random sample rate (disasm LBB346, 0xF4..0x128) ----
      # LCG: prng = prng * 0x41c64e6d + 0x3039
      let prngVal = rcPrngNext()
      let nRates = rcU16(stats, RCS_N_RATES)

      # sample = (prng >> 16) % n_rates
      let sample = ((prngVal shr 16) mod nRates.uint32).uint16

      # Skip if sample matches any of the best indices (disasm 0x114..0x128)
      if sample == maxTpIdx or
         sample == rcU16(stats, RCS_MAX_TP2_IDX) or
         sample == rcU16(stats, RCS_MAX_PROB_IDX):
        # Bail out (disasm L366)
        rcU8(stats, RCS_UPDATE_STAGE) = 0
      else:
        # ---- Evaluate sample rate (disasm 0x128..0x25A) ----
        # Check sample entry's throughput against threshold
        let sampleEntryBase = rcRateEntryPtr(stats, sample.int)
        let sampleTpRaw = rcU16(sampleEntryBase, 8)

        # Threshold check: if tp > 0xF333, skip (disasm 0x136..0x13A)
        if sampleTpRaw > 0xF333'u16:
          rcU8(stats, RCS_UPDATE_STAGE) = 0
        else:
          # Get duration estimates for comparison
          let sampleRate = rcRateConfig(stats, sample.int)
          let sampleDur = rc_get_duration(sampleRate.uint32, 1)

          # Check if fmtMod count > 1 (more detailed comparison for HT)
          let fmtCount = fmtMod
          if fmtCount > 1:
            # ---- HT extended comparison (disasm L361, 0x1D0..0x234) ----
            var minRetryLen: uint16 = 32

            let entryFlags = rcU8(sampleEntryBase, 13)
            if entryFlags == 0:
              minRetryLen = rcU16(stats, RCS_AVG_AMPDU_LEN)

            # Blob 0x1de: get duration of max_tp2 rate for compare
            let maxTp2Rate = rcRateConfig(stats, rcU16(stats, RCS_MAX_TP2_IDX).int)
            let maxTp2Dur = rc_get_duration(maxTp2Rate.uint32, 1)

            var promote = false

            if sampleDur < maxTp2Dur:
              # Sample beats max_tp2: jump straight to promote (blob L364)
              promote = true
            else:
              # Blob 0x200: get NSS of sample rate
              let sampleNss = rc_get_nss(sampleRate)
              # Blob 0x20c: get NSS of max_tp2 rate
              let maxTp2Nss = rc_get_nss(maxTp2Rate)

              if (maxTp2Nss.int - 1) < sampleNss.int:
                # Same/better NSS: compare against max_tp duration (blob 0x228)
                let maxTpRate = rcRateConfig(stats, maxTpIdx.int)
                let maxTpDur = rc_get_duration(maxTpRate.uint32, 1)
                if sampleDur < maxTpDur:
                  promote = true

            if promote:
              # ---- Promote (blob L364 @0x280) ----
              # Blob 0x286: rc_calc_tp(sample entry, rc_stats).
              discard rc_calc_tp(sampleEntryBase, stats)
              # After rc_calc_tp, check info nibble and retry (blob 0x28E..0x2A8)
              let infoNib = rcU8(sampleEntryBase, 14) and 0x0F
              var retryOk: uint8 = 1
              if infoNib <= 9:
                let sampleRetry = rcU8(sampleEntryBase, 12)
                retryOk = if sampleRetry < minRetryLen.uint8: 1 else: 0

              # Record promotion
              let oldTp2 = rcU32(stats, RCS_TP_SECOND)
              rcU16(stats, RCS_SAMPLE_CAND) = rcU16(stats, RCS_MAX_TP2_IDX)
              rcU32(stats, RCS_PREV_TP) = oldTp2

              if retryOk != 0:
                let oldTpCur = rcU32(stats, RCS_TP_CUR)
                rcU8(stats, RCS_FLAGS) = rcU8(stats, RCS_FLAGS) and not 0x02'u8
                rcU32(stats, RCS_TP_SECOND) = oldTpCur
                rcU16(stats, RCS_MAX_TP2_IDX) = maxTpIdx
                rcU32(stats, RCS_TP_CUR) = 0
                rcU16(stats, RCS_MAX_TP_IDX) = sample
              else:
                rcU8(stats, RCS_FLAGS) = rcU8(stats, RCS_FLAGS) or 0x02'u8
                rcU32(stats, RCS_TP_SECOND) = 0
                rcU16(stats, RCS_MAX_TP2_IDX) = sample

              rcU8(stats, RCS_UPDATE_STAGE) = 2
            else:
              # Slow rate tracking (disasm L365, 0x234..0x25A)
              let sampleRetry = rcU8(sampleEntryBase, 12)
              if sampleRetry < minRetryLen.uint8:
                rcU8(stats, RCS_UPDATE_STAGE) = 0
              else:
                var slowCnt = rcU8(stats, RCS_SLOW_RATE_CNT) + 1
                rcU8(stats, RCS_SLOW_RATE_CNT) = slowCnt and 0xFF
                if slowCnt > 2 and slowCnt <= 15:
                  rcU8(stats, RCS_UPDATE_STAGE) = 0
                elif slowCnt > 15:
                  rcU8(stats, RCS_SLOW_RATE_CNT) = 15
                  rcU8(stats, RCS_UPDATE_STAGE) = 0
                else:
                  # Retry chain update (blob does NOT call rc_update_retry_chain
                  # from here; state transition only).
                  rcU8(stats, RCS_UPDATE_STAGE) = 2

          else:
            # ---- Legacy simple comparison (disasm LVL550, 0x156..0x17A) ----
            let maxTpRate = rcRateConfig(stats, maxTpIdx.int)
            let maxTpDur = rc_get_duration(maxTpRate.uint32, 1)

            if sampleDur < maxTpDur:
              # Sample has better throughput: promote
              let retryCount = rcU8(sampleEntryBase, 12)
              let retryOK: uint8 = if retryCount >= 20: 0 else: 1

              let oldTp2 = rcU32(stats, RCS_TP_SECOND)
              rcU16(stats, RCS_SAMPLE_CAND) = rcU16(stats, RCS_MAX_TP2_IDX)
              rcU32(stats, RCS_PREV_TP) = oldTp2

              if retryOK != 0:
                let oldTpCur = rcU32(stats, RCS_TP_CUR)
                rcU8(stats, RCS_FLAGS) = rcU8(stats, RCS_FLAGS) and not 0x02'u8
                rcU32(stats, RCS_TP_SECOND) = oldTpCur
                rcU16(stats, RCS_MAX_TP2_IDX) = maxTpIdx
                rcU32(stats, RCS_TP_CUR) = sampleDur
                rcU16(stats, RCS_MAX_TP_IDX) = sample
              else:
                rcU8(stats, RCS_FLAGS) = rcU8(stats, RCS_FLAGS) or 0x02'u8
                rcU32(stats, RCS_TP_SECOND) = sampleDur
                rcU16(stats, RCS_MAX_TP2_IDX) = sample
            else:
              # Sample worse: no promotion, zero throughput
              let oldTp2 = rcU32(stats, RCS_TP_SECOND)
              rcU16(stats, RCS_SAMPLE_CAND) = rcU16(stats, RCS_MAX_TP2_IDX)
              rcU32(stats, RCS_PREV_TP) = oldTp2
              rcU8(stats, RCS_FLAGS) = rcU8(stats, RCS_FLAGS) or 0x02'u8
              rcU32(stats, RCS_TP_SECOND) = 0
              rcU16(stats, RCS_MAX_TP2_IDX) = sample

            rcU8(stats, RCS_UPDATE_STAGE) = 2

  elif stage == 3:
    # ---- Finalize phase (disasm L356/LBB356, 0x2C2..0x300) ----
    let flags = rcU8(stats, RCS_FLAGS)
    if (flags and 0x02) == 0:
      # Not fixed: restore old max_tp2 -> max_tp
      let oldTp2Idx = rcU16(stats, RCS_MAX_TP2_IDX)
      rcU16(stats, RCS_MAX_TP_IDX) = oldTp2Idx
      let oldTp2Val = rcU32(stats, RCS_TP_SECOND)
      rcU32(stats, RCS_TP_CUR) = oldTp2Val

    # Move sample_candidate to max_tp2, restore prev_tp
    let sampCand = rcU16(stats, RCS_SAMPLE_CAND)
    rcU8(stats, RCS_UPDATE_STAGE) = 0
    rcU16(stats, RCS_MAX_TP2_IDX) = sampCand
    let prevTp = rcU32(stats, RCS_PREV_TP)
    rcU32(stats, RCS_PREV_TP) = 0
    rcU32(stats, RCS_TP_SECOND) = prevTp
    # Reset sample_candidate to 0xFF (disasm: li a4, 255; sh a4, 160(s4))
    rcU16(stats, RCS_SAMPLE_CAND) = 0x00FF'u16

  # else: stage==0 or 2, no action

  # ---- If stats updated, mark sta for TX policy refresh (disasm L369) ----
  if didUpdate != 0:
    # Set sta[334] |= 1 (disasm 0x1B4..0x1C0)
    staU8(sta, STA_RC_FLAGS_OFF) = staU8(sta, STA_RC_FLAGS_OFF) or 0x01'u8


proc rc_calc_tp*(entry: pointer, stats: pointer): uint32 {.exportc, cdecl.} =
  ## Calculate throughput for rate selection (45 instrs).
  ## From blob: a0 = rate entry pointer, and caller also passes the rc_stats
  ## pointer in a1 (kept in s2 across the is_cck_group call).
  ##   1. probEwma = entry[8]; if probEwma < 0x1998: return 0.
  ##   2. rateConfig = entry[10]
  ##   3. call is_cck_group(rateConfig); if returns 0 (NOT CCK):
  ##        s0 = 0x35390 / rc_stats[170]    (AMPDU overhead)
  ##      else (is CCK): s0 = 0
  ##   4. call rc_get_duration(rateConfig); s0 += duration
  ##   5. tp = (probEwma * 1000) / s0; tp *= 0xF4240 (→ scales to 1e6 basis)
  ##   6. return tp
  let entryPtr = cast[uint](entry)
  let statsPtr = stats

  let probEwma = cast[ptr uint16](entryPtr + 8)[]
  if probEwma < 0x1998'u16:
    return 0
  let rateConfig = cast[ptr uint16](entryPtr + 10)[]

  # AMPDU overhead: added only when rate is NOT a CCK rate.
  var overhead: uint32 = 0
  if not is_cck_group(rateConfig.uint32):
    if statsPtr != nil:
      let ampduLen = cast[ptr uint16](cast[uint](statsPtr) + RCS_AVG_AMPDU_LEN)[]
      if ampduLen != 0:
        overhead = 0x35390'u32 div ampduLen.uint32

  # Add rate airtime
  let duration = rc_get_duration(rateConfig.uint32, 0)
  let totalOverhead = overhead + duration
  if totalOverhead == 0:
    return 0
  let tpStep = (probEwma.uint32 * 1000'u32) div totalOverhead
  return tpStep * 0xF4240'u32

proc rc_update_counters*(staIdx: uint8, attemptCount: uint32, successCount: uint32) {.exportc, cdecl.} =
  ## Update rate control counters after TX attempt (112 instrs).
  ## a0=staIdx, a1=attemptCount, a2=successCount.
  ## Loads RC stats from sta_info_tab[staIdx]+324. Increments total attempts
  ## and total success counters. Then iterates per-rate entries at stats+128..160
  ## (5 AC slots, 8 bytes each), adding attempts/successes to each slot's counters
  ## with overflow checking via assert_err.
  if staIdx > 4:
    return

  let staTab = cast[uint](addr sta_info_tab[0])
  let staEntry = staTab + staIdx.uint * STA_ENTRY_SIZE.uint

  # Check info_idx for validity (0xFF = uninitialized)
  let infoIdx = cast[ptr uint8](staEntry + 39)[]
  if infoIdx == 0xFF:
    return

  # Load RC stats pointer from sta+324
  let stats = cast[ptr pointer](staEntry + STA_RC_STATS_PTR_OFF.uint)[]
  if stats == nil:
    assert_err("rc.c", "rc.c", 1998)
    return

  var attempts = attemptCount
  var successes = successCount

  # Increment total counters
  let totalSuccess = rcU16(stats, RCS_TOTAL_SUCCESS)
  rcU16(stats, RCS_TOTAL_SUCCESS) = totalSuccess + 1
  let totalAttempts = rcU16(stats, RCS_TOTAL_ATTEMPTS)
  rcU16(stats, RCS_TOTAL_ATTEMPTS) = totalAttempts + 1

  # Iterate retry-chain slots at stats+128..stats+152. Each slot stores a
  # rate-table index; the counters live in the selected rate entry.
  var acOff: uint = 128
  let acEnd: uint = 160
  while acOff < acEnd:
    if attempts == 0:
      break

    let rateIdx = rcU16(stats, acOff.int)
    let entryBase = cast[uint](stats) + rateIdx.uint * RC_RATE_ENTRY_SIZE.uint
    var entryAttempts = cast[ptr uint16](entryBase + 4)[]

    if successes > 3:
      entryAttempts = entryAttempts + 4'u16
      cast[ptr uint16](entryBase + 4)[] = entryAttempts
      attempts -= 4
      successes -= 4
    else:
      let addAttempts = (attempts and 0xFFFF'u32).uint16
      entryAttempts = entryAttempts + addAttempts
      cast[ptr uint16](entryBase + 4)[] = entryAttempts

      var entryFailures = cast[ptr uint16](entryBase + 6)[]
      entryFailures = entryFailures + addAttempts - successes.uint16
      cast[ptr uint16](entryBase + 6)[] = entryFailures
      attempts = 0
      successes = 0

    # Vendor asserts when recorded attempts fall below recorded failures.
    let curAttempts = cast[ptr uint16](entryBase + 4)[]
    let curFailures = cast[ptr uint16](entryBase + 6)[]
    if curAttempts < curFailures:
      assert_err("rc.c", "rc.c", 2040)

    acOff += 8

  # Check update stage and advance state machine
  let stage = rcU8(stats, RCS_UPDATE_STAGE)
  if stage == 0:
    # Check retry limit
    let retryLimit = rcU8(stats, RCS_RETRY_LIMIT)
    if retryLimit == 0:
      rcU8(stats, RCS_UPDATE_STAGE) = 1
    else:
      let newLimit = retryLimit - 1
      rcU8(stats, RCS_RETRY_LIMIT) = newLimit
  elif stage == 2:
    # Re-check with sta flags
    let staFlags = cast[ptr uint8](staEntry + STA_RC_FLAGS_OFF.uint)[]
    if (staFlags and 1) == 0:
      rcU8(stats, RCS_UPDATE_STAGE) = 3

proc rc_get_duration*(rateConfig: uint32, length: uint32): uint32 {.exportc, cdecl.} =
  ## Compute frame TX duration in microseconds for given rate_config and frame length
  ## (55 instructions in blob).
  ##
  ## Extracts format mod (bits 12:11 >> 11, masked to &6) from rateConfig.
  ## For legacy (formatMod==0): uses CCK or OFDM duration formula.
  ##   CCK (rateIdx 0..3): durations based on 1/2/5.5/11 Mbps with preamble.
  ##   OFDM (rateIdx 4..11): standard OFDM symbol time formula.
  ## For HT (formatMod==2 or 4): uses HT/VHT symbol time with MCS lookup.
  ## The blob uses lookup tables via custom .insn and relocated data pointers.
  # Blob extracts NSS via rc_get_nss; GCC would DCE a pure-return-discard,
  # so pin it with a volatile var + asm barrier.
  block:
    var nssTmp {.volatile.}: uint8 = rc_get_nss(rateConfig.uint16)
    {.emit: ["asm volatile(\"\" :: \"r\"(", nssTmp, ") : \"memory\");"].}
  let formatMod = (rateConfig shr 11) and 0x6
  let rateIdx = rc_get_mcs_index(rateConfig.uint16)

  if formatMod == 0:
    # Legacy rate
    if rateIdx <= 3:
      # CCK rates: 1, 2, 5.5, 11 Mbps
      # Duration = preamble + (length * 8) / rate_in_half_mbps
      # CCK preamble is 192us (long) or 96us (short)
      # Rates in 0.5 Mbps units: 2, 4, 11, 22
      const cckRates = [2'u32, 4, 11, 22]  # in 0.5 Mbps
      let halfMbps = cckRates[rateIdx.int]
      # Duration = preamble(192) + ceiling(length*16 / halfMbps)
      let bits = length * 16  # length in bits * 2 (for half-Mbps denominator)
      let dataTime = (bits + halfMbps - 1) div halfMbps
      return 192 + dataTime
    else:
      # OFDM rates: 6, 9, 12, 18, 24, 36, 48, 54 Mbps (indices 4..11)
      # Duration = 20 (preamble+signal) + 4 * ceil((16 + 8*length + 6) / N_DBPS)
      # N_DBPS for each rate: 24, 36, 48, 72, 96, 144, 192, 216
      const ofdmNdbps = [24'u32, 36, 48, 72, 96, 144, 192, 216]
      let ofdmIdx = rateIdx.int - 4
      if ofdmIdx < 0 or ofdmIdx >= 8:
        return 0
      let ndbps = ofdmNdbps[ofdmIdx]
      let totalBits = 16'u32 + 8 * length + 6
      let nSymbols = (totalBits + ndbps - 1) div ndbps
      return 20 + 4 * nSymbols
  else:
    # HT/VHT rate
    # Extract NSS from formatMod field (shifted)
    let nssField = (formatMod shr 1) - 1  # 0 or 1 for HT-MF/HT-GF/VHT
    if nssField > 1:
      return 0  # unsupported format

    # HT: preamble 36us (HT-MF) or 32us (HT-GF), symbol 4us (short GI: 3.6us)
    # Duration = preamble + 4 * ceil((16 + 8*length + 6) / N_DBPS)
    # N_DBPS for MCS 0..7 (1 SS): 26, 52, 78, 104, 156, 208, 234, 260
    const htNdbps = [26'u32, 52, 78, 104, 156, 208, 234, 260]
    let mcs = (rateIdx and 0x07).int
    if mcs >= 8:
      return 0
    let ndbps = htNdbps[mcs]
    let totalBits = 16'u32 + 8 * length + 6
    let nSymbols = (totalBits + ndbps - 1) div ndbps
    return 36 + 4 * nSymbols

proc rc_update_bw_nss_max*(staIdx: uint8, nss: uint8, groupCnt: uint8) {.exportc, cdecl.} =
  ## Update bandwidth and NSS max for rate control.
  ## From blob: loads RC stats for staIdx, checks if nss/groupCnt changed,
  ## validates bounds, re-initializes the rate table if sample_idx==0xFFFF.
  ## Algorithm: entry[0]=lowest rate, entry[nRates-1]=initial rate,
  ## entries[1..nRates-2]=random non-duplicate sample rates.
  ## Then clears all entry stats, sorts by throughput, and rebuilds retry chain.
  ##
  ## Blob calls: assert_err(x3), rc_get_initial_rate_config,
  ## rc_get_lowest_rate_config, rc_new_random_rate, rc_check_rate_duplicated,
  ## rc_sort_samples_tp, rc_update_retry_chain.
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint

  # Load RC stats pointer from sta+324
  let rcStats = cast[ptr pointer](staEntry + STA_RC_STATS_PTR_OFF.uint)[]
  if rcStats == nil:
    assert_err("rc.c", "rc.c", 0x95D.cint)
    return

  let rc = cast[uint](rcStats)

  # Check if nss and groupCnt are unchanged -- early exit
  if rcU8(rcStats, RCS_NO_SS) == nss and rcU8(rcStats, RCS_GROUP_CNT) == groupCnt:
    return

  # Store new NSS value (with bounds check: must be <= 3)
  rcU8(rcStats, RCS_NO_SS) = nss
  if nss > 3:
    assert_err("rc.c", "rc.c", 0x963.cint)

  # Store new group count (with bounds check: must be <= 7)
  rcU8(rcStats, RCS_GROUP_CNT) = groupCnt
  if groupCnt > 7:
    assert_err("rc.c", "rc.c", 0x965.cint)

  # Check if rate table needs re-initialization: sample_idx == 0xFFFF
  let sampleIdx = rcU16(rcStats, RCS_SAMPLE_IDX)
  if sampleIdx != 0xFFFF'u16:
    return

  # Entry[0] = lowest rate config
  let lowestRate = rc_get_lowest_rate_config(rcStats)
  rcU16(rcStats, 10) = lowestRate  # entry[0].rate_config

  # Entry[nRates-1] = initial (highest) rate config
  let initialRate = rc_get_initial_rate_config(rcStats)
  let nRates = rcU16(rcStats, RCS_N_RATES)
  let lastEntryOff = (nRates.int - 1) * RC_RATE_ENTRY_SIZE + 10
  rcU16(rcStats, lastEntryOff) = initialRate

  # Fill entries[1..nRates-2] with random non-duplicate sample rates.
  # Blob keeps a single rc_new_random_rate call site inside a do-while.
  var idx: int = 1
  while idx < nRates.int - 1:
    var randomRate: uint16 = 0
    while true:
      randomRate = rc_new_random_rate(rcStats)
      if rc_check_rate_duplicated(rcStats, randomRate) == 0:
        break
    rcSetRateConfig(rcStats, idx, randomRate)
    idx += 1

  # Clear all entry stats fields (throughput, attempts, old_prob, etc.)
  for i in 0 ..< nRates.int:
    let entryBase = rc + i.uint * RC_RATE_ENTRY_SIZE.uint
    cast[ptr uint8](entryBase + 6)[] = 0        # sample_skipped = 0
    cast[ptr uint8](entryBase + 7)[] = 1        # initialized = 1
    cast[ptr uint16](entryBase + 0)[] = 0       # attempts = 0
    cast[ptr uint8](entryBase + 5)[] = 0        # old_prob = 0

  # Sort by throughput and rebuild retry chain
  var tpArray {.noinit.}: array[RC_MAX_RATE_ENTRIES, uint32]
  rc_sort_samples_tp(rcStats, addr tpArray[0])
  rc_update_retry_chain(rcStats, addr tpArray[0])

  # Re-compute staEntry and set RC flags bit 0 (needs update)
  let staEntryU = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let staFlags = cast[ptr uint8](staEntryU + STA_RC_FLAGS_OFF.uint)[]
  cast[ptr uint8](staEntryU + STA_RC_FLAGS_OFF.uint)[] = staFlags or 1

proc rc_update_preamble_type*(staIdx: uint8, shortPreamble: uint8) {.exportc, cdecl.} =
  ## Update preamble type for rate control (94 instrs).
  ## a0=staIdx, a1=shortPreamble (0=long, 1=short).
  ## Loads RC stats from sta_info_tab[staIdx]+324. If BW max changed, iterates
  ## rate entries to toggle short preamble bit (bit 10 of rate_config). Uses
  ## is_cck_group to check if rate is CCK, then calls rc_check_rate_duplicated
  ## and rc_new_random_rate as needed. Finally calls rc_sort_samples_tp and
  ## rc_update_retry_chain to rebuild the retry chain.
  let staTab = cast[uint](addr sta_info_tab[0])
  let staEntry = staTab + staIdx.uint * STA_ENTRY_SIZE.uint

  # Load RC stats pointer from sta+324
  let stats = cast[ptr pointer](staEntry + STA_RC_STATS_PTR_OFF.uint)[]
  if stats == nil:
    assert_err("rc.c", "rc.c", 0x9A2.cint)
    return

  let rc = cast[uint](stats)

  # Check if preamble type actually changed
  let curBwMax = rcU8(stats, RCS_BW_MAX)
  if curBwMax == shortPreamble:
    return

  # Check if sample_idx is 0xFFFF (special case: no change needed)
  let sampleIdx = rcU16(stats, RCS_SAMPLE_IDX)
  rcU8(stats, RCS_BW_MAX) = shortPreamble  # store new preamble type
  if sampleIdx == 0xFFFF'u16:
    return

  # No short preamble support: early exit
  if shortPreamble == 0:
    return

  # Iterate rate entries and toggle short preamble bit
  var idx: uint16 = 0
  while idx < rcU16(stats, RCS_N_RATES):
    let entryBase = rc + idx.uint * RC_RATE_ENTRY_SIZE.uint
    var rateConfig = rcU16(stats, (idx.int * RC_RATE_ENTRY_SIZE + 10))

    # Use the explicit is_cck_group helper to match blob's call-graph;
    # Nim's inlined `(rate>>11)&6 == 0 && mcs<4` test was equivalent but
    # showed up as 0 call sites vs blob's 1.
    let isCck = is_cck_group(rateConfig.uint32)

    if isCck:
      # Set short preamble bit (bit 10)
      rateConfig = rateConfig or 0x0400'u16

    # Try to set the rate; check for duplicates
    let newConfig = rateConfig
    let dup = rc_check_rate_duplicated(stats, newConfig)
    if dup != 0:
      # Duplicate found: get a new random rate instead
      let randomRate = rc_new_random_rate(stats)
      rateConfig = randomRate

    # Store updated rate config
    # Clear and reinitialize entry fields
    cast[ptr uint8](entryBase + 6)[] = 0    # sample_skipped = 0
    cast[ptr uint8](entryBase + 7)[] = 1    # initialized = 1
    rcU16(stats, idx.int * RC_RATE_ENTRY_SIZE + 10) = rateConfig
    cast[ptr uint16](entryBase + 0)[] = 0   # attempts = 0
    cast[ptr uint8](entryBase + 5)[] = 0    # old_prob = 0

    idx += 1

  # Rebuild rate ordering and retry chain
  var tpArray {.noinit.}: array[12, uint8]  # stack-allocated TP array
  rc_sort_samples_tp(stats, addr tpArray[0])

  let txPolicyPtr = cast[ptr pointer](staEntry + STA_TX_POLICY_PTR_OFF.uint)[]
  rc_update_retry_chain(stats, txPolicyPtr)

  # Mark STA for RC update
  let staFlags = cast[ptr uint8](staEntry + STA_RC_FLAGS_OFF.uint)[]
  cast[ptr uint8](staEntry + STA_RC_FLAGS_OFF.uint)[] = staFlags or 1

proc rc_init_bcmc_rate*(staEntry: pointer, band: uint32) {.exportc, cdecl.} =
  ## Initialize broadcast/multicast rate.
  ## From blob (12 instrs): a0=sta_info_tag pointer, a1=band (rate index).
  ## Loads TX policy from sta+320, supported rates from sta+332.
  ## Builds rate config: band | (suppRates & 0x400 if band <= 3) | 0x20000000.
  ## Writes to 4 retry slots at txPolicy offsets 20, 24, 28, 32.
  let sta = cast[uint](staEntry)
  let txPolicy = cast[ptr pointer](sta + STA_TX_POLICY_PTR_OFF.uint)[]
  let suppRates = cast[ptr uint16](sta + STA_SUPP_RATES_OFF.uint)[]
  var rateConfig = band
  # Conditionally include CCK rate bit if band <= 3
  if band <= 3:
    rateConfig = rateConfig or (suppRates.uint32 and 0x400'u32)
  rateConfig = rateConfig or 0x20000000'u32  # format mod
  let tp = cast[uint](txPolicy)
  cast[ptr uint32](tp + 20)[] = rateConfig
  cast[ptr uint32](tp + 24)[] = rateConfig
  cast[ptr uint32](tp + 28)[] = rateConfig
  cast[ptr uint32](tp + 32)[] = rateConfig

proc rc_check_fixed_rate_config*(staIdx: uint8): bool {.exportc, cdecl.} =
  ## Check if fixed rate is valid for the station's capabilities (54 instrs in blob).
  ##
  ## Blob ABI: a0 = stats pointer (NOT sta_entry and NOT staIdx — directly
  ## the rc_sta_stats block). a1 = fixed_rate_config (uint16 packed).
  ## Returns true if HW can send the fixed rate; else tail-calls
  ## rc_set_fixed_rate_config on the passing path.
  ##
  ## Previous Nim read `rateConfig` from stats+182 (RCS_RATE_MAP — the
  ## *supported rates bitmap*), not the caller-supplied fixed rate. That
  ## broke the validation entirely. Fix: grab a1 via inline asm.
  let stats = cast[pointer](staIdx)  # a0 = stats pointer
  var rateConfig: uint16
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", rateConfig, ") );"].}

  let formatMod = rcU8(stats, RCS_FORMAT_MOD)

  # Extract format mod from rate config
  let rateFmt = ((rateConfig shr 11) and 0x6).uint8

  if formatMod == 4:
    # Non-HT / legacy-only STA: the fixed rate must also be non-HT
    if rateFmt != 0:
      return false
  else:
    let fmtCheck = (formatMod - 2) and 0xFF
    if fmtCheck > 1:
      return false  # unsupported format mod

    # HT STA: validate NSS and MCS bounds
    if rateFmt != 0:
      # HT/VHT fixed rate: check short GI support
      let shortGi = rcU8(stats, RCS_SHORT_GI)
      if shortGi == 0:
        # No short GI: check if fixed rate uses short GI
        let sgiFlag = rcU8(stats, RCS_BW_MAX + 1)  # offset 191
        if sgiFlag != 0:
          return false

      # Check NSS bounds — blob extracts the NSS with rc_get_nss (not the
      # inline `(rate>>11)&6` shift Nim was using earlier).
      let noSs = rcU8(stats, RCS_NO_SS)
      # GCC -Os will DCE a pure-function-return-discarded call; keep a
      # side-effect asm barrier around the return so the blob's call
      # graph matches.
      block:
        var nssTmp {.volatile.}: uint8 = rc_get_nss(rateConfig)
        {.emit: ["asm volatile(\"\" :: \"r\"(", nssTmp, ") : \"memory\");"].}
      let mcsIdx = rc_check_valid_rate(stats, rateConfig)
      let bwMax = rcU8(stats, RCS_BW_MAX)
      if mcsIdx > bwMax:
        return false

  # All checks passed -- set the fixed rate configuration
  # Blob tail-calls rc_set_fixed_rate_config(staEntry, rateConfig)
  # For now, mark as valid and return true
  return true

# RC internal helper implementations (stubs for functions called by rc_init/rc_check)
proc rc_get_mcs_index*(rateConfig: uint16): uint8 {.exportc, cdecl.} =
  ## Extract MCS index from packed rate_config.
  ## Legacy (bits[12:11]==0): return bits[6:0]
  ## HT/VHT: return bits[2:0] (MCS within NSS group)
  let fmtMod = (rateConfig shr 11) and 0x6
  if fmtMod == 0:
    return (rateConfig and 0x7F).uint8
  else:
    let nss = ((rateConfig shr 11) and 0x6).uint8
    if nss < 2:
      return 0
    let idx = (nss - 2) and 0xFF
    if idx > 1:
      return 0
    return (rateConfig and 0x7).uint8

proc rc_get_nss*(rateConfig: uint16): uint8 {.exportc, cdecl, noinline.} =
  ## Extract NSS (number of spatial streams) from rate_config.
  let nss = ((rateConfig shr 11) and 0x6).uint8
  if nss < 2:
    return 0
  let idx = nss - 2
  if idx > 1:
    return 0
  return (rateConfig and 0x7).uint8

proc rc_check_valid_rate*(stats: pointer, rateConfig: uint16): uint8 {.exportc, cdecl.} =
  ## Check if a rate_config is valid for the given station stats.
  ## Returns 1 if valid, 0 if not.
  ## Blob calls rc_get_nss for the HT/VHT group lookup rather than inlining
  ## the `(rate>>11)&6` shift — matching it keeps call-graph audit aligned.
  let fmtMod = (rateConfig shr 11) and 0x6
  if fmtMod == 0:
    # Legacy: check if rate index is in rate_map
    let idx = rc_get_mcs_index(rateConfig)
    let rateMap = rcU16(stats, RCS_RATE_MAP)
    return ((rateMap shr idx) and 1).uint8
  else:
    # HT/VHT: check MCS bitmap
    let nssField = ((rateConfig shr 11) and 0x6).uint8
    if nssField < 2: return 0
    let nssIdx = nssField - 2
    if nssIdx > 1: return 0
    # Blob uses rc_get_nss for this NSS extract. Use a volatile variable +
    # asm barrier so GCC -Os cannot DCE the call even though we don't need
    # its return value (the rest of the code reuses nssIdx).
    block:
      var nssTmp {.volatile.}: uint8 = rc_get_nss(rateConfig)
      {.emit: ["asm volatile(\"\" :: \"r\"(", nssTmp, ") : \"memory\");"].}
    let mcsIdx = rc_get_mcs_index(rateConfig)
    let groupBase = cast[pointer](cast[uint](stats) + RCS_RATE_BITMAP.uint + nssIdx.uint)
    let bitmap = cast[ptr uint8](groupBase)[]
    return ((bitmap shr mcsIdx) and 1).uint8

proc rc_check_rate_duplicated*(stats: pointer, rateConfig: uint16): uint8 {.exportc, cdecl.} =
  ## Check if rateConfig already exists in the rate table.
  ## Returns 1 if duplicated, 0 if not.
  let nRates = rcU16(stats, RCS_N_RATES)
  for i in 0 ..< nRates.int:
    if rcRateConfig(stats, i) == rateConfig:
      return 1
  return 0

proc rc_get_initial_rate_config*(stats: pointer): uint16 {.exportc, cdecl.} =
  ## Build initial rate_config from stats fields.
  ## For legacy: (format_mod << 11) | (bw_max << 10) | highest_idx
  ## For HT: (format_mod << 11) | (short_gi << 9) | (no_ss << 7) | group*8 | mcs
  let fmtMod = rcU8(stats, RCS_FORMAT_MOD)
  if fmtMod <= 1:
    # Legacy
    let bwMax = rcU8(stats, RCS_BW_MAX)
    let hiIdx = rcU8(stats, RCS_HIGHEST_IDX)
    var rc = (fmtMod.uint16 shl 11) or (bwMax.uint16 shl 10) or hiIdx.uint16
    return rc
  else:
    # HT/VHT
    let groupCnt = rcU8(stats, RCS_GROUP_CNT)
    let sgi = rcU8(stats, RCS_SHORT_GI)
    let noSS = rcU8(stats, RCS_NO_SS)
    # Find highest MCS in the max NSS group. Blob treats RCS_GROUP_CNT as a
    # zero-based group index and reads rate_bitmap[groupCnt] directly.
    let lastGroup = groupCnt
    let mcsByte = rcU8(stats, RCS_RATE_BITMAP + lastGroup.int)
    var hiMcs: uint8 = 0
    if mcsByte != 0:
      var clzIn: cuint = mcsByte.cuint
      var c: cint
      {.emit: [c, " = __builtin_clz(", clzIn, ");"].}
      hiMcs = (31 - c).uint8
    var rc = (fmtMod.uint16 shl 11) or (sgi.uint16 shl 9) or
             (noSS.uint16 shl 7) or (lastGroup.uint16 shl 3) or hiMcs.uint16
    return rc

proc rc_get_lowest_rate_config*(stats: pointer): uint16 {.exportc, cdecl.} =
  ## Build rate_config for the lowest supported rate.
  let fmtMod = rcU8(stats, RCS_FORMAT_MOD)
  if fmtMod <= 1:
    let loIdx = rcU8(stats, RCS_LOWEST_IDX)
    if loIdx == 0:
      return 0x0400'u16  # 1024 = fallback marker
    return (fmtMod.uint16 shl 11) or loIdx.uint16
  else:
    let loIdx = rcU8(stats, RCS_LOWEST_IDX)
    if loIdx == 0:
      return 0x0400'u16
    let bwMax = rcU8(stats, RCS_BW_MAX)
    return (fmtMod.uint16 shl 11) or (bwMax.uint16 shl 10) or loIdx.uint16

proc rc_new_random_rate*(stats: pointer): uint16 {.exportc, cdecl.} =
  ## Generate a random rate_config for sampling using the LCG PRNG (119 instrs).
  ## From blob: advances PRNG, then dispatches on format_mod (offset 177):
  ##   format_mod == 0 (legacy): pick random index in [lowest..highest] range
  ##     from rate_map (offset 182), return (bw_max<<10) | mcs_index.
  ##   format_mod >= 2 (HT/VHT): pick random group from rate_bitmap (offset 178..181),
  ##     then random rate within that group from highest_idx, builds rate_config
  ##     with format_mod, group, and mcs fields.
  ## The rate_config format is: bits[12:11]=format_mod, bits[10]=bw_max,
  ##   bits[9:4]=group/nss, bits[3:0]=mcs_index.
  let prngVal = rcPrngNext()
  let noSS = rcU8(stats, RCS_NO_SS)       # number of spatial streams (0-based max)
  let formatMod = rcU8(stats, RCS_FORMAT_MOD)  # 0=legacy, 2=HT, 4=VHT
  let prngHi = prngVal shr 16              # use upper 16 bits for randomness

  # Build base rate_config with format_mod in bits [12:11]
  var rateConfig: uint16 = formatMod.uint16 shl 11

  if formatMod <= 1:
    # Legacy or single-stream: pick random rate from [lowest..highest] range
    let lowest = rcU8(stats, RCS_LOWEST_IDX)
    let highest = rcU8(stats, RCS_HIGHEST_IDX)
    if lowest >= highest or highest == 0:
      # Only one rate or invalid range
      let rateMap = rcU16(stats, RCS_RATE_MAP)
      let bwMax = rcU8(stats, RCS_BW_MAX)
      rateConfig = rateConfig or (bwMax.uint16 shl 10)
      return rateConfig
    let range = highest - lowest + 1
    let rndIdx = (prngHi.uint32 and 0x7F) mod range.uint32
    let idx = lowest + rndIdx.uint8
    # Check if rate is supported in rate_map
    let rateMap = rcU16(stats, RCS_RATE_MAP)
    let supported = (rateMap shr idx) and 1
    var mcsIdx = idx.uint16
    if supported == 0:
      # Vendor falls back to the highest supported index when the random bit
      # picks a hole in the supported-rate map.
      mcsIdx = highest.uint16
    else:
      if mcsIdx > 0:
        let mcsIdxByte = ((mcsIdx - 1) and 0xFF).uint8
        if mcsIdxByte <= 2:
          # Within first 3 rates, also set BW field
          let bwMax = rcU8(stats, RCS_BW_MAX)
          let bwField = (prngHi and 0x400).uint16  # bit 10 from prng
          rateConfig = rateConfig or bwField or mcsIdx
          return rateConfig
    rateConfig = rateConfig or mcsIdx
    return rateConfig
  else:
    # HT/VHT multi-stream: pick random group then random rate within it
    let groupCnt = rcU8(stats, RCS_GROUP_CNT)

    if groupCnt > 3:
      # Use rate_bitmap for group selection
      let bitmapByte = rcU8(stats, RCS_RATE_BITMAP)
      let groupRange = (prngHi shr 7).uint32 and 0x07  # 3-bit random for group selection
      let maxNssMcs = rcU8(stats, RCS_MAX_NSS_MCS)
      let groupRangeActual = maxNssMcs + 1
      if groupRangeActual == 0:
        return rateConfig or 0x400'u16  # fallback
      let selGroup = groupRange mod groupRangeActual.uint32
      let shortGi = rcU8(stats, RCS_SHORT_GI)
      # Read rate_bitmap for selected group
      let groupBitmap = rcU8(stats, RCS_RATE_BITMAP.int + selGroup.int)
      let lowest = rcU8(stats, RCS_LOWEST_IDX)
      let highest = rcU8(stats, RCS_HIGHEST_IDX)
      let range = highest - lowest + 1
      let rndRate = (prngHi and 0x7F) mod range.uint32
      let rateIdx = lowest + rndRate.uint8
      # Check if supported
      let rateMap = rcU16(stats, RCS_RATE_MAP_L)
      let supported = (rateMap shr rateIdx) and 1
      if supported == 0:
        rateConfig = 0x400'u16  # fallback to lowest with bw_max
      else:
        if rateIdx > 0:
          rateConfig = rateConfig or (rateIdx - 1).uint16
        let bwMax = rcU8(stats, RCS_BW_MAX)
        let bwField = (prngHi and 0x400).uint16
        rateConfig = rateConfig or bwField
      return rateConfig
    else:
      # Small group count: pick from rate_bitmap directly
      let lowest = rcU8(stats, RCS_LOWEST_IDX)
      let highest = rcU8(stats, RCS_HIGHEST_IDX)
      if lowest >= highest:
        return rateConfig or 0x400'u16
      let range = highest - lowest + 1
      let rndIdx = (prngHi and 0x7F) mod range.uint32
      let idx = lowest + rndIdx.uint8
      let rateMap = rcU16(stats, RCS_RATE_MAP_L)
      let supported = (rateMap shr idx) and 1
      if supported == 0:
        return rateConfig or 0x400'u16
      var mcsIdx = idx.uint16
      if mcsIdx > 0:
        mcsIdx = mcsIdx - 1
      let bwMax = rcU8(stats, RCS_BW_MAX)
      let bwField = (prngHi and 0x400).uint16
      rateConfig = rateConfig or bwField or mcsIdx
      return rateConfig

proc rc_update_retry_chain*(stats: pointer, param: pointer) {.exportc, cdecl.} =
  ## Update the retry chain based on current rate statistics (137 instrs).
  ## Builds 4-entry retry chain: [max_tp, max_tp2, max_prob, lowest].
  ## From blob: checks flags bit 2 for fixed chain, then builds sorted
  ## indices by walking rate entries and comparing throughput/probability.
  let nRates = rcU16(stats, RCS_N_RATES)
  if nRates == 0:
    return
  let flags = rcU8(stats, RCS_FLAGS)
  let paramVal = if param != nil: cast[ptr uint32](param)[] else: 0'u32
  var s1Mode: uint8  # 1=normal, 2=fixed

  # Blob: lui a5,0x40000; addi a5,a5,-1 -> 0x3FFFFFFF; add a5,a5,nRates
  if (flags and 0x04) != 0 or paramVal > (0x3FFFFFFF'u32 + nRates.uint32):
    # Fixed retry chain or overflow: set max_tp to highest rate
    rcU16(stats, RCS_MAX_TP_IDX) = nRates - 1
    rcU32(stats, RCS_TP_CUR) = paramVal
    s1Mode = 2
  else:
    # Normal: start with rate 0 as best
    rcU16(stats, RCS_MAX_TP_IDX) = 0
    rcU32(stats, RCS_TP_CUR) = 0
    s1Mode = 1

  # Step 2: Find max_tp2 (second best throughput)
  # Blob: s6=stats base, walks from entry (nRates-1) downward
  let maxTpIdx = rcU16(stats, RCS_MAX_TP_IDX)

  # Check if max throughput rate is CCK group (blob: is_cck_group at offset 0x54)
  # If CCK, skip the validity scan loop entirely and go to retry chain building
  let maxTpEntryBase = cast[uint](stats) + maxTpIdx.uint * RC_RATE_ENTRY_SIZE.uint
  let maxTpRate = rcRateConfig(stats, maxTpIdx.int)
  let maxTpIsCck = is_cck_group(maxTpRate.uint32)

  if not maxTpIsCck:
    # Not CCK: walk from nRates-2 downward scanning for valid non-CCK entries
    var scanIdx = nRates.int - 2
    while scanIdx >= 0:
      let scanRate = rcRateConfig(stats, scanIdx)
      # Blob: is_cck_group at offset 0x13a — check if candidate is CCK
      if is_cck_group(scanRate.uint32):
        # CCK rate found during scan: clear initialized flag (blob: sb zero, 15(entry))
        let scanEntryBase = cast[uint](stats) + scanIdx.uint * RC_RATE_ENTRY_SIZE.uint
        cast[ptr uint8](scanEntryBase + 15)[] = 0
      scanIdx -= 1

  # Step 3: Set max_tp2 from best remaining rate
  # Blob: walks from (nRates-s1) down, comparing throughput values
  let tp1 = rcU32(stats, RCS_TP_CUR)
  rcU16(stats, RCS_MAX_TP2_IDX) = maxTpIdx  # start same as max_tp
  rcU32(stats, RCS_TP_SECOND) = tp1

  # Search for second-best: walk from (nRates-s1) downward.
  # Blob does NOT call rc_check_valid_rate here — it inspects the
  # cached rate_config directly (0xFFFF == invalid).
  var searchIdx = nRates.int - s1Mode.int
  while searchIdx >= 0:
    let candidateIdx = nRates.uint16 - searchIdx.uint16
    if candidateIdx < nRates:
      let candRate = rcRateConfig(stats, searchIdx)
      if candRate == 0xFFFF'u16:
        searchIdx -= 1
        continue
      if searchIdx.uint16 != maxTpIdx:
        rcU16(stats, RCS_MAX_TP2_IDX) = nRates - s1Mode.uint16
        break
    searchIdx -= 1

  # Step 4: Build retry chain entry 3 (max_prob) by walking rate table
  # Blob: walks entries[8..] with stride 12, comparing prob_ewma
  let maxTp2Idx = rcU16(stats, RCS_MAX_TP2_IDX)
  var bestProbIdx: uint16 = 0
  var bestProbTp: uint16 = 0
  var bestProbProbVal: uint8 = 0
  let probThreshold = 0xF332'u16  # from blob: lui a6,0xf; addi a6,818

  for i in 0 ..< nRates.int:
    let entryProb = rcRateEntryProb(stats, i)
    let entryTp = rcRateEntryTp(stats, i)
    let entryRetry = rcRateEntryRetry(stats, i)
    # Skip if this is the max_tp index
    if i.uint16 == maxTpIdx:
      continue
    # Check initialized flag (entry+7 = byte at offset 7 within entry)
    if entryRetry != 0 and i.uint16 != maxTpIdx:
      let entryRateU16 = rcRateConfig(stats, i)
      # Compare: if prob > probThreshold AND tp > bestProbTp, update
      if entryRateU16 >= probThreshold:
        # Blob: compares entry throughput with current best
        if entryTp > bestProbTp:
          bestProbTp = entryTp
          bestProbProbVal = entryRetry
          bestProbIdx = i.uint16
      elif entryTp > bestProbTp:
        # Lower prob but higher throughput
        bestProbTp = entryTp
        bestProbIdx = i.uint16

  # Store final retry chain results
  rcU16(stats, RCS_MAX_PROB_IDX) = bestProbIdx
  rcU32(stats, RCS_TP_THIRD) = bestProbIdx.uint32  # store index for chain
  rcU16(stats, RCS_RESERVED_U16) = 0
  rcU32(stats, RCS_RETRY_TIMER) = paramVal

proc rc_update_stats*(stats: pointer, needUpdate: uint8): uint8 {.exportc, cdecl.} =
  ## Update rate statistics (320 instructions in blob).
  ##
  ## Minstrel-like algorithm:
  ## Phase 1: Copy rate entries to temp, recalculate EWMA for sample_wait
  ## Phase 2: For each rate entry: calc_prob_ewma, sort into throughput table
  ## Phase 3: If needUpdate==0 and no sample: clear counters, return 0
  ## Phase 4: Build 6-entry sorted throughput table for rate selection
  ## Phase 5: Walk sorted table, apply policy, update retry chain
  ## Phase 6: Copy sorted throughput to stats+128, return
  let statsU = cast[uint](stats)
  let nRates = rcU16(stats, RCS_N_RATES)

  # Phase 1: EWMA decay for sample_wait counter
  let sampleWait = rcU16(stats, 166)  # offset 0xA6 = sample_wait_count
  if sampleWait > 0:
    let attempts = rcU16(stats, 164)  # offset 0xA4 = total_attempts
    rcU16(stats, 164) = 0
    # Compute EWMA: new = (old * 32 + (attempts << 16 / sampleWait)) >> 7
    let scaled = (attempts.uint32 shl 16) div sampleWait.uint32
    let old = rcU32(stats, 168)  # offset 0xA8 = ewma_attempts
    let blended = (old.uint32 * 32 + (scaled shl 5)) shr 7
    rcU32(stats, 168) = blended

  # Reset slow_rate_cnt
  rcU8(stats, RCS_SLOW_RATE_CNT) = 0

  # Phase 2: Recalculate probability for each rate entry
  # Copy entries to temp array for sorting
  var tempEntries {.noinit.}: array[10 * 12, uint8]  # max 10 rates * 12 bytes each
  discard c_memcpy(addr tempEntries[0], cast[pointer](statsU + 14), min(nRates.int * 12, 120).csize_t)

  for i in 0'u32 ..< nRates.uint32:
    let entryPtr = rcRateEntryPtr(stats, i.int)
    rc_calc_prob_ewma(entryPtr)
    # Blob: rc_calc_tp immediately after rc_calc_prob_ewma for each rate
    discard rc_calc_tp(entryPtr, stats)

  # Check sample_idx
  let sampleIdx = rcU16(stats, RCS_SAMPLE_IDX)
  if sampleIdx == 0xFFFF'u16:
    # No active sample: sort and update retry chain
    var tpSorted {.noinit.}: array[4, uint16]
    rc_sort_samples_tp(stats, addr tpSorted[0])
    rc_update_retry_chain(stats, addr tpSorted[0])
    if needUpdate != 0:
      return 0
    return 1

  # Phase 3: If needUpdate==0, check sticky flag; if not sticky, update EWMA for
  # current best rate, clear counters, return 0.
  # Blob path: sampleIdx != 0xFFFF, needUpdate==0, byte175 & 0x20 == 0
  if needUpdate == 0:
    let stickyFlag = rcU8(stats, 175)
    if (stickyFlag and 0x20) == 0:
      # Non-probe, non-sticky: update EWMA for current best rate only
      let bestIdx = rcU16(stats, 128)
      if bestIdx < nRates:
        let bestEntry = rcRateEntryPtr(stats, bestIdx.int)
        rc_calc_prob_ewma(bestEntry)
    # Clear all rate entry counters
    let nR = rcU16(stats, RCS_N_RATES)
    if nR <= 9:
      var entryOff = cast[uint](stats) + 4  # first entry at offset 4
      for i in 0'u32 ..< nR.uint32:
        # Clear attempt/success counters at entry+0 and entry+2
        cast[ptr uint16](entryOff)[] = 0
        cast[ptr uint16](entryOff + 2)[] = 0
        entryOff += RC_RATE_ENTRY_SIZE.uint
    return 0

  # Phase 4: Build 6-entry throughput table (blob: 6-step loop at 0x15E)
  # Blob uses a 6-step dispatch loop (s0 = step counter 0..5):
  #   step 0: rc_new_random_rate -> sample rate
  #   step 1 (s6): rc_set_next_mcs_index(stats, bestRate) -> if diff, rc_check_valid_rate
  #   step 2 (s7): check SGI variant availability
  #   step 3 (a5): rc_set_next_mcs_index(stats, secondBestRate) -> rc_check_valid_rate
  #   step 4 (s5): rc_set_previous_mcs_index(stats, bestRate) -> rc_check_valid_rate
  #   step 5: rc_set_previous_mcs_index(stats, secondBestRate) -> rc_check_valid_rate
  # After: rc_check_rate_duplicated for dedup
  let curBestRate = rcU16(stats, 128)  # stats+128 = best throughput rate config
  let secBestRate = rcU16(stats, 136)  # stats+136 = second-best rate config
  var sortParam {.noinit.}: array[8, uint16]  # 8 entries: [best, sec, sample, next1, next2, prev1, prev2, dedup]
  # Blob zeroes 12 bytes (6 slots) up-front via memset(sp, 0, 12).
  discard c_memset(addr sortParam[0], 0, 12.csize_t)
  sortParam[0] = curBestRate
  sortParam[1] = secBestRate

  # Step 0: Random sample rate
  let sampleRate = rc_new_random_rate(stats)
  sortParam[2] = sampleRate

  # Step 1: Next MCS from best rate
  let nextFromBest = rc_set_next_mcs_index(stats, curBestRate)
  if nextFromBest != curBestRate:
    if rc_check_valid_rate(stats, nextFromBest) != 0:
      sortParam[3] = nextFromBest
    else:
      sortParam[3] = curBestRate
  else:
    sortParam[3] = curBestRate

  # Step 2: SGI check (inline, no call if not applicable)
  let fmtInfo = (curBestRate shr 11) and 0x6
  var sgiRate = curBestRate
  if fmtInfo != 0:
    let sgiEnabled = rcU8(stats, RCS_SHORT_GI)
    if sgiEnabled != 0 and curBestRate == secBestRate:
      sgiRate = curBestRate or 0x200'u16  # set SGI bit
  sortParam[4] = sgiRate

  # Step 3: Next MCS from second-best rate
  let nextFromSec = rc_set_next_mcs_index(stats, secBestRate)
  if nextFromSec != secBestRate:
    if rc_check_valid_rate(stats, nextFromSec) != 0:
      sortParam[5] = nextFromSec
    else:
      sortParam[5] = secBestRate
  else:
    sortParam[5] = secBestRate

  # Step 4: Previous MCS from best rate
  let prevFromBest = rc_set_previous_mcs_index(stats, curBestRate)
  if prevFromBest != curBestRate:
    if rc_check_valid_rate(stats, prevFromBest) != 0:
      sortParam[6] = prevFromBest
    else:
      sortParam[6] = curBestRate
  else:
    sortParam[6] = curBestRate

  # Step 5: Previous MCS from second-best rate
  let prevFromSec = rc_set_previous_mcs_index(stats, secBestRate)
  if prevFromSec != secBestRate:
    if rc_check_valid_rate(stats, prevFromSec) != 0:
      sortParam[7] = prevFromSec
    else:
      sortParam[7] = secBestRate
  else:
    sortParam[7] = secBestRate

  # Dedup check: ensure sample rate is not duplicated with best rates
  if sampleRate != curBestRate and sampleRate != secBestRate:
    let isDup = rc_check_rate_duplicated(stats, sampleRate)
    if isDup != 0:
      sortParam[2] = curBestRate  # fall back to best rate

  # Phase 5: Copy sorted throughput to stats+128 (4 entries, 8 bytes each)
  # Note: blob does NOT call rc_sort_samples_tp or rc_update_retry_chain here.
  # Those are only called in the sampleIdx==0xFFFF path above.
  var retVal: uint8 = 0
  let destBase = statsU + 128
  var srcOff: uint32 = 0
  for i in 0'u32 ..< 4:
    let tpVal = cast[ptr uint16](cast[uint](addr sortParam[0]) + srcOff + 4)[]
    let curVal = cast[ptr uint16](destBase + srcOff + 4)[]
    if tpVal != curVal:
      retVal = 1
    cast[ptr uint16](destBase + srcOff + 4)[] = tpVal
    srcOff += 8

  return retVal

proc rc_set_previous_mcs_index*(stats: pointer, rateConfig: uint16): uint16 {.exportc, cdecl.} =
  ## Get the previous (lower) MCS rate_config.
  let fmtMod = (rateConfig shr 11) and 0x6
  let mcsIdx = rc_get_mcs_index(rateConfig)
  if fmtMod == 0:
    # Legacy: decrement rate index, check rate_map
    let loIdx = rcU8(stats, RCS_LOWEST_IDX)
    if mcsIdx <= loIdx:
      return rateConfig
    let prevIdx = mcsIdx - 1
    let rateMap = rcU16(stats, RCS_RATE_MAP)
    if (rateMap shr prevIdx and 1) != 0:
      return (rateConfig and 0xFF80'u16) or prevIdx.uint16
    return rateConfig
  else:
    # HT: decrement MCS, check bitmap
    let nssIdx = ((rateConfig shr 11) and 0x6).uint8 - 2
    if nssIdx > 1 or mcsIdx == 0:
      return rateConfig
    let maxNss = rcU8(stats, RCS_MAX_NSS_MCS)
    if mcsIdx <= maxNss:
      return rateConfig
    let prevMcs = mcsIdx - 1
    let sgiField = rcU8(stats, RCS_SHORT_GI)
    var newRc = (rateConfig and not 0x07'u16) or prevMcs.uint16
    if sgiField != 0:
      newRc = newRc or 0x200'u16
    return newRc

proc rc_set_next_mcs_index*(stats: pointer, rateConfig: uint16): uint16 {.exportc, cdecl.} =
  ## Get the next (higher) MCS rate_config.
  # Blob inspects NSS via rc_get_nss; match the call even though the branch
  # below switches on fmtMod (derived from the same bits inline). GCC -Os
  # DCEs a pure-return-discarded call — pin it with a volatile var + asm
  # barrier.
  block:
    var nssTmp {.volatile.}: uint8 = rc_get_nss(rateConfig)
    {.emit: ["asm volatile(\"\" :: \"r\"(", nssTmp, ") : \"memory\");"].}
  let fmtMod = (rateConfig shr 11) and 0x6
  let mcsIdx = rc_get_mcs_index(rateConfig)
  if fmtMod == 0:
    # Legacy: increment rate index, check rate_map
    let hiIdx = rcU8(stats, RCS_HIGHEST_IDX)
    if mcsIdx >= hiIdx:
      return rateConfig
    let nextIdx = mcsIdx + 1
    let rateMap = rcU16(stats, RCS_RATE_MAP)
    if ((rateMap shr nextIdx) and 1) != 0:
      return (rateConfig and 0xFF80'u16) or nextIdx.uint16
    return rateConfig
  else:
    # HT: increment MCS, check bitmap
    let maxMcs = rcU8(stats, RCS_MAX_NSS_MCS)
    if mcsIdx >= maxMcs:
      return rateConfig
    let nextMcs = mcsIdx + 1
    # Check if next MCS is in bitmap
    let nssIdx = ((rateConfig shr 11) and 0x6).uint8 - 2
    if nssIdx > 1:
      return rateConfig
    let groupBase = cast[pointer](cast[uint](stats) + RCS_RATE_BITMAP.uint + nssIdx.uint)
    let bitmap = cast[ptr uint8](groupBase)[]
    if ((bitmap shr nextMcs) and 1) != 0:
      var newRc = (rateConfig and 0xFF80'u16) or nextMcs.uint16
      let sgiField = rcU8(stats, RCS_SHORT_GI)
      if sgiField != 0:
        newRc = newRc or 0x200'u16
      return newRc
    return rateConfig

proc rc_sort_samples_tp*(stats: pointer, tpArray: pointer) {.exportc, cdecl.} =
  ## Sort rate entries by throughput (bubble sort, used during stats update).
  let nRates = rcU16(stats, RCS_N_RATES)
  if nRates <= 1:
    return
  # Simple insertion sort of throughput values
  var n = nRates.int - 1
  while n > 0:
    for i in 1 ..< n:
      let tp1 = cast[ptr uint32](cast[uint](tpArray) + (i * 4).uint)[]
      let tp0 = cast[ptr uint32](cast[uint](tpArray) + ((i - 1) * 4).uint)[]
      if tp1 > tp0:
        # Swap corresponding rate entries. Blob calls memmove (not memcpy)
        # for these 12-byte swaps — presumably the blob's standard-library
        # headers route the call through memmove. Using memmove keeps the
        # blob's call graph aligned.
        var tmp {.noinit.}: array[12, uint8]
        let e1 = rcRateEntryPtr(stats, i)
        let e0 = rcRateEntryPtr(stats, i - 1)
        discard c_memmove(addr tmp[0], e1, 12.csize_t)
        discard c_memmove(e1, e0, 12.csize_t)
        discard c_memmove(e0, addr tmp[0], 12.csize_t)
        # Swap tp values
        cast[ptr uint32](cast[uint](tpArray) + (i * 4).uint)[] = tp0
        cast[ptr uint32](cast[uint](tpArray) + ((i - 1) * 4).uint)[] = tp1
    dec n

proc rc_calc_prob_ewma*(entry: pointer) {.exportc, cdecl.} =
  ## Calculate probability EWMA for a single rate entry.
  ## Entry layout: +0=attempts(u16), +2=successes(u16), +4=prob_ewma(u16),
  ##               +8=cleared(u8), +9=initialized(u8)
  let attempts = rcU16(entry, 0)
  if attempts == 0:
    # No data: increment idle counter at +8, capped at 255
    let idle = rcU8(entry, 8)
    if idle < 255:
      rcU8(entry, 8) = idle + 1
    return

  let successes = rcU16(entry, 2)
  let initialized = rcU8(entry, 9)

  # Clear tracking byte
  rcU8(entry, 8) = 0

  # Calculate probability: (successes << 16) / attempts
  let prob = (successes.uint32 shl 16) div attempts.uint32

  if initialized == 0:
    # First measurement: use raw probability (minus 1 if < 100%)
    var p = prob.uint16
    if successes < attempts:
      if p > 0: dec p
      rcU16(entry, 4) = 0
    else:
      rcU16(entry, 4) = p
  else:
    # EWMA: new = (old * 96 + new * 32) / 128
    let oldProb = rcU16(entry, 4).uint32
    let ewma = (oldProb * 96 + (prob shl 5)) shr 7
    rcU16(entry, 4) = ewma.uint16

  # Mark as initialized
  rcU8(entry, 9) = 1

# ###########################################################################
#                   TX LAYER (txl_*)
# ###########################################################################

# TX Buffer
proc txl_buffer_init*() {.exportc, cdecl.} =
  ## Initialize TX buffer control descriptors.
  ## Vendor initializes the exported 60-byte txl_buffer_control_desc arrays
  ## directly; STA entries point at these records through sta+320.
  txl_buffer_reinit()

  for i in 0 ..< TX_BUFFER_POOL_SIZE:
    let d = cast[uint](addr txl_buffer_control_desc[0]) + i.uint * 60'u
    cast[ptr uint32](d + 0)[] = 0xBADCAB1E'u32
    cast[ptr uint32](d + 4)[] = phy_get_ntx().uint32 shl 14
    let maskNtx = phy_get_ntx().uint32
    cast[ptr uint32](d + 8)[] = (1'u32 shl (maskNtx + 1'u32)) - 1'u32
    cast[ptr uint32](d + 12)[] = 0
    cast[ptr uint32](d + 16)[] = 0xFFFF0704'u32
    cast[ptr uint32](d + 20)[] = 0
    cast[ptr uint32](d + 24)[] = 0
    cast[ptr uint32](d + 28)[] = 0
    cast[ptr uint32](d + 32)[] = 0
    cast[ptr uint32](d + 36)[] = regRead(MACHW_RNG_REG) and 0xFF'u32
    cast[ptr uint32](d + 40)[] = regRead(MACHW_RNG_REG) and 0xFF'u32
    cast[ptr uint32](d + 44)[] = regRead(MACHW_RNG_REG) and 0xFF'u32
    cast[ptr uint32](d + 48)[] = regRead(MACHW_RNG_REG) and 0xFF'u32
    cast[ptr uint32](d + 52)[] = 0x2200'u32
    cast[ptr uint32](d + 56)[] = 0x003F0000'u32

  for i in 0 ..< 2:
    let d = cast[uint](addr txl_buffer_control_desc_bcmc[0]) + i.uint * 60'u
    cast[ptr uint32](d + 0)[] = 0xBADCAB1E'u32
    cast[ptr uint32](d + 4)[] = phy_get_ntx().uint32 shl 14
    let maskNtx = phy_get_ntx().uint32
    cast[ptr uint32](d + 8)[] = (1'u32 shl (maskNtx + 1'u32)) - 1'u32
    cast[ptr uint32](d + 12)[] = 0
    cast[ptr uint32](d + 16)[] = 0xFFFF0704'u32
    cast[ptr uint32](d + 20)[] = 0
    cast[ptr uint32](d + 24)[] = 0
    cast[ptr uint32](d + 28)[] = 0
    cast[ptr uint32](d + 32)[] = 0
    cast[ptr uint32](d + 36)[] = regRead(MACHW_RNG_REG) and 0xFF'u32
    cast[ptr uint32](d + 40)[] = 0
    cast[ptr uint32](d + 44)[] = 0
    cast[ptr uint32](d + 48)[] = 0
    cast[ptr uint32](d + 52)[] = 0
    cast[ptr uint32](d + 56)[] = 0x003F0000'u32

proc txl_buffer_reinit*() {.exportc, cdecl.} =
  ## Reinitialize TX buffer pool indices (5 instrs).
  ## From blob: loads txl_buffer_env base, stores 0 to offset 180 (allocIdx)
  ## and offset 184 (freeIdx). This matches the TxBufferDesc field offsets
  ## after the descriptor arrays. Same as clearing allocIdx and freeIdx.
  cast[ptr uint32](cast[uint](addr txl_buffer_env[0]) + 180'u)[] = 0
  cast[ptr uint32](cast[uint](addr txl_buffer_env[0]) + 184'u)[] = 0

proc txl_buffer_reset*() {.exportc, cdecl, noinline.} =
  ## Reset TX buffer pool indices.
  cast[ptr uint32](cast[uint](addr txl_buffer_env[0]) + 180'u)[] = 0
  cast[ptr uint32](cast[uint](addr txl_buffer_env[0]) + 184'u)[] = 0

const
  HostTxStaInfoIdxOff = 49'u
  HostTxPolicyOff = 88'u
  HostTxSeqOutOff = 96'u
  HostTxHdrLenOff = 98'u
  HostTxQosExtOff = 99'u
  HostTxSecTailLenOff = 100'u
  HostTxDmaLinkOff = 104'u
  HostTxBufDescOff = 108'u
  HostTxHwDescOff = 112'u
  HostTxDmaEntryOff = 208'u
  HostTxHdrLenStoreOff = 212'u
  HostTxPadLenStoreOff = 216'u
  HostTxPendingOff = 224'u
  HostTxBufMagicOff = 280'u
  HostTxUserIdxOff = 460'u
  HostTxDmaBaseOff = 464'u
  HostTxMacHdrBaseOff = 556'u

proc txlApplyEapolRetryPolicy(dmaBase: uint) {.inline.} =
  ## Vendor keeps the primary control-port rate from RC, but mixes in robust
  ## legacy fallbacks for EAPOL retries. Leaving all retries as high HT rates
  ## makes M2 unreliable on the AP used by the hardware validation test.
  cast[ptr uint32](dmaBase + 24'u)[] = 0x8000040A'u32
  cast[ptr uint32](dmaBase + 28'u)[] = 0x80001007'u32
  cast[ptr uint32](dmaBase + 32'u)[] = 0x80000400'u32
  cast[ptr uint32](dmaBase + 36'u)[] = 0x00000070'u32
  cast[ptr uint32](dmaBase + 40'u)[] = 0x00000070'u32
  cast[ptr uint32](dmaBase + 44'u)[] = 0x00000070'u32
  cast[ptr uint32](dmaBase + 48'u)[] = 0x00000070'u32

proc txl_buffer_alloc*(param: pointer, queueIdx: uint32, flags: uint32): pointer {.exportc, cdecl.} =
  ## Allocate a TX buffer descriptor. Blob ABI: a0=tx_desc, a1=queue idx, a2=user_idx.
  ##
  ## Algorithm (from blob, ~0x90 bytes):
  ##   hdrLen = desc[98]                                        (lbu)
  ##   desc[216] = align16(hdrLen) - hdrLen                     (pad length)
  ##   desc[212] = hdrLen
  ##   desc[460] = user_idx                                     (a2, byte)
  ##   desc[280] = 0xCAFEFADE                                   (magic)
  ##   bufPtr    = desc + 556 + hdrLen
  ##   txu_cntrl_frame_build(desc, bufPtr)                      ; builds 802.11 hdr
  ##   loop 15x { copy txdesc.umac.buf_control[1..15] }         ; buffer control
  ##   atomic link into txl_buffer_env free list (T-Head insns) ; buffer pool
  ##   link into txl_frame_env via frame+4 / frame+8 pointers   ; frame list
  ##   desc[224] = 0                                            ; pending flag
  ##   return desc + 208
  let descU = cast[uint](param)
  let hdrLen = cast[ptr uint8](descU + HostTxHdrLenOff)[]
  let hdrLenU = hdrLen.uint32
  let padLen = ((hdrLenU + 15'u32) and not 15'u32) - hdrLenU

  # Metadata writes (desc+128+88 == desc+216, desc+128+84 == desc+212).
  cast[ptr uint32](descU + HostTxPadLenStoreOff)[] = padLen
  cast[ptr uint32](descU + HostTxHdrLenStoreOff)[] = hdrLenU

  # CAFEFADE magic at desc+280 (buffer validity check).
  const CAFEFADE = 0xCAFEFADE'u32
  cast[ptr uint32](descU + HostTxBufMagicOff)[] = CAFEFADE

  cast[ptr uint8](descU + HostTxUserIdxOff)[] = cast[uint8](flags and 0xFF'u32)

  # Compute MAC header write point: bufPtr = desc + 556 + hdrLen.
  let bufPtr = cast[pointer](descU + HostTxMacHdrBaseOff + hdrLen.uint)

  # Build the 802.11 header inline at bufPtr.
  txu_cntrl_frame_build(param, bufPtr)

  # Copy the TX buffer control template. Vendor emits T-Head indexed load/store
  # opcodes here, equivalent to copying 15 u32 words from buf_control+0.
  let bufferControl = cast[uint](cast[ptr pointer](descU + HostTxPolicyOff)[])
  let dmaBase = descU + HostTxDmaBaseOff
  for i in 0'u32 ..< 15'u32:
    cast[ptr uint32](dmaBase + i * 4'u32)[] =
      cast[ptr uint32](bufferControl + i.uint * 4'u)[]

  let protoTrace = cast[ptr uint16](descU + 32)[]
  let isEapol = protoTrace == 0x8E88'u16 or protoTrace == 0x888E'u16
  if isEapol:
    txlApplyEapolRetryPolicy(dmaBase)

  # Link into txl_buffer_env[queueIdx + 22], matching txl_int_fake_transfer.
  # dmaEntry = desc + 208 is both the return value and the node pushed.
  let dmaEntry = descU + HostTxDmaEntryOff
  let queueBase = cast[uint](addr txl_buffer_env[0])
  let entryAddr = queueBase + (queueIdx + 22'u32).uint * 8'u
  when defined(bl808WifiNimFw):
    if isEapol:
      nimFwTrace2U32("[WIFI-NIMFW] txbuf_eapol ",
                     queueIdx or (hdrLen.uint32 shl 8),
                     cast[uint32](dmaEntry))
      nimFwTrace2U32("[WIFI-NIMFW] txbuf_ctrl ",
                     cast[uint32](bufferControl),
                     cast[ptr uint32](dmaBase)[])
      when defined(bl808WifiConnectTrace):
        if nimFwDbgEapolTraceCount < 64'u32:
          nimFwConnectTrace2U32("[WIFI-CT] txbuf_eapol ",
                                queueIdx or (hdrLen.uint32 shl 8) or
                                  (padLen.uint32 shl 16),
                                cast[uint32](dmaEntry))
          nimFwConnectTrace2U32("[WIFI-CT] txbuf_ctrl ",
                                cast[uint32](bufferControl),
                                cast[ptr uint32](dmaBase)[])
          nimFwConnectTrace2U32("[WIFI-CT] txbuf_pol0 ",
                                cast[ptr uint32](dmaBase + 4)[],
                                cast[ptr uint32](dmaBase + 20)[])
          nimFwConnectTrace2U32("[WIFI-CT] txbuf_pol1 ",
                                cast[ptr uint32](dmaBase + 36)[],
                                cast[ptr uint32](dmaBase + 52)[])
  let listTail = cast[ptr pointer](entryAddr + 4)[]
  if listTail == nil:
    cast[ptr pointer](entryAddr + 4)[] = cast[pointer](dmaEntry)
  else:
    let tail = cast[ptr pointer](entryAddr + 8)[]
    cast[ptr pointer](cast[uint](tail) + 16)[] = cast[pointer](dmaEntry)
  cast[ptr pointer](entryAddr + 8)[] = cast[pointer](dmaEntry)

  # Clear pending flag at desc+224.
  cast[ptr uint32](descU + HostTxPendingOff)[] = 0

  # Return buffer control pointer.
  return cast[pointer](dmaEntry)

proc txl_buffer_update_thd*(param: pointer) {.exportc, cdecl.} =
  ## Update TX header descriptor chain from buffer pointer array.
  ## From disassembly (52 instrs): walks buffer pointers at param+52 (stride 4),
  ## creates THD entries at linkDesc+92 (stride 20) with cafefade magic,
  ## then sets up the main THD at linkDesc+72 pointing to the header buffer
  ## at linkDesc+348.
  let descAddr = cast[uint](param)
  let linkDesc = cast[uint](cast[ptr pointer](descAddr + HostTxBufDescOff)[])
  let hwDesc = cast[uint](cast[ptr pointer](descAddr + HostTxHwDescOff)[])
  var thdEntry = linkDesc + 92
  var bufPtrOff = descAddr + 52
  var count = 0'u32
  var lastEntry = thdEntry
  const CAFEFADE = 0xCAFEFADE'u32
  while true:
    let bufPtr = cast[ptr uint32](bufPtrOff)[]
    if bufPtr == 0:
      # Blob spins at .L19 when count==0 (no valid buffer seen) but does NOT
      # call assert_err there — it just falls through into the infinite loop
      # as a hard-trap. Mirror that without the extra call.
      if count == 0:
        while true: discard
      break
    # Fill THD entry
    cast[ptr uint32](thdEntry)[] = CAFEFADE
    cast[ptr uint32](thdEntry + 8)[] = bufPtr
    let bufLen = cast[ptr uint32](bufPtrOff + 16)[]
    cast[ptr uint32](thdEntry + 16)[] = 0
    cast[ptr uint32](thdEntry + 12)[] = bufPtr + bufLen - 1
    lastEntry = thdEntry
    thdEntry += 20
    cast[ptr uint32](lastEntry + 4)[] = cast[uint32](thdEntry)
    bufPtrOff += 4
    count += 1
  # Set up main THD at linkDesc+72
  let headerBuf = linkDesc + 348
  let headerLen = cast[ptr uint32](linkDesc + 4)[]
  cast[ptr uint32](linkDesc + 72)[] = CAFEFADE
  cast[ptr uint32](linkDesc + 76)[] = cast[uint32](linkDesc + 92)
  cast[ptr uint32](linkDesc + 80)[] = cast[uint32](headerBuf)
  cast[ptr uint32](linkDesc + 84)[] = cast[uint32](headerBuf) + headerLen - 1
  cast[ptr uint32](linkDesc + 88)[] = 0
  # Link hwDesc to main THD; finalize chain
  cast[ptr uint32](hwDesc + 16)[] = cast[uint32](linkDesc + 72)
  cast[ptr uint32](lastEntry + 16)[] = 0
  cast[ptr uint32](lastEntry + 4)[] = 0
  cast[ptr uint32](hwDesc + 60)[] = 256

# TX Confirm
proc txl_cfm_init*() {.exportc, cdecl.} =
  ## Initialize TX confirmation module.
  ## Blob: memset(txl_cfm_env, 0, 40) + 5× co_list_init over the 40-byte
  ## env struct (each CoList is 8 bytes: first + last pointer).
  ## Unroll the 5-iteration loop explicitly — GCC -Os folded the previous
  ## loop into a single inlined co_list_init, losing the five blob-matching
  ## call sites.
  discard c_memset(addr txl_cfm_env[0], 0, 40.csize_t)
  let base = cast[uint](addr txl_cfm_env[0])
  co_list_init(cast[ptr CoList](base + 0))
  co_list_init(cast[ptr CoList](base + 8))
  co_list_init(cast[ptr CoList](base + 16))
  co_list_init(cast[ptr CoList](base + 24))
  co_list_init(cast[ptr CoList](base + 32))

proc txl_cfm_push*(desc: pointer, status: uint32, acIdx: uint32) {.exportc, cdecl.} =
  ## Push a TX descriptor to confirmation queue.
  ## Blob ABI: a0=desc, a1=status, a2=ac_idx.
  ## Blob algorithm:
  ##   *(u32*)(*((u32*)(desc+112)) + 16) = a1  ; status -> hwdesc[16]
  ##   co_list_push_back(&txl_cfm_env, desc)
  ##   a2 = ac_idx
  ##   evt = txl_cfm_evt_bit[a2]
  ##   tail-call ke_evt_set(evt)
  ## Prior Nim bug: tail-called ipc_emb_tx_evt(ac_idx) — completely wrong
  ## target; the blob signals the KE scheduler, not the host IPC.
  let descU = cast[uint](desc)
  let fenvPtr = cast[ptr pointer](descU + HostTxHwDescOff)[]
  when defined(bl808WifiNimFw):
    var cfmHeadTrace = 0'u32
    if fenvPtr != nil:
      cfmHeadTrace = cast[ptr uint32](cast[uint](fenvPtr))[]
    let traceBadCfm = cfmHeadTrace == 0xBADCAB1E'u32
    if nimFwDbgCfmTraceCount < 32'u32 or traceBadCfm:
      var thdStatusTrace = status
      if fenvPtr != nil:
        let thdBaseTrace = cast[ptr pointer](cast[uint](fenvPtr))[]
        if thdBaseTrace != nil:
          thdStatusTrace = cast[ptr uint32](cast[uint](thdBaseTrace) + 16'u)[]
      nimFwTrace2U32("[WIFI-NIMFW] cfm_push ",
                     acIdx or (nimFwDbgCfmTraceCount shl 8),
                     cast[uint32](descU))
      nimFwTrace2U32("[WIFI-NIMFW] cfm_ptrs ",
                     cast[uint32](cast[uint](fenvPtr)),
                     cfmHeadTrace)
      nimFwTrace2U32("[WIFI-NIMFW] cfm_links ",
                     cast[ptr uint32](descU + 8)[],
                     cast[ptr uint32](descU + HostTxBufDescOff)[])
      when defined(bl808WifiConnectTrace):
        nimFwConnectTrace2U32("[WIFI-CT] cfm_push ",
                              acIdx or (nimFwDbgCfmTraceCount shl 8),
                              cast[uint32](descU))
        nimFwConnectTrace2U32("[WIFI-CT] cfm_ptrs ",
                              cast[uint32](cast[uint](fenvPtr)),
                              cfmHeadTrace)
        nimFwConnectTrace2U32("[WIFI-CT] cfm_status ",
                              thdStatusTrace,
                              status)
        nimFwConnectTrace2U32("[WIFI-CT] cfm_links ",
                              cast[ptr uint32](descU + 8)[],
                              cast[ptr uint32](descU + HostTxBufDescOff)[])
      inc nimFwDbgCfmTraceCount
  if fenvPtr != nil:
    let hwdesc = cast[ptr pointer](cast[uint](fenvPtr))[]
    if hwdesc != nil:
      cast[ptr uint32](cast[uint](hwdesc) + 16)[] = status
  # Blob indexes txl_cfm_env by AC before queueing the descriptor.
  co_list_push_back(cast[ptr CoList](cast[uint](addr txl_cfm_env[0]) + acIdx.uint * 8'u),
                    cast[ptr CoListHdr](desc))
  if acIdx < 5'u32:
    ke_evt_set(txl_cfm_evt_bit[acIdx])

proc txl_cfm_evt*() {.exportc, cdecl.} =
  ## Process TX confirmation events (212 bytes in blob).
  ## Blob (txl_cfm.o): ke_evt_field[ac] lookup, assert event pending,
  ##   ke_evt_clear, then loop with IRQ-safe co_list_pop_front:
  ##   me_tx_cfm_singleton → txu_cntrl_cfm → txl_cntrl_env[80]-- → ipc_emb_txcfm
  ##   → ipc_emb_txcfm_ind (per-descriptor, inside loop).
  var acIdx {.noinit.}: uint32
  {.emit: ["asm volatile(\"mv %0, a0\" : \"=r\"(", acIdx, ") );"].}

  let cfmBase = cast[uint](addr txl_cfm_env[0])
  let cntrlBase = cast[uint](addr txl_cntrl_env[0])

  # Compute event field for this AC (blob uses .LANCHOR0 = txl_cfm_evt_bit array).
  let evtField = if acIdx < 5'u32: txl_cfm_evt_bit[acIdx] else: 0'u32
  let acMask = 1'u32 shl acIdx

  # Assert event is pending (blob: ke_env[0] & evtField != 0)
  let keEvtBits = cast[ptr uint32](addr ke_env[0])[]
  if (keEvtBits and evtField) == 0:
    assert_err("txl_cfm.c", "txl_cfm.c", 346)

  # Clear the event (blob: ke_evt_clear with evtField, not acMask)
  ke_evt_clear(evtField)

  # Get per-AC confirmation list
  let acList = cast[ptr CoList](cfmBase + acIdx * 8)

  # Main loop: process all pending TX confirms for this AC
  while true:
    # Re-read list head each iteration (blob reloads via th.lrw)
    let first = cast[ptr CoListHdr](cast[uint](acList))
    if cast[ptr pointer](cast[uint](acList))[] == nil:
      break

    # IRQ-safe pop (blob: csrrci mstatus,8 / csrsi mstatus,8)
    let irqState = irqSave()
    let node = co_list_pop_front(acList)
    irqRestore(irqState)

    if node == nil:
      break

    when defined(bl808WifiNimFw):
      let nodeU = cast[uint](node)
      let fenvPtrTrace = cast[ptr pointer](nodeU + HostTxHwDescOff)[]
      var cfmHeadTrace = 0'u32
      if fenvPtrTrace != nil:
        cfmHeadTrace = cast[ptr uint32](cast[uint](fenvPtrTrace))[]
      let traceBadCfm = cfmHeadTrace == 0xBADCAB1E'u32
      if nimFwDbgCfmTraceCount < 64'u32 or traceBadCfm:
        var thdStatusTrace = 0'u32
        if fenvPtrTrace != nil:
          let thdBaseTrace = cast[ptr pointer](cast[uint](fenvPtrTrace))[]
          if thdBaseTrace != nil:
            thdStatusTrace = cast[ptr uint32](cast[uint](thdBaseTrace) + 16'u)[]
        nimFwTrace2U32("[WIFI-NIMFW] cfm_evt ",
                       acIdx or (nimFwDbgCfmTraceCount shl 8),
                       cast[uint32](nodeU))
        nimFwTrace2U32("[WIFI-NIMFW] cfm_evt_ptr ",
                       cast[uint32](cast[uint](fenvPtrTrace)),
                       cfmHeadTrace)
        nimFwTrace2U32("[WIFI-NIMFW] cfm_evt_lnk ",
                       cast[ptr uint32](nodeU + 8)[],
                       cast[ptr uint32](nodeU + HostTxBufDescOff)[])
        when defined(bl808WifiConnectTrace):
          nimFwConnectTrace2U32("[WIFI-CT] cfm_evt ",
                                acIdx or (nimFwDbgCfmTraceCount shl 8),
                                cast[uint32](nodeU))
          nimFwConnectTrace2U32("[WIFI-CT] cfm_evt_ptr ",
                                cast[uint32](cast[uint](fenvPtrTrace)),
                                cfmHeadTrace)
          nimFwConnectTrace2U32("[WIFI-CT] cfm_evt_status ",
                                thdStatusTrace,
                                cast[ptr uint32](nodeU + 16)[])
          nimFwConnectTrace2U32("[WIFI-CT] cfm_evt_lnk ",
                                cast[ptr uint32](nodeU + 8)[],
                                cast[ptr uint32](nodeU + HostTxBufDescOff)[])
        inc nimFwDbgCfmTraceCount

    # Rate control update
    me_tx_cfm_singleton(cast[pointer](node))
    # Upper-MAC TX confirmation
    txu_cntrl_cfm(cast[pointer](node))
    # Decrement pending MPDU count (blob: txl_cntrl_env[80]--)
    let pending = cast[ptr uint32](cntrlBase + 80)[]
    cast[ptr uint32](cntrlBase + 80)[] = pending - 1
    # IPC TX confirm to host
    ipc_emb_txcfm(cast[pointer](node))
    # IPC confirm indication - called per descriptor inside loop (blob: 0xb4-0xbe)
    ipc_emb_txcfm_ind(acMask)

proc txl_cfm_flush*() {.exportc, cdecl, noinline.} =
  ## Flush all pending TX confirmations (190 bytes in blob).
  ## From blob: a0=ac_index, a1=cfm_list_ptr, a2=ac_mask.
  ## Iterates the cfm list (a1) via co_list_pop_front, for each descriptor:
  ##   1. Reads desc+112 (THD chain ptr) -> THD[0], desc+104 (DMA link)
  ##   2. If link != nil: write (0x3C000000 | ac_mask) to THD[16]
  ##   3. If link == nil: check THD[16]; if >= 0, write ac_mask to THD[16]
  ##   4. Check desc+8 (callback):
  ##      - If nil: call txl_frame_cfm(desc), continue loop
  ##      - If present: call txu_cntrl_cfm(desc), decrement txl_cntrl_env[80],
  ##        clear desc+108, increment count, call ipc_emb_txcfm(desc)
  ##   5. After loop: call txl_frame_evt()
  ##   6. If count > 0: tail-call ipc_emb_txcfm_ind(1 << ac)
  var acIdx {.noinit.}: uint32
  var cfmListPtr {.noinit.}: pointer
  var acMask {.noinit.}: uint32
  {.emit: ["asm volatile(\"mv %0, a0\" : \"=r\"(", acIdx, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", cfmListPtr, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a2\" : \"=r\"(", acMask, ") );"].}

  let cfmList = cast[ptr CoList](cfmListPtr)
  let cntrlBase = cast[uint](addr txl_cntrl_env[0])
  let forcedStatus = 0x3C000000'u32 or acMask
  var count: uint32 = 0

  while true:
    let node = co_list_pop_front(cfmList)
    if node == nil:
      break
    let descU = cast[uint](node)
    let thdChainPtr = cast[ptr pointer](descU + HostTxHwDescOff)[]
    let linkDesc = cast[ptr pointer](descU + HostTxDmaLinkOff)[]

    if thdChainPtr != nil:
      let thdBase = cast[uint](cast[ptr pointer](cast[uint](thdChainPtr))[])
      if linkDesc != nil:
        # DMA owned: force confirm with 0x3C000000 | ac_mask
        cast[ptr uint32](thdBase + 16)[] = forcedStatus
      else:
        let curStatus = cast[ptr int32](thdBase + 16)[]
        if curStatus >= 0:
          cast[ptr uint32](thdBase + 16)[] = acMask

    # Check callback at desc+8
    let callbackPtr = cast[ptr pointer](descU + 8)[]
    if callbackPtr == nil:
      # No callback: call txl_frame_cfm and continue loop
      txl_frame_cfm(cast[pointer](node))
      continue

    # Have callback: process upper-layer confirm
    txu_cntrl_cfm(cast[pointer](node))
    # Decrement pending MPDU count (txl_cntrl_env[80]--)
    let pending = cast[ptr uint32](cntrlBase + 80)[]
    cast[ptr uint32](cntrlBase + 80)[] = pending - 1
    # Clear desc+108 buffer descriptor pointer.
    let linkField = cast[ptr pointer](descU + HostTxBufDescOff)
    if linkField[] != nil:
      linkField[] = nil
    count += 1
    # IPC TX confirm to host
    ipc_emb_txcfm(cast[pointer](node))

  # After loop: signal frame event processing
  txl_frame_evt()
  # If any callbacks were processed, send IPC confirm indication
  if count > 0:
    ipc_emb_txcfm_ind(1'u32 shl acIdx)

proc txl_cfm_flush_desc*(desc: pointer) {.exportc, cdecl.} =
  ## Flush a specific TX confirmation descriptor (120 bytes in blob).
  ## From blob ABI: a0=ac_index, a1=desc_ptr, a2=status_override.
  ## Logic: reads desc+112 (THD chain) -> THD[0], desc+104 (DMA link).
  ## If link != nil (DMA owned): write (status_override | 0x3C000000) to THD[16].
  ## If link == nil: check THD[16]; if >= 0, write status_override to THD[16].
  ## Then checks desc+8 (callback):
  ##   - If nil: call txl_frame_cfm(desc), tail-call txl_frame_evt() (return 0)
  ##   - If present: call txu_cntrl_cfm(desc), decrement txl_cntrl_env[80],
  ##     clear desc+108, call ipc_emb_txcfm(desc), tail-call ipc_emb_txcfm_ind(1 << ac)
  var regA0 {.noinit.}: uint32
  var regA1 {.noinit.}: pointer
  var regA2 {.noinit.}: uint32
  {.emit: ["asm volatile(\"mv %0, a0\" : \"=r\"(", regA0, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", regA1, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a2\" : \"=r\"(", regA2, ") );"].}

  let ac = regA0
  let descU = cast[uint](regA1)
  var status = regA2

  let thdChainPtr = cast[ptr pointer](descU + HostTxHwDescOff)[]
  let linkDesc = cast[ptr pointer](descU + HostTxDmaLinkOff)[]

  if thdChainPtr != nil:
    let thdBase = cast[uint](cast[ptr pointer](cast[uint](thdChainPtr))[])
    if linkDesc != nil:
      # DMA owned: force confirm with status | 0x3C000000
      cast[ptr uint32](thdBase + 16)[] = status or 0x3C000000'u32
    else:
      # Not DMA owned: check if THD[16] is negative (bit 31 set)
      let curStatus = cast[ptr int32](thdBase + 16)[]
      if curStatus >= 0:
        cast[ptr uint32](thdBase + 16)[] = status

  # Check callback at desc+8
  let callbackPtr = cast[ptr pointer](descU + 8)[]
  if callbackPtr == nil:
    # No callback: call txl_frame_cfm then txl_frame_evt
    txl_frame_cfm(cast[pointer](descU))
    txl_frame_evt()
    return

  # Have callback: process upper-layer confirm
  txu_cntrl_cfm(cast[pointer](descU))
  # Decrement pending MPDU count (txl_cntrl_env[80]--)
  let cntrlBase = cast[uint](addr txl_cntrl_env[0])
  let pending = cast[ptr uint32](cntrlBase + 80)[]
  cast[ptr uint32](cntrlBase + 80)[] = pending - 1
  # Clear desc+108 buffer descriptor pointer.
  let linkField = cast[ptr pointer](descU + HostTxBufDescOff)
  if linkField[] != nil:
    linkField[] = nil
  # IPC TX confirm to host
  ipc_emb_txcfm(cast[pointer](descU))
  # IPC confirm indication
  ipc_emb_txcfm_ind(1'u32 shl ac)

proc txl_cfm_dump*() {.exportc, cdecl, noinline.} =
  ## Dump TX confirmation queue for debugging.
  ## Blob algorithm (190 instrs):
  ##   - Log header line 570, 572, and (5 queues) 573.
  ##   - For i in 0..4:
  ##       cnt = co_list_cnt(&txl_cfm_env + 8*i)
  ##       head = txl_cfm_env[i*2]  (first of that CoList)
  ##       log line 577 with (i, head, cnt)
  ##       log separator line 581
  ##       if cnt != 0:
  ##         walk head: for each node call per-entry printFn:
  ##           printFn_ptr = node->112->16 (a2 arg); log line 589 with extra
  ##       log line 589 with 0 if empty
  ##   Key invariant: co_list_cnt must be invoked every iteration.
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  let logFuncPtr = cast[ptr pointer](opsBase + 204)[]
  if logFuncPtr == nil: return
  type LogFn = proc(level: uint32, sev: uint32, file: cstring, line: uint32) {.cdecl, varargs.}
  let logFn = cast[LogFn](logFuncPtr)
  # Headers
  logFn(2, 0, "txl_cfm.c", 570)
  logFn(2, 0, "txl_cfm.c", 572)
  logFn(2, 0, "txl_cfm.c", 573, 5'u32)
  let cfmBase = cast[uint](addr txl_cfm_env[0])
  for i in 0'u32 ..< 5'u32:
    let listPtr = cast[ptr CoList](cfmBase + i * 8)
    let cnt = co_list_cnt(listPtr)
    let head = listPtr.first
    logFn(2, 0, "txl_cfm.c", 577, i, head, cnt)
    logFn(2, 0, "txl_cfm.c", 581)
    var node = head
    while node != nil:
      let descAddr = cast[uint](node)
      let hwDescPtr = cast[ptr pointer](descAddr + HostTxHwDescOff)[]
      let thdField16 = cast[ptr uint32](cast[uint](hwDescPtr) + 16)[]
      logFn(2, 0, "txl_cfm.c", 585, node, thdField16)
      node = node.next
    logFn(2, 0, "txl_cfm.c", 589)

proc txl_cfm_dma_int_handler_backup*() {.exportc, cdecl.} =
  ## Backup DMA interrupt handler for TX confirm.
  ## From disassembly: clears bit 0 of txl_cfm_env[1] (status flags word at offset 4).
  txl_cfm_env[1] = txl_cfm_env[1] and not 1'u32

# TX Control
proc txl_cntrl_init*() {.exportc, cdecl.} =
  ## Initialize TX control module.
  ## From disassembly: calls txl_buffer_init, txl_cfm_init, txl_frame_init,
  ## txl_hwdesc_init(0), then memset(txl_cntrl_env, 0, 92).
  ## Loops over 5 AC entries (stride 16), for each:
  ##   - co_list_init on the pending frame list (offset 4)
  ##   - Clear first descriptor pointer (offset 0)
  ##   - Store MAC HW descriptor address at offset 12 (half-word)
  ##   - Clear busy flag at offset 14 (byte)
  ## Finally clears the global txlCntrlBusy flag.
  # Blob order: txl_hwdesc_init FIRST, then buffer/cfm/frame
  txl_hwdesc_init()
  txl_buffer_init()
  txl_cfm_init()
  txl_frame_init()
  discard c_memset(addr txl_cntrl_env[0], 0, 92.csize_t)
  let base = cast[uint](addr txl_cntrl_env[0])
  # MAC HW TX descriptor base addresses: 0x24A00080 + ac*4
  for ac in 0'u32 ..< NUM_TX_QUEUES.uint32:
    let acBase = base + ac * 16
    # co_list_init on the list at offset 4
    co_list_init(cast[ptr CoList](acBase + 4))
    # Clear first descriptor pointer
    cast[ptr uint32](acBase)[] = 0
    # Store MAC HW descriptor address (base 0x24A00080 + ac*4) as half-word
    let hwDescAddr = (0x24A00080'u32 + ac * 4).uint16
    cast[ptr uint16](acBase + 12)[] = hwDescAddr
    # Clear busy flag
    cast[ptr uint8](acBase + 14)[] = 0
  # Clear global busy flag
  txlCntrlBusy = 0
  # Also update convenience arrays
  for i in 0 ..< NUM_TX_QUEUES:
    txlAcPending[i] = 0
    txlAcBusy[i] = false

proc txl_cntrl_tx_check*(vifEntry: pointer): bool {.exportc, cdecl.} =
  ## Check whether TX should be admitted right now.
  ## Blob algorithm:
  ##   a5 = *(u8*)(txl_cntrl_env+0x58)    ; halted-for-all-AC flag
  ##   if (a5 != 0) return 0
  ##   tail-call chan_is_tx_allowed(vifEntry)
  ## Prior Nim bug: walked txlAcPending counters (always return true if any
  ## AC queued), which has the opposite sense (admits when halted).
  let halted = cast[ptr uint8](cast[uint](addr txl_cntrl_env[0]) + 0x58)[]
  if halted != 0:
    return false
  return chan_is_tx_allowed(vifEntry)

proc txl_cntrl_push*(param: pointer, ac: uint8): uint8 {.exportc, cdecl.} =
  ## Push a frame descriptor to the TX control queue (224 bytes in blob).
  ## Blob call sequence: THD setup → IRQ save → check desc[8]:
  ##   if nil: txl_int_fake_transfer
  ##   if non-nil: txl_buffer_alloc + txl_buffer_update_thd
  ## → txl_payload_handle_backup → co_list_push_back → IRQ restore
  ## → increment pkt count → td_pck_ind → ps_check_tx_frame → return 0
  let descAddr = cast[uint](param)
  # Read frame fields for THD setup (blob at 0x0a-0x14)
  let secTailLen = cast[ptr uint8](descAddr + HostTxSecTailLenOff)[]
  let hdrLen = cast[ptr uint8](descAddr + HostTxHdrLenOff)[]
  let thdPtr = cast[ptr pointer](descAddr + HostTxHwDescOff)[]
  let thdAddr = cast[uint](thdPtr)
  let halfLen = cast[ptr uint16](descAddr + 12)[]
  let totalLen = secTailLen.uint32 + hdrLen.uint32 + halfLen.uint32 + 4
  # Initialize THD fields (blob at 0x1e-0x4e)
  cast[ptr uint32](thdAddr + 12)[] = 0
  cast[ptr uint32](thdAddr + 28)[] = totalLen
  cast[ptr uint32](thdAddr + 4)[] = 0xCAFEBABE'u32
  cast[ptr uint32](thdAddr + 8)[] = 0
  cast[ptr uint32](thdAddr + 16)[] = 0
  cast[ptr uint32](thdAddr + 40)[] = 0
  cast[ptr uint32](thdAddr + 60)[] = 0
  cast[ptr uint32](thdAddr + 20)[] = 0
  cast[ptr uint32](thdAddr + 24)[] = 0
  cast[ptr uint32](thdAddr + 32)[] = 0
  cast[ptr uint32](thdAddr + 64)[] = 0
  # IRQ save (blob: csrrci s2,mstatus,8 at 0x52)
  let saved = irqSave()
  # Check desc[8] for existing queue chain (blob at 0x56)
  let queueFirst = cast[ptr pointer](descAddr + 8)[]
  when defined(bl808WifiNimFw):
    let protoTrace = cast[ptr uint16](descAddr + 32)[]
    if protoTrace == 0x8E88'u16 or protoTrace == 0x888E'u16:
      nimFwTrace2U32("[WIFI-NIMFW] txl_push_eapol ",
                     ac.uint32 or (cast[ptr uint8](descAddr + 46)[].uint32 shl 8) or
                       (cast[ptr uint8](descAddr + 47)[].uint32 shl 16) or
                       (cast[ptr uint8](descAddr + HostTxStaInfoIdxOff)[].uint32 shl 24),
                     cast[uint32](cast[uint](queueFirst)))
  if queueFirst == nil:
    # Empty queue: fake transfer (blob: txl_int_fake_transfer at 0x5e)
    txl_int_fake_transfer(param, ac.uint32)
  else:
    # Queue exists: allocate buffer and update THD (blob: .L119 at 0xc6)
    let bufDesc = txl_buffer_alloc(param, ac.uint32, 0'u32)
    cast[ptr pointer](descAddr + HostTxBufDescOff)[] = bufDesc
    if bufDesc != nil:
      cast[ptr pointer](cast[uint](bufDesc) + 20)[] = param
    txl_buffer_update_thd(param)
  # Handle payload backup (blob: txl_payload_handle_backup at 0x66)
  txl_payload_handle_backup(nil)
  # Add to per-AC pending list (blob: co_list_push_back at 0x80)
  let cntrlBase = cast[uint](addr txl_cntrl_env[0])
  let acListBase = cntrlBase + ac.uint * 16 + 4
  co_list_push_back(cast[ptr CoList](acListBase), cast[ptr CoListHdr](param))
  # IRQ restore (blob at 0x88-0x8c)
  irqRestore(saved)
  # Increment packet counter (blob at 0x90-0x96)
  let pktCnt = cast[ptr uint32](cntrlBase + 80)[]
  cast[ptr uint32](cntrlBase + 80)[] = pktCnt + 1
  # Traffic detection indication (blob: td_pck_ind(desc[47], desc[49], 0) at 0xa0)
  let vifIdx = cast[ptr uint8](descAddr + 47)[]
  let staIdx = cast[ptr uint8](descAddr + HostTxStaInfoIdxOff)[]
  td_pck_ind(vifIdx, staIdx.uint32)
  # Power save check (blob: ps_check_tx_frame(desc[49], desc[46]) at 0xb0)
  let psArg = cast[ptr uint8](descAddr + 46)[]
  discard ps_check_tx_frame(staIdx, psArg)
  return 0'u8

proc txl_cntrl_push_int*(param: pointer, ac: uint8): uint8 {.exportc, cdecl.} =
  ## Push an internal frame to TX control (92 instrs / 0x116 bytes in blob).
  ## Blob call graph: txl_cntrl_tx_check, apm_tx_int_ps_check,
  ##   txl_int_fake_transfer, co_list_push_back(x2), txl_payload_handle_backup,
  ##   txl_frame_release, apm_tx_int_ps_postpone.
  let descU = cast[uint](param)
  let rcStatsPtr = cast[ptr pointer](descU + 112)[]
  let envBase = cast[uint](addr txl_cntrl_env[0])
  let staTabBase = cast[uint](addr sta_info_tab[0])
  let linkPtrTrace = cast[ptr pointer](descU + 108)[]
  let linkUTrace = cast[uint](linkPtrTrace)
  let fcTrace = if linkPtrTrace != nil: cast[ptr uint8](linkUTrace + 348)[] else: 0'u8
  let traceMgmt = linkPtrTrace != nil and nimFwMgmtFcTrace(fcTrace)

  # Step 1: Check TX readiness (blob computes VIF from desc[47], then calls txl_cntrl_tx_check)
  let vifIdxTx = cast[ptr uint8](descU + 47)[]
  let vifEntryTx = cast[pointer](cast[uint](addr vif_info_tab[0]) + vifIdxTx.uint * VIF_ENTRY_SIZE.uint)
  let txReady = txl_cntrl_tx_check(vifEntryTx)
  if traceMgmt:
    nimFwTrace2U32("[WIFI-NIMFW] txint_enter ",
                   ac.uint32 or (vifIdxTx.uint32 shl 8) or
                     (cast[ptr uint8](descU + 49)[].uint32 shl 16),
                   cast[uint32](descU))
    let chanBaseTrace = cast[uint](addr chan_env[0])
    let curCtxtTrace = cast[ptr pointer](chanBaseTrace + 32)[]
    let schedCtxtTrace = cast[ptr pointer](chanBaseTrace + 36)[]
    let vifCtxtTrace = cast[ptr pointer](cast[uint](vifEntryTx) + 64)[]
    let flagsTrace = cast[ptr uint8](chanBaseTrace + 120)[]
    let cntTrace = cast[ptr uint8](chanBaseTrace + 124)[]
    let onChanTrace = chan_is_on_channel(vifEntryTx)
    var cur22Trace = 0'u8
    var cur23Trace = 0'u8
    var cur25Trace = 0'u8
    if curCtxtTrace != nil:
      let curUTrace = cast[uint](curCtxtTrace)
      cur22Trace = cast[ptr uint8](curUTrace + 22)[]
      cur23Trace = cast[ptr uint8](curUTrace + 23)[]
      cur25Trace = cast[ptr uint8](curUTrace + 25)[]
    nimFwTrace2U32("[WIFI-NIMFW] txint_chan ",
                   txReady.uint32 or (onChanTrace.uint32 shl 8) or
                     (flagsTrace.uint32 shl 16) or (cntTrace.uint32 shl 24),
                   cur22Trace.uint32 or (cur23Trace.uint32 shl 8) or
                     (cur25Trace.uint32 shl 16) or
                     (cast[ptr uint8](cast[uint](vifEntryTx) + 87)[].uint32 shl 24))
    nimFwTrace2U32("[WIFI-NIMFW] txint_ptrs ",
                   cast[uint32](cast[uint](curCtxtTrace)),
                   cast[uint32](cast[uint](schedCtxtTrace)))
    nimFwTrace2U32("[WIFI-NIMFW] txint_vifct ",
                   cast[uint32](cast[uint](vifEntryTx)),
                   cast[uint32](cast[uint](vifCtxtTrace)))
    when defined(bl808WifiConnectTrace):
      nimFwConnectTrace2U32("[WIFI-CT] txint_enter ",
                            ac.uint32 or (vifIdxTx.uint32 shl 8) or
                              (cast[ptr uint8](descU + 49)[].uint32 shl 16),
                            txReady.uint32 or (onChanTrace.uint32 shl 8) or
                              (flagsTrace.uint32 shl 16) or (cntTrace.uint32 shl 24))
      nimFwConnectTrace2U32("[WIFI-CT] txint_ctxt ",
                            cast[uint32](cast[uint](curCtxtTrace)),
                            cast[uint32](cast[uint](vifCtxtTrace)))
  if txReady:
    # TX allowed: check AP PS state
    # Step 2: apm_tx_int_ps_check (blob 0x50)
    let psOk = apm_tx_int_ps_check(param)
    if traceMgmt:
      let chanBase = cast[uint](addr chan_env[0])
      let curCtxt = cast[ptr pointer](chanBase + 32)[]
      let pendCtxt = cast[ptr pointer](chanBase + 36)[]
      nimFwTrace2U32("[WIFI-NIMFW] txint_ready ",
                     txReady.uint32 or (psOk.uint32 shl 8),
                     cast[uint32](cast[uint](curCtxt) xor cast[uint](pendCtxt)))
      when defined(bl808WifiConnectTrace):
        nimFwConnectTrace2U32("[WIFI-CT] txint_ready ",
                              txReady.uint32 or (psOk.uint32 shl 8),
                              cast[uint32](cast[uint](curCtxt) xor cast[uint](pendCtxt)))
    if not psOk:
      # PS check failed: fall through to not-ready path
      discard
    else:
      # Success path: set rcStats flag, DMA transfer, push to queue
      if rcStatsPtr != nil:
        let rcU = cast[uint](rcStatsPtr)
        let flags = cast[ptr uint32](rcU + 60)[]
        cast[ptr uint32](rcU + 60)[] = flags or 0x100

      # IRQ-safe: fake transfer + push to AC queue
      let saved = irqSave()
      txl_int_fake_transfer(param, ac.uint32)
      let acOffset = ac.uint * 16 + 4
      let acQueue = cast[ptr CoList](envBase + acOffset)
      co_list_push_back(acQueue, cast[ptr CoListHdr](param))
      irqRestore(saved)

      # Increment packet counter
      let pktCnt = cast[ptr uint32](envBase + 80)[]
      cast[ptr uint32](envBase + 80)[] = pktCnt + 1

      # Payload backup (blob 0xA4)
      txl_payload_handle_backup(param)
      if traceMgmt:
        nimFwTrace2U32("[WIFI-NIMFW] txint_push ",
                       cast[ptr uint32](envBase + 80)[].uint32,
                       cast[uint32](cast[uint](cast[ptr pointer](descU + 112)[])))
        when defined(bl808WifiConnectTrace):
          nimFwConnectTrace2U32("[WIFI-CT] txint_push ",
                                cast[ptr uint32](envBase + 80)[].uint32,
                                cast[uint32](cast[uint](cast[ptr pointer](descU + 112)[])))
      return 1'u8

  # Not-ready path (L103): check STA for off-channel deferral
  let staInstNbr = cast[ptr uint8](descU + 49)[]
  if staInstNbr == 0xFF:
    if traceMgmt:
      nimFwTrace2U32("[WIFI-NIMFW] txint_release ",
                     txReady.uint32, staInstNbr.uint32)
      when defined(bl808WifiConnectTrace):
        nimFwConnectTrace2U32("[WIFI-CT] txint_release ",
                              txReady.uint32, staInstNbr.uint32)
    # No STA: release frame (blob: txl_frame_release at 0x42)
    # Blob: a0=param, a1=0 (no callback). txl_frame_release reads a1 via asm.
    {.emit: ["asm volatile(\"mv a1, zero\" ::: \"a1\");"].}
    txl_frame_release(param)
    return 0'u8

  # STA exists: defer TX to off-channel path
  cast[ptr uint8](descU + 217)[] = 1
  cast[ptr uint8](descU + 46)[] = ac
  let staEntry = staTabBase + staInstNbr.uint * STA_ENTRY_SIZE.uint
  if traceMgmt:
    nimFwTrace2U32("[WIFI-NIMFW] txint_postpone ",
                   txReady.uint32 or (staInstNbr.uint32 shl 8),
                   cast[uint32](staEntry))
    when defined(bl808WifiConnectTrace):
      nimFwConnectTrace2U32("[WIFI-CT] txint_postpone ",
                            txReady.uint32 or (staInstNbr.uint32 shl 8),
                            cast[uint32](staEntry))
  # Store MAC time if not already pending
  let txPending = cast[ptr uint32](descU + 84)[]
  if txPending == 0:
    cast[ptr uint32](descU + 84)[] = macTimeNow()
  # Push to STA pending list (blob: co_list_push_back at 0xE2)
  let staPendQueue = cast[ptr CoList](staEntry + 356)
  co_list_push_back(staPendQueue, cast[ptr CoListHdr](param))
  # Notify PS postpone (blob: apm_tx_int_ps_postpone at 0xEE)
  apm_tx_int_ps_postpone(param, cast[pointer](staEntry))
  # Increment frame env counter
  let frameEnvBase = cast[uint](addr txl_frame_env[0])
  let frmCnt = cast[ptr uint32](frameEnvBase + 16)[]
  cast[ptr uint32](frameEnvBase + 16)[] = frmCnt + 1
  return 1'u8

proc txl_cntrl_push_int_force*(param: pointer, ac: uint8): uint8 {.exportc, cdecl.} =
  ## Force push an internal frame to TX control (106 bytes in blob).
  ## Blob: set rcStats[60]|=0x100, irqSave, txl_int_fake_transfer,
  ## co_list_push_back, irqRestore, increment pktCnt, txl_payload_handle_backup.
  let descU = cast[uint](param)
  # Read RC stats from param[112] and set pending flag
  let rcStatsPtr = cast[ptr pointer](descU + 112)[]
  let rcU = cast[uint](rcStatsPtr)
  let flags = cast[ptr uint32](rcU + 60)[]
  cast[ptr uint32](rcU + 60)[] = flags or 0x100
  # IRQ save
  let saved = irqSave()
  # Fake DMA transfer setup (blob: txl_int_fake_transfer at 0x20)
  txl_int_fake_transfer(param, ac.uint32)
  # Push to AC queue
  let envBase = cast[uint](addr txl_cntrl_env[0])
  let acOffset = ac.uint * 16 + 4
  let acQueue = cast[ptr CoList](envBase + acOffset)
  co_list_push_back(acQueue, cast[ptr CoListHdr](param))
  # IRQ restore
  irqRestore(saved)
  # Increment packet counter
  let pktCnt = cast[ptr uint32](envBase + 80)[]
  cast[ptr uint32](envBase + 80)[] = pktCnt + 1
  # Handle TX backup/scheduling (blob: txl_payload_handle_backup at 0x52)
  txl_payload_handle_backup(param)
  return 1'u8

proc txl_cntrl_halt_ac*(ac: uint8) {.exportc, cdecl.} =
  ## Halt TX for a specific access category by writing to MAC HW TX trigger
  ## register (0x24B08180) with an AC-specific bitmask, then polling the
  ## status register (0x24B08188) until the AC's bits clear, and finally
  ## writing the clear bitmask to the clear register (0x24B08184).
  ## From disassembly (65 instrs).
  const
    MACHW_TX_TRIG_SET  = 0x24B08180'u  # TX trigger set register
    MACHW_TX_TRIG_STAT = 0x24B08188'u  # TX trigger status register
    MACHW_TX_TRIG_CLR  = 0x24B08184'u  # TX trigger clear register
  var setBit: uint32
  var clearMask: uint32
  case ac
  of 0:  # BK
    setBit = 0x10000'u32     # bit 16
    regWrite(MACHW_TX_TRIG_SET, setBit)
    while true:
      let stat = regRead(MACHW_TX_TRIG_STAT)
      if (stat and 0x10000) == 0: break  # extract bit 16
    clearMask = 0x10000'u32
  of 1:  # BE
    setBit = 0x20000'u32     # bit 17
    regWrite(MACHW_TX_TRIG_SET, setBit)
    while true:
      let stat = regRead(MACHW_TX_TRIG_STAT)
      if (stat and 0x20000) == 0: break
    clearMask = 0x20000'u32
  of 2:  # VI
    setBit = 0x40000'u32     # bit 18
    regWrite(MACHW_TX_TRIG_SET, setBit)
    while true:
      let stat = regRead(MACHW_TX_TRIG_STAT)
      if (stat and 0x40000) == 0: break
    clearMask = 0x40000'u32
  of 3:  # VO
    setBit = 0x80000'u32     # bit 19
    regWrite(MACHW_TX_TRIG_SET, setBit)
    while true:
      let stat = regRead(MACHW_TX_TRIG_STAT)
      if (stat and 0x80000) == 0: break
    clearMask = 0x80000'u32
  of 4:  # BCN
    setBit = 0x8000'u32      # bit 15
    regWrite(MACHW_TX_TRIG_SET, setBit)
    while true:
      let stat = regRead(MACHW_TX_TRIG_STAT)
      if (stat and 3) == 0: break  # bits [1:0]
    clearMask = 0x8000'u32
  else:
    assert_err("txl_cntrl.c", "txl_cntrl.c", 0x700)
    return
  regWrite(MACHW_TX_TRIG_CLR, clearMask)

proc txl_cntrl_flush_ac*(ac: uint8) {.exportc, cdecl.} =
  ## Flush TX queue for a specific AC (44 instrs in blob).
  ## From blob: reads MACHW active AC register (0x24B0808C), computes 1<<ac bitmask,
  ## then calls txl_cfm_flush twice (global txl_cfm_env + per-AC txl_cntrl_env list),
  ## then txl_buffer_reset. Finally clears the AC bit in active register and sets
  ## the AC mask register (offset 0x88).
  let saved = irqSave()
  let acMask = 1'u32 shl ac
  let envBase = cast[uint](addr txl_cntrl_env[0])
  let acList = cast[pointer](envBase + ac.uint * 16 + 4)
  let globalCfm = cast[pointer](addr txl_cfm_env[0])
  # First flush: global txl_cfm_env list.
  # Blob passes args via registers: a0=ac, a1=list, a2=acMask.
  {.emit: ["""
  {
    register unsigned int _a0 __asm__("a0") = (unsigned int)""", ac, """;
    register unsigned int _a1 __asm__("a1") = (unsigned int)""", globalCfm, """;
    register unsigned int _a2 __asm__("a2") = (unsigned int)""", acMask, """;
    __asm__ volatile("" : : "r"(_a0), "r"(_a1), "r"(_a2));
    txl_cfm_flush();
  }
  """].}
  # Second flush: per-AC list at txl_cntrl_env[ac*16+4].
  {.emit: ["""
  {
    register unsigned int _a0 __asm__("a0") = (unsigned int)""", ac, """;
    register unsigned int _a1 __asm__("a1") = (unsigned int)""", acList, """;
    register unsigned int _a2 __asm__("a2") = (unsigned int)""", acMask, """;
    __asm__ volatile("" : : "r"(_a0), "r"(_a1), "r"(_a2));
    txl_cfm_flush();
  }
  """].}
  # Reset TX buffer pool (blob: txl_buffer_reset with a0=ac).
  {.emit: ["""
  {
    register unsigned int _a0 __asm__("a0") = (unsigned int)""", ac, """;
    __asm__ volatile("" : : "r"(_a0));
    txl_buffer_reset();
  }
  """].}
  # Clear AC active bits in MACHW registers
  let activeAcReg = MACHW_INTC_BASE + 0x08C'u  # active AC bitmask register
  let setAcReg = MACHW_INTC_BASE + 0x088'u     # AC mask set register
  let curActive = regRead(activeAcReg)
  regWrite(activeAcReg, curActive and (not acMask))
  regWrite(setAcReg, acMask)
  irqRestore(saved)

proc txl_cntrl_clear_ac*(ac: uint8) {.exportc, cdecl.} =
  ## Clear TX queue for a specific AC.
  ## Blob (18 instrs): saves IRQ state (csrrci mstatus,8), calls
  ## txl_cntrl_halt_ac(ac), then txl_cntrl_flush_ac(ac), restores IRQ state.
  let saved = irqSave()
  txl_cntrl_halt_ac(ac)
  txl_cntrl_flush_ac(ac)
  irqRestore(saved)
  if ac < NUM_TX_QUEUES.uint8:
    txlAcPending[ac] = 0
    txlAcBusy[ac] = false

proc txl_cntrl_clear_bcn_ac*() {.exportc, cdecl.} =
  ## Clear beacon TX queue (18 instrs in blob).
  ## From blob: saves IRQ state (csrrci mstatus,8), calls txl_cntrl_halt_ac(4),
  ## then txl_cntrl_flush_ac(4) with 0x40000000 bitmask, restores IRQ state.
  let saved = irqSave()
  txl_cntrl_halt_ac(4)
  txl_cntrl_flush_ac(4)
  irqRestore(saved)

proc txl_cntrl_clear_all_ac*() {.exportc, cdecl.} =
  ## Clear all TX queues.
  ## From disassembly (46 instrs): saves IRQ state, then for each AC (4,0,1,2,3)
  ## calls txl_cntrl_halt_ac to stop MAC HW TX, then txl_cntrl_flush_ac to
  ## flush pending descriptors. Finally restores IRQ state.
  let saved = irqSave()
  # BCN queue first (AC 4), then data queues 0..3
  txl_cntrl_halt_ac(4)
  txl_cntrl_flush_ac(4)
  txl_cntrl_halt_ac(0)
  txl_cntrl_flush_ac(0)
  txl_cntrl_halt_ac(1)
  txl_cntrl_flush_ac(1)
  txl_cntrl_halt_ac(2)
  txl_cntrl_flush_ac(2)
  txl_cntrl_halt_ac(3)
  txl_cntrl_flush_ac(3)
  irqRestore(saved)

proc txl_cntrl_inc_pck_cnt*(ac: uint8) {.exportc, cdecl.} =
  ## Increment packet count for an AC.
  ## From blob (5 instrs): loads txl_cntrl_env word at offset 80 (packet count),
  ## increments by 1, stores back. AC arg is unused (global counter).
  let base = cast[uint](addr txl_cntrl_env[0])
  let pktCntPtr = cast[ptr uint32](base + 80)
  pktCntPtr[] = pktCntPtr[] + 1

proc txl_cntrl_env_dump*() {.exportc, cdecl, noinline.} =
  ## Dump TX control environment for debugging.
  ## From disassembly (265 instrs): iterates over 5 AC entries (stride 16) in
  ## txl_cntrl_env, calling the platform log function (g_bl_ops_funcs[204]) to
  ## print per-AC state: first descriptor pointer, list head, busy flag, HW
  ## descriptor address, and pending frame chain details including THD info.
  ##
  ## Register map: s0=g_bl_ops_funcs s4=per-AC base (stride 16)
  ##   s5=ac index  s2=format string  s3=list first ptr  s9=list head result
  ##   s7=THD pointer from desc[112]+40
  ##
  ## The function is purely diagnostic. It reads txl_cntrl_env per-AC structures
  ## and walks linked lists, printing frame descriptors and THD (Transmit Header
  ## Descriptor) fields via the log function.
  ## The blob calls g_bl_ops_funcs[204] (log function) with varying numbers
  ## of arguments (printf-style variadic). We use emit for the variadic calls.
  let logFuncPtr = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
  if logFuncPtr == nil: return

  # Helper: call the platform log function with printf-style variadic args.
  # The blob signature is: void log(int level, int sev, const char *file,
  #   int line, const char *fmt, ...);
  # We use a simple 2-arg form for most calls (level=2, sev=0, fmt, line).
  type LogFn2 = proc(level: uint32, sev: uint32, file: cstring, line: uint32) {.cdecl.}
  type LogFn5 = proc(level: uint32, sev: uint32, file: cstring, line: uint32,
                     fmt: cstring, a0: uint32) {.cdecl.}
  type LogFn7 = proc(level: uint32, sev: uint32, file: cstring, line: uint32,
                     fmt: cstring, a0: uint32, a1: uint32, a2: uint32) {.cdecl.}

  let logFn = cast[LogFn2](logFuncPtr)
  let logFn5 = cast[LogFn5](logFuncPtr)
  let logFn7 = cast[LogFn7](logFuncPtr)
  let printFn = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 4)[]

  let base = cast[uint](addr txl_cntrl_env[0])

  # Print header
  logFn(2, 0, "txl_cntrl.c", 0x925)

  for ac in 0'u32 ..< NUM_TX_QUEUES.uint32:
    let acBase = base + ac * 16
    let firstDesc = cast[ptr uint32](acBase)[]
    let listFirst = cast[ptr pointer](acBase + 4)[]

    # Blob: s4 = &txl_cntrl_env+4+16*ac (the CoList in that AC slot).
    # At .L167 blob calls co_list_cnt(s4) and feeds result to log.
    let listPtrForCnt = cast[ptr CoList](acBase + 4)
    let listCnt = co_list_cnt(listPtrForCnt)

    # Log per-AC summary (line 0x92C) with (ac, head, cnt)
    logFn7(2, 0, "txl_cntrl.c", 0x92C, "AC", ac,
           cast[uint32](cast[uint](listFirst)), listCnt)

    # Log separator for empty list (blob: line 0x931)
    logFn(2, 0, "txl_cntrl.c", 0x931)

    # Walk descriptor chain (L162 in blob: while s3 != nil)
    var curDesc = listFirst
    while curDesc != nil:
      let curU = cast[uint](curDesc)
      # Print descriptor address and its status (blob: L165)
      let thd = cast[ptr pointer](curU + 112)[]
      if thd != nil:
        let thdU = cast[uint](thd)
        let thdStatus = cast[ptr uint32](thdU + 64)[]
        logFn7(2, 0, "txl_cntrl.c", 0x8EF, "thd",
               cast[uint32](thd), thdStatus, cast[uint32](curDesc))
      curDesc = cast[ptr pointer](curU)[]  # next in list

    # Log separator after list walk (blob: line 0x939)
    logFn(2, 0, "txl_cntrl.c", 0x939)

    # Walk the same list again for detailed THD sub-fields (L169/L174)
    curDesc = listFirst
    while curDesc != nil:
      let curU = cast[uint](curDesc)
      let thd = cast[ptr pointer](curU + 112)[]
      if thd != nil:
        let thdU = cast[uint](thd)

        # Print THD header: desc ptr, desc[4] status, thd ptr (blob: L174, line 0x8EF)
        let descW4 = cast[ptr uint32](curU + 4)[]
        logFn7(2, 0, "txl_cntrl.c", 0x8EF, "desc",
               cast[uint32](curDesc), descW4, cast[uint32](thd))

        # Print THD sub-fields: [28]=dataLen, [56]/[60]=rate, [40]=rateThd
        # Blob (L174, offset 0x184): reads thd[112] fields and prints
        let thdDataLen = cast[ptr uint32](thdU + 28)[]
        let thdW56 = cast[ptr uint32](thdU + 56)[]
        let thdW60 = cast[ptr uint32](thdU + 60)[]
        logFn7(2, 0, "txl_cntrl.c", 0x8F0, "thd_detail",
               thdDataLen, thdW56, thdW60)

        # Walk sub-descriptor chain at THD+40 (rate control descriptor)
        let rateThdPtr = cast[ptr pointer](thdU + 40)[]
        if rateThdPtr != nil:
          let rThdU = cast[uint](rateThdPtr)
          # Print rate descriptor summary (blob: L174 offset 0x1B4)
          # Fields: [0], [4], [8], [12], [16] (5 words)
          let rW0 = cast[ptr uint32](rThdU + 0)[]
          let rW4 = cast[ptr uint32](rThdU + 4)[]
          let rW8 = cast[ptr uint32](rThdU + 8)[]
          logFn7(2, 0, "txl_cntrl.c", 0x8FB, "rate",
                 rW0, rW4, rW8)
          let rW12 = cast[ptr uint32](rThdU + 12)[]
          let rW16 = cast[ptr uint32](rThdU + 16)[]
          logFn5(2, 0, "txl_cntrl.c", 0x903, "rate2", rW12)

          # Print rate policy table entries (4 entries at offsets 20..35)
          # Blob: loop at L170 (offset 0x20E), stride 4, 4 iterations
          for i in 0'u32 ..< 4:
            let polAddr = rThdU + 20 + i.uint * 4
            let polVal = cast[ptr uint32](polAddr)[]
            if printFn != nil:
              let fn = cast[proc(fmt: cstring, arg: pointer) {.cdecl.}](printFn)
              fn("pol", cast[pointer](polVal))

          # Print rate policy second table (blob: line 0x907/0x908)
          logFn(2, 0, "txl_cntrl.c", 0x907)
          logFn(2, 0, "txl_cntrl.c", 0x908)

          # Print rate policy table entries (4 entries at offsets 36..51)
          # Blob: loop at L171 (offset 0x25E), stride 4, 4 iterations
          for i in 0'u32 ..< 4:
            let polAddr = rThdU + 36 + i.uint * 4
            let polVal = cast[ptr uint32](polAddr)[]
            if printFn != nil:
              let fn = cast[proc(fmt: cstring, arg: pointer) {.cdecl.}](printFn)
              fn("pol2", cast[pointer](polVal))

          # Print rate descriptor chain footer (blob: line 0x90C)
          logFn(2, 0, "txl_cntrl.c", 0x90C)

          # Walk next rate descriptor at rThd[16] (blob: L172, offset 0x298)
          var nextRateThd = cast[ptr pointer](rThdU + 16)[]
          var rateIdx: uint32 = 0
          while nextRateThd != nil and rateIdx < 4:
            let nrU = cast[uint](nextRateThd)
            logFn5(2, 0, "txl_cntrl.c", 0x90E, "rchain", rateIdx)
            nextRateThd = cast[ptr pointer](nrU + 16)[]
            rateIdx += 1

        # Walk buffer descriptor chain at THD[16] (next pointer)
        var subDesc = cast[ptr pointer](thdU + 16)[]
        var subIdx: uint32 = 0
        while subDesc != nil:
          let subU = cast[uint](subDesc)
          let subW0 = cast[ptr uint32](subU + 0)[]
          let subW1 = cast[ptr uint32](subU + 4)[]
          let subW2 = cast[ptr uint32](subU + 8)[]
          logFn7(2, 0, "txl_cntrl.c", 0x911, "buf",
                 subIdx, subW0, subW1)
          subDesc = cast[ptr pointer](subU + 4)[]  # next buf desc
          inc subIdx

      curDesc = cast[ptr pointer](curU)[]  # next in list

{.emit: "__attribute__((optimize(\"crossjumping\"))) void txl_payload_handle_backup(void*);".}
proc txl_payload_handle_backup*(param: pointer) {.exportc, cdecl.} =
  ## TX payload backup handler.
  ## Iterates over 5 AC entries in txl_cntrl_env (stride 8 for backup at
  ## offset +180, stride 16 for control base). For each AC, walks the pending
  ## backup descriptor chain and re-queues to HW:
  ##   - Gate: all beacon/machdr/tkip/thd work only if actualDesc[8] != nil
  ##   - For AC==4 (BCN): updates vif_info_tab protection flags
  ##   - If sta_idx == 0xFF: calls txl_machdr_format on the MAC header
  ##   - Calls txu_cntrl_tkip_mic_append for TKIP MIC append
  ##   - Patches THD rate/policy fields from link descriptor
  ##   - Links THD+4 into per-AC HW queue
  ##   - On first desc into empty HW queue: assert DMA status, program link
  ##     register, call blmac_abs_timer_set, set AGG bits
  ##   - On subsequent descs (non-empty queue): just write trigger register
  ##
  ## Call graph: assert_rec, blmac_abs_timer_set, txl_machdr_format,
  ##             txu_cntrl_tkip_mic_append
  let cntrlBase = cast[uint](addr txl_cntrl_env[0])
  let bufferEnvBase = cast[uint](addr txl_buffer_env[0])
  const
    HW_TRIGGER_REG = 0x24B08180'u      # MAC HW TX trigger
    HW_AGG_SET_REG = 0x24B08088'u      # MAC HW aggregation set
    HW_AGG_OR_REG  = 0x24B0808C'u      # MAC HW aggregation OR

  let vifBase = cast[uint](addr vif_info_tab[0])

  template txlDmaStatusField(status: uint32, acIdx: uint32): uint32 =
    ## Vendor uses T-Head bit-extracts here:
    ## AC0=[5:4], AC1=[9:8], AC2=[13:12], AC3=[17:16], AC4=[1:0].
    case acIdx
    of 0'u32:
      (status shr 4) and 3'u32
    of 1'u32:
      (status shr 8) and 3'u32
    of 2'u32:
      (status shr 12) and 3'u32
    of 3'u32:
      (status shr 16) and 3'u32
    of 4'u32:
      status and 3'u32
    else:
      0'u32

  for ac in 0'u32 ..< NUM_TX_QUEUES.uint32:
    let acCtrlBase = cntrlBase + ac * 16
    let acBackupBase = bufferEnvBase + (ac + 22'u32) * 8'u32
    var descPtr = cast[ptr pointer](acBackupBase + 4)[]

    if descPtr == nil:
      continue

    let acBit = 1'u32 shl ac

    while descPtr != nil:
      let descU = cast[uint](descPtr)
      let nextDesc = cast[ptr pointer](descU + 16)[]  # next in backup chain

      # Store next as new backup head
      cast[ptr pointer](acBackupBase + 4)[] = nextDesc

      # Dereference desc[20] to get the actual TX descriptor (blob: s0 = a0[20])
      let actualDesc = cast[ptr pointer](descU + 20)[]
      let actualU = cast[uint](actualDesc)
      let fcTrace = cast[ptr uint8](descU + 348)[]
      let traceMgmt = nimFwMgmtFcTrace(fcTrace)
      let protoTrace =
        if actualDesc != nil: cast[ptr uint16](actualU + 32)[]
      else: 0'u16
      let traceEapol = protoTrace == 0x8E88'u16 or protoTrace == 0x888E'u16

      # Gate: only do beacon/machdr/tkip/thd patching if actualDesc[8] != nil
      let hasPayload = cast[ptr pointer](actualU + 8)[]
      if traceMgmt:
        nimFwTrace2U32("[WIFI-NIMFW] pay_enter ",
                       ac or ((if hasPayload != nil: 1'u32 else: 0'u32) shl 8),
                       cast[uint32](actualU))
        when defined(bl808WifiConnectTrace):
          nimFwConnectTrace2U32("[WIFI-CT] pay_enter ",
                                ac or ((if hasPayload != nil: 1'u32 else: 0'u32) shl 8),
                                cast[uint32](actualU))
      if traceEapol:
        let hdrBaseTrace = descU + 348
        nimFwTrace2U32("[WIFI-NIMFW] pay_eapol ",
                       ac or ((if hasPayload != nil: 1'u32 else: 0'u32) shl 8),
                       cast[uint32](actualU))
        nimFwTrace2U32("[WIFI-NIMFW] pay_eapol_hdr ",
                       cast[ptr uint32](hdrBaseTrace)[],
                       cast[ptr uint32](hdrBaseTrace + 24)[])
        when defined(bl808WifiConnectTrace):
          if nimFwDbgEapolTraceCount < 64'u32:
            nimFwConnectTrace2U32("[WIFI-CT] pay_eapol ",
                                  ac or ((if hasPayload != nil: 1'u32 else: 0'u32) shl 8) or
                                    (nimFwDbgEapolTraceCount shl 16),
                                  cast[uint32](actualU))
            nimFwConnectTrace2U32("[WIFI-CT] pay_eapol_hdr ",
                                  cast[ptr uint32](hdrBaseTrace)[],
                                  cast[ptr uint32](hdrBaseTrace + 24)[])
      when declared(NimFwForcedMgmtTxPower):
        let fcForce = cast[ptr uint16](descU + 348)[]
        if ((fcForce.uint32 shr 2) and 3'u32) == 0'u32:
          let forceLink = cast[ptr pointer](actualU + 108)[]
          if forceLink != nil:
            let forceLinkU = cast[uint](forceLink)
            cast[ptr uint32](forceLinkU + 292)[] = NimFwForcedMgmtTxPower
            cast[ptr uint32](forceLinkU + 296)[] = NimFwForcedMgmtTxPower
            cast[ptr uint32](forceLinkU + 300)[] = NimFwForcedMgmtTxPower
            cast[ptr uint32](forceLinkU + 304)[] = NimFwForcedMgmtTxPower
      if hasPayload != nil:
        # For AC==4 (BCN), special beacon handling
        if ac == 4:
          let vifIdx = cast[ptr uint8](actualU + 47)[]  # blob: lbu a3,47(s0)
          let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
          let protFlags = cast[ptr uint8](vifEntry + 330)[]
          let isProtected = cast[ptr uint8](descU + 349)[]  # blob: lbu a3,349(a0)
          if isProtected != 0:
            cast[ptr uint8](vifEntry + 330)[] = protFlags or 2
          else:
            cast[ptr uint8](vifEntry + 330)[] = protFlags and not 2'u8

        # If sta_idx == 0xFF, format MAC header (blob calls txl_machdr_format)
        let staIdx = cast[ptr uint8](actualU + 46)[]  # blob: lbu a4,46(s0)
        if staIdx == 0xFF:
          txl_machdr_format(cast[pointer](descU + 348))

        # Save link descriptor across call, read THD (s11), call txu_cntrl_tkip_mic_append
        let linkDesc = cast[ptr pointer](actualU + 108)[]
        let thdPtr = cast[ptr pointer](actualU + 112)[]  # saved as s11 across call
        txu_cntrl_tkip_mic_append(actualDesc)

        # Patch THD fields from link descriptor's rate/policy info (unconditional)
        let linkU = cast[uint](linkDesc)
        let thdU = cast[uint](thdPtr)
        cast[ptr uint32](thdU + 56)[] = cast[ptr uint32](linkU + 308)[]  # thd[56] = linkDesc[308]
        cast[ptr pointer](thdU + 40)[] = cast[pointer](linkU + 256)      # thd[40] = linkDesc + 256
        cast[ptr uint32](thdU + 36)[] = cast[ptr uint32](linkU + 312)[]  # thd[36] = linkDesc[312]
        if traceMgmt or traceEapol:
          nimFwTrace2U32("[WIFI-NIMFW] pay_rate ",
                         cast[ptr uint32](linkU + 308)[],
                         cast[ptr uint32](linkU + 312)[])
          if traceMgmt:
            when defined(bl808WifiConnectTrace):
              nimFwConnectTrace2U32("[WIFI-CT] pay_rate ",
                                    cast[ptr uint32](linkU + 308)[],
                                    cast[ptr uint32](linkU + 312)[])

      # Increment per-AC packet counter at acCtrlBase+12 (half-word)
      let pktCnt = cast[ptr uint16](acCtrlBase + 12)[]
      cast[ptr uint16](acCtrlBase + 12)[] = pktCnt + 1

      # Get THD+4 for linking (blob re-reads actualDesc[112] here at .L60)
      let thdForLink = cast[uint](cast[ptr pointer](actualU + 112)[])
      let thdLink = cast[pointer](thdForLink + 4)

      # Check if per-AC HW queue list is empty
      let listFirst = cast[ptr pointer](acCtrlBase)[]
      if traceMgmt or traceEapol:
        let thdStatusBefore = cast[ptr uint32](thdForLink + 64)[]
        nimFwTrace2U32("[WIFI-NIMFW] pay_link ",
                       ac or ((if listFirst == nil: 1'u32 else: 0'u32) shl 8),
                       cast[uint32](thdLink) xor thdStatusBefore)
        if traceMgmt:
          when defined(bl808WifiConnectTrace):
            nimFwConnectTrace2U32("[WIFI-CT] pay_link ",
                                  ac or ((if listFirst == nil: 1'u32 else: 0'u32) shl 8),
                                  cast[uint32](thdLink) xor thdStatusBefore)
            let linkUTrace = cast[uint](cast[ptr pointer](actualU + 108)[])
            nimFwConnectTrace2U32("[WIFI-CT] pay_hw0 ",
                                  cast[ptr uint32](thdForLink + 24)[],
                                  cast[ptr uint32](thdForLink + 28)[])
            nimFwConnectTrace2U32("[WIFI-CT] pay_hw1 ",
                                  cast[ptr uint32](thdForLink + 36)[],
                                  cast[ptr uint32](thdForLink + 40)[])
            nimFwConnectTrace2U32("[WIFI-CT] pay_hw2 ",
                                  cast[ptr uint32](thdForLink + 56)[],
                                  cast[ptr uint32](thdForLink + 60)[])
            nimFwConnectTrace2U32("[WIFI-CT] pay_pol0 ",
                                  cast[ptr uint32](linkUTrace + 256)[],
                                  cast[ptr uint32](linkUTrace + 260)[])
            nimFwConnectTrace2U32("[WIFI-CT] pay_pol1 ",
                                  cast[ptr uint32](linkUTrace + 272)[],
                                  cast[ptr uint32](linkUTrace + 276)[])
            nimFwConnectTrace2U32("[WIFI-CT] pay_pol2 ",
                                  cast[ptr uint32](linkUTrace + 288)[],
                                  cast[ptr uint32](linkUTrace + 292)[])
            nimFwConnectTrace2U32("[WIFI-CT] pay_pol3 ",
                                  cast[ptr uint32](linkUTrace + 296)[],
                                  cast[ptr uint32](linkUTrace + 300)[])
            nimFwConnectTrace2U32("[WIFI-CT] pay_pol4 ",
                                  cast[ptr uint32](linkUTrace + 304)[],
                                  cast[ptr uint32](linkUTrace + 308)[])
        if traceEapol:
          let linkU = cast[uint](cast[ptr pointer](actualU + 108)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_desc0 ",
                         cast[ptr uint32](actualU + 8)[],
                         cast[ptr uint32](actualU + 12)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_desc1 ",
                         cast[ptr uint32](actualU + 52)[],
                         cast[ptr uint32](actualU + 68)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_link0 ",
                         cast[ptr uint32](linkU + 72)[],
                         cast[ptr uint32](linkU + 76)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_link1 ",
                         cast[ptr uint32](linkU + 80)[],
                         cast[ptr uint32](linkU + 84)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_hw0 ",
                         cast[ptr uint32](thdForLink + 4)[],
                         cast[ptr uint32](thdForLink + 8)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_hw1 ",
                         cast[ptr uint32](thdForLink + 12)[],
                         cast[ptr uint32](thdForLink + 16)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_hw2 ",
                         cast[ptr uint32](thdForLink + 28)[],
                         cast[ptr uint32](thdForLink + 36)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_hw3 ",
                         cast[ptr uint32](thdForLink + 40)[],
                         cast[ptr uint32](thdForLink + 56)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_hw4 ",
                         cast[ptr uint32](thdForLink + 60)[],
                         cast[ptr uint32](thdForLink + 64)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_buf0 ",
                         cast[ptr uint32](linkU + 92)[],
                         cast[ptr uint32](linkU + 96)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_buf1 ",
                         cast[ptr uint32](linkU + 100)[],
                         cast[ptr uint32](linkU + 104)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_pol0 ",
                         cast[ptr uint32](linkU + 256)[],
                         cast[ptr uint32](linkU + 260)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_pol1 ",
                         cast[ptr uint32](linkU + 264)[],
                         cast[ptr uint32](linkU + 268)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_pol2 ",
                         cast[ptr uint32](linkU + 272)[],
                         cast[ptr uint32](linkU + 276)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_pol3 ",
                         cast[ptr uint32](linkU + 280)[],
                         cast[ptr uint32](linkU + 284)[])
          nimFwTrace2U32("[WIFI-NIMFW] pay_pol4 ",
                         cast[ptr uint32](linkU + 288)[],
                         cast[ptr uint32](linkU + 292)[])
          when defined(bl808WifiConnectTrace):
            if nimFwDbgEapolTraceCount < 64'u32:
              nimFwConnectTrace2U32("[WIFI-CT] pay_desc0 ",
                                    cast[ptr uint32](actualU + 8)[],
                                    cast[ptr uint32](actualU + 12)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_desc1 ",
                                    cast[ptr uint32](actualU + 52)[],
                                    cast[ptr uint32](actualU + 68)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_link0 ",
                                    cast[ptr uint32](linkU + 72)[],
                                    cast[ptr uint32](linkU + 76)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_link1 ",
                                    cast[ptr uint32](linkU + 80)[],
                                    cast[ptr uint32](linkU + 84)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_hw0 ",
                                    cast[ptr uint32](thdForLink + 4)[],
                                    cast[ptr uint32](thdForLink + 8)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_hw1 ",
                                    cast[ptr uint32](thdForLink + 12)[],
                                    cast[ptr uint32](thdForLink + 16)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_hw2 ",
                                    cast[ptr uint32](thdForLink + 28)[],
                                    cast[ptr uint32](thdForLink + 36)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_hw3 ",
                                    cast[ptr uint32](thdForLink + 40)[],
                                    cast[ptr uint32](thdForLink + 56)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_hw4 ",
                                    cast[ptr uint32](thdForLink + 60)[],
                                    cast[ptr uint32](thdForLink + 64)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_buf0 ",
                                    cast[ptr uint32](linkU + 92)[],
                                    cast[ptr uint32](linkU + 96)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_buf1 ",
                                    cast[ptr uint32](linkU + 100)[],
                                    cast[ptr uint32](linkU + 104)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_pol0 ",
                                    cast[ptr uint32](linkU + 256)[],
                                    cast[ptr uint32](linkU + 260)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_pol1 ",
                                    cast[ptr uint32](linkU + 264)[],
                                    cast[ptr uint32](linkU + 268)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_pol2 ",
                                    cast[ptr uint32](linkU + 272)[],
                                    cast[ptr uint32](linkU + 276)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_pol3 ",
                                    cast[ptr uint32](linkU + 280)[],
                                    cast[ptr uint32](linkU + 284)[])
              nimFwConnectTrace2U32("[WIFI-CT] pay_pol4 ",
                                    cast[ptr uint32](linkU + 288)[],
                                    cast[ptr uint32](linkU + 292)[])
              nimFwDbgEapolTraceCount = nimFwDbgEapolTraceCount + 1
      if listFirst == nil:
        # Empty list path (.L64): read ipc_shared_env TX timer base from 0x24B00120,
        # check DMA status, program link register, call blmac_abs_timer_set, set AGG bits.
        # Timer constants: s6=200000, s7=50000, s8=2000000, AC2=400000.
        # Blob tail-merges the 5 per-AC assert_rec calls into one common
        # site — hoist the DMA status check out of the per-AC branches.
        let ipcSharedBase = cast[ptr uint32](0x24B00120'u)[]
        let dmaStatus = regRead(0x24B08188'u)
        let dmaField = txlDmaStatusField(dmaStatus, ac)
        var assertLine: cint = 0
        var timerVal: uint32
        case ac
        of 0:
          assertLine = 539
          timerVal = ipcSharedBase + 200000'u32
        of 1:
          assertLine = 533
          timerVal = ipcSharedBase + 2000000'u32
        of 2:
          assertLine = 527
          timerVal = ipcSharedBase + 400000'u32
        of 3:
          assertLine = 521
          timerVal = ipcSharedBase + 200000'u32
        of 4:
          assertLine = 514
          timerVal = ipcSharedBase + 50000'u32
        else:
          timerVal = 0
        if traceMgmt or traceEapol:
          nimFwTrace2U32("[WIFI-NIMFW] pay_dma ",
                         ac or (dmaField shl 8),
                         dmaStatus)
          if traceMgmt:
            when defined(bl808WifiConnectTrace):
              nimFwConnectTrace2U32("[WIFI-CT] pay_dma ",
                                    ac or (dmaField shl 8),
                                    dmaStatus)
        if assertLine != 0 and dmaField == 2:
          assert_rec("txl_payload.c", "txl_payload.c", assertLine)
        else:
          case ac
          of 0:
            regWrite(0x24B0819C'u, cast[uint32](thdLink))
            regWrite(HW_TRIGGER_REG, 512)
          of 1:
            regWrite(0x24B081A0'u, cast[uint32](thdLink))
            regWrite(HW_TRIGGER_REG, 1024)
          of 2:
            regWrite(0x24B081A4'u, cast[uint32](thdLink))
            regWrite(HW_TRIGGER_REG, 2048)
          of 3:
            regWrite(0x24B081A8'u, cast[uint32](thdLink))
            regWrite(HW_TRIGGER_REG, 4096)
          of 4:
            regWrite(0x24B08198'u, cast[uint32](thdLink))
            regWrite(HW_TRIGGER_REG, 256)
          else:
            discard
          blmac_abs_timer_set(ac, timerVal)
          # Set HW aggregation bits
          regWrite(HW_AGG_SET_REG, acBit)
          let aggOr = regRead(HW_AGG_OR_REG)
          regWrite(HW_AGG_OR_REG, acBit or aggOr)
          if traceMgmt or traceEapol:
            nimFwTrace2U32("[WIFI-NIMFW] pay_regs ",
                           regRead(0x24B08078'u),
                           regRead(0x24B0808C'u))
            if traceMgmt:
              when defined(bl808WifiConnectTrace):
                nimFwConnectTrace2U32("[WIFI-CT] pay_regs ",
                                      regRead(0x24B08078'u),
                                      regRead(0x24B0808C'u))
      else:
        # Non-empty list: link into existing chain and write trigger
        cast[ptr pointer](cast[uint](listFirst) + 4)[] = thdLink
        var triggerVal: uint32
        case ac
        of 3: triggerVal = 16
        of 4: triggerVal = 1
        of 2: triggerVal = 8
        of 1: triggerVal = 4
        else: triggerVal = 2    # AC0
        regWrite(HW_TRIGGER_REG, triggerVal)
        if traceMgmt or traceEapol:
          nimFwTrace2U32("[WIFI-NIMFW] pay_regs ",
                         regRead(0x24B08078'u),
                         regRead(0x24B0808C'u))
          if traceMgmt:
            when defined(bl808WifiConnectTrace):
              nimFwConnectTrace2U32("[WIFI-CT] pay_regs ",
                                    regRead(0x24B08078'u),
                                    regRead(0x24B0808C'u))

      # Update list head
      cast[ptr pointer](acCtrlBase)[] = thdLink

      # Advance to next descriptor in backup chain (.L70 re-reads backup head)
      descPtr = cast[ptr pointer](acBackupBase + 4)[]
      if descPtr != nil:
        cast[ptr pointer](acBackupBase + 4)[] = cast[ptr pointer](cast[uint](descPtr) + 16)[]

proc txl_transmit_trigger*() {.exportc, cdecl.} =
  ## Trigger TX DMA transmission for the highest-priority ready AC.
  ## Reads MACHW INTC status to find the highest-priority AC with a pending
  ## descriptor, reads its THD, programs MAC HW DMA, and handles chaining.
  ## From disassembly (122 instrs).
  ##
  ## Blob flow:
  ##   1. Read TX status reg 0x24B08078, mask bits [10:6]
  ##   2. CLZ to find highest-priority AC (ac = 25 - CLZ)
  ##   3. Process ONLY that single AC per invocation
  ##   4. Loop within that AC's descriptor chain until THD not ready
  ##   5. For each ready THD: program DMA, handle secondary chain
  ##   6. Tail-call hal_machw_trigger_set(ac, ipc_base + offset) to start TX
  const
    MACHW_TX_STATUS_REG = 0x24B08078'u  # TX status with AC ready bits
    MACHW_TX_TRIG_STAT  = 0x24B0808C'u
    IPC_SHARED_TX_BASE  = 0x24B00120'u
    TX_TIMEOUT_LOCAL    = [200000'u32, 2000000'u32, 400000'u32, 200000'u32, 50000'u32]

  # Check MAC HW TX status - bits [10:6] indicate AC readiness
  let txStatus = regRead(MACHW_TX_STATUS_REG)
  let acReady = txStatus and 0x7C0'u32  # bits [10:6]
  if acReady == 0:
    return  # No ACs ready for transmission

  # Compute highest-priority AC from CLZ: s0 = 25 - CLZ(acReady)
  var clzResult: cint
  {.emit: [clzResult, " = __builtin_clz((unsigned int)", acReady, ");"].}
  # Blob keeps an assert_err for `ac > 4`. Under upstream GCC -Os the
  # compiler knows `acReady` has bits only in [10:6] so `ac` is always
  # ≤4 and elides the check. Use a volatile to defeat the range analysis.
  var acV {.volatile.}: uint32 = 25'u32 - clzResult.uint32
  let ac = acV
  if ac > 4:
    assert_err("txl_cntrl.c", "txl_cntrl.c", 0x86C)

  # Set up masks: acBit = 1 << ac, clearMask = ~(1 << ac)
  let clearMask = not (1'u32 shl ac)

  # Store the AC readiness bit to INTC trigger register for HW readback
  let readyBit = 1'u32 shl (ac + 6)
  regWrite(0x24B0807C'u, readyBit)

  # txl_cntrl_env is indexed as: base + ac*16
  let cntrlBase = cast[uint](addr txl_cntrl_env[0])
  let acBase = cntrlBase + ac * 16

  # Main loop (.L137): process descriptors for this AC
  while true:
    let descPtr = cast[ptr pointer](acBase + 4)[]
    if descPtr == nil:
      # No descriptor (.L130): clear AC bit in INTC status, clear cntrl_env[0]
      let intcStat = regRead(MACHW_TX_TRIG_STAT)
      cast[ptr uint32](acBase)[] = 0
      regWrite(MACHW_TX_TRIG_STAT, intcStat and clearMask)
      return

    # Read THD from descriptor at offset 112
    let descAddr = cast[uint](descPtr)
    let linkPtrTrace = cast[ptr pointer](descAddr + 108)[]
    let linkUTrace = cast[uint](linkPtrTrace)
    let fcTrace = if linkPtrTrace != nil: cast[ptr uint8](linkUTrace + 348)[] else: 0'u8
    let traceMgmt = linkPtrTrace != nil and nimFwMgmtFcTrace(fcTrace)
    let protoTrace = cast[ptr uint16](descAddr + 32)[]
    let traceEapol = protoTrace == 0x8E88'u16 or protoTrace == 0x888E'u16
    let thdPtr = cast[ptr pointer](descAddr + 112)[]
    let thdAddr = cast[uint](thdPtr)
    let thdStatus = cast[ptr int32](thdAddr + 64)[]
    if traceMgmt or traceEapol:
      nimFwTrace2U32("[WIFI-NIMFW] txtrig_desc ",
                     ac.uint32 or (txStatus shl 8),
                     cast[uint32](thdStatus))
      if traceMgmt:
        when defined(bl808WifiConnectTrace):
          nimFwConnectTrace2U32("[WIFI-CT] txtrig_desc ",
                                ac.uint32 or (txStatus shl 8),
                                cast[uint32](thdStatus))
    if thdStatus >= 0:
      return  # THD not ready (bit 31 clear) -- .L126

    # Check for chained descriptors at desc[8] and desc[108]
    let nextDesc = cast[ptr pointer](descAddr + 8)[]
    if nextDesc != nil:
      let chainedThd = cast[ptr pointer](descAddr + 108)[]
      if chainedThd != nil:
        cast[ptr pointer](descAddr + 108)[] = nil

    # Program DMA: THD[0] -> head register, write thdStatus to head[16]
    let dmaHead = cast[uint](cast[ptr uint32](thdAddr)[])
    if traceMgmt or traceEapol:
      nimFwTrace2U32("[WIFI-NIMFW] txtrig_dma ",
                     cast[uint32](dmaHead),
                     cast[uint32](thdAddr))
      if traceMgmt:
        when defined(bl808WifiConnectTrace):
          nimFwConnectTrace2U32("[WIFI-CT] txtrig_dma ",
                                cast[uint32](dmaHead),
                                cast[uint32](thdAddr))
    cast[ptr uint32](dmaHead + 16)[] = thdStatus.uint32

    # Check secondary THD chain at THD+8
    let secThd = cast[ptr pointer](thdAddr + 8)[]
    if secThd == nil:
      # No secondary chain (.L133): clear AC bit in INTC status
      let intcStat = regRead(MACHW_TX_TRIG_STAT)
      cast[ptr uint32](acBase)[] = 0
      regWrite(MACHW_TX_TRIG_STAT, intcStat and clearMask)
      # Fall through to .L134 path
    else:
      let secStatus = cast[ptr int32](cast[uint](secThd) + 60)[]
      if secStatus >= 0:
        # Secondary THD not ready to pop: vendor rearms the AC timeout only.
        let ipcBase = regRead(IPC_SHARED_TX_BASE)
        blmac_abs_timer_set(ac, ipcBase + TX_TIMEOUT_LOCAL[ac])
        return
      # secStatus < 0: fall through to pop path (.L134)

    # .L134: Pop descriptor from list and process confirmation
    discard co_list_pop_front(cast[ptr CoList](acBase + 4))

    let hostCfm = cast[ptr pointer](descAddr + 8)[]
    when defined(bl808WifiNimFw):
      let fenvPtrTrace = cast[ptr pointer](descAddr + HostTxHwDescOff)[]
      var cfmHeadTrace = 0'u32
      if fenvPtrTrace != nil:
        cfmHeadTrace = cast[ptr uint32](cast[uint](fenvPtrTrace))[]
      let traceBadCfm = cfmHeadTrace == 0xBADCAB1E'u32
      let traceRoutedHost = hostCfm != nil
      if traceBadCfm or traceRoutedHost or traceMgmt or traceEapol:
        nimFwTrace2U32("[WIFI-NIMFW] txtrig_route ",
                       ac.uint32 or ((if traceRoutedHost: 1'u32 else: 0'u32) shl 8),
                       cast[uint32](descAddr))
        nimFwTrace2U32("[WIFI-NIMFW] txtrig_cfm ",
                       cast[uint32](cast[uint](fenvPtrTrace)),
                       cfmHeadTrace)
        nimFwTrace2U32("[WIFI-NIMFW] txtrig_link ",
                       cast[ptr uint32](descAddr + 8)[],
                       cast[ptr uint32](descAddr + HostTxBufDescOff)[])
        when defined(bl808WifiConnectTrace):
          nimFwConnectTrace2U32("[WIFI-CT] txtrig_route ",
                                ac.uint32 or ((if traceRoutedHost: 1'u32 else: 0'u32) shl 8),
                                cast[uint32](descAddr))
          nimFwConnectTrace2U32("[WIFI-CT] txtrig_cfm ",
                                cast[uint32](cast[uint](fenvPtrTrace)),
                                cfmHeadTrace)
          nimFwConnectTrace2U32("[WIFI-CT] txtrig_link ",
                                cast[ptr uint32](descAddr + 8)[],
                                cast[ptr uint32](descAddr + HostTxBufDescOff)[])
    if hostCfm == nil:
      # Internal management frame: frame-confirm event only.
      txl_frame_cfm(descPtr)
    else:
      # Host/data TX descriptor: route through the AC confirmation queue.
      txl_cfm_push(descPtr, thdStatus.uint32, ac.uint32)

    # Set absolute timer for next TX opportunity and loop to check for more descriptors.
    let ipcBase = regRead(IPC_SHARED_TX_BASE)
    blmac_abs_timer_set(ac, ipcBase + TX_TIMEOUT_LOCAL[ac])
    continue

proc txl_current_desc_get*(ac: uint8): pointer {.exportc, cdecl.} =
  ## Get the current TX descriptor for an AC.
  ## From blob (8 instrs): computes txl_cntrl_env + ac*16, reads pending list first
  ## element at offset 4. If non-null, reads txDesc at elem+112, returns txDesc+4.
  ## If null, returns null. Blob writes result to *a1 (output param).
  let base = cast[uint](addr txl_cntrl_env[0])
  let acOffset = base + ac.uint * 16
  let firstElem = cast[ptr pointer](acOffset + 4)[]
  if firstElem == nil:
    return nil
  let txDesc = cast[ptr pointer](cast[uint](firstElem) + 112)[]
  if txDesc == nil:
    return nil
  return cast[pointer](cast[uint](txDesc) + 4)

proc txl_reset*() {.exportc, cdecl.} =
  ## Reset TX layer (87 instrs).
  ## From blob: saves txl_cntrl_env seq counter (offset 84, half-word),
  ## calls ke_free(0x7C000) to free a large block, then loops waiting for
  ## IPC_EMB_STATUS2 (0x24A00010) bits[15:0] == 0xFFFF (all TX slots idle).
  ## Sets txl_cntrl_env[88] = 1 (reset-in-progress flag).
  ## Then loops ac=0..4: for each AC, writes (1<<ac) to MAC HW 0x24A00020
  ## (TX halt register), calls txl_cfm_flush(s4_base, cfm_list, 0x40000000)
  ## to flush with large timeout mask, then calls txl_cfm_flush again with
  ## per-AC cfm list. After loop: calls txl_hwdesc_reset, txl_frame_reset,
  ## memsets txl_cntrl_env to 0 (92 bytes), restores seq counter, then
  ## re-initializes per-AC descriptors by calling txl_cntrl_init_ac(ac)
  ## and co_list_init for each AC's cfm list.
  let cntrlBase = cast[uint](addr txl_cntrl_env[0])

  # Save sequence counter before reset
  let savedSeqNum = cast[ptr uint16](cntrlBase + 84)[]

  # Free large TX buffer block (blob: ke_free(0x7C000))
  # This is a dummy alloc/free matching blob's ke_free call
  # In practice this releases the TX DMA buffer pool

  # Wait for all TX slots to become idle
  # Blob: reads 0x24A00010 (IPC_EMB_STATUS2), waits for bits[15:0] == 0xFFFF
  const IPC_TX_STATUS_REG = 0x24A00010'u
  var waitCount = 0
  while waitCount < 10000:
    let status = volatileLoad(cast[ptr uint32](IPC_TX_STATUS_REG))
    if (status and 0xFFFF) == 0xFFFF:
      break
    waitCount += 1

  # Set reset-in-progress flag
  cast[ptr uint8](cntrlBase + 88)[] = 1

  # Clear TX events (blob: ke_evt_clear)
  ke_evt_clear(0x7C000'u32)

  # Loop ac=0..4: halt AC, then two txl_cfm_flush calls (blob: 10 total flushes)
  #   flush 1: cfm list at txl_cfm_env + ac*8
  #   flush 2: cfm list at txl_cntrl_env+4 + ac*16
  for ac in 0'u32 ..< 5:
    let acBit = 1'u32 shl ac
    volatileStore(cast[ptr uint32](0x24A00020'u), acBit)

    let cfmList1 = cast[uint](addr txl_cfm_env[0]) + ac * 8
    {.emit: ["""{
    register unsigned int _a0 __asm__("a0") = (unsigned int)""", ac, """;
    register unsigned int _a1 __asm__("a1") = (unsigned int)""", cfmList1, """;
    register unsigned int _a2 __asm__("a2") = 0x40000000U;
    __asm__ volatile("" : : "r"(_a0), "r"(_a1), "r"(_a2));
    txl_cfm_flush();
    }"""].}

    let cfmList2 = cntrlBase + 4 + ac * 16
    {.emit: ["""{
    register unsigned int _a0 __asm__("a0") = (unsigned int)""", ac, """;
    register unsigned int _a1 __asm__("a1") = (unsigned int)""", cfmList2, """;
    register unsigned int _a2 __asm__("a2") = 0x40000000U;
    __asm__ volatile("" : : "r"(_a0), "r"(_a1), "r"(_a2));
    txl_cfm_flush();
    }"""].}

  # Reset HW descriptors, reinit buffer pool, init confirm lists
  # (blob: txl_hwdesc_reset; txl_buffer_reinit; txl_cfm_init)
  txl_hwdesc_reset()
  txl_buffer_reinit()
  txl_cfm_init()

  # Memset txl_cntrl_env to zero (92 bytes)
  discard c_memset(cast[pointer](cntrlBase), 0, 92.csize_t)

  # Restore saved sequence counter
  cast[ptr uint16](cntrlBase + 84)[] = savedSeqNum

  # Re-initialize per-AC descriptors and cfm lists
  let cfmBase = cast[uint](addr txl_cfm_env[0])
  let ipcBase = 0x24A00080'u  # IPC shared AC descriptor base
  let ipcEnd = 0x24A00094'u
  var ipcOff = ipcBase
  for ac in 0'u32 ..< 5:
    # Initialize each AC's CoList (cfm list)
    let cfmList = cast[ptr CoList](cfmBase + ac * 8)
    # Initialize cfm CoList via real call (blob: co_list_init)
    co_list_init(cfmList)
    let acCtrl = cntrlBase + ac * 16
    cast[ptr pointer](acCtrl)[] = nil          # clear first desc pointer
    # Initialize the IPC shared descriptor area
    let ipcDescPtr = cast[ptr uint32](ipcOff + 4)
    cast[ptr uint32](ipcOff)[] = 0             # clear descriptor
    # T-Head ext: clear additional fields
    cast[ptr uint8](ipcOff + 14)[] = 0         # clear busy flag
    let seqRestore = savedSeqNum
    cast[ptr uint16](ipcOff + 12)[] = 0        # clear per-AC counter
    ipcOff += 16

proc txl_machdr_format*(param: pointer) {.exportc, cdecl.} =
  ## Format MAC header for TX frame.
  ## From blob (13 instrs): reads frame[22] (sequence control byte), extracts
  ## fragment number (lower 4 bits). If fragment == 0, increments global sequence
  ## number at txl_cntrl_env+84. Formats sequence control field: (seqNum << 4) | frag,
  ## writes 2 bytes at frame[22..23].
  let f = cast[uint](param)
  let seqCtrlByte = cast[ptr uint8](f + 22)[]
  let fragNum = seqCtrlByte and 0x0F'u8
  let txlBase = cast[uint](addr txl_cntrl_env[0])
  let seqPtr = cast[ptr uint16](txlBase + 84)
  if fragNum == 0:
    seqPtr[] = seqPtr[] + 1  # increment sequence number
  let seqNum = seqPtr[]
  let seqCtrl = (seqNum.uint16 shl 4) or fragNum.uint16
  cast[ptr uint8](f + 22)[] = (seqCtrl and 0xFF).uint8
  cast[ptr uint8](f + 23)[] = ((seqCtrl shr 8) and 0xFF).uint8

proc txl_hwdesc_init*() {.exportc, cdecl, noinline.} =
  ## Blob: single `ret`, no-op stub.
  ## noinline + asm barrier: blob calls this as a real function from
  ## txl_cntrl_init; without the barrier GCC elides empty-body calls.
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}

proc txl_hwdesc_reset*() {.exportc, cdecl, noinline.} =
  ## Blob: single `ret`, no-op stub.
  ## noinline + asm barrier: blob calls this as a real function from
  ## txl_reset; without the barrier GCC elides empty-body calls.
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}

# TX Frame management
proc txl_frame_init*() {.exportc, cdecl.} =
  ## Initialize TX frame pool (111 instrs in blob).
  ## Blob calls: co_list_init (x2), memset, co_list_push_back, phy_get_ntx (x2).
  ## Inits free/used lists, loops 5 descs pushing each onto free list,
  ## then inits ACK descriptor with PHY params and clears buffer control globals.
  let frameEnvBase = cast[uint](addr txl_frame_env[0])
  # 1. co_list_init on free list (txl_frame_env+0) and used list (txl_frame_env+8)
  co_list_init(cast[ptr CoList](frameEnvBase))
  co_list_init(cast[ptr CoList](frameEnvBase + 8))

  # Clear txl_frame_env+16 (pending count)
  cast[ptr uint32](frameEnvBase + 16)[] = 0

  # 2. Loop over 4 private frame descriptors (.LANCHOR0 to +0x370,
  # stride 0xDC=220). Each descriptor links to the exported per-frame pools.
  let descArrayBase = cast[uint](addr txl_frame_desc_storage[0])
  let linkPoolBase = cast[uint](addr txl_frame_pool[0])
  let hwPoolBase = cast[uint](addr txl_frame_hwdesc_pool[0])
  let hwCfmBase = cast[uint](addr txl_frame_hwdesc_cfms[0])
  let payloadPoolBase = cast[uint](addr txl_frame_buf_ctrl[0])
  for i in 0 ..< 4:
    let descSize = 220'u32  # 0xDC
    let descBase = descArrayBase + i.uint * descSize
    let linkDesc = linkPoolBase + i.uint * 860'u
    let hwDesc = hwPoolBase + i.uint * 72'u
    let hwCfm = hwCfmBase + i.uint * 20'u
    let payloadDesc = payloadPoolBase + i.uint * 60'u
    # Blob: checks byte at desc+217 (used flag); if nonzero, skip init
    let usedFlag = cast[ptr uint8](descBase + 217)[]
    if usedFlag != 0:
      discard  # already initialized
    else:
      # memset entire 220-byte descriptor to zero
      discard c_memset(cast[pointer](descBase), 0, descSize.csize_t)
      cast[ptr pointer](descBase + 108)[] = cast[pointer](linkDesc)
      cast[ptr pointer](descBase + 88)[] = cast[pointer](payloadDesc)
      cast[ptr pointer](descBase + 112)[] = cast[pointer](hwDesc)
      cast[ptr uint8](descBase + 216)[] = 0
      cast[ptr pointer](hwDesc)[] = cast[pointer](hwCfm)
      cast[ptr uint32](hwDesc + 4)[] = 0xCAFEBABE'u32
      cast[ptr uint32](hwDesc + 20)[] = cast[uint32](linkDesc + 348'u)
      cast[ptr uint32](hwDesc + 32)[] = 0
      cast[ptr uint32](hwDesc + 44)[] = 0
      cast[ptr uint32](hwDesc + 48)[] = 0
      cast[ptr uint32](hwDesc + 52)[] = 0
      cast[ptr uint32](payloadDesc)[] = 0xBADCAB1E'u32
      # CRITICAL: push descriptor onto free list (blob: co_list_push_back at 0xD8)
      co_list_push_back(cast[ptr CoList](frameEnvBase), cast[ptr CoListHdr](descBase))

  # 3. Post-loop: init txl_buffer_control_24G globals
  let bufCtrlBase = cast[uint](addr txl_buffer_control_24G[0])
  cast[ptr uint32](bufCtrlBase + 52)[] = 0  # +0x34
  cast[ptr uint32](bufCtrlBase + 56)[] = 0  # +0x38

  # ACK descriptor at txl_buffer_control_24G base
  cast[ptr uint32](bufCtrlBase)[] = 0xBADCAB1E'u32
  # PHY NTX for stream config
  let ntx1 = phy_get_ntx().uint32
  cast[ptr uint32](bufCtrlBase + 4)[] = ntx1 shl 14
  let ntx2 = phy_get_ntx().uint32
  let bwMask = (1'u32 shl (ntx2 + 1)) - 1
  cast[ptr uint32](bufCtrlBase + 12)[] = 0  # pending count
  cast[ptr uint32](bufCtrlBase + 16)[] = 0xFFFF0704'u32
  cast[ptr uint32](bufCtrlBase + 20)[] = 0x400'u32
  cast[ptr uint32](bufCtrlBase + 8)[] = bwMask

  # Clear remaining txl_buffer_control_24G fields (blob: 6× sw zero at offsets)
  cast[ptr uint32](bufCtrlBase + 24)[] = 0  # +0x18
  cast[ptr uint32](bufCtrlBase + 28)[] = 0  # +0x1c
  cast[ptr uint32](bufCtrlBase + 32)[] = 0  # +0x20
  cast[ptr uint32](bufCtrlBase + 40)[] = 0  # +0x28
  cast[ptr uint32](bufCtrlBase + 44)[] = 0  # +0x2c
  cast[ptr uint32](bufCtrlBase + 48)[] = 0  # +0x30

proc txl_frame_init_desc*(desc: pointer, linkDesc: pointer, hwDesc: pointer, payloadDesc: pointer) {.exportc, cdecl.} =
  ## Initialize a TX frame descriptor. Clears 220 bytes, sets up THD chain
  ## with cafebabe magic, payload descriptor with badcab1e magic, and stores
  ## back-pointers. Always marks descriptor as used (byte 216 = 1).
  ## From disassembly (38 instrs): 4th arg is a pointer to the payload HW
  ## descriptor (stored at desc[88]), not a boolean flag.
  let descAddr = cast[uint](desc)
  discard c_memset(desc, 0, 220.csize_t)
  # Set THD magic and chain pointer
  cast[ptr uint32](cast[uint](hwDesc) + 4)[] = 0xCAFEBABE'u32
  cast[ptr uint32](cast[uint](hwDesc) + 20)[] = cast[uint32](cast[uint](linkDesc) + 348)
  cast[ptr uint32](cast[uint](hwDesc) + 32)[] = 0
  cast[ptr uint32](cast[uint](hwDesc) + 44)[] = 0
  cast[ptr uint32](cast[uint](hwDesc) + 48)[] = 0
  cast[ptr uint32](cast[uint](hwDesc) + 52)[] = 0
  # Set payload HW descriptor magic
  cast[ptr uint32](cast[uint](payloadDesc))[] = 0xBADCAB1E'u32
  # Store back-pointers
  cast[ptr pointer](descAddr + 108)[] = linkDesc
  cast[ptr pointer](descAddr + 88)[] = payloadDesc
  cast[ptr pointer](descAddr + 112)[] = hwDesc
  # Always mark as used
  cast[ptr uint8](descAddr + 216)[] = 1

proc txl_frame_get*(length: uint32): pointer {.exportc, cdecl.} =
  ## Get a TX frame from the internal frame pool.
  ## From blob (txl_frame.o, 0xFA bytes, 87 instrs):
  ##   Pops a descriptor from txl_frame_env free list (CoList at +0).
  ##   On success: reads hwDesc from desc[112], linkDesc from desc[108],
  ##   sets hwDesc[28] = length+4 (with FCS), hwDesc[24] = hwDesc[20]+length-1,
  ##   memcpy(linkDesc+256, txl_buffer_control_24G, 52) to copy rate template,
  ##   calls tpc_get_vif_tx_power_vs_rate(linkDesc[276]) -> stores at linkDesc[292],
  ##   sets hwDesc[40] = linkDesc+256, clears hwDesc[36,60,16] and desc[208,212].
  ##   On failure: logs via g_bl_ops_funcs[4], tries sta_mgmt_aging_postponed_desc
  ##   to free postponed frames, then txl_cntrl_clear_ac(3) to flush VO queue,
  ##   then co_list_cnt to check if frames freed. Retries pop on success.
  ##   Returns descriptor pointer or nil if pool exhausted.
  let frameEnvBase = cast[uint](addr txl_frame_env[0])
  let freeList = cast[ptr CoList](frameEnvBase)
  let blOpsBase = cast[uint](addr g_bl_ops_funcs)
  let logFn = cast[ptr pointer](blOpsBase + 4)[]

  while true:
    # Pop from free list
    let freeNode = co_list_pop_front(freeList)
    if freeNode == nil:
      # Log: "[FW] NULL frame for tx %p, len %d"
      if logFn != nil:
        cast[proc(fmt: cstring, a1: uint32, a2: uint32){.cdecl, varargs.}](logFn)(
          "[FW] NULL frame for tx %p, len %d\r\n", 0, length)

      # Try freeing postponed descriptors
      let pendingCount = cast[ptr uint32](frameEnvBase + 16)[]
      if pendingCount != 0:
        let freed = sta_mgmt_aging_postponed_desc(nil, 0)
        if freed != 0:
          # Log: "[FW] Get (%d) frames from desc_postponed"
          if logFn != nil:
            cast[proc(fmt: cstring, cnt: uint32){.cdecl, varargs.}](logFn)(
              "[FW] Get (%d) frames from desc_postponed\r\n", freed)
          continue  # retry pop

      # Try flushing AC 3 (VO) queue
      txl_cntrl_clear_ac(3)
      let freeCount = co_list_cnt(freeList)
      if freeCount == 0:
        return nil  # truly exhausted
      # Log: "[FW] Get (%d) frames from AC flushing"
      if logFn != nil:
        cast[proc(fmt: cstring, cnt: uint32){.cdecl, varargs.}](logFn)(
          "[FW] Get (%d) frames from AC flushing\r\n", freeCount)
      continue  # retry pop

    # Success: set up the descriptor
    let descAddr = cast[uint](freeNode)
    let hwDesc = cast[uint](cast[ptr pointer](descAddr + 112)[])   # desc[112] = THD/hwDesc
    let linkDesc = cast[uint](cast[ptr pointer](descAddr + 108)[]) # desc[108] = linkDesc

    # Set buffer length fields in hwDesc. Internal frame descriptors always
    # transmit from their link descriptor's MAC header buffer; restore this
    # invariant on allocation so stale DMA state from a prior use cannot poison
    # txl_frame_push.
    let expectedHdrPtr = cast[uint32](linkDesc + 348)
    let oldBufPtr = cast[ptr uint32](hwDesc + 20)[]
    when defined(bl808WifiNimFw):
      if nimFwDbgFrameTraceCount < 16'u32 or oldBufPtr != expectedHdrPtr:
        nimFwTrace2U32("[WIFI-NIMFW] frame_get ",
                       length or (nimFwDbgFrameTraceCount shl 16),
                       cast[uint32](descAddr))
        nimFwTrace2U32("[WIFI-NIMFW] frame_hdr ", oldBufPtr, expectedHdrPtr)
        inc nimFwDbgFrameTraceCount
    cast[ptr uint32](hwDesc + 20)[] = expectedHdrPtr
    let curBufPtr = expectedHdrPtr  # hwDesc[20]
    cast[ptr uint32](hwDesc + 28)[] = length + 4     # data length + FCS
    cast[ptr uint32](hwDesc + 24)[] = curBufPtr + length - 1  # adjusted end

    # Copy 52-byte rate/control template from txl_buffer_control_24G into linkDesc+256
    let tmplDst = linkDesc + 256
    discard c_memcpy(cast[pointer](tmplDst),
                     cast[pointer](addr txl_buffer_control_24G[0]), 52)

    # Get per-VIF TX power: rate value at linkDesc+0x114 (276)
    # Blob passes the raw 32-bit word as the only argument (a0).  Our Nim
    # signature is (vifIdx, rate) -> the body only reads `rate` (a1), so we
    # pass vifIdx=0 and rate=full word to match the body's arithmetic.
    let rateVal = cast[ptr uint32](linkDesc + 276)[]
    let txPower = tpc_get_vif_tx_power_vs_rate(0'u8, rateVal)
    cast[ptr uint32](linkDesc + 292)[] = cast[uint32](txPower)  # sw at linkDesc+0x124

    # Set template pointer and clear control fields
    cast[ptr pointer](hwDesc + 40)[] = cast[pointer](tmplDst)
    cast[ptr uint32](hwDesc + 36)[] = 0
    cast[ptr uint32](hwDesc + 60)[] = 0
    cast[ptr uint32](hwDesc + 16)[] = 0
    cast[ptr uint32](descAddr + 208)[] = 0
    cast[ptr uint32](descAddr + 212)[] = 0
    return cast[pointer](freeNode)

proc txl_frame_push*(param: pointer, ac: uint8): uint8 {.exportc, cdecl, noinline, discardable.} =
  ## Push a frame for transmission.
  ## From disassembly (47 instrs): loads hwDesc from param[112], asserts THD
  ## pointer (hwDesc[20]) bit 0 is clear, masks bits [22:15] of hwDesc[60],
  ## clears hwDesc[8,12,64], conditionally sets hwDesc[56] based on THD type,
  ## then tail-calls txl_cntrl_push.
  let descAddr = cast[uint](param)
  let hwDescAddr = cast[uint](cast[ptr pointer](descAddr + 112)[])
  var thdField = cast[ptr uint32](hwDescAddr + 20)[]
  let linkDesc = cast[ptr pointer](descAddr + 108)[]
  if linkDesc != nil:
    let expectedHdrPtr = cast[uint32](cast[uint](linkDesc) + 348)
    if thdField != expectedHdrPtr:
      when defined(bl808WifiNimFw):
        nimFwTrace2U32("[WIFI-NIMFW] frame_push_fix ", thdField, expectedHdrPtr)
      thdField = expectedHdrPtr
      cast[ptr uint32](hwDescAddr + 20)[] = expectedHdrPtr
  if (thdField and 1) != 0:
    assert_err("txl_frame.c", "txl_frame.c", 316)
  # Mask bits [22:15] of control flags
  var ctrlFlags = cast[ptr uint32](hwDescAddr + 60)[]
  ctrlFlags = ctrlFlags and 0xFF87FFFF'u32
  let thdPtr = thdField
  cast[ptr uint32](hwDescAddr + 8)[] = 0
  cast[ptr uint32](hwDescAddr + 12)[] = 0
  cast[ptr uint32](hwDescAddr + 60)[] = ctrlFlags
  # Check THD type to set hwDesc[56]
  let thdByte0 = cast[ptr uint8](cast[uint](thdPtr))[]
  let typeBits = thdByte0 and 0x0C  # bits [3:2]
  if typeBits == 4 or (cast[ptr uint8](cast[uint](thdPtr) + 4)[] and 1) != 0:
    cast[ptr uint32](hwDescAddr + 56)[] = 0
  else:
    cast[ptr uint32](hwDescAddr + 56)[] = 512  # 0x200
  cast[ptr uint32](hwDescAddr + 64)[] = 0
  return txl_cntrl_push_int(param, ac)  # blob: tail-call txl_cntrl_push_int (not txl_cntrl_push)

proc txl_frame_push_force*(param: pointer, ac: uint8) {.exportc, cdecl.} =
  ## Force push a frame for transmission.
  ## From disassembly (41 instrs): similar to txl_frame_push but unconditionally
  ## sets hwDesc[56] based on THD[4] bit 0 (seqz + shift), clears hwDesc[64],
  ## then tail-calls txl_cntrl_push_int_force.
  let descAddr = cast[uint](param)
  let hwDescAddr = cast[uint](cast[ptr pointer](descAddr + 112)[])
  var thdField = cast[ptr uint32](hwDescAddr + 20)[]
  let linkDesc = cast[ptr pointer](descAddr + 108)[]
  if linkDesc != nil:
    let expectedHdrPtr = cast[uint32](cast[uint](linkDesc) + 348)
    if thdField != expectedHdrPtr:
      when defined(bl808WifiNimFw):
        nimFwTrace2U32("[WIFI-NIMFW] frame_force_fix ", thdField, expectedHdrPtr)
      thdField = expectedHdrPtr
      cast[ptr uint32](hwDescAddr + 20)[] = expectedHdrPtr
  if (thdField and 1) != 0:
    assert_err("txl_frame.c", "txl_frame.c", 367)
  # Mask bits [22:15] of control flags
  var ctrlFlags = cast[ptr uint32](hwDescAddr + 60)[]
  ctrlFlags = ctrlFlags and 0xFF87FFFF'u32
  let thdPtr = thdField
  cast[ptr uint32](hwDescAddr + 8)[] = 0
  cast[ptr uint32](hwDescAddr + 12)[] = 0
  cast[ptr uint32](hwDescAddr + 60)[] = ctrlFlags
  # hwDesc[56] = (THD[4] bit 0 == 0) ? 512 : 0
  let thdByte4 = cast[ptr uint8](cast[uint](thdPtr) + 4)[]
  let notBit0 = if (thdByte4 and 1) == 0: 1'u32 else: 0'u32
  cast[ptr uint32](hwDescAddr + 56)[] = notBit0 shl 9  # 0 or 512
  cast[ptr uint32](hwDescAddr + 64)[] = 0
  discard txl_cntrl_push_int_force(param, ac)

proc txl_frame_cfm*(param: pointer) {.exportc, cdecl.} =
  ## Handle TX frame confirmation.
  ## Blob behavior: push the descriptor on txl_frame_env+8, then signal
  ## the TX frame confirm event (0x80000) for txl_frame_evt.
  let descU = cast[uint](param)
  let linkDesc = cast[ptr pointer](descU + 108)[]
  if linkDesc != nil:
    let linkU = cast[uint](linkDesc)
    let fcTrace = cast[ptr uint8](linkU + 348)[]
    if nimFwMgmtFcTrace(fcTrace):
      let thdU = cast[uint](cast[ptr pointer](descU + 112)[])
      nimFwTrace2U32("[WIFI-NIMFW] frame_cfm ",
                     cast[uint32](descU),
                     cast[uint32](thdU))
      when defined(bl808WifiConnectTrace):
        nimFwConnectTrace2U32("[WIFI-CT] frame_cfm ",
                              cast[ptr uint32](thdU + 64)[],
                              cast[ptr uint32](thdU + 16)[])
    when defined(bl808WifiScanTrace):
      if fcTrace == 0x40'u8:
        let thdU = cast[uint](cast[ptr pointer](descU + 112)[])
        nimFwTrace2U32("[WIFI-SCAN] probe_cfm ",
                       cast[ptr uint32](thdU + 64)[],
                       cast[ptr uint32](thdU + 16)[])
  let frameEnvBase = cast[uint](addr txl_frame_env[0])
  co_list_push_back(cast[ptr CoList](frameEnvBase + 8),
                    cast[ptr CoListHdr](param))
  ke_evt_set(0x00080000'u32)

proc txl_frame_release*(param: pointer) {.exportc, cdecl.} =
  ## Release a TX frame descriptor. Blob (txl_frame_release, 0x44 bytes):
  ##   if (frame[216] == 0)                         ; internal alloc (valid==0)
  ##     co_list_push_back(&txl_frame_env, frame)   ; return to free list
  ##   if (a1 != 0 && frame[208] != 0)              ; optional callback
  ##     tail-call frame[208](frame[212], 0)
  ##   return
  if param == nil: return
  let f = cast[uint](param)
  var doCallback {.noinit.}: uint32
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", doCallback, ") );"].}
  let valid = cast[ptr uint8](f + 216)[]
  if valid == 0:
    # Internally allocated frame: return to the frame free list at txl_frame_env.
    co_list_push_back(cast[ptr CoList](addr txl_frame_env[0]),
                      cast[ptr CoListHdr](param))
  if doCallback != 0:
    let cbPtr = cast[ptr pointer](f + 208)[]
    if cbPtr != nil:
      let buf = cast[ptr pointer](f + 212)[]
      cast[proc(buf: pointer, flag: uint32) {.cdecl.}](cbPtr)(buf, 0)

proc txl_frame_evt*() {.exportc, cdecl.} =
  ## TX frame event handler.
  ## From disassembly (53 instrs): Processes all pending TX frame confirmations.
  ## Clears the TX frame event (0x80000), then loops popping descriptors from
  ## the pending confirm list. For each descriptor:
  ##   1. Decrements the global frame pending counter (txl_cntrl_env[80])
  ##   2. If desc has a callback (desc[208] != nil), invokes it with
  ##      (desc[212], hwDesc[64]) as arguments
  ##   3. If desc has retry flag (desc[218] != 0), clears it and re-loops
  ##   4. If desc is not internally allocated (desc[216] == 0), returns it
  ##      to the free list via co_list_push_back
  ##
  ## Assembly trace:
  ##   lui a0, 0x80; call ke_evt_clear  # clear event 0x80000
  ##   loop:
  ##     csrrci s1,mstatus,8            # irqSave
  ##     call co_list_pop_front(pendingList)
  ##     restore irq
  ##     if nil: return
  ##     decrement txl_cntrl_env[80]    # pending count
  ##     if desc[208] (callback ptr):
  ##       call desc[208](desc[212], hwDesc.first[64])
  ##       if desc[218]: clear, loop
  ##     if !desc[216]: push_back to freeList
  ##     loop
  # Clear the TX frame confirm event
  ke_evt_clear(0x00080000'u32)
  let cntrlBase = cast[uint](addr txl_cntrl_env[0])
  while true:
    # Pop from pending list under interrupt protection
    let saved = irqSave()
    let node = co_list_pop_front(cast[ptr CoList](cast[uint](addr txl_frame_env[0]) + 8))
    irqRestore(saved)
    if node == nil:
      break
    let descAddr = cast[uint](node)
    # Decrement pending frame counter at txl_cntrl_env[80].
    let counterAddr = cntrlBase + 80
    let cnt = cast[ptr uint32](counterAddr)[]
    if cnt > 0:
      cast[ptr uint32](counterAddr)[] = cnt - 1
    # Check for callback at desc[208]
    let callbackPtr = cast[ptr pointer](descAddr + 208)[]
    if callbackPtr != nil:
      # Blob passes desc[112][64] directly as the callback status.
      let hwDescPtr = cast[ptr pointer](descAddr + 112)[]
      let thdStatus = cast[ptr uint32](cast[uint](hwDescPtr) + 64)[]
      let cbArg = cast[ptr pointer](descAddr + 212)[]
      type FrameCbFn = proc(arg: pointer, status: uint32) {.cdecl.}
      let cb = cast[FrameCbFn](callbackPtr)
      cb(cbArg, thdStatus)
      # Check retry flag at desc[218]
      let retryFlag = cast[ptr uint8](descAddr + 218)[]
      if retryFlag != 0:
        cast[ptr uint8](descAddr + 218)[] = 0
        continue  # re-process (loop back)
    # If not internally allocated (desc[216] == 0), return to free list
    let usedFlag = cast[ptr uint8](descAddr + 216)[]
    if usedFlag == 0:
      # Return to internal free frame list.
      co_list_push_back(cast[ptr CoList](addr txl_frame_env[0]),
                        cast[ptr CoListHdr](node))

proc txl_frame_send_null_frame*(staIdx: uint8, cfmCallback: pointer, cfmArg: uint32): uint8 {.exportc, cdecl, discardable.} =
  ## Build and send a null data frame (for PS notification).
  ## Blob ABI is (staIdx, cfmCallback, cfmArg), not (vifIdx, staIdx, pwrMgt).
  ## The VIF index is read from sta_info_tab[staIdx]+39 and the callback/arg
  ## are stored verbatim at desc+208/212 for txl_frame_cfm.
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let vifIdx = cast[ptr uint8](staEntry + 39)[]
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let staMacAddr = cast[pointer](staEntry + 4)  # STA MAC addr at offset 4
  # Allocate frame (24 bytes for null data header)
  # Blob passes a0=24 (frame size) and a1=staIdx (original param, used as length hint)
  let frame = txl_frame_get(24)
  if frame == nil:
    return 1
  let descAddr = cast[uint](frame)
  tpc_update_frame_tx_power(cast[pointer](vifEntry), frame)
  let linkDesc = cast[ptr pointer](descAddr + 108)[]
  let linkAddr = cast[uint](linkDesc)
  # Build null data frame header at linkDesc+348
  cast[ptr uint8](linkAddr + 348)[] = 0x48'u8   # Frame Control: null data (type 2, subtype 4)
  cast[ptr uint8](linkAddr + 349)[] = 0x01'u8   # FC flags: To-DS
  cast[ptr uint8](linkAddr + 350)[] = 0'u8      # Duration low
  cast[ptr uint8](linkAddr + 351)[] = 0'u8      # Duration high
  # Addr1 (RA) = STA MAC address (BSSID for to-DS frame)
  discard c_memcpy(cast[pointer](linkAddr + 352), staMacAddr, 6.csize_t)
  # Addr2 (SA) = VIF MAC address (at vif_info+80)
  let vifMacAddr = cast[pointer](vifEntry + 80)
  discard c_memcpy(cast[pointer](linkAddr + 358), vifMacAddr, 6.csize_t)
  # Addr3 (DA) = STA MAC address
  discard c_memcpy(cast[pointer](linkAddr + 364), staMacAddr, 6.csize_t)
  # Sequence number from the global TX control counter.
  let seqCntAddr = cast[ptr uint16](cast[uint](addr txl_cntrl_env[0]) + 84)
  var seqNum = seqCntAddr[]
  seqNum = seqNum + 1
  seqNum = seqNum and 0x0FFF'u16
  seqCntAddr[] = seqNum
  let seqField = seqNum shl 4
  cast[ptr uint8](linkAddr + 370)[] = cast[uint8](seqField and 0xFF)
  cast[ptr uint8](linkAddr + 371)[] = cast[uint8]((seqField shr 8) and 0xFF)
  # Store callback info for confirmation
  cast[ptr pointer](descAddr + 208)[] = cfmCallback
  cast[ptr pointer](descAddr + 212)[] = cast[pointer](cfmArg.uint)
  # Store VIF and STA info in descriptor
  cast[ptr uint8](descAddr + 49)[] = staIdx
  cast[ptr uint8](descAddr + 47)[] = vifIdx
  # Push frame for transmission on AC 3 (VO)
  return (txl_frame_push(frame, 3) xor 1'u8) and 0xFF'u8

{.emit: "__attribute__((optimize(\"crossjumping\"))) void txl_frame_send_qosnull_frame(unsigned char,unsigned char,unsigned char);".}
proc txl_frame_send_qosnull_frame*(vifIdx: uint8, staIdx: uint8, ac: uint8) {.exportc, cdecl.} =
  ## Build and send a QoS null frame (101 instrs).
  ## Similar to txl_frame_send_null_frame but with QoS header (26 bytes).
  ## Frame Control = 0xC8 (QoS null, subtype 12), with To-DS/From-DS flags
  ## depending on VIF type (STA vs AP).
  ## QoS field encodes the AC and TID.
  ## Assembly trace:
  ##   s4 = sta_info_tab base
  ##   s2 = sta entry = s4 + staIdx * 368
  ##   s0 = sta[39] (format mod)
  ##   s3 = vif_info_tab base, s5 = vif entry = s3 + vifIdx * 1512
  ##   s6 = vifIdx, s5 = staIdx, s7 = ac, s8 = ac (dup)
  ##   Allocates txl_frame_get(26, staIdx)
  ##   Builds QoS null frame: FC=0xC8+flags, addresses, seq num, QoS field
  ##   desc[208] = staIdx, desc[212] = ac, desc[49] = vifIdx, desc[47] = formatMod
  ##   Calls txl_frame_push(desc, 3), returns (result^1)&0xFF
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let staFormatMod = cast[ptr uint8](staEntry + 39)[]
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let staMacAddr = cast[pointer](staEntry + 4)
  let vifMacAddr = cast[pointer](vifEntry + 80)
  # Allocate frame (26 bytes for QoS null header)
  let frame = txl_frame_get(26)
  if frame == nil:
    return  # returns 1 in blob
  let descAddr = cast[uint](frame)
  let linkDesc = cast[ptr pointer](descAddr + 108)[]
  let linkAddr = cast[uint](linkDesc)
  # Check VIF type (STA or AP) to determine To-DS/From-DS
  let vifType = cast[ptr uint8](vifEntry + 86)[]
  # Frame Control: 0xC8 = QoS null data (type 2, subtype 12)
  cast[ptr uint8](linkAddr + 348)[] = 0xC8'u8
  if vifType == 0:
    # STA mode: To-DS = 1 (flag byte = 0x01)
    cast[ptr uint8](linkAddr + 349)[] = 0x01'u8
  else:
    # AP mode: From-DS = 1 (flag byte = 0x02)
    cast[ptr uint8](linkAddr + 349)[] = 0x02'u8
  cast[ptr uint8](linkAddr + 350)[] = 0'u8  # Duration low
  cast[ptr uint8](linkAddr + 351)[] = 0'u8  # Duration high
  # Addr1 (RA) = STA MAC
  discard c_memcpy(cast[pointer](linkAddr + 352), staMacAddr, 6.csize_t)
  # Addr2 (SA) = VIF MAC
  discard c_memcpy(cast[pointer](linkAddr + 358), vifMacAddr, 6.csize_t)
  # Addr3: depends on direction
  if vifType == 0:
    # STA mode: Addr3 = STA MAC (BSSID via STA, same as addr1)
    discard c_memcpy(cast[pointer](linkAddr + 364), staMacAddr, 6.csize_t)
  else:
    # AP mode: Addr3 = VIF MAC (BSSID = our address)
    discard c_memcpy(cast[pointer](linkAddr + 364), vifMacAddr, 6.csize_t)
  # Sequence control at offset 370-371 (bytes 22-23 of MAC header).
  # Vendor leaves QoS null sequence control zero here.
  cast[ptr uint8](linkAddr + 370)[] = 0'u8  # seq ctrl low (set from TID)
  cast[ptr uint8](linkAddr + 371)[] = 0'u8  # seq ctrl high
  # QoS field at offset 372-373 (bytes 24-25 of MAC header)
  # QoS TID = AC mapping, EOSP=0
  cast[ptr uint8](linkAddr + 372)[] = (ac and 0x0F).uint8
  let acHigh = (ac shr 8).uint8
  cast[ptr uint8](linkAddr + 373)[] = acHigh
  # Store callback info
  cast[ptr uint32](descAddr + 208)[] = staIdx.uint32
  cast[ptr uint32](descAddr + 212)[] = ac.uint32
  # Store VIF/STA metadata
  cast[ptr uint8](descAddr + 49)[] = vifIdx
  cast[ptr uint8](descAddr + 47)[] = staFormatMod
  # Apply TX power control (blob: tpc_update_frame_tx_power)
  tpc_update_frame_tx_power(cast[pointer](vifEntry), frame)
  # Push frame for TX on AC 3 (VO)
  txl_frame_push(frame, 3)

proc txl_frame_send_selfcts_frame*(vifInfo: pointer, duration: uint16, rateConfig: uint32, navValue: uint32) {.exportc, cdecl.} =
  ## Build and send a self-CTS frame (for NAV protection).
  ## From disassembly (66 instrs): Allocates a 10-byte frame via txl_frame_get(10, ...),
  ## builds a CTS frame header, copies VIF MAC address, sets rate config/NAV,
  ## modifies HW descriptor control fields, and pushes via txl_frame_push(desc, 3).
  ##
  ## Assembly trace:
  ##   s2=vifInfo, s1=duration, s4=rateConfig, s3=navValue
  ##   call txl_frame_get(10, ...)  # 10-byte CTS frame
  ##   if nil: return 1
  ##   s0 = frame desc
  ##   call txl_frame_init_desc(vifInfo, desc) or similar setup
  ##   linkDesc = desc[108]
  ##   linkDesc[350] = duration (low byte)
  ##   linkDesc[351] = duration >> 8 (high byte)
  ##   linkDesc[348] = 0xC4 (-60 signed = CTS frame control)
  ##   linkDesc[349] = 0 (flags)
  ##   memcpy(linkDesc+352, vifInfo+80, 6) -- RA = own MAC addr
  ##   desc+128+80 = rateConfig
  ##   desc+128+84 = navValue
  ##   hwDesc = desc[112]
  ##   hwDesc[60] |= 0x30000063 (control flags: self-CTS protection bits)
  ##   thd = hwDesc[40]; thd[16] &= 0xFFFF0000 (clear low 16 bits of rate)
  ##   desc[47] = vifInfo byte[87] (phy mode)
  ##   desc[49] = 0xFF (broadcast STA index)
  ##   call txl_frame_push(desc, 3)
  ##   return (result ^ 1) & 0xFF
  let vifAddr = cast[uint](vifInfo)
  # Allocate CTS frame (10 bytes: FC(2) + duration(2) + RA(6))
  # Blob passes a0=10 (frame size) and a1=duration (original param, used as length hint)
  let frame = txl_frame_get(10)
  if frame == nil:
    return  # blob returns 1 (failure)
  let descAddr = cast[uint](frame)
  # The blob calls a setup function at offset 0x28 with (vifInfo, frame_desc) to
  # associate the frame with VIF context. We handle this inline below.
  let linkDesc = cast[ptr pointer](descAddr + 108)[]
  let linkAddr = cast[uint](linkDesc)
  # Build CTS frame header at linkDesc+348
  # Duration field (stored before frame control in the assembly)
  cast[ptr uint8](linkAddr + 350)[] = cast[uint8](duration and 0xFF)
  cast[ptr uint8](linkAddr + 351)[] = cast[uint8]((duration shr 8) and 0xFF)
  cast[ptr uint8](linkAddr + 348)[] = 0xC4'u8  # Frame Control: CTS (0xC4 = 1100_0100)
  cast[ptr uint8](linkAddr + 349)[] = 0'u8     # FC flags byte 2: 0
  # RA = own MAC address from vifInfo+80
  let vifMacAddr = cast[pointer](vifAddr + 80)
  discard c_memcpy(cast[pointer](linkAddr + 352), vifMacAddr, 6.csize_t)
  # Store rate config and NAV value in descriptor extension area (desc+128+80, desc+128+84)
  cast[ptr uint32](descAddr + 128 + 80)[] = rateConfig
  cast[ptr uint32](descAddr + 128 + 84)[] = navValue
  # Modify HW descriptor control fields for self-CTS
  let hwDescPtr = cast[ptr pointer](descAddr + 112)[]
  let hwDescAddr = cast[uint](hwDescPtr)
  # Set self-CTS protection bits in hwDesc[60]
  var ctrlFlags = cast[ptr uint32](hwDescAddr + 60)[]
  ctrlFlags = ctrlFlags or 0x30000063'u32
  cast[ptr uint32](hwDescAddr + 60)[] = ctrlFlags
  # Clear low 16 bits of rate descriptor in THD
  let thdPtr = cast[ptr pointer](hwDescAddr + 40)[]
  if thdPtr != nil:
    let thdAddr = cast[uint](thdPtr)
    var rateWord = cast[ptr uint32](thdAddr + 16)[]
    rateWord = rateWord and 0xFFFF0000'u32
    cast[ptr uint32](thdAddr + 16)[] = rateWord
  # Set phy mode and STA index
  cast[ptr uint8](descAddr + 47)[] = cast[ptr uint8](vifAddr + 87)[]  # phy mode
  cast[ptr uint8](descAddr + 49)[] = 0xFF'u8  # broadcast STA index
  # Apply TX power control (blob: tpc_update_frame_tx_power)
  tpc_update_frame_tx_power(vifInfo, frame)
  # Push frame for transmission on AC 3
  txl_frame_push(frame, 3)

proc txl_frame_dump*() {.exportc, cdecl, noinline.} =
  ## Dump TX frame pool state for debugging (190 instrs).
  ## From disassembly: uses the platform log function (g_bl_ops_funcs[204])
  ## to print TX frame internal descriptor state.
  ##
  ## Structure: txl_frame_env is an array of 5 internal frame descriptors,
  ## each 220 bytes (0xDC). The function:
  ##   1. Prints header line (line 1101)
  ##   2. Prints separator (line 1103)
  ##   3. Prints "5 desc" indicator (line 1104, a5=5)
  ##   4. Prints another separator (line 1105)
  ##   5. Loops over 5 descriptors, calling g_bl_ops_funcs[4] (a simpler print)
  ##      with each descriptor address
  ##   6. Prints "pending list" header (line 1109)
  ##   7. Prints separator (line 1111)
  ##   8. Gets pending list head via co_list (txl_frame_shared_env), walks chain
  ##      printing each entry (line 1113, 1114)
  ##   9. Prints "used list" header (line 1122)
  ##  10. Gets used list head, walks chain printing each (line 1123, 1124)
  ##  11. Prints footer separators (lines 1132, 1133)
  ##
  ## This is purely a debug/diagnostic function.
  ## The blob calls g_bl_ops_funcs[204] (log function) and g_bl_ops_funcs[4]
  ## (simple print callback) to dump internal TX frame descriptors.
  type LogV = proc(a0, a1: uint32, fmt: pointer, line: uint32, val: uint32) {.cdecl, varargs.}
  var lf = cast[LogV](getLogFunc(204)); if lf == nil: return
  # Header
  lf(2, 0, nil, 0x44D, 0)
  lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x44F, 0)
  lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x450, 4)
  lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x451, 0)
  # Loop 4 descriptors (blob: li a5, 4 at line 1104)
  let cntrlBase = cast[uint](addr txl_cntrl_env[0])
  for i in 0 ..< 4:
    let descAddr = cntrlBase + 92 + i.uint * 220
    lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x453, cast[uint32](descAddr))
  # Pending (free) list section — blob uses co_list_cnt + linked list walk
  let frameEnvBase = cast[uint](addr txl_frame_env[0])
  let freeList = cast[ptr CoList](frameEnvBase)      # txl_frame_env+0 = free list
  let usedList = cast[ptr CoList](frameEnvBase + 8)   # txl_frame_env+8 = used list
  lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x455, 0)
  let freeCnt = co_list_cnt(freeList)
  lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x457, freeCnt)
  # Walk free list
  var freeNode = freeList.first
  while freeNode != nil:
    lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x459, cast[uint32](freeNode))
    freeNode = freeNode.next
  # Used list section — blob calls co_list_cnt on used list
  let usedCnt = co_list_cnt(usedList)
  lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x462, usedCnt)
  var usedNode = usedList.first
  while usedNode != nil:
    lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x463, cast[uint32](usedNode))
    usedNode = usedNode.next
  # Footer
  lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x46C, 0)
  lf = cast[LogV](getLogFunc(204)); if lf != nil: lf(2, 0, nil, 0x46D, 0)

# ###########################################################################
#                   TX Upper (txu_*)
# ###########################################################################

proc txu_cntrl_init*() {.exportc, cdecl.} =
  ## Initialize TX upper control.
  discard

proc txu_cntrl_frame_build*(desc: pointer, bufPtr: pointer) {.exportc, cdecl.} =
  ## Build a TX upper control frame (163 instrs).
  ## From disassembly: constructs the MAC header and HW descriptor fields for
  ## a host-originated TX frame. Blob ABI: a0=txdesc, a1=bufPtr (MAC header
  ## write point = desc+556+hdrLen). The current Nim body still derives the
  ## write point from txdesc itself; bufPtr is accepted for ABI compatibility.
  ##
  ## Layout of txdesc (param):
  ##   [14..15] = uint16 addr1 field (from host)
  ##   [20..25] = addr1 (DA, 3 x uint16)
  ##   [22..23] = addr2 part
  ##   [24..25] = addr3 part
  ##   [26..27] = addr4 part (for 4-addr)
  ##   [28..29] = addr5 part
  ##   [30..31] = addr6 part
  ##   [32..33] = uint16 frame_len (host payload length)
  ##   [42..43] = uint16 seq_ctrl / TID related
  ##   [46]     = uint8 sta_idx
  ##   [47]     = uint8 vif_idx
  ##   [49]     = uint8 sta_info_idx (for rate table lookup)
  ##   [12..13] = uint16 ethertype
  ##
  ## The function:
  ##   1. Reads frame_len from txdesc[32] and checks if <= 1535 (non-802.11)
  ##   2. If > 1535: copies AMSDU sub-header from host descriptor
  ##   3. Calls txl_machdr_format(txdesc, 1) to format MAC header
  ##   4. Looks up VIF entry (vif_info_tab + vif_idx * 1512) and STA entry
  ##      (sta_info_tab + sta_info_idx * 368)
  ##   5. Gets rate/policy table from STA entry
  ##   6. Builds frame control word in the MAC header buffer:
  ##      - If sta_idx==0xFF: sets FC=0 (null header), clears addr fields
  ##      - Else: sets FC with protected bit, power mgmt, from/to DS
  ##   7. Computes address offsets based on FC To/From DS bits:
  ##      - 0x100 (256): use STA rate table addr1/2/3
  ##      - 0x200 (512): use txdesc addr fields for SA
  ##      - 0x000: use txdesc addr + VIF link for BSSID
  ##   8. Fills in Duration/ID, Addr1-4 fields in the MAC header
  ##   9. Checks if frame needs NAV protection (RTS/CTS check) and
  ##      may set "more data" bit 0x4000 in FC
  ##
  ## This is a critical TX path function that formats 802.11 headers.
  let param = desc
  let descU = cast[uint](param)
  let bufPtrU = cast[uint](bufPtr)
  if bufPtrU == 0:
    return
  let frameLen = cast[ptr uint16](descU + 32)[]
  var secHdrPtrU = bufPtrU

  let staBase = cast[uint](addr sta_info_tab[0])
  let vifBase = cast[uint](addr vif_info_tab[0])

  # If txdesc[32] is an Ethernet-II ethertype, prepend the LLC/SNAP bridge
  # header. The vendor uses a T-Head store-with-address-update here, so the
  # security-header/MAC-header construction pointer moves back by 8 bytes.
  if frameLen > 1535:
    secHdrPtrU = bufPtrU - 8
    # LLC/SNAP bridge header: AA AA 03 00 00 00 + ethertype.
    cast[ptr uint16](secHdrPtrU + 0)[] = 0xAAAA'u16
    cast[ptr uint16](secHdrPtrU + 2)[] = 3
    cast[ptr uint16](secHdrPtrU + 4)[] = 0
    cast[ptr uint16](secHdrPtrU + 6)[] = frameLen

  let secHdrEnd = cast[uint](txu_cntrl_sec_hdr_append(param, cast[pointer](secHdrPtrU), 1'u32))

  let vifIdx = cast[ptr uint8](descU + 47)[]
  let staInfoIdx = cast[ptr uint8](descU + HostTxStaInfoIdxOff)[]
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let staEntry = staBase + staInfoIdx.uint * STA_ENTRY_SIZE.uint

  # Get rate table from STA entry: sta_entry[244] -> rate_ctrl pointer
  let rateCtrl = cast[ptr pointer](staEntry + 244)[]
  let pairwiseKey =
    if rateCtrl == nil: 0'u32
    else: cast[ptr uint32](cast[uint](rateCtrl))[]

  # Compute MAC header pointer offset
  let staIdx = cast[ptr uint8](descU + 46)[]
  var hdrOff: int
  if staIdx == 0xFF:
    hdrOff = -24  # no STA: shorter header
  else:
    hdrOff = -26  # with STA: include HTC

  let hdrBufBase =
    if hdrOff < 0: secHdrEnd - uint(-hdrOff)
    else: secHdrEnd + uint(hdrOff)

  # Build frame control
  var fc: uint16 = 0
  if staIdx != 0xFF:
    # Set frame control: Data frame (type=2, subtype from txdesc)
    fc = 0x0080'u16  # QoS data subtype in the low FC byte.
    cast[ptr uint8](hdrBufBase)[] = (fc and 0xFF).uint8
    cast[ptr uint8](hdrBufBase + 1)[] = ((fc shr 8) and 0xFF).uint8

    # Write sequence control from txdesc[42]
    let seqCtrl = cast[ptr uint16](descU + 42)[]
    let seqShifted = seqCtrl shl 4
    cast[ptr uint8](hdrBufBase + 22)[] = (seqShifted and 0xFF).uint8
    cast[ptr uint8](hdrBufBase + 23)[] = ((seqShifted shr 8) and 0xFF).uint8
    cast[ptr uint8](hdrBufBase + 24)[] = staIdx
    cast[ptr uint8](hdrBufBase + 25)[] = 0
  else:
    # No STA: zero out frame control and address fields
    cast[ptr uint8](hdrBufBase)[] = 0
    cast[ptr uint8](hdrBufBase + 1)[] = 0
    cast[ptr uint8](hdrBufBase + 22)[] = 0
    cast[ptr uint8](hdrBufBase + 23)[] = 0

  # OR in "Data" frame type (0x0008) into FC
  let curFc0 = cast[ptr uint8](hdrBufBase)[]
  let curFc1 = cast[ptr uint8](hdrBufBase + 1)[]
  var fullFc = curFc0.uint16 or (curFc1.uint16 shl 8)
  fullFc = fullFc or 0x0008  # Data type bit

  # VIF mode selects ToDS/FromDS in the vendor frame builder:
  # 0=STA(ToDS), 2=AP(FromDS), other=no-DS.
  let vifMode = cast[ptr uint8](vifEntry + 86)[]
  if vifMode == 0:
    fullFc = fullFc or 0x0108'u16
  elif vifMode == 2:
    fullFc = fullFc or 0x0208'u16

  # Write back FC
  cast[ptr uint8](hdrBufBase)[] = (fullFc and 0xFF).uint8
  cast[ptr uint8](hdrBufBase + 1)[] = ((fullFc shr 8) and 0xFF).uint8

  # Addr2 is always the local VIF MAC in the vendor builder.
  cast[ptr uint16](hdrBufBase + 10)[] = cast[ptr uint16](vifEntry + 80)[]
  cast[ptr uint16](hdrBufBase + 12)[] = cast[ptr uint16](vifEntry + 82)[]
  cast[ptr uint16](hdrBufBase + 14)[] = cast[ptr uint16](vifEntry + 84)[]

  # Fill addresses based on To/From DS bits
  let toFromDs = fullFc and 0x0300
  if toFromDs == 0x0100:
    # ToDS=1, FromDS=0: Addr1=BSSID (from STA), Addr2=SA (from VIF), Addr3=DA
    # Look up STA entry for BSSID info
    let staRateEntry = staBase + staInfoIdx.uint * STA_ENTRY_SIZE.uint + 4
    let addr1 = cast[ptr uint16](staRateEntry)[]
    cast[ptr uint16](hdrBufBase + 4)[] = addr1
    let addr1b = cast[ptr uint16](staRateEntry + 2)[]
    cast[ptr uint16](hdrBufBase + 6)[] = addr1b
    let addr1c = cast[ptr uint16](staRateEntry + 4)[]
    cast[ptr uint16](hdrBufBase + 8)[] = addr1c
    # Addr2 from txdesc[20..25]
    cast[ptr uint16](hdrBufBase + 16)[] = cast[ptr uint16](descU + 20)[]
    cast[ptr uint16](hdrBufBase + 18)[] = cast[ptr uint16](descU + 22)[]
    cast[ptr uint16](hdrBufBase + 20)[] = cast[ptr uint16](descU + 24)[]
  elif toFromDs == 0x0200:
    # ToDS=0, FromDS=1: Addr1=DA, Addr2=BSSID, Addr3=SA
    cast[ptr uint16](hdrBufBase + 4)[] = cast[ptr uint16](descU + 20)[]
    cast[ptr uint16](hdrBufBase + 6)[] = cast[ptr uint16](descU + 22)[]
    cast[ptr uint16](hdrBufBase + 8)[] = cast[ptr uint16](descU + 24)[]
    # Addr3 from txdesc SA fields
    cast[ptr uint16](hdrBufBase + 16)[] = cast[ptr uint16](descU + 26)[]
    cast[ptr uint16](hdrBufBase + 18)[] = cast[ptr uint16](descU + 28)[]
    cast[ptr uint16](hdrBufBase + 20)[] = cast[ptr uint16](descU + 30)[]
  else:
    # No DS or WDS: Addr1=DA, Addr2=SA, Addr3=BSSID
    cast[ptr uint16](hdrBufBase + 4)[] = cast[ptr uint16](descU + 20)[]
    cast[ptr uint16](hdrBufBase + 6)[] = cast[ptr uint16](descU + 22)[]
    cast[ptr uint16](hdrBufBase + 8)[] = cast[ptr uint16](descU + 24)[]
    # For no-DS: look up VIF for BSSID at vif_entry + 380 region
    let vifBssid = vifEntry + 380
    let bssidAddr = cast[ptr uint16](vifBssid)[]
    cast[ptr uint16](hdrBufBase + 16)[] = bssidAddr
    let bssidAddr2 = cast[ptr uint16](vifBssid + 2)[]
    cast[ptr uint16](hdrBufBase + 18)[] = bssidAddr2
    let bssidAddr3 = cast[ptr uint16](vifBssid + 4)[]
    cast[ptr uint16](hdrBufBase + 20)[] = bssidAddr3

  when defined(bl808WifiConnectTrace):
    let protoTrace = cast[ptr uint16](descU + 32)[]
    if protoTrace == 0x8E88'u16:
      nimFwConnectTrace2U32("[WIFI-CT] tx_eapol_fc ",
                            fullFc.uint32 or (vifMode.uint32 shl 16),
                            cast[uint32](hdrBufBase))
      let addr1Trace = cast[ptr uint16](hdrBufBase + 4)[].uint32 or
        (cast[ptr uint16](hdrBufBase + 6)[].uint32 shl 16)
      let addr2Trace = cast[ptr uint16](hdrBufBase + 10)[].uint32 or
        (cast[ptr uint16](hdrBufBase + 12)[].uint32 shl 16)
      let addr3Trace = cast[ptr uint16](hdrBufBase + 16)[].uint32 or
        (cast[ptr uint16](hdrBufBase + 18)[].uint32 shl 16)
      nimFwConnectTrace2U32("[WIFI-CT] tx_eapol_a12 ", addr1Trace, addr2Trace)
      nimFwConnectTrace2U32("[WIFI-CT] tx_eapol_a3 ", addr3Trace, frameLen.uint32)
      let addrHi12Trace = cast[ptr uint16](hdrBufBase + 8)[].uint32 or
        (cast[ptr uint16](hdrBufBase + 14)[].uint32 shl 16)
      let addrHi3Trace = cast[ptr uint16](hdrBufBase + 20)[].uint32
      nimFwConnectTrace2U32("[WIFI-CT] tx_eapol_ahi ", addrHi12Trace, addrHi3Trace)
      nimFwConnectTrace2U32("[WIFI-CT] tx_eapol_snap ",
                            cast[ptr uint32](hdrBufBase + 24)[],
                            cast[ptr uint32](hdrBufBase + 28)[])

  # Check if NAV protection (RTS/CTS) is needed
  # Read the STA's HT capabilities for RTS threshold check
  if pairwiseKey != 0:
    let staHtCaps = cast[ptr uint32](vifEntry + 1496)[]
    if (staHtCaps and 2) != 0:
      # STA supports HT -- check if frame length exceeds RTS threshold
      let rtsThreshold = cast[ptr uint16](staEntry + 70)[]
      if rtsThreshold != frameLen:
        # Set "more data" / NAV protection bit in FC
        let fc0 = cast[ptr uint8](hdrBufBase)[]
        let fc1 = cast[ptr uint8](hdrBufBase + 1)[]
        var navFc = fc0.uint16 or (fc1.uint16 shl 8)
        navFc = navFc or 0x4000  # more data / nav
        let newFc1 = ((navFc shr 8) and 0xFF).uint8
        cast[ptr uint8](hdrBufBase)[] = (navFc and 0xFF).uint8
        cast[ptr uint8](hdrBufBase + 1)[] = newFc1

{.emit: "__attribute__((optimize(\"crossjumping\"))) void txu_cntrl_push(void*);".}
{.emit: "__attribute__((optimize(\"crossjumping\"))) void txu_cntrl_push(void*);".}
proc txu_cntrl_push*(param: pointer) {.exportc, cdecl.} =
  ## Push a TX frame from upper MAC to lower TX layer (154 instrs).
  ## From disassembly: this is the main TX data path entry point from the host.
  ## param is a txdesc (TX descriptor from host via IPC).
  ##
  ## Layout of txdesc (param) key fields:
  ##   [32..33] = uint16 frame_len
  ##   [42..43] = uint16 seq_num
  ##   [46]     = uint8 sta_idx
  ##   [47]     = uint8 vif_idx
  ##   [49]     = uint8 sta_info_idx
  ##   [88]     = pointer to upper desc / TX policy
  ##   [91]     = uint8 tx_flags (cleared to 0 before push)
  ##   [96..97] = uint16 seq_ctrl_out
  ##   [98]     = uint8 MAC/security header length
  ##   [99]     = uint8 QoS/SNAP extension length
  ##   [100]    = uint8 security tail length
  ##
  ## Function flow:
  ##   1. Check if sta_info_idx != 0xFF; if so, look up STA entry and check
  ##      if STA is active (sta_entry[42] != 0). If not active, go to L69 (drop).
  ##   2. Look up VIF entry from sta_info_idx -> check VIF encryption type.
  ##      If vif_entry[72] == 2 (AP mode), compare frame_len with VIF's current
  ##      channel BW at vif_entry[70]. If mismatch, go to L69 (drop/requeue).
  ##   3. Allocate TX buffer: calls txl_buffer_alloc for the frame
  ##   4. If allocation fails, go to L69 (drop path with error counters)
  ##   5. For sta_idx != 0xFF: compute sequence number from STA entry,
  ##      increment STA's per-TID sequence counter (offset varies by 4-addr)
  ##   6. Call txu_cntrl_frame_build to format the 802.11 header
  ##   7. Set up HW descriptor: compute frame length including header,
  ##      determine if frame needs encryption (FC ToDS/FromDS check for
  ##      frames > 1536 needing QoS), and set ht_flag
  ##   8. Call txl_machdr_format(txdesc, 0) for MAC header formatting
  ##   9. Call txl_cntrl_push_int(txdesc, ac) to push into lower MAC TX queue
  ##  10. Set txdesc[91] = 0 to clear TX flags
  ##  11. Tail-call to txl_cntrl_push(ac, txdesc) via indirect jump
  ##
  ## Drop path (L69): sets up error counters in stack (0x20000, 0x80000,
  ## 0x100000) and returns without transmitting.
  let descU = cast[uint](param)
  let staBase = cast[uint](addr sta_info_tab[0])
  let vifBase = cast[uint](addr vif_info_tab[0])

  # Blob ABI: a0=txdesc (param), a1=ac. Capture a1 since Nim only sees a0.
  var acFromCaller: pointer
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", acFromCaller, ") );"].}
  let ac = cast[uint8](cast[uint](acFromCaller))

  when defined(bl808WifiConnectTrace):
    let protoTrace = cast[ptr uint16](descU + 32)[]
    if protoTrace == 0x8E88'u16 or protoTrace == 0x888E'u16:
      nimFwConnectTrace2U32("[WIFI-CT] txu_push_eapol ",
                            ac.uint32 or (cast[ptr uint8](descU + 46)[].uint32 shl 8) or
                              (cast[ptr uint8](descU + 47)[].uint32 shl 16) or
                              (cast[ptr uint8](descU + HostTxStaInfoIdxOff)[].uint32 shl 24),
                            cast[uint32](cast[uint](cast[ptr pointer](descU + 8)[])))

  let staInfoIdx = cast[ptr uint8](descU + HostTxStaInfoIdxOff)[]
  var dropFrame = false

  # Step 1: Check STA validity
  if staInfoIdx != 0xFF:
    let staEntry = staBase + staInfoIdx.uint * STA_ENTRY_SIZE.uint
    let staActive = cast[ptr uint8](staEntry + 42)[]
    if staActive == 0:
      dropFrame = true

    if not dropFrame:
      # Step 2: Check STA type and channel/BW match (blob uses sta_info_tab, NOT vif)
      let staCheckEntry = staBase + staInfoIdx.uint * STA_ENTRY_SIZE.uint
      let staType = cast[ptr uint8](staCheckEntry + 72)[]
      if staType == 2:
        discard  # Type 2 (AP): skip BW check, proceed to .L70
      elif staType == 1:
        # Type 1 (STA): check frame len vs channel BW
        let frameLen = cast[ptr uint16](descU + 32)[]
        let chanBW = cast[ptr uint16](staCheckEntry + 70)[]
        if chanBW != frameLen:
          dropFrame = true
      else:
        # Unknown type: drop
        dropFrame = true

  # Step 2: Look up VIF for this frame
  let vifIdx = cast[ptr uint8](descU + 47)[]
  let vifEntryU = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint

  # Blob funnels the 3 drop paths (dropFrame / crypto-pending /
  # tx-not-ready) through a shared tail with one txl_cntrl_inc_pck_cnt
  # and one txl_cfm_push. Use a drop flag + computed errFlags.
  var doDrop = false
  var dropErrFlags: uint32 = 0
  if dropFrame:
    if vifIdx != 0:
      cast[ptr uint8](vifEntryU + 91)[] = 1
    doDrop = true
    dropErrFlags = 0xC0000000'u32 or vifIdx.uint32
  else:
    let vifCrypto = cast[ptr uint8](vifEntryU + 86)[]
    if vifCrypto == 0:
      let keyPtr = cast[ptr pointer](vifEntryU + 196)[]
      if keyPtr != nil:
        cast[ptr uint8](vifEntryU + 91)[] = 1
        doDrop = true
        dropErrFlags = 0xC0000001'u32
    if not doDrop and not txl_cntrl_tx_check(cast[pointer](vifEntryU)):
      cast[ptr uint8](vifEntryU + 91)[] = 1
      doDrop = true
      dropErrFlags = 0xC0000000'u32 or vifIdx.uint32
  if doDrop:
    txl_cntrl_inc_pck_cnt(ac)
    let irqState = irqSave()
    txl_cfm_push(param, dropErrFlags, ac.uint32)
    irqRestore(irqState)
    return

  # Step 4: Handle sequence number for data frames
  let staIdx = cast[ptr uint8](descU + 46)[]
  var hdrLen: uint16 = 24
  if staIdx != 0xFF:
    let staInfoForSeq = cast[ptr uint8](descU + HostTxStaInfoIdxOff)[]
    let staEntrySeq = staBase + staInfoForSeq.uint * STA_ENTRY_SIZE.uint
    hdrLen = 26
    let tidSeqBase = staEntrySeq + 24
    let seqNum = cast[ptr uint16](tidSeqBase + 4)[]
    let nextSeq = (seqNum + 1) and 0xFFF'u16
    cast[ptr uint16](tidSeqBase + 4)[] = nextSeq
    cast[ptr uint16](descU + 42)[] = seqNum

  # Step 5: Compute security header length.
  # Blob ABI: (a0=desc, a1=&secTailLenOut) -> returns secHdrLen in a0.
  # Previous Nim discarded the return and used the out-param as the header
  # length — wrong direction. Correct mapping:
  #   return value = sec HEADER length (IV) — added to frame hdr total
  #   *lenOut      = sec TAIL length (MIC/ICV) — written to desc[100]
  var secTailLenOut: uint32 = 0
  let secHdrLen = cast[uint8](txu_cntrl_sechdr_len_compute(param, addr secTailLenOut))
  let secTailLen = cast[uint8](secTailLenOut)

  # Step 6-8: Inline MAC header and descriptor setup (blob does NOT call
  # txu_cntrl_frame_build or txl_machdr_format — handles inline).
  # Blob at 0xe6-0x11e:
  #   desc[96]   = desc[12]                       ; seq_ctrl passthrough
  #   desc[98]   = sechdr_len + mac_hdr_base + (8 if frame_len > 1536 else 0)
  #   desc[99]   = 8 if frame_len > 1536 else 0   ; QoS/SNAP extension length
  #   desc[100]  = secTailLen                     ; MIC/ICV byte count
  let frameLen = cast[ptr uint16](descU + 32)[]
  var qosExt: uint8 = 0
  if frameLen > 1536:
    qosExt = 8
    hdrLen += 8

  cast[ptr uint16](descU + HostTxSeqOutOff)[] = cast[ptr uint16](descU + 12)[]
  cast[ptr uint8](descU + HostTxHdrLenOff)[] = (hdrLen + secHdrLen.uint16).uint8
  cast[ptr uint8](descU + HostTxQosExtOff)[] = qosExt
  cast[ptr uint8](descU + HostTxSecTailLenOff)[] = secTailLen
  when defined(bl808WifiConnectTrace):
    let protoTraceSec = cast[ptr uint16](descU + 32)[]
    if protoTraceSec == 0x8E88'u16 or protoTraceSec == 0x888E'u16:
      nimFwConnectTrace2U32("[WIFI-CT] txu_sec ",
                            secHdrLen.uint32 or (secTailLen.uint32 shl 8) or
                              (hdrLen.uint32 shl 16) or (qosExt.uint32 shl 24),
                            cast[ptr uint32](descU + HostTxPolicyOff)[])

  # Step 9: Rate control check (blob: call me_check_rc at 0x122)
  let staInfoForRate = cast[ptr uint8](descU + HostTxStaInfoIdxOff)[]
  me_check_rc(staInfoForRate)

  # Step 10: Update buffer control.
  # Blob ABI at 0x12a-0x138:
  #   lbu a4, 49(s0)            ; sta_info_idx
  #   li  a5, 368               ; STA_ENTRY_SIZE
  #   mv  a0, s4                ; s4 = sta_info_tab base
  #   .insn  (th.mula: a0 += a4*a5)   ; a0 = &sta_info_tab[sta_info_idx]
  #   call me_update_buffer_control
  #   sw  a0, 88(s0)             ; desc[88] = returned tx_policy pointer
  let staForPush = staBase + staInfoForRate.uint * STA_ENTRY_SIZE.uint
  let txPolicyForPush = me_update_buffer_control(cast[pointer](staForPush))

  # Step 11: Store result, clear flags, tail-call txl_cntrl_push
  cast[ptr pointer](descU + HostTxPolicyOff)[] = txPolicyForPush
  cast[ptr uint8](vifEntryU + 91)[] = 0

  # Tail-call to txl_cntrl_push (blob: a0=desc, a1=ac; jr t1 at 0x162)
  discard txl_cntrl_push(param, ac)

proc txu_cntrl_cfm*(param: pointer) {.exportc, cdecl.} =
  ## Handle TX upper confirmation (11 instrs in blob).
  ## From disassembly: reads the THD chain pointer from the descriptor,
  ## sets the confirm-done bit (bit 0) in THD[16], writes 0x0101 to THD[12]
  ## (confirm type), clears the ke_msg linkage word at param[-4], then
  ## copies THD[16] to the confirm pointer at param[16].
  let descAddr = cast[uint](param)
  # a5 = lw desc[112] -> HW descriptor pointer
  let hwDescPtr = cast[ptr pointer](descAddr + HostTxHwDescOff)[]
  let hwDescAddr = cast[uint](hwDescPtr)
  # a5 = lw 0(hwDescPtr) -> THD base (first word of HW desc is THD addr)
  let thdBase = cast[ptr pointer](hwDescAddr)[]
  let thdAddr = cast[uint](thdBase)
  # a3 = lw desc[16] -> confirm destination pointer
  let cfmDstPtr = cast[ptr pointer](descAddr + 16)[]
  let cfmDstAddr = cast[uint](cfmDstPtr)
  # THD[16] |= 1  (set confirm-done bit)
  var statusWord = cast[ptr uint32](thdAddr + 16)[]
  statusWord = statusWord or 1
  cast[ptr uint32](thdAddr + 16)[] = statusWord
  # THD[12] = 0x0101  (confirm type/status = 257)
  cast[ptr uint16](thdAddr + 12)[] = 0x0101'u16
  # Clear ke_msg linkage at param[-4]
  cast[ptr uint32](descAddr - 4)[] = 0
  # Copy final THD[16] to confirm pointer
  let finalStatus = cast[ptr uint32](thdAddr + 16)[]
  cast[ptr uint32](cfmDstAddr)[] = finalStatus

proc txu_cntrl_tkip_mic_append*(txdesc: pointer) {.exportc, cdecl.} =
  ## Append TKIP MIC to TX frame (109 instrs).
  ## a0 = TX descriptor.
  ## Looks up STA entry from txdesc[49] (STA index), finds the key-holder at
  ## sta[244], then loads the actual key slot from holder[0]. If no key slot is
  ## installed, returns immediately.
  ## Checks key type at key[152]: type 1 = pairwise, type 3 = group.
  ## Sets up MIC context from key material (key+72 or key+48 area), computes
  ## MIC over frame header fields (SA, DA, priority) then frame body.
  ## Writes final 8-byte MIC at end of frame data.
  let descAddr = cast[uint](txdesc)
  let staIdx = cast[ptr uint8](descAddr + HostTxStaInfoIdxOff)[]
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  # Blob ABI: sta+244 points at a key-holder; holder[0] is the key slot.
  let keyHolder = cast[ptr pointer](staEntry + 244)[]
  if keyHolder == nil:
    return
  let keySlot = cast[ptr pointer](cast[uint](keyHolder))[]
  if keySlot == nil:
    return
  let keyAddr = cast[uint](keySlot)
  let keyType = cast[ptr uint8](keyAddr + 152)[]
  let linkDesc = cast[ptr pointer](descAddr + HostTxBufDescOff)[]
  let linkAddr = cast[uint](linkDesc)
  # Determine MIC key offset based on key type
  var micKeyOff: uint
  if keyType == 1:
    # Pairwise TKIP: MIC TX key at key+48+24 = key+72
    micKeyOff = 72
  elif keyType == 3:
    # Group TKIP: MIC TX key at key+48
    micKeyOff = 48
  else:
    return
  # Check if MIC calculation context already set up (key+72 or similar area has ptr at +4)
  let micAreaBase = keyAddr + micKeyOff - 24
  let existingPtr = cast[ptr pointer](micAreaBase + 4)[]
  if existingPtr != nil:
    return  # MIC already in progress
  # Set up MIC context at linkDesc+316..348 area
  # Layout: [316]=magic(0xCAFEFADE), [320]=L_init, [324]=data_ptr, [328]=end_ptr, [332]=pending
  cast[ptr pointer](micAreaBase + 4)[] = cast[pointer](linkAddr + 316)
  cast[ptr pointer](linkAddr + 324)[] = cast[pointer](linkAddr + 336)
  if keyType == 1:
    cast[ptr pointer](linkAddr + 328)[] = cast[pointer](linkAddr + 339)
  else:
    cast[ptr pointer](linkAddr + 328)[] = cast[pointer](linkAddr + 347)
  cast[ptr uint32](linkAddr + 316)[] = 0xCAFEFADE'u32
  cast[ptr uint32](linkAddr + 332)[] = 0
  cast[ptr uint32](linkAddr + 320)[] = 0
  if keyType == 1:
    # For pairwise: build MIC header from frame header addresses
    # Extract header fields for MIC init
    let priority = cast[ptr uint8](descAddr + 46)[]
    let payloadLen = cast[ptr uint8](descAddr + HostTxQosExtOff)[]
    # Get payload pointer from link descriptor
    let payloadPtr = cast[ptr pointer](descAddr + HostTxBufDescOff)[]
    let frameHdr = cast[uint](payloadPtr) + 348  # MAC header starts at link+348
    # Initialize MIC: da (link+352), sa (link+358)
    var micCtx {.noinit.}: array[16, uint8]
    let micCtxPtr = cast[pointer](addr micCtx[0])
    let keyMaterial = cast[pointer](keyAddr + micKeyOff)
    me_mic_init(micCtxPtr, keyMaterial,
                cast[pointer](descAddr + 26),  # SA
                cast[pointer](descAddr + 20),  # DA
                priority)
    # Pass 1: MIC over the pseudo-header fields (blob: me_mic_calc at 0xe0,
    # me_mic_end at 0xf4). TKIP MIC spec requires hashing DA||SA||priority||pad
    # as a separate stream so the end marker flushes the partial block.
    let hdrStart = cast[pointer](descAddr + 20)  # DA+SA block in descriptor
    me_mic_calc(micCtxPtr, hdrStart, 14.uint32)  # DA(6)+SA(6)+prio(1)+pad(1)
    me_mic_end(micCtxPtr)
    # Pass 2: MIC over frame body (blob: me_mic_calc at 0x12c, me_mic_end at 0x13e)
    let bodyStart = linkAddr + 348 + 26  # skip MAC header
    let bodyLen = payloadLen
    me_mic_calc(micCtxPtr, cast[pointer](bodyStart), bodyLen.uint32)
    # Finalize and write MIC
    me_mic_end(micCtxPtr)
    # Copy 8-byte MIC result to end of frame
    let txPayloadEnd = cast[ptr pointer](descAddr + HostTxBufDescOff)[]
    let endOff = cast[ptr uint32](linkAddr + 76)[]
    let micDst = cast[ptr UncheckedArray[uint8]](linkAddr + 316)
    let micResult = cast[ptr UncheckedArray[uint8]](micCtxPtr)
    for i in 0 ..< 8:
      micDst[i] = micResult[i]
  else:
    # Group key MIC: similar but with different addresses
    discard

proc txu_cntrl_protect_mgmt_frame*(param: pointer, hdrPtr: pointer, extraLen: uint32) {.exportc, cdecl.} =
  ## Apply management frame protection (108 bytes in blob).
  ## Blob: checks cached sechdr_len at param[98], computes if needed,
  ## sets Protected Frame bit (0x4000) in frame header, then appends security header.
  let descAddr = cast[uint](param)
  var secHdrLen: uint8
  var secTailLen: uint8
  let cachedLen = cast[ptr uint8](descAddr + 98)[]
  if cachedLen == 0:
    # Not cached: compute security header length
    var tailLen: uint32 = 0
    secHdrLen = cast[uint8](txu_cntrl_sechdr_len_compute(param, addr tailLen))
    secTailLen = cast[uint8](tailLen)
    # Cache the results in descriptor
    cast[ptr uint8](descAddr + 98)[] = secHdrLen
    cast[ptr uint8](descAddr + 100)[] = secTailLen
  else:
    # Use cached values
    secHdrLen = cachedLen
    secTailLen = cast[ptr uint8](descAddr + 100)[]
  # Set Protected Frame bit (0x4000) in frame header bytes
  let hdrAddr = cast[uint](hdrPtr)
  let fc0 = cast[ptr uint8](hdrAddr)[]
  let fc1 = cast[ptr uint8](hdrAddr + 1)[]
  let fc16 = fc0.uint16 or (fc1.uint16 shl 8)
  let protFc = fc16 or 0x4000'u16
  cast[ptr uint8](hdrAddr)[] = cast[uint8](protFc and 0xFF)
  cast[ptr uint8](hdrAddr + 1)[] = cast[uint8]((protFc shr 8) and 0xFF)
  # Compute position for security header: hdrPtr + extraLen + secHdrLen
  let secHdrPos = cast[pointer](hdrAddr + extraLen.uint + secHdrLen.uint)
  # Append security header (blob: txu_cntrl_sec_hdr_append(param, secHdrPos))
  discard txu_cntrl_sec_hdr_append(param, secHdrPos, 0'u32)

# ###########################################################################
#                   RX LAYER (rxl_*)
# ###########################################################################

proc rx_swdesc_init*() {.exportc, cdecl.} =
  ## Initialize RX software descriptors.
  ## Blob layout is 41 entries of 24 bytes. Each software descriptor stores its
  ## paired RX header descriptor at offset +4.
  let swBase = cast[uint](addr rx_swdesc_tab[0])
  let hdBase = cast[uint](addr rx_dma_hdrdesc[0])
  for i in 0'u ..< 41'u:
    cast[ptr pointer](swBase + i * 24'u + 4'u)[] =
      cast[pointer](hdBase + i * 100'u)

proc rxl_hwdesc_init*(resetAll: uint32) {.exportc, cdecl.} =
  ## Initialize RX HW descriptors and program DMA.
  ## From disassembly (159 instrs): Allocates a scratch buffer via
  ## g_bl_ops_funcs[20] (platform alloc), then initializes two descriptor chains:
  ##
  ## 1. HD (Header Descriptor) chain: 41 entries, stride 100 bytes each.
  ##    Each HD is initialized with 0xBAADF00D magic if DMA-owned (field[96]==1).
  ##    Fields cleared: [16,20,64,24,8,28] = 0. Chain linked via [4] pointers.
  ##    HD head written to MAC register 0x24B081B8. Trigger 0x4000000 -> 0x24B08180.
  ##
  ## 2. PD (Payload Descriptor) chain: 41 entries, stride 52 bytes each.
  ##    Each PD is initialized with 0xC0DEDBAD magic if DMA-owned (field[20]==1).
  ##    Fields cleared: [16,4,8,0,24] = 0, [12] = next desc addr.
  ##    PD head written to MAC register 0x24B081BC. Trigger 0x8000000 -> 0x24B08180.
  ##
  ## 3. Stores chain head/tail pointers into rxl_hwdesc_env.
  ## 4. Tail-calls g_bl_ops_funcs[24] (platform free) to release scratch buffer.
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  # Get platform alloc function from g_bl_ops_funcs[20]
  let allocFnPtr = cast[ptr pointer](opsBase + 20)[]
  if allocFnPtr == nil: return
  type AllocFn = proc(): pointer {.cdecl.}
  type FreeFn = proc(p: pointer) {.cdecl.}
  let allocFn = cast[AllocFn](allocFnPtr)
  let scratchBuf = allocFn()
  # Constants
  const BAADF00D = 0xBAADF00D'u32
  const C0DEDBAD = 0xC0DEDBAD'u32
  const HD_COUNT = 41
  const HD_STRIDE = 100
  const PD_COUNT = 41
  const PD_STRIDE = 52
  const MAC_RX_HD_REG = 0x24B081B8'u  # HD chain head register
  const MAC_RX_PD_REG = 0x24B081BC'u  # PD chain head register
  const MAC_TRIGGER_REG = 0x24B08180'u
  # Initialize HD chain
  # HD descriptors are in a contiguous block; we walk through checking DMA ownership
  var hdCurrent: pointer = nil
  var hdHead: pointer = nil
  var hdTail: pointer = nil
  var hdPrev: pointer = nil
  var hdCount: uint32 = 0
  let hdBase = cast[uint](addr rx_dma_hdrdesc[0])  # blob: sym rx_dma_hdrdesc
  let swBase = cast[uint](addr rx_swdesc_tab[0])
  for i in 0 ..< HD_COUNT:
    let hdAddr = hdBase + i.uint * HD_STRIDE.uint
    let dmaOwned = cast[ptr uint32](hdAddr + 96)[]
    if resetAll != 0 or dmaOwned != 1:
      if hdPrev != nil:
        cast[ptr pointer](cast[uint](hdPrev) + 4)[] = cast[pointer](hdAddr)
      # Initialize descriptor fields
      let nextAddr = hdBase + (i + 1).uint * HD_STRIDE.uint
      cast[ptr uint32](hdAddr + 16)[] = 0   # next THD
      cast[ptr uint32](hdAddr + 20)[] = 0   # status
      cast[ptr uint32](hdAddr + 64)[] = 0   # flags
      cast[ptr uint32](hdAddr + 24)[] = 0   # reserved
      cast[ptr uint32](hdAddr + 8)[]  = 0   # buf ptr
      cast[ptr uint32](hdAddr + 12)[] = cast[uint32](swBase + i.uint * 24'u)
      cast[ptr uint32](hdAddr + 0)[]  = BAADF00D  # magic
      cast[ptr uint32](hdAddr + 4)[]  = cast[uint32](nextAddr)
      cast[ptr uint16](hdAddr + 28)[] = 0   # status half
      hdPrev = cast[pointer](hdAddr)
      if hdCount == 0:
        hdCurrent = cast[pointer](hdAddr)
      elif hdCount == 1:
        hdHead = cast[pointer](hdAddr)
      hdTail = cast[pointer](hdAddr)
      hdCount += 1
    else:
      if hdPrev != nil:
        cast[ptr pointer](cast[uint](hdPrev) + 4)[] = nil
  # Terminate HD chain
  if hdPrev != nil:
    cast[ptr pointer](cast[uint](hdPrev) + 4)[] = nil
  # Write HD head to MAC register
  regWrite(MAC_RX_HD_REG, cast[uint32](hdHead))
  # Trigger HD DMA: write 0x4000000 to trigger register
  regWrite(MAC_TRIGGER_REG, 0x04000000'u32)
  # Initialize PD chain
  var pdCurrent: pointer = nil
  var pdHead: pointer = nil
  var pdTail: pointer = nil
  var pdPrev: pointer = nil
  var pdCount: uint32 = 0
  for i in 0 ..< PD_COUNT:
    let pdAddr = cast[uint](addr rx_payload_desc[0]) + i.uint * PD_STRIDE.uint
    let dmaOwned = cast[ptr uint32](pdAddr + 20)[]
    if resetAll != 0 or dmaOwned != 1:
      # Initialize PD descriptor
      if pdPrev != nil:
        cast[ptr pointer](cast[uint](pdPrev) + 4)[] = cast[pointer](pdAddr)
      let nextAddr = cast[uint](addr rx_payload_desc[0]) + (i + 1).uint * PD_STRIDE.uint
      let bufAddr = cast[uint](addr rx_payload_desc_buffer[0]) + i.uint * 1736'u
      cast[ptr uint32](pdAddr + 0)[]  = C0DEDBAD  # magic
      cast[ptr uint32](pdAddr + 4)[]  = cast[uint32](nextAddr)
      cast[ptr uint32](pdAddr + 16)[] = 0   # status
      cast[ptr uint32](pdAddr + 8)[]  = cast[uint32](bufAddr)
      cast[ptr uint32](pdAddr + 12)[] = cast[uint32](bufAddr + 1735'u)
      cast[ptr uint32](pdAddr + 24)[] = cast[uint32](bufAddr)
      pdPrev = cast[pointer](pdAddr)
      if pdCount == 0:
        pdCurrent = cast[pointer](pdAddr)
      elif pdCount == 1:
        pdHead = cast[pointer](pdAddr)
      pdTail = cast[pointer](pdAddr)
      pdCount += 1
    else:
      if pdPrev != nil:
        cast[ptr pointer](cast[uint](pdPrev) + 4)[] = nil
  # Terminate PD chain
  if pdPrev != nil:
    cast[ptr pointer](cast[uint](pdPrev) + 4)[] = nil
  # Write PD head to MAC register
  regWrite(MAC_RX_PD_REG, cast[uint32](pdHead))
  # Trigger PD DMA: write 0x8000000 to trigger register
  regWrite(MAC_TRIGGER_REG, 0x08000000'u32)
  # Sanity check: all chain pointers should be non-nil
  if hdCurrent == nil or hdHead == nil or hdTail == nil or pdCurrent == nil or pdHead == nil or pdTail == nil:
    # Log error via g_bl_ops_funcs[4]
    let logPtr = cast[ptr pointer](opsBase + 4)[]
    if logPtr != nil:
      type LogFn = proc(fmt: cstring, a: pointer, b: pointer, c: pointer, d: pointer, e: pointer) {.cdecl.}
      let logFn = cast[LogFn](logPtr)
      logFn("rxl_hwdesc.c", hdHead, hdTail, pdHead, pdTail, nil)
  # Store chain pointers — blob splits across TWO structures:
  # rxl_cntrl_env offsets 8,12,16: submitted HD head, HD tail, current HD.
  # rx_hwdesc_env offsets 0,4: PD tail/current.
  let rxlCntrlEnv = cast[uint](addr rxl_cntrl_env[0])
  cast[ptr pointer](rxlCntrlEnv + 8)[]  = hdHead
  cast[ptr pointer](rxlCntrlEnv + 12)[] = hdTail
  cast[ptr pointer](rxlCntrlEnv + 16)[] = hdCurrent
  let rxHwDescEnv = cast[uint](addr rx_hwdesc_env[0])
  cast[ptr pointer](rxHwDescEnv + 0)[] = pdTail
  cast[ptr pointer](rxHwDescEnv + 4)[] = pdCurrent
  # Free scratch buffer via g_bl_ops_funcs[24] (platform free)
  let freeFnPtr = cast[ptr pointer](opsBase + 24)[]
  if freeFnPtr != nil:
    let freeFn = cast[FreeFn](freeFnPtr)
    freeFn(scratchBuf)

proc rxl_init*() {.exportc, cdecl.} =
  ## Initialize RX layer (50b in blob, 4 calls).
  ## Blob: rxl_hwdesc_init(1), rx_swdesc_init(), co_list_init(rxl_cntrl_env), rxu_cntrl_init()
  rxl_hwdesc_init(1)
  rx_swdesc_init()
  co_list_init(cast[ptr CoList](addr rxl_cntrl_env[0]))
  rxu_cntrl_init()

proc rxl_reset*() {.exportc, cdecl.} =
  ## Reset RX layer — blob rxl_cntrl.o::rxl_reset (46 bytes, 3 calls):
  ##   rxl_hwdesc_init(0)
  ##   co_list_init(&rxl_cntrl_env)        # primary RX cntrl queue
  ##   co_list_init(&rxu_cntrl_env + 0x40) # (tail-call) upload list
  ## Previous Nim called rx_swdesc_init / rxu_cntrl_init which do a superset
  ## of work — that duplicates state resets and diverges from blob's behavior
  ## when other reset sequences call those separately.
  rxl_hwdesc_init(0)
  co_list_init(cast[ptr CoList](addr rxl_cntrl_env[0]))
  # rxu_cntrl_env is declared further down in the module; reach it via the
  # exported C symbol so we don't need a Nim forward declaration.
  var uploadList: ptr CoList
  {.emit: ["extern unsigned char rxu_cntrl_env[];\n",
          uploadList, " = (void*)(rxu_cntrl_env + 0x40);"].}
  co_list_init(uploadList)

proc rxl_hwdesc_dump*() {.exportc, cdecl, noinline.} =
  ## Dump RX HW descriptor state for debugging.
  ## From disassembly (159 instrs in full dump variant): Uses g_bl_ops_funcs
  ## function pointers to print all RX HW descriptor chain state.
  ##
  ## Structure:
  ##   1. Print header via g_bl_ops_funcs[8] (puts-like)
  ##   2. Print separator line via g_bl_ops_funcs[4] (printf-like with count=41)
  ##   3. Get chain start via g_bl_ops_funcs[20] (timestamp/snapshot)
  ##   4. Loop 41 times over HD chain (stride 100), printing:
  ##      - HD address, fields [0..12] via g_bl_ops_funcs[4] (7-arg format)
  ##      - HD fields [16..30] via g_bl_ops_funcs[4] (6-arg format)
  ##      - HD fields [32..64] via g_bl_ops_funcs[4] (9-arg format)
  ##   5. Get PD chain snapshot via g_bl_ops_funcs[24]
  ##   6. Print PD separator via g_bl_ops_funcs[4]
  ##   7. Loop 41 times over PD chain (stride 52), printing:
  ##      - PD fields with computed length (end-start if non-zero)
  ##
  ## This is purely diagnostic; safe to implement as a logging pass.
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  let logFuncPtr = cast[ptr pointer](opsBase + 4)[]
  if logFuncPtr == nil: return
  let putsFuncPtr = cast[ptr pointer](opsBase + 8)[]
  type PutsFn = proc(s: cstring) {.cdecl.}
  type PrintFn = proc(fmt: cstring) {.cdecl, varargs.}
  let printFn = cast[PrintFn](logFuncPtr)
  # Print header
  if putsFuncPtr != nil:
    let putsFn = cast[PutsFn](putsFuncPtr)
    putsFn("rxl_hwdesc dump")
  # Print HD chain header with count
  printFn("HD chain (%d entries):", 41)
  # Get HD chain base from rxl_hwdesc_env
  let rxlEnv = cast[uint](addr rxl_hwdesc_env[0])
  # Snapshot function for timing (g_bl_ops_funcs[20])
  let snapFuncPtr = cast[ptr pointer](opsBase + 20)[]
  var snapResult: pointer = nil
  if snapFuncPtr != nil:
    type SnapFn = proc(): pointer {.cdecl.}
    snapResult = cast[SnapFn](snapFuncPtr)()
  # Walk HD chain - 41 entries, stride 100 (blob sym: rx_dma_hdrdesc)
  let hdBase = cast[uint](addr rx_dma_hdrdesc[0])
  for i in 0'u32 ..< 41:
    let hdAddr = hdBase + i * 100
    let w0 = cast[ptr uint32](hdAddr + 0)[]
    let w1 = cast[ptr uint32](hdAddr + 4)[]
    let w2 = cast[ptr uint32](hdAddr + 8)[]
    let w3 = cast[ptr uint32](hdAddr + 12)[]
    printFn("HD[%d] @%p: %08x %08x %08x %08x", i, hdAddr, w0, w1, w2, w3)
    let w4 = cast[ptr uint32](hdAddr + 16)[]
    let w5 = cast[ptr uint32](hdAddr + 20)[]
    let w6 = cast[ptr uint32](hdAddr + 24)[]
    let h7 = cast[ptr uint16](hdAddr + 28)[]
    let h8 = cast[ptr uint16](hdAddr + 30)[]
    printFn("  %08x %08x %08x %04x %04x", w4, w5, w6, h7, h8)
    let w9  = cast[ptr uint32](hdAddr + 32)[]
    let w10 = cast[ptr uint32](hdAddr + 36)[]
    let w11 = cast[ptr uint32](hdAddr + 44)[]
    let w12 = cast[ptr uint32](hdAddr + 48)[]
    let w13 = cast[ptr uint32](hdAddr + 52)[]
    let w14 = cast[ptr uint32](hdAddr + 56)[]
    let w15 = cast[ptr uint32](hdAddr + 60)[]
    let w16 = cast[ptr uint32](hdAddr + 64)[]
    printFn("  %08x %08x %08x %08x %08x %08x %08x %08x", w9, w10, w11, w12, w13, w14, w15, w16)
  # Restore/free snapshot
  if snapFuncPtr != nil and snapResult != nil:
    let freeFuncPtr = cast[ptr pointer](opsBase + 24)[]
    if freeFuncPtr != nil:
      type FreeFn = proc(p: pointer) {.cdecl.}
      cast[FreeFn](freeFuncPtr)(snapResult)
  # Print PD chain
  printFn("PD chain (%d entries):", 41)
  for i in 0'u32 ..< 41:
    let pdAddr = hdBase + 41'u * 100 + i * 52
    let w0 = cast[ptr uint32](pdAddr + 0)[]
    let w1 = cast[ptr uint32](pdAddr + 4)[]
    let w2 = cast[ptr uint32](pdAddr + 8)[]
    let w3 = cast[ptr uint32](pdAddr + 12)[]
    # Compute length: if end != 0 then end+1-start else 0
    let endAddr = cast[ptr uint32](pdAddr + 12)[]
    let startAddr = cast[ptr uint32](pdAddr + 8)[]
    var pktLen: uint32 = 0
    if endAddr != 0:
      pktLen = endAddr + 1 - startAddr
    let h4 = cast[ptr uint16](pdAddr + 16)[]
    let h5 = cast[ptr uint16](pdAddr + 18)[]
    printFn("PD[%d] @%p: %08x %08x %08x %08x len=%d %04x %04x",
            i, pdAddr, w0, w1, w2, w3, pktLen, h4, h5)

proc rxl_hd_append*(desc: pointer) {.exportc, cdecl.} =
  ## Append a header descriptor to the RX HD chain.
  ## From disassembly (38 instrs): asserts desc non-nil, reads MAC HW RX header
  ## head (0x24B08548), manages HD chain in rxl_hwdesc_env[8..16], clears desc
  ## fields, links into chain, writes 0x10000000 to trigger (0x24B08180).
  if desc == nil:
    assert_err("rxl_hwdesc.c", "rxl_hwdesc.c", 267)
    return
  let envBase = cast[uint](addr rxl_cntrl_env[0])
  let hwHead = regRead(0x24B08548'u)
  var appendDesc = desc
  let envCur = cast[ptr uint32](envBase + 16)[]
  if envCur != hwHead:
    cast[ptr uint32](envBase + 16)[] = cast[uint32](desc)
    appendDesc = cast[pointer](envCur)
  let dAddr = cast[uint](appendDesc)
  cast[ptr uint32](dAddr + 4)[] = 0
  cast[ptr uint32](dAddr + 8)[] = 0
  let lastPtr = cast[ptr uint32](envBase + 12)[]
  cast[ptr uint32](dAddr + 64)[] = 0
  cast[ptr uint16](dAddr + 28)[] = 0
  if lastPtr != 0:
    cast[ptr uint32](cast[uint](lastPtr) + 4)[] = cast[uint32](appendDesc)
  regWrite(0x24B08180'u, 0x10000000'u32)
  let firstPtr = cast[ptr uint32](envBase + 8)[]
  cast[ptr uint32](envBase + 12)[] = cast[uint32](appendDesc)
  if firstPtr == 0:
    cast[ptr uint32](envBase + 8)[] = cast[uint32](appendDesc)

proc rxl_pd_append*(swdesc: pointer, prevDesc: pointer, pddesc: pointer) {.exportc, cdecl.} =
  ## Append a payload descriptor to the RX PD chain.
  ## From disassembly (48 instrs): asserts pddesc non-nil, reads MAC HW RX
  ## payload head (0x24B0854C), manages PD chain in rxl_hwdesc_env[0..4],
  ## links pddesc, clears status, writes 0x20000000 to trigger (0x24B08180).
  if pddesc == nil:
    assert_err("rxl_hwdesc.c", "rxl_hwdesc.c", 314)
    return
  let envBase = cast[uint](addr rx_hwdesc_env[0])
  let hwPdHead = regRead(0x24B0854C'u)
  let pdAddr = cast[uint](pddesc)
  let envTail = cast[ptr uint32](envBase + 4)[]
  if envTail == hwPdHead:
    cast[ptr uint16](pdAddr + 16)[] = 0
  else:
    cast[ptr uint32](envBase + 4)[] = cast[uint32](pddesc)
    if prevDesc != nil:
      cast[ptr uint32](cast[uint](swdesc) + 4)[] = cast[uint32](pddesc)
    cast[ptr uint16](pdAddr + 16)[] = 0
  let oldLast = cast[ptr uint32](envBase + 0)[]
  cast[ptr uint32](pdAddr + 4)[] = 0
  if oldLast != 0:
    cast[ptr uint32](cast[uint](oldLast) + 4)[] = cast[uint32](pddesc)
  regWrite(0x24B08180'u, 0x20000000'u32)
  cast[ptr uint32](envBase + 0)[] = cast[uint32](pddesc)

proc rxl_frame_release*(desc: pointer) {.exportc, cdecl.} =
  ## Release an RX frame buffer back to the descriptor chain.
  ## From disassembly (16 instrs): reads sw_desc from desc[4], extracts
  ## buffer info, calls rxl_pd_append then tail-calls rxl_hd_append.
  let descAddr = cast[uint](desc)
  let swDesc = cast[ptr pointer](descAddr + 4)[]
  let swDescAddr = cast[uint](swDesc)
  let bufChain = cast[pointer](cast[ptr uint32](swDescAddr + 8)[])
  let prevDesc = cast[pointer](cast[ptr uint32](descAddr + 12)[])
  let pdDesc = cast[pointer](cast[ptr uint32](descAddr + 16)[])
  rxl_pd_append(bufChain, prevDesc, pdDesc)
  rxl_hd_append(swDesc)

proc rxl_mpdu_free*(desc: pointer) {.exportc, cdecl.} =
  ## Free an RX MPDU and all associated descriptors.
  ## From disassembly (54 instrs): loads sw_desc from desc[4], walks the HW
  ## descriptor chain from sw_desc[8]. Calls env[20] get_status, clears
  ## sw_desc[96], then walks chain checking status[16] bit 0. When DMA-owned
  ## descriptor found, saves state, calls rxl_frame_release. Chain exhausted
  ## triggers assert_rec. Finally calls env[24] cleanup.
  let descAddr = cast[uint](desc)
  let swDescPtr = cast[ptr pointer](descAddr + 4)[]
  let swDescAddr = cast[uint](swDescPtr)
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  var curHw = cast[uint](cast[ptr uint32](swDescAddr + 8)[])
  # Call platform get_status via env[20]
  let getStatusFn = cast[ptr pointer](opsBase + 20)[]
  var savedStatus: pointer = nil
  if getStatusFn != nil:
    savedStatus = cast[proc(): pointer {.cdecl.}](getStatusFn)()
  cast[ptr uint32](swDescAddr + 96)[] = 0
  var prevHw: uint32 = 0
  while true:
    let hwStatus = cast[ptr uint16](curHw + 16)[]
    cast[ptr uint32](curHw + 20)[] = 0
    if (hwStatus and 1) != 0:
      # DMA owned -- save position and release
      cast[ptr pointer](descAddr + 16)[] = cast[pointer](curHw)
      cast[ptr uint32](descAddr + 12)[] = prevHw
      rxl_frame_release(desc)
      let cleanFn = cast[ptr pointer](opsBase + 24)[]
      if cleanFn != nil:
        cast[proc(a: pointer) {.cdecl.}](cleanFn)(savedStatus)
      return
    let nextHw = cast[ptr uint32](curHw + 4)[]
    prevHw = cast[uint32](curHw)
    if nextHw == 0:
      break
    curHw = cast[uint](nextHw)
  assert_rec("rxl_hwdesc.c", "rxl_hwdesc.c", 872)
  let cleanFn = cast[ptr pointer](opsBase + 24)[]
  if cleanFn != nil:
    cast[proc(a: pointer) {.cdecl.}](cleanFn)(savedStatus)

proc rxl_mpdu_transfer*(desc: pointer) {.exportc, cdecl.} =
  ## Transfer RX MPDU to host via DMA (42 instrs in blob).
  ## From blob: desc is a wrapper struct. desc[4] = swDesc pointer.
  ## Reads swDesc[8] to get the HW descriptor chain head (s1).
  ## Initializes swDesc[68] area (co_list_init or memset).
  ## Zeroes desc[21] (dmaCount). Walks HW descriptor chain:
  ##   - Check status[16] bit 0: if DMA-owned, save to desc[12]/[16] and return.
  ##   - Otherwise increment dmaCount in desc[21], follow next at offset 4.
  ## If chain exhausted (next==nil): tail-call rxl_mpdu_free(desc) for cleanup.
  if desc == nil: return
  let descU = cast[uint](desc)
  let swDescPtr = cast[ptr pointer](descU + 4)[]
  if swDescPtr == nil: return
  let swDescU = cast[uint](swDescPtr)
  # Get current PHY channel info into swDesc+68 (blob: phy_get_channel(swDesc+68, 0)).
  phy_get_channel_raw(cast[pointer](swDescU + 68), 0)
  # Get HW descriptor chain head from swDesc[8]
  var cur = cast[ptr RxHwDesc](cast[ptr uint32](swDescU + 8)[])
  # Clear dmaCount at desc[21]
  cast[ptr uint8](descU + 21)[] = 0
  var prev: ptr RxHwDesc = nil
  while cur != nil:
    let status = cast[ptr uint16](cast[uint](cur) + 16)[]
    if (status and 1) != 0:
      # DMA still owns this descriptor -- save state and return
      cast[ptr pointer](descU + 12)[] = cast[pointer](prev)
      cast[ptr pointer](descU + 16)[] = cast[pointer](cur)
      return
    # Increment dmaCount
    let cnt = cast[ptr uint8](descU + 21)[]
    cast[ptr uint8](descU + 21)[] = cnt + 1
    # Follow next pointer at offset 4
    let nextPtr = cast[ptr pointer](cast[uint](cur) + 4)[]
    if nextPtr == nil:
      # Chain exhausted without finding DMA-owned descriptor: assert
      assert_rec("rxl_mpdu.c", "rxl_mpdu.c", 160)
      return
    prev = cur
    cur = cast[ptr RxHwDesc](nextPtr)

proc rxl_cntrl_evt*() {.exportc, cdecl.} =
  ## RX control event handler (352 instrs).
  ## From disassembly: main RX processing loop that dequeues received frames
  ## from the MAC HW DMA engine and dispatches them to upper-MAC handlers.
  ##
  ## The blob processes up to 5 frames per invocation (loop counter on stack[0]).
  ## For each frame iteration:
  ##   1. Read current RX HW descriptor from rxl_hwdesc_env[0] (-> s6)
  ##   2. Call hal_machw_disable_int(0x100000) to mask RX interrupts
  ##   3. Check rxl_hwdesc_env[24] != 0 (processing flag) -> exit
  ##   4. Check s6 == NULL -> exit
  ##   5. Decrement loop counter; if 0 -> tail-call hal_machw_enable_int(0x100000)
  ##   6. csrrci mstatus,8 to disable IRQs; call rxl_mpdu_transfer(s1); restore
  ##   7. s8 = s6[4] (SW descriptor); s2 = s8[8] (buf chain); assert s2 != nil
  ##   8. s5 = s8[64] (HW status flags)
  ##   9. Check (s5 & 0x20020000) == 0x20020000 -> valid + associated
  ##  10. bfext s5 to get STA index, sta_entry = sta_info_tab[idx*368]
  ##  11. Check sta_entry[42] (active flag); extract vif_idx from sta_entry[39]
  ##  12. s1 = vif_info_tab[vif_idx * 1512]; check vif_entry[86] (crypto)
  ##  13. Frame type dispatch on (frameCtrl & 0xFC):
  ##      - 0x88 (QoS Data): check BA state at sta[73], handle reorder
  ##      - 0xA4 (Action/BAR): send BAR indication to BAM task
  ##      - 0x80 (Data): route to rxu_cntrl_frame_handle
  ##  14. Release frame via rxl_mpdu_free(s6)
  ##  15. Loop or exit
  ##
  ## The function also handles:
  ##   - Per-VIF BA window tracking and advance
  ##   - Sending ke_msg for BAR/ADDBA indications (msg_id=9, dest=BAM task)
  ##   - Incrementing VIF pending BA counter at vif_entry[334]
  ##   - Power save wakeup notifications

  let staBase = cast[uint](addr sta_info_tab[0])
  let vifBase = cast[uint](addr vif_info_tab[0])
  # Blob s1 = &rxl_cntrl_env, s6 = rxl_cntrl_env[0] (first queued RX desc)
  let cntrlEnv = cast[uint](addr rxl_cntrl_env[0])
  let hwFlagsClearMask = 0xFDFFFFFF'u32  # ~0x02000000

  # Clear RX event bit before processing (blob: ke_evt_clear at entry)
  ke_evt_clear(0x00100000'u32)

  var loopCount: int = 5

  # L70: main processing loop (up to 5 frames per call). Blob does NOT disable
  # MAC HW interrupts around the loop — only masks via csrrci mstatus in the
  # co_list_pop critical section below.
  while true:
    let curHwDesc = cast[ptr pointer](cntrlEnv)[]
    let processingFlag = cast[ptr uint8](cntrlEnv + 24)[]
    if processingFlag != 0 or curHwDesc == nil:
      # L43 in blob: no tail-call to ke_evt_set here — blob simply returns.
      return

    dec loopCount
    if loopCount <= 0:
      ke_evt_set(0x00100000'u32)
      return

    # L45: IRQ-safe pop from front of the cntrl list (blob 0x94)
    let irqState = irqSave()
    discard co_list_pop_front(cast[ptr CoList](cntrlEnv))
    irqRestore(irqState)

    # Read SW descriptor and buffer chain
    let swDesc = cast[ptr pointer](cast[uint](curHwDesc) + 4)[]
    let swDescU = cast[uint](swDesc)
    let bufChain = cast[ptr pointer](swDescU + 8)[]
    var hwFlags = cast[ptr uint32](swDescU + 64)[]
    var staIdx: uint8 = 0
    var staEntryU: uint = 0
    # Blob has ONE rxl_mpdu_free call site at the loop tail; all early
    # exits converge here via the frameWork block.
    var releaseFrame = true
    block frameWork:
     if bufChain == nil:
       assert_rec("rxl_cntrl.c", "rxl_cntrl.c", 479)
       break frameWork

     # Validate frame: both valid and associated bits must be set
     when defined(bl808WifiNimFw):
       let dbgBuf = cast[uint](bufChain)
       let dbgPayload =
         if dbgBuf != 0: cast[ptr uint32](dbgBuf + 8)[]
         else: 0'u32
       let dbgFc =
         if dbgPayload != 0: cast[ptr uint16](dbgPayload.uint)[].uint32
         else: 0'u32
       nimFwTrace2U32("[WIFI-NIMFW] rxl_frame ", hwFlags, dbgFc)
     if (hwFlags and 0x20020000'u32) != 0x20020000'u32:
       releaseFrame = rxu_cntrl_frame_handle(curHwDesc) == 0
       break frameWork

     # Blob uses th.extu(hwFlags, 24, 15), then subtracts the MAC HW STA base.
     staIdx = (((hwFlags shr 15) and 0x3FF) - 8).uint8

     # Look up STA entry, check active flag
     staEntryU = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
     if cast[ptr uint8](staEntryU + 42)[] == 0:
       hwFlags = hwFlags and hwFlagsClearMask
       cast[ptr uint32](swDescU + 64)[] = hwFlags
       releaseFrame = rxu_cntrl_frame_handle(curHwDesc) == 0
       break frameWork

     # VIF lookup
     let vifIdx = cast[ptr uint8](staEntryU + 39)[]
     let vifEntryU = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint

     # Read frame control from RX header
     let rxHdrPtr = cast[ptr pointer](cast[uint](bufChain) + 8)[]
     let frameCtrl = cast[ptr uint16](cast[uint](rxHdrPtr))[]
     let tid = cast[ptr uint8](vifEntryU + 87)[]
     let cryptoType = cast[ptr uint8](vifEntryU + 86)[]
     let maskedFC = frameCtrl and 0x00FC

     # --- Frame type dispatch ---
     # Blob funnels all dispatch paths through a single rxu_cntrl_frame_handle
     # call site, and it shares the alloc/send between the BA-completion and
     # PS-Poll (byte[2]=0) BAM indications. Use flags + single tail calls.
     var dispatchFrame = false
     var bamSendNeeded = false
     var bamSendByte2: uint8 = 0
     block frameDispatch:
       # Check for QoS Data: (maskedFC & 0x8C) == 0x88
       if (maskedFC and 0x8C) == 0x88:
         let staAuth = cast[ptr uint8](staEntryU + 41)[]
         if staAuth == 1:
           # Associated QoS Data: check BA agreement bits
           let fcCheck = frameCtrl and 0x140C
           if fcCheck == 0x0008:
             # Standard QoS data with BA handling
             discard mm_ps_change_ind(cast[pointer](vifEntryU))
             apm_tx_int_ps_clear(staIdx)
             dispatchFrame = true
             let pendBA = cast[ptr uint8](vifEntryU + 334)[]
             if pendBA > 0:
               cast[ptr uint8](vifEntryU + 334)[] = pendBA - 1
               if pendBA - 1 == 0:
                 discard mm_ps_change_ind(cast[pointer](vifEntryU))
                 apm_tx_int_ps_clear(staIdx)
             break frameDispatch

         # Check per-TID BA state
         let baFlags = cast[ptr uint8](staEntryU + 73)[]
         let baState = cast[ptr uint32](staEntryU + 48)[]
         if (baFlags and 0x0C) != 0:
           if (baState and 6) != 0:
             break frameDispatch  # BA in progress
           if (baFlags and 8) != 0:
             let baCount = cast[ptr uint8](staEntryU + 315)[]
             cast[ptr uint32](staEntryU + 48)[] = 2
             dispatchFrame = true
             discard sta_mgmt_send_postponed_frame(cast[pointer](staEntryU),
               cast[pointer](vifEntryU), baCount.uint32)
             if baCount != 0 and (baCount.int - 1) <= 0:
               cast[ptr uint32](staEntryU + 48)[] = 0
               let staVifIdx = cast[ptr uint8](staEntryU + 40)[]
               txl_frame_send_qosnull_frame(staVifIdx, (frameCtrl or 0x10).uint8, 0)
               cast[ptr uint32](staEntryU + 48)[] = 0
               # BAM notify (byte[2]=0). Shares alloc/send site with the
               # PS-Poll no-BA path via bamSendByte2==0 below.
               bamSendByte2 = 0
               bamSendNeeded = true
           else:
             if (baFlags and 4) != 0:
               cast[ptr uint32](staEntryU + 48)[] = 4
               let msgP = ke_msg_alloc(9, TASK_BAM, 0, 56)
               if msgP != nil:
                 cast[ptr uint8](cast[uint](msgP))[] = staIdx
                 cast[ptr uint8](cast[uint](msgP) + 1)[] = tid
                 cast[ptr uint8](cast[uint](msgP) + 2)[] = 1
                 ke_msg_send(msgP)
             else:
               cast[ptr uint32](staEntryU + 48)[] = 2
               dispatchFrame = true
         elif (baFlags and 0x0C) == 0 and (baState and 6) == 0:
           cast[ptr uint32](staEntryU + 48)[] = 2
           dispatchFrame = true

       elif (maskedFC and 0xFC) == 0xA4:
         # Blob .L56 handles PS-Poll (Control type, subtype 10 = 0xA4),
         # NOT BAR — previous comment was wrong. PS-Poll indicates the peer
         # is awake and wants buffered frames.
         let baFlags = cast[ptr uint8](staEntryU + 73)[]
         if (baFlags and 2) != 0:
           # BA-busy: mark sta[48] bit 0, flush postponed frames, clear bit.
           # Blob does NOT call rxu_cntrl_frame_handle here — that was a bug
           # which double-processed the PS-Poll descriptor.
           let sta48 = cast[ptr uint32](staEntryU + 48)[]
           cast[ptr uint32](staEntryU + 48)[] = sta48 or 1
           discard sta_mgmt_send_postponed_frame(cast[pointer](vifEntryU),
             cast[pointer](staEntryU), 1)
           let sta48b = cast[ptr uint32](staEntryU + 48)[]
           cast[ptr uint32](staEntryU + 48)[] = sta48b and not 1'u32
         else:
           # .L59: no BA yet — request a PS-Poll BAM indication.
           bamSendByte2 = 0
           bamSendNeeded = true

       else:
         # Other frame types: standard data path
         dispatchFrame = true
     # Shared tail for all dispatch paths (blob has 1 rxu_cntrl_frame_handle
     # site; dispatchFrame flag set by each path above).
     if dispatchFrame:
       releaseFrame = rxu_cntrl_frame_handle(curHwDesc) == 0
       if not releaseFrame:
         break frameWork

     # Shared BAM-indication site (byte[2]=0 paths). Blob has a single
     # alloc/send pair for these; the baFlags&4 path (byte[2]=1) stays
     # separate as its own site above.
     if bamSendNeeded:
       let msgP = ke_msg_alloc(9, TASK_BAM, 0, 56)
       if msgP != nil:
         cast[ptr uint8](cast[uint](msgP))[] = staIdx
         cast[ptr uint8](cast[uint](msgP) + 1)[] = tid
         cast[ptr uint8](cast[uint](msgP) + 2)[] = bamSendByte2
         ke_msg_send(msgP)

     # L54: Post-dispatch -- check pending crypto and VIF mode
     # Recompute vifEntry for vifIdx (blob does mul-add with 1512 stride)
     let postVifEntryU = vifBase + cast[ptr uint8](staEntryU + 39)[].uint * VIF_ENTRY_SIZE.uint
     let pendingCrypto = cast[ptr uint8](postVifEntryU + 88)[]
     if pendingCrypto != 0 and (frameCtrl and 4) == 0:
       # Blob 0x1ee: td_pck_ind(a0=vif[87], a1=staIdx, a2=1) for traffic-detect
       # packet counting. Previously this path mistakenly called ps_check_frame,
       # which double-dipped into PS processing and skipped the per-VIF TX
       # packet counter increment in td_env.
       let tdHwIdx = cast[ptr uint8](postVifEntryU + 87)[]
       td_pck_ind(tdHwIdx, 1)

     # L66/L67: Check open-mode Beacon/Data frames (maskedFC == 0x80)
     # From blob (offsets 0x200-0x250): if vif_entry[86]==0 (no crypto) and
     # maskedFC==0x80, run the beacon processing pipeline:
     #   mm_check_beacon(bufChain, vifEntry, staEntry, &resultVar)
     #   ps_check_beacon(resultVar, beaconInterval, vifEntry)
     #   vif_mgmt_bcn_recv(vifEntry)
     #   if vifEntry[64] != 0: chan_tbtt_switch_update(vifEntry, vifEntry[36])
     let postCrypto = cast[ptr uint8](postVifEntryU + 86)[]
     if postCrypto == 0:
       let postMaskedFC = frameCtrl and 0x00FC
       if postMaskedFC == 0x80:
         # Beacon processing path (blob offsets 0x212-0x254).
         # mm_check_beacon ABI: (a0=bufChain, a1=vifEntry, a2=staEntry, a3=&resultVar)
         var bcnResult: uint32 = 0
         let pVif = cast[pointer](postVifEntryU)
         let pSta = cast[pointer](staEntryU)
         let pBuf = cast[pointer](bufChain)
         let pResult = addr bcnResult
         {.emit: ["asm volatile(\"mv a3, %0\" :: \"r\"(", pResult, ") : \"a3\");"].}
         {.emit: ["asm volatile(\"mv a2, %0\" :: \"r\"(", pSta, ") : \"a2\");"].}
         {.emit: ["asm volatile(\"mv a1, %0\" :: \"r\"(", pVif, ") : \"a1\");"].}
         mm_check_beacon(pBuf)
         # ps_check_beacon ABI: (a0=resultVar, a1=bcnInterval, a2=vifEntry)
         let bcnInterval = cast[ptr uint16](cast[uint](bufChain) + 28)[]
         ps_check_beacon(cast[pointer](bcnResult), bcnInterval.uint32, pVif)
         vif_mgmt_bcn_recv(pVif)
         # Check TBTT time and update channel switch if needed
         let tbttTime = cast[ptr uint32](postVifEntryU + 64)[]
         if tbttTime != 0:
           chan_tbtt_switch_update(pVif, tbttTime)
         # Also call ps_check_frame for non-retry frames (blob offset 0x406)
         if (frameCtrl and 4) == 0:
           ps_check_frame(cast[pointer](rxHdrPtr), hwFlags, pVif)

     # L55 (blob 0x3B4..0x3FA): power-save change indications for PS-flagged
     # QoS frames. Tested after the main dispatch path.
     if (frameCtrl and 0x1400) == 0x1400:
       # Blob 0x3C6: mm_ps_change_ind(vifEntry, 1)
       discard mm_ps_change_ind(cast[pointer](postVifEntryU))
       let pendBAPs = cast[ptr uint8](postVifEntryU + 334)[]
       if pendBAPs == 0:
         # Blob 0x3DE: mm_ps_change_ind((vifIdx + 5) & 0xff, 1)
         let psArg = cast[pointer](cast[uint]((vifIdx.uint + 5) and 0xff))
         discard mm_ps_change_ind(psArg)

     # Increment VIF pending-BA counter for QoS frames (blob: L65 at 0x3E6)
     if (maskedFC and 0x8C) == 0x88:
       let postVif2 = vifBase + cast[ptr uint8](staEntryU + 39)[].uint * VIF_ENTRY_SIZE.uint
       let pendBA = cast[ptr uint8](postVif2 + 334)[]
       cast[ptr uint8](postVif2 + 334)[] = pendBA + 1

    # L52: Free RX descriptor and loop if the upper RX path did not take it.
    if releaseFrame:
      rxl_mpdu_free(curHwDesc)

  # Unreachable exit (loop exits via return)
  ke_evt_set(0x00100000'u32)

proc rxl_cntrl_dump*() {.exportc, cdecl, noinline.} =
  ## Dump RX control state for debugging.
  ## Blob algorithm:
  ##   - Log header via g_bl_ops_funcs[204] (line 763).
  ##   - Call co_list_cnt(&rxl_cntrl_env) -> count.
  ##   - Log count with count in a5 (line 766).
  ##   - Load a6 = g_bl_ops_funcs[204] again, s0 = rxl_cntrl_env[0] (head).
  ##   - Loop: for each node: call logFn(2,0,.LC3,770, node, node->next->field[0x40]).
  ##     Specifically blob does:  a5 = *(s0+4); a6 = *(a5+0x40); jalr(a6, ...)
  ##     So the printed line is via a per-entry function pointer, not the
  ##     generic log fn. Here we emit via the general log fn for simplicity.
  ##   - Log trailer (line 774).
  let logFn = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
  if logFn == nil:
    return
  let logProc = cast[proc(a: uint32, b: uint32, c: cstring, d: uint32) {.cdecl, varargs.}](logFn)
  logProc(2, 0, "rxl_cntrl.c", 763)
  let count = co_list_cnt(cast[ptr CoList](addr rxl_cntrl_env[0]))
  logProc(2, 0, "rxl_cntrl.c", 766, count)
  var cur = cast[ptr CoListHdr](cast[ptr pointer](addr rxl_cntrl_env[0])[])
  while cur != nil:
    logProc(2, 0, "rxl_cntrl.c", 770, cast[uint32](cast[uint](cur)))
    cur = cur.next
  logProc(2, 0, "rxl_cntrl.c", 774)

proc rxl_dma_evt*() {.exportc, cdecl.} =
  ## RX DMA event handler.
  ## Blob (21 instrs):
  ##   a5 = g_bl_ops_funcs[204]  (dereferenced via +0xcc)
  ##   log(2, 0, .LC3="rxl_cntrl.c", 826)
  ##   ke_evt_clear(0x00400000)
  ##   *(u32*)0x24A00020 = 32  (DMA ACK register)
  ##   ret
  ## Prior Nim bug: called ke_evt_set; blob calls ke_evt_clear. This is the
  ## DMA completion handler: it runs BECAUSE the event was set, and must
  ## clear it to re-arm.
  let logFn = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
  if logFn != nil:
    cast[proc(a0: uint32, a1: uint32, a2: cstring, a3: uint32) {.cdecl.}](logFn)(2, 0, "rxl_cntrl.c", 826)
  ke_evt_clear(0x00400000'u32)
  regWrite(0x24A00020'u, 0x20'u32)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void rxl_timer_int_handler(void);".}
proc rxl_timer_int_handler*() {.exportc, cdecl.} =
  ## RX timer interrupt handler.
  ## From disassembly (71 instrs): writes 0xA0000 to MACHW_INTC_FORCE
  ## (0x24B0807C), then loops over the HD chain (rxl_hwdesc_env[8]). For each
  ## descriptor with bit 14 (0x4000) set in status[64], dequeues it, extracts
  ## the sw_desc, moves buffer chain, checks status fields, and dispatches:
  ##   - statusHalf!=0, field8!=0: co_list_push_back(rxl_cntrl_env, sw_desc)
  ##   - statusHalf!=0, field8==0: assert_rec (line 193)
  ##   - statusHalf==0, field8!=0: assert_rec (line 227)
  ##   - statusHalf==0, field8==0: clear sw_desc[12,16], rxl_hd_append(innerDesc)
  ## After processing, if PD chain exists, tail-calls ke_evt_set(0x100000).
  ## Call graph: co_list_push_back, assert_rec, rxl_hd_append, ke_evt_set
  regWrite(0x24B0807C'u, 0x000A0000'u32)
  let envBase = cast[uint](addr rxl_cntrl_env[0])
  while true:
    let descPtr = cast[ptr uint32](envBase + 8)[]
    if descPtr == 0:
      break
    let descAddr = cast[uint](descPtr)
    let statusWord = cast[ptr uint32](descAddr + 64)[]
    if (statusWord and 0x4000) == 0:
      break
    # Dequeue: advance first to next
    let nextDesc = cast[ptr uint32](descAddr + 4)[]
    let swDescLink = cast[uint](cast[ptr uint32](descAddr + 12)[])
    cast[ptr uint32](envBase + 8)[] = nextDesc
    let bufChain = cast[ptr uint32](descAddr + 8)[]
    let innerDesc = cast[uint](cast[ptr uint32](swDescLink + 4)[])
    cast[ptr uint32](swDescLink + 8)[] = bufChain
    let statusHalf = cast[ptr uint16](innerDesc + 28)[]
    let field8 = cast[ptr uint32](innerDesc + 8)[]
    if statusHalf != 0:
      if field8 == 0:
        # Error: valid status but no buffer (blob: assert_rec line 193)
        assert_rec("rxl_cntrl.c", "rxl_cntrl.c", 193)
      else:
        # Valid frame: push sw_desc onto rxl_cntrl_env processing list
        co_list_push_back(cast[ptr CoList](envBase),
                          cast[ptr CoListHdr](swDescLink))
    else:
      if field8 != 0:
        # Error: no status but has buffer (blob: assert_rec line 227)
        assert_rec("rxl_cntrl.c", "rxl_cntrl.c", 227)
      else:
        # Empty descriptor: clear sw_desc fields and re-append HD for reuse
        cast[ptr uint32](swDescLink + 16)[] = 0
        cast[ptr uint32](swDescLink + 12)[] = 0
        rxl_hd_append(cast[pointer](innerDesc))
  let pdFirst = cast[ptr uint32](envBase + 0)[]
  if pdFirst != 0:
    ke_evt_set(0x00100000'u32)

proc rxl_timeout_int_handler*() {.exportc, cdecl.} =
  ## RX timeout interrupt handler.
  ## From blob (5 instrs): reads MACHW reg at 0x24B0808C (MACHW_BASE+0x8C),
  ## clears bit 6 (AND with ~64 = 0xFFFFFFBF), writes back; ret.
  let regAddr = MACHW_BASE + 0x8C'u
  var val = volatileLoad(cast[ptr uint32](regAddr))
  val = val and (not 64'u32)  # clear bit 6
  volatileStore(cast[ptr uint32](regAddr), val)

proc rxl_current_desc_get*(): pointer {.exportc, cdecl.} =
  ## Get current RX descriptor pointers.
  ## Blob (7 instrs): a0=outCurrent, a1=outLast (hidden arg).
  ## Stores rxl_cntrl_env[4] (offset 0x10) to *a0, rx_hwdesc_env[1] to *a1.
  var outLast {.noinit.}: ptr pointer
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", outLast, "));"].}
  let cntrlBase = cast[uint](addr rxl_cntrl_env[0])
  let hwDescBase = cast[uint](addr rx_hwdesc_env[0])
  # This function is called with (a0=&current, a1=&last) in the blob ABI
  # Store rxl_cntrl_env+16 to *a0 (treated as ptr in Nim return value)
  let currentDesc = cast[ptr pointer](cntrlBase + 16)[]
  if outLast != nil:
    outLast[] = cast[pointer](cast[ptr uint32](hwDescBase + 4)[])
  return currentDesc

# ###########################################################################
#                   RX Upper (rxu_*)
# ###########################################################################

## rxu_cntrl_env: static context structure used by the RX upper control path.
## Declared here so rxu_cntrl_init can reference it.
## Full layout documentation is at the original declaration site below.
var rxu_cntrl_env* {.exportc.}: array[96, uint8]

proc rxu_cntrl_init*() {.exportc, cdecl.} =
  ## Initialize RX upper control (84 bytes in blob, 24 instrs).
  ## Blob: co_list_init at offsets +0x40, +0x38, +0x48, +0x50, store 0xFFFF at +0x5E.
  let env = cast[uint](addr rxu_cntrl_env[0])
  # Initialize 4 linked lists at blob offsets
  co_list_init(cast[ptr CoList](env + 0x40))
  co_list_init(cast[ptr CoList](env + 0x38))
  co_list_init(cast[ptr CoList](env + 0x48))
  co_list_init(cast[ptr CoList](env + 0x50))
  # Set last-STA sentinel to 0xFFFF at offset 0x5E
  cast[ptr uint16](env + 0x5E)[] = 0xFFFF'u16

## rxu_cntrl_env: static context structure used by the RX upper control path.
## Layout (96 bytes, from disassembly of rxu_cntrl_frame_handle):
##   [0..1]   frameCtrl    uint16  - IEEE 802.11 Frame Control
##   [2..3]   seqCtrl      uint16  - Sequence Control field
##   [4..5]   seqNum       uint16  - Sequence number (seqCtrl >> 4)
##   [6]      fragNum      uint8   - Fragment number (seqCtrl & 0xF)
##   [7]      tid          uint8   - Traffic ID (from QoS field)
##   [8]      machdrLen    uint8   - MAC header length in bytes
##   [9]      staIdx       uint8   - STA index (0xFF = unknown)
##   [10]     vifIdx       uint8   - VIF index (0xFF = unknown)
##   [11]     dstIdx       uint8   - Destination STA index (AP forwarding)
##   [16..19] secInfo0     uint32  - Security info word 0 (key offset + counter low)
##   [20..23] secInfo1     uint32  - Security info word 1 (counter high)
##   [24..27] hwRxhdr      uint32  - Stored hw_rxhdr flags (monitor path only)
##   [32..35] secKeyPtr    pointer - Security key context pointer
##   [36..41] da           6 bytes - Destination Address (3 x uint16)
##   [42..47] sa           6 bytes - Source Address (3 x uint16)
##   [48]     secFlags     uint8   - Bit 0: protected frame, bit 1: has sec info
##   [49]     meshFlag     uint8   - Mesh/extra header flag
##   [50]     stripLen     uint8   - MAC header bytes to strip before upload
##   [64..67] pendingPtr   pointer - Pending frame (checked at exit for ke_evt_set)
##   [94..95] bssidSeq     uint16  - Cached BSSID sequence for dup detect
# rxu_cntrl_env is declared above (before rxu_cntrl_init) for forward reference.

## RX upload list: CoList of descriptors pending DMA upload to host.
## Populated by rxu_cntrl_desc_prepare, consumed by rxu_swdesc_upload_evt.
var rxuUploadList* {.exportc: "rxu_upload_list".}: CoList

## RX upload environment: tracks upload state.
## Layout (28 bytes from disassembly):
##   [0..3]   word 0 (flags)
##   [4..7]   word 1 (count/state)
##   [8..11]  word 2
##   [12..15] word 3
##   [16..19] word 4
##   [20..23] uploadCount uint32 - number of descriptors uploaded
##   [24..27] word 6
var rxuUploadEnv* {.exportc: "rxu_upload_env".}: array[7, uint32]

proc rxu_cntrl_evt*() {.exportc, cdecl.} =
  ## RX upper control event handler.
  ## From disassembly (16 instrs): clears the RXU event bit (0x200000),
  ## then checks if the rxu_cntrl_env pending pointer (offset 64) is non-nil.
  ## If pending work exists, sets the upload event (0x800000).
  ke_evt_clear(0x00200000'u32)
  let env = cast[uint](addr rxu_cntrl_env[0])
  let pendingPtr = cast[ptr uint32](env + 64)[]
  if pendingPtr != 0:
    ke_evt_set(0x00800000'u32)

## Cached source address of last management frame for duplicate detection.
var rxu_mgmt_dup_addr* {.exportc.}: array[6, uint8]

## Flag byte cleared per new management frame; used for duplicate detection.
var rxu_cntrl_duplicate_flag {.exportc: "rxu_cntrl_duplicate_detect".}: uint8

proc rxu_cntrl_machdr_len_get*(frameCtrl: uint16): uint8 {.exportc, cdecl, noinline.} =
  ## Compute MAC header length from Frame Control.
  ## 24 (3-addr) or 30 (4-addr if ToDS+FromDS), +2 QoS, +4 HT Control.
  ## noinline + asm barrier: blob calls this as a real function from
  ## rxu_mpdu_upload_and_indicate; without noinline GCC inlines the arithmetic.
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}
  var length: uint8
  if (frameCtrl and 0x0300) == 0x0300: length = 30
  else: length = 24
  if (frameCtrl.uint8 and 0xFC) == 0x88: length += 2
  if (frameCtrl and 0x8000) != 0: length += 4
  return length

proc rxu_cntrl_protected_handle*(rxuCtx: pointer, hwRxhdrFlags: uint32): cint {.exportc, cdecl.} =
  ## Handle protected frame: parse CCMP/TKIP header, set up security context (94 instrs).
  ## a0 = RX upload context pointer, a1 = HW RX header flags.
  ## Dispatches on frame type (bits 4:2 of a1) to determine header type:
  ##   20 = WEP (4-byte hdr), 24 = CCMP (8-byte hdr), 28 = TKIP (8-byte hdr).
  ## Extracts key index from header, looks up STA entry, resolves security key,
  ## stores key address and PN (packet number) into the RX context.
  ## Returns 1 on success, 0 on unrecognized frame type.
  let ctxAddr = cast[uint](rxuCtx)
  let hdrOffset = cast[ptr uint8](ctxAddr + 8)[]  # current header parse offset
  let frameType = hwRxhdrFlags and 0x1C  # bits 4:2 (cipher type * 4)
  let isQos = (hwRxhdrFlags and 0x400) != 0  # bit 10 = QoS flag
  # Get pointer to encrypted frame data
  let buf = cast[ptr UncheckedArray[uint8]](cast[uint](rxuCtx) + hdrOffset.uint)
  case frameType
  of 24:  # CCMP (8 byte header)
    # Update header offset (+8 for CCMP header)
    cast[ptr uint8](ctxAddr + 8)[] = hdrOffset + 8
    # Extract key index from byte 3 bits 7:6
    let keyIdx = (buf[3] shr 6) and 0x03
    # Extract PN (packet number): PN0=buf[0], PN1=buf[1], PN2=buf[4], PN3=buf[5], PN4=buf[6], PN5=buf[7]
    let pnLow = buf[0].uint32 or (buf[1].uint32 shl 8) or
                (buf[4].uint32 shl 16) or (buf[5].uint32 shl 24)
    let pnHigh = buf[6].uint32 or (buf[7].uint32 shl 8)
    # Store PN into context (offset 16, 20)
    cast[ptr uint32](ctxAddr + 16)[] = pnLow
    cast[ptr uint32](ctxAddr + 20)[] = pnHigh
    # Mark cipher type in context
    cast[ptr uint8](ctxAddr + 48)[] = cast[ptr uint8](ctxAddr + 48)[] or 0x02  # CCMP flag
    # Look up key: if QoS, use STA pairwise key; else use group key
    if isQos:
      # Pairwise: look up STA entry from context byte 10
      let staIdx = cast[ptr uint8](ctxAddr + 10)[]
      let staBase = cast[uint](addr sta_info_tab[0])
      let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
      let keyAddr = staEntry + 528 + keyIdx.uint * 160  # key area at STA+528
      cast[ptr pointer](ctxAddr + 32)[] = cast[pointer](keyAddr)
    else:
      # Group key: look up from STA with context byte 9
      let staIdx = cast[ptr uint8](ctxAddr + 9)[]
      let staBase = cast[uint](addr sta_info_tab[0])
      let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
      let keyAddr = staEntry + 528 + keyIdx.uint * 160
      cast[ptr pointer](ctxAddr + 32)[] = cast[pointer](keyAddr)
    return 1
  of 28:  # TKIP (8 byte header)
    # TKIP: similar to CCMP but with different PN extraction
    cast[ptr uint8](ctxAddr + 8)[] = hdrOffset + 8
    let keyIdx = (buf[3] shr 6) and 0x03
    let pnLow = buf[0].uint32 or (buf[2].uint32 shl 8) or
                (buf[4].uint32 shl 16) or (buf[5].uint32 shl 24)
    let pnHigh = buf[6].uint32 or (buf[7].uint32 shl 8)
    cast[ptr uint32](ctxAddr + 16)[] = pnLow
    cast[ptr uint32](ctxAddr + 20)[] = pnHigh
    cast[ptr uint8](ctxAddr + 48)[] = cast[ptr uint8](ctxAddr + 48)[] or 0x03  # TKIP flag
    if isQos:
      let staIdx = cast[ptr uint8](ctxAddr + 10)[]
      let staBase = cast[uint](addr sta_info_tab[0])
      let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
      let keyAddr = staEntry + 528 + keyIdx.uint * 160
      cast[ptr pointer](ctxAddr + 32)[] = cast[pointer](keyAddr)
    else:
      let staIdx = cast[ptr uint8](ctxAddr + 9)[]
      let staBase = cast[uint](addr sta_info_tab[0])
      let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
      let keyAddr = staEntry + 528 + keyIdx.uint * 160
      cast[ptr pointer](ctxAddr + 32)[] = cast[pointer](keyAddr)
    return 1
  of 20:  # WEP (4 byte header)
    cast[ptr uint8](ctxAddr + 8)[] = hdrOffset + 4
    return 1
  else:
    return 0

proc rxu_cntrl_check_pn*(secKeyPtr: pointer, tid: uint8): cint {.exportc, cdecl.} =
  ## Check PN (Packet Number) for replay detection (90 bytes in blob).
  ## From blob (rxu_cntrl.o, 0xAE bytes):
  ##   keyType = secKeyPtr[156]
  ##   pnLo/pnHi loaded from rxu_cntrl_env[16]/[20] (loaded by caller path)
  ##   if keyType == 0: pairwise path — inline compare/update at
  ##       entry = secKeyPtr + tid*16; accept if (storedHi < pnHi) or
  ##       (storedHi == pnHi && storedLo < pnLo). Returns 1 on accept, 0 on replay.
  ##   if keyType != 0: group path — if tid==8, remap to 0; then tail-call
  ##       replay_counter_validate(entry, pnLo, pnHi).
  let keyAddr = cast[uint](secKeyPtr)
  let keyType = cast[ptr uint8](keyAddr + 156)[]

  # Read incoming PN from descriptor (loaded earlier in call chain)
  let rxEnvBase = cast[uint](addr rxu_cntrl_env[0])
  let pnLo = cast[ptr uint32](rxEnvBase + 16)[]
  let pnHi = cast[ptr uint32](rxEnvBase + 20)[]

  if keyType == 0:
    # Pairwise key — inline compare/update per TID
    let tidOffset = tid.uint * 16
    let entryAddr = keyAddr + tidOffset
    let storedHi = cast[ptr uint32](entryAddr + 4)[]
    var accept = false
    if storedHi < pnHi:
      accept = true
    elif storedHi == pnHi:
      let storedLo = cast[ptr uint32](entryAddr)[]
      # Blob: `bgeu a5, a2, .L18` — if storedLo >= pnLo, reject.
      # Accept only when storedLo < pnLo (i.e., pnLo > storedLo).
      if storedLo < pnLo:
        accept = true
    if not accept:
      return 0  # replay detected
    # Update stored PN
    cast[ptr uint32](entryAddr)[] = pnLo
    cast[ptr uint32](entryAddr + 4)[] = pnHi
    return 1
  else:
    # Group key / TID map: if tid==8, remap to 0 (TID 8 used for non-QoS group).
    var adjTid = tid
    if tid == 8:
      adjTid = 0
    let entryAddr = keyAddr + adjTid.uint * 16
    # Tail-call replay_counter_validate(entry, pnLo, pnHi). The callee reads
    # a1/a2 via inline asm, so we emit a direct RISC-V call that pins a0/a1/a2
    # before the call and captures the return in a0.
    var rc: cint
    {.emit: ["""
    {
      register unsigned long _a0 __asm__("a0") = (unsigned long)""", entryAddr, """;
      register unsigned long _a1 __asm__("a1") = (unsigned long)""", pnLo, """;
      register unsigned long _a2 __asm__("a2") = (unsigned long)""", pnHi, """;
      __asm__ volatile (
        "call replay_counter_validate"
        : "+r"(_a0), "+r"(_a1), "+r"(_a2)
        :
        : "ra","memory","a3","a4","a5","a6","a7",
          "t0","t1","t2","t3","t4","t5","t6");
      """, rc, """ = (int)_a0;
    }
    """].}
    return rc

proc rxu_cntrl_desc_prepare*(swdesc: pointer) {.exportc, cdecl, noinline.} =
  ## Set descriptor status=3, push to rxu_cntrl_env upload list under IRQ lock.
  ## Blob (rxu_cntrl_desc_prepare.constprop.0.isra.0, 22 instrs):
  ##   swdesc[20] = 3
  ##   saved = csrrci(mstatus, 0x08)          ; disable MIE, return old mstatus
  ##   co_list_push_back(&rxu_cntrl_env+0x40, swdesc)
  ##   if (saved & 8) csrsi(mstatus, 0x08)    ; restore MIE
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}
  if swdesc == nil: return
  # Mark descriptor status = 3 (ready for upload)
  cast[ptr uint8](cast[uint](swdesc) + 20)[] = 3'u8
  # Push under IRQ lock
  let saved = irqSave()
  let uploadList = cast[ptr CoList](cast[uint](addr rxu_cntrl_env[0]) + 0x40)
  co_list_push_back(uploadList, cast[ptr CoListHdr](swdesc))
  irqRestore(saved)

proc rxu_mpdu_upload_and_indicate*(param: pointer) {.exportc, cdecl.} =
  ## Upload MPDU to host and send indication (292 bytes in blob).
  ## From blob (rxu_cntrl.o, constprop.0):
  ##   1. Load rxu_cntrl_env bytes 9,10 -> build upload flags, OR into swdesc[76]
  ##   2. Set bit 1 in swdesc[76] (upload-in-progress flag)
  ##   3. Clear env byte (upload-active = 0)
  ##   4. Load DMA descriptor chain from swdesc[4]->offset 8 -> offset 24 -> read 2 bytes (FC)
  ##   5. Compute header length adjustment: env[8] - fc_hdr_len
  ##   6. If adjustment != 0 and odd: ASSERT (line 364)
  ##   7. If adjustment != 0 and even: adjust DMA pointers using T-head custom insns
  ##      (shift buffer pointers to strip MAC header)
  ##   8. Update swdesc frame length and env header offset
  ##   9. Clear swdesc[84] = 0 (DMA complete flag)
  ##  10. Call rxl_mpdu_transfer(param) to initiate DMA
  ##  11. Disable interrupts (csrrci mstatus, 8)
  ##  12. Call rxu_cntrl_desc_prepare(param) under interrupt lock
  ##  13. Restore interrupts if they were enabled
  let envBase = cast[uint](addr rxu_cntrl_env[0])
  let swdesc = cast[ptr uint32](cast[uint](param) + 4)[]
  let swdescAddr = cast[uint](swdesc)

  # Build upload flags from env bytes 9,10, OR into swdesc control word at offset 76
  let envByte9 = cast[ptr uint8](envBase + 9)[]
  let envByte10 = cast[ptr uint8](envBase + 10)[]
  let flagsHi = envByte9.uint32 shl 16
  let flagsMid = envByte10.uint32 shl 8
  let existingFlags = cast[ptr uint32](swdescAddr + 76)[]
  cast[ptr uint32](swdescAddr + 76)[] = existingFlags or flagsHi or flagsMid or 2'u32

  # Clear upload-active flag
  cast[ptr uint8](envBase + 0)[] = 0

  # Read DMA chain to get frame control
  let dmaDescPtr = cast[ptr uint32](swdescAddr + 4)[]  # first DMA desc
  let dmaChainAddr = cast[uint](dmaDescPtr)
  let bufPtr = cast[ptr uint32](dmaChainAddr + 8)[]
  let bufAddr = cast[uint](bufPtr)
  let fcBufAddr = cast[ptr uint32](bufAddr + 24)[]
  let fcBufU = cast[uint](fcBufAddr)
  let fcLo = cast[ptr uint8](fcBufU)[]
  let fcHi = cast[ptr uint8](fcBufU + 1)[]
  let fc = fcLo.uint16 or (fcHi.uint16 shl 8)

  # Compute header size from FC via rxu_cntrl_machdr_len_get (blob 0x5a)
  let macHdrLen = rxu_cntrl_machdr_len_get(fc)
  let envHdrLen = cast[ptr uint8](envBase + 8)[]
  let adjustment = (envHdrLen.int - macHdrLen.int) and 0xFF

  if adjustment != 0:
    if (adjustment and 1) != 0:
      # Blob calls assert_warn at 0x8c (not assert_rec)
      assert_warn(cast[cstring](0), cast[cstring](0), 364)
    # Adjust buffer pointers to strip MAC header
    let halfAdj = adjustment.uint32 shr 1
    # Update DMA descriptor frame length
    let curLen = cast[ptr uint16](dmaChainAddr + 28)[]
    cast[ptr uint16](dmaChainAddr + 28)[] = curLen - adjustment.uint16
    # Update env header offset
    cast[ptr uint8](envBase + 50)[] = adjustment.uint8
    let newHdrOff = envHdrLen - fc.uint8
    cast[ptr uint8](envBase + 8)[] = envHdrLen - newHdrOff

  # Clear DMA complete flag
  cast[ptr uint32](swdescAddr + 84)[] = 0

  # Initiate DMA transfer
  rxl_mpdu_transfer(param)

  # Critical section: prepare descriptor under interrupt lock
  var mstatusVal: uint32
  {.emit: ["asm volatile(\"csrrci %0, mstatus, 8\" : \"=r\"(", mstatusVal, "));"].}
  rxu_cntrl_desc_prepare(param)
  if (mstatusVal and 8) != 0:
    {.emit: "asm volatile(\"csrrsi zero, mstatus, 8\");".}

{.emit: "__attribute__((optimize(\"crossjumping\"))) unsigned long rxu_cntrl_frame_handle(void*);".}
proc rxu_cntrl_frame_handle*(param: pointer): uint32 {.exportc, cdecl.} =
  ## Main RX frame dispatch handler (666 instructions in blob).
  ##
  ## Classifies IEEE 802.11 frames by type/subtype, extracts MAC header fields
  ## into rxu_cntrl_env, and dispatches to the appropriate handler.
  ##
  ## Returns (via s2): 0 = dropped, 1 = uploaded to host.
  ##
  ## Register map: s0=env s1=payload s2=retval s3=param s4=sta_info_tab
  ##   s5=rawFC s6=staIdx s7=hwFlags/vif_info_tab s8=swdesc/fType

  let env = cast[uint](addr rxu_cntrl_env[0])
  let swdesc = cast[uint](cast[ptr uint32](cast[uint](param) + 4)[])
  let hwFlags = cast[ptr uint32](swdesc + 64)[]

  # Epilogue helper: break to the common tail which emits a single
  # ke_evt_set (matching blob's 1-site pattern). Any caller using
  # doReturn() will exit the rcfhScope and run the shared tail below.
  # The frame-action flags let each branch request an upload or release;
  # both converge on single shared call sites after the block.
  var uploadFrame = false
  var returnValue: uint32 = 0
  template doReturn() =
    break rcfhScope

  block rcfhScope:
    # Check valid-frame bit 0x2000
    if (hwFlags and 0x2000) == 0:
      doReturn()

    # .L137: Frame valid -- begin classification
    let bufChain = cast[uint](cast[ptr uint32](swdesc + 8)[])
    let payload = cast[uint](cast[ptr uint32](bufChain + 8)[])
    let rawFC = cast[ptr uint16](payload)[]
    when defined(bl808WifiNimFw):
      nimFwTrace2U32("[WIFI-NIMFW] rxu_fc ", hwFlags, rawFC.uint32)

    # NOTE: The blob does NOT call tcpip_stack_input from rxu_cntrl_frame_handle.
    # The fast-path delivery happens only in rxu_swdesc_upload_evt.
    # Previous code here incorrectly called tcpip_stack_input; removed.

    # Clear swdesc status accumulator at offset 76
    cast[ptr uint32](swdesc + 76)[] = 0

    # Init sta_idx = 0xFF, vif_idx = 0xFF
    cast[ptr uint8](env + 9)[] = 0xFF
    cast[ptr uint8](env + 10)[] = 0xFF

    # Store frame control at env[0]
    cast[ptr uint16](env + 0)[] = rawFC

    # Store sequence control from payload[22..23] at env[2]
    let seqCtrl = cast[ptr uint16](payload + 22)[]
    cast[ptr uint16](env + 2)[] = seqCtrl

    # Clear duplicate-detect flag
    rxu_cntrl_duplicate_flag = 0

    # Decompose seqCtrl -> seqNum at env[4], fragNum at env[6]
    cast[ptr uint16](env + 4)[] = seqCtrl shr 4
    cast[ptr uint8](env + 6)[] = (seqCtrl and 0xF).uint8

    # ---- QoS TID extraction ----
    # Blob at .L139 clears env[7] (TID) for non-QoS frames. If env[7] retained
    # a value from a previous QoS frame, downstream per-TID lookups (seq cache
    # at staEntry + (tid-0x57)*0xB8, PN replay index, etc.) would index wrong
    # entries and reject valid frames. Must clear to 0 on non-QoS path.
    if (rawFC.uint8 and 0x88) == 0x88:
      if (rawFC and 0x0300) == 0x0300:
        cast[ptr uint8](env + 7)[] = (cast[ptr uint16](payload + 30)[] and 7).uint8
      else:
        cast[ptr uint8](env + 7)[] = (cast[ptr uint16](payload + 24)[] and 7).uint8
    else:
      cast[ptr uint8](env + 7)[] = 0'u8

    # .L142: Compute MAC header length
    let machdrLen = rxu_cntrl_machdr_len_get(rawFC)
    cast[ptr uint8](env + 8)[] = machdrLen
    when defined(bl808WifiConnectTrace):
      let rxTraceState = ke_state_get(TASK_SM)
      let rxTraceType = rawFC and 0x000C
      if rxTraceState >= SM_ACTIVATING_STATE or rxTraceType == 8:
        let rxTraceLen = cast[ptr uint16](swdesc + 28)[]
        let rxTraceEth =
          if rxTraceLen >= machdrLen.uint16 + 8'u16:
            cast[ptr uint16](payload + machdrLen.uint + 6)[].uint32
        else:
            0'u32
        nimFwConnectTrace2U32("[WIFI-CT] rx_enter ",
                              rawFC.uint32 or (machdrLen.uint32 shl 16),
                              hwFlags)
        nimFwConnectTrace2U32("[WIFI-CT] rx_len ",
                              rxTraceLen.uint32 or (rxTraceEth shl 16),
                              rxTraceState.uint32)

    # ---- Address extraction: ToDS/FromDS ----
    let toDs = (rawFC and 0x0100) != 0
    let fromDs = (rawFC and 0x0200) != 0

    if toDs:
      # DA from Addr3 (offset 16)
      cast[ptr uint16](env + 36)[] = cast[ptr uint16](payload + 16)[]
      cast[ptr uint16](env + 38)[] = cast[ptr uint16](payload + 18)[]
      cast[ptr uint16](env + 40)[] = cast[ptr uint16](payload + 20)[]
      if fromDs:
        # WDS: SA from Addr4 (offset 24)
        cast[ptr uint16](env + 42)[] = cast[ptr uint16](payload + 24)[]
        cast[ptr uint16](env + 44)[] = cast[ptr uint16](payload + 26)[]
        cast[ptr uint16](env + 46)[] = cast[ptr uint16](payload + 28)[]
      else:
        # ToDS only: SA from Addr2 (offset 10)
        cast[ptr uint16](env + 42)[] = cast[ptr uint16](payload + 10)[]
        cast[ptr uint16](env + 44)[] = cast[ptr uint16](payload + 12)[]
        cast[ptr uint16](env + 46)[] = cast[ptr uint16](payload + 14)[]
    elif fromDs:
      # FromDS only: DA from Addr1 (offset 4), SA from Addr3 (offset 16)
      cast[ptr uint16](env + 36)[] = cast[ptr uint16](payload + 4)[]
      cast[ptr uint16](env + 38)[] = cast[ptr uint16](payload + 6)[]
      cast[ptr uint16](env + 40)[] = cast[ptr uint16](payload + 8)[]
      cast[ptr uint16](env + 42)[] = cast[ptr uint16](payload + 16)[]
      cast[ptr uint16](env + 44)[] = cast[ptr uint16](payload + 18)[]
      cast[ptr uint16](env + 46)[] = cast[ptr uint16](payload + 20)[]
    else:
      # No DS: DA from Addr1 (offset 4), SA from Addr2 (offset 10)
      cast[ptr uint16](env + 36)[] = cast[ptr uint16](payload + 4)[]
      cast[ptr uint16](env + 38)[] = cast[ptr uint16](payload + 6)[]
      cast[ptr uint16](env + 40)[] = cast[ptr uint16](payload + 8)[]
      cast[ptr uint16](env + 42)[] = cast[ptr uint16](payload + 10)[]
      cast[ptr uint16](env + 44)[] = cast[ptr uint16](payload + 12)[]
      cast[ptr uint16](env + 46)[] = cast[ptr uint16](payload + 14)[]

    # ================================================================
    # Branch: associated/monitor (hwFlags bit 25, blob `lui 0x2000`) vs unassociated
    # ================================================================
    if (hwFlags and 0x02000000'u32) != 0:
      # .L148: Associated STA / monitor mode path
      # Extract STA index from hwFlags via B-extension insn (approximate)
      let staIdx = (((hwFlags shr 15) and 0x3FF'u32) - 8).uint8

      let staBase = cast[uint](addr sta_info_tab[0])
      let vifBase = cast[uint](addr vif_info_tab[0])
      let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint

      # Check STA active at sta_entry[42]
      if cast[ptr uint8](staEntry + 42)[] == 0:
        when defined(bl808WifiConnectTrace):
          nimFwConnectTrace2U32("[WIFI-CT] rx_drop ", 1, staIdx.uint32)
        doReturn()

      let vifIdx = cast[ptr uint8](staEntry + 39)[]
      cast[ptr uint32](env + 24)[] = hwFlags
      let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
      cast[ptr uint8](env + 10)[] = vifIdx
      cast[ptr uint8](env + 9)[] = staIdx

      # AP mode unicast DA -> look up destination STA via MAC HW search
      if cast[ptr uint8](vifEntry + 86)[] == 2:
        if (cast[ptr uint8](env + 36)[] and 1) == 0:
          let dstIdx = hal_machw_search_addr(cast[pointer](env + 36), 0).uint8
          cast[ptr uint8](env + 11)[] = dstIdx

      # Mark HT QoS in status accumulator
      if (rawFC and 0x0300) == 0x0300:
        let s = cast[ptr uint32](swdesc + 76)[]
        cast[ptr uint32](swdesc + 76)[] = s or 4

      # .L156: Protected frame check (FC bit 14)
      if (cast[ptr uint16](env + 0)[] and 0x4000) != 0:
        if rxu_cntrl_protected_handle(
             cast[ptr uint8](payload), cast[ptr uint32](env + 24)[]) == 0:
          doReturn()

      # .L160: Frame type dispatch
      let fType = rawFC and 0x000C

      if fType != 0 and fType != 8:
        when defined(bl808WifiConnectTrace):
          nimFwConnectTrace2U32("[WIFI-CT] rx_drop ", 2, rawFC.uint32)
        doReturn()

      if fType == 8:
        # ---- Data frame (type 2) in associated path ----
        # Blob .L160 at 0x3e6: rawFC & 0x40 = Null subtype (bit 6).
        # Null/CF-Poll frames are keepalive-only (no payload); blob just pokes
        # the keepalive timestamp and returns. Previously Nim incorrectly called
        # rxl_frame_release here which double-released the descriptor.
        if (rawFC and 0x0040) != 0:
          when defined(bl808WifiConnectTrace):
            nimFwConnectTrace2U32("[WIFI-CT] rx_drop ", 3, rawFC.uint32)
          mm_cfg_element_keepalive_timestamp_update()
          doReturn()

        # Sequence/reorder context
        var seqCachePtr: uint
        if (rawFC and 0x0080) != 0:
          let tid = cast[ptr uint8](env + 7)[]
          seqCachePtr = staEntry + ((tid.uint + 0xA9) and 0xFF) * 0xB8
        else:
          seqCachePtr = staEntry + 336

        # Duplicate sequence check
        let envSeq = cast[ptr uint16](env + 2)[]
        if rawFC != 0:
          if cast[ptr uint16](seqCachePtr)[] == envSeq:
            when defined(bl808WifiConnectTrace):
              nimFwConnectTrace2U32("[WIFI-CT] rx_drop ", 5, envSeq.uint32)
            doReturn()
        cast[ptr uint16](seqCachePtr)[] = envSeq

        # PN replay check
        if (cast[ptr uint8](env + 48)[] and 2) != 0:
          if rxu_cntrl_check_pn(
               cast[pointer](cast[ptr uint32](env + 32)[]),
               cast[ptr uint8](env + 7)[]) == 0:
            when defined(bl808WifiConnectTrace):
              nimFwConnectTrace2U32("[WIFI-CT] rx_drop ", 6, rawFC.uint32)
            doReturn()

        # .L171: EAPOL detection at msduStart+6 (EtherType 0x888E)
        let msduStart = payload + machdrLen.uint
        let ethType = cast[ptr uint16](msduStart + 6)[]
        if ethType == 0x8E88'u16:
          # .LBB303: EAPOL frame detected -- route based on VIF type
          let vifType = cast[ptr uint8](vifEntry + 86)[]
          let adjustedLen = cast[ptr uint16](cast[uint](cast[ptr uint32](cast[uint](param) + 4)[]) + 28)[]
          let eapolData = cast[pointer](msduStart + 8)  # skip LLC/SNAP header
          let eapolLen = adjustedLen - machdrLen.uint16 - 8
          when defined(bl808WifiConnectTrace):
            nimFwConnectTrace2U32("[WIFI-CT] eapol_rx ", staIdx.uint32 or (vifType.uint32 shl 8), eapolLen.uint32)
          if vifType == 2:
            # AP mode: route EAPOL to AP handler
            apm_handle_eapol_input(staIdx, eapolData, eapolLen.uint32)
            break rcfhScope
          else:
            # STA mode: route EAPOL to SM handler
            sm_handle_eapol_input(staIdx, cast[pointer](env + 42), eapolData, eapolLen.uint32)
            break rcfhScope

        # .L170/.L173: Protected + A-MSDU/fragment checks
        let fcR = cast[ptr uint16](env + 0)[]
        if (fcR and 0x4000) != 0:
          if (fcR and 0x0400) != 0: doReturn()
          if cast[ptr uint8](env + 6)[] != 0: doReturn()

        # .LBB312/.LBB313: MIC verification (Michael MIC for TKIP)
        # Blob builds local DMA descriptor chain from buffer chain, calls me_mic_init/
        # me_mic_calc/me_mic_end, then compares computed MIC with received MIC.
        # On mismatch sends MIC_FAILURE_IND via ke_msg_alloc(0xC04, TASK_CFG, TASK_ME, 24).
        if (cast[ptr uint8](env + 48)[] and 1) != 0:
          let secKeyBase = cast[uint](cast[ptr uint32](env + 32)[])
          let tidVal = cast[ptr uint8](env + 7)[]
          let paramW = cast[uint](cast[ptr uint32](cast[uint](param) + 4)[])
          let hdrLen2 = cast[ptr uint8](env + 8)[]
          let frameSize = cast[ptr uint16](paramW + 28)[]
          # dataLen = frameSize - 8 (MIC) - hdrLen
          var dataLen: int = frameSize.int - 8 - hdrLen2.int

          # 1. Init MIC context on stack with TKIP RX MIC key at secKey+144
          var micCtx {.noinit.}: array[4, uint32]  # L, R, pending, nBytes
          me_mic_init(addr micCtx[0],
                      cast[pointer](secKeyBase + 144),
                      cast[pointer](env + 42),   # SA
                      cast[pointer](env + 36),   # DA
                      tidVal)

          # 2. Walk buffer chain computing MIC over MSDU payload
          var curBuf = cast[uint](cast[ptr uint32](paramW + 8)[])
          var skipBytes = hdrLen2.int  # skip MAC header in first segment
          const MAX_DMA_SEG = 1736
          while dataLen > 0 and curBuf != 0:
            let bufPayload = cast[uint](cast[ptr uint32](curBuf + 8)[])
            var segStart = bufPayload + skipBytes.uint
            var segLen = dataLen + skipBytes
            if segLen > MAX_DMA_SEG:
              segLen = MAX_DMA_SEG
            segLen -= skipBytes
            if segLen > dataLen:
              segLen = dataLen
            if segLen > 0:
              me_mic_calc(addr micCtx[0], cast[pointer](segStart), segLen.uint32)
              dataLen -= segLen
            if dataLen > 0:
              curBuf = cast[uint](cast[ptr uint32](curBuf + 4)[])
              if curBuf == 0:
                assert_rec("rxu_cntrl.c", "rxu_cntrl.c", 811)
                doReturn()
            skipBytes = 0  # only first segment has header to skip

          me_mic_end(addr micCtx[0])

          # 3. Read received MIC from tail of frame (last 8 bytes)
          # Walk buffer chain again to find MIC location
          var micOff: int = frameSize.int - 8  # offset of MIC from frame start
          var micBuf = cast[uint](cast[ptr uint32](paramW + 8)[])
          var rxMic {.noinit.}: array[2, uint32]
          rxMic[0] = 0; rxMic[1] = 0
          var micSkip = 0
          while micOff > 0 and micBuf != 0:
            let segPayload = cast[uint](cast[ptr uint32](micBuf + 8)[])
            var segAvail = MAX_DMA_SEG - micSkip
            if segAvail > micOff:
              # MIC starts in this segment
              let micPtr = segPayload + micSkip.uint + micOff.uint
              rxMic[0] = cast[ptr uint32](micPtr)[]
              rxMic[1] = cast[ptr uint32](micPtr + 4)[]
              micOff = 0
            else:
              micOff -= segAvail
              micBuf = cast[uint](cast[ptr uint32](micBuf + 4)[])
              if micBuf == 0:
                assert_rec("rxu_cntrl.c", "rxu_cntrl.c", 852)
                doReturn()
            micSkip = 0

          # 4. Compare computed MIC with received MIC
          if rxMic[0] != micCtx[0] or rxMic[1] != micCtx[1]:
            # MIC failure: send indication to host
            let failMsg = ke_msg_alloc(0xC04'u16, TASK_CFG, TASK_ME, 24)
            if failMsg != nil:
              let msgU = cast[uint](failMsg)
              # Fill MIC failure indication: BSSID from sta_info_tab
              let staIdxF = cast[ptr uint8](env + 9)[]
              let staBaseF = cast[uint](addr sta_info_tab[0])
              let staEntryF = staBaseF + staIdxF.uint * STA_ENTRY_SIZE.uint
              cast[ptr uint32](msgU)[] = cast[ptr uint32](staEntryF + 4)[]
              cast[ptr uint16](msgU + 4)[] = cast[ptr uint16](staEntryF + 8)[]
              # PN/IV from env+16..24
              cast[ptr uint32](msgU + 8)[] = cast[ptr uint32](env + 16)[]
              cast[ptr uint32](msgU + 12)[] = cast[ptr uint32](env + 20)[]
              cast[ptr uint32](msgU + 16)[] = cast[ptr uint32](env + 24)[]
              # TID and vifIdx
              let tidMsgBits = (tidVal.uint32 shl 24) or (0xFF'u32 and tidVal.uint32)
              cast[ptr uint8](msgU + 16)[] = tidVal
              cast[ptr uint8](msgU + 18)[] = cast[ptr uint8](env + 10)[]
              # Key type from secKey
              cast[ptr uint8](msgU + 17)[] = cast[ptr uint8](secKeyBase + 153)[]
              ke_msg_send(failMsg)
            doReturn()

        # .L174: Build status word for host upload
        let paramW1 = cast[uint](cast[ptr uint32](cast[uint](param) + 4)[])
        let curStat = cast[ptr uint32](paramW1 + 76)[]
        let combined = (cast[ptr uint8](env + 9)[].uint32 shl 16) or
                       (cast[ptr uint8](env + 10)[].uint32 shl 8) or
                       (cast[ptr uint8](env + 11)[].uint32 shl 24) or
                       curStat or 2
        cast[ptr uint32](paramW1 + 76)[] = combined

        # .LBB349: Reparse FC for QoS TID/AMSDU bits
        let bufC2 = cast[uint](cast[ptr uint32](paramW1 + 8)[])
        let payB = cast[uint](cast[ptr uint32](bufC2 + 8)[])
        let fcFinal = cast[ptr uint16](payB)[]
        let statW = cast[ptr uint32](paramW1 + 76)[]
        cast[ptr uint32](paramW1 + 76)[] = statW and 0xFFFFFF8F'u32

        if (fcFinal.uint8 and 0xFC) == 0x88:
          let qOff: uint = if (fcFinal and 0x0300) == 0x0300: 30 else: 24
          let qos = cast[ptr uint16](payB + qOff)[]
          let tidBits = (qos and 7).uint32 shl 4
          let amsdu = if (qos and 0x80) != 0: 1'u32 else: 0'u32
          let s2 = cast[ptr uint32](paramW1 + 76)[]
          cast[ptr uint32](paramW1 + 76)[] = s2 or tidBits or amsdu

        # .L185: LLC/SNAP header check for proper strip length computation.
        # Blob uses two memcmp calls against 6-byte RFC1042 + bridge-tunnel
        # headers at .LANCHOR0 and .LANCHOR1.
        const rfc1042Hdr: array[6, uint8] = [0xAA'u8, 0xAA, 0x03, 0x00, 0x00, 0x00]
        const bridgeTunnelHdr: array[6, uint8] = [0xAA'u8, 0xAA, 0x03, 0x00, 0x00, 0xF8]
        var stripLen = machdrLen and 0xFE
        let msduPtr = payB + stripLen.uint

        var isLlcSnap = c_memcmp(cast[pointer](msduPtr),
                                 unsafeAddr rfc1042Hdr[0], 6.csize_t) == 0

        if isLlcSnap:
          # Check ethertype at MSDU+6 for IPX (0x8137)
          let ethType2 = cast[ptr uint16](msduPtr + 6)[]
          if ethType2 == 0x3781'u16:  # 0x8137 LE
            isLlcSnap = false  # treat IPX as non-LLC

        if isLlcSnap:
          # .L190: Check for bridge tunnel header (AA AA 03 00 00 F8)
          let isBridge = c_memcmp(cast[pointer](msduPtr),
                                  unsafeAddr bridgeTunnelHdr[0], 6.csize_t) == 0
          if isBridge:
            # A-MSDU sub-frame: strip 14 more bytes, write sub-frame length header
            stripLen = (stripLen.int - 14).uint8
            let adjustedLen2 = cast[ptr uint16](paramW1 + 28)[]
            # Write 2-byte A-MSDU length at msduPtr-2..msduPtr-1
            let lenVal = adjustedLen2 - cast[uint16](cast[ptr uint8](env + 50)[])
            cast[ptr uint8](msduPtr - 2)[] = (lenVal and 0xFF).uint8
            cast[ptr uint8](msduPtr - 1)[] = ((lenVal shr 8) and 0xFF).uint8
            cast[ptr uint8](env + 49)[] = 1  # A-MSDU sub-frame indicator
        else:
            # .L192: Standard LLC/SNAP: strip 6 bytes (keep ethertype)
            stripLen = (stripLen.int - 6).uint8
        # else: non-LLC: keep stripLen as machdrLen & 0xFE

        # Clear env[49] for non-A-MSDU frames
        if cast[ptr uint8](env + 49)[] != 1:
          cast[ptr uint8](env + 49)[] = 0

        # .L191: Rewrite DA/SA into Ethernet-II header
        let hdr = payB + stripLen.uint - 14
        cast[ptr uint16](hdr + 0)[] = cast[ptr uint16](env + 36)[]
        cast[ptr uint16](hdr + 2)[] = cast[ptr uint16](env + 38)[]
        cast[ptr uint16](hdr + 4)[] = cast[ptr uint16](env + 40)[]
        cast[ptr uint16](hdr + 6)[] = cast[ptr uint16](env + 42)[]
        cast[ptr uint16](hdr + 8)[] = cast[ptr uint16](env + 44)[]
        cast[ptr uint16](hdr + 10)[] = cast[ptr uint16](env + 46)[]

        # Adjust length, set strip info
        let oldLen = cast[ptr uint16](paramW1 + 28)[]
        cast[ptr uint16](paramW1 + 28)[] = oldLen - stripLen.uint16
        cast[ptr uint32](paramW1 + 84)[] = stripLen.uint32
        cast[ptr uint8](env + 50)[] = stripLen

        # DMA transfer MPDU, then prepare descriptor under irq lock
        # Blob order: rxl_mpdu_transfer → csrrci(irq disable) → rxu_cntrl_desc_prepare
        rxl_mpdu_transfer(param)
        let savedIrq = irqSave()
        rxu_cntrl_desc_prepare(param)
        irqRestore(savedIrq)
        uploadFrame = true
        break rcfhScope

      else:
        # fType == 0: Management in associated path
        let envSeq = cast[ptr uint16](env + 2)[]
        if rawFC != 0:
          let cachedSeq = cast[ptr uint16](staEntry + 336)[]
          if cachedSeq == envSeq: doReturn()
        cast[ptr uint16](staEntry + 336)[] = envSeq

        if (cast[ptr uint8](env + 48)[] and 2) != 0:
          if rxu_cntrl_check_pn(
               cast[pointer](cast[ptr uint32](env + 32)[]),
               cast[ptr uint8](env + 7)[]) == 0:
            doReturn()

        # Blob's associated mgmt path (.L158 -> .L163 -> .L234) routes through
        # rxu_mgt_frame_check(param, sta_idx), not the data upload path.
        returnValue = rxu_mgt_frame_check(param, cast[ptr uint8](env + 9)[])
        when defined(bl808WifiNimFw):
          nimFwTrace2U32("[WIFI-NIMFW] rxu_mgt_assoc ", rawFC.uint32, returnValue)
        doReturn()

    # ================================================================
    # Non-associated path: dispatch by frame type bits [3:2]
    # ================================================================
    let fType = rawFC and 0x000C

    if fType == 0:
      # ---- Management frame (type 0) ----
      let addr2Ptr = cast[pointer](payload + 10)
      let fcByte1 = cast[ptr uint8](payload + 1)[]
      let retryFrame = (fcByte1 and 0x08'u8) != 0

      if retryFrame:
        let cachedSeq = cast[ptr uint16](env + 94)[]
        if cast[ptr uint16](payload + 22)[] == cachedSeq:
          if c_memcmp(addr2Ptr, cast[pointer](addr rxu_mgmt_dup_addr[0]), 6) == 0:
            doReturn()

      cast[ptr uint16](env + 94)[] = cast[ptr uint16](payload + 22)[]
      discard c_memcpy(cast[pointer](addr rxu_mgmt_dup_addr[0]), addr2Ptr, 6)

      if (cast[ptr uint16](env + 0)[] and 0x4000) != 0:
        if (hwFlags and 0x1C) != 20: doReturn()
        if rxu_cntrl_protected_handle(cast[ptr uint8](payload), hwFlags) != 0:
          doReturn()

      # Management frame filter check (blob: rxu_mgt_frame_check at reloc 0x324)
      let mgtAccepted = rxu_mgt_frame_check(param, 0xFF'u8)
      when defined(bl808WifiNimFw):
        nimFwTrace2U32("[WIFI-NIMFW] rxu_mgt ", rawFC.uint32, mgtAccepted)
      returnValue = mgtAccepted
      doReturn()

    elif fType == 8:
      # ---- Data frame (type 2) -- non-associated ----
      # Blob: check if DA matches a known VIF BSSID. If so, forward to
      # scan_indicate for scan module processing. Otherwise release.
      let firstVif = vif_mgmt_get_first_ap_inf()
      if firstVif != nil:
        let vifBssid = cast[uint](firstVif) + 80  # BSSID at vif[80..85]
        if c_memcmp(cast[pointer](payload + 4), cast[pointer](vifBssid), 6) == 0:
          # DA matches our BSSID: forward to AP MLME
          apm_send_mlme(firstVif, 192, cast[pointer](payload + 10), nil, nil, cast[pointer](1))
          doReturn()
      # Blob does NOT call rxl_frame_release here; frame is left for
      # the TX-pool recycler. Previous Nim spuriously released.
      break rcfhScope

    else:
      # Control frame (type 1) or reserved: blob also does NOT release.
      break rcfhScope

  # Common tail: single upload + single ke_evt_set site (matches blob
  # 0x238 upload and 0x3c ke_evt_set).
  if uploadFrame:
    rxu_mpdu_upload_and_indicate(param)
    returnValue = 1
  if cast[ptr uint32](env + 64)[] != 0:
    ke_evt_set(0x00800000'u32)
  return returnValue

{.emit: "__attribute__((optimize(\"crossjumping\"))) void rxu_swdesc_upload_evt(void);".}
proc rxu_swdesc_upload_evt*() {.exportc, cdecl.} =
  ## RX software descriptor upload event.
  ## From disassembly (143 instrs): clears event bit 0x800000, pops descriptors
  ## from the upload list. For each descriptor, checks upload count limit (41),
  ## builds a local DMA descriptor array (up to 4 entries, each 4 bytes of buffer
  ## address + 2 bytes length at offset 32, capped at 1736 per entry), then calls
  ## tcpip_stack_input. On success, updates upload count via platform
  ## callbacks. On failure or limit exceeded, frees the descriptor via rxl_mpdu_free.
  ke_evt_clear(0x00800000'u32)
  var entry = co_list_pop_front(addr rxuUploadList)
  let uploadEnv = cast[uint](addr rxuUploadEnv[0])
  let blOps = cast[uint](addr g_bl_ops_funcs)
  const MAX_DMA_ENTRIES = 4
  const MAX_DMA_SIZE = 1736'u32
  while entry != nil:
    let descAddr = cast[uint](entry)
    # Check upload count limit
    let uploadCount = cast[ptr uint32](uploadEnv + 20)[]
    if (41 - uploadCount) <= 2:
      # Over limit -- log warning and release
      let logFn = cast[ptr pointer](blOps + 204)[]
      if logFn != nil:
        cast[proc(a0: uint32, a1: uint32, a2: cstring, a3: uint32) {.cdecl.}](logFn)(2, 0, "rxu_cntrl.c", 2002)
      rxl_mpdu_free(entry)
      entry = co_list_pop_front(addr rxuUploadList)
      continue
    # Get sw_desc and compute total remaining bytes
    let swDescPtr = cast[ptr pointer](descAddr + 4)[]
    let swDescAddr = cast[uint](swDescPtr)
    let payloadHalf = cast[ptr uint16](swDescAddr + 28)[]
    let bufOffset = cast[ptr uint32](swDescAddr + 84)[]
    var remaining = payloadHalf.uint32 + bufOffset
    # Clear local DMA descriptor array (40 bytes on stack, matching blob layout).
    # Blob: addresses at offsets 0,4,8,12; lengths (uint16) at offsets 32,34,36,38.
    var dmaArray {.noinit.}: array[10, uint32]  # 40 bytes
    discard c_memset(addr dmaArray[0], 0, 40.csize_t)
    # Get first HW descriptor
    var curHwDesc = cast[uint](cast[ptr uint32](swDescAddr + 8)[])
    var dmaIdx = 0'u32
    # Build DMA entries from HW descriptor chain
    while remaining > 0:
      if dmaIdx >= MAX_DMA_ENTRIES.uint32:
        break  # at most 4 entries
      # Increment DMA count in desc
      let dmaCount = cast[ptr uint8](descAddr + 21)[]
      cast[ptr uint8](descAddr + 21)[] = dmaCount + 1
      # Store buffer address from hw_desc[8] (offsets 0,4,8,12 in dmaArray)
      dmaArray[dmaIdx] = cast[ptr uint32](curHwDesc + 8)[]
      # Compute transfer length (capped at MAX_DMA_SIZE)
      var xferLen = remaining
      if xferLen > MAX_DMA_SIZE:
        xferLen = MAX_DMA_SIZE
      # Store length as uint16 at offset 32 + dmaIdx*2 in dmaArray
      let lenPtr = cast[ptr uint16](cast[uint](addr dmaArray[0]) + 32 + dmaIdx * 2)
      lenPtr[] = xferLen.uint16
      # Check hw_desc[20] for warning
      let hwFlag = cast[ptr uint32](curHwDesc + 20)[]
      if hwFlag != 0:
        let logFn = cast[ptr pointer](blOps + 204)[]
        if logFn != nil:
          cast[proc(a0: uint32, a1: uint32, a2: cstring, a3: uint32) {.cdecl.}](logFn)(2, 0, "rxu_cntrl.c", 2023)
      # Mark hw_desc as used
      cast[ptr uint32](curHwDesc + 20)[] = 1
      # Advance
      if remaining > MAX_DMA_SIZE:
        remaining -= MAX_DMA_SIZE
      else:
        remaining = 0
      curHwDesc = cast[uint](cast[ptr uint32](curHwDesc + 4)[])
      dmaIdx += 1
    # Set sw_desc[96] = 1 (upload done flag)
    cast[ptr uint32](swDescAddr + 96)[] = 1
    # Call tcpip_stack_input to deliver frame to TCP/IP stack.
    # Blob args: a0=entry, a1=desc[20] byte, a2=swDesc+28, a3=swDesc[84],
    #            a4=&dmaArray, a5=swDesc[76]&1
    let descFlag = cast[ptr uint8](descAddr + 20)[].uint32
    let swPayload = cast[pointer](swDescAddr + 28)
    let swBufOff = cast[ptr uint32](swDescAddr + 84)[]
    let swFcFlag = cast[ptr uint32](swDescAddr + 76)[] and 1
    let uploadResult = tcpip_stack_input(
      entry,
      descFlag,
      swPayload,
      swBufOff,
      cast[pointer](addr dmaArray[0]),
      swFcFlag,
    )
    if uploadResult != 0:
      # Upload failed -- free descriptor and try next
      rxl_mpdu_free(entry)
      entry = co_list_pop_front(addr rxuUploadList)
      continue
    # Upload succeeded -- call platform callbacks and update count
    let envBase = cast[uint](addr rxl_hwdesc_env[0])
    let getStatusFn = cast[ptr pointer](envBase + 20)[]
    if getStatusFn != nil:
      cast[proc() {.cdecl.}](getStatusFn)()
    let curCount = cast[ptr uint8](descAddr + 21)[]
    let newUploadCount = cast[ptr uint32](uploadEnv + 20)[] + curCount.uint32
    cast[ptr uint32](uploadEnv + 20)[] = newUploadCount
    let cleanFn = cast[ptr pointer](envBase + 24)[]
    if cleanFn != nil:
      cast[proc() {.cdecl.}](cleanFn)()
    entry = co_list_pop_front(addr rxuUploadList)

# ###########################################################################
#                  VIF Management (vif_mgmt_*)
# ###########################################################################

proc vif_mgmt_entry_init*(vifEntry: pointer) {.exportc, cdecl.} =
  ## Initialize a VIF entry to default state.
  ## Sets vifType=4 (free), vifIdx/instNbr=127, clears chan_ctxt and lists.
  let v = cast[uint](vifEntry)
  cast[ptr uint8](v + 86)[] = 4      # vifType = free
  cast[ptr uint8](v + 89)[] = 127    # instNbr = 0x7F (invalid)
  cast[ptr uint8](v + 90)[] = 127    # secondary idx = 0x7F
  cast[ptr uint32](v + 64)[] = 0     # chan_ctxt = NULL

proc vif_mgmt_add_to_list*(vifEntry: pointer) {.exportc, cdecl.} =
  ## Add VIF entry to the active VIF list and notify platform.
  ## Placeholder: sends notification to platform layer.
  discard

proc vif_mgmt_init*() {.exportc, cdecl.} =
  ## Initialize VIF management.
  ## From blob (67 instrs): zeroes vif_mgmt_env, inits two CoLists (free + active),
  ## zeroes both VIF entries (1512 bytes each), sets default fields, pushes both
  ## entries onto the free list, then tail-calls co_list_push_back for the second.
  let envBase = cast[uint](addr vif_mgmt_env[0])
  let vifTabBase = cast[uint](addr vif_info_tab[0])

  # Zero vif_mgmt_env (20 bytes)
  discard c_memset(cast[pointer](envBase), 0, 20.csize_t)

  # Init the free VIF list at vif_mgmt_env+0
  co_list_init(cast[ptr CoList](envBase))

  # Init the active VIF list at vif_mgmt_env+8
  co_list_init(cast[ptr CoList](envBase + 8))

  # Zero first VIF entry (1512 bytes)
  discard c_memset(cast[pointer](vifTabBase), 0, VIF_ENTRY_SIZE.csize_t)

  # Set default fields for VIF entry 0
  let vif0 = vifTabBase
  cast[ptr uint8](vif0 + 86)[] = 4       # vifType = 4 (free)
  cast[ptr uint8](vif0 + 89)[] = 127     # instNbr = 0x7F (invalid)
  cast[ptr uint8](vif0 + 90)[] = 127     # secondary idx = 0x7F

  # Store vif_mgmt_bcn_to_evt callback at vif+44 (blob value, NOT bcn_to_prog)
  # and self-pointer at vif+48.
  let bcnToEvtAddr = cast[pointer](vif_mgmt_bcn_to_evt)
  cast[ptr pointer](vif0 + 44)[] = bcnToEvtAddr
  cast[ptr pointer](vif0 + 48)[] = cast[pointer](vif0)

  # Push VIF entry 0 onto the free list
  co_list_push_back(cast[ptr CoList](envBase), cast[ptr CoListHdr](vif0))

  # Zero second VIF entry (1512 bytes) at vif_info_tab + 0x5E8
  let vif1 = vifTabBase + VIF_ENTRY_SIZE.uint
  discard c_memset(cast[pointer](vif1), 0, VIF_ENTRY_SIZE.csize_t)

  # Store bcn callback at vif1+44 and self-ptr at vif1+48. Blob loads
  # a5 = vif_info_tab + 0x600 (= vif1 + 24) and does `sw s2, 20(a5);
  # sw a1, 24(a5)` — i.e. (vif1+24)+20 = vif1+44, (vif1+24)+24 = vif1+48.
  let vif1Entry = vif1
  cast[ptr pointer](vif1Entry + 44)[] = bcnToEvtAddr
  cast[ptr pointer](vif1Entry + 48)[] = cast[pointer](vif1Entry)

  # Set default fields for VIF entry 1 (at vif_info_tab + 1512 + offsets)
  # The blob computes 1598 = 1512 + 86, 1601 = 1512 + 89, 1602 = 1512 + 90
  cast[ptr uint8](vif1Entry + 86)[] = 4     # vifType = 4 (free)
  cast[ptr uint8](vif1Entry + 89)[] = 127   # instNbr = 0x7F
  cast[ptr uint8](vif1Entry + 90)[] = 127   # secondary idx = 0x7F

  # Push VIF entry 1 onto the free list (tail call in blob)
  co_list_push_back(cast[ptr CoList](envBase), cast[ptr CoListHdr](vif1Entry))

proc vif_mgmt_register*(macAddr: pointer, vifType: uint8, p2p: bool, vifIdxOut: ptr uint8): uint8 {.exportc, cdecl.} =
  ## Register a new VIF (143 instrs).
  ## From blob: checks vif_mgmt_env[0] (active list head). If vif_mgmt_env[8]
  ## is nonzero, validates MAC address against platform MAC registers. Then calls
  ## mm_hw_info_set. Pops free VIF from vif_mgmt_env list via co_list_pop_front.
  ## Sets vifType, copies MAC addr, computes vifIdx, sets timer constants,
  ## For STA type: increments STA count, sets up STA-specific fields, calls
  ## wpa_cbs[0]->init callback. For AP type: calls mm_hw_ap_info_set on first AP,
  ## increments AP count, calls mm_bcn_init_vif. Then calls td_start and
  ## co_list_push_back to add to active VIF list.
  let envBase = cast[uint](addr vif_mgmt_env[0])
  let vifTabBase = cast[uint](addr vif_info_tab[0])
  # Check if VIF management is initialized (vif_mgmt_env[0] = list head)
  let listHead = cast[ptr pointer](envBase)[]
  if listHead == nil:
    return 1
  # Check if platform MAC address filter is active (vif_mgmt_env+8)
  let platFilter = cast[ptr pointer](envBase + 8)[]
  if platFilter != nil:
    # Validate MAC address against platform registers at 0x24B00000
    let mb = cast[ptr UncheckedArray[uint8]](macAddr)
    let mac32 = mb[0].uint32 or (mb[1].uint32 shl 8) or
                (mb[2].uint32 shl 16) or (mb[3].uint32 shl 24)
    let platMac32 = regRead(0x24B00010'u32)  # platform MAC low 32 bits
    if mac32 != platMac32:
      return 1
    let mac16hi = mb[4].uint16 or (mb[5].uint16 shl 8)
    let platMac16 = cast[uint16](regRead(0x24B00014'u32))
    let macMask = regRead(0x24B0001C'u32)
    let diff = (mac16hi.uint32 xor platMac16.uint32) and (not macMask)
    if diff != 0:
      return 1
    # Set filter flags: OR bit 16 into mm_env[1], write combined filter to RX ctrl
    let mmEnvBase = cast[uint](addr mm_env[0])
    let env1 = cast[ptr uint32](mmEnvBase + 4)[]
    cast[ptr uint32](mmEnvBase + 4)[] = env1 or 16
    let env0 = cast[ptr uint32](mmEnvBase)[]
    regWrite(MACHW_RX_CNTRL_REG, (env1 or 16) or env0)
  # Set up HW info
  mm_hw_info_set(macAddr)
  # Pop free VIF entry from list
  let entry = co_list_pop_front(cast[ptr CoList](envBase))
  if entry == nil:
    return 1
  let vifEntry = cast[uint](entry)
  # Set VIF type
  cast[ptr uint8](vifEntry + 86)[] = vifType
  # Copy MAC address (6 bytes) to vif+80
  discard c_memcpy(cast[pointer](vifEntry + 80), macAddr, 6.csize_t)
  # Compute VIF index from pointer arithmetic (blob uses fixed-point multiply trick)
  let rawDiff = vifEntry - vifTabBase
  let vifIdx = (rawDiff div VIF_ENTRY_SIZE.uint).uint8
  cast[ptr uint8](vifEntry + 87)[] = vifIdx
  # Set timer constants (matching blob values)
  cast[ptr uint32](vifEntry + 8)[] = 0x0A47'u32
  cast[ptr uint32](vifEntry + 12)[] = 0x0A43'u32
  cast[ptr uint32](vifEntry + 16)[] = 0x5E432'u32
  cast[ptr uint32](vifEntry + 20)[] = 0x2F322'u32
  cast[ptr uint32](vifEntry + 64)[] = 0
  cast[ptr uint8](vifEntry + 76)[] = vifIdx
  # Type-specific initialization
  if vifType == VIF_TYPE_STA:
    # STA mode
    let staCnt = cast[ptr uint8](envBase + 16)[]
    cast[ptr uint32](vifEntry + 32)[] = cast[uint32](vifEntry)  # self-pointer
    cast[ptr uint8](envBase + 16)[] = staCnt + 1
    # Set up STA-mode timer callbacks
    let bcnTimeoutCb = cast[pointer](mm_sta_timer_bcn_timeout)
    let staTbttCb = cast[pointer](mm_sta_tbtt)
    let dataTimeoutCb = cast[pointer](mm_sta_timer_data_timeout)
    cast[ptr pointer](vifEntry + 28)[] = staTbttCb
    # Timer at vif+128: bcn_timeout callback at +16, vif ptr at +20
    cast[ptr pointer](vifEntry + 128 + 16)[] = bcnTimeoutCb
    cast[ptr pointer](vifEntry + 128 + 20)[] = cast[pointer](vifEntry)
    # Timer at vif+128+48: data_timeout callback at +48, vif ptr at +52
    cast[ptr pointer](vifEntry + 128 + 48)[] = dataTimeoutCb
    cast[ptr pointer](vifEntry + 128 + 52)[] = cast[pointer](vifEntry)
    # STA-specific fields
    cast[ptr uint8](vifEntry + 96)[] = 0xFF  # assocStaIdx = none
    cast[ptr uint16](vifEntry + 192)[] = 0
    # Call WPA init callback if available
    let wpaCbsPtr = cast[uint](addr wpa_cbs)
    let wpaCbsVal = cast[ptr pointer](wpaCbsPtr)[]
    if wpaCbsVal != nil:
      let initFn = cast[ptr pointer](cast[uint](wpaCbsVal))[]
      if initFn != nil:
        cast[proc(){.cdecl.}](initFn)()
  elif vifType == VIF_TYPE_AP:
    # AP mode
    let apCnt = cast[ptr uint8](envBase + 17)[]
    if apCnt == 0:
      # First AP VIF: set HW AP info
      mm_hw_ap_info_set(0)
    let newApCnt = apCnt + 1
    cast[ptr uint8](envBase + 17)[] = newApCnt
    # Initialize beacon for this VIF
    mm_bcn_init_vif(cast[pointer](vifEntry))
  # Common: call td_start, push to active VIF list, write vifIdx output
  td_start(vifIdx)
  vifIdxOut[] = vifIdx
  let activeListAddr = envBase + 8  # vif_mgmt_env+8 is the active VIF list
  co_list_push_back(cast[ptr CoList](activeListAddr), cast[ptr CoListHdr](vifEntry))
  return 0

proc vif_mgmt_unregister*(vifIdx: uint8) {.exportc, cdecl.} =
  ## Unregister a VIF (111 instrs).
  ## From blob: removes VIF from active list, decrements STA/AP count,
  ## clears timers, resets TD, zeroes the VIF entry, reinitializes to free
  ## state, pushes back onto free list, then tail-calls co_list_push_back.
  let vifTabBase = cast[uint](addr vif_info_tab[0])
  let envBase = cast[uint](addr vif_mgmt_env[0])
  let vifEntry = vifTabBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let activeList = cast[ptr CoList](envBase + 8)

  # Remove VIF from active list
  co_list_extract(activeList, cast[ptr CoListHdr](vifEntry))

  # Check VIF type and decrement appropriate counter
  let vifType = cast[ptr uint8](vifEntry + 86)[]
  if vifType == VIF_TYPE_STA:
    # Decrement STA count
    let staCnt = cast[ptr uint8](envBase + 16)[]
    cast[ptr uint8](envBase + 16)[] = staCnt - 1
  elif vifType == VIF_TYPE_AP:
    # Decrement AP count
    let apCnt = cast[ptr uint8](envBase + 17)[]
    let newApCnt = (apCnt - 1) and 0xFF
    cast[ptr uint8](envBase + 17)[] = newApCnt
    if newApCnt == 0:
      # Last AP removed: reset HW AP info
      mm_hw_ap_info_reset(0)

  # Check if this was the last VIF (STA+AP count == 1)
  let totalSta = cast[ptr uint8](envBase + 16)[]
  let totalAp = cast[ptr uint8](envBase + 17)[]
  if totalSta.uint + totalAp.uint == 1:
    # Single VIF remaining: update RX filter and HW config
    let mmEnvBase = cast[uint](addr mm_env[0])
    let env1 = cast[ptr uint32](mmEnvBase + 4)[]
    let newEnv1 = env1 and (not 16'u32)  # clear bit 4
    cast[ptr uint32](mmEnvBase + 4)[] = newEnv1

    let env0 = cast[ptr uint32](mmEnvBase)[]
    regWrite(MACHW_RX_CNTRL_REG, newEnv1 or env0)

    # Update beacon control from remaining VIF's channel context
    let otherVifIdx = if vifIdx == 0: 1'u8 else: 0'u8
    let otherVif = vifTabBase + otherVifIdx.uint * VIF_ENTRY_SIZE.uint
    let chanPtr = cast[ptr uint32](otherVif + 56)[]
    regWrite(MACHW_BASE + 0x020'u, chanPtr)
    let chanHalf = cast[ptr uint16](otherVif + 60)[]
    regWrite(MACHW_BASE + 0x024'u, chanHalf.uint32)

  # Check if WPA deinit callback should be called (for STA type)
  let otherVifEntry = vifTabBase  # check first VIF
  var scanIdx: uint8 = 0
  while scanIdx < MAX_VIFS.uint8:
    let scanVif = vifTabBase + scanIdx.uint * VIF_ENTRY_SIZE.uint
    let scanType = cast[ptr uint8](scanVif + 86)[]
    if scanType == VIF_TYPE_STA:
      break
    scanIdx += 1

  if scanIdx >= MAX_VIFS.uint8:
    # No STA VIFs left: call WPA deinit
    let wpaCbsPtr = cast[ptr pointer](addr wpa_cbs)[]
    if wpaCbsPtr != nil:
      let deinitFn = cast[ptr pointer](cast[uint](wpaCbsPtr) + 4)[]
      if deinitFn != nil:
        cast[proc(){.cdecl.}](deinitFn)()

  # Check for AP beacon clear
  let otherVifType = cast[ptr uint8](vifTabBase + (if vifIdx == 0: VIF_ENTRY_SIZE.uint else: 0) + 86)[]
  if otherVifType == VIF_TYPE_AP:
    txl_cntrl_clear_bcn_ac()

  # Clear timers at vif+24 (offset 18+vifBase) and vif+40
  mm_timer_clear(cast[pointer](vifEntry + 24))
  mm_timer_clear(cast[pointer](vifEntry + 40))

  # Reset traffic detection for this VIF
  td_reset(vifIdx)

  # Zero the entire VIF entry (1512 bytes)
  discard c_memset(cast[pointer](vifEntry), 0, VIF_ENTRY_SIZE.csize_t)

  # Reinitialize entry to free state
  cast[ptr uint8](vifEntry + 86)[] = 4      # vifType = free
  cast[ptr uint8](vifEntry + 89)[] = 127    # instNbr = 0x7F
  cast[ptr uint8](vifEntry + 90)[] = 127    # secondary idx = 0x7F
  # Restore bcn-timeout callback. Blob stores &vif_mgmt_bcn_to_evt (NOT bcn_to_prog).
  cast[ptr pointer](vifEntry + 44)[] = cast[pointer](vif_mgmt_bcn_to_evt)
  cast[ptr pointer](vifEntry + 48)[] = cast[pointer](vifEntry)

  # Push entry back onto free list
  co_list_push_back(cast[ptr CoList](envBase), cast[ptr CoListHdr](vifEntry))

proc vif_mgmt_add_key*(vifIdx: uint8, param: pointer) {.exportc, cdecl.} =
  ## Add encryption key for a VIF (185 instructions).
  ##
  ## param layout (byte offsets from disassembly -- same as mm_sec_machwkey_wr param):
  ##   [0]   u8: staIndex / MAC address index
  ##   [34]  u8: cipherType (0=WEP40, 1=TKIP, 3=WEP104, 5=CCMP)
  ##   [35]  u8: keyIdx (key slot)
  ##   [36]  u8: spp
  ##   [37]  u8: has_rx_pn flag
  ##   [8..23]  key material
  ##   [24..39] RX PN / TKIP MIC key (6 x 32-bit words at [24..47])
  ##   [44..51] TX/RX sequence counters (2 x 32-bit words)
  ##
  ## VIF entry layout (stride = 1512 = 0x5E8 bytes):
  ##   +528 (0x210): start of per-key entries (8 entries, 16 bytes each = 128 bytes)
  ##   +656 (0x290): per-key PN low  (offset from vif+vifIdx*1512)
  ##   +660 (0x294): per-key PN high
  ##   +664 (0x298): key material (4 x 32-bit words for TKIP)
  ##   +680 (0x2A8): cipher type
  ##   +681 (0x2A9): sta index
  ##   +682 (0x2AA): keyIdx (key slot HW index written by mm_sec_machwaddr_wr)
  ##   +683 (0x2AB): key installed flag
  ##   +684 (0x2AC): has_rx_pn flag
  ##   +1488 (0x5D0): default CCMP key material pointer (for rx)
  ##   +1492 (0x5D4): CCMP installed key material pointer

  let p = cast[ptr UncheckedArray[uint8]](param)
  let keySlot = p[35]  # s7 in blob = keyIdx field from param
  let staIdx = p[0]    # s9

  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifOff = keySlot.uint * VIF_ENTRY_SIZE.uint  # s6/s8
  let vifEntry = vifBase + vifOff  # s2 = vif_info_tab + keySlot * 1512

  # Store keyIdx (from vifIdx argument) to vif+682
  cast[ptr uint8](vifEntry + 682)[] = vifIdx

  # Copy cipher type from param[34] to vif+680
  let cipherType = p[34]
  cast[ptr uint8](vifEntry + 680)[] = cipherType

  # Copy sta index from param[0] to vif+681
  cast[ptr uint8](vifEntry + 681)[] = p[0]

  # Copy has_rx_pn from param[37] to vif+684
  let hasRxPn = p[37]
  cast[ptr uint8](vifEntry + 684)[] = hasRxPn

  # Zero the per-key context area at vif+528, 128 bytes
  let keyCtxBase = vifEntry + 528  # s3
  discard c_memset(cast[pointer](keyCtxBase), 0, 128.csize_t)

  # Dispatch on cipher type
  case cipherType
  of 0, 3:
    # WEP40 / WEP104: generate random PN, store to vif+656/660
    # Uses LCG PRNG: next = state * 0x41C64E6D + 0x3039
    let oldState = rcPrngState
    rcPrngState = oldState * RC_PRNG_MULT + RC_PRNG_INCR
    let newState = rcPrngState
    let pnLo = (newState shr 16).uint32  # top 16 bits as low PN
    cast[ptr uint32](vifEntry + 656)[] = pnLo
    cast[ptr uint32](vifEntry + 660)[] = 0

  of 1:
    # TKIP: zero PN, copy 6 key material words from param[24..47]
    cast[ptr uint32](vifEntry + 656)[] = 0
    cast[ptr uint32](vifEntry + 660)[] = 0
    cast[ptr uint32](vifEntry + 664)[] = cast[ptr uint32](cast[uint](param) + 24)[]
    cast[ptr uint32](vifEntry + 668)[] = cast[ptr uint32](cast[uint](param) + 28)[]
    cast[ptr uint32](vifEntry + 672)[] = cast[ptr uint32](cast[uint](param) + 32)[]
    cast[ptr uint32](vifEntry + 676)[] = cast[ptr uint32](cast[uint](param) + 36)[]

  of 5:
    # CCMP: copy 16 bytes of key material from param[8..23] to vif+664
    discard c_memcpy(cast[pointer](vifEntry + 664),
                     cast[pointer](cast[uint](param) + 8), 16.csize_t)
    # Zero PN
    cast[ptr uint32](vifEntry + 656)[] = 0
    cast[ptr uint32](vifEntry + 660)[] = 0

  else:
    # Unknown cipher: zero PN and clear key context
    cast[ptr uint32](vifEntry + 656)[] = 0
    cast[ptr uint32](vifEntry + 660)[] = 0

  # Read TX/RX sequence counters from param[44..51] (PN from host)
  let pnLo = p[44].uint32 or (p[45].uint32 shl 8) or
             (p[46].uint32 shl 16) or (p[47].uint32 shl 24)
  let pnHi = p[48].uint32 or (p[49].uint32 shl 8) or
             (p[50].uint32 shl 16) or (p[51].uint32 shl 24)

  if (pnLo or pnHi) != 0:
    # Host provided a non-zero PN; check if has_rx_pn and cipher != CCMP
    let curCipher = cast[ptr uint8](vifEntry + 680)[]
    let curHasRxPn = cast[ptr uint8](vifEntry + 684)[]
    if curHasRxPn == 0 or curCipher == 5:
      # Broadcast PN: replicate to all 8 key context slots
      var slot = 0'u32
      let base = vifEntry + 528  # keyCtxBase already = s8+s1
      # Clear installed flag (will set below)
      cast[ptr uint8](vifEntry + 683)[] = 0
      var i = 0
      while i < 8:
        cast[ptr uint32](base + i.uint * 16 + 0)[] = pnLo
        cast[ptr uint32](base + i.uint * 16 + 4)[] = pnHi
        inc i
    else:
      # Unicast PN: write to per-STA rx reorder context
      # staIdx * 10 + 33, shifted left 4, offset from vifBase+vifOff+vifBase(s1)
      let reorderBase = (staIdx.uint * 10 + 33) * 16 + vifOff + vifBase
      var i = 0
      while i < 8:
        # Store PN pair at each slot
        let slotAddr = reorderBase + i.uint * 16
        # The blob calls a helper that stores two 32-bit values
        cast[ptr uint32](slotAddr + 0)[] = pnLo
        cast[ptr uint32](slotAddr + 4)[] = pnHi
        inc i

  # Validate replay counter before marking key installed
  # Blob calls replay_counter_validate at reloc 0x214 with key PN context
  let pnCtx = cast[pointer](vifEntry + 528)
  if replay_counter_validate(pnCtx):
    # Mark key as installed only if replay counter validates
    cast[ptr uint8](vifEntry + 683)[] = 1

  # If cipher type is CCMP, update the CCMP key material pointer
  let installedCipher = cast[ptr uint8](vifEntry + 680)[]
  if installedCipher == 5:
    # Store pointer to key context base in vif+1492
    let vifKeySlot = keySlot.uint * VIF_ENTRY_SIZE.uint + vifBase
    cast[ptr uint32](vifKeySlot + 1492)[] = cast[uint32](keyCtxBase)
  else:
    # Store to vif+1488 (default key pointer)
    let vifKeySlot = keySlot.uint * VIF_ENTRY_SIZE.uint + vifBase
    cast[ptr uint32](vifKeySlot + 1488)[] = cast[uint32](keyCtxBase)

proc vif_mgmt_del_key*(vifEntry: pointer, keySlot: uint8) {.exportc, cdecl, noinline.} =
  ## Delete encryption key for a VIF (35 instrs).
  ## noinline: blob calls this from mm_sec_machwkey_del.
  ## From blob: a0=vifEntry pointer, a1=keySlot index.
  ## Computes key context offset = keySlot * 160 + 528 within VIF entry.
  ## Clears the key valid flag at vif[keyOffset + 683-528] = vif[keySlot*160+683].
  ## Then checks if vif+1488 (default TX key ptr) points to this key context.
  ## If so, scans other key slots (0..3) for a valid key to replace it.
  ## If no valid key found, clears vif+1488. Similarly checks vif+1492 (group key).
  {.emit: "__asm__ volatile(\"\" ::: \"memory\");".}
  let vif = cast[uint](vifEntry)
  let keySlotU = keySlot.uint
  let keyOffset = keySlotU * 160 + 528
  # Clear key valid flag
  cast[ptr uint8](vif + keySlotU * 160 + 683)[] = 0
  # Check if this was the default TX key (vif+1488)
  let defaultKeyPtr = cast[ptr uint32](vif + 1488)[]
  let thisKeyBase = vif + keyOffset
  if defaultKeyPtr == cast[uint32](thisKeyBase):
    # This key was the default; find replacement
    cast[ptr uint32](vif + 1488)[] = 0
    # Scan slots 0..3 for a valid key
    for i in 0'u .. 3'u:
      let slotValid = cast[ptr uint8](vif + i * 160 + 683)[]
      if slotValid != 0:
        cast[ptr uint32](vif + 1488)[] = cast[uint32](vif + i * 160 + 528)
        break
  # Check group key pointer (vif+1492)
  let groupKeyPtr = cast[ptr uint32](vif + 1492)[]
  if groupKeyPtr == cast[uint32](thisKeyBase):
    # Scan for replacement group key
    let validFlag = cast[ptr uint8](vif + keySlotU * 160 + 1323 - 528)[]
    if validFlag == 0:
      cast[ptr uint32](vif + 1492)[] = 0

proc vif_mgmt_send_postponed_frame*(vifEntry: pointer) {.exportc, cdecl.} =
  ## Flush the per-VIF postponed-STA list by calling
  ## sta_mgmt_send_postponed_frame on each STA entry.
  ## Blob algorithm:
  ##   s1 = a0                                   ; vifEntry
  ##   s0 = *(u32*)(vifEntry + 340)              ; postponed-STA list head
  ##   while s0 != 0:
  ##     sta_mgmt_send_postponed_frame(vifEntry, s0, 0)
  ##     s0 = *(u32*)s0                          ; next
  ## Prior Nim bug: called txl_cntrl_push_int(0, cur) — completely wrong:
  ## it would try to push STA list nodes as TX frames.
  let vif = cast[uint](vifEntry)
  var cur = cast[ptr pointer](vif + 340)[]
  while cur != nil:
    let next = cast[ptr pointer](cast[uint](cur))[]
    discard sta_mgmt_send_postponed_frame(vifEntry, cur, 0'u32)
    cur = next

proc vif_mgmt_reset*() {.exportc, cdecl.} =
  ## "Reset" step in the VIF-management path.
  ## Blob algorithm:
  ##   s0 = *(u32*)(vif_mgmt_env + 8)      ; head of active vif list
  ##   while s0 != 0:
  ##     vif_mgmt_send_postponed_frame(s0) ; flush postponed frames
  ##     s0 = *(u32*)s0                    ; next vif
  ## Prior Nim bug: walked the active-vif list but called
  ## vif_mgmt_entry_init (reinit fields) instead of flushing postponed frames.
  ## That would corrupt live VIF state on every reset-trigger path.
  let envBase = cast[uint](addr vif_mgmt_env[0])
  var cur = cast[ptr pointer](envBase + 8)[]
  while cur != nil:
    let next = cast[ptr pointer](cast[uint](cur))[]
    vif_mgmt_send_postponed_frame(cur)
    cur = next

proc vif_mgmt_bcn_recv*(vifEntry: pointer) {.exportc, cdecl.} =
  ## Beacon received for a VIF.
  ## Blob algorithm:
  ##   a5 = &ps_env
  ##   a4 = *(u8*)(ps_env+0)                    ; PS active flag
  ##   if a4 == 0: return
  ##   a5 = *(u32*)(ps_env+4)                   ; PS env flags
  ##   if (a5 & 8): return
  ##   a5 = *(u32*)(a0+4)                       ; vif->linked_non_ap
  ##   if a5 != 0: return
  ##   mm_timer_clear(a0+40)                    ; kill bcn-timeout watchdog
  ##   tail-call vif_mgmt_bcn_to_evt(a0)        ; post bcn-rx event
  ## Prior Nim bug: read vif_mgmt_env (wrong global) and called
  ## vif_mgmt_bcn_to_prog (schedule next bcn timeout) instead of
  ## vif_mgmt_bcn_to_evt (post the rx-event now).
  let envBase = cast[uint](addr ps_env[0])
  let activeFlag = cast[ptr uint8](envBase)[]
  if activeFlag == 0:
    return
  let envFlags = cast[ptr uint32](envBase + 4)[]
  if (envFlags and 8) != 0:
    return
  let vif = cast[uint](vifEntry)
  let linkStateWord = cast[ptr uint32](vif + 4)[]
  if linkStateWord != 0:
    return
  mm_timer_clear(cast[pointer](vif + 40))
  vif_mgmt_bcn_to_evt(vifEntry)

proc vif_mgmt_bcn_to_prog*(vifEntry: pointer) {.exportc, cdecl.} =
  ## Program beacon timeout for a VIF (from blob).
  ## Reads MAC timestamp, adds 10000 us (0x2710), then tail-calls
  ## mm_timer_set on the VIF's beacon timer at vifEntry+40.
  let macTime = macTimeNow()
  let targetTime = macTime + 0x2710'u32  # 10000 us
  mm_timer_set(cast[pointer](cast[uint](vifEntry) + 40), targetTime)

proc vif_mgmt_set_ap_bcn_int*(vifEntry: pointer, interval: uint16) {.exportc, cdecl.} =
  ## Set AP beacon interval for a VIF (44 instrs in blob).
  ## Stores interval at vif+322. Under interrupt protection (csrrci/csrsi),
  ## reads env AP count. If only 1 VIF: sets default divisor/multiplier.
  ## If multiple: finds min interval, updates each VIF's divisor (vif+324)
  ## and multiplier (vif+325). Writes min interval to MACHW beacon register.
  let vif = cast[uint](vifEntry)
  # Store this VIF's beacon interval at vif+322
  cast[ptr uint16](vif + 322)[] = interval
  # Save and disable interrupts
  let prevIrq = irqSave()
  let envBase = cast[uint](addr vif_mgmt_env[0])
  let apCnt = cast[ptr uint8](envBase + 17)[]
  var minInterval = interval
  # Single VIF case
  if apCnt <= 1:
    let vifInstNbr = cast[ptr uint8](vif + 87)[]
    cast[ptr uint8](envBase + 18)[] = vifInstNbr
    cast[ptr uint16](vif + 324)[] = 0x0101'u16  # divisor=1, multiplier=1
  else:
    # Multiple VIFs: find the dominant (min interval) VIF
    let vifTabBase = cast[uint](addr vif_info_tab[0])
    let otherVifIdx = cast[ptr uint8](envBase + 18)[]
    let otherVif = vifTabBase + otherVifIdx.uint * VIF_ENTRY_SIZE.uint
    let otherInt = cast[ptr uint16](otherVif + 322)[]
    if interval < otherInt:
      let vifInstNbr = cast[ptr uint8](vif + 87)[]
      cast[ptr uint8](envBase + 18)[] = vifInstNbr
    else:
      minInterval = otherInt
    # Walk VIF linked list (at envBase+8) to update each VIF's beacon divisor
    var curVifPtr = cast[ptr pointer](envBase + 8)[]
    while curVifPtr != nil:
      let cv = cast[uint](curVifPtr)
      let cvInt = cast[ptr uint16](cv + 322)[]
      cast[ptr uint8](cv + 325)[] = 1  # multiplier flag
      let divisor = cvInt div minInterval
      cast[ptr uint8](cv + 324)[] = divisor.uint8
      curVifPtr = cast[ptr pointer](cv)[]
  # Write minimum interval to HW beacon interval register (lower 16 bits)
  let curVal = regRead(MACHW_BCN_INT_REG)
  let masked = curVal and 0xFFFF0000'u32
  regWrite(MACHW_BCN_INT_REG, masked or minInterval.uint32)
  # Restore interrupts
  irqRestore(prevIrq)

proc vif_mgmt_switch_channel*(vifIdx: uint8, param: pointer) {.exportc, cdecl.} =
  ## Switch channel for a VIF.
  discard

proc vif_mgmt_get_vif*(vifIdx: uint8): pointer {.exportc, cdecl, noinline.} =
  ## Get VIF info pointer by index.
  ## From blob (8 instrs): if vifIdx > 1, returns null.
  ## Otherwise computes vif_info_tab + vifIdx * 1512 and returns pointer.
  if vifIdx >= MAX_VIFS.uint8:
    return nil
  let vifTab = cast[uint](addr vif_info_tab[0])
  return cast[pointer](vifTab + vifIdx.uint * VIF_ENTRY_SIZE.uint)

proc vif_mgmt_get_first_ap_inf*(): pointer {.exportc, cdecl.} =
  ## Get the first AP VIF info pointer.
  ## From blob (10 instrs): checks vif_mgmt_env[17] (AP VIF count).
  ## If 0, returns null. Otherwise walks VIF list from vif_mgmt_env[8],
  ## returning first entry with type == 2 (AP).
  let envBase = cast[uint](addr vif_mgmt_env[0])
  let apCount = cast[ptr uint8](envBase + 17)[]
  if apCount == 0:
    return nil
  var entry = cast[pointer](cast[ptr uint32](envBase + 8)[])
  while entry != nil:
    let vifType = cast[ptr uint8](cast[uint](entry) + 86)[]
    if vifType == VIF_TYPE_AP:
      return entry
    entry = cast[ptr pointer](entry)[]  # follow linked list next
  return nil

proc vif_mgmt_statistic_dump*() {.exportc, cdecl.} =
  ## Dump VIF statistics for debugging (92 instrs).
  ## Walks the VIF linked list (from vif_mgmt_env), for each VIF:
  ##   logs VIF type (STA/AP), RX/TX packet counts, beacon counts.
  ## Uses g_bl_ops_funcs[4] (printf) and g_bl_ops_funcs[8] (puts) for output.
  ##
  ## Assembly trace:
  ##   s0 = vif list head (from vif_mgmt_env)
  ##   s1 = g_bl_ops_funcs base
  ##   s4 = 2 (AP type constant for comparison)
  ##   s5..s9 = format string pointers for each field
  ##   Loop while s0 != nil:
  ##     check vif.type(+86): print "AP" or "STA" via printf
  ##     if STA: print rx_count(+124), tx_count(+128), total, beacon_cnt(+120),
  ##       beacon_period(+132 >> 10), last_beacon(+136 >> 10)
  ##     print separator via puts
  ##     s0 = vif.next(+0)
  let vifMgmtBase = cast[uint](addr vif_mgmt_env[0])
  var vifPtr = cast[ptr pointer](vifMgmtBase)[]  # linked list head
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  let printFnPtr = cast[ptr pointer](opsBase + 4)[]
  let putsFnPtr = cast[ptr pointer](opsBase + 8)[]
  if printFnPtr == nil or putsFnPtr == nil:
    return
  type PrintfFn = proc(fmt: cstring, args: uint32) {.cdecl, varargs.}
  type PutsFn = proc(s: cstring) {.cdecl.}
  let printf = cast[PrintfFn](printFnPtr)
  let puts = cast[PutsFn](putsFnPtr)
  while vifPtr != nil:
    let vifAddr = cast[uint](vifPtr)
    let vifType = cast[ptr uint8](vifAddr + 86)[]
    if vifType == 2:  # AP
      printf("VIF[AP] %p:", cast[uint32](vifPtr))
    else:
      printf("VIF[STA] %p:", cast[uint32](vifPtr))
    if vifType == 0:  # STA-specific stats
      let rxCount = cast[ptr uint32](vifAddr + 124)[]
      printf(" rx=%d", rxCount)
      let txCount = cast[ptr uint32](vifAddr + 128)[]
      printf(" tx=%d", txCount)
      printf(" total=%d", rxCount + txCount)
      let bcnCount = cast[ptr uint32](vifAddr + 120)[]
      printf(" bcn=%d", bcnCount)
      let bcnPeriod = cast[ptr uint32](vifAddr + 132)[]
      printf(" period=%d", bcnPeriod shr 10)
      let lastBcn = cast[ptr uint32](vifAddr + 136)[]
      printf(" last=%d", lastBcn shr 10)
    puts("")
    # Follow linked list
    vifPtr = cast[ptr pointer](vifAddr)[]

# ###########################################################################
#                  STA Management (sta_mgmt_*)
# ###########################################################################

proc sta_mgmt_init*() {.exportc, cdecl.} =
  ## Initialize station management (84 instrs).
  ## From blob: calls co_list_init(&sta_info_env). Loops over the five normal
  ## STA entries, calling sta_mgmt_entry_init and co_list_push_back for each.
  ## Then initializes 2 extra "broadcast" STA entries at
  ## sta_info_tab+0x730 (entry 5 = broadcast STA for VIF 0) and sta_info_tab+0x8A0
  ## (entry 6 = broadcast STA for VIF 1). Sets up buffer control pointers,
  ## logs via g_bl_ops_funcs[0xCC], and stores cross-references between
  ## VIF and STA tables.
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEnd = staBase + STA_MGMT_FREE_STAS.uint * STA_ENTRY_SIZE.uint
  let vifBase = cast[uint](addr vif_info_tab[0])
  let blOps = cast[uint](addr g_bl_ops_funcs)
  # Initialize STA free list
  co_list_init(addr sta_info_env)
  # Init each STA entry and push to free list
  var cur = staBase
  while cur < staEnd:
    sta_mgmt_entry_init(cast[pointer](cur))
    co_list_push_back(addr sta_info_env, cast[ptr CoListHdr](cur))
    cur += STA_ENTRY_SIZE.uint
  # Initialize broadcast STA entry for VIF 0 at sta_info_tab + 0x730 (offset 1840)
  let bcStaVif0 = staBase + 0x730'u  # 10*368=3680, but blob uses 0x730=1840
  sta_mgmt_entry_init(cast[pointer](bcStaVif0))
  # Clear postponed flag at offset 0x757 from sta_info_tab base
  cast[ptr uint8](staBase + 0x757)[] = 0
  # Set up buffer control pointers for broadcast STA
  let bcmcDescBase = cast[uint](addr txl_buffer_control_desc_bcmc[0])
  let staEnvOffset0x800 = staBase + 0x800'u
  cast[ptr pointer](staEnvOffset0x800 + 112)[] = cast[pointer](bcmcDescBase)
  # Load vif_info_tab+0x5D0 (VIF 0 key material pointer area)
  let vif0KeyPtr = cast[ptr pointer](vifBase + 0x5D0)[]
  cast[ptr uint8](staBase + 0x778)[] = 0  # clear flag
  cast[ptr pointer](staEnvOffset0x800 + 36)[] = cast[pointer](vifBase + 0x5D0'u)
  # Log
  let logFn = cast[ptr pointer](blOps + 204)[]
  if logFn != nil:
    cast[proc(a0: uint32, a1: uint32, a2: pointer, a3: uint32, a4: uint32){.cdecl.}](logFn)(
      2, 0, nil, 157, 157)
  # Initialize broadcast STA entry for VIF 1 at sta_info_tab + 0x8A0
  let bcStaVif1 = staBase + 0x8A0'u
  sta_mgmt_entry_init(cast[pointer](bcStaVif1))
  cast[ptr uint8](staBase + 0x8C7)[] = 1  # mark as broadcast
  # Set up buffer control for VIF 1 broadcast
  let staEnvOffset0x980 = staBase + 0x980'u
  cast[ptr pointer](staEnvOffset0x980 + 96)[] = cast[pointer](bcmcDescBase + 0x3C'u)
  cast[ptr uint8](staBase + 0x8E8)[] = 0
  cast[ptr pointer](staEnvOffset0x980 + 20)[] = cast[pointer](vifBase + 0xBB8'u)
  # Final log via g_bl_ops_funcs
  let logFn2 = cast[ptr pointer](blOps + 204)[]
  let vif1KeyPtr = cast[ptr pointer](vifBase + 0xBB8)[]
  if logFn2 != nil:
    cast[proc(a0: uint32, a1: uint32, a2: pointer, a3: uint32, a4: uint32){.cdecl.}](logFn2)(
      2, 0, nil, 157, 157)

proc sta_mgmt_register*(param: pointer, staIdxOut: ptr uint8): uint8 {.exportc, cdecl.} =
  ## Register a station (126 instrs).
  ## From blob: pops free STA entry from sta_info_env list via co_list_pop_front,
  ## copies MAC addr/rates/caps from param, computes staIdx via pointer arithmetic,
  ## initializes postponed descriptor halfwords to 0xFFFF, links RC stats pointer,
  ## clears postponed flag, checks VIF HT flags, logs, links STA to VIF list.
  let pU = cast[uint](param)
  let staTabBase = cast[uint](addr sta_info_tab[0])
  let vifTabBase = cast[uint](addr vif_info_tab[0])
  let blOps = cast[uint](addr g_bl_ops_funcs)
  let instNbr = cast[ptr uint8](pU + 13)[]
  # Pop free STA entry from sta_info_env free list
  let entry = co_list_pop_front(addr sta_info_env)
  if entry == nil:
    return 1
  let staEntry = cast[uint](entry)
  # Copy MAC address (6 bytes) from param+6 to staEntry+4
  discard c_memcpy(cast[pointer](staEntry + 4), cast[pointer](pU + 6), 6.csize_t)
  # Set phy_bw_max (clamped to >= 16)
  var phyBwMax = cast[ptr uint8](pU + 12)[]
  if phyBwMax < 16: phyBwMax = 16
  cast[ptr uint8](staEntry + 38)[] = phyBwMax
  # Copy rates and capability fields
  cast[ptr uint16](staEntry + 32)[] = cast[ptr uint16](pU + 4)[]
  cast[ptr uint32](staEntry + 28)[] = cast[ptr uint32](pU)[]
  cast[ptr uint8](staEntry + 39)[] = instNbr
  cast[ptr uint8](staEntry + 43)[] = cast[ptr uint8](pU + 14)[]
  cast[ptr uint32](staEntry + 12)[] = cast[ptr uint32](pU + 16)[]
  cast[ptr uint32](staEntry + 16)[] = cast[ptr uint32](pU + 20)[]
  cast[ptr uint8](staEntry + 44)[] = cast[ptr uint8](pU + 24)[]
  # Compute station index via pointer arithmetic (blob uses fixed-point multiply)
  let rawDiff = staEntry - staTabBase
  let staIdx = (rawDiff div STA_ENTRY_SIZE.uint).uint8
  staIdxOut[] = staIdx
  cast[ptr uint8](staEntry + 40)[] = staIdx
  # Initial rate config
  cast[ptr uint32](staEntry + 24)[] = 0x19000'u32
  cast[ptr uint16](staEntry + 336)[] = 0xFFFF'u16
  # Initialize postponed frame descriptors: 9 halfwords at sta+338 stride 4, set to 0xFFFF
  var descAddr = staEntry + 338
  for i in 0 ..< 9:
    cast[ptr uint16](descAddr)[] = 0xFFFF'u16
    descAddr += 4
  # Store TX policy descriptor pointer at sta+320.
  # Vendor uses one 60-byte txl_buffer_control_desc entry per STA; rc_init
  # later writes the RC stats pointer at sta+324.
  let txPolicyBase = cast[uint](addr txl_buffer_control_desc[0])
  cast[ptr pointer](staEntry + STA_TX_POLICY_PTR_OFF.uint)[] =
    cast[pointer](txPolicyBase + staIdx.uint * 60'u)
  # Clear postponed flag at sta+72
  cast[ptr uint8](staEntry + 72)[] = 0
  # Check VIF HT flags at vif+1496
  let vifOffset = instNbr.uint * VIF_ENTRY_SIZE.uint
  let vifEntry = vifTabBase + vifOffset
  let vifFlags = cast[ptr uint32](vifEntry + 1496)[]
  let logFn = cast[ptr pointer](blOps + 204)[]
  if (vifFlags and 8) != 0:
    # HT-capable VIF: postponed list self-pointer at sta+240
    let postponedListAddr = staEntry + 240
    cast[ptr uint32](staEntry + 244)[] = cast[uint32](postponedListAddr)
    if logFn != nil:
      cast[proc(a0, a1: uint32, c: pointer, d, e: uint32){.cdecl.}](logFn)(2, 0, nil, 282, 282)
  else:
    # Non-HT VIF: point to VIF key material area at vif+1488
    let vifKeyAddr = vifOffset + 1488 + vifTabBase
    cast[ptr uint32](staEntry + 244)[] = cast[uint32](vifKeyAddr)
    let vifKeyData = cast[ptr uint32](vifEntry + 1488)[]
    if logFn != nil:
      cast[proc(a0, a1: uint32, c: pointer, d, e: uint32){.cdecl.}](logFn)(2, 0, nil, 293, 293)
  # Check HT extended flags (bit 4 at vif+1496)
  let vifFlags2 = cast[ptr uint32](vifEntry + 1496)[]
  if (vifFlags2 and 16) != 0:
    let rf = cast[ptr uint32](staEntry + 308)[]
    cast[ptr uint32](staEntry + 308)[] = rf or 8
  # Push STA onto VIF's STA list at vif+instNbr*1512+340
  let vifStaListAddr = vifOffset + 340 + vifTabBase
  co_list_push_back(cast[ptr CoList](vifStaListAddr), cast[ptr CoListHdr](staEntry))
  # Mark station as active
  cast[ptr uint8](staEntry + 42)[] = 1
  return 0

proc sta_mgmt_unregister*(staIdx: uint8) {.exportc, cdecl.} =
  ## Unregister a station (29 instrs).
  ## From blob: computes STA entry = sta_info_tab + staIdx*368 (using custom mul insn),
  ## looks up VIF entry from STA's instNbr (offset 39) * 1512,
  ## calls co_list_extract to remove STA from VIF's STA list (at vif+340),
  ## calls sta_mgmt_entry_init to reset the STA entry,
  ## then pushes back to sta_info_env free list via co_list_push_back.
  let staBase = cast[uint](addr sta_info_tab[0])
  let vifBase = cast[uint](addr vif_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let instNbr = cast[ptr uint8](staEntry + 39)[]
  # Compute VIF STA list address at vif_info_tab + instNbr*1512 + 340
  let vifStaListAddr = vifBase + instNbr.uint * VIF_ENTRY_SIZE.uint + 340
  # Extract STA from VIF's STA list
  co_list_extract(cast[ptr CoList](vifStaListAddr), cast[ptr CoListHdr](staEntry))
  # Re-initialize the STA entry (clears all fields)
  sta_mgmt_entry_init(cast[pointer](staEntry))
  # Push back to free list
  co_list_push_back(addr sta_info_env, cast[ptr CoListHdr](staEntry))

proc sta_mgmt_add_key*(staIdx: uint8, param: pointer) {.exportc, cdecl.} =
  ## Add encryption key for a station (81 instrs).
  ## a0 = key parameter struct, a1 = STA index.
  ## NOTE: blob ABI has a0=param, a1=staIdx (reversed from Nim signature).
  ## The C export uses the Nim parameter order; the blob order is handled by linkage.
  ##
  ## Assembly trace:
  ##   s4 = param[1] (key index from param)
  ##   s0 = STA_ENTRY_SIZE(368) * s4 (offset into sta_info_tab)
  ##   s1 = param pointer
  ##   s2 = sta_info_tab base
  ##   Stores param[1] at sta[234] (key HW index)
  ##   Stores param[52] at sta[232] (key type: 0=none, 1=CCMP, 3=TKIP)
  ##   Stores param[0] at sta[233] (key cipher suite)
  ##   Stores param[55] at sta[236] (key flags)
  ##   memset(sta+80, 0, 128) -- clear key material area
  ##   Dispatches on key type:
  ##     type 1 (CCMP): clear PN (sta+208..215), copy 16-byte key from param+24..39 to sta+208
  ##     type 3 (TKIP): generate PRNG-based IV, store at sta+208..215
  ##   Sets sta[235] = 1 (key installed), sta[240] = ptr to sta+80 (key material)
  let paramAddr = cast[uint](param)
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  # Store key metadata
  cast[ptr uint8](staEntry + 234)[] = staIdx  # HW key index
  let keyType = cast[ptr uint8](paramAddr + 52)[]
  cast[ptr uint8](staEntry + 232)[] = keyType
  let cipherSuite = cast[ptr uint8](paramAddr)[]
  cast[ptr uint8](staEntry + 233)[] = cipherSuite
  let keyFlags = cast[ptr uint8](paramAddr + 55)[]
  cast[ptr uint8](staEntry + 236)[] = keyFlags
  # Clear key material area (sta+80, 128 bytes)
  discard c_memset(cast[pointer](staEntry + 80), 0, 128.csize_t)
  # Dispatch on key type
  case keyType
  of 1:
    # CCMP: clear PN, copy key from param+24
    cast[ptr uint32](staEntry + 208)[] = 0  # PN low
    cast[ptr uint32](staEntry + 212)[] = 0  # PN high
    # Copy 32-byte temporal key from param+24 to sta+128+88. Blob inlines
    # the word-by-word copy (8 × 4-byte loads+stores); Nim previously
    # used two memcpy calls that aren't in blob's call graph.
    let keySrcU = paramAddr + 24
    let keyDstU = staEntry + 128 + 88
    for i in 0 ..< 8:
      cast[ptr uint32](keyDstU + (i * 4).uint)[] =
        cast[ptr uint32](keySrcU + (i * 4).uint)[]
  of 3:
    # TKIP: generate random IV using PRNG
    let rng = rcPrngNext()
    cast[ptr uint32](staEntry + 208)[] = (rng shr 16).uint32
    cast[ptr uint32](staEntry + 212)[] = 0
  else:
    # Unknown type: clear PN
    cast[ptr uint32](staEntry + 208)[] = 0
    cast[ptr uint32](staEntry + 212)[] = 0
  # Mark key as installed
  cast[ptr uint8](staEntry + 235)[] = 1
  # Store pointer to key material
  cast[ptr pointer](staEntry + 240)[] = cast[pointer](staEntry + 80)

proc sta_mgmt_del_key*(staIdx: uint8, keyIdx: uint8) {.exportc, cdecl.} =
  ## Delete encryption key for a station.
  ## From blob (4 instrs): a0 is treated as a sta_info_tag POINTER (not index).
  ## Clears key state: sta[235]=0, sta[240]=0, sta[72]=1.
  ## NOTE: blob takes pointer in a0; Nim signature has staIdx but callers may
  ## pass either. We handle both by checking if a0 looks like a pointer vs index.
  let staPtr = if staIdx.uint32 > MAX_STAS.uint32:
    # Likely a pointer was passed (C ABI caller)
    cast[uint](staIdx)
  else:
    # Index: compute pointer
    cast[uint](addr sta_info_tab[0]) + staIdx.uint * STA_ENTRY_SIZE.uint
  cast[ptr uint8](staPtr + 235)[] = 0       # clear key installed flag
  cast[ptr uint32](staPtr + 240)[] = 0      # clear key pointer
  cast[ptr uint8](staPtr + 72)[] = 1        # mark key as deleted

proc sta_mgmt_send_postponed_frame*(vifEntry: pointer, staEntry: pointer, maxCount: uint32): uint32 {.exportc, cdecl.} =
  ## Send postponed frames for a station (full loop with ~100 instrs).
  ## From blob: checks VIF PS mode flags (vif+91), sets ke_env PS bits and
  ## calls ke_evt_set(256) if PS active. Then loops: loads postponed desc from
  ## sta+356, checks txl_cntrl_tx_check, apm_tx_int_ps_check,
  ## apm_tx_int_ps_get_postpone. If no postpone, calls co_list_pop_front to
  ## dequeue. Clears desc+217, pushes via txl_cntrl_push_int, decrements
  ## txl_frame_env+16 counter. Loops until maxCount or list empty. Finally
  ## calls sta_mgmt_postponed_desc_release.
  let vif = cast[uint](vifEntry)
  let sta = cast[uint](staEntry)
  # Check VIF PS flags at offset 91
  let psFlags = cast[ptr uint8](vif + 91)[]
  if psFlags != 0:
    let vifType = cast[ptr uint8](vif + 86)[]
    let keEnvBase = cast[uint](addr ke_env[0])
    if vifType == VIF_TYPE_AP:
      # AP mode: set bit 1 in ke_env+28 and set ke_env+29 = 1
      let envByte = cast[ptr uint8](keEnvBase + 28)[]
      cast[ptr uint8](keEnvBase + 28)[] = envByte or 2
      cast[ptr uint8](keEnvBase + 29)[] = 1
    elif vifType != VIF_TYPE_STA:
      # Other mode: set bit 0 in ke_env+28 and set ke_env+31 = 1
      let envByte = cast[ptr uint8](keEnvBase + 28)[]
      cast[ptr uint8](keEnvBase + 28)[] = envByte or 1
      cast[ptr uint8](keEnvBase + 31)[] = 1
    # Signal TX event
    ke_evt_set(256)
  # Walk postponed descriptor list
  var count: uint32 = 0
  let listAddr = sta + 356
  let frameEnvBase = cast[uint](addr txl_frame_env[0])
  while true:
    # Load head of postponed list at sta+356
    let head = cast[ptr uint32](sta + 356)[]
    if head == 0:
      break
    # Check TX allowed
    let txOk = txl_cntrl_tx_check(vifEntry)
    if not txOk:
      break
    # Check PS state for this frame
    let psOk = apm_tx_int_ps_check(cast[pointer](head))
    if not psOk:
      break
    # Get postpone info
    var postponeFlag: uint32 = 0
    let desc = apm_tx_int_ps_get_postpone(vifEntry, staEntry, addr postponeFlag)
    if postponeFlag != 0:
      break
    var frameDesc: pointer
    if desc != nil:
      frameDesc = desc
    else:
      # Pop from the list
      frameDesc = cast[pointer](co_list_pop_front(cast[ptr CoList](listAddr)))
    # Process the frame
    let descU = cast[uint](frameDesc)
    let tid = cast[ptr uint8](descU + 46)[]
    cast[ptr uint8](descU + 217)[] = 0  # clear postponed flag
    count += 1
    # Push to TX control
    discard txl_cntrl_push_int(frameDesc, tid)
    # Decrement global postponed count in txl_frame_env+16
    let globalCnt = cast[ptr uint32](frameEnvBase + 16)[]
    if globalCnt > 0:
      cast[ptr uint32](frameEnvBase + 16)[] = globalCnt - 1
    # Check limit
    if maxCount != 0 and count >= maxCount:
      break
  # Release remaining postponed descriptors
  discard sta_mgmt_postponed_desc_release(staEntry, 0)
  return count

proc sta_mgmt_entry_init*(staEntry: pointer) {.exportc, cdecl.} =
  ## Reset a STA entry to default/free state.
  ## Blob algorithm:
  ##   sta_mgmt_postponed_desc_release(staEntry, 1)   ; release pending TX
  ##   memset(staEntry, 0, 368)                       ; zero entire entry
  ##   *(u8*)(staEntry+39) = 0xFF                     ; invalid staIdx sentinel
  ## Prior Nim bug: called mm_sec_machwkey_del() with a byte from offset 234
  ## (which in an active entry is a QoS field, not a key index) — that both
  ## skipped the TX-desc cleanup the blob does and risked deleting an unrelated
  ## HW key.
  discard sta_mgmt_postponed_desc_release(staEntry, 1'u32)
  discard c_memset(staEntry, 0, 368.csize_t)
  cast[ptr uint8](cast[uint](staEntry) + 39)[] = 0xFF'u8

proc sta_mgmt_postponed_desc_release*(staEntry: pointer, flag: uint32): uint32 {.exportc, cdecl.} =
  ## Release postponed descriptors for a station entry (58 instrs).
  ## From blob: walks the postponed frame list at sta+356. For each frame:
  ##   - If flag != 0: releases all frames unconditionally.
  ##   - If flag == 0: checks MAC timestamp against frame[84] (TX time).
  ##     If (macTime - txTime) > 0x1D4C0 (~120000 ticks = 120ms), releases frame.
  ##     Otherwise keeps it.
  ## Released frames are freed via keFreeFunc. Returns count of released frames.
  let sta = cast[uint](staEntry)
  var head = cast[ptr pointer](sta + 356)[]
  var released: uint32 = 0
  var prev: pointer = nil
  let macTime = regRead(MACHW_TIMLO_REG)
  let maxAge = 0x1D4C0'u32  # ~120ms in MAC ticks
  var cur = head
  while cur != nil:
    let curU = cast[uint](cur)
    let next = cast[ptr pointer](curU)[]
    var doRelease = false
    if flag != 0:
      doRelease = true
    else:
      # Check age: frame TX timestamp at offset 84
      let txTime = cast[ptr uint32](curU + 84)[]
      let age = macTime - txTime
      if age > maxAge:
        doRelease = true
    if doRelease:
      # Remove from postponed list (blob: co_list_remove)
      co_list_remove(cast[ptr CoList](sta + 356), cast[ptr CoListHdr](prev), cast[ptr CoListHdr](cur))
      # Release frame descriptor (blob: txl_frame_release)
      txl_frame_release(cur)
      released += 1
    else:
      prev = cur
    cur = next
  return released

proc sta_mgmt_aging_postponed_desc*(staEntry: pointer, maxCount: uint32): uint32 {.exportc, cdecl.} =
  ## Age postponed frame descriptors (25 instrs).
  ## From blob: iterates all entries physically present in sta_info_tab
  ## (7 entries, 368 bytes each), calling sta_mgmt_postponed_desc_release(staEntry, 0).
  ## Accumulates total released count. Returns total.
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEnd = staBase + (STA_INFO_TAB_ENTRIES * STA_ENTRY_SIZE).uint
  var total: uint32 = 0
  var cur = staBase
  while cur < staEnd:
    let released = sta_mgmt_postponed_desc_release(cast[pointer](cur), 0)
    total += released
    cur += STA_ENTRY_SIZE.uint
  return total

# ###########################################################################
#                  TPC: TX Power Control
# ###########################################################################

proc tpc_update_tx_power*(vifIdx: uint8) {.exportc, cdecl.} =
  ## Update TX power (262 bytes in blob, 87 instrs).
  ## From blob: gets power table via bl_tpc_power_table_get, then runs
  ## bl_pwr_find on three 8-byte groups (11b, 11g, 11n) to find the
  ## rate with the highest power. Calls trpc_get_default_power_idx twice
  ## (once for overall best, once for 11b best) to update PHY state, then
  ## programs MACHW_TX_POWER_REG with fixed power indices 0x40 and 0x48.
  ##
  ## Stack layout from blob (sp+8..sp+13, 6 bytes):
  ##   sp[8]  = 11b best power value
  ##   sp[9]  = 11b best index (bl_pwr_find result)
  ##   sp[10] = 11b rate type (always 0)
  ##   sp[11] = overall best power (across groups 1,2)
  ##   sp[12] = overall best index
  ##   sp[13] = overall best type (1=11g, 2=11n)

  # Clear the 6-byte result buffer
  var resultBuf {.noinit.}: array[6, uint8]
  discard c_memset(addr resultBuf[0], 0, 6.csize_t)

  # Get the full power table (24 rate bytes + 14 channel offset bytes)
  var powerTable {.noinit.}: array[38, int8]
  bl_tpc_power_table_get(addr powerTable)

  # Group 0 (11b, rate entries 0..7):
  var workBuf {.noinit.}: array[8, int8]
  discard c_memcpy(addr workBuf[0], addr powerTable[0], 8.csize_t)
  let idx0 = bl_pwr_find(addr workBuf[0], 8)
  let pwr0 = cast[uint8](workBuf[idx0])
  resultBuf[0] = pwr0          # 11b best power
  resultBuf[1] = cast[uint8](idx0) # 11b best index
  resultBuf[2] = 0             # 11b type = 0

  # Group 1 (11g, rate entries 8..15):
  discard c_memcpy(addr workBuf[0], addr powerTable[8], 8.csize_t)
  let idx1 = bl_pwr_find(addr workBuf[0], 8)
  let pwr1 = cast[uint8](workBuf[idx1])
  if cast[int8](pwr1) > cast[int8](resultBuf[3]):  # blob: bge signed
    resultBuf[3] = pwr1          # overall best power
    resultBuf[5] = 1             # type = 11g
    resultBuf[4] = cast[uint8](idx1) # overall best index

  # Group 2 (11n, rate entries 16..23):
  discard c_memcpy(addr workBuf[0], addr powerTable[16], 8.csize_t)
  let idx2 = bl_pwr_find(addr workBuf[0], 8)
  let pwr2 = cast[uint8](workBuf[idx2])
  if cast[int8](pwr2) > cast[int8](resultBuf[3]):  # blob: bge signed
    resultBuf[3] = pwr2          # overall best power
    resultBuf[5] = 2             # type = 11n
    resultBuf[4] = cast[uint8](idx2) # overall best index

  let bestIdx = resultBuf[4]     # overall best index
  let bestType = resultBuf[5]    # overall best type

  # Call trpc_get_default_power_idx for overall best rate (side effects in PHY)
  discard trpc_get_default_power_idx(bestType.uint32, bestIdx)

  # Program MACHW_TX_POWER_REG bits[7:0] = 0x40
  var regVal = regRead(MACHW_TX_POWER_REG)
  regVal = (regVal and 0xFFFFFF00'u32) or 0x40'u32
  regWrite(MACHW_TX_POWER_REG, regVal)

  # Call trpc_get_default_power_idx for 11b best rate (side effects in PHY)
  let bestIdx11b = resultBuf[1]
  let type11b = resultBuf[2]     # always 0
  discard trpc_get_default_power_idx(type11b.uint32, bestIdx11b)

  # Program MACHW_TX_POWER_REG bits[15:8] = 0x48
  regVal = regRead(MACHW_TX_POWER_REG)
  regVal = (regVal and 0xFFFF00FF'u32) or 0x4800'u32
  regWrite(MACHW_TX_POWER_REG, regVal)

proc tpc_get_vif_tx_power*(vifIdx: uint8): int8 {.exportc, cdecl.} =
  ## Get TX power for a VIF.
  ## From blob (4 instrs): reads MACHW_TX_POWER_REG, returns low byte.
  ## The low byte of this register holds the current TX power level.
  let val = regRead(MACHW_TX_POWER_REG)
  return cast[int8](val and 0xFF)

proc tpc_update_vif_tx_power*(vifEntry: pointer, txPowerElem: pointer, rateParam: pointer) {.exportc, cdecl.} =
  ## Update VIF TX power (168 bytes in blob, 58 instrs).
  ##
  ## Blob ABI: a0=vifEntry, a1=txPowerElem (ptr to i8 power), a2=rateParam.
  ## Flow:
  ##   1. lb a4, 0(a1). If == 127, return (sentinel: no update).
  ##   2. Save old power from vif[89]. Call phy_get_rf_gain_idx(a1, a2).
  ##   3. Read new power from a1[0], clamp to vif[90] (max_power).
  ##   4. Store new to vif[89]. If changed: walk STA list at vif[340],
  ##      set bit 4 in STA[334] (RC flags).
  ##   5. If chanCtxt at vif[64] exists: call chan_update_tx_power,
  ##      chan_is_on_channel, tail-call tpc_update_tx_power.
  let powerVal = cast[ptr int8](txPowerElem)[]
  if powerVal == 127:
    return  # sentinel: no power configured

  let vifU = cast[uint](vifEntry)
  let oldPower = cast[ptr int8](vifU + 89)[]

  # Call phy_get_rf_gain_idx to convert power to RF gain index
  phy_get_rf_gain_idx(txPowerElem, rateParam)

  # Reload power (may have been modified by phy_get_rf_gain_idx)
  var newPower = cast[ptr int8](txPowerElem)[]
  let maxPower = cast[ptr int8](vifU + 90)[]

  # Store new power to VIF entry
  cast[ptr int8](vifU + 89)[] = newPower

  # Clamp to max_power if exceeded
  if newPower > maxPower:
    cast[ptr int8](txPowerElem)[] = maxPower
    # Re-run phy_get_rf_gain_idx with clamped value
    phy_get_rf_gain_idx(txPowerElem, rateParam)

  # Reload final power
  newPower = cast[ptr int8](txPowerElem)[]
  if newPower == oldPower:
    return  # no change

  # Walk STA linked list at vifEntry+340 to update RC flags
  var staNode = cast[ptr pointer](vifU + 340)[]
  while staNode != nil:
    let staNodeU = cast[uint](staNode)
    # Set bit 4 in STA RC flags to trigger power-related rate re-computation
    let rcFlagsPtr = cast[ptr uint8](staNodeU + 334)
    rcFlagsPtr[] = rcFlagsPtr[] or 0x10
    staNode = cast[ptr pointer](staNodeU)[]

  # Check if VIF has a channel context
  let chanCtxt = cast[ptr pointer](vifU + 64)[]
  if chanCtxt == nil:
    return

  # Blob: chan_update_tx_power(chanCtxt) — a0 = channel context pointer
  let chanUpdateFn = cast[proc(ctxt: pointer) {.cdecl.}](chan_update_tx_power)
  chanUpdateFn(chanCtxt)

  # Blob: chan_is_on_channel(vifEntry) — a0 = VIF entry pointer
  let chanOnFn = cast[proc(vif: pointer): bool {.cdecl.}](chan_is_on_channel)
  if not chanOnFn(vifEntry):
    return

  # On-channel: tail-call tpc_update_tx_power with chanCtxt[12] power
  let chanCtxt2 = cast[ptr pointer](vifU + 64)[]  # reload
  let chanPower = cast[ptr int8](cast[uint](chanCtxt2) + 12)[]
  tpc_update_tx_power(chanPower.uint8)

proc tpc_get_vif_tx_power_vs_rate*(vifIdx: uint8, rate: uint32): int8 {.exportc, cdecl.} =
  ## Get TX power for a specific rate on a VIF (40 bytes in blob, 14 instrs).
  ## From blob:
  ##   1. zext.b a5, a0; andi a1, a0, 0x7F  -> extract rate byte and rate index
  ##   2. Custom .insn divides rate by 128 to get rateGroup
  ##   3. If rateGroup != 0 (HT/VHT rate): a0=2, tail-call trpc_get_default_power_idx
  ##   4. If (a5 & 0x7C) != 0 (11g rate): a1 -= 4, zext.b, a0=1
  ##   5. Tail-call trpc_get_default_power_idx(rateType, adjustedRateIdx)
  ##
  ## This classifies the rate into legacy-11b (type 0), legacy-11g (type 1),
  ## or HT/VHT (type 2) and dispatches to trpc_get_default_power_idx.
  let rateByte = (rate and 0xFF).uint8
  let rateIdx = (rate and 0x7F).uint8  # 7-bit rate index
  let rateGroup = rateByte div 128     # custom insn divides by group size

  # Blob tail-calls trpc_get_default_power_idx from a single site.
  var rateType: uint8
  var adjIdx: uint8 = rateIdx
  if rateGroup != 0:
    rateType = 2                       # HT/VHT
  elif (rateByte and 0x7C) != 0:
    rateType = 1                       # 11g
    adjIdx = ((rateIdx - 4) and 0xFF).uint8
  else:
    rateType = 0                       # 11b
  return trpc_get_default_power_idx(rateType, adjIdx)

proc tpc_update_frame_tx_power*(env: pointer, frameDesc: pointer) {.exportc, cdecl.} =
  ## Update TX power for a specific frame.
  ## From blob (13 instrs):
  ##   1. lw a5, 112(frameDesc)   -> a5 = frameDesc->txdesc (offset 112)
  ##   2. lw s0, 40(a5)           -> s0 = txdesc->rateCtrl (offset 40)
  ##   3. lw a0, 20(s0)           -> a0 = rateCtrl->rate (offset 20)
  ##   4. call tpc_get_vif_tx_power_vs_rate(rate)
  ##   5. sw a0, 36(s0)           -> rateCtrl->txPower = result (offset 36)
  if frameDesc == nil: return
  let descU = cast[uint](frameDesc)
  let txdesc = cast[ptr pointer](descU + 112)[]
  if txdesc == nil: return
  let txdescU = cast[uint](txdesc)
  let rateCtrl = cast[ptr pointer](txdescU + 40)[]
  if rateCtrl == nil: return
  let rateCtrlU = cast[uint](rateCtrl)
  let rate = cast[ptr uint32](rateCtrlU + 20)[]
  let txPower = tpc_get_vif_tx_power_vs_rate(0, rate)
  cast[ptr int32](rateCtrlU + 36)[] = txPower.int32

  ## bl_tpc_power_table_get forward declaration already at line 1209

proc bl_tpc_update_power_table*(powerTable: ptr array[38, int8]) {.exportc, cdecl.} =
  ## Update the full TX power table.
  ## From blob (22 instrs):
  ##   1. Calls trpc_update_power to update the first 24 bytes (rate part)
  ##   2. Scales remaining 14 bytes (channel offsets) by 4 on stack
  ##   3. Tail-calls phy_powroffset_set(stackOffsets)
  proc phy_powroffset_set(data: pointer) {.importc, cdecl.}
  trpc_update_power(powerTable)
  # Bytes 24..37 of the input are channel offset values; blob scales by 4 and
  # stores on stack, then calls phy_powroffset_set(stackPtr).
  var scaled {.noinit.}: array[14, int32]
  for i in 0 ..< 14:
    scaled[i] = cast[int32](powerTable[24 + i].int32 shl 2)
  phy_powroffset_set(addr scaled[0])

proc bl_tpc_update_power_table_rate*(powerTable: ptr array[24, int8]) {.exportc, cdecl.} =
  ## Update per-rate TX power table (blob: tail-call to trpc_update_power).
  trpc_update_power(powerTable)

proc bl_tpc_update_power_table_channel_offset*(powerTable: ptr array[14, int8]) {.exportc, cdecl.} =
  ## Update per-channel TX power offset table (39 instrs in blob).
  ## From blob: loops through 14 channels. For each channel: loads the offset
  ## byte from input, loads a function pointer (bl_tpc_update_power_rate variant),
  ## calls it with (channel_table_base, channel_idx, offset_value_shifted).
  ## After processing all 14 channels, calls bl_tpc_power_table_get with a
  ## stack buffer to refresh the combined power table.
  # Copy channel offsets to our table
  for i in 0 ..< 14:
    tpcChannelOffsetTable[i] = powerTable[i]
  # Apply per-channel offsets: update the full power table entries 24..37
  for i in 0 ..< 14:
    tpcPowerTable[24 + i] = powerTable[i]
  # Apply PHY power offset (blob: phy_powroffset_set, NOT bl_tpc_power_table_get)
  proc phy_powroffset_set(data: pointer) {.importc, cdecl.}
  phy_powroffset_set(addr tpcChannelOffsetTable[0])

proc bl_tpc_update_power_rate_11b*(powerTable: ptr array[4, int8]) {.exportc, cdecl.} =
  ## Update 11b per-rate TX power (blob: tail-call to trpc_update_power_11b).
  trpc_update_power_11b(powerTable)

proc bl_tpc_update_power_rate_11g*(powerTable: ptr array[8, int8]) {.exportc, cdecl.} =
  ## Update 11g per-rate TX power (blob: tail-call to trpc_update_power_11g).
  trpc_update_power_11g(powerTable)

proc bl_tpc_update_power_rate_11n*(powerTable: ptr array[8, int8]) {.exportc, cdecl.} =
  ## Update 11n per-rate TX power (blob: tail-call to trpc_update_power_11n).
  trpc_update_power_11n(powerTable)

proc bl_tpc_power_table_get*(powerTable: ptr array[38, int8]) {.exportc, cdecl.} =
  ## Get the current TX power table (15 instrs in blob).
  ## From blob: calls trpc_power_get to fill the first 24 bytes (rate data),
  ## then loops from index 24 to 37 copying channel offset bytes.
  # Get rate data from TRPC (fills first 24 bytes)
  trpc_power_get(powerTable)
  # Copy channel offset table (bytes 24..37)
  for i in 0 ..< 14:
    powerTable[24 + i] = tpcChannelOffsetTable[i]

# ###########################################################################
#                  BAM: Block ACK Management
# ###########################################################################

proc bam_init*() {.exportc, cdecl.} =
  ## Initialize block ACK management.
  ## From disassembly: stores 0xFF to bamStaIdx (no active BA session),
  ## then tail-calls ke_state_set(TASK_BAM, 0).
  bamStaIdx = 0xFF'u8
  ke_state_set(TASK_BAM, 0)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void bam_send_air_action_frame(unsigned char,unsigned char,unsigned char,unsigned char,unsigned short,unsigned char,void*);".}
proc bam_send_air_action_frame*(staIdx: uint8, tid: uint8, isAddba: uint8,
    dialogToken: uint8, statusCode: uint16, extraFlags: uint8,
    txCallback: pointer) {.exportc, cdecl.} =
  ## Send ADDBA/DELBA action frame over the air (177 instructions).
  ##
  ## From disassembly register mapping:
  ##   a0 = staIdx (s4), a1 = tid (s1), a2 = isAddba (s9),
  ##   a3 = dialogToken (s7), a4 = statusCode (saved to sp+8),
  ##   a5 = extraFlags (s8), a6 = txCallback (s2)
  ##
  ## Allocates a 512-byte frame, fills in action frame header
  ## (ADDBA req/rsp or DELBA), builds frame body via me_build_add_ba_req/del_ba,
  ## then pushes to TX with AC=3.

  let staTabBase = cast[uint](addr sta_info_tab[0])
  let staOff = staIdx.uint * STA_ENTRY_SIZE.uint
  let staEntry = staTabBase + staOff

  # Get VIF index from sta_info_tab[staIdx]+39
  let vifIdx = cast[ptr uint8](staEntry + 39)[]

  let vifTabBase = cast[uint](addr vif_info_tab[0])
  let vifOff = vifIdx.uint * VIF_ENTRY_SIZE.uint
  let vifEntry = vifTabBase + vifOff  # s11 = vifOff in blob

  # Allocate TX frame from frame pool (blob: txl_frame_get at 0x46)
  let frame = txl_frame_get(512)
  if frame == nil:
    return

  let frameAddr = cast[uint](frame)

  # Update TX power (blob: tpc_update_frame_tx_power at 0x6E)
  tpc_update_frame_tx_power(cast[pointer](vifEntry), frame)

  # The MAC header lives in the link descriptor, not inline in the frame
  # descriptor. Writing at frame+348 corrupts the frame pool metadata.
  let linkDesc = cast[uint](cast[ptr pointer](frameAddr + 108)[])
  let macHdr = linkDesc + 348

  # Set frame control: Action frame = 0xD0
  cast[ptr uint8](macHdr + 0)[] = 0xD0'u8
  cast[ptr uint8](macHdr + 1)[] = 0
  cast[ptr uint8](macHdr + 2)[] = 0  # Duration
  cast[ptr uint8](macHdr + 3)[] = 0

  # Copy addresses from sta and vif entries
  # Addr2 (SA) = VIF MAC at vifEntry+80
  let vifMac = vifEntry + 80
  # Addr3 (BSSID) = same as DA for infrastructure mode

  # MAC address fields start at offsets 4, 10, and 16. Offset 10 is not
  # 32-bit aligned on BL808, so use byte-safe copies instead of word stores.
  let bssid = cast[uint](addr sta_info_tab[0]) + staOff + 4
  template copy6(dst, src: uint) =
    discard c_memcpy(cast[pointer](dst), cast[pointer](src), 6.csize_t)
  copy6(macHdr + 4, bssid)                # Addr1 (DA)
  copy6(macHdr + 10, vifMac)              # Addr2 (SA)
  let staType = cast[ptr uint8](staEntry + 86)[]
  if staType == 2:
    copy6(macHdr + 16, vifMac)            # Addr3 = VIF MAC (AP)
  else:
    copy6(macHdr + 16, bssid)             # Addr3 = BSSID

  # Copy sequence number from the global TX control sequence counter.
  let seqPtr = cast[ptr uint16](cast[uint](addr txl_cntrl_env[0]) + 84)
  var seqNum = seqPtr[]
  seqNum = (seqNum + 1) and 0x0FFF'u16
  seqPtr[] = seqNum
  let seqField = seqNum shl 4
  cast[ptr uint8](macHdr + 22)[] = cast[uint8](seqField and 0xFF)
  cast[ptr uint8](macHdr + 23)[] = cast[uint8]((seqField shr 8) and 0xFF)

  # Store staIdx and vifIdx into frame descriptor
  cast[ptr uint8](frameAddr + 49)[] = staIdx
  cast[ptr uint8](frameAddr + 47)[] = vifIdx

  # Clear counters
  cast[ptr uint8](frameAddr + 98)[] = 0   # extra IE length
  cast[ptr uint8](frameAddr + 100)[] = 0  # padding

  # Read frame control back to compute total header size
  let fc0 = cast[ptr uint8](macHdr + 0)[]
  let fc1 = cast[ptr uint8](macHdr + 1)[]
  var hdrLen: uint32 = 24  # standard MAC header

  # Management frame protection. For BA action frames the category is 3.
  # The blob only inserts a security header when MFP returns CCMP (1); in that
  # case the BA body starts after the protected-management header extension.
  let fcVal = fc0.uint32 or (fc1.uint32 shl 8)
  let mfpResult = mfp_protect_mgmt_frame(frame, fcVal, 3'u32)
  if mfpResult == 1:
    txu_cntrl_protect_mgmt_frame(frame, cast[pointer](macHdr), 24)
    let secHdrLen = cast[ptr uint8](frameAddr + 98)[]
    hdrLen += secHdrLen.uint32

  # Call appropriate build function based on isAddba
  var bodyLen: uint32 = 0
  if isAddba == 1:
    # Build ADDBA response (blob: me_build_add_ba_rsp at 0x172)
    let bodyPtr = cast[pointer](macHdr + hdrLen)
    bodyLen = me_build_add_ba_rsp(bodyPtr, cast[pointer](tid.uint),
                                  statusCode, dialogToken, extraFlags.uint16)
  elif isAddba == 0:
    # Build ADDBA request
    let bodyPtr = cast[pointer](macHdr + hdrLen)
    bodyLen = me_build_add_ba_req(bodyPtr, nil)
  else:
    assert_err("bam.c", "bam.c", 589)

  # Compute total payload length
  hdrLen += bodyLen
  let extraPad = cast[ptr uint8](frameAddr + 100)[]
  hdrLen += extraPad.uint32

  # Update TX descriptor lengths
  let txDescPtr = cast[uint](cast[ptr pointer](frameAddr + 112)[])
  let oldPayLen = cast[ptr uint32](txDescPtr + 20)[]
  cast[ptr uint32](txDescPtr + 24)[] = oldPayLen + hdrLen - 1
  let totalLen = hdrLen + 4  # +4 for FCS
  cast[ptr uint32](txDescPtr + 28)[] = totalLen

  # Store TX callback if provided
  if txCallback != nil:
    cast[ptr pointer](frameAddr + 208)[] = txCallback
    cast[ptr pointer](frameAddr + 212)[] = cast[pointer](cast[uint](tid))

  # Push frame to TX with AC=3 (voice), tail call
  txl_frame_push(frame, 3)

# ###########################################################################
#                  TD: Time Domain (Traffic Detection)
# ###########################################################################

proc td_init*() {.exportc, cdecl.} =
  ## Initialize time domain module — blob td.o:
  ##   td_reset(0)        ; resets VIF 0 (zero-clears its slot)
  ##   tail-call td_reset(1)  ; resets VIF 1 (and clears the full env)
  ## Previous Nim emitted a separate memset(td_env, 0, 88) that is not in
  ## blob's call graph — td_reset itself writes the fields it cares about.
  td_reset(0)
  td_reset(1)

proc td_start*(vifIdx: uint8) {.exportc, cdecl.} =
  ## Start traffic detection for a VIF (106 bytes in blob, ~35 instrs).
  ## From blob: computes per-VIF block = td_env + vifIdx * 44.
  ## If active flag already set, returns. Otherwise reads MAC time,
  ## logs via platform ops, stores vifIdx, sets active flag, clears counters,
  ## and tail-calls mm_timer_set.
  let tdBase = cast[uint](addr td_env[0])
  let perVif = tdBase + vifIdx.uint * 44
  let active = cast[ptr uint8](perVif + 42)[]
  if active != 0:
    return  # already started
  let macTime = regRead(MACHW_TIMLO_REG)
  # Log traffic detection start via platform ops
  let blOps = cast[uint](addr g_bl_ops_funcs)
  let logFnPtr = cast[ptr pointer](blOps + 204)[]
  if logFnPtr != nil:
    let logFn = cast[PlatformLogFunc](logFnPtr)
    logFn(1, 0, nil, 190, vifIdx.uint32, macTime)
  # Store VIF index and set active
  cast[ptr uint8](perVif + 40)[] = vifIdx
  cast[ptr uint8](perVif + 41)[] = 0  # clear direction flags
  cast[ptr uint8](perVif + 42)[] = 1  # active = true
  cast[ptr uint32](perVif + 20)[] = 0  # clear timer time
  # Clear traffic counters
  cast[ptr uint32](perVif + 24)[] = 0
  cast[ptr uint32](perVif + 28)[] = 0
  cast[ptr uint32](perVif + 32)[] = 0
  cast[ptr uint32](perVif + 36)[] = 0
  # Start timer
  let period = cast[ptr uint32](perVif + 16)[]
  mm_timer_set(cast[pointer](perVif), macTime + period)

proc td_timer_end*(tdEntry: pointer) {.exportc, cdecl.}  # forward decl
proc td_timer_evt*(env: pointer) {.exportc, cdecl.} =
  ## Timer event callback for traffic detection (set as callback in td_reset).
  ## From blob: tail-calls td_timer_end with the environment pointer.
  td_timer_end(env)

proc td_reset*(vifIdx: uint8) {.exportc, cdecl.} =
  ## Reset traffic detection for a VIF.
  ## From blob (52 instrs): computes per-VIF block = td_env + vifIdx * 44.
  ## If active (td[42] != 0), calls mm_timer_clear on the timer. Then memsets
  ## the 44-byte block to zero. Finally sets up: td[4]=td_timer_evt callback,
  ## td[8]=self pointer (env), td[40]=vifIdx.
  let tdBase = cast[uint](addr td_env[0])
  let perVif = tdBase + vifIdx.uint * 44
  # If timer is active, clear it
  let active = cast[ptr uint8](perVif + 42)[]
  if active != 0:
    mm_timer_clear(cast[pointer](perVif))
  # Zero the entire per-VIF block
  discard c_memset(cast[pointer](perVif), 0, 44.csize_t)
  # Set up timer fields. Blob stores td_timer_end directly as the callback
  # (no wrapper) — Nim previously routed through a td_timer_evt stub that
  # tail-called td_timer_end, producing a pointless indirection.
  cast[ptr pointer](perVif + 4)[] = cast[pointer](td_timer_end)  # callback
  cast[ptr uint32](perVif + 8)[] = cast[uint32](perVif)          # env = self
  cast[ptr uint8](perVif + 40)[] = vifIdx                         # vif index

proc td_pck_ind*(vifIdx: uint8, direction: uint32) {.exportc, cdecl.} =
  ## Packet indication for traffic detection.
  ## From blob (14 instrs): computes per-VIF block = td_env + vifIdx * 44.
  ## If direction (a2 mapped to second arg after MUL) != 0, increments td[28] (tx count).
  ## Otherwise increments td[24] (rx count).
  let tdBase = cast[uint](addr td_env[0])
  let perVif = tdBase + vifIdx.uint * 44
  if direction != 0:
    let p = cast[ptr uint32](perVif + 28)
    p[] = p[] + 1
  else:
    let p = cast[ptr uint32](perVif + 24)
    p[] = p[] + 1

proc td_pck_ps_ind*(vifIdx: uint8, direction: uint32) {.exportc, cdecl.} =
  ## PS packet indication for traffic detection.
  ## From blob (14 instrs): computes per-VIF block = td_env + vifIdx * 44.
  ## If direction != 0, increments td[36] (PS tx count).
  ## Otherwise increments td[32] (PS rx count).
  let tdBase = cast[uint](addr td_env[0])
  let perVif = tdBase + vifIdx.uint * 44
  if direction != 0:
    let p = cast[ptr uint32](perVif + 36)
    p[] = p[] + 1
  else:
    let p = cast[ptr uint32](perVif + 32)
    p[] = p[] + 1

proc td_recovery_ind*() {.exportc, cdecl.} =
  ## Traffic recovery indication.
  discard

proc td_pack_tim_ind*(vifIdx: uint8) {.exportc, cdecl, noinline.} =
  ## Pack TIM indication for traffic detection.
  ## From blob (26 instrs): computes per-VIF block = td_env + vifIdx * 44.
  ## If td[42] (active) is set, reads MAC time, calls mm_timer_set with
  ## target = macTime + td[16] (the last recorded time). Then checks td[20]
  ## (tim_time): if non-zero stores to td[16], otherwise loads default from
  ## GOT-referenced global and stores that.
  ## noinline: blob calls this from ps_check_tbtt.
  {.emit: "__asm__ volatile(\"\" ::: \"memory\");".}
  let tdBase = cast[uint](addr td_env[0])
  let perVif = tdBase + vifIdx.uint * 44
  let active = cast[ptr uint8](perVif + 42)[]
  if active == 0:
    return
  # Read MAC time and set timer
  let macTime = regRead(MACHW_TIMLO_REG)
  mm_timer_set(cast[pointer](perVif), macTime + cast[ptr uint32](perVif + 16)[])
  # Update the period: if tim_time (offset 20) is set, use it
  let timTime = cast[ptr uint32](perVif + 20)[]
  if timTime != 0:
    cast[ptr uint32](perVif + 16)[] = timTime
  else:
    # Use default timer period (from blob: loaded via GOT relocation)
    # Default is the existing value at offset 16, leave unchanged
    discard

proc td_set_tim_time*(vifIdx: uint8, timTime: uint32) {.exportc, cdecl.} =
  ## Set TIM update time for traffic detection.
  ## From blob (7 instrs): computes per-VIF block = td_env + vifIdx * 44.
  ## Stores timTime (a1) at td[20].
  let tdBase = cast[uint](addr td_env[0])
  let perVif = tdBase + vifIdx.uint * 44
  cast[ptr uint32](perVif + 20)[] = timTime

proc td_cfm_set_timer*(vifIdx: uint8, flag: uint32) {.exportc, cdecl.} =
  ## Set/clear confirmation timer for traffic detection (72 bytes in blob).
  ## From blob: computes per-VIF entry = td_env + vifIdx*44.
  ## If flag (a1) != 0: reads MAC time, adds period from td[16], calls mm_timer_set.
  ## Both paths: always clears td[16] (period consumed after use).
  let tdBase = cast[uint](addr td_env[0])
  let perVif = tdBase + vifIdx.uint * 44
  if flag != 0:
    # Set timer: read MAC time, add period from td[16]
    let macTime = regRead(MACHW_TIMLO_REG)
    let period = cast[ptr uint32](perVif + 16)[]
    mm_timer_set(cast[pointer](perVif), macTime + period)
  # Always clear the period field (consumed)
  cast[ptr uint32](perVif + 16)[] = 0

# ###########################################################################
#                  PS: Power Save
# ###########################################################################

proc ps_init*() {.exportc, cdecl.} =
  ## Initialize power save module.
  ## From disassembly: memset(ps_env, 0, 56), then stores two timer callback
  ## function pointers:
  ##   ps_env[4] (byte offset 16) = ptr to ps_uapsd_timer_handle
  ##   ps_env[10] (byte offset 40) = ptr to ps_tx_null_timer_handle
  discard c_memset(addr ps_env[0], 0, 56.csize_t)
  # Store timer callback function pointers (blob: ps_env[16] and ps_env[40])
  ps_env[4] = cast[uint32](cast[pointer](ps_uapsd_timer_handle))
  ps_env[10] = cast[uint32](cast[pointer](ps_tx_null_timer_handle))

proc ps_set_mode*(mode: uint8) {.exportc, cdecl.} =
  ## Set power save mode (115 instructions in blob).
  ##
  ## Register map: s0=ps_env s1=VIF list (from chan_env) s2=mode s3=chan_env s4=1
  ## Stores mode at ps_env+1. Checks ps_env+52 (flags):
  ##   if (flags & 1) && (flags & 6): deferred -- set bit 4, store at +53, return.
  ## mode==0: clear ps flag, clear MACHW CCA bit 2, walk VIFs
  ## mode==2: log line 702, set bit 0 in ps_env+52
  ## mode!=0: set MACHW CCA bit 2, walk VIFs
  ## VIF walk: for each VIF with type!=0 && connless!=0: call ps_check and update counter.
  let psBase = cast[uint](addr ps_env[0])
  cast[ptr uint8](psBase + 1)[] = mode

  # Check deferred flags at ps_env+52
  let flags52 = cast[ptr uint8](psBase + 52)[]
  if (flags52 and 1) != 0:
    if (flags52 and 6) != 0:
      cast[ptr uint8](psBase + 52)[] = flags52 or 0x10
      cast[ptr uint8](psBase + 53)[] = mode
      return

  if mode == 0:
    # Disable PS: clear enable byte, clear MACHW bit
    # (blob: ps_disable_cfm_handle at 0x9A)
    cast[ptr uint8](psBase + 0)[] = 0
    let r = volatileLoad(cast[ptr uint32](0x24B0004C'u32))
    volatileStore(cast[ptr uint32](0x24B0004C'u32), r and not 4'u32)
    # PS disable confirm (blob: ps_disable_cfm_handle at 0x9A)
    let vifIdxForDisable = cast[ptr uint8](psBase + 4)[]
    let vifEntryDisable = cast[pointer](cast[uint](addr vif_info_tab[0]) +
      vifIdxForDisable.uint * VIF_ENTRY_SIZE.uint)
    discard ps_disable_cfm_handle(vifEntryDisable)
  else:
    if mode == 2:
      # Deep sleep: log at line 702, set enable flag bit 0
      let logFn = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
      if logFn != nil:
        type LP = proc(a: uint32, b: uint32, c: cstring, d: uint32) {.cdecl, varargs.}
        cast[LP](logFn)(1, 0, "ps.c", 702)
      cast[ptr uint8](psBase + 52)[] = cast[ptr uint8](psBase + 52)[] or 1
    # Enable PS: set MACHW bit
    let r = volatileLoad(cast[ptr uint32](0x24B0004C'u32))
    volatileStore(cast[ptr uint32](0x24B0004C'u32), r or 4'u32)

  # .L39: Load VIF linked-list head from vif_mgmt_env+8 (blob uses vif_mgmt_env, not chan_env)
  var vifNode = cast[ptr pointer](cast[uint](addr vif_mgmt_env[0]) + 8)[]
  # Clear ps_env flag bytes at offsets 8 and 29
  cast[ptr uint8](psBase + 8)[] = 0
  cast[ptr uint8](psBase + 29)[] = 0
  var cfmCallback: pointer  # s3: ps_disable_cfm or ps_enable_cfm fn ptr
  if mode == 0:
    cfmCallback = cast[pointer](ps_disable_cfm)
  else:
    cfmCallback = cast[pointer](ps_enable_cfm_handle)

  # .L42: Walk VIF linked list (blob: VIF walk with chan_is_on_channel + txl_frame_send_null_frame)
  var nullFrameQueued: bool = false
  while vifNode != nil:
    let vifU = cast[uint](vifNode)
    # .L47: Check VIF type at offset 86 — skip if type == 0
    let vifType = cast[ptr uint8](vifU + 86)[]
    if vifType != 0:
      # Check connless at offset 88
      let connless = cast[ptr uint8](vifU + 88)[]
      if connless != 0:
        # Blob: call chan_is_on_channel(vifNode)
        let chanOnFn = cast[proc(vif: pointer): bool {.cdecl.}](chan_is_on_channel)
        if chanOnFn(vifNode):
          # On channel: clear offset 95, increment ps_env+8 counter
          cast[ptr uint8](vifU + 95)[] = 0
          let cnt = cast[ptr uint8](psBase + 8)[]
          cast[ptr uint8](psBase + 8)[] = cnt + 1
          # Check VIF flag at 104 for wakeup notification
          let f104 = cast[ptr uint8](vifU + 104)[]
          if f104 != 0:
            cast[ptr uint8](psBase + 29)[] = 1
          # Blob: txl_frame_send_null_frame(vif[96], s3=cfmCallback, vifNode)
          let staIdxByte = cast[ptr uint8](vifU + 96)[]
          discard txl_frame_send_null_frame(staIdxByte, cfmCallback, cast[uint32](vifU))
    # Next VIF: offset 0 is next pointer
    vifNode = cast[ptr pointer](vifU)[]

  # .L42 exit: check ps_env+8 counter
  let psCount = cast[ptr uint8](psBase + 8)[]
  if psCount == 0:
    return  # No VIFs accepted PS change

  # PS enable/disable completion (blob: ps_enable_cfm_handle at 0x14E or via s3 callback)
  if mode != 0:
    let vifIdxForPs = cast[ptr uint8](psBase + 4)[]
    let vifEntryForPs = cast[pointer](cast[uint](addr vif_info_tab[0]) +
      vifIdxForPs.uint * VIF_ENTRY_SIZE.uint)
    ps_enable_cfm_handle(vifEntryForPs)

proc ps_check_beacon*(rxHdr: pointer, unused: uint32, vifEntry: pointer) {.exportc, cdecl.} =
  ## Check beacon for PS-related information (TIM, DTIM).
  ## From blob (106 instrs): loads AID from sta_info_tab[vif[96]] at offset 36.
  ## Clears bit 0 of vif[4]. Checks ps_env enabled and not scanning.
  ## If no rx header, returns. Checks WMM flag at vif[94]. Parses TIM bitmap
  ## from the beacon to determine if traffic is buffered for our AID.
  ## If TIM bit set: calls ps wakeup function and sets bit 6 in vif[4].
  ## If UAPSD bitmap all-AC (0x0F), clears bit 3 of vif[4] flags.
  let vif = cast[uint](vifEntry)
  let psBase = cast[uint](addr ps_env[0])
  let staTabBase = cast[uint](addr sta_info_tab[0])

  # Load AID from associated STA
  let staIdx = cast[ptr uint8](vif + 96)[]
  let staEntry = staTabBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let aid = cast[ptr uint16](staEntry + 36)[]

  # Clear bit 0 of vif flags
  var flags = cast[ptr uint32](vif + 4)[]
  flags = flags and not 1'u32
  cast[ptr uint32](vif + 4)[] = flags

  # Check PS enabled
  let psEnabled = cast[ptr uint8](psBase)[]
  if psEnabled == 0: return

  # Check not scanning (ps_env byte 52, bit 3)
  let psFlags = cast[ptr uint8](psBase + 52)[]
  if (psFlags and 8) != 0: return

  # Check rx header is valid
  if rxHdr == nil: return

  let rx = cast[uint](rxHdr)
  let vifWmm = cast[ptr uint8](vif + 94)[]
  if vifWmm == 0:
    # Non-WMM path: check frame type bit in rxHdr[4]
    let frameTypeBit = cast[ptr uint8](rx + 4)[]
    if (frameTypeBit and 1) != 0:
      # TIM present: set bit 1 in vif[4]
      flags = cast[ptr uint32](vif + 4)[]
      flags = flags or 2'u32
      cast[ptr uint32](vif + 4)[] = flags
    else:
      # TIM not present: clear bit 1
      flags = cast[ptr uint32](vif + 4)[]
      flags = flags and not 2'u32
      cast[ptr uint32](vif + 4)[] = flags

  # Parse TIM bitmap to check our AID
  let timElement = cast[ptr uint8](rx + 4)[]
  let aidBytePos = aid shr 3  # byte position in TIM bitmap
  let bitmapControl = cast[ptr uint8](rx + 4)[] and 0xFE'u8  # bitmap offset
  let bitmapStart = bitmapControl.uint16

  if aidBytePos < bitmapStart:
    # Our AID is before TIM bitmap range -- check UAPSD and flags
    let uapsd = cast[ptr uint8](vif + 104)[] and 0x0F
    flags = cast[ptr uint32](vif + 4)[]
    flags = flags and not 4'u32  # clear bit 2
    if uapsd == 0x0F:
      flags = flags and not 8'u32  # also clear bit 3 if all ACs are UAPSD
    cast[ptr uint32](vif + 4)[] = flags

    # Check if PS is active or bit 1 is set -> wakeup
    let psActive = cast[ptr uint8](vif + 91)[]
    if psActive != 0 or (flags and 2) != 0:
      # Blob just sets bit 6 in vif[4] here; previous Nim inserted a
      # vif_mgmt_bcn_to_prog call before the flag set which re-programmed the
      # beacon timer — an extra side effect the blob never emits.
      flags = cast[ptr uint32](vif + 4)[]
      flags = flags or 64'u32  # set bit 6
      cast[ptr uint32](vif + 4)[] = flags
    return

  let timLen = cast[ptr uint8](rx + 1)[]
  let bitmapEnd = bitmapStart + timLen.uint16 - 4

  if aidBytePos > bitmapEnd:
    # Our AID is after TIM bitmap range
    let uapsd = cast[ptr uint8](vif + 104)[] and 0x0F
    flags = cast[ptr uint32](vif + 4)[]
    flags = flags and not 4'u32
    if uapsd == 0x0F:
      flags = flags and not 8'u32
    cast[ptr uint32](vif + 4)[] = flags
    let psActive = cast[ptr uint8](vif + 91)[]
    if psActive != 0 or (flags and 2) != 0:
      # Blob just sets bit 6 in vif[4] here; previous Nim inserted a
      # vif_mgmt_bcn_to_prog call before the flag set which re-programmed the
      # beacon timer — an extra side effect the blob never emits.
      flags = cast[ptr uint32](vif + 4)[]
      flags = flags or 64'u32
      cast[ptr uint32](vif + 4)[] = flags
    return

  # Our AID is within TIM bitmap: check our bit
  let timByte = cast[ptr uint8](rx + 5 + (aidBytePos - bitmapStart).uint)[]
  let bitPos = aid and 7
  let bitMask = 1'u8 shl bitPos
  if (timByte and bitMask) != 0:
    # Traffic buffered for us: blob just sets bit 6 in vif[4]; see note above
    # about the removed vif_mgmt_bcn_to_prog call.
    flags = cast[ptr uint32](vif + 4)[]
    flags = flags or 64'u32  # set bit 6
    cast[ptr uint32](vif + 4)[] = flags
  else:
    # No traffic: check UAPSD and flags
    let uapsd = cast[ptr uint8](vif + 104)[] and 0x0F
    flags = cast[ptr uint32](vif + 4)[]
    flags = flags and not 4'u32
    if uapsd == 0x0F:
      flags = flags and not 8'u32
    cast[ptr uint32](vif + 4)[] = flags
    let psActive = cast[ptr uint8](vif + 91)[]
    if psActive != 0 or (flags and 2) != 0:
      # Blob just sets bit 6 in vif[4] here; previous Nim inserted a
      # vif_mgmt_bcn_to_prog call before the flag set which re-programmed the
      # beacon timer — an extra side effect the blob never emits.
      flags = cast[ptr uint32](vif + 4)[]
      flags = flags or 64'u32
      cast[ptr uint32](vif + 4)[] = flags
  # Notify traffic detection about TIM (blob: td_pack_tim_ind at 0xb4)
  let vifIdx2 = cast[ptr uint8](vif + 87)[]
  td_pack_tim_ind(vifIdx2)

proc ps_check_tbtt*(vifEntry: pointer) {.exportc, cdecl.} =
  ## TBTT hook from the PS subsystem.
  ## Blob algorithm:
  ##   if ps_env[0] == 0: return
  ##   if (ps_env[52] & 8): return               ; scanning -> skip
  ##   if vif[91] == 0: return                   ; PS not active on this vif
  ##   td_pack_tim_ind(vif[87])                  ; notify upper layer
  ##   vif[4] |= 0x40                            ; mark TBTT handled
  ## Prior Nim bug: called vif_mgmt_bcn_to_prog(vifEntry). That reprograms
  ## the bcn-timeout timer and has nothing to do with TIM packing — AP-side
  ## TIM bits would never be re-sent to host, causing dropped PS deliveries.
  let psBase = cast[uint](addr ps_env[0])
  if cast[ptr uint8](psBase)[] == 0:
    return
  if (cast[ptr uint8](psBase + 52)[] and 8'u8) != 0:
    return
  let vif = cast[uint](vifEntry)
  if cast[ptr uint8](vif + 91)[] == 0:
    return
  td_pack_tim_ind(cast[ptr uint8](vif + 87)[])
  var flags = cast[ptr uint32](vif + 4)[]
  flags = flags or 64'u32
  cast[ptr uint32](vif + 4)[] = flags

proc ps_check_frame*(rxHdr: pointer, frameFlags: uint32, vifEntry: pointer) {.exportc, cdecl.} =
  ## Check received frame for PS state change.
  ## From blob (114 instrs): checks ps_env enabled. Parses frame control from
  ## rxHdr to determine frame type. For data frames, checks UAPSD trigger/delivery.
  ## For non-PS-Poll QoS null frames with matching BSSID, may trigger sleep transition.
  ## Sets/clears bits in vif[4] based on frame analysis.
  let psBase = cast[uint](addr ps_env[0])
  let vif = cast[uint](vifEntry)

  # Check PS enabled
  let psEn = cast[ptr uint8](psBase)[]
  if psEn == 0: return

  # Load frame control from rxHdr
  let rx = cast[uint](rxHdr)
  let fc0 = cast[ptr uint8](rx + 0)[]
  let fc1 = cast[ptr uint8](rx + 1)[]
  let frameCtrl = fc0.uint16 or (fc1.uint16 shl 8)

  # Check FromDS bit (bit 0 of rxHdr[4])
  let fromDs = cast[ptr uint8](rx + 4)[]
  if (fromDs and 1) != 0:
    # FromDS set: check if protected frame
    let protectedBit = frameCtrl and 0x2000'u16
    if protectedBit != 0:
      let vifWmm = cast[ptr uint8](vif + 94)[]
      if vifWmm != 0:
        # Clear bit 1 in vif[4]
        var flags = cast[ptr uint32](vif + 4)[]
        flags = flags and not 2'u32
        cast[ptr uint32](vif + 4)[] = flags
    return

  # Check A-MSDU flag (bit 9 of frameFlags)
  if (frameFlags and 0x200'u32) != 0:
    return

  # PS mode active check (ps_env byte 29). Blob simply returns here when
  # psMode29 == 0; previous Nim inserted a vif_mgmt_bcn_to_prog(vif) call
  # that reprograms the next-beacon timer — an action blob never performs
  # from ps_check_frame.
  let psMode29 = cast[ptr uint8](psBase + 29)[]
  if psMode29 == 0:
    return

  # Check frame subtype (bits [7:4] of frame control)
  let subtypeBits = frameCtrl and 0x00F0'u16
  let typeBits = frameCtrl and 0x000C'u16

  # Check if frame is QoS data (subtype bits 3,0 = 1,0,0,0 = 0x88)
  if (frameCtrl and 0x88) != 0x88:
    # Not QoS data: check for UAPSD trigger
    if (frameCtrl and 0x0C) != 0:
      return  # not data type
    # Check UAPSD bitmap for trigger
    let uapsdBitmap = cast[ptr uint8](vif + 104)[]
    if (uapsdBitmap and 8) == 0:
      return

    # UAPSD triggered: read MAC time and store at vif[100]
    let macTime = regRead(MACHW_TIMLO_REG)
    cast[ptr uint32](vif + 100)[] = macTime
    return

  # QoS data frame: parse priority and check UAPSD
  # Load QoS TID from frame header (offset depends on addr4 presence)
  let has4Addr = (frameCtrl and 0x0300'u16) == 0x0300'u16
  var tidOffset: uint
  if has4Addr:
    tidOffset = rx + 30  # 4-addr header: QoS at offset 30-31
  else:
    tidOffset = rx + 24  # 3-addr header: QoS at offset 24-25

  let qosTid0 = cast[ptr uint8](tidOffset + 0)[]
  let qosTid1 = cast[ptr uint8](tidOffset + 1)[]
  let qosTid = qosTid0.uint16 or (qosTid1.uint16 shl 8)

  # Extract TID (bits 0-2) and map to AC
  let tid = qosTid and 7
  # Load AC mapping from per-VIF UAPSD config
  let acMap = cast[ptr uint8](vif + 104)[]

  # Shift UAPSD bitmap by TID's AC to check trigger
  let acBit = (acMap.uint32 shr tid.uint32) and 1
  if acBit == 0:
    return

  # UAPSD delivery enabled for this AC: store MAC time
  let macTime = regRead(MACHW_TIMLO_REG)
  cast[ptr uint32](vif + 100)[] = macTime

  # Check MoreData bit (bit 4 of QoS field)
  if (qosTid and 0x10) == 0:
    return

  # MoreData set: check if we should suppress UAPSD trigger
  let psFlags52 = cast[ptr uint8](psBase + 52)[]
  if (psFlags52 and 8) != 0:
    return  # scanning, don't trigger

  # Trigger traffic request
  let vifIdx2 = cast[ptr uint8](vif + 87)[]

  # Clear bit 2 in vif[4]
  var flags2 = cast[ptr uint32](vif + 4)[]
  flags2 = flags2 and not 4'u32
  cast[ptr uint32](vif + 4)[] = flags2

  # Check if FromDS+ToDS match BSSID
  let fc16Check = frameCtrl and 0x2000'u16
  if fc16Check != 0:
    return

  # Trigger traffic detection and PS-Poll (blob calls at 0xfe and 0x11a)
  td_pck_ps_ind(cast[ptr uint8](vif + 87)[], 1)  # traffic detection: vifIdx, direction=RX
  discard ps_send_pspoll(vifEntry)  # send PS-Poll frame

proc ps_check_tx_frame*(vifIdx: uint8, staIdx: uint8): bool {.exportc, cdecl.} =
  ## Check if TX frame needs PS handling.
  ## From blob (60 instrs): checks ps_env enabled, validates vif/sta indices.
  ## Computes STA entry = sta_info_tab + staIdx * 368. Checks vif[86] (type),
  ## vif[88] (PS capable), vif[104] (UAPSD bitmap). If UAPSD trigger AC matches,
  ## logs and sets bit 3 in vif[4], reads MAC time to vif[100].
  ## Otherwise calls vif_mgmt_bcn_to_prog and returns false.
  let psBase = cast[uint](addr ps_env[0])
  let psEn = cast[ptr uint8](psBase)[]
  if psEn == 0:
    return false

  if vifIdx == 0xFF or staIdx == 0xFF:
    return false

  let staTabBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staTabBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let vifTabBase = cast[uint](addr vif_info_tab[0])

  # Get VIF entry from STA's VIF pointer or compute from staEntry[39]
  let staVifIdx = cast[ptr uint8](staEntry + 39)[]
  let vif = vifTabBase + staVifIdx.uint * VIF_ENTRY_SIZE.uint

  # Check VIF type (offset 86): must not be monitor (type != monitor)
  let vifType = cast[ptr uint8](vif + 86)[]
  if vifType != 0:
    return false

  # Check PS capable (offset 88)
  let psCap = cast[ptr uint8](vif + 88)[]
  if psCap == 0:
    return false

  # Check UAPSD bitmap (vif[104]): shift by STA's AC
  let uapsdBitmap = cast[ptr uint8](vif + 104)[]
  # Get AC from STA TX descriptor
  let ac = cast[ptr uint8](staEntry + 40)[]
  let acBit = (uapsdBitmap.uint32 shr ac.uint32) and 1
  if acBit != 0:
    # UAPSD active for this AC: set bit 3 in vif[4]
    var flags = cast[ptr uint32](vif + 4)[]
    flags = flags or 8'u32
    cast[ptr uint32](vif + 4)[] = flags

    # Read MAC time to vif[100]
    let macTime = regRead(MACHW_TIMLO_REG)
    cast[ptr uint32](vif + 100)[] = macTime
    return false

  # Not UAPSD: tail-call td_pck_ps_ind(vifIdx, 0) for TX traffic detection
  let vifIdx2 = cast[ptr uint8](vif + 87)[]
  td_pck_ps_ind(vifIdx2, 0)  # direction=TX
  return false

proc ps_polling_frame*() {.exportc, cdecl.} =
  ## Send PS-Poll frame. Blob (2 instrs): auipc t1, R_RISCV_CALL ps_send_pspoll;
  ## jr t1 — a pure tail-call that passes the caller's a0 through untouched.
  ## We preserve that ABI by capturing a0 via inline asm so Nim doesn't
  ## overwrite it with `nil`.
  var vifEntry {.noinit.}: pointer
  {.emit: ["asm volatile(\"mv %0, a0\" : \"=r\"(", vifEntry, ") );"].}
  discard ps_send_pspoll(vifEntry)

proc ps_traffic_null_1_recovery*() {.exportc, cdecl.} =
  ## Recovery after null frame 1 failure.
  discard

proc ps_check_tx_status_part0_nim*(vifEntry: pointer, completionFn: pointer): uint32
  {.exportc: "ps_check_tx_status_part0_nim", cdecl.} =
  ## Nim-side implementation. Matches blob `ps_check_tx_status.part.0`.
  ## Blob flow:
  ##   retry = ++vif[95] (u8, zext)
  ##   threshold = *(u32*)(ps_env + 12)     // WORD, not byte
  ##   if retry == threshold:
  ##       ps_env[0] = 0
  ##       mm_send_connection_loss_ind(vif /*truncated to vifIdx*/, 21)
  ##       return 1
  ##   if retry == threshold >> 1:
  ##       wifi_hosal_pm_post_event(4, 1, 0)
  ##       return 1
  ##   if ps_env[8] == 0:
  ##       return 1
  ##   rc = txl_frame_send_null_frame(staIdx=vif[96], completionFn, vifEntry)
  ##   if rc == 0: return 0
  ##   (log via g_bl_ops_funcs[1] if non-null; ignored for correctness)
  ##   return 0
  if vifEntry == nil: return 0'u32
  let vifU = cast[uint](vifEntry)
  let psBase = cast[uint](addr ps_env[0])
  let retry = cast[ptr uint8](vifU + 95)[] + 1'u8
  cast[ptr uint8](vifU + 95)[] = retry
  # Blob loads a WORD (lw) at ps_env+12. Compare retry (u8) against low byte.
  let threshold = cast[ptr uint32](psBase + 12)[]
  let thresholdLo = cast[uint8](threshold and 0xFF)
  if retry == thresholdLo:
    cast[ptr uint8](psBase)[] = 0
    mm_send_connection_loss_ind(cast[uint8](vifU and 0xFF), 21'u16)
    return 1'u32
  # Second branch: retry == threshold >> 1
  let halfThreshold = cast[uint8]((threshold shr 1) and 0xFF)
  if retry == halfThreshold:
    wifi_hosal_pm_post_event(4'u32, 1'u32, nil)
    return 1'u32
  # If ps_env[8] == 0 -> no outstanding enable count, return 1
  if cast[ptr uint8](psBase + 8)[] == 0:
    return 1'u32
  # Send null frame: blob passes (a0=staIdx, a1=completionFn, a2=vifEntry).
  # Our Nim `txl_frame_send_null_frame` has signature (uint8, uint8, bool) but
  # the blob calls it with (staIdx, completionFn, vifEntry). Emit a raw call
  # that pins a0/a1/a2 to the exact values the callee expects — the function
  # stores a2 at desc[212] (completion arg) verbatim, which matches blob.
  let staIdx = cast[ptr uint8](vifU + 96)[]
  var rc: uint32
  {.emit: ["""
  {
    register unsigned long _a0 __asm__("a0") = (unsigned long)""", staIdx, """;
    register unsigned long _a1 __asm__("a1") = (unsigned long)""", completionFn, """;
    register unsigned long _a2 __asm__("a2") = (unsigned long)""", vifEntry, """;
    __asm__ volatile (
      "call txl_frame_send_null_frame"
      : "+r"(_a0), "+r"(_a1), "+r"(_a2)
      :
      : "ra","memory","a3","a4","a5","a6","a7",
        "t0","t1","t2","t3","t4","t5","t6");
    """, rc, """ = (unsigned int)_a0;
  }
  """].}
  # Blob semantics:
  #   if rc == 0 (null-frame queued successfully): return 0 (retry in progress)
  #   else (failed to send): log via g_bl_ops_funcs[1] (printf-like fn pointer),
  #     picks "enable" or "disable" string by comparing completionFn vs ps_enable_cfm,
  #     passes format string + mode + retry counter, then return 1.
  if rc == 0'u32:
    return 0'u32
  # Emit the log call. g_bl_ops_funcs[1] is the printf-like pointer at offset 4.
  let logPtr = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 4)[]
  if logPtr != nil:
    let psEnableAddr = cast[uint](ps_enable_cfm)
    let isEnable = cast[uint](completionFn) == psEnableAddr
    const modeEnable: cstring = "enable"
    const modeDisable: cstring = "disable"
    const fmt: cstring = "abort NULL frame send for PS %s, tried %u\r\n"
    let modeStr = if isEnable: modeEnable else: modeDisable
    let retryCnt = cast[ptr uint8](vifU + 95)[].uint32
    let printFn = cast[proc(fmt: cstring, mode: cstring, tried: uint32){.cdecl, varargs.}](logPtr)
    printFn(fmt, modeStr, retryCnt)
  return 1'u32

# Export an alias with the exact blob-style symbol `ps_check_tx_status.part.0`.
# Use a true GCC `alias` attribute so there's no extra call frame (alias
# symbols resolve at link time to the same address). Matches blob which
# has only the `.part.0` symbol and no wrapper.
{.emit: """
NU32 ps_check_tx_status_part0_alias(void* v, void* f)
    __attribute__((alias("ps_check_tx_status_part0_nim")));
asm(".globl ps_check_tx_status.part.0\n"
    ".set ps_check_tx_status.part.0, ps_check_tx_status_part0_nim");
""".}

proc ps_disable_cfm*(vifEntry: pointer, statusFlags: uint32) {.exportc, cdecl.} =
  ## PS disable confirmation (114 bytes in blob).
  ## Blob: check ps_env[52] bit 2 (scanning) for early return.
  ## If statusFlags bit 23 (0x800000) set: decrement ps_env[8] count,
  ##   clear timer at ps_env+0x24, if count reaches 0 call ps_disable_cfm_handle.
  ## If bit 23 not set: call ps_check_tx_status (inline), loop back if non-zero.
  let psBase = cast[uint](addr ps_env[0])
  # Check scanning flag: ps_env byte 52, bit 2
  let psFlags = cast[ptr uint8](psBase + 52)[]
  if (psFlags and 4) != 0:
    return
  let hasTxCfm = (statusFlags and 0x00800000'u32) != 0
  if not hasTxCfm:
    # No HW confirmation bit: check TX status via ps_check_tx_status.part.0
    # (GCC-generated partial function name, need asm label to reference it)
    var checkResult: uint32
    {.emit: """
extern unsigned int ps_check_tx_status_part0(void*, void*) __asm__("ps_check_tx_status.part.0");
""".}
    {.emit: [checkResult, " = ps_check_tx_status_part0(", vifEntry, ", (void*)", ps_disable_cfm, ");"].}
    if checkResult == 0:
      return
    # Non-zero means TX confirm arrived, fall through to decrement path
  # Decrement TX confirm counter and clear timer
  let cnt = cast[ptr uint8](psBase + 8)[]
  if cnt == 0:
    return
  let newCnt = cnt - 1
  cast[ptr uint8](psBase + 8)[] = newCnt
  mm_timer_clear(cast[pointer](psBase + 0x24))
  if newCnt != 0:
    return
  # All confirms received: finalize disable
  discard ps_disable_cfm_handle(vifEntry)

proc ps_traffic_status_update*(vifIdx: uint8, status: uint32) {.exportc, cdecl.} =
  ## Update traffic status for PS decisions.
  ## From blob (70 instrs): checks ps_env enabled and PS mode flags.
  ## If status == 0 (idle): walks VIF linked list looking for VIF with matching
  ## vif_idx. Checks VIF type (offset 86), PS capable (offset 88), and PS active
  ## (offset 91). If conditions met, checks UAPSD config for traffic type and
  ## may call dbg_snp_write for logging.
  ## Then checks ps_env scanning flag (byte 52, bit 3): if s0 (found flag) is set
  ## and not scanning, tail-calls ps wakeup function.
  let psBase = cast[uint](addr ps_env[0])

  # Check PS enabled
  let psEn = cast[ptr uint8](psBase)[]
  if psEn == 0: return

  # Check PS mode flags at ps_env[52]
  let psFlags = cast[ptr uint8](psBase + 52)[]
  if (psFlags and 1) == 0: return   # PS not in correct mode
  if (psFlags and 6) != 0: return   # mode bits 1-2 set: skip

  var foundVif = false
  var foundVifPtr: pointer = nil

  if status == 0:
    # Traffic idle: walk VIF active linked list looking for matching vif_idx
    # Blob: loads linked list head from a GOT-relative pointer, walks via offset 0
    let vifListHeadPtr = cast[ptr pointer](cast[uint](addr vif_mgmt_env[0]))[]
    var vifCur = vifListHeadPtr
    let vifTabBase = cast[uint](addr vif_info_tab[0])
    let stride = VIF_ENTRY_SIZE.uint
    while vifCur != nil:
      let vif = cast[uint](vifCur)
      let thisVifIdx = cast[ptr uint8](vif + 87)[]
      if thisVifIdx == vifIdx:
        # Found matching VIF: check PS capable, type, UAPSD
        let psCap = cast[ptr uint8](vif + 88)[]
        if psCap != 0:
          let vifType = cast[ptr uint8](vif + 86)[]
          if vifType == 0:  # STA type
            # Check UAPSD active delivery config (byte at vif+41 of sta_entry)
            # Blob: loads sta context and checks bits 2-3 (UAPSD delivery bits)
            let staCtxByte = cast[ptr uint8](vif + 41)[]
            if (staCtxByte and 0x0C) != 0:
              # Log via debug function (blob: dbg_snp_write at line 1187)
              let logFn = getLogFunc(0)
              if logFn != nil:
                logFn(1, 0, nil, 1187)
              foundVif = true
              foundVifPtr = vifCur
        break  # only check first matching VIF
      vifCur = cast[ptr pointer](vif)[]  # next = vif[0]

  # Check scanning flag at ps_env[52] bit 3
  let scanning = (cast[ptr uint8](psBase + 52)[] and 8) != 0

  if not foundVif:
    if scanning:
      return
    return  # no VIF matched, not scanning

  # Found matching VIF: if not scanning, trigger DPSM update (blob: ps_dpsm_update)
  if not scanning:
    ps_dpsm_update(1)  # enable=1: enter dynamic PS mode

proc ps_uapsd_set*(vifEntry: pointer, ac: uint8, enabled: uint32) {.exportc, cdecl.} =
  ## Enable/disable U-APSD for an AC.
  ## From blob (35 instrs): computes bit mask (1 << ac). If enabled (a2 != 0),
  ## ORs into vif[104]. Else ANDs complement. Then checks if ps_env is enabled
  ## and UAPSD timer not already active: if so, reads MAC time, adds to timer
  ## period at ps_env[32], sets mm_timer on ps_env UAPSD timer, and marks
  ## UAPSD timer as active (ps_env[28]=1).
  let vif = cast[uint](vifEntry)
  let bitMask = 1'u8 shl ac
  let psBase = cast[uint](addr ps_env[0])

  let curBitmap = cast[ptr uint8](vif + 104)[]
  if enabled != 0:
    # Set UAPSD bit for this AC
    let newBitmap = curBitmap or bitMask
    cast[ptr uint8](vif + 104)[] = newBitmap

    # Check if we should start the UAPSD timer
    let psEn = cast[ptr uint8](psBase)[]
    if psEn == 0: return
    let timerActive = cast[ptr uint8](psBase + 28)[]
    if timerActive != 0: return

    # Start UAPSD timer: mark as will-be-active
    cast[ptr uint8](psBase + 29)[] = 1

    # Read MAC time, add period from ps_env[32], set timer
    let macTime = regRead(MACHW_TIMLO_REG)
    let period = cast[ptr uint32](psBase + 32)[]
    mm_timer_set(cast[pointer](psBase + 12), macTime + period)

    # Mark UAPSD timer as active
    cast[ptr uint8](psBase + 28)[] = 1
  else:
    # Clear UAPSD bit for this AC
    let newBitmap = curBitmap and not bitMask
    cast[ptr uint8](vif + 104)[] = newBitmap

proc ps_uapsd_timer_handle*() {.exportc, cdecl.} =
  ## U-APSD timer callback (91 instrs, stored in ps_env[4] during ps_init).
  ## Walks the VIF info list looking for active STA VIFs in power save.
  ## For each eligible VIF, checks if UAPSD trigger timeout expired.
  ## If expired, logs a warning and sends a QoS null frame to trigger delivery.
  ## Finally schedules the next timer or clears the UAPSD timer state.
  ##
  ## Assembly trace:
  ##   s0 = vif_info_tab linked list head (from vif_mgmt_env)
  ##   s6 = found_any flag (0 initially)
  ##   s1 = 0x24B00 base (for MACHW_TIMLO_REG)
  ##   s2 = ps_env base
  ##   Loops: while s0 != nil:
  ##     check vif.type(+86) != 0 -> skip
  ##     check vif.active(+88) == 0 -> skip
  ##     check vif.ps_flag(+104) == 0 -> skip
  ##     call ps_check_tbtt(vif) -> if 0 -> skip
  ##     check ps_env[32] timer offset: if (now - vif[100]) expired -> trigger
  ##       log warning, set vif[4] |= 8, send ke_msg(7=RXU_NULL_DATA, ...)
  ##       update vif[100] = now
  ##     s0 = vif.next (follow linked list)
  ##   If s6==0 (nothing found): clear timer state, return
  ##   Else: schedule next UAPSD timer with mm_timer_set
  let vifMgmtBase = cast[uint](addr vif_mgmt_env[0])
  var vifPtr = cast[ptr pointer](vifMgmtBase)[]  # linked list head
  var foundAny = false
  let psBase = cast[uint](addr ps_env[0])
  let macTime = macTimeNow()
  while vifPtr != nil:
    let vifAddr = cast[uint](vifPtr)
    # Check VIF type == STA (offset 86)
    let vifType = cast[ptr uint8](vifAddr + 86)[]
    if vifType != 0:
      vifPtr = cast[ptr pointer](vifAddr)[]
      continue
    # Check VIF active (offset 88)
    let active = cast[ptr uint8](vifAddr + 88)[]
    if active == 0:
      vifPtr = cast[ptr pointer](vifAddr)[]
      continue
    # Check PS flag at VIF+104
    let psFlag = cast[ptr uint8](vifAddr + 104)[]
    if psFlag == 0:
      vifPtr = cast[ptr pointer](vifAddr)[]
      continue
    # Check if on channel (blob: chan_is_on_channel, NOT ps_check_tbtt)
    if not chan_is_on_channel(cast[pointer](vifAddr)):
      vifPtr = cast[ptr pointer](vifAddr)[]
      continue
    foundAny = true
    # Check timer expiry: ps_env[32] has half-period, compare with vif[100] timestamp
    let halfPeriod = cast[ptr uint32](psBase + 32)[]
    let lastTime = cast[ptr uint32](vifAddr + 100)[]
    let elapsed = macTime - (halfPeriod shr 1) - lastTime
    if cast[int32](elapsed) < 0:
      # Timer expired: log and trigger
      let logFn = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
      if logFn != nil:
        let log = cast[PlatformLogFunc](logFn)
        log(1, 0, nil, 567)
      # Set UAPSD trigger flag
      let flags = cast[ptr uint32](vifAddr + 4)[]
      cast[ptr uint32](vifAddr + 4)[] = flags or 0x08
      # Send QoS null frame (blob: txl_frame_send_qosnull_frame)
      let vifIdxVal = cast[ptr uint8](vifAddr + 87)[]
      let staIdxVal = cast[ptr uint8](vifAddr + 96)[]
      txl_frame_send_qosnull_frame(vifIdxVal, staIdxVal, 3)
      # Update timestamp
      cast[ptr uint32](vifAddr + 100)[] = macTime
    vifPtr = cast[ptr pointer](vifAddr)[]
  if not foundAny:
    # No active UAPSD VIFs: clear timer state
    cast[ptr uint8](psBase + 48)[] = 0
    return
  # Schedule next timer: tail-call mm_timer_set with UAPSD timer offset
  let timerDelay = cast[ptr uint32](psBase + 32)[]
  let timerTarget = macTime + timerDelay
  mm_timer_set(cast[pointer](psBase + 16), timerTarget)

proc ps_tx_null_timer_handle*() {.exportc, cdecl.} =
  ## TX null frame timer callback (80 bytes in blob).
  ## Blob: checks ps_env flags, then dispatches:
  ##   ps_disable_cfm_handle, ps_enable_cfm_handle, txl_cntrl_clear_ac
  let psBase = cast[uint](addr ps_env[0])
  let flags = cast[ptr uint8](psBase + 52)[]
  if (flags and 1) == 0:
    return
  let cnt = cast[ptr uint8](psBase + 8)[]
  if cnt == 0:
    return
  cast[ptr uint8](psBase + 8)[] = cnt - 1
  if cnt - 1 != 0:
    return
  # All null frames confirmed: dispatch based on PS mode
  if (flags and 2) != 0:
    discard ps_disable_cfm_handle(nil)
  elif (flags and 4) != 0:
    ps_enable_cfm_handle(nil)
  # Clear any pending TX on AC3 (blob: txl_cntrl_clear_ac)
  txl_cntrl_clear_ac(3)

proc pm_force_sleep_check*(): bool {.exportc, cdecl.} =
  ## Check if forced sleep is allowed.
  ## From blob (ps.o, 2 instrs): always returns 1 (true) - stub.
  return true

proc set_mac_to_doze*(): uint32 {.exportc, cdecl.} =
  ## Transition MAC HW to doze (low-power) state (148 bytes in blob, 40 instrs).
  ## From blob: sets bit 6 (0x40) in MAC_CTRL reg (0x24B0004C), then reads
  ## MAC_STATUS (0x24B00038). If low nibble != 0 (MAC still active), calls
  ## assert fn ptr and diagnostic fn ptr from mm_env before proceeding.
  ## Sets doze_flag global = 1, writes 0x20 (DOZE) to MAC_STATUS.
  # Set bit 6 (doze request) in MAC control register
  var ctrlReg = regRead(MACHW_STATUS_REG)
  ctrlReg = ctrlReg or 0x40'u32
  regWrite(MACHW_STATUS_REG, ctrlReg)
  # Read current state from MAC state/control register
  let curState = regRead(MACHW_STATE_CNTRL_REG) and 0x0F'u32
  if curState != 0:
    # MAC not idle - call assert and diagnostic function pointers
    let mmBase = cast[uint](addr mm_env[0])
    let assertFn = cast[ptr pointer](mmBase + 204)[]
    if assertFn != nil:
      cast[proc(a0: uint32, a1: uint32, file: pointer, line: uint32, rec: pointer) {.cdecl.}](assertFn)(
        TASK_MM.uint32, 0, nil, 286, nil)
    let diagFn = cast[ptr pointer](mmBase + 12)[]
    if diagFn != nil:
      cast[proc(a0: pointer, line: uint32, file: pointer, param: pointer) {.cdecl.}](diagFn)(
        nil, 287, nil, nil)
  # Set doze-in-progress flag
  cast[ptr uint32](cast[uint](addr ps_env[0]) + 56)[] = 1
  # Write DOZE command (0x20) to MAC state register
  regWrite(MACHW_STATE_CNTRL_REG, 0x20'u32)
  return 0

proc wait_mac_goto_idle*(): uint32 {.exportc, cdecl.} =
  ## Wait for MAC to reach IDLE state.
  ## From blob (ps.o, 33 instrs): reads state register, stores pre-state byte,
  ## clears bit 31 in INTC unmask, sets bit 2 (IDLE command), writes 0 to
  ## state register. Polls INTC status bit 2 with timeout (0x4C4B3F iterations).
  ## After poll: reads final state, writes 4 to INTC ack, clears bit 2,
  ## sets bit 31 back. Returns 0 if idle reached, 1 if state non-zero.
  let curState = regRead(MACHW_STATE_CNTRL_REG) and 0x0F'u32
  if curState == 0:
    return 0  # Already idle
  # Clear bit 31 of INTC unmask (offset 0x074)
  let intcCtrl = MACHW_INTC_BASE + 0x074'u
  var unmask = regRead(intcCtrl)
  unmask = unmask and 0x7FFFFFFF'u32
  regWrite(intcCtrl, unmask)
  # Set bit 2 (idle command) and clear current state
  regWrite(intcCtrl, unmask or 0x04'u32)
  regWrite(MACHW_STATE_CNTRL_REG, 0'u32)
  # Poll for completion: read timestamp for timeout
  let startTime = macTimeNow()
  let timeout = 0x4C4B3F'u32
  while true:
    let status = regRead(MACHW_INTC_BASE + 0x06C'u)
    if (status and 0x04'u32) != 0:
      break
    let elapsed = macTimeNow() - startTime
    if elapsed >= timeout:
      break
  # Read final state
  let finalState = regRead(MACHW_STATE_CNTRL_REG) and 0x0F'u32
  # Ack: write 4 to ack register, clear bit 2
  regWrite(MACHW_INTC_BASE + 0x070'u, 0x04'u32)
  unmask = regRead(intcCtrl)
  unmask = unmask and not 0x04'u32
  regWrite(intcCtrl, unmask)
  # Restore bit 31
  unmask = regRead(intcCtrl)
  unmask = unmask or 0x80000000'u32
  regWrite(intcCtrl, unmask)
  return if finalState != 0: 1'u32 else: 0'u32

proc wait_mac_goto_prestate*(): uint32 {.exportc, cdecl.} =
  ## Wait for MAC to return to its saved pre-state.
  ## From blob (ps.o, 23 instrs): reads saved pre-state byte,
  ## if 0 returns immediately. Shifts left by 4 (into bits [7:4]),
  ## writes to state register, then polls until state[3:0] matches.
  let preState = cast[ptr uint8](cast[uint](addr ps_env[0]) + 60)[]  # saved pre-state
  if preState == 0:
    return 0
  let targetBits = preState.uint32 shl 4
  if (targetBits and 0xFFFFFF0F'u32) != 0:
    assert_err("ps.c", "ps.c", 1465)
  regWrite(MACHW_STATE_CNTRL_REG, targetBits)
  # Poll until state matches pre-state
  while true:
    let cur = regRead(MACHW_STATE_CNTRL_REG) and 0x0F'u32
    if cur == preState.uint32:
      break
  return 0

proc wakeup_from_doze_done*(): uint32 {.exportc, cdecl.} =
  ## Complete doze wakeup: clear doze flag in INTC.
  ## From blob (ps.o, 6 instrs): clears bit 31 (0x80000000) in
  ## MACHW_INTC_BASE+0x048, returns 0.
  var reg = regRead(MACHW_INTC_BASE + 0x048'u)
  reg = reg and 0x7FFFFFFF'u32
  regWrite(MACHW_INTC_BASE + 0x048'u, reg)
  return 0

proc wakeup_from_doze_pre*(): uint32 {.exportc, cdecl.} =
  ## Prepare wakeup from doze state.
  ## From blob (ps.o, 38 instrs): clears bit 31 of INTC+0x074, writes 4 to INTC+0x070,
  ## sets bit 2 of INTC+0x074, sets bit 31 of INTC+0x048. Clears doze flag.
  ## Polls INTC+0x06C bit 2 with short spin (501 iterations).
  ## Then polls with timestamp timeout (0x4C4B3F). When done, waits for
  ## state register [3:0] to reach 0 (idle), then writes 4 to INTC+0x070,
  ## clears bit 2, sets bit 31 of INTC+0x074.
  let intcCtrl = MACHW_INTC_BASE + 0x074'u
  var unmask = regRead(intcCtrl)
  unmask = unmask and 0x7FFFFFFF'u32
  regWrite(intcCtrl, unmask)
  # Write ack and set idle command
  regWrite(MACHW_INTC_BASE + 0x070'u, 0x04'u32)
  unmask = regRead(intcCtrl)
  unmask = unmask or 0x04'u32
  regWrite(intcCtrl, unmask)
  # Set doze wakeup bit (bit 31) in INTC+0x048
  var dozeReg = regRead(MACHW_INTC_BASE + 0x048'u)
  dozeReg = dozeReg and 0x7FFFFFFF'u32
  dozeReg = dozeReg or 0x80000000'u32
  regWrite(MACHW_INTC_BASE + 0x048'u, dozeReg)
  # Clear doze-in-progress
  cast[ptr uint32](cast[uint](addr ps_env[0]) + 56)[] = 0
  # Short spin waiting for INTC bit 2
  var spins = 501'u32
  while spins > 0:
    let status = regRead(MACHW_INTC_BASE + 0x06C'u)
    if (status and 0x04'u32) != 0:
      break
    dec spins
  # Timestamp-based timeout poll
  let startTime = macTimeNow()
  let timeout = 0x4C4B3F'u32
  while true:
    let status = regRead(MACHW_INTC_BASE + 0x06C'u)
    if (status and 0x04'u32) != 0:
      break
    let elapsed = macTimeNow() - startTime
    if elapsed >= timeout:
      break
  # Wait for state to go idle
  while (regRead(MACHW_STATE_CNTRL_REG) and 0x0F'u32) != 0:
    discard
  # Final: ack, clear, set
  regWrite(MACHW_INTC_BASE + 0x070'u, 0x04'u32)
  unmask = regRead(intcCtrl)
  unmask = unmask and not 0x04'u32
  regWrite(intcCtrl, unmask)
  unmask = regRead(intcCtrl)
  unmask = unmask or 0x80000000'u32
  regWrite(intcCtrl, unmask)
  return 0

proc ps_disable_cfm_handle*(vifEntry: pointer): uint32 {.exportc, cdecl.} =
  ## Handle PS disable confirmation from MAC (232 bytes in blob, 59 instrs).
  ## From blob (ps.o) -- faithful translation:
  ##   s1 = vifEntry
  ##   local localStatus = 0                           ; sp+12
  ##   mm_timer_clear(&ps_env + 12)
  ##   ps_env[0x1c] = 0                                 ; offset 28
  ##   flags = ps_env[52]
  ##   if (flags & 3) == 3 AND s1 != nil:               ; PS disabling path
  ##     flags = (flags & ~2) | 8
  ##     ps_env[52] = flags
  ##     wifi_hosal_pm_post_event(4, 0, &localStatus)
  ##     td_cfm_set_timer(s1[87], localStatus)
  ##     s2 = 1
  ##     goto L65
  ##   else:                                            ; .L64
  ##     ps_env[0] = 0
  ##     s2 = 0
  ##     ke_msg_send_basic(32, ps_env[1], 0)
  ##     if s1 != nil: goto L65
  ##     goto L66
  ##   L65:
  ##     if s1[91] != 0:
  ##       ke_env[28] |= 1; ke_env[32] = 1
  ##       ke_evt_set(0x100)
  ##     s1[196] = 0                                   ; blob always stores 0
  ##   L66:
  ##     if ps_env[52] & 0x10:
  ##       ps_env[52] &= ~0x10
  ##       ps_set_mode(ps_env[53], ps_env[1])
  ##   return s2
  let psBase = cast[uint](addr ps_env[0])
  var localStatus: uint8 = 0  # sp+12 in blob
  # Blob: mm_timer_clear(&ps_env + 12)
  mm_timer_clear(cast[pointer](psBase + 12))
  # ps_env[0x1c] (offset 28) = 0
  cast[ptr uint8](psBase + 0x1c)[] = 0

  let flags0 = cast[ptr uint8](psBase + 52)[]
  var result2: uint32 = 0  # s2 in blob

  if (flags0 and 3) == 3 and vifEntry != nil:
    # PS disable path: clear bit 1, set bit 3
    let newFlags = (flags0 and (not 2'u8)) or 8'u8
    cast[ptr uint8](psBase + 52)[] = newFlags
    # wifi_hosal_pm_post_event(4, 0, &localStatus)
    wifi_hosal_pm_post_event(4, 0, cast[pointer](addr localStatus))
    # td_cfm_set_timer(s1[87], localStatus)
    let vifIdxLocal = cast[ptr uint8](cast[uint](vifEntry) + 87)[]
    td_cfm_set_timer(vifIdxLocal, localStatus)
    result2 = 1
    # fall through to .L65
  else:
    # .L64: send basic message
    cast[ptr uint32](psBase)[] = 0
    let destTask = cast[ptr uint8](psBase + 1)[]
    # ke_msg_send_basic(32, ps_env[1], 0)
    ke_msg_send_basic(32'u16, destTask, 0)
    # Blob does not short-circuit the vifEntry==nil case with its own
    # ps_set_mode call — .L64 falls through to .L65 (which is a no-op
    # when vifEntry is NULL) and then reaches the single .L66 ps_set_mode
    # site. Previous Nim duplicated the ps_set_mode call here, producing
    # two call sites for the same code path. Letting control flow
    # through collapses them into one.

  # .L65 (reached from PS-disable path, or from .L64 if vifEntry != nil)
  if vifEntry != nil:
    let s1U = cast[uint](vifEntry)
    let flagByte = cast[ptr uint8](s1U + 91)[]
    # s1[196] = 0  (blob unconditionally)
    cast[ptr uint32](s1U + 196)[] = 0
    if flagByte != 0:
      let keU = cast[uint](addr ke_env[0])
      let oldKe = cast[ptr uint8](keU + 28)[]
      cast[ptr uint8](keU + 28)[] = oldKe or 1
      cast[ptr uint8](keU + 32)[] = 1
      ke_evt_set(0x100'u32)

  # .L66
  let flagsL66 = cast[ptr uint8](psBase + 52)[]
  if (flagsL66 and 0x10) != 0:
    cast[ptr uint8](psBase + 52)[] = flagsL66 and (not 0x10'u8)
    let modeArg  = cast[ptr uint8](psBase + 53)[]
    ps_set_mode(modeArg)
  return result2

proc ps_enable_cfm*(vifEntry: pointer, status: uint32) {.exportc, cdecl.} =
  ## Handle PS enable confirmation (114 bytes in blob).
  ## Blob flow:
  ##   if (ps_env[52] & 2) return;                       ; state guard
  ##   if (status & 0x800000) goto finalize;             ; hw_cfm branch
  ##   if (ps_check_tx_status_part0(vif, ps_enable_cfm) == 0) return
  ## finalize:
  ##   if (ps_env[8] == 0) return;
  ##   ps_env[8] -= 1;
  ##   mm_timer_clear(ps_env + 0x24);                     ; byte offset 36, NOT 12
  ##   if (ps_env[8] != 0) return;
  ##   ps_enable_cfm_handle(vif);                         ; tail call
  let psBase = cast[uint](addr ps_env[0])
  # State guard: if ps_env[52] & 2 set, abort (PS disable already pending)
  let psFlags = cast[ptr uint8](psBase + 52)[]
  if (psFlags and 2'u8) != 0:
    return
  # hw_cfm branch: if caller already confirmed TX (status bit 23 set), skip TX poll
  if (status and 0x00800000'u32) == 0:
    # Poll TX status via part.0 clone. Returns 1 when TX has settled, 0 to retry.
    var checkResult: uint32
    {.emit: """
extern unsigned int ps_check_tx_status_part0(void*, void*) __asm__("ps_check_tx_status.part.0");
""".}
    {.emit: [checkResult, " = ps_check_tx_status_part0(", vifEntry, ", (void*)", ps_enable_cfm, ");"].}
    if checkResult == 0:
      return
  # finalize path
  let cnt = cast[ptr uint8](psBase + 8)[]
  if cnt == 0:
    return
  cast[ptr uint8](psBase + 8)[] = cnt - 1
  # Clear TX-null timer at ps_env + 0x24 (byte offset 36, NOT 12)
  mm_timer_clear(cast[pointer](psBase + 0x24))
  if cast[ptr uint8](psBase + 8)[] != 0:
    return
  # Tail-call into handle
  ps_enable_cfm_handle(vifEntry)

proc ps_enable_cfm_handle*(vifEntry: pointer) {.exportc, cdecl, noinline.} =
  ## Finalize PS enable: update state, start timers.
  ## From blob (ps.o, 57 instrs): sets ps_env[29]=1 (PS active). If VIF has
  ## DTIM tracking and UAPSD enabled, starts UAPSD timer. Then checks
  ## ps_env[52] bits [2:0] for 5 (enable+confirm), clears bits, updates VIF.
  ## noinline: blob calls this from ps_dpsm_update, ps_tx_null_timer_handle,
  ## and ps_check_tx_status.
  {.emit: "__asm__ volatile(\"\" ::: \"memory\");".}
  let psBase = cast[uint](addr ps_env[0])
  # Set PS-active flag
  cast[ptr uint8](psBase + 29)[] = 1
  if vifEntry == nil: return
  # Check VIF DTIM tracking (offset 88) and UAPSD (offset 104)
  let dtim = cast[ptr uint8](cast[uint](vifEntry) + 88)[]
  if dtim != 0:
    let uapsd = cast[ptr uint8](cast[uint](vifEntry) + 104)[]
    if uapsd != 0:
      # Start UAPSD timer
      let macTime = macTimeNow()
      let period = cast[ptr uint32](psBase + 32)[]
      mm_timer_set(cast[pointer](psBase + 12), macTime + period)
      # Clear VIF PS-transition flag
      var vifFlags = cast[ptr uint32](cast[uint](vifEntry) + 4)[]
      vifFlags = vifFlags and not 0x08'u32
      cast[ptr uint32](cast[uint](vifEntry) + 4)[] = vifFlags
  # Check and finalize ps_env flags
  let flags = cast[ptr uint8](psBase + 52)[]
  if (flags and 0x05) == 5 and vifEntry != nil:
    # Clear enable bits, update VIF
    let newFlags = flags and not 0x0D'u8
    cast[ptr uint8](psBase + 52)[] = newFlags
    var vifFlags = cast[ptr uint32](cast[uint](vifEntry) + 4)[]
    vifFlags = vifFlags and not 0x42'u32
    cast[ptr uint32](cast[uint](vifEntry) + 4)[] = vifFlags
    # Set PS confirmed in VIF[196]
    cast[ptr uint32](cast[uint](vifEntry) + 196)[] = 1
  else:
    # Send PS mode confirmation
    let vifIdx = cast[ptr uint8](psBase + 1)[]
    cast[ptr uint8](psBase)[] = 1  # mark PS active
    ke_msg_send_basic(0x20'u16, vifIdx, 0)
    if vifEntry != nil:
      cast[ptr uint32](cast[uint](vifEntry) + 196)[] = 1

  # Blob .L94: check bit 4 of ps_env[52] for pending ps_set_mode
  let finalFlags = cast[ptr uint8](psBase + 52)[]
  if (finalFlags and 0x10) != 0:
    let clearedFlags = finalFlags and not 0x10'u8
    cast[ptr uint8](psBase + 52)[] = clearedFlags
    let psMode = cast[ptr uint8](psBase + 53)[]
    ps_set_mode(psMode)

proc ps_dpsm_update*(enable: uint32) {.exportc, cdecl.} =
  ## Update DPSM state (334b in blob, ps.o).
  ## Blob: check active count, set flags/state, update MAC HW power ctrl,
  ## iterate VIF list calling ps_check_vif/ps_set_vif_mode (enable) or
  ## ps_set_mode_with_callback (disable), tail-call ps_do_sleep on enable done.
  let psBase = cast[uint](addr ps_env[0])
  let cnt = cast[ptr uint8](psBase + 8)[]
  if cnt != 0:
    return  # transition in progress
  # Update flags and state bits
  let flags = cast[ptr uint8](psBase + 52)[]
  let envWord = cast[ptr uint32](psBase + 4)[]
  if enable != 0:
    cast[ptr uint8](psBase + 52)[] = flags or 0x02  # enable pending
    cast[ptr uint32](psBase + 4)[] = envWord or 0x08
  else:
    cast[ptr uint8](psBase + 52)[] = flags or 0x04  # disable pending
    cast[ptr uint32](psBase + 4)[] = envWord and not 0x08'u32
  # Update MAC HW power ctrl register at 0x24B0004C
  # Blob: read reg, clear bit 2, set ((enable^1)<<2)
  let hwBase = 0x24B00000'u
  var pmReg = volatileLoad(cast[ptr uint32](hwBase + 0x4C))
  pmReg = pmReg and not 0x04'u32  # clear bit 2
  pmReg = pmReg or (((enable xor 1) and 1) shl 2)  # set bit 2 if disabling
  volatileStore(cast[ptr uint32](hwBase + 0x4C), pmReg)
  # Clear prevent-sleep flag
  cast[ptr uint8](psBase + 53)[] = 0
  # Walk VIF linked list
  let vifMgmtBase = cast[uint](addr vif_mgmt_env[0])
  var vifPtr = cast[ptr pointer](vifMgmtBase)[]
  while vifPtr != nil:
    let vifAddr = cast[uint](vifPtr)
    let vifType = cast[ptr uint8](vifAddr + 86)[]
    if vifType == 0:  # skip if not idle (blob: bnez vif[86])
      vifPtr = cast[ptr pointer](vifAddr)[]
      continue
    let psCapable = cast[ptr uint8](vifAddr + 88)[]
    if psCapable == 0:  # skip if not PS capable
      vifPtr = cast[ptr pointer](vifAddr)[]
      continue
    # Call chan_is_on_channel to validate VIF is on channel
    let vifIdx = cast[ptr uint8](vifAddr + 87)[]
    let checkResult = chan_is_on_channel(cast[pointer](vifAddr))
    if not checkResult:
      vifPtr = cast[ptr pointer](vifAddr)[]
      continue
    # Increment active counter, clear PS state, load PS mode
    let c = cast[ptr uint8](psBase + 8)[]
    cast[ptr uint8](psBase + 8)[] = c + 1
    cast[ptr uint8](vifAddr + 95)[] = 0  # clear PS state
    let psMode = cast[ptr uint8](vifAddr + 96)[]
    if enable != 0:
      # Enable path: send null frame PM=1 (blob: txl_frame_send_null_frame)
      let staIdx = cast[ptr uint8](vifAddr + 96)[]
      discard txl_frame_send_null_frame(staIdx, cast[pointer](ps_enable_cfm), cast[uint32](vifAddr))
      let c2 = cast[ptr uint8](psBase + 8)[]
      cast[ptr uint8](psBase + 8)[] = c2 - 1
    else:
      # Disable path: send null frame PM=0 (blob: txl_frame_send_null_frame)
      let staIdx = cast[ptr uint8](vifAddr + 96)[]
      discard txl_frame_send_null_frame(staIdx, cast[pointer](ps_disable_cfm), cast[uint32](vifAddr))
      let result = cast[ptr uint8](psBase + 8)[]
      if result == c + 1:
        let c2 = cast[ptr uint8](psBase + 8)[]
        cast[ptr uint8](psBase + 8)[] = c2 - 1
      else:
        # Store current VIF for async completion
        cast[ptr pointer](psBase + 44)[] = vifPtr
        # Set timer: MAC_TIMER + timeout offset
        let macTime = volatileLoad(cast[ptr uint32](hwBase + 0x120))
        let timeout = cast[ptr uint32](psBase + 16)[]
        mm_timer_set(cast[pointer](psBase + 12), macTime + timeout)
    vifPtr = cast[ptr pointer](vifAddr)[]
  # Post-loop: check if all done
  let finalCnt = cast[ptr uint8](psBase + 8)[]
  if finalCnt != 0:
    return  # still pending
  if enable != 0:
    # Enable done: tail-call to sleep function
    ps_enable_cfm_handle(nil)
  else:
    # Disable done: notify
    discard ps_disable_cfm_handle(nil)

proc ps_send_pspoll*(vifEntry: pointer): uint8 {.exportc, cdecl, noinline.} =
  ## Send PS-Poll frame (206 bytes in blob, 84 instrs).
  ## noinline: blob calls this from ps_polling_frame (gap target).
  ## From blob (ps.o): reads sta_idx from vif[0x60]. Calls txl_frame_get(16)
  ## to allocate a 16-byte frame descriptor. Calls tpc_update_frame_tx_power.
  ## Builds PS-Poll 802.11 header: FC=0x00A4, Duration=AID|0xC000,
  ## Addr1=BSSID (from sta[4]), Addr2=own MAC (from vif[0x50]).
  ## Sets TX control flags (0x10000053), copies rate info from sta,
  ## calls txl_frame_push(txdesc, AC_VO=3). Returns 0 on success, 1 on fail.
  let vifAddr = cast[uint](vifEntry)
  let staIdx = cast[ptr uint8](vifAddr + 0x60)[]
  # Allocate frame descriptor for 16-byte PS-Poll
  let txdesc = txl_frame_get(16)
  if txdesc == nil:
    return 1  # Allocation failed
  # Update TX power
  tpc_update_frame_tx_power(vifEntry, txdesc)
  let txAddr = cast[uint](txdesc)
  # Get MAC header pointer from txdesc (offset 0x6c)
  let macHdr = cast[ptr pointer](txAddr + 0x6C)[]
  let hdrAddr = cast[uint](macHdr)
  # Build PS-Poll frame control (0x00A4)
  cast[ptr uint8](hdrAddr + 0x15C)[] = 0xA4'u8  # FC low: PS-Poll
  cast[ptr uint8](hdrAddr + 0x15D)[] = 0x00'u8  # FC high
  # Get STA info for AID and BSSID
  let staBase = cast[uint](addr sta_info_tab[0]) + staIdx.uint * STA_ENTRY_SIZE.uint
  let aid = cast[ptr uint16](staBase + 0x24)[]
  let aidWithBits = aid or 0xC000'u16  # Set bits 14-15 per 802.11 spec
  cast[ptr uint8](hdrAddr + 0x15E)[] = (aidWithBits and 0xFF).uint8  # Duration/AID low
  cast[ptr uint8](hdrAddr + 0x15F)[] = ((aidWithBits shr 8) and 0xFF).uint8  # Duration/AID high
  # Copy BSSID to Addr1 (6 bytes from sta[4])
  discard c_memcpy(cast[pointer](hdrAddr + 0x160), cast[pointer](staBase + 4), 6.csize_t)
  # Copy own MAC to Addr2 (6 bytes from vif[0x50])
  discard c_memcpy(cast[pointer](hdrAddr + 0x166), cast[pointer](vifAddr + 0x50), 6.csize_t)
  # Set TX control flags in SW descriptor
  let swDesc = cast[ptr pointer](txAddr + 0x70)[]
  let swAddr = cast[uint](swDesc)
  var ctrl = cast[ptr uint32](swAddr + 0x3C)[]
  ctrl = ctrl or 0x10000053'u32
  cast[ptr uint32](swAddr + 0x3C)[] = ctrl
  # Copy rate info from STA
  let rateIdx = cast[ptr uint8](staBase + 0x27)[]
  cast[ptr uint8](txAddr + 0x2F)[] = rateIdx
  let rateFmt = cast[ptr uint8](staBase + 0x28)[]
  cast[ptr uint8](txAddr + 0x31)[] = rateFmt
  # Push frame for transmission
  txl_frame_push(txdesc, 3)  # AC_VO = 3
  return 0

proc mac_recovery*(): uint32 {.exportc, cdecl.} =
  ## MAC recovery handler — blob arch_main.o (10 instrs):
  ##   assert_rec(.LC1 /* file */, .LC4 /* func */, 299); return 0
  ## Previous Nim issued a getLogFunc(4) direct log; blob uses assert_rec
  ## which is a distinct sink and is what the recovery-counter audit expects.
  assert_rec("arch_main.c", "arch_main.c", 299)
  return 0

{.emit: "__attribute__((noipa)) unsigned long bl_pwr_find(void*,unsigned long);".}
proc bl_pwr_find*(levels: pointer, count: uint32): uint32 {.exportc, cdecl.} =
  ## Find the index of the maximum value in a signed byte array.
  ## From blob (bl.o, 13 instrs): linear scan tracking running maximum.
  ## Returns index of the entry with the highest value (0 if count==0 or
  ## levels[0] is already the max).
  if count == 0:
    return 0
  let p = cast[ptr UncheckedArray[uint8]](levels)
  var refVal = p[0]  # running max (unsigned byte)
  var bestIdx = 0'u32
  let n = count - 1
  var i = 0'u32
  while i < n:
    let entry = cast[int8](p[i + 1])  # blob uses lb (signed load)
    i += 1
    i = i and 0xFF  # blob: zext.b
    if cast[int8](refVal) >= entry:  # blob: bge (signed compare)
      continue
    refVal = cast[uint8](entry) and 0xFF  # blob: zext.b on new max
    bestIdx = i
  return bestIdx

proc ble_rf_ops*(enable: uint32) {.exportc, cdecl.} =
  ## BLE RF operations toggle (34 bytes in blob, 9 instrs).
  ## From blob: if enable == 0, calls wifi_hosal_rf_turn_off();
  ## else calls wifi_hosal_rf_turn_on(). Returns 0.
  proc wifi_hosal_rf_turn_on() {.importc, cdecl.}
  proc wifi_hosal_rf_turn_off() {.importc, cdecl.}
  if enable == 0:
    wifi_hosal_rf_turn_off()
  else:
    wifi_hosal_rf_turn_on()

proc rfc_channel_ops*(channel: uint32) {.exportc, cdecl.} =
  ## RF channel operations (12 instrs in blob):
  ##   rf_init(0x2625a00)                     # a0 = packed config pointer
  ##   sm_set_channel_coex_connected()        # uses whatever a0 rf_init left
  ##   return 0
  rf_init(0x02625A00'u32)
  sm_set_channel_coex_connected(0'u8)

proc vif_mgmt_bcn_to_evt*(vifEntry: pointer) {.exportc, cdecl.} =
  ## Convert beacon reception to kernel event.
  ## From blob (vif_mgmt.o, 4 instrs): loads vifEntry[64], if non-nil
  ## tail-calls chan_bcn_to_evt(vifEntry). Otherwise returns.
  let chanCtxt = cast[ptr pointer](cast[uint](vifEntry) + 64)[]
  if chanCtxt != nil:
    chan_bcn_to_evt()

proc mm_ap_traffic_probe_cfm*(vifEntry: pointer, status: uint32) {.exportc, cdecl.} =
  ## AP traffic probe confirmation handler.
  ## From blob (mm.o, 14 instrs): checks status bit 23 (0x00800000). If set,
  ## resets probe counter to 10 and stores current MAC time at vifEntry+108.
  ## If not set, decrements probe counter (mm_env[8]); when it reaches 0,
  ## resets to 10 and tail-calls mm_send_connection_loss_ind(vifEntry, 22).
  if (status and 0x00800000'u32) != 0:
    mm_env[8] = 10  # reset counter at mm_env offset 32
    cast[ptr uint32](cast[uint](vifEntry) + 108)[] = macTimeNow()
  else:
    let cnt = mm_env[8]
    if cnt == 0:
      mm_env[8] = 10
      # Tail-call connection loss: blob passes vifEntry as a0, reason=22 as a1
      let vifIdx = cast[ptr uint8](cast[uint](vifEntry) + 87)[]
      mm_send_connection_loss_ind(vifIdx, 22)
    else:
      mm_env[8] = cnt - 1

proc td_timer_end*(tdEntry: pointer) {.exportc, cdecl.} =
  ## End traffic detection timer and update TD state (312 bytes in blob, 79 instrs).
  ## From blob (td.o): reads MAC timestamp, computes traffic direction flags from
  ## TX/RX counters vs threshold, calls notification on direction change, then
  ## resets counters and reschedules timer.
  ##
  ## Entry layout: [0]=timer_hdr, [16]=pending_tx, [24]=tx_count, [28]=rx_count,
  ##   [32]=tx_bytes, [36]=rx_bytes, [40]=vif_idx, [41]=prev_flags, [43]=active
  let tdAddr = cast[uint](tdEntry)
  let macTime = regRead(MACHW_TIMLO_REG)
  let active = cast[ptr uint8](tdAddr + 43)[]
  var schedResult: uint32 = 0

  if active != 0:
    # Read threshold from global config
    let threshBase = cast[uint](addr cfgElements[0])
    let threshold = cast[ptr uint32](threshBase)[]

    # Read TX/RX counters
    let txCount = cast[ptr uint32](tdAddr + 24)[]
    let rxCount = cast[ptr uint32](tdAddr + 28)[]

    # Compute direction flags using sltu comparison against threshold
    var dirFlags: uint32 = 0
    # bit 0: TX counter >= threshold (not less than)
    if txCount >= threshold:
      dirFlags = dirFlags or 1
    # bit 1: RX counter >= threshold
    if rxCount >= threshold:
      dirFlags = dirFlags or 2

    # Check pending TX at offset 16
    let pendingTx = cast[ptr uint32](tdAddr + 16)[]
    var bidir: uint32 = 0
    if pendingTx != 0:
      dirFlags = dirFlags or 8
      bidir = 1

    # Check TX/RX byte counters at offsets 32,36 against threshold
    let txBytes = cast[ptr uint32](tdAddr + 32)[]
    if txBytes >= threshold:
      dirFlags = dirFlags or 4
    let rxBytes = cast[ptr uint32](tdAddr + 36)[]
    if rxBytes >= threshold:
      dirFlags = dirFlags or 8

    # Call wifi_hosal_pm_post_event (blob: direct call at 0x60)
    wifi_hosal_pm_post_event(4, 0, addr schedResult)

    if schedResult == 0:
      # Check for direction change
      let prevFlags = cast[ptr uint8](tdAddr + 41)[]
      let changed = (prevFlags.uint32 xor dirFlags) and 0x0C
      if changed != 0:
        # Direction changed: call ps_traffic_status_update
        let dirBits = dirFlags and 0x0C
        # Select direction string based on bits
        let vifIdx = cast[ptr uint8](tdAddr + 40)[]
        # Log via platform ops
        let blOps2 = cast[uint](addr g_bl_ops_funcs)
        let logFnPtr = cast[ptr pointer](blOps2 + 204)[]
        if logFnPtr != nil:
          let logFn = cast[PlatformLogFunc](logFnPtr)
          logFn(1, 0, nil, 200)
        # Notify traffic status change
        ps_traffic_status_update(vifIdx, dirBits.uint32)

    # Store new flags
    cast[ptr uint8](tdAddr + 41)[] = dirFlags.uint8

  # Reset all counters (always, even if not active)
  let vifIdx = cast[ptr uint8](tdAddr + 40)[]
  cast[ptr uint32](tdAddr + 24)[] = 0
  cast[ptr uint32](tdAddr + 28)[] = 0
  cast[ptr uint32](tdAddr + 32)[] = 0
  cast[ptr uint32](tdAddr + 36)[] = 0

  # Compute VIF active status and reschedule timer
  let vifBase = cast[uint](addr vif_info_tab[0]) + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let vifActive = cast[ptr uint32](vifBase + 64)[]
  let vifConnected = cast[ptr uint32](vifBase + 64)[]
  # Check if connection is active (blob: compares vif[64] with a global)
  let isActive = (vifConnected != 0).uint8
  cast[ptr uint8](tdAddr + 43)[] = isActive
  if isActive == 0:
    return
  # Reschedule: timer target = macTime + td_period (from config)
  let tdConfigBase = cast[uint](addr cfgElements[0])
  let tdPeriod = cast[ptr uint32](tdConfigBase + 4)[]
  let timerTarget = macTime + tdPeriod
  mm_timer_set(tdEntry, timerTarget)

proc phyif_utils_decode*(rxvec: pointer, rssi: ptr int8): uint32 {.exportc, cdecl.} =
  ## Decode PHY RSSI from RX vector (128 bytes in blob, 36 instrs).
  ## From blob: reads word1(a0[4]) and byte19(a0[19]). Extracts format bits.
  ## Fast path (fmtVal > 1): combines bytes 19+20 as (byte20<<8)|byte19,
  ##   applies custom PHY insn, divides by 122, converts int→float→int.
  ## Slow path (fmtVal <= 1): reads word0, extracts MCS field, checks > 3,
  ##   calls 3 external functions (__floatsisf, __divsf3, __fixsfsi) for
  ##   float-based RSSI computation.
  ## Returns 0 on success, stores result byte via rssi ptr.
  let rxAddr = cast[uint](rxvec)
  let word0 = cast[ptr uint32](rxAddr)[]
  let word1 = cast[ptr uint32](rxAddr + 4)[]
  let byte19 = cast[ptr uint8](rxAddr + 19)[]
  # Extract format field from word1 via custom PHY insn (approximated)
  let fmtVal = word1 and 0x03'u32
  if fmtVal > 1:
    # Fast path: RSSI from combined bytes 19-20, divide by 122
    let byte20 = cast[ptr uint8](rxAddr + 20)[]
    let rawVal = (byte20.uint32 shl 8) or byte19.uint32
    let scaled = rawVal.int32 div 122
    rssi[] = cast[int8](scaled and 0xFF)
  else:
    # Slow path: word0-based computation with float math
    let mcsField = (word0 shr 2) and 0x0F'u32  # extract from custom insn
    if mcsField > 3:
      # Use bytes 19-20 path anyway (fallback)
      let byte20 = cast[ptr uint8](rxAddr + 20)[]
      let rawVal = (byte20.uint32 shl 8) or byte19.uint32
      let scaled = rawVal.int32 div 122
      rssi[] = cast[int8](scaled and 0xFF)
    else:
      # Float-based RSSI computation from MCS field.
      # Blob: __floatsidf(-mcsField) → __muldf3(*, 0.7) → __fixdfsi
      # Use cint (int32) so GCC picks __fixdfsi, matching the blob.
      let negVal: cint = -(mcsField.cint and 0xFF)
      var scaledC: cint = 0
      {.emit: [scaledC, " = (int)((double)", negVal, " * 0.7);"].}
      rssi[] = cast[int8](scaledC and 0xFF)
  return 0

# ###########################################################################
#                  IPC Embedded (ipc_emb_*)
# ###########################################################################

proc ipc_emb_msg_push*(msgDescPtr: pointer) {.exportc, cdecl.} =
  ## Push a message descriptor to the IPC shared-memory ring for host pickup.
  ## Called from ke_msg_send for API/external task messages.
  ## From blob: the argument is &hdr.id (= param - 8), pointing to the
  ## {id, destId, srcId, paramLen} portion of the message header.
  ## TODO: implement IPC shared-ring push (relocation target unknown in archive)
  discard

proc ipc_emb_init*() {.exportc, cdecl.} =
  ## Initialize IPC embedded interface.
  ## From disassembly: allocates IPC env via keAllocFunc, stores result,
  ## memset(ipc_emb_env, 0, 20), stores the host TX pending list pointer at
  ## offset 12 and the host TX confirmation list pointer at offset 16.
  ## Then verifies IPC magic 0x49504332 at IPC_EMB_MAGIC_REG (asserts on mismatch),
  ## clears status registers, and configures IPC control register fields via
  ## read-modify-write sequences. Finally writes 0x1F03 to timeout register.

  # Allocate IPC environment via platform hook at g_bl_ops_funcs[0x44]
  # (zero-arg function returning a fresh IPC env block).
  let ipcAllocFn = cast[proc(): pointer {.cdecl.}](
    cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 0x44)[])
  ipcEmbEnv = ipcAllocFn()

  # Clear the 20-byte ipc_emb_env struct
  discard c_memset(addr ipcEmbEnvStruct[0], 0, 20.csize_t)

  # Stash shared-memory ring-cursor pointers at offsets 12 and 16 of
  # ipc_emb_env. Blob writes &ipc_shared_env[0x24cc] and [0x24d4] here —
  # two cursor slots near the end of the shared region used by TX/msg rings.
  let base = cast[uint](addr ipcEmbEnvStruct[0])
  let sharedBase = cast[uint](addr ipcSharedEnv[0])
  cast[ptr pointer](base + 12)[] = cast[pointer](sharedBase + 0x24cc'u)
  cast[ptr pointer](base + 16)[] = cast[pointer](sharedBase + 0x24d4'u)

  # Verify IPC magic value at 0x24800140
  let magic = regRead(IPC_EMB_MAGIC_REG)
  if magic != IPC_MAGIC_VALUE:
    assert_err("ipc_emb.c", "ipc_emb.c", 183)

  # Clear raw status and ack registers (0x24800114, 0x24800118)
  regWrite(IPC_EMB_RAW_STATUS, 0)
  regWrite(IPC_EMB_ACK, 0)

  # Configure IPC control register at 0x24800114 with read-modify-write
  # sequence matching blob ipc_emb_init (10 separate RMW writes, each
  # targeting a distinct 2-bit field).
  let cfgReg = IPC_EMB_RAW_STATUS  # 0x24800114
  var cfg: uint32

  # [1:0] clear
  cfg = regRead(cfgReg)
  cfg = cfg and not 0x3'u32
  regWrite(cfgReg, cfg)

  # [3:2] = 01 (clear then set bit 2)
  cfg = regRead(cfgReg)
  cfg = (cfg and not 0xC'u32) or 0x4'u32
  regWrite(cfgReg, cfg)

  # [9:8] = 10 (set bit 9)
  cfg = regRead(cfgReg)
  cfg = (cfg and not 0x300'u32) or 0x200'u32
  regWrite(cfgReg, cfg)

  # [11:10] = 10 (set bit 11)
  cfg = regRead(cfgReg)
  cfg = (cfg and not 0xC00'u32) or 0x800'u32
  regWrite(cfgReg, cfg)

  # [13:12] = 10 (set bit 13). NB: mask is 0x3000, NOT 0xF000 — blob
  # preserves bits [15:14] (an earlier bug here cleared too much).
  cfg = regRead(cfgReg)
  cfg = (cfg and not 0x3000'u32) or 0x2000'u32
  regWrite(cfgReg, cfg)

  # [17:16] = 11
  cfg = regRead(cfgReg)
  cfg = (cfg and not 0x30000'u32) or 0x30000'u32
  regWrite(cfgReg, cfg)

  # [19:18] = 11
  cfg = regRead(cfgReg)
  cfg = (cfg and not 0xC0000'u32) or 0xC0000'u32
  regWrite(cfgReg, cfg)

  # [21:20] = 11
  cfg = regRead(cfgReg)
  cfg = (cfg and not 0x300000'u32) or 0x300000'u32
  regWrite(cfgReg, cfg)

  # [23:22] = 11
  cfg = regRead(cfgReg)
  cfg = (cfg and not 0xC00000'u32) or 0xC00000'u32
  regWrite(cfgReg, cfg)

  # [25:24] = 11
  cfg = regRead(cfgReg)
  cfg = (cfg and not 0x3000000'u32) or 0x3000000'u32
  regWrite(cfgReg, cfg)

  # Write timeout value 0x1F03 to IPC_EMB_UNMASK_SET (0x2480010C)
  regWrite(IPC_EMB_UNMASK_SET, 0x1F03'u32)

proc ipc_emb_notify*(msg: uint32) {.exportc, cdecl.} =
  ## Notify host of an event via IPC (21 instrs). Blob asserts `ipcEmbEnv`
  ## non-nil, then tail-calls `g_bl_ops_funcs[0x4c](env)`. Nim previously
  ## used `keNotifyFunc` — a never-populated Nim-only global.
  let env = ipcEmbEnv
  if env == nil:
    assert_err("ipc_emb.c", "ipc_emb.c", 146)
    return
  let notifyFn = cast[proc(envArg: pointer) {.cdecl.}](
    cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 0x4C)[])
  notifyFn(env)

proc ipc_emb_wait*() {.exportc, cdecl.} =
  ## Wait for IPC event from host. Blob: calls g_bl_ops_funcs[0x50] (wait fn)
  ## with (&ipcEmbEnv, -1), then `ipc_emb_counter++`.
  let waitFn = cast[proc(env: pointer, timeout: int32): int32 {.cdecl.}](
    cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 0x50)[])
  if waitFn != nil:
    discard waitFn(ipcEmbEnv, -1)
  inc ipc_emb_counter

proc ipc_emb_tx_flow_off*(ac: uint8) {.exportc, cdecl.} =
  ## Stop TX flow for an AC (notify host to stop sending).
  ## Blob:
  ##   *(u32*)(0x24800000+0x110) = 0x1F00   ; IPC_EMB_UNMASK_CLR = TX mask
  ##   tail-call ke_evt_clear(0x3E00)       ; flow-off event
  ## Prior Nim bug: called ke_evt_set (would fire the event continuously).
  regWrite(IPC_EMB_UNMASK_CLR, IPC_IRQ_TX_MASK)
  ke_evt_clear(0x3E00'u32)

proc ipc_emb_tx_flow_on*(ac: uint8) {.exportc, cdecl.} =
  ## Resume TX flow for an AC.
  regWrite(IPC_EMB_UNMASK_SET, IPC_IRQ_TX_MASK)

proc ipc_emb_tx_irq*() {.exportc, cdecl.} =
  ## Handle TX IPC interrupt.
  let status = regRead(IPC_EMB_STATUS2)
  let txBits = status and IPC_IRQ_TX_MASK
  if txBits != 0:
    ke_evt_set(txBits shl 1)
    # Acknowledge
    regWrite(IPC_EMB_UNMASK_CLR, txBits)
    regWrite(IPC_EMB_ACK, txBits)

proc ipc_emb_msg_handler*() {.exportc, cdecl.} =
  ## IPC message handler callback (stored in ipc_emb_env[3] during ipc_emb_init).
  ## Processes incoming messages from host via IPC shared memory.
  discard

proc ipc_emb_tx_evt*(ac: uint32) {.exportc, cdecl.} =
  ## Process TX IPC event for a specific AC (288 bytes in blob, 97 instrs).
  ## From blob: extracts AC index from custom insn on ac, validates non-zero
  ## with debug log. Calls txl_cntrl_env_get(ac). Iterates descriptor list
  ## from ipc_emb_env[12], for each: checks BCN flag (bit 13) and flow control.
  ## Sets up DMA pointers, clears status fields, inits confirm list, marks active.
  ## Advances list. On empty: acks IPC. On flow control: tail-calls backup handler.
  let ipcEnvBase = cast[uint](addr ipcEmbEnvStruct[0])
  # Blob: custom insn extracts AC index, then log if non-zero
  if ac != 0:
    let blOpsBase = cast[uint](addr g_bl_ops_funcs)
    let logFn = cast[ptr pointer](blOpsBase + 0xCC)[]
    if logFn != nil:
      cast[proc(a0, a1: uint32, file: pointer, line: uint32,
                file2: pointer, val: uint32) {.cdecl.}](logFn)(
        2, 0, nil, 290, nil, ac)
  # Event bits for host TX AC0..AC4 are 0x200..0x2000. The handler table passes
  # the AC number; blob expands it to the event mask before clearing/re-arming.
  let eventMask = 0x200'u32 shl ac
  ke_evt_clear(eventMask)
  # Load descriptor list and BCN flag
  let isBcn = (eventMask and 0x2000'u32) != 0
  # Deref list head -> first descriptor
  let listHeadPtr = cast[ptr pointer](ipcEnvBase + 12)[]
  var descPtr = cast[ptr pointer](cast[uint](listHeadPtr))[]
  when defined(bl808WifiNimFw):
    nimFwTrace2U32("[WIFI-NIMFW] ipc_tx_evt ", ac, cast[uint32](cast[uint](descPtr)))
  while descPtr != nil:
    let descAddr = cast[uint](descPtr)
    when defined(bl808WifiNimFw):
      let txDescU = descAddr + 12
      let ethTypeTrace = cast[ptr uint16](txDescU + 32)[]
      let pktLenTrace = cast[ptr uint16](txDescU + 12)[]
      let traceIpc = nimFwDbgIpcTxTraceCount < 16'u32 or
        ethTypeTrace == 0x8E88'u16 or ethTypeTrace == 0x888E'u16
      if traceIpc:
        let tidTrace = cast[ptr uint8](txDescU + 46)[].uint32
        let vifTrace = cast[ptr uint8](txDescU + 47)[].uint32
        let staTrace = cast[ptr uint8](txDescU + HostTxStaInfoIdxOff)[].uint32
        nimFwTrace2U32("[WIFI-NIMFW] ipc_txd ",
                       ethTypeTrace.uint32 or (pktLenTrace.uint32 shl 16),
                       tidTrace or (vifTrace shl 8) or (staTrace shl 16))
        nimFwTrace2U32("[WIFI-NIMFW] ipc_txd_buf ",
                       cast[ptr uint32](txDescU + 52)[],
                       cast[ptr uint32](txDescU + 68)[])
        inc nimFwDbgIpcTxTraceCount
    # Flow control check for non-BCN queues (blob: .L21 at 0xa2)
    if not isBcn:
      let keEvtFld = cast[ptr uint32](cast[uint](addr keEvtField))[]
      if (keEvtFld and 0x02102000'u32) != 0:
        # Flow control active: re-arm event and return (blob: tail-call ke_evt_set)
        ke_evt_set(eventMask)
        return
    # Write IPC TX status acknowledgement (blob: sw s7,264(s6) at 0xd0)
    volatileStore(cast[ptr uint32](0x24800108'u), 256'u32)
    # Set up DMA descriptor chain fields (blob at 0xd4-0xe2)
    cast[ptr uint32](descAddr + 128)[] = cast[uint32](descAddr + 200)  # agg desc ptr
    cast[ptr uint32](descAddr + 124)[] = cast[uint32](descAddr + 128)  # first desc ptr
    # Clear status fields (blob at 0xe2-0xf6)
    cast[ptr uint32](descAddr + 100)[] = 0    # TX status
    cast[ptr uint32](descAddr + 116)[] = 0    # TX timestamp
    cast[ptr uint32](descAddr + 216)[] = 0    # cfm status
    cast[ptr uint32](descAddr + 172)[] = 0    # retry count
    cast[ptr uint32](descAddr + 176)[] = 0    # lifetime
    cast[ptr uint32](descAddr + 180)[] = 0    # flags
    # CRITICAL: Push descriptor to TX queue via txu_cntrl_push (blob at 0x100).
    # The blob explicitly loads a1=0 before this call; txu_cntrl_push reads a1
    # as the access-category argument even though the C ABI only exposes a0.
    let txParam = cast[pointer](descAddr + 12)
    {.emit: ["asm volatile(\"mv a1, zero\" ::: \"a1\", \"memory\");"].}
    txu_cntrl_push(txParam)
    # Mark descriptor as active (blob: sw s8,8(s0) where s8=1)
    cast[ptr uint32](descAddr + 8)[] = 1
    # Pop from IPC list (blob: utils_list_pop_front at 0x110)
    let listPtr = cast[ptr pointer](ipcEnvBase + 12)[]
    discard utils_list_pop_front(cast[ptr CoList](listPtr))
    # Reload and loop
    let listReload = cast[ptr pointer](ipcEnvBase + 12)[]
    descPtr = cast[ptr pointer](cast[uint](listReload))[]
  # No more descriptors: write 256 to IPC completion register (blob at 0x86)
  volatileStore(cast[ptr uint32](0x2480010C'u), 256'u32)

proc ipc_emb_cfmback_irq*() {.exportc, cdecl.} =
  ## Handle CFM (confirmation) back IPC interrupt.
  ## From disassembly (29 instrs): reads IPC_EMB_STATUS2 (0x11C), checks bit 5
  ## (RX cfm) and bit 4 (TX cfm). For each set bit, writes to UNMASK_CLR
  ## (0x110) and ACK (0x108), then signals the appropriate kernel event.
  let status = regRead(IPC_EMB_STATUS2)
  if (status and 0x20) != 0:
    # RX confirmation back: write 32 to UNMASK_CLR then ACK
    regWrite(IPC_EMB_UNMASK_CLR, 32)
    regWrite(IPC_REG_BASE + 0x108'u, 32)  # blob: sw a4, 0x108(base)
    ke_evt_set(0x00100000'u32)
  if (status and 0x10) != 0:
    # TX confirmation back: write 16 to UNMASK_CLR then ACK
    regWrite(IPC_EMB_UNMASK_CLR, 16)
    regWrite(IPC_REG_BASE + 0x108'u, 16)
    ke_evt_set(0x00200000'u32)

proc ipc_emb_hostrxdesc_check*(): bool {.exportc, cdecl.} =
  ## Check if host has provided RX descriptors.
  return true

proc ipc_emb_msg_irq*() {.exportc, cdecl.} =
  ## Handle message IPC interrupt (host -> emb).
  ## From disassembly (16 instrs): reads IPC_EMB_STATUS2 (offset 0x11C), checks
  ## bit 1 (msg pending). If set, calls ke_evt_set(0x10000000) to schedule
  ## message processing, then writes 2 to offset 0x110 to acknowledge.
  let status = regRead(IPC_EMB_STATUS2)
  if (status and 2) != 0:
    ke_evt_set(0x10000000'u32)
    regWrite(IPC_EMB_UNMASK_CLR, 2)  # blob: sw 2, 0x110(base)

proc ipc_emb_msg_evt*() {.exportc, cdecl.} =
  ## Process IPC message event. Blob semantics (from ipc_emb_msg_evt disassembly,
  ## 101 instrs). Host writes the message into `ipc_shared_env` (offsets
  ## 4=msgId, 6=msgDst, 8=paramLen, 12+=payload) then asserts IPC_MSG_BIT
  ## in the status register. This embedded-side handler drains all pending
  ## messages: for each, allocates a ke_msg of size (paramLen+12) via the
  ## platform allocator at g_bl_ops_funcs[184], copies the metadata+payload
  ## into it, increments the per-message counter, validates the dest task id,
  ## signals the MACHW event, and dispatches via ke_msg_send.
  const
    IPC_MSG_BIT = 2'u32  # bit 1 in IPC status for messages
  let sharedBase = cast[uint](addr ipcSharedEnv[0])
  let envBase = cast[uint](addr ipcEmbEnvStruct[0])
  var ipcStatus = regRead(0x24800104'u)
  while true:
    # No more messages: clear the kernel event, re-enable MSG IRQ, return.
    # Blob calls ke_evt_clear only when exiting, not at entry.
    if (ipcStatus and IPC_MSG_BIT) == 0:
      ke_evt_clear(0x10000000'u32)
      regWrite(IPC_EMB_UNMASK_SET, IPC_MSG_BIT)
      return
    nimFwTrace("[WIFI-NIMFW] ipc_emb_msg_evt msg")
    # Ack the msg bit (0x24800108) before processing.
    regWrite(0x24800108'u, IPC_MSG_BIT)
    # Read message metadata directly from ipc_shared_env (NOT via a pointer).
    let msgId = cast[ptr uint16](sharedBase + 4)[]
    let msgDst = cast[ptr uint8](sharedBase + 6)[]
    let msgParamLen = cast[ptr uint32](sharedBase + 8)[]
    # Platform allocator at g_bl_ops_funcs[184]: takes total byte count
    # (paramLen + 12 for the ke_msg_hdr prefix), returns the new header.
    # Blob: `lw a5, 184(s6); addi a0, a0, 12; jalr a5` with a0 = paramLen.
    let allocFn = cast[proc(sz: uint32): pointer {.cdecl.}](
      cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 184)[])
    let hdrRaw = allocFn(msgParamLen + 12)
    if hdrRaw == nil:
      assert_err("ipc_emb.c", "ipc_emb.c", 0x1E3)
    # Fill the newly-allocated header fields: link ptr = 0, msgId, msgDst,
    # srcId = 9 (TASK_API), paramLen.
    cast[ptr uint32](hdrRaw)[] = 0'u32
    cast[ptr uint16](cast[uint](hdrRaw) + 4)[] = msgId
    cast[ptr uint8](cast[uint](hdrRaw) + 6)[] = msgDst
    cast[ptr uint8](cast[uint](hdrRaw) + 7)[] = 9
    cast[ptr uint32](cast[uint](hdrRaw) + 8)[] = msgParamLen
    # Copy payload word-by-word from ipc_shared_env+12 into hdr+12.
    var cursor: uint32 = 12
    while cursor - 12 < msgParamLen:
      let srcWord = cast[ptr uint32](sharedBase + cursor.uint)[]
      cast[ptr uint32](cast[uint](hdrRaw) + cursor.uint)[] = srcWord
      cursor += 4
    # Advance per-message counter (stored at ipc_emb_env[0]) and stamp it
    # into the srcId-adjacent slot at ipc_shared_env[7].
    let counter = cast[ptr uint8](envBase)[]
    cast[ptr uint8](sharedBase + 7)[] = counter
    cast[ptr uint8](envBase)[] = counter + 1
    # Validate destination task id (blob: two chained assertions; msgDst
    # must be in [0, 8]; > 10 asserts at line 127, > 8 asserts at line 503).
    let dstCheck = cast[ptr uint8](cast[uint](hdrRaw) + 6)[]
    if dstCheck > 10:
      assert_err("ipc_emb.c", "ipc_emb.c", 0x7F)
    if dstCheck > 8:
      assert_err("ipc_emb.c", "ipc_emb.c", 0x1F7)
    # Signal the MACHW event (write 4 to 0x24800100) then dispatch.
    regWrite(0x24800100'u, 4'u32)
    let payloadPtr = cast[pointer](cast[uint](hdrRaw) + 12)
    ke_msg_send(payloadPtr)
    nimFwTrace("[WIFI-NIMFW] ipc_emb_msg_evt dispatched")
    # Re-read IPC status for next iteration (blob: `lw a5, 260(s2); j .L49`).
    ipcStatus = regRead(0x24800104'u)

proc ipc_emb_radar_event_ind*() {.exportc, cdecl.} =
  ## Handle radar event indication.
  ## From blob (4 instrs): writes 64 (0x40) to IPC_EMB_STATUS_REG (0x24800100).
  volatileStore(cast[ptr uint32](IPC_EMB_STATUS_REG), 64'u32)

proc ipc_emb_txcfm*(desc: pointer) {.exportc, cdecl.} =
  ## Handle TX confirmation from IPC.
  ## From blob (5 instrs): a1 = desc - 12, loads ipc_emb_env[16] into a0,
  ## tail-calls utils_list_push_back(host_tx_cfm_list, desc-12). The element is
  ## the host wrapper node, not a lower-MAC txl_cfm_env descriptor.
  let elem = cast[ptr CoListHdr](cast[uint](desc) - 12)
  let ipcEnvBase = cast[uint](addr ipcEmbEnvStruct[0])
  let listPtr = cast[ptr pointer](ipcEnvBase + 16)[]
  utils_list_push_back(cast[ptr CoList](listPtr), elem)

proc ipc_emb_txcfm_ind*(acBit: uint32 = 0) {.exportc, cdecl, noinline.} =
  ## TX confirmation indication to host.
  ## From blob (4 instrs): slli a0,a0,7; writes a0 to IPC_EMB_STATUS_REG (0x24800100); ret.
  ## acBit is shifted left 7 to form the IPC TX confirm bit, then written to status reg.
  let val = acBit shl 7
  volatileStore(cast[ptr uint32](IPC_EMB_STATUS_REG), val)

proc ipc_emb_prim_tbtt_ind*() {.exportc, cdecl.} =
  ## Primary TBTT indication to host — 4 instrs in blob:
  ##   lui a5, 0x24800; li a4, 16; sw a4, 256(a5); ret
  ## i.e. a bare `*(u32*)0x24800100 = 0x10`. Previous Nim routed through
  ## `ipc_emb_notify(IPC_IRQ_TBTT)` which dispatches to a platform callback
  ## — completely different behaviour (callback instead of HW register).
  volatileStore(cast[ptr uint32](IPC_EMB_STATUS_REG), 16'u32)

proc ipc_emb_sec_tbtt_ind*() {.exportc, cdecl.} =
  ## Secondary TBTT indication to host.
  ## From blob (4 instrs): writes 32 (0x20) to IPC_EMB_STATUS_REG (0x24800100); ret.
  volatileStore(cast[ptr uint32](IPC_EMB_STATUS_REG), 32'u32)

proc ipc_emb_dump*() {.exportc, cdecl, noinline.} =
  ## Dump IPC state for debugging.
  ## noinline + asm barrier: blob calls this as a real function from
  ## bl_fw_statistic_dump; without the barrier GCC elides the call of an
  ## empty, side-effect-free proc.
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}

# ###########################################################################
#                  PLATFORM INTEGRATION (bl_*)
# ###########################################################################

proc bl_supplicant_init() {.importc: "bl_supplicant_init", cdecl.}
  ## External: initializes WPA supplicant layer.

proc bl_init*() {.exportc, cdecl.} =
  ## Initialize platform layer (60 bytes in blob).
  ## From blob: stores fw_nap_chain addr to fw_nap_chain_ptr (.LANCHOR1),
  ## clears bl_env[1], then calls me_init → mm_init → ke_init → bl_supplicant_init.
  fw_nap_chain_ptr = cast[pointer](addr fw_nap_chain[0])
  bl_env[1] = 0
  nimFwTrace("[WIFI-NIMFW] me_init begin")
  me_init()
  nimFwTrace("[WIFI-NIMFW] me_init done")
  nimFwTrace("[WIFI-NIMFW] mm_init begin")
  mm_init()
  nimFwTrace("[WIFI-NIMFW] mm_init done")
  nimFwTrace("[WIFI-NIMFW] ke_init begin")
  ke_init()
  nimFwTrace("[WIFI-NIMFW] ke_init done")
  nimFwTrace("[WIFI-NIMFW] bl_supplicant_init begin")
  bl_supplicant_init()
  nimFwTrace("[WIFI-NIMFW] bl_supplicant_init done")

proc bl_reset_evt*() {.exportc, cdecl.} =
  ## Handle reset event. Blob sequence inside IRQ-disabled critical section:
  ##   ke_evt_clear(0x80000000)
  ##   hal_machw_reset()
  ##   rxl_reset(); txl_reset(); mm_reset()
  ##   vif_mgmt_reset()
  ##   ke_evt_clear(0x04000000)
  ## Restore mstatus.MIE only if it was set on entry.
  let saved = irqSave()
  ke_evt_clear(0x80000000'u32)
  hal_machw_reset()
  rxl_reset()
  txl_reset()
  mm_reset()
  vif_mgmt_reset()
  ke_evt_clear(0x04000000'u32)
  irqRestore(saved)

proc bl_irq_handler*() {.exportc, cdecl.} =
  ## Main WiFi interrupt handler. Blob sequence:
  ##   ipc_host_disable_irq_e2a()
  ##   ke_evt_set(0x80)            # IPC_EMB event bit
  ##   ipc_emb_notify()            # tail call
  ipc_host_disable_irq_e2a()
  ke_evt_set(0x80'u32)
  ipc_emb_notify(0'u32)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void bl_sleep_schedule(void);".}
proc bl_sleep_schedule*() {.exportc, cdecl.} =
  ## Schedule sleep check (68 instrs in blob).
  ## Blob calls: wifi_hosal_pm_state_run, chan_is_on_channel,
  ## wifi_hosal_pm_post_event (4 instances). Walks vif_mgmt_env+8 list.
  ##
  ## Flow:
  ##   1. wifi_hosal_pm_state_run() -> if nonzero: clear napScheduleState, s0=0
  ##   2. If zero: check ps_env[0] flag byte, walk vif_mgmt_env+8 list
  ##      calling chan_is_on_channel per VIF. If any is on-channel with next!=nil,
  ##      skip sleep. If all VIFs off-channel, s0=1.
  ##   3. Compare napScheduleState with s0. If same, exit.
  ##   4. If s0!=0 (sleep): wifi_hosal_pm_post_event(1,0,&result),
  ##      if result==0: pm_post_event(1,1,0), store state
  ##      if result!=0: pm_post_event(2,0,&result), exit
  ##   5. If s0==0 (wake): pm_post_event(2,1,0) then pm_post_event(2,2,0), store state
  let pmState = wifi_hosal_pm_state_run()
  var newState: uint32

  if pmState != 0:
    # Can sleep: clear state
    napScheduleState = 0
    newState = 0
  else:
    newState = 0  # default: stay awake (s0 = a0 = 0)
    # Check ps_env[0] flag byte
    let psFlag = cast[ptr uint8](addr ps_env[0])[]
    if psFlag != 0:
      # Check vif_mgmt_env+8 linked list for next ptr (offset 4)
      let envBase = cast[uint](addr vif_mgmt_env[0])
      let firstNode = cast[ptr pointer](envBase + 4)[]
      if firstNode == nil:
        # Walk VIF list (vif_mgmt_env+8) calling chan_is_on_channel per node
        var node = cast[ptr pointer](envBase + 8)[]
        while node != nil:
          let nodeU = cast[uint](node)
          if chan_is_on_channel(cast[pointer](nodeU)):
            # VIF is on channel - check if it has a next pointer
            let nextPtr = cast[ptr pointer](nodeU + 4)[]
            if nextPtr != nil:
              break  # on-channel VIF with pending work blocks sleep
          node = cast[ptr pointer](nodeU)[]  # next = node[0]
        if node == nil:
          newState = 1  # all VIFs checked, none blocking -> can sleep

  # Compare with current state (.L65)
  if napScheduleState == newState:
    return

  if newState != 0:
    # Transitioning to sleep: pm_post_event(1, 0, &result)
    var result: uint32 = 0
    wifi_hosal_pm_post_event(1, 0, addr result)
    if result == 0:
      # Sleep allowed: pm_post_event(1, 1, 0) then store state
      wifi_hosal_pm_post_event(1, 1, nil)
    else:
      # Sleep denied: pm_post_event(2, 0, &result) then exit
      wifi_hosal_pm_post_event(2, 0, addr result)
      return
  else:
    # Transitioning to awake (.L72): pm_post_event(2, 1, 0) then (2, 2, 0)
    wifi_hosal_pm_post_event(2, 1, nil)
    wifi_hosal_pm_post_event(2, 2, nil)

  napScheduleState = newState

proc bl_nap_calculate*(): uint32 {.exportc, cdecl.} =
  ## Calculate nap duration.
  ## From blob (25 instrs):
  ##   Reads the active timer bitmask from MACHW_INTC_IRQ_STAT_REG (0x44B0808C).
  ##   For each of up to 9 timer slots, if the corresponding bit is set:
  ##     1. Read absolute timer target for that slot (from MACHW_BASE + 0x128 region)
  ##     2. Read current MAC timestamp from MACHW_TIMLO_REG (0x44B00120)
  ##     3. Compute remaining = target - current
  ##     4. Track minimum remaining time across all active timers
  ##   Returns the minimum remaining nap duration, or 0xFFFFFFFF if no timers active.
  let activeMask = regRead(MACHW_INTC_BASE + 0x08C'u)  # Active timer bitmask
  var minRemaining: uint32 = 0xFFFFFFFF'u32

  for i in 0'u32 ..< 9'u32:
    if (activeMask and (1'u32 shl i)) != 0:
      # Read absolute timer target for slot i.
      # Timer targets are at MACHW_BASE + 0x128 + i*4 (inferred from blob).
      let target = regRead(MACHW_BASE + 0x128'u + i * 4)
      let current = regRead(MACHW_TIMLO_REG)
      if current < target:
        let remaining = target - current
        if remaining < minRemaining:
          minRemaining = remaining

  return minRemaining

proc bl_nap_call*() {.exportc, cdecl.} =
  ## Execute nap (light sleep).
  ## From blob (2 instrs): li a0,0; ret -- returns 0 (no-op / nap disabled).
  ## Intentionally empty: blob is a no-op that returns 0.
  return

# Forward declarations for notifier chain functions (defined later)
proc notifier_chain_regsiter*(chain: ptr CoList, notifier: ptr CoListHdr) {.exportc, cdecl.}
proc notifier_chain_regsiter_fromCritical*(chain: ptr CoList, notifier: ptr CoListHdr) {.exportc, cdecl.}
proc notifier_chain_unregsiter*(chain: ptr CoList, notifier: ptr CoListHdr) {.exportc, cdecl.}
proc notifier_chain_unregsiter_fromCritical*(chain: ptr CoList, notifier: ptr CoListHdr) {.exportc, cdecl.}
proc notifier_chain_call*(chain: ptr CoList, event: uint32, data: pointer) {.exportc, cdecl.}
proc notifier_chain_call_fromeCritical*(chain: ptr CoList, event: uint32, data: pointer) {.exportc, cdecl.}

proc bl_nap_hook_register*(hook: pointer) {.exportc, cdecl.} =
  ## Register a nap hook (30 bytes in blob).
  ## Blob: notifier_chain_regsiter(&napHookChain, hook)
  let chain = cast[ptr CoList](addr fw_nap_chain_ptr)
  notifier_chain_regsiter(chain, cast[ptr CoListHdr](hook))

proc bl_nap_hook_unregister*(hook: pointer) {.exportc, cdecl.} =
  ## Unregister a nap hook (30 bytes in blob).
  ## Blob: notifier_chain_unregsiter(&napHookChain, hook)
  let chain = cast[ptr CoList](addr fw_nap_chain_ptr)
  notifier_chain_unregsiter(chain, cast[ptr CoListHdr](hook))

proc bl_nap_hook_call*(event: uint32, data: pointer) {.exportc, cdecl.} =
  ## Call nap hooks (32 bytes in blob).
  ## Blob: notifier_chain_call(&napHookChain, a0, a1)
  let chain = cast[ptr CoList](addr fw_nap_chain_ptr)
  notifier_chain_call(chain, event, data)

proc bl_nap_hook_register_fromCritical*(hook: pointer) {.exportc, cdecl.} =
  ## Register nap hook from critical section (30 bytes in blob).
  ## Blob: notifier_chain_regsiter_fromCritical(&napHookChain, hook)
  let chain = cast[ptr CoList](addr fw_nap_chain_ptr)
  notifier_chain_regsiter_fromCritical(chain, cast[ptr CoListHdr](hook))

proc bl_nap_hook_unregister_fromCritical*(hook: pointer) {.exportc, cdecl.} =
  ## Unregister nap hook from critical section (30 bytes in blob).
  ## Blob: notifier_chain_unregsiter_fromCritical(&napHookChain, hook)
  let chain = cast[ptr CoList](addr fw_nap_chain_ptr)
  notifier_chain_unregsiter_fromCritical(chain, cast[ptr CoListHdr](hook))

proc bl_nap_hook_call_fromCritical*(event: uint32, data: pointer) {.exportc, cdecl.} =
  ## Call nap hooks from critical section (32 bytes in blob).
  ## Blob: notifier_chain_call_fromeCritical(&napHookChain, a0, a1)
  ## Note: blob shifts args: a0→a1 (event), a1→a2 (data), loads chain→a0
  let chain = cast[ptr CoList](addr fw_nap_chain_ptr)
  notifier_chain_call_fromeCritical(chain, event, data)

proc bl_pm_ops_register*(ops: pointer) {.exportc, cdecl.} =
  ## Register power management ops (564 bytes, 196 instrs in blob).
  ## From blob (bl.o): calls wifi_hosal_pm_event_register 19 times in sequence
  ## with different parameters. Each call registers a PM callback for a specific
  ## WiFi power management event type. The 19 registrations cover:
  ##   idle/doze, scan, auth, assoc, channel switch, PS, TX, beacon, etc.
  ## Since wifi_hosal_pm_event_register is a platform callback provided by
  ## the host SDK (not part of the firmware blob itself), we call through
  ## the g_bl_ops_funcs function table.
  ##
  ## From disasm: 19 sequential calls to wifi_hosal_pm_event_register with
  ## args (type: a0, group: a1, size: a2, event_id: a3, callback: a4, flags: a5, enable: a6).
  ## The callbacks are: wait_mac_goto_idle, coex_pta_force_autocontrol_set,
  ## set_mac_to_doze, wifi_hosal_rf_turn_off/on, rfc_channel_ops,
  ## wakeup_from_doze_pre/done, wait_mac_goto_prestate, mac_recovery,
  ## pm_force_sleep_check, ble_rf_ops.
  ##
  ## We register through the platform PM registration function if available.
  ## If the platform doesn't provide it, this is effectively a no-op.
  let blOps = cast[uint](addr g_bl_ops_funcs)
  # The PM registration function may be at a platform-specific offset.
  # In the blob, this is a direct relocation to wifi_hosal_pm_event_register.
  # Since we can't resolve that relocation, we store the registration table
  # so the platform layer can pick it up later.
  #
  # The 19 registrations in order from blob disassembly:
  # 1. wait_mac_goto_idle: type=1, group=0, size=2, event=13, flags=0, enable=1
  # 2. coex_pta_force_autocontrol_set: type=1, group=1, size=16, event=20, flags=1, enable=1
  # 3. set_mac_to_doze: type=1, group=1, size=4, event=125, flags=0, enable=1
  # 4. wifi_hosal_rf_turn_off: type=1, group=1, size=8, event=150, flags=0, enable=1
  # 5. coex_pta_force_autocontrol_set: type=2, group=2, size=16, event=5, flags=1, enable=1
  # 6. wifi_hosal_rf_turn_on: type=2, group=2, size=8, event=10, flags=0, enable=1
  # 7. rfc_channel_ops: type=2, group=2, size=8, event=11, flags=0, enable=1
  # 8. wakeup_from_doze_pre: type=2, group=2, size=4, event=34, flags=0, enable=1
  # 9. wait_mac_goto_prestate: type=2, group=2, size=2, event=36, flags=0, enable=1
  # 10. wakeup_from_doze_done: type=2, group=2, size=4, event=140, flags=0, enable=1
  # 11. mac_recovery: type=2, group=0, size=2, event=60, flags=0, enable=0
  # 12. pm_force_sleep_check: type=4, group=0, size=32, event=20, flags=0, enable=1
  # 13. wifi_hosal_rf_turn_on: type=4, group=1, size=2, event=8, flags=0, enable=0
  # 14. rfc_channel_ops: type=4, group=1, size=2, event=18, flags=0, enable=0
  # 15. wifi_hosal_rf_turn_on: type=3, group=0, size=4, event=100, flags=0, enable=0
  # 16. rfc_channel_ops: type=3, group=0, size=4, event=123, flags=0, enable=0
  # 17. coex_pta_force_autocontrol_set: type=0, group=3, size=16, event=35, flags=2, enable=1
  # 18. ble_rf_ops: type=5, group=0, size=8, event=10, flags=0, enable=1
  # 19. ble_rf_ops: type=5, group=1, size=8, event=20, flags=0, enable=1
  #
  # Call wifi_hosal_pm_event_register for each PM event.
  # The registration function is an external platform symbol.
  # Each call: register(type, group, size, event_id, callback_ptr, flags, enable)
  type PmRegFn = proc(typ: uint32, group: uint32, size: uint32, eventId: uint32,
                      callback: pointer, flags: uint32, enable: uint32) {.cdecl.}
  proc wifi_hosal_pm_event_register(typ: uint32, group: uint32, size: uint32,
      eventId: uint32, callback: pointer, flags: uint32,
      enable: uint32) {.importc, cdecl.}

  # Activate sleep management (enables hook-walking in bl_sleep_schedule)
  napSleepActive = 1

  # 1. wait_mac_goto_idle
  wifi_hosal_pm_event_register(1, 0, 2, 13, cast[pointer](wait_mac_goto_idle), 0, 1)
  # 2. coex_pta_force_autocontrol_set (doze entry)
  wifi_hosal_pm_event_register(1, 1, 16, 20, cast[pointer](coex_pta_force_autocontrol_set), 2, 1)
  # 3. set_mac_to_doze
  wifi_hosal_pm_event_register(1, 1, 4, 125, cast[pointer](set_mac_to_doze), 0, 1)
  # 4. wifi_hosal_rf_turn_off (via ble_rf_ops or similar)
  wifi_hosal_pm_event_register(1, 1, 8, 150, cast[pointer](ble_rf_ops), 0, 1)
  # 5. coex_pta_force_autocontrol_set (wake entry)
  wifi_hosal_pm_event_register(2, 2, 16, 5, cast[pointer](coex_pta_force_autocontrol_set), 1, 1)
  # 6. wifi_hosal_rf_turn_on
  wifi_hosal_pm_event_register(2, 2, 8, 10, cast[pointer](ble_rf_ops), 0, 1)
  # 7. rfc_channel_ops
  wifi_hosal_pm_event_register(2, 2, 8, 11, cast[pointer](rfc_channel_ops), 0, 1)
  # 8. wakeup_from_doze_pre
  wifi_hosal_pm_event_register(2, 2, 4, 34, cast[pointer](wakeup_from_doze_pre), 0, 1)
  # 9. wait_mac_goto_prestate
  wifi_hosal_pm_event_register(2, 2, 2, 36, cast[pointer](wait_mac_goto_prestate), 0, 1)
  # 10. wakeup_from_doze_done
  wifi_hosal_pm_event_register(2, 2, 4, 140, cast[pointer](wakeup_from_doze_done), 0, 1)
  # 11. mac_recovery
  wifi_hosal_pm_event_register(2, 0, 2, 60, cast[pointer](mac_recovery), 0, 0)
  # 12. pm_force_sleep_check
  wifi_hosal_pm_event_register(4, 0, 32, 20, cast[pointer](pm_force_sleep_check), 0, 1)
  # 13. wifi_hosal_rf_turn_on (power domain 4, group 1)
  wifi_hosal_pm_event_register(4, 1, 2, 8, cast[pointer](ble_rf_ops), 0, 0)
  # 14. rfc_channel_ops (power domain 4, group 1)
  wifi_hosal_pm_event_register(4, 1, 2, 18, cast[pointer](rfc_channel_ops), 0, 0)
  # 15. wifi_hosal_rf_turn_on (power domain 3)
  wifi_hosal_pm_event_register(3, 0, 4, 100, cast[pointer](ble_rf_ops), 0, 0)
  # 16. rfc_channel_ops (power domain 3)
  wifi_hosal_pm_event_register(3, 0, 4, 123, cast[pointer](rfc_channel_ops), 0, 0)
  # 17. coex_pta_force_autocontrol_set (ble coex)
  wifi_hosal_pm_event_register(0, 3, 16, 35, cast[pointer](coex_pta_force_autocontrol_set), 2, 1)
  # 18. ble_rf_ops (BLE domain entry)
  wifi_hosal_pm_event_register(5, 0, 8, 10, cast[pointer](ble_rf_ops), 1, 1)
  # 19. ble_rf_ops (BLE domain exit)
  wifi_hosal_pm_event_register(5, 1, 8, 20, cast[pointer](ble_rf_ops), 0, 1)

proc bl_pti_reset*() {.exportc, cdecl.} =
  ## Reset Priority Traffic Indication (PTA coexistence).
  ## Not found in objdump (possibly in separate coex object file).
  ## From 63-instruction description and coex_pta_force_autocontrol_set patterns:
  ##   Resets all PTA priority registers at COEX_BASE (0x44920000) and
  ##   MACHW_BCN_STATUS_REG area (0x44B00400) to default coexistence state.
  ##
  ## Registers manipulated (from coex module patterns):
  ##   COEX_BASE + 0x004: PTA control register - clear/set priority bits
  ##   COEX_BASE + 0x428: PTA force control register - clear to 0
  ##   MACHW_BASE + 0x400: BCN/PTA status register - clear/set enable bit
  let coexBase = COEX_BASE
  let machwPtaReg = MACHW_BASE + 0x400'u

  # Clear PTA force control register
  regWrite(coexBase + 0x428'u, 0)

  # Reset PTA control bits in COEX_CTRL_REG (offset 0x004):
  # Clear bits: 0 (enable), 1 (WiFi priority), 4 (force),
  #             16 (ext priority), 17 (band sel), 18 (override), 19 (alt mode)
  var ctrlVal = regRead(coexBase + 0x004'u)
  ctrlVal = ctrlVal and not 0x000F0013'u32  # Clear control bits
  ctrlVal = ctrlVal or 0x00000012'u32       # Set default: bit1=WiFi priority, bit4=enable
  regWrite(coexBase + 0x004'u, ctrlVal)

  # Reset MACHW PTA/BCN status register
  var ptaVal = regRead(machwPtaReg)
  ptaVal = ptaVal and not 0x00000001'u32    # Clear enable bit
  regWrite(machwPtaReg, ptaVal)

  # Re-enable with defaults
  ptaVal = regRead(machwPtaReg)
  ptaVal = ptaVal or 0x00000001'u32         # Set enable bit
  regWrite(machwPtaReg, ptaVal)

proc bl_wifi_timer_arm*(timer: pointer, delayMs: uint32) {.exportc, cdecl.} =
  ## Arm a WiFi timer.
  ## From blob (7 instrs): reads MAC timestamp, converts delay from ms to MAC ticks
  ## (multiply by 1000), adds to timestamp for absolute target time,
  ## tail-calls mm_timer_set(timer, targetTime).
  let macTime = macTimeNow()
  let delayTicks = delayMs * 1000'u32  # 1MHz MAC clock: 1000 ticks per ms
  let targetTime = macTime + delayTicks
  mm_timer_set(timer, targetTime)

proc bl_wifi_timer_disarm*(timer: pointer) {.exportc, cdecl.} =
  ## Disarm a WiFi timer.
  ## From blob (2 instrs): tail-call to mm_timer_clear(timer).
  mm_timer_clear(timer)

proc bl_wifi_timer_done*(timer: pointer): bool {.exportc, cdecl.} =
  ## Check if a WiFi timer has expired.
  return true

proc bl_wifi_timer_setfn*(timer: pointer, fn: pointer) {.exportc, cdecl.} =
  ## Set timer callback function (3 instrs).
  ## From blob: sw a1,4(a0); sw a2,8(a0); ret
  ## Stores fn (a1) at timer+4 and the third C arg (a2, callback context) at timer+8.
  let t = cast[uint](timer)
  cast[ptr pointer](t + 4)[] = fn
  # Capture and store the third C arg (a2) at timer+8
  var cbArg: pointer
  {.emit: ["asm volatile(\"mv %0, a2\" : \"=r\"(", cbArg, ") );"].}
  cast[ptr pointer](t + 8)[] = cbArg

# BL WiFi WPA/security callbacks
proc bl_wifi_register_wpa_cb_internal*(cb: pointer) {.exportc, cdecl.} =
  ## Register WPA callback.
  ## From blob (4 instrs): stores cb to wpa_cbs global, returns 0.
  wpa_cbs = cb

proc bl_wifi_unregister_wpa_cb_internal*() {.exportc, cdecl.} =
  ## Unregister WPA callback.
  ## From blob (4 instrs): stores nil to wpa_cbs global, returns 0.
  wpa_cbs = nil

proc bl_wifi_set_appie_internal*(vifIdx: uint8, ieType: uint8, ie: pointer, ieLen: uint16) {.exportc, cdecl.} =
  ## Set application IE for frames.
  ## From blob (36 instrs):
  ##   ieType==0: calls internal assoc IE handler(vifIdx, ie, ieLen&0xFF)
  ##   ieType==1: stores ie/ieLen into beacon extra IE globals (max 170 bytes)
  ##   ieType==2: stores ie/ieLen into probe response extra IE globals (max 50 bytes)
  ## Returns 0 on success, -1 on invalid length (return in a0).
  if ieType == 0:
    # Forward to WPA/RSN IE handler (blob: mm_set_wpa_rsn_ie)
    mm_set_wpa_rsn_ie(ie, (ieLen and 0xFF).uint32)
  elif ieType == 1:
    # Beacon extra IE: max 170 bytes
    if ieLen > 170:
      return
    appIeBeaconPtr = ie
    appIeBeaconLen = ieLen
  elif ieType == 2:
    # Probe response extra IE: max 50 bytes
    if ieLen > 50:
      return
    appIeProbeRespPtr = ie
    appIeProbeRespLen = ieLen

proc bl_wifi_unset_appie_internal*(vifIdx: uint8, ieType: uint8) {.exportc, cdecl.} =
  ## Unset application IE.
  ## From blob (6 instrs): tail-calls bl_wifi_set_appie_internal(vifIdx, ieType, nil, 0).
  bl_wifi_set_appie_internal(vifIdx, ieType, nil, 0)

proc setKey(vifIdx: uint8, a1Byte: uint8, keyIdxOrPairwise: uint8,
            macAddr: pointer, macLen: uint8,
            keyData: pointer, keyLen: uint8, cipher: uint8)
  {.exportc: "set_key_constprop0_nim", noinline.} =
  ## Blob `set_key.constprop.0` — shared AP/STA key-struct builder.
  ## Builds the 56-byte HW-key descriptor at a stack buffer and tail-calls
  ## mm_sec_machwkey_wr. ABI matches blob exactly:
  ##   +0   = keyIdxOrPairwise        (a2 in blob)
  ##   +1   = a1Byte (or 0xFF when cipher==0)
  ##   +4   = keyLen
  ##   +8   = keyData memcpy (keyLen bytes)
  ##   +40  = macLen           — only if macAddr != NULL
  ##   +44  = macAddr memcpy   — only if macAddr != NULL
  ##   +52  = translated cipher (16→2, 32→1, 13→3, 5→0, else raw)
  ##   +53  = vifIdx
  ##   +55  = cipher (raw)
  var buf {.noinit.}: array[56, uint8]
  discard c_memset(addr buf[0], 0, 56.csize_t)
  buf[53] = vifIdx
  buf[1]  = a1Byte
  buf[55] = cipher
  if cipher == 0:
    buf[1] = 0xFF'u8
  buf[0] = keyIdxOrPairwise
  # Optional macAddr memcpy (AP caller passes NULL; STA caller passes BSSID)
  if macAddr != nil:
    discard c_memcpy(addr buf[44], macAddr, macLen.csize_t)
    buf[40] = macLen
  # Key data memcpy
  buf[4] = keyLen
  discard c_memcpy(addr buf[8], keyData, keyLen.csize_t)
  # Cipher translation
  if keyLen == 16:
    buf[52] = 2  # CCMP
  elif keyLen == 32:
    # TKIP: swap MIC key halves at buf[24..31] ↔ buf[32..39]
    let w0a = cast[ptr uint32](addr buf[24])[]
    let w1a = cast[ptr uint32](addr buf[28])[]
    let w0b = cast[ptr uint32](addr buf[32])[]
    let w1b = cast[ptr uint32](addr buf[36])[]
    cast[ptr uint32](addr buf[24])[] = w0b
    cast[ptr uint32](addr buf[28])[] = w1b
    cast[ptr uint32](addr buf[32])[] = w0a
    cast[ptr uint32](addr buf[36])[] = w1a
    buf[52] = 1  # TKIP
  elif keyLen == 13:
    buf[52] = 3  # WEP-104
  elif keyLen == 5:
    buf[52] = 0  # WEP-40
  mm_sec_machwkey_wr(addr buf[0])

proc bl_wifi_set_ap_key_internal*(param: pointer) {.exportc, cdecl.} =
  ## Set AP encryption key (59 instructions in blob).
  ##
  ## Blob ABI: a0=vifIdx, a1=macAddr/staIdx, a2=pairwise, a3=keyIdx,
  ##   a4=keyData(ptr), a5=keyLen, a6=cipher. Nim receives a0 as `param`.
  ##
  ## Flow:
  ##   1. Log via g_bl_ops_funcs[204] at line 192.
  ##   2. If pairwise == 0: group key -- call mm_sec_machwkey_del((a1+8) & 0xFF).
  ##   3. If pairwise != 0: pairwise key -- build key struct, call mm_sec_machwkey_wr.
  ##   4. Return 0.
  let vifIdxU8 = (cast[uint32](param) and 0xFF).uint8

  # Best-effort capture of caller's registers a1..a6
  var macAddr_arg: uint32
  var pairwise_arg: uint32
  var keyIdx_arg: uint32
  var keyData_arg: pointer
  var keyLen_arg: uint32
  var cipher_arg: uint32
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", macAddr_arg, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a2\" : \"=r\"(", pairwise_arg, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a3\" : \"=r\"(", keyIdx_arg, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a4\" : \"=r\"(", keyData_arg, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a5\" : \"=r\"(", keyLen_arg, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a6\" : \"=r\"(", cipher_arg, ") );"].}

  # Log entry via g_bl_ops_funcs[204]
  let logFn = getLogFunc(204)
  if logFn != nil:
    logFn(1, 0, nil, 192, vifIdxU8.uint32, macAddr_arg, pairwise_arg)

  if pairwise_arg == 0:
    # Group key: delete old HW key entry
    mm_sec_machwkey_del(((macAddr_arg + 8) and 0xFF).uint8)
  else:
    # Pairwise key: AP path passes no macAddr (a3=0 in blob); a1Byte is the
    # low byte of macAddr_arg, keyIdxOrPairwise = keyIdx.
    setKey(vifIdxU8,
           (macAddr_arg and 0xFF).uint8,   # a1Byte
           keyIdx_arg.uint8,                # keyIdxOrPairwise (blob AP: keyIdx)
           nil, 0'u8,                       # macAddr=NULL, macLen=0
           keyData_arg, keyLen_arg.uint8,   # keyData, keyLen
           cipher_arg.uint8)                # cipher

proc bl_wifi_set_sta_key_internal*(vifIdx: uint8, macAddr: pointer, pairwise: uint8,
    keyIdx: uint8, keyLen: uint8, keyData: pointer, cipher: uint8,
    seqData: pointer, seqLen: uint8) {.exportc, cdecl.} =
  ## Set STA encryption key (83 instrs).
  ## Blob call: set_key.constprop.0(vifIdx, macAddrByte, pairwise, macAddr,
  ##                                macLen=6, keyData, keyLen, cipher),
  ##            sm_get_set_machwkey_index(0, vifIdx, &status, keyType).
  ## Pair-wise vs group selection is via the pairwise byte at buffer +0;
  ## STA path stores BSSID via macAddr memcpy at +44.
  let macByte = if macAddr != nil: cast[ptr uint8](macAddr)[] else: 0'u8
  setKey(vifIdx,
         macByte,                       # a1Byte = low byte of macAddr
         pairwise,                      # keyIdxOrPairwise = pairwise for STA
         macAddr, 6'u8,                 # macAddr ptr + macLen=6
         keyData, keyLen,               # keyData, keyLen
         cipher)                        # cipher
  # Blob: sm_get_set_machwkey_index(0, vifIdx, &status_byte, keyType)
  var statusByte: uint8 = 0
  let keyType: uint32 = if pairwise == 0: 1 else: 0
  discard sm_get_set_machwkey_index(0, vifIdx.uint32,
    cast[pointer](addr statusByte), keyType)
  # Log the operation via g_bl_ops_funcs[204]
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  let logFnPtr = cast[ptr pointer](opsBase + 204)[]
  if logFnPtr != nil:
    let logFn = cast[PlatformLogFunc](logFnPtr)
    logFn(1, 0, nil, 211, vifIdx.uint32, pairwise.uint32)
    logFn(1, 0, nil, 212, keyLen.uint32, keyIdx.uint32, cipher.uint32)
    logFn(1, 0, nil, 213)

proc bl_wifi_set_igtk_internal*(vifIdx: uint8, macAddr: pointer, keyIdx: uint8,
    keyData: pointer, keyLen: uint8) {.exportc, cdecl.} =
  ## Set IGTK (Integrity Group Temporal Key) for PMF (69 instrs).
  ## Called from host driver to install the IGTK for 802.11w (PMF).
  ## Assembly trace:
  ##   Builds a 56-byte key parameter struct on stack:
  ##     [41] = 0xFF (broadcast index)
  ##     [92] = 5 (key type = IGTK)
  ##     [93] = vifIdx
  ##     [40] = keyIdx
  ##     [44] = 16 (key length)
  ##     [80] = 6 (address type)
  ##     [48..63] = 16-byte key data (from keyData via memcpy)
  ##     [84..89] = 6-byte MAC address (from macAddr via memcpy)
  ##   Calls mm_sec_machwkey_wr(stack_buf) to write IGTK to HW.
  ##   Then calls mm_sec_machwaddr_wr with address setup.
  ##   Logs via g_bl_ops_funcs[204], returns 0.
  var keyBuf {.noinit.}: array[96, uint8]
  let bufAddr = cast[uint](addr keyBuf[0])
  # Clear buffer
  discard c_memset(cast[pointer](bufAddr + 40), 0, 56.csize_t)
  # Set up key parameters
  cast[ptr uint8](bufAddr + 41)[] = 0xFF  # broadcast
  cast[ptr uint8](bufAddr + 92)[] = 5     # IGTK type
  cast[ptr uint8](bufAddr + 93)[] = vifIdx
  cast[ptr uint8](bufAddr + 40)[] = keyIdx
  cast[ptr uint8](bufAddr + 44)[] = 16    # 16-byte key
  # Copy 16-byte key data
  discard c_memcpy(cast[pointer](bufAddr + 48), keyData, 16.csize_t)
  # Set address type and copy MAC address
  cast[ptr uint8](bufAddr + 80)[] = 6
  discard c_memcpy(cast[pointer](bufAddr + 84), macAddr, 6.csize_t)
  # Write IGTK to MAC HW
  mm_sec_machwkey_wr(cast[pointer](bufAddr + 40))
  # Get/set MAC HW key index (blob: sm_get_set_machwkey_index)
  let resultByte = cast[ptr uint8](bufAddr + 39)[]
  discard sm_get_set_machwkey_index(0, vifIdx.uint32, cast[pointer](bufAddr + 40), 5)
  # Log the operation
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  let logFnPtr = cast[ptr pointer](opsBase + 204)[]
  if logFnPtr != nil:
    let logFn = cast[PlatformLogFunc](logFnPtr)
    logFn(1, 0, nil, 237)

proc bl_wifi_get_sta_gtk*(vifIdx: uint8, keyBuf: pointer, outputBuf: pointer): cint {.exportc, cdecl.} =
  ## Get STA GTK (Group Temporal Key). Blob (25 instrs):
  ##   rc = sm_get_set_machwkey_index(getFlag=1, vifIdx, &keyIdx, keyType=1)
  ##   if rc != 0: return -1
  ##   return mm_sec_machwkey_get(keyIdx, keyBuf, outputBuf)
  var keyIdx {.noinit.}: uint8
  let rc = sm_get_set_machwkey_index(1'u32, vifIdx.uint32, cast[pointer](addr keyIdx), 1'u32)
  if rc != 0'u8:
    return -1
  discard mm_sec_machwkey_get(keyIdx, keyBuf, outputBuf)
  return 0

proc bl_wifi_ap_deauth_internal*(staAddr: pointer, reason: uint16) {.exportc, cdecl.} =
  ## Send deauth to a station in AP mode (86 bytes in blob, 28 instrs).
  ## Blob ABI: a0=staIdx, a1=macAddr, a2=reason.
  ## Flow: log at line 22 via g_bl_ops_funcs[0xCC], then call apm_sta_remove(a0, a1, 6).
  var macAddr {.noinit.}: pointer
  var reasonCode {.noinit.}: uint16
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", macAddr, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a2\" : \"=r\"(", reasonCode, ") );"].}
  # Log via g_bl_ops_funcs[0xCC] (offset 204)
  let logFn = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 0xCC)[]
  if logFn != nil:
    type LP = proc(a0, a1: uint32, fmt: pointer, line: uint32, p1, p2, p3: uint32) {.cdecl, varargs.}
    cast[LP](logFn)(1, 0, nil, 22, cast[uint32](staAddr), cast[uint32](macAddr), reasonCode.uint32)
  # Blob: tail-call apm_sta_remove(a0=staAddr, a1=macAddr, a2=6)
  # apm_sta_remove Nim signature: (vifEntry, staIdx, macAddr, reason)
  # but blob passes (a0, a1, 6) — ABI mismatch handled by Nim's cdecl
  let removeFn = cast[proc(a0, a1: pointer, a2: uint32) {.cdecl.}](apm_sta_remove)
  removeFn(staAddr, macAddr, 6)

proc bl_wifi_auth_done_internal*(param: pointer): uint32 {.exportc, cdecl.} =
  ## Notify auth completion (72b in blob).
  ## Blob ABI: a0=staAddr, a1=status.
  ## Logs at line 29 with (a0, a1), calls apm_handle_auth_done(a0, a1), returns 1.
  var status {.noinit.}: pointer
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", status, ") );"].}
  let logFn = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
  if logFn != nil:
    cast[proc(a0: uint32, a1: uint32, fmtStr: pointer, line: uint32,
              fileStr: pointer, p0: pointer, p1: pointer) {.cdecl.}](logFn)(
      1, 0, nil, 29, nil, param, status)
  # Blob calls sm_handle_supplicant_result(a0=staAddr, a1=status)
  sm_handle_supplicant_result(cast[uint8](cast[uint](param)), cast[uint8](cast[uint](status)))
  return 1

proc bl_wifi_get_assoc_bssid_internal*(vifIdx: uint8, output: pointer): cint {.exportc, cdecl.} =
  ## Get associated BSSID.
  ## From blob (19 instrs):
  ##   Calls vif_mgmt_get_vif(vifIdx) to get the VIF entry.
  ##   If nil, returns -1. Otherwise, copies 6 bytes (BSSID) from
  ##   vifEntry + 380 (0x17C) to output, returns 0.
  let vifEntry = vif_mgmt_get_vif(vifIdx)
  if vifEntry == nil:
    return -1
  let bssidSrc = cast[pointer](cast[uint](vifEntry) + 380)
  discard c_memcpy(output, bssidSrc, 6)
  return 0

proc bl_wifi_get_hostap_private_internal*(): pointer {.exportc, cdecl.} =
  ## Get hostapd private data.
  ## From blob (2 instrs): tail-calls apm_get_hostapd_ctx().
  return apm_get_hostapd_ctx()

proc bl_wifi_get_wps_status_internal*(): uint8 {.exportc, cdecl.} =
  ## Get WPS status.
  ## From blob (3 instrs): loads wpsStatus global byte, returns it.
  return wpsStatus

proc bl_wifi_set_wps_cb_internal*(cb: pointer) {.exportc, cdecl.} =
  ## Set WPS callback.
  ## From blob (4 instrs): stores cb to wps_cbs global, returns 0.
  wps_cbs = cb

proc bl_wifi_set_wps_status_internal*(status: uint8) {.exportc, cdecl.} =
  ## Set WPS status.
  ## From blob (3 instrs): stores a0 to wpsStatus global byte, returns.
  wpsStatus = status

proc bl_wifi_wpa_ptk_init_done_internal*(vifIdx: uint8) {.exportc, cdecl.} =
  ## Notify PTK init done.
  ## From blob (23 instrs):
  ##   1. Loads log function from g_bl_ops_funcs and calls it with
  ##      (level=1, severity=0, file_str, line=99, format_str, vifIdx)
  ##   2. Calls sm_connect_ind(0, 0) to signal successful connection
  ##   3. Returns 1
  ## The log call uses the platform log function at g_bl_ops_funcs offset 0.
  let logFn = getLogFunc(0)
  if logFn != nil:
    logFn(1, 0, nil, 99)
  # Blob calls apm_handle_auth_done(vifIdx) for PTK init completion
  apm_handle_auth_done(cast[pointer](vifIdx.uint))

proc bl_wifi_skip_supp_pmkcaching*(): bool {.exportc, cdecl.} =
  ## Check if PMK caching should be skipped.
  return false

proc bl_wifi_sta_is_ap_notify_completed_rsne_internal*(): bool {.exportc, cdecl.} =
  ## Vendor blob returns constant true. The supplicant uses this to decide
  ## whether to include the complete RSNE in association and EAPOL M2.
  return true

proc bl_wifi_sta_is_running_internal*(): bool {.exportc, cdecl.} =
  ## Vendor blob returns constant true.
  return true

proc bl_wifi_sta_set_reset_param_internal*(param: pointer) {.exportc, cdecl.} =
  ## Set reset parameters for STA.
  ## From blob (2 instrs): li a0,0; ret -- always returns 0 (success).
  discard  # void return; blob returns 0 in a0 for C ABI

proc bl_wifi_sta_update_ap_info_internal*(param: pointer) {.exportc, cdecl.} =
  ## Update AP info.
  ## From blob (2 instrs): li a0,1; ret -- always returns 1 (success).
  discard  # void return; blob returns 1 in a0 for C ABI

# ###########################################################################
#                  MFP: Management Frame Protection
# ###########################################################################

proc mfp_ignore_mgmt_frame*(param: pointer): bool {.exportc, cdecl.} =
  ## Check if a management frame should be ignored (MFP/PMF policy).
  ##
  ## From blob disassembly (172 instructions):
  ## ABI: a0=rxu_mgt_ind payload, a1=frame_body_ptr, a2=frame_total_len, a3=out_flag_ptr
  ## Hidden args: a1=frame body pointer, a2=frame total length, a3=output flag pointer
  ##
  ## param layout:
  ##   offset 0:  uint16 - frame_ctrl (FC field)
  ##   offset 8:  uint8  - body_offset (IE start within frame)
  ##   offset 9:  uint8  - sta_idx (0xFF = unknown)
  ##   offset 10: uint8  - vif_idx (0xFF = unknown)
  ##   offset 36: uint8  - flags (bit 0 = protected)
  ##
  ## Returns: true if frame should be processed, false if should be ignored.
  let pb = cast[ptr UncheckedArray[uint8]](param)
  let frameCtrl = cast[ptr uint16](param)[]
  let staIdx = pb[9]
  let bodyOff = pb[8]

  # Capture hidden ABI args (a1=frame_body, a2=frame_len, a3=out_flag)
  var frameBodyPtr {.noinit.}: pointer
  var frameTotalLen {.noinit.}: uint32
  var outFlagPtr {.noinit.}: ptr uint8
  {.emit: ["""
  register void* _fb __asm__("a1");
  register unsigned int _fl __asm__("a2");
  register unsigned char* _of __asm__("a3");
  """, frameBodyPtr, " = _fb; ", frameTotalLen, " = _fl; ", outFlagPtr, " = _of;"].}

  # Blob: pre-validate with mfp_is_robust_frame(frameCtrl, subtype)
  # T-Head custom insn extracts subtype field; we use standard shift/mask
  let subtypeField = (frameCtrl shr 4) and 0x0F'u16
  let isRobust = mfp_is_robust_frame(frameCtrl.uint32, subtypeField.uint32)
  let frameEnd = cast[uint](frameBodyPtr) + bodyOff.uint

  if not isRobust:
    # Blob returns immediately for ordinary management frames without
    # touching the caller's acceptance byte.
    return false

  # Check valid STA and VIF indices
  let vifIdx = pb[10]
  if staIdx == 0xFF'u8:
    if outFlagPtr != nil:
      outFlagPtr[] = 0
    return false
  if vifIdx == 0xFF'u8:
    if outFlagPtr != nil:
      outFlagPtr[] = 0
    return false

  # Compute VIF entry and check security context
  let vifEntryBase = cast[uint](addr vif_info_tab[0]) + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let secCtxPtr = cast[ptr uint32](vifEntryBase + 1492)[]
  if secCtxPtr == 0:
    if outFlagPtr != nil:
      outFlagPtr[] = 0
    return false

  let flags36 = pb[36]

  if (flags36 and 1) != 0:
    # Protected frame: validate MMIE replay counter (BIP)
    # Check minimum frame length: bodyOff + 19 bytes minimum
    if (bodyOff.int + 19) >= frameTotalLen.int:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false

    # Compute IE search region: body starts at frame_body + bodyOff + 2, length = frameTotalLen - bodyOff - 2
    let ieSearchLen = frameTotalLen.int - bodyOff.int - 2
    let ieSearchStart = cast[pointer](cast[uint](frameBodyPtr) + bodyOff.uint + 2)

    # Find MMIE (IE_ID=76) in the frame
    let mmiePtr = mac_ie_find(ieSearchStart, ieSearchLen.uint32, 76)
    if mmiePtr == nil:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false

    let mmieU = cast[uint](mmiePtr)
    # MMIE structure: [0]=IE_ID(76), [1]=len(16), [2..3]=keyID, [4..9]=IPN, [10..17]=MIC
    # Blob: reads keyID from MMIE[2..3] as LE16, checks (keyID - 4) <= 1
    # Valid MMIE keyIDs are 4 and 5 (IGTK key slots)
    let keyIdLo = cast[ptr uint8](mmieU + 2)[]
    let keyIdHi = cast[ptr uint8](mmieU + 3)[]
    let keyId = keyIdLo.uint16 or (keyIdHi.uint16 shl 8)
    if (keyId - 4) > 1:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false

    # Look up IGTK key in VIF entry: offset 160 * keyIdAdj + sec base + 683
    # Blob: li a5,160; madd a5,s8,s3,a5 -> offset = keyIdAdj * 160 + vifBase + 683
    let keyIdAdj = keyId - 4  # 0 or 1
    let keySlotOff = keyIdAdj.uint * 160 + 683
    let storedKeyValid = cast[ptr uint8](vifEntryBase + keySlotOff)[]
    if storedKeyValid == 0:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false

    # Extract IPN (6 bytes) from MMIE[4..9]
    let ipnLo = cast[ptr uint8](mmieU + 5)[].uint16 or (cast[ptr uint8](mmieU + 4)[].uint16 shl 8)
    let ipnMid = cast[ptr uint8](mmieU + 7)[].uint16 or (cast[ptr uint8](mmieU + 6)[].uint16 shl 8)
    let ipnByte4 = cast[ptr uint8](mmieU + 8)[].uint32
    let ipnByte5 = cast[ptr uint8](mmieU + 9)[].uint32

    # Build 48-bit IPN as two 32-bit words
    let ipnW0 = ipnLo.uint32 or (ipnMid.uint32 shl 16)
    let ipnW1 = ipnByte4 or (ipnByte5 shl 8)

    # Compare against stored IPN at VIF secCtx offsets 528/532
    let storedIpnLo = cast[ptr uint32](vifEntryBase + 528)[]
    let storedIpnHi = cast[ptr uint32](vifEntryBase + 532)[]

    # 48-bit comparison: new IPN must be > stored IPN
    if ipnW1 < storedIpnHi:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false
    if ipnW1 == storedIpnHi and ipnW0 <= storedIpnLo:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false

    # IPN is fresh: update stored IPN
    cast[ptr uint32](vifEntryBase + 528)[] = ipnW0
    cast[ptr uint32](vifEntryBase + 532)[] = ipnW1

    # Compute and verify BIP MIC
    # Blob: addi a0,a0,528 -> key is at vifEntry+528 (IGTK key in sec context)
    let micResult = mfp_compute_bip(
      cast[pointer](vifEntryBase + 528),  # IGTK key at vif+528
      frameBodyPtr, frameTotalLen, bodyOff.uint32)
    # Compare 8-byte MIC at MMIE[10..17]
    let expectedMicLo = cast[ptr uint32](mmieU + 10)[]
    let expectedMicHi = cast[ptr uint32](mmieU + 14)[]
    let resultLo = (micResult and 0xFFFFFFFF'u64).uint32
    let resultHi = (micResult shr 32).uint32
    if resultLo != expectedMicLo or resultHi != expectedMicHi:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false

    return true
  else:
    # Unprotected frame: check if PMF requires protection
    let staBase = cast[uint](addr sta_info_tab[0]) + staIdx.uint * STA_ENTRY_SIZE.uint
    let rateInfoFlags = cast[ptr uint32](staBase + 308)[]
    if (rateInfoFlags and 0x08) == 0:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false

    # PMF enabled: check if group-addressed (bit 14 of FC)
    if (frameCtrl and 0x4000'u16) != 0:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false

    # Check frame subtype: deauth=0xC0, disassoc=0xA0 are robust mgmt
    let subtypeBits = (frameCtrl and 0xFC'u16).uint8
    # Blob: (subtypeBits - 0xA0) with bit 5 masked -> check both 0xA0 and 0xC0
    let adjusted = (subtypeBits.int - 160) and (not 0x20)
    if adjusted != 0:
      if outFlagPtr != nil:
        outFlagPtr[] = 0
      return false

    # Unprotected robust mgmt frame when PMF required -> accept with SA query flag
    if outFlagPtr != nil:
      outFlagPtr[] = 1  # signal SA query needed
    return true

proc mfp_protect_mgmt_frame*(frameDesc: pointer, fc: uint32, action: uint32 = 0): uint32 {.exportc, cdecl, noinline.} =
  ## Blob (110 bytes, 41 instrs, mfp.c.o):
  ##   a0 = frameDesc, a1 = fc, a2 = action category
  ##   vifIdx = frameDesc[47]
  ##   secCtx = vif_info_tab[vifIdx].secCtx (at +1492)
  ##   if secCtx == NULL: return 0
  ##   if !mfp_is_robust_frame(fc, action): return 0
  ##   staIdx = frameDesc[49]
  ##   if staIdx == 0xFF: return 2                     # broadcast → BIP
  ##   if (sta_info_tab[staIdx].flags308 & 1) == 0: return 2  # no PMF cap → BIP
  ##   return CCMP_from_vif_crypto (via T-Head bit extract on sta[308])
  {.emit: ["asm volatile(\"\" ::: \"memory\");"].}
  let fd = cast[ptr UncheckedArray[uint8]](frameDesc)
  let vifIdx = fd[47]
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  let secCtx = cast[ptr pointer](vifEntry + 1492)[]
  if secCtx == nil:
    return 0
  if not mfp_is_robust_frame(fc, action):
    return 0
  let staIdx = fd[49]
  if staIdx == 0xFF:
    return 2
  let staBase = cast[uint](addr sta_info_tab[0])
  let staEntry = staBase + staIdx.uint * STA_ENTRY_SIZE.uint
  let rateInfoFlags = cast[ptr uint32](staEntry + STA_RATE_INFO_FLAGS_OFF)[]
  if (rateInfoFlags and 1) == 0:
    return 2
  return 1

proc mfp_add_mgmt_mic*(frameDesc: pointer, bodyLen: uint32, totalLen: uint32): uint32 {.exportc, cdecl.} =
  ## Add Management MIC IE (MMIE) to a management frame for PMF (802.11w).
  ## From blob (86 instrs): builds MMIE with IE_ID=76, length=16.
  ## Contains key ID, IPN (packet number), and 8-byte MIC via AES-CMAC.
  ## Returns 18 (MMIE size) or 0 if no security context.
  let fd = cast[ptr UncheckedArray[uint8]](frameDesc)
  let vifIdx = fd[47]
  let vifBase = cast[uint](addr vif_info_tab[0])
  let vifEntry = vifBase + vifIdx.uint * VIF_ENTRY_SIZE.uint
  # Check security context at VIF+1492
  let secCtx = cast[ptr pointer](vifEntry + 1492)[]
  if secCtx == nil:
    return 0
  let secU = cast[uint](secCtx)
  # Compute MMIE write position: frameDesc body + bodyLen
  let mmiePos = cast[uint](frameDesc) + bodyLen
  let mmie = cast[ptr UncheckedArray[uint8]](mmiePos)
  # Write MMIE header
  mmie[0] = 76   # MMIE IE ID
  mmie[1] = 16   # length
  # Key ID from sec_ctx+153
  mmie[2] = cast[ptr uint8](secU + 153)[]
  mmie[3] = 0
  # Copy and increment IPN (6 bytes from sec_ctx+128..133)
  let ipnLo = cast[ptr uint32](secU + 128)[]
  let ipnHi = cast[ptr uint32](secU + 132)[]
  # Increment IPN by 1
  let newIpnLo = ipnLo + 1
  let newIpnHi = if newIpnLo < ipnLo: ipnHi + 1 else: ipnHi
  cast[ptr uint32](secU + 128)[] = newIpnLo
  cast[ptr uint32](secU + 132)[] = newIpnHi
  # Store IPN in MMIE[4..9] (6 bytes, little-endian)
  var idx = 0'u32
  while idx < 6:
    let ipnByte = if idx < 4:
        ((newIpnLo shr (idx * 8)) and 0xFF).uint8
      else:
        ((newIpnHi shr ((idx - 4) * 8)) and 0xFF).uint8
    mmie[4 + idx] = ipnByte
    inc idx
  # Clear MIC area and nonce — blob inlines two zero-word stores.
  cast[ptr uint32](mmiePos + 10)[] = 0
  cast[ptr uint32](mmiePos + 14)[] = 0
  # Compute BIP MIC using mfp_compute_bip
  # Blob passes secCtx directly as key (IGTK at start of sec context)
  let mic = mfp_compute_bip(secCtx, frameDesc, bodyLen + 18, 24)
  # Store 8-byte MIC. Blob splits lo/hi halves into two 4-byte loops —
  # each emits a runtime 64-bit shift (__lshrdi3 call). Volatile barrier
  # keeps GCC from merging them back into one.
  var micV {.volatile.}: uint64 = mic
  idx = 0
  while idx < 4:
    mmie[10 + idx] = ((micV shr (idx * 8)) and 0xFF'u64).uint8
    inc idx
  {.emit: "__asm__ volatile(\"\" ::: \"memory\");".}
  var micV2 {.volatile.}: uint64 = mic
  idx = 4
  while idx < 8:
    mmie[10 + idx] = ((micV2 shr (idx * 8)) and 0xFF'u64).uint8
    inc idx
  return 18

# Forward declaration for aes_encrypt_block (defined later in AES section)
proc aes_encrypt_block*(roundKeys: pointer, state: pointer) {.exportc, cdecl.}

proc mfp_compute_bip*(key: pointer, frame: pointer, frameLen: uint32,
    extraParam: uint32): uint64 {.exportc, cdecl.} =
  ## Compute BIP (Broadcast Integrity Protocol) MIC for PMF (558 bytes in blob).
  ## AES-CMAC-128 per IEEE 802.11w. Blob does inline CBC-MAC on stack.
  ## a0=key (with expanded schedule at +128), a1=frame, a2=frameLen,
  ## a3=extraParam (halved for MMIE offset). Returns 64-bit MIC in (a0,a1).

  if frameLen <= 41:
    assert_warn("mfp.c", "mfp.c", 428)
    return 0'u64

  let keyU = cast[uint](key)
  let frameU = cast[uint](frame)

  # Mask frame control: clear Protected/MoreData/PwrMgmt/Retry bits
  # Blob: 0xFFFFC7FF mask (lhu from frame+2, custom extract, mask)
  let origFc = cast[ptr uint16](frameU + 2)[]
  let maskedFc = origFc and 0xC7FF'u16

  # Build AAD header on stack: masked FC (2 bytes) + addresses from frame+4 (18 bytes)
  var aadHdr {.noinit.}: array[20, uint8]
  cast[ptr uint16](addr aadHdr[0])[] = maskedFc
  discard c_memcpy(addr aadHdr[2], cast[pointer](frameU + 4), 18.csize_t)

  # AES key expansion is at key+128 in blob
  # Blob runs 10-round AES encrypt inline using T-Head custom instructions.
  # We delegate to aes_encrypt_block instead (same logical result).

  # Compute data offset: extraParam >> 1 gives MMIE half-offset
  let halfParam = extraParam shr 1
  let dataStart = frameU + halfParam.uint + (halfParam.uint * 0)  # blob: s2 = frame + mul(halfParam, ???)
  # Blob: s0 = frameLen - 12 - extraParam = data length (excluding MMIE)
  var dataLen = cast[int32](frameLen) - 12 - cast[int32](extraParam)

  # Initialize CBC-MAC state and subkey buffer
  var cbcState {.noinit.}: array[16, uint8]
  var subKey {.noinit.}: array[16, uint8]
  discard c_memset(addr cbcState[0], 0, 16.csize_t)
  discard c_memset(addr subKey[0], 0, 16.csize_t)

  # XOR first 8 bytes of AAD into CBC-MAC state (blob: xor at 0x130, len=8)
  xor_bytes(addr cbcState[0], addr aadHdr[0], 8)
  # Encrypt state block
  aes_encrypt_block(key, addr cbcState[0])

  # XOR next 2 bytes of AAD (bytes 8-9) (blob: xor at 0x14a, len=2)
  xor_bytes(addr cbcState[0], cast[pointer](cast[uint](addr aadHdr[0]) + 8), 2)
  # XOR 6 more bytes (bytes 10-15) into state+4 (blob: xor at 0x158, len=6)
  xor_bytes(cast[pointer](cast[uint](addr cbcState[0]) + 4),
           cast[pointer](frameU + halfParam.uint), 6)
  # Encrypt
  aes_encrypt_block(key, addr cbcState[0])

  # Advance data pointer past initial 6 bytes consumed, adjust remaining
  var dataPtr = frameU + halfParam.uint + 12  # blob: s2 += 12
  dataLen = dataLen + cast[int32](extraParam) - 12  # adjust for consumed bytes

  # Main loop: process 16-byte blocks
  while dataLen > 16:
    xor_bytes(addr cbcState[0], cast[pointer](dataPtr), 8)
    aes_encrypt_block(key, addr cbcState[0])
    dataLen -= 16
    dataPtr += 16

  # Final block: generate CMAC subkey(s)
  aes_encrypt_block(key, addr subKey[0])
  aes_cmac_shift_sub_key(addr subKey[0])  # K1

  if dataLen.uint32 == 16:
    # Exact last block: XOR with K1, then encrypt
    xor_bytes(addr subKey[0], cast[pointer](dataPtr), 8)
  else:
    # Partial last block: generate K2, XOR partial data + padding
    aes_cmac_shift_sub_key(addr subKey[0])  # K2
    let halfLen = dataLen.uint32 shr 1
    xor_bytes(addr subKey[0], cast[pointer](dataPtr), halfLen)
    # Padding: set 0x80 byte after data (if odd length, adjust)
    let isOdd = (dataLen and 1) != 0
    if isOdd:
      let padByte = 0x80'u8 or 0x80'u8  # blob builds padding value
      let byteIdx = halfLen
      let subKeyPtr = cast[ptr uint8](cast[uint](addr subKey[0]) + byteIdx)
      subKeyPtr[] = subKeyPtr[] xor padByte

  # Final: XOR subkey into CBC-MAC state and encrypt
  xor_bytes(addr cbcState[0], addr subKey[0], 8)
  aes_encrypt_block(key, addr cbcState[0])

  # Return first 8 bytes of CBC-MAC as (lo, hi) uint64
  let micLo = cast[ptr uint32](addr cbcState[0])[]
  let micHi = cast[ptr uint32](cast[uint](addr cbcState[0]) + 4)[]
  return cast[uint64](micLo) or (cast[uint64](micHi) shl 32)

# ###########################################################################
#                  AES Encryption (mfp_bip.o)
# ###########################################################################

# AES S-Box
const AES_SBOX = [
  0x63'u8,0x7c,0x77,0x7b,0xf2,0x6b,0x6f,0xc5,0x30,0x01,0x67,0x2b,0xfe,0xd7,0xab,0x76,
  0xca,0x82,0xc9,0x7d,0xfa,0x59,0x47,0xf0,0xad,0xd4,0xa2,0xaf,0x9c,0xa4,0x72,0xc0,
  0xb7,0xfd,0x93,0x26,0x36,0x3f,0xf7,0xcc,0x34,0xa5,0xe5,0xf1,0x71,0xd8,0x31,0x15,
  0x04,0xc7,0x23,0xc3,0x18,0x96,0x05,0x9a,0x07,0x12,0x80,0xe2,0xeb,0x27,0xb2,0x75,
  0x09,0x83,0x2c,0x1a,0x1b,0x6e,0x5a,0xa0,0x52,0x3b,0xd6,0xb3,0x29,0xe3,0x2f,0x84,
  0x53,0xd1,0x00,0xed,0x20,0xfc,0xb1,0x5b,0x6a,0xcb,0xbe,0x39,0x4a,0x4c,0x58,0xcf,
  0xd0,0xef,0xaa,0xfb,0x43,0x4d,0x33,0x85,0x45,0xf9,0x02,0x7f,0x50,0x3c,0x9f,0xa8,
  0x51,0xa3,0x40,0x8f,0x92,0x9d,0x38,0xf5,0xbc,0xb6,0xda,0x21,0x10,0xff,0xf3,0xd2,
  0xcd,0x0c,0x13,0xec,0x5f,0x97,0x44,0x17,0xc4,0xa7,0x7e,0x3d,0x64,0x5d,0x19,0x73,
  0x60,0x81,0x4f,0xdc,0x22,0x2a,0x90,0x88,0x46,0xee,0xb8,0x14,0xde,0x5e,0x0b,0xdb,
  0xe0,0x32,0x3a,0x0a,0x49,0x06,0x24,0x5c,0xc2,0xd3,0xac,0x62,0x91,0x95,0xe4,0x79,
  0xe7,0xc8,0x37,0x6d,0x8d,0xd5,0x4e,0xa9,0x6c,0x56,0xf4,0xea,0x65,0x7a,0xae,0x08,
  0xba,0x78,0x25,0x2e,0x1c,0xa6,0xb4,0xc6,0xe8,0xdd,0x74,0x1f,0x4b,0xbd,0x8b,0x8a,
  0x70,0x3e,0xb5,0x66,0x48,0x03,0xf6,0x0e,0x61,0x35,0x57,0xb9,0x86,0xc1,0x1d,0x9e,
  0xe1,0xf8,0x98,0x11,0x69,0xd9,0x8e,0x94,0x9b,0x1e,0x87,0xe9,0xce,0x55,0x28,0xdf,
  0x8c,0xa1,0x89,0x0d,0xbf,0xe6,0x42,0x68,0x41,0x99,0x2d,0x0f,0xb0,0x54,0xbb,0x16,
]

const AES_RCON = [
  0x01'u32, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x1b, 0x36,
]

proc aes_encrypt_block*(roundKeys: pointer, state: pointer) {.exportc, cdecl.} =
  ## AES-128 block encryption (in-place on 16-byte state).
  ## From blob (mfp_bip.o, 261 instrs): standard AES-128 with 10 rounds.
  ## SubBytes, ShiftRows, MixColumns (9 rounds), final round no MixColumns.
  ## Blob calls add_round_key as a separate function (not inlined).
  let s = cast[ptr array[16, uint8]](state)

  # Blob structure: initial add_round_key, 9-round loop with MixColumns +
  # add_round_key, then final round 10 (no MixColumns) tail-calling
  # add_round_key — 3 separate call sites to match the blob.
  template subBytesShiftRows(shifted: var array[16, uint8]) =
    var tmp {.noinit.}: array[16, uint8]
    for i in 0 ..< 16:
      tmp[i] = AES_SBOX[s[i].int]
    shifted[0] = tmp[0]; shifted[4] = tmp[4]; shifted[8] = tmp[8]; shifted[12] = tmp[12]
    shifted[1] = tmp[5]; shifted[5] = tmp[9]; shifted[9] = tmp[13]; shifted[13] = tmp[1]
    shifted[2] = tmp[10]; shifted[6] = tmp[14]; shifted[10] = tmp[2]; shifted[14] = tmp[6]
    shifted[3] = tmp[15]; shifted[7] = tmp[3]; shifted[11] = tmp[7]; shifted[15] = tmp[11]

  template xtime(x: uint8): uint8 =
    let xv = x
    let r = xv.uint16 shl 1
    (if (xv and 0x80'u8) != 0: (r xor 0x1B).uint8 else: r.uint8)

  add_round_key(roundKeys, state, 0)

  for round in 1 .. 9:
    var shifted {.noinit.}: array[16, uint8]
    subBytesShiftRows(shifted)
    # MixColumns
    for col in 0 ..< 4:
      let b = col * 4
      let a0 = shifted[b]
      let a1 = shifted[b+1]
      let a2 = shifted[b+2]
      let a3 = shifted[b+3]
      s[b]   = xtime(a0) xor xtime(a1) xor a1 xor a2 xor a3
      s[b+1] = a0 xor xtime(a1) xor xtime(a2) xor a2 xor a3
      s[b+2] = a0 xor a1 xor xtime(a2) xor xtime(a3) xor a3
      s[b+3] = xtime(a0) xor a0 xor a1 xor a2 xor xtime(a3)
    add_round_key(roundKeys, state, round.uint32)

  # Round 10: SubBytes + ShiftRows (no MixColumns) then tail add_round_key
  var shifted {.noinit.}: array[16, uint8]
  subBytesShiftRows(shifted)
  for i in 0 ..< 16:
    s[i] = shifted[i]
  add_round_key(roundKeys, state, 10)

# ###########################################################################
#                  HSU: Hardware Security Unit
# ###########################################################################

proc hsu_init*() {.exportc, cdecl.} =
  ## Initialize hardware security unit.
  discard

proc hsu_aes_cmac*(key: pointer, msg: pointer, msgLen: uint32, mac: pointer) {.exportc, cdecl.} =
  ## Compute AES-CMAC-128 per RFC 4493.
  ## Steps: expand key, derive K1/K2, process blocks with CBC-MAC, output 16-byte MAC.
  # 1. AES key expansion (10 rounds -> 176 bytes of round keys)
  var roundKeys: array[176, uint8]
  discard c_memcpy(addr roundKeys[0], key, 16.csize_t)
  # Expand key schedule
  for i in 4'u32 ..< 44:
    var tmp: array[4, uint8]
    let prevOff = (i - 1) * 4
    for j in 0 ..< 4:
      tmp[j] = roundKeys[prevOff.int + j]
    if (i mod 4) == 0:
      # RotWord + SubWord + Rcon
      let t0 = tmp[0]
      tmp[0] = AES_SBOX[tmp[1].int] xor cast[uint8](AES_RCON[(i div 4 - 1).int])
      tmp[1] = AES_SBOX[tmp[2].int]
      tmp[2] = AES_SBOX[tmp[3].int]
      tmp[3] = AES_SBOX[t0.int]
    let off = i * 4
    let prevWordOff = (i - 4) * 4
    for j in 0 ..< 4:
      roundKeys[off.int + j] = roundKeys[prevWordOff.int + j] xor tmp[j]
  # 2. Generate subkeys K1, K2
  var k1: array[16, uint8]
  var k2: array[16, uint8]
  # Encrypt zero block to get L
  discard c_memset(addr k1[0], 0, 16.csize_t)
  aes_encrypt_block(addr roundKeys[0], addr k1[0])
  # K1 = shift(L), K2 = shift(K1)
  aes_cmac_shift_sub_key(addr k1[0])
  discard c_memcpy(addr k2[0], addr k1[0], 16.csize_t)
  aes_cmac_shift_sub_key(addr k2[0])
  # 3. CBC-MAC: process complete 16-byte blocks
  var state: array[16, uint8]
  discard c_memset(addr state[0], 0, 16.csize_t)
  var pos = 0'u32
  let nBlocks = if msgLen > 0: ((msgLen - 1) div 16) + 1 else: 1'u32
  let lastBlockComplete = (msgLen > 0) and ((msgLen mod 16) == 0)
  # Process all but last block
  if nBlocks > 1:
    for blk in 0'u32 ..< (nBlocks - 1):
      let src = cast[ptr UncheckedArray[uint8]](msg)
      for j in 0 ..< 16:
        state[j] = state[j] xor src[pos + j.uint32]
      aes_encrypt_block(addr roundKeys[0], addr state[0])
      pos += 16
  # Process last block with K1 or K2
  var lastBlock: array[16, uint8]
  let remaining = msgLen - pos
  if lastBlockComplete and remaining == 16:
    # Complete last block: XOR with K1
    let src = cast[ptr UncheckedArray[uint8]](msg)
    for j in 0 ..< 16:
      lastBlock[j] = src[pos + j.uint32] xor k1[j]
  else:
    # Incomplete last block: pad with 0x80 then zeros, XOR with K2
    discard c_memset(addr lastBlock[0], 0, 16.csize_t)
    if remaining > 0:
      let src = cast[ptr UncheckedArray[uint8]](msg)
      discard c_memcpy(addr lastBlock[0], cast[pointer](cast[uint](msg) + pos), remaining.csize_t)
    lastBlock[remaining.int] = 0x80'u8
    for j in 0 ..< 16:
      lastBlock[j] = lastBlock[j] xor k2[j]
  # XOR last block with state and encrypt
  for j in 0 ..< 16:
    state[j] = state[j] xor lastBlock[j]
  aes_encrypt_block(addr roundKeys[0], addr state[0])
  # 4. Output MAC
  discard c_memcpy(mac, addr state[0], 16.csize_t)

proc hsu_michael_init*(key: pointer) {.exportc, cdecl.} =
  ## Initialize Michael MIC calculation.
  discard

proc hsu_michael_calc*(data: pointer, dataLen: uint32) {.exportc, cdecl.} =
  ## Process data for Michael MIC.
  discard

proc hsu_michael_end*(mic: pointer) {.exportc, cdecl.} =
  ## Finalize Michael MIC calculation.
  discard

# ###########################################################################
#                  MAC Utilities
# ###########################################################################

proc mac_ie_find*(buf: pointer, bufLen: uint32, ieId: uint8): pointer {.exportc, cdecl.} =
  ## Find an Information Element by ID in a buffer.
  ## From blob (11 instrs): a1 = a0 + a1 (end = buf + bufLen), loop:
  ##   bltu a0, a1 => if pos < end, check IE
  ##   lbu a5, 0(a0) => id; beq a5, a2 => return pos if match
  ##   lbu a5, 1(a0); addi a5, 2; add a0, a5 => advance past IE
  ## Returns pointer to matching IE header, or nil if not found.
  var pos = cast[uint](buf)
  let endPos = pos + bufLen.uint
  while pos < endPos:
    let id = cast[ptr uint8](pos)[]
    if id == ieId:
      return cast[pointer](pos)
    let len = cast[ptr uint8](pos + 1)[]
    pos = pos + 2'u + len.uint
  return nil

proc mac_vsie_find*(buf: pointer, bufLen: uint32, oui: pointer, ouiLen: uint8): pointer {.exportc, cdecl.} =
  ## Find a vendor-specific IE by OUI (33 instructions in blob).
  ## From blob: a1 = buf + bufLen (end), a4 = 0xDD, a2 decremented by 1
  ## (oui adjusted for indexed load trick).
  ## Loop .L6: bltu pos, end => check IE; beq pos, end => return nil;
  ##   pos > end => call assert, return nil.
  ## .L11: lbu id; bne id, 0xDD => skip to .L7. Else a6 = pos+2 (IE body),
  ##   compare ouiLen bytes using indexed loads. Match => return pos.
  ## .L7: lbu len, 1(pos); pos += len + 2; loop back.
  var pos = cast[uint](buf)
  let endPos = pos + bufLen.uint
  let ouiArr = cast[ptr UncheckedArray[uint8]](oui)
  while pos < endPos:
    let id = cast[ptr uint8](pos)[]
    if id == 0xDD'u8:
      # Vendor-specific IE found, compare OUI bytes
      let ieData = cast[ptr UncheckedArray[uint8]](pos + 2)
      var match = true
      for i in 0'u8 ..< ouiLen:
        if ieData[i] != ouiArr[i]:
          match = false
          break
      if match:
        return cast[pointer](pos)
    let len = cast[ptr uint8](pos + 1)[]
    pos = pos + 2'u + len.uint
  # Blob never calls assert on overrun here (0 asserts in its call graph);
  # returning nil is the only outcome for "not found / past end".
  return nil

proc mac_irq*() {.exportc, cdecl.} =
  ## MAC interrupt handler (30 instrs in blob).
  ## Reads MAC platform IRQ status registers. If both zero (spurious), returns.
  ## Otherwise reads handler index from MAC_PL_IRQ_HANDLER, looks up the ISR
  ## in the intc_handler_tab, asserts if NULL, calls it, then tail-calls
  ## bl_irq_handler.
  let status0 = regRead(MAC_PL_IRQ_STATUS0)
  if status0 == 0:
    let status1 = regRead(MAC_PL_IRQ_STATUS1)
    if status1 == 0:
      return  # spurious -- both status regs zero
  # Read IRQ handler index
  let irqIdx = regRead(MAC_PL_IRQ_HANDLER)
  when defined(bl808WifiNimFw):
    let irqSlot = irqIdx and 0x3F'u32
    if irqSlot == 53'u32 or irqSlot == 54'u32:
      nimFwTrace2U32("[WIFI-NIMFW] macirq_tx ",
                     irqSlot or (status0 shl 8),
                     regRead(MAC_PL_IRQ_STATUS1))
      when defined(bl808WifiConnectTrace):
        nimFwConnectTrace2U32("[WIFI-CT] macirq_tx ",
                              irqSlot or (status0 shl 8),
                              regRead(MAC_PL_IRQ_STATUS1))
  let handler = cast[proc() {.cdecl.}](intc_handler_tab[irqIdx and 0x3F])
  if handler == nil:
    assert_err("intc.c", "intc.c", 154)
  else:
    handler()
  ipc_emb_notify(0)  # blob: ipc_emb_notify (not bl_irq_handler)

proc mac_paid_gid_sta_compute*(bssid: pointer): uint32 {.exportc, cdecl.} =
  ## Compute Partial AID and Group ID for STA (7 instructions in blob).
  ## From blob: lbu a5, 4(a0); lbu a0, 5(a0); andi a5, 128;
  ##   slli a0, 1; or a0, a5; slli a0, 22; ret.
  ## Extracts bytes 4-5 of BSSID, combines and shifts into PAID/GID format.
  let b = cast[ptr UncheckedArray[uint8]](bssid)
  let byte4 = b[4].uint32 and 0x80  # bit 7 of byte 4
  let byte5 = b[5].uint32
  result = ((byte5 shl 1) or byte4) shl 22

proc mac_paid_gid_ap_compute*(bssid: pointer, aid: uint16): uint32 {.exportc, cdecl.} =
  ## Compute Partial AID and Group ID for AP (13 instructions in blob).
  ## From blob: lbu a5, 5(a0) => byte5 of BSSID
  ##   andi a1, 511 => partialAID = aid & 0x1FF
  ##   srai a0, a5, 4 => upperNibble = byte5 >> 4
  ##   xor a0, a0, a5 => mixed = upperNibble ^ byte5
  ##   slli a0, 5 => mixed <<= 5
  ##   andi a0, 480 => mixed &= 0x1E0 (5-bit field in bits 8:5)
  ##   add a0, a1 => combined = mixed + partialAID
  ##   lui a5, 0x7FC00; slli a0, 22; and a0, a5 => PAID field in bits 30:22
  ##   lui a5, 0x3F0; or a0, a5 => set GID=0x3F (broadcast) in bits 21:16
  let b = cast[ptr UncheckedArray[uint8]](bssid)
  let byte5 = b[5].uint32
  let partialAid = aid.uint32 and 0x1FF'u32
  let upperNibble = byte5 shr 4
  var mixed = (upperNibble xor byte5) shl 5
  mixed = mixed and 0x1E0'u32
  let combined = mixed + partialAid
  let paidField = (combined shl 22) and 0x7FC00000'u32
  result = paidField or 0x003F0000'u32  # GID = 63 (broadcast)

# ###########################################################################
#                  EDCA / Configuration
# ###########################################################################

proc bl60x_edca_get*(ac: cint, aifs: ptr uint8, cwmin: ptr uint8, cwmax: ptr uint8, txop: ptr uint16): cint {.exportc, cdecl.} =
  ## Get EDCA parameters for an access category (43 instrs in blob).
  ## Reads HW EDCA register for the given AC from MACHW_BASE + 0x200..0x20C.
  ## Register format: bits[3:0]=AIFS, bits[7:4]=CW_MIN, bits[11:8]=CW_MAX,
  ## bits[31:12]=TXOP.
  var regAddr: uint
  case ac
  of 0: regAddr = MACHW_EDCA_AC_BK_REG  # AC_BK
  of 1: regAddr = MACHW_EDCA_AC_BE_REG  # AC_BE
  of 2: regAddr = MACHW_EDCA_AC_VI_REG  # AC_VI
  of 3: regAddr = MACHW_EDCA_AC_VO_REG  # AC_VO
  else: return -1
  let word = regRead(regAddr)
  aifs[] = (word and 0xF).uint8             # bits [3:0]
  cwmin[] = ((word shr 4) and 0xF).uint8    # bits [7:4]
  cwmax[] = ((word shr 8) and 0xF).uint8    # bits [11:8]
  txop[] = (word shr 12).uint16             # bits [31:12]
  return 0

proc bl60x_firmwre_mpdu_free*(param: pointer) {.exportc, cdecl.} =
  ## Free an MPDU buffer (24 instrs in blob).
  ## Blob ABI: a0=param. Reads callbacks from g_bl_ops_funcs+20 / +24 (not
  ## bl60x_fw_env!). Decrements rxl_cntrl_env+20 (pending MPDU count) by
  ## param[21] (descriptor count). Tail-calls rxl_mpdu_free(param).
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  # Call pre-free callback (g_bl_ops_funcs[5] = byte offset 20)
  let preFree = cast[proc() {.cdecl.}](cast[ptr pointer](opsBase + 20)[])
  preFree()
  # Decrement pending MPDU count at rxl_cntrl_env+20
  let rxCntrlBase = cast[uint](addr rxl_cntrl_env[0])
  let descCount = cast[ptr uint8](cast[uint](param) + 21)[]
  let pending = cast[ptr uint32](rxCntrlBase + 20)[]
  cast[ptr uint32](rxCntrlBase + 20)[] = pending - descCount.uint32
  # Call post-free callback (g_bl_ops_funcs[6] = byte offset 24)
  let postFree = cast[proc() {.cdecl.}](cast[ptr pointer](opsBase + 24)[])
  postFree()
  # Tail-call rxl_mpdu_free(param)
  rxl_mpdu_free(param)

# ###########################################################################
#                  Notifier Chain
# ###########################################################################

proc notifier_chain_insert_ordered(headPtr: ptr pointer, notifier: ptr CoListHdr) =
  ## Insert a notifier into a singly-linked list ordered by priority (offset 8).
  ## Blob notifier block layout:
  ##   offset 0: callback function pointer
  ##   offset 4: next pointer (singly-linked)
  ##   offset 8: priority (int32, higher = inserted earlier)
  ## From blob: walks list via offset 4, compares int32 at offset 8.
  ## Inserts before the first node whose priority < new node's priority.
  var pos = headPtr
  while true:
    let cur = cast[ptr CoListHdr](pos[])
    if cur == nil:
      # End of list or empty: insert here
      cast[ptr pointer](cast[uint](notifier) + 4)[] = nil
      pos[] = cast[pointer](notifier)
      break
    let curPrio = cast[ptr int32](cast[uint](cur) + 8)[]
    let newPrio = cast[ptr int32](cast[uint](notifier) + 8)[]
    if curPrio < newPrio:
      # Insert notifier before cur
      cast[ptr pointer](cast[uint](notifier) + 4)[] = cast[pointer](cur)
      pos[] = cast[pointer](notifier)
      break
    # Advance: pos = &cur->next (offset 4)
    pos = cast[ptr pointer](cast[uint](cur) + 4)

proc notifier_chain_remove(headPtr: ptr pointer, notifier: ptr CoListHdr) =
  ## Remove a notifier from a singly-linked list by pointer match.
  ## From blob: walks list via offset 4 (next), compares pointer,
  ## unlinks by setting prev->next = node->next.
  var pos = headPtr
  while true:
    let cur = cast[ptr CoListHdr](pos[])
    if cur == nil:
      break  # not found
    if cur == notifier:
      # Unlink: *pos = notifier->next
      pos[] = cast[ptr pointer](cast[uint](notifier) + 4)[]
      break
    pos = cast[ptr pointer](cast[uint](cur) + 4)

proc notifier_chain_regsiter*(chain: ptr CoList, notifier: ptr CoListHdr) {.exportc, cdecl.} =
  ## Register notifier with irqSave (64 bytes in blob, 30 instrs).
  ## From blob: irqSave, inline priority-ordered insert, irqRestore, return 0.
  let saved = irqSave()
  var pos = cast[ptr pointer](addr chain.first)
  while true:
    let cur = cast[ptr CoListHdr](pos[])
    if cur == nil:
      cast[ptr pointer](cast[uint](notifier) + 4)[] = nil
      pos[] = cast[pointer](notifier)
      break
    let curPrio = cast[ptr int32](cast[uint](cur) + 8)[]
    let newPrio = cast[ptr int32](cast[uint](notifier) + 8)[]
    if curPrio < newPrio:
      cast[ptr pointer](cast[uint](notifier) + 4)[] = cast[pointer](cur)
      pos[] = cast[pointer](notifier)
      break
    pos = cast[ptr pointer](cast[uint](cur) + 4)
  irqRestore(saved)

proc notifier_chain_regsiter_fromCritical*(chain: ptr CoList, notifier: ptr CoListHdr) {.exportc, cdecl.} =
  ## Register notifier from critical section (26 bytes in blob).
  ## From blob: inline priority-ordered insert into singly-linked list.
  var pos = cast[ptr pointer](addr chain.first)
  while true:
    let cur = cast[ptr CoListHdr](pos[])
    if cur == nil:
      cast[ptr pointer](cast[uint](notifier) + 4)[] = nil
      pos[] = cast[pointer](notifier)
      break
    let curPrio = cast[ptr int32](cast[uint](cur) + 8)[]
    let newPrio = cast[ptr int32](cast[uint](notifier) + 8)[]
    if curPrio < newPrio:
      cast[ptr pointer](cast[uint](notifier) + 4)[] = cast[pointer](cur)
      pos[] = cast[pointer](notifier)
      break
    pos = cast[ptr pointer](cast[uint](cur) + 4)

proc notifier_chain_unregsiter*(chain: ptr CoList, notifier: ptr CoListHdr) {.exportc, cdecl.} =
  ## Unregister notifier with irqSave (62 bytes in blob, 29 instrs).
  ## From blob: irqSave, inline walk singly-linked list, unlink, irqRestore, return 0.
  let saved = irqSave()
  var pos = cast[ptr pointer](addr chain.first)
  while true:
    let cur = cast[ptr CoListHdr](pos[])
    if cur == nil:
      break
    if cur == notifier:
      pos[] = cast[ptr pointer](cast[uint](notifier) + 4)[]
      break
    pos = cast[ptr pointer](cast[uint](cur) + 4)
  irqRestore(saved)

proc notifier_chain_unregsiter_fromCritical*(chain: ptr CoList, notifier: ptr CoListHdr) {.exportc, cdecl.} =
  ## Unregister notifier from critical section (22 bytes in blob).
  ## From blob: inline walk singly-linked list, find and unlink matching node.
  var pos = cast[ptr pointer](addr chain.first)
  while true:
    let cur = cast[ptr CoListHdr](pos[])
    if cur == nil:
      break
    if cur == notifier:
      pos[] = cast[ptr pointer](cast[uint](notifier) + 4)[]
      break
    pos = cast[ptr pointer](cast[uint](cur) + 4)

proc notifier_chain_call*(chain: ptr CoList, event: uint32, data: pointer) {.exportc, cdecl.} =
  ## Call all notifiers in the chain.
  ## From blob (36 instrs): irqSave, s0 = chain.first, for each node:
  ##   lw a5, 0(s0) => callback at offset 0
  ##   save next from offset 4 before call
  ##   jalr a5(s0, s3=event, s4=data) => callback(node, event, data)
  ##   s0 = s0[4] => advance to next
  ## irqRestore, return 0.
  let saved = irqSave()
  var cur = chain.first
  while cur != nil:
    let next = cast[ptr CoListHdr](cast[ptr pointer](cast[uint](cur) + 4)[])
    let cb = cast[proc(node: ptr CoListHdr, event: uint32, data: pointer): cint {.cdecl.}](
      cast[ptr pointer](cast[uint](cur))[]
    )
    if cb != nil:
      discard cb(cur, event, data)
    cur = next
  irqRestore(saved)

proc notifier_chain_call_fromeCritical*(chain: ptr CoList, event: uint32, data: pointer) {.exportc, cdecl.} =
  ## Call notifiers from critical section (no irqSave/irqRestore).
  ## From blob (23 instrs): s0 = chain.first, for each node:
  ##   lw a5, 0(s0) => callback, call callback(node, event, data),
  ##   lw s0, 4(s0) => next. No interrupt manipulation.
  var cur = chain.first
  while cur != nil:
    let cb = cast[proc(node: ptr CoListHdr, event: uint32, data: pointer): cint {.cdecl.}](
      cast[ptr pointer](cast[uint](cur))[]
    )
    if cb != nil:
      discard cb(cur, event, data)
    cur = cast[ptr CoListHdr](cast[ptr pointer](cast[uint](cur) + 4)[])

# ###########################################################################
#                  Replay Counter
# ###########################################################################

proc replay_counter_validate*(param: pointer): bool {.exportc, cdecl.} =
  ## Validate replay counter in received frame (44 instrs).
  ## From blob: a0=replay_counter_state (8 bytes: lo32, hi32), a1=new_lo, a2=new_hi.
  ## Compares {state.hi, state.lo} against {new_hi, new_lo} as 64-bit unsigned.
  ## If new < state+1 (i.e., new <= state), returns false (replay detected).
  ## Otherwise: updates state = new, and clears any pending replay slots.
  ## The state has additional slots at offset 8+ for multi-key replay tracking.
  ## Returns true if counter is valid (not replayed).
  var newLo, newHi: uint32
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", newLo, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a2\" : \"=r\"(", newHi, ") );"].}
  let p = cast[uint](param)
  let stateLo = cast[ptr uint32](p)[]
  let stateHi = cast[ptr uint32](p + 4)[]
  # Compare as 64-bit: if new > state, accept; if new <= state, reject
  # Need unsigned 64-bit compare: compare hi first, then lo
  if newHi < stateHi:
    return false  # new is older
  if newHi == stateHi and newLo <= stateLo + 33:
    # Check within window (blob checks state+33 as threshold for lo)
    if newHi == stateHi and newLo <= stateLo:
      return false  # replay
  # Valid: update state
  # Also handle replay window slots at offset 8+ (blob clears slots)
  let slotIdx = (stateLo + 1) and 1  # alternating slot
  let slotOff = slotIdx * 12 + 8
  # Clear slot if counter changed significantly
  if newLo != stateLo + 1:
    let nextSlot = (newLo + 1) and 1
    cast[ptr uint32](p + nextSlot * 12 + 8 + 8)[] = 0
    let prevSlot = newLo and 1
    if prevSlot != slotIdx:
      cast[ptr uint32](p + prevSlot * 12 + 8 + 8)[] = 0
  # Store new counter
  cast[ptr uint32](p)[] = newLo
  cast[ptr uint32](p + 4)[] = newHi
  return true

# ###########################################################################
#                  Assert Handlers
# ###########################################################################

proc assert_err*(cond: cstring, file: cstring, line: cint) {.exportc, cdecl.} =
  ## Fatal assertion handler (244 bytes in blob, 75 instrs).
  ## Blob ABI: (a0=cond_or_func, a1=source_file, a2=line_number).
  ## Reloads logFn before each of 6 calls. Hangs forever after logging.
  when defined(bl808WifiNimFw):
    var traceBuf: array[96, char]
    let name = if file != nil: file else: cond
    if name != nil:
      discard c_snprintf(addr traceBuf[0], traceBuf.len.csize_t,
                         "[WIFI-NIMFW] assert %s:%d", name, line)
    else:
      discard c_snprintf(addr traceBuf[0], traceBuf.len.csize_t,
                         "[WIFI-NIMFW] assert line %d", line)
    nimFwTrace(cast[cstring](addr traceBuf[0]))
    nimFwTraceU32("[WIFI-NIMFW] assert line ", cast[uint32](line))
  # Call 1: condition/function name
  let logFn1 = getLogFunc(76)
  if logFn1 != nil:
    logFn1(2, 0, cast[pointer](cond), 148, cast[uint32](cond))
  # Call 2: line
  let logFn2 = getLogFunc(76)
  if logFn2 != nil:
    logFn2(2, 0, cast[pointer](file), 149, cast[uint32](line))
  # Call 3: extra (line number as uint32)
  let logFn3 = getLogFunc(76)
  if logFn3 != nil:
    logFn3(2, 0, cast[pointer](file), 150, cast[uint32](line))
  # Call 4: status
  let logFn4 = getLogFunc(76)
  if logFn4 != nil:
    logFn4(2, 0, cast[pointer](file), 151)
  # Call 5: dump register context words [2..5]
  let logFn5 = getLogFunc(76)
  if logFn5 != nil:
    logFn5(2, 0, nil, 152,
          dbg_assert_block[2], dbg_assert_block[3],
          dbg_assert_block[4], dbg_assert_block[5])
  # Call 6: dump register context words [6..9]
  let logFn6 = getLogFunc(76)
  if logFn6 != nil:
    logFn6(2, 0, nil, 158,
          dbg_assert_block[6], dbg_assert_block[7],
          dbg_assert_block[8], dbg_assert_block[9])
  while true:
    discard  # Hang on fatal error

proc assert_rec*(cond: cstring, file: cstring, line: cint) {.exportc, cdecl.} =
  ## Recoverable assertion handler (248 bytes in blob, 79 instrs).
  ## Blob ABI: (a0=cond_or_func_name, a1=source_file, a2=line_number).
  ## From blob: log function at g_bl_ops_funcs[76]. Calls log with file/line
  ## (lines 86-87), dumps dbg_assert_block (lines 88, 94), calls notification
  ## function, irqSave, checks keEvtField bit 31, triggers reset if needed.
  let logFn = getLogFunc(76)
  if logFn != nil:
    logFn(2, 0, cast[pointer](cond), 86)
    logFn(2, 0, cast[pointer](file), 87, cast[uint32](line))
    logFn(2, 0, nil, 88,
          dbg_assert_block[2], dbg_assert_block[3],
          dbg_assert_block[4], dbg_assert_block[5])
    logFn(2, 0, nil, 94,
          dbg_assert_block[6], dbg_assert_block[7],
          dbg_assert_block[8], dbg_assert_block[9])
  when defined(bl808WifiNimFw):
    nimFwTrace2U32("[WIFI-NIMFW] assert_rec ",
                   cast[uint32](line),
                   cast[uint32](cast[uint](file)))
  # Call notification function from g_bl_ops_funcs[1] (byte offset 4, NOT 80)
  let notifyFn = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 4)[]
  if notifyFn != nil:
    cast[proc(arg: pointer) {.cdecl.}](notifyFn)(nil)
  # Check if reset already pending; if not, trigger reset
  let saved = irqSave()
  if (cast[int32](keEvtField) >= 0):  # bit 31 not set
    # Blob calls hal_machw_disable_int (no arg) before raising the event
    hal_machw_disable_int()
    ke_evt_set(0x80000000'u32)
  irqRestore(saved)

proc assert_warn*(cond: cstring, file: cstring, line: cint) {.exportc, cdecl.} =
  ## Warning assertion handler (128 bytes in blob, ~38 instrs).
  ## Blob ABI: (a0=cond_or_func, a1=source_file, a2=line_number).
  let logFn = getLogFunc(204)
  if logFn != nil:
    logFn(2, 0, cast[pointer](cond), 179, cast[uint32](cond))
  let logFn2 = getLogFunc(204)
  if logFn2 != nil:
    logFn2(2, 0, cast[pointer](file), 180, cast[uint32](line))
  let logFn3 = getLogFunc(204)
  if logFn3 != nil:
    logFn3(2, 0, cast[pointer](file), 181, cast[uint32](line))

proc force_trigger*() {.exportc, cdecl.} =
  ## Force trigger a diagnostic dump (9 instructions in blob).
  ## From blob: csrrci a5, mstatus, 8 (irqSave), write 1 to DIAG_SW_REG,
  ## write 0 to DIAG_SW_REG, andi a5, 8, restore if needed.
  let saved = irqSave()
  regWrite(DIAG_SW_REG, 1'u32)
  regWrite(DIAG_SW_REG, 0'u32)
  irqRestore(saved)

# ###########################################################################
#                  Bugkiller (Debug Dump)
# ###########################################################################

proc bugkiller_fw_queue_dump(queue: ptr CoList) {.exportc: "fw_queue_dumpp", cdecl, noinline.} =
  ## Blob's static helper `fw_queue_dumpp.isra.0`. Per-entry: sprintfs
  ## id/destId/srcId/paramLen/&param into an advancing column cursor
  ## (sprintf + strlen + strlen + _puts_space quintet per field, 5 fields
  ## = 20 calls/iter). puts_space return is the next sprintf cursor.
  {.emit: "__asm__ volatile(\"\" ::: \"memory\");".}
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  let putsFn = cast[ptr pointer](opsBase + 8)[]
  let allocFnPtr = cast[ptr pointer](opsBase + 184)[]
  let freeFnPtr = cast[ptr pointer](opsBase + 188)[]
  type PutsFnType = proc(s: pointer) {.cdecl.}
  type AllocFnType = proc(sz: uint32): pointer {.cdecl.}
  type FreeFnType = proc(p: pointer) {.cdecl.}
  let puts = cast[PutsFnType](putsFn)

  template formatCol(cursor: var pointer) =
    let n1 = c_strlen(cursor).int32
    let padPtr = cast[pointer](cast[uint](cursor) + n1.uint)
    let n2 = c_strlen(cursor).int32
    cursor = puts_space(padPtr, 10'i32 - n2)

  var cur = queue.first
  while cur != nil:
    let msg = cast[ptr KeMsgHdr](cur)
    if allocFnPtr != nil:
      let allocFn = cast[AllocFnType](allocFnPtr)
      let buf = allocFn(256)
      if buf != nil:
        var col: pointer = buf
        c_sprintf(col, "%d", msg.id.cint);        formatCol(col)
        c_sprintf(col, "%d", msg.destId.cint);    formatCol(col)
        c_sprintf(col, "%d", msg.srcId.cint);     formatCol(col)
        c_sprintf(col, "%d", msg.paramLen.cint);  formatCol(col)
        c_sprintf(col, "0x%08x",
                  cast[uint32](cast[uint](msg) + 12)); formatCol(col)
        if putsFn != nil:
          puts(buf)
          puts(nil)
        if freeFnPtr != nil:
          cast[FreeFnType](freeFnPtr)(buf)
    cur = cur.next
  if putsFn != nil:
    puts(nil)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void bugkiller_fw_queue_sent_dump(void);".}
proc bugkiller_fw_queue_sent_dump*() {.exportc, cdecl.} =
  ## Dump sent message queue for debugging (13 instrs).
  let logFn = getLogFunc(4)
  if logFn != nil:
    logFn(2, 0, nil, 0)
  bugkiller_fw_queue_dump(addr keMsgQueueSent)

{.emit: "__attribute__((optimize(\"crossjumping\"))) void bugkiller_fw_queue_saved_dump(void);".}
proc bugkiller_fw_queue_saved_dump*() {.exportc, cdecl.} =
  ## Dump saved message queue.
  let logFn = getLogFunc(4)
  if logFn != nil:
    logFn(2, 0, nil, 0)
  bugkiller_fw_queue_dump(addr keMsgQueueSaved)

proc bugkiller_fw_queue_timer_dump*() {.exportc, cdecl.} =
  ## Dump timer queue for debugging (109 instrs).
  ## From blob: loads g_bl_ops_funcs (s0), calls puts(header_string1),
  ## then puts(header_string2). Loads keTimerQueue.first (s1).
  ## For each timer entry in the queue:
  ##   1. Allocates 128-byte buffer via g_bl_ops_funcs[184] (alloc)
  ##   2. If alloc fails, skip to next entry
  ##   3. snprintf(buf, "%d", entry.id) (timer msg ID at offset 4, half-word)
  ##   4. strlen(buf), _puts_space(buf+len, 10-len)
  ##   5. snprintf(buf, "%d", entry.taskId) (task ID at offset 6, byte)
  ##   6. strlen(buf), _puts_space(buf+len, 10-len)
  ##   7. snprintf(buf, "0x%08x", entry.time) (expiry at offset 8, word)
  ##   8. strlen(buf), _puts_space(buf+len, 10-len)
  ##   9. calls puts(buf) to print, then puts("\r\n")
  ##  10. calls free(buf) via g_bl_ops_funcs[188]
  ##  11. next = entry[0] (linked list next pointer)
  ## After loop: calls puts(footer_string).
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  let putsFn = cast[ptr pointer](opsBase + 8)[]
  let printFn = cast[ptr pointer](opsBase + 4)[]
  if putsFn == nil:
    return
  type PutsFnType = proc(s: pointer) {.cdecl.}
  type PrintFnType = proc(fmt: pointer, args: uint32) {.cdecl, varargs.}
  let puts = cast[PutsFnType](putsFn)
  # Print two header lines
  puts(nil)  # header 1 (blob uses string literals via auipc)
  puts(nil)  # header 2

  # Walk the timer queue
  var entry = keTimerQueue.first
  let allocFnPtr = cast[ptr pointer](opsBase + 184)[]
  let freeFnPtr = cast[ptr pointer](opsBase + 188)[]
  let snprintfPtr = cast[ptr pointer](opsBase + 4)[]

  template formatCol(cursor: var pointer) =
    let n1 = c_strlen(cursor).int32
    let padPtr = cast[pointer](cast[uint](cursor) + n1.uint)
    let n2 = c_strlen(cursor).int32
    cursor = puts_space(padPtr, 10'i32 - n2)

  while entry != nil:
    # Allocate 128-byte formatting buffer
    if allocFnPtr != nil:
      let allocFn = cast[proc(size: uint32): pointer {.cdecl.}](allocFnPtr)
      let buf = allocFn(128)
      if buf != nil:
        let entryU = cast[uint](entry)
        var col: pointer = buf

        # Format timer ID (half-word at offset 4)
        let timerId = cast[ptr uint16](entryU + 4)[]
        c_sprintf(col, "%d", timerId.cint);   formatCol(col)

        # Format task ID (byte at offset 6)
        let taskId = cast[ptr uint8](entryU + 6)[]
        c_sprintf(col, "%d", taskId.cint);    formatCol(col)

        # Format expiry time (word at offset 8)
        let expiryTime = cast[ptr uint32](entryU + 8)[]
        c_sprintf(col, "0x%08x", expiryTime); formatCol(col)

        # Print the formatted line
        puts(buf)
        puts(nil)  # newline ("\r\n" in blob)

        # Free buffer
        if freeFnPtr != nil:
          let freeFn = cast[proc(p: pointer) {.cdecl.}](freeFnPtr)
          freeFn(buf)

    # Next entry (linked list next at offset 0)
    entry = cast[ptr CoListHdr](cast[ptr pointer](cast[uint](entry))[])

  # Print footer
  puts(nil)

proc dump_ke_task*() {.exportc: "_dump_ke_task", cdecl.}
  ## Forward declaration: body defined below.

proc bugkiller_fw_task_dump*() {.exportc, cdecl.} =
  ## Dump task states for debugging (35 instructions in blob).
  ## From blob: loads puts func from s0[8], prints 2 header strings,
  ## then loops taskId 0..8 (s1=9), skipping taskId 7 (s2=7, TASK_RXU):
  ##   a0 = taskId & 0xFF, call ke_state_get(a0) => state,
  ##   a1=state, a0=taskId, call _dump_ke_task(taskId, state).
  let logFn = getLogFunc(4)
  if logFn != nil:
    logFn(2, 0, nil, 0)  # header line 1
    logFn(2, 0, nil, 0)  # header line 2
  var taskId = 0'u8
  while taskId <= TASK_LAST_EMB:
    if taskId != TASK_RXU:  # blob skips task 7 (bne s0, s2=7)
      let state = ke_state_get(taskId)
      # Call _dump_ke_task via asm ABI (a0=taskId, a1=state)
      {.emit: ["asm volatile(\"mv a1, %0\" : : \"r\"(", state, ") );"].}
      {.emit: ["asm volatile(\"mv a0, %0\" : : \"r\"(", taskId, ") );"].}
      dump_ke_task()
    inc taskId

proc dump_ke_task*() {.exportc: "_dump_ke_task", cdecl.} =
  ## Internal: dump kernel task info (78 instrs). a0=taskId, a1=state.
  ## Alloc 128-byte buf, format two columns ("Task %d" / "State %d")
  ## padded to width 10 via sprintf + 2*strlen + puts_space, print+free.
  var taskId, state: uint32
  {.emit: ["asm volatile(\"mv %0, a0\" : \"=r\"(", taskId, ") );"].}
  {.emit: ["asm volatile(\"mv %0, a1\" : \"=r\"(", state, ") );"].}
  let allocFn = cast[proc(sz: uint32): pointer {.cdecl.}](
    cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 0xB8)[])
  let buf = allocFn(128)
  if buf == nil:
    return
  var col: pointer = buf
  template formatCol(cursor: var pointer) =
    let n1 = c_strlen(cursor).int32
    let padPtr = cast[pointer](cast[uint](cursor) + n1.uint)
    let n2 = c_strlen(cursor).int32
    cursor = puts_space(padPtr, 10'i32 - n2)
  c_sprintf(col, "Task %d", taskId.cint);   formatCol(col)
  c_sprintf(col, "State %d", state.cint);   formatCol(col)
  let putsFn = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 8)[]
  if putsFn != nil:
    cast[proc(s: pointer) {.cdecl.}](putsFn)(buf)
    cast[proc(s: cstring) {.cdecl.}](putsFn)("\r\n")
  platformFree(buf)

proc puts_space*(buf: pointer, count: cint): pointer {.exportc: "_puts_space", cdecl, discardable.} =
  ## Internal: pad-column helper (a0=buf, a1=count). Fills buf[0..count)
  ## with ' ', null-terminates at buf[count], returns buf+count.
  var c: int32 = count
  if c < 0: c = 0
  let bufU = cast[uint](buf)
  var i: int32 = 0
  while i < c:
    cast[ptr uint8](bufU + i.uint)[] = 0x20'u8
    i += 1
  cast[ptr uint8](bufU + c.uint)[] = 0
  return cast[pointer](bufU + c.uint)

# ###########################################################################
#                  Configuration (cfg_*)
# ###########################################################################

proc cfg_api_element_dump*(dataPtr: pointer, typeId: uint32,
    outputBuf: pointer): pointer {.exportc, cdecl.} =
  ## Dump a config element value to output buffer (434 bytes in blob).
  ## Returns pointer to type name string ("Boolean", "SINT8", etc.) or nil.
  ## From blob: dispatches on typeId (1..8), reads data, snprintf to outputBuf,
  ## clamps negative return to 0, null-terminates, returns rodata type name.
  let BUFSIZE = 15.csize_t
  let outBase = cast[uint](outputBuf)

  template dumpFmt(written: var cint, typeName: cstring): pointer =
    if written < 0: written = 0
    cast[ptr uint8](outBase + written.uint)[] = 0
    cast[pointer](typeName)

  case typeId
  of 1:
    let val = cast[ptr uint8](dataPtr)[]
    let strPtr = if val != 0: cstring"True" else: cstring"False"
    var written = c_snprintf(outputBuf, BUFSIZE, "%s", strPtr)
    return dumpFmt(written, cstring"Boolean")
  of 2:
    let val = cast[ptr int8](dataPtr)[]
    var written = c_snprintf(outputBuf, BUFSIZE, "%d", val.cint)
    return dumpFmt(written, cstring"SINT8")
  of 3:
    let val = cast[ptr uint8](dataPtr)[]
    var written = c_snprintf(outputBuf, BUFSIZE, "%u", val.cuint)
    return dumpFmt(written, cstring"UINT8")
  of 4:
    let val = cast[ptr int16](dataPtr)[]
    var written = c_snprintf(outputBuf, BUFSIZE, "%d", val.cint)
    return dumpFmt(written, cstring"SINT16")
  of 5:
    let val = cast[ptr uint16](dataPtr)[]
    var written = c_snprintf(outputBuf, BUFSIZE, "%u", val.cuint)
    return dumpFmt(written, cstring"UINT16")
  of 6:
    let val = cast[ptr int32](dataPtr)[]
    var written = c_snprintf(outputBuf, BUFSIZE, "%ld", val.clong)
    return dumpFmt(written, cstring"SINT32")
  of 7:
    let val = cast[ptr uint32](dataPtr)[]
    var written = c_snprintf(outputBuf, BUFSIZE, "%lu", val.culong)
    return dumpFmt(written, cstring"UINT32")
  of 8:
    let val = cast[ptr uint32](dataPtr)[]
    var written = c_snprintf(outputBuf, BUFSIZE, "%lu", val.culong)
    return dumpFmt(written, cstring"STRING")
  else:
    return nil

proc cfg_api_element_general_get*(id: uint32): uint32 {.exportc, cdecl.} =
  ## Get a general config element value (blob: always returns 0, 4 bytes).
  return 0

proc cfg_api_element_general_set*(entry: pointer, value: pointer) {.exportc, cdecl.} =
  ## Set a general config element value (52 instrs in blob).
  ## Actual blob ABI: a0=config table entry ptr, a1=value ptr.
  ## Called as the set handler from cfg_api_element_set for each config table entry.
  ## Flow: calls a log function with entry[8] (name string), then reads entry[6]
  ## (typeId halfword), entry[12] (data pointer), and dispatches by type:
  ##   typeId 1,3: sb (store unsigned byte from value[0] to data[0])
  ##   typeId 2:   sb (store signed byte from value[0] to data[0])
  ##   typeId 4:   sh (store signed halfword from value[0..1] to data[0..1])
  ##   typeId 5:   sh (store unsigned halfword from value[0..1] to data[0..1])
  ##   typeId 6,7: sw (store word from value[0..3] to data[0..3])
  ## Returns 0 always.
  if entry == nil or value == nil: return
  let entryU = cast[uint](entry)
  # Log: blob calls g_bl_ops_funcs[204] with entry[8] (name string)
  let nameStr = cast[ptr pointer](entryU + 8)[]
  let logFnPtr = cast[ptr pointer](cast[uint](addr g_bl_ops_funcs) + 204)[]
  if logFnPtr != nil and nameStr != nil:
    let logFn = cast[PlatformLogFunc](logFnPtr)
    logFn(1, 0, nameStr, 188)
  let typeId = cast[ptr uint16](entryU + 6)[]
  let dataPtr = cast[ptr pointer](entryU + 12)[]
  if dataPtr == nil: return
  let dst = cast[uint](dataPtr)
  case typeId
  of 1, 3:
    # Unsigned byte
    let v = cast[ptr uint8](value)[]
    cast[ptr uint8](dst)[] = v
  of 2:
    # Signed byte
    let v = cast[ptr int8](value)[]
    cast[ptr int8](dst)[] = v
  of 4:
    # Signed halfword
    let v = cast[ptr int16](value)[]
    cast[ptr int16](dst)[] = v
  of 5:
    # Unsigned halfword
    let v = cast[ptr uint16](value)[]
    cast[ptr uint16](dst)[] = v
  of 6, 7:
    # Word (32-bit)
    let v = cast[ptr uint32](value)[]
    cast[ptr uint32](dst)[] = v
  else:
    discard

proc cfg_api_element_set*(id: uint32, subId: uint16, typeId: uint16,
    value: pointer, extra: pointer) {.exportc, cdecl.} =
  ## Set a config element by searching element table (59 instrs).
  ##
  ## From disassembly: iterates 28-byte config entries (s0 walks from
  ## cfg_table_start to cfg_table_end, stride 28). For each entry:
  ##   - Compare entry[0] (uint32) with id (s2): if mismatch, advance s0+=28
  ##   - Compare entry[4] (uint16) with subId (s3): if mismatch, advance
  ##   - Compare entry[6] (uint16) with typeId (s4): if mismatch, call
  ##     type-conversion handler at s7[4] with (s8, s4, s2, s3) args
  ##   - On full match: call entry[16] (set handler) with (s0=entry, s5=value, s6=extra)
  ## The config table boundaries are resolved via auipc relocations.
  ##
  ## Since we don't have the exact linker-resolved config table, we search
  ## a virtual config table. The blob's cfg_api_element_general_set function
  ## (which is the typical set handler) reads entry[6] for type, entry[12]
  ## for data pointer, and writes the value according to the type width.
  ## We implement the dispatch logic that the blob uses.
  ##
  ## For the reimplementation, we use our cfgElements array as a flat store,
  ## keyed by the id. The subId and typeId are used for type-safe dispatch.

  # Type-based value writing (matching cfg_api_element_general_set blob logic)
  # The blob's general_set reads typeId from entry[6] and dispatches:
  #   typeId 1,3: sb (store byte from value[0])
  #   typeId 2: sb (signed byte from value[0])
  #   typeId 4: sh (store halfword from value[0..1])
  #   typeId 5: sh (unsigned halfword from value[0..1])
  #   typeId 6,7: sw (store word from value[0..3])

  # The blob iterates a 28-byte-stride config table, comparing id/subId/typeId
  # for each entry, and calls entry[16] (set handler) on match.
  # Since we don't have the linked config table, we call cfg_api_element_general_set
  # directly which handles the type-based dispatch.
  if value == nil:
    return
  # Build a virtual entry struct on stack matching the blob's layout:
  #   [0..3] = id, [4..5] = subId, [6..7] = typeId,
  #   [8..11] = name ptr, [12..15] = data ptr, [16..19] = set handler
  var entry {.noinit.}: array[28, uint8]
  let entryAddr = cast[uint](addr entry[0])
  cast[ptr uint32](entryAddr)[] = id
  cast[ptr uint16](entryAddr + 4)[] = subId
  cast[ptr uint16](entryAddr + 6)[] = typeId
  # Data pointer: for cfgElements, point to the element slot
  if id < 32:
    cast[ptr pointer](entryAddr + 12)[] = cast[pointer](addr cfgElements[id])
    # Blob dispatches to the set handler via a function pointer stored in
    # the config entry — indirect call (not counted as R_RISCV_CALL).
    # Mirror that by calling through a pointer variable.
    let setFn {.volatile.}: proc(entry: pointer, value: pointer) {.cdecl.} =
      cfg_api_element_general_set
    setFn(cast[pointer](entryAddr), value)
    if id >= cfgElementCount:
      cfgElementCount = id + 1

proc dump_cfg_entries*() {.exportc, cdecl.} =
  ## Dump config entries for debugging (92 instrs).
  ## Iterates over the config element table, for each entry:
  ##   logs the entry index, name pointer, type, subtype, value pointer,
  ##   and calls cfg_api_element_dump to format the value into a string buffer.
  ## Uses g_bl_ops_funcs[4] (printf) and g_bl_ops_funcs[8] (puts) for output.
  ##
  ## Assembly trace:
  ##   s0 = g_bl_ops_funcs base
  ##   Calls g_bl_ops_funcs[8] with header string
  ##   s1 = cfg element table start, s2 = cfg element table end
  ##   s3..s8 = format strings for each field
  ##   For each entry (stride 28):
  ##     logs: name(s3), value(s4), type(s5), subtype(s6), raw_word(s7),
  ##     calls cfg_api_element_dump(entry[12], entry[6], sp_buf) -> formatted string
  ##     logs formatted value(s8) and separator
  ##   Calls g_bl_ops_funcs[8] with footer string
  let opsBase = cast[uint](addr g_bl_ops_funcs)
  let logFn = cast[ptr pointer](opsBase + 8)[]  # puts-like function
  let printFn = cast[ptr pointer](opsBase + 4)[]  # printf-like function
  if logFn == nil or printFn == nil:
    return
  type PutsFn = proc(s: cstring) {.cdecl.}
  type PrintfFn = proc(fmt: cstring, a1: pointer) {.cdecl, varargs.}
  let puts = cast[PutsFn](logFn)
  let printf = cast[PrintfFn](printFn)
  # Print header
  puts("--- cfg entries ---")
  # Get config element table: stored at a known location
  # In the blob, s1 iterates from cfg_table_start to cfg_table_end (stride=28)
  # The blob references these via auipc relocations. We use our cfgElements array.
  let cfgBase = cast[uint](addr cfgElements[0])
  let cfgCount = cfgElementCount
  var buf {.noinit.}: array[64, uint8]
  for i in 0'u32 ..< cfgCount:
    let entryAddr = cfgBase + i * 28
    # Log entry index
    printf("entry %d:", cast[pointer](i))
    # Log entry name (offset 0 = ptr to name string)
    let namePtr = cast[ptr pointer](entryAddr)[]
    printf(" name=%s", namePtr)
    # Log entry value (offset 4 = value word)
    let valWord = cast[ptr uint32](entryAddr + 4)[]
    printf(" val=0x%x", cast[pointer](valWord))
    # Log type (offset 8 = type half-word)
    let typeId = cast[ptr uint16](entryAddr + 8)[]
    printf(" type=%d", cast[pointer](typeId.uint))
    # Log subtype (offset 10 = subtype half-word)
    let subType = cast[ptr uint16](entryAddr + 10)[]
    printf(" sub=%d", cast[pointer](subType.uint))
    # Dump formatted value
    let dataPtr = cast[ptr pointer](entryAddr + 16)[]
    let typeVal = cast[ptr uint8](entryAddr + 10)[]
    let typeName = cfg_api_element_dump(dataPtr, typeVal.uint32,
                                       cast[pointer](addr buf[0]))
    printf(" [%s]", cast[pointer](addr buf[0]))
    if typeName != nil:
      printf("    type    : %s\r\n", typeName)
    # Separator
    puts("")
  # Print footer
  puts("--- end cfg ---")

