# --- KE task dispatch table types ---
# ke_msg_handler_t: {msg_id: uint32, handler: pointer} = 8 bytes per entry
# ke_task_handler_t: {msg_handlers: pointer, count: uint32} = 8 bytes per entry

type
  KeMsgHandler* = object
    msgId*: uint32
    handler*: pointer
  KeTaskHandler* = object
    msgHandlers*: pointer
    count*: uint32

